:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) body {
  background:var(--bg); color:var(--ink); font-family:var(--sans);
}
:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"])
main:has(> :is(.shelf-index-page,.tradeoff-sheet-page,.progress-bulletin-page,.margin-reading-room-page,.light-table-page,.counterpoint-page)) {
  overflow:hidden;
}
:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) .ec-site-header {
  position:sticky; top:0; z-index:20; height:73px; border:0; border-bottom:1px solid var(--line);
  background:var(--bg); backdrop-filter:none;
}
:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) .ec-header-grid { height:72px; }
:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) .ec-main-nav { height:72px; }
:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) .ec-header-brand > small { display:none; }
:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) .ec-header-brand .brand.has-logo {
  display:flex; align-items:center; gap:12px;
}
:is(
  [data-theme^="shelf-index"],
  [data-theme^="tradeoff-sheet"],
  [data-theme^="progress-bulletin"],
  [data-theme^="margin-reading-room"],
  [data-theme^="light-table"],
  [data-theme^="counterpoint"],
  [data-theme^="seamless-canvas"],
  [data-theme^="night-corridor"],
  [data-theme^="open-ascent"]
) .ec-header-brand .brand-logo {
  width:auto; max-width:min(180px,38vw); height:30px; max-height:30px; object-fit:contain; transform-origin:left center;
}
:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) .ec-header-brand .brand-name {
  color:var(--ink); font-family:var(--serif); font-size:1.15rem; font-weight:700;
}
:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) .ec-footer {
  min-height:104px; margin-top:clamp(52px,7vw,92px); padding-top:26px; padding-bottom:34px;
}
:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) main:not(:has(> :is(.shelf-index-page,.tradeoff-sheet-page,.progress-bulletin-page,.margin-reading-room-page,.light-table-page,.counterpoint-page))) {
  padding-bottom:clamp(72px,8vw,112px);
}
:is(.shelf-index-page,.tradeoff-sheet-page,.progress-bulletin-page,.margin-reading-room-page,.light-table-page,.counterpoint-page) {
  width:100%; max-width:1280px; margin-inline:auto; padding:0 30px;
}
:is(.si-hero-media,.ts-hero-media,.pb-hero-media,.mr-hero-media,.lt-hero-visual,.cp-hero-media) img,
:is(.si-hero-embed,.ts-hero-embed,.pb-hero-embed,.mr-hero-embed,.lt-hero-embed,.cp-hero-embed),
:is(.si-hero-embed,.ts-hero-embed,.pb-hero-embed,.mr-hero-embed,.lt-hero-embed,.cp-hero-embed) svg {
  display:block; width:100%; height:100%; object-fit:cover;
}
.content-skeleton-hero-anim {
  display:grid; width:100%; height:100%; min-height:inherit; place-items:center; overflow:hidden;
}
.content-skeleton-hero-anim .hero-svg {
  width:min(88%,620px); height:auto; max-height:90%; margin:0;
}

/* Shelf Index */
.si-hero { display:grid; grid-template-columns:minmax(0,5fr) minmax(0,7fr); min-height:440px; border-bottom:1px solid var(--line); }
.si-hero-copy { display:flex; flex-direction:column; justify-content:center; padding:52px 54px 52px 20px; border-right:1px solid var(--line); }
.si-eyebrow,.ts-eyebrow,.pb-eyebrow,.mr-eyebrow,.lt-eyebrow,.cp-eyebrow { margin:0 0 22px; color:var(--accent); font-size:.72rem; font-weight:700; letter-spacing:.08em; }
.si-hero h1 { max-width:12ch; margin:0; font:600 clamp(2.9rem,4vw,4.3rem)/1.12 var(--serif); letter-spacing:-.045em; }
.si-hero-description { max-width:54ch; margin:26px 0; color:var(--ink-soft); font-size:.88rem; line-height:1.9; }
.si-hero-action,.si-read { color:var(--accent); font-size:.74rem; font-weight:700; }
.si-hero-media { min-height:440px; overflow:hidden; background:transparent; }
.si-media-empty,.ts-media-empty { width:100%; height:100%; min-height:inherit; background:var(--accent-wash); }
.si-feature { display:grid; grid-template-columns:180px minmax(0,1fr) 150px 230px; min-height:180px; border-bottom:1px solid var(--line); align-items:stretch; }
.si-feature-label,.si-feature-copy,.si-feature-meta { display:flex; flex-direction:column; justify-content:center; padding:28px; border-right:1px solid var(--line); }
.si-feature-label { color:var(--accent); font-size:.72rem; font-weight:700; }
.si-feature-copy h2 { margin:0 0 14px; font:600 clamp(1.55rem,2.2vw,2.35rem)/1.18 var(--serif); }
.si-feature-copy h2 a,.si-shelf a,.si-latest a { color:var(--ink); }
.si-feature-copy p { margin:0 0 14px; color:var(--ink-soft); font-size:.76rem; line-height:1.7; }
.si-feature-meta { gap:14px; color:var(--muted); font-size:.67rem; }
.si-feature-cover { overflow:hidden; }.si-feature-cover img { width:100%; height:100%; object-fit:cover; }
.si-shelf { display:grid; grid-template-columns:200px minmax(0,1fr) minmax(280px,.8fr); min-height:150px; border-bottom:1px solid var(--line); }
.si-shelf > div { padding:28px; border-right:1px solid var(--line); }.si-shelf > div:last-child { border-right:0; }
.si-shelf-topic a { color:var(--accent); font:600 1.35rem var(--serif); }
.si-shelf-topic p,.si-shelf-primary p { color:var(--muted); font-size:.72rem; line-height:1.65; }
.si-shelf-topic span { color:var(--muted); font-size:.66rem; }
.si-shelf-primary h2 { margin:0 0 10px; font:600 1.45rem/1.28 var(--serif); }
.si-shelf-primary > a { color:var(--accent); font-size:.7rem; }
.si-shelf-secondary { display:grid; grid-template-columns:1fr auto; align-content:center; gap:20px; font-size:.74rem; }
.si-shelf-secondary time { color:var(--muted); font-size:.64rem; }
.si-latest { padding-top:28px; }.si-latest header,.ts-lenses header,.ts-worksheet header,.pb-categories header,.pb-ledger header,.mr-bibliography header,.lt-latest > header {
  display:flex; justify-content:space-between; align-items:baseline; border-bottom:1px solid var(--ink);
}
.si-latest header h2,.ts-lenses header h2,.ts-worksheet header h2,.pb-categories header h2,.pb-ledger header h2,.mr-bibliography header h2,.lt-latest > header h2 { margin:0 0 12px; font-size:1.12rem; }
.si-latest header > a,.ts-lenses header > a,.ts-worksheet header > a,.pb-categories header > a,.pb-ledger header > a,.mr-bibliography header > a,.lt-latest > header > a { color:var(--accent); font-size:.68rem; }
.si-latest-head,.si-latest-row { display:grid; grid-template-columns:minmax(0,1fr) 180px 120px; gap:18px; align-items:center; }
.si-latest-head { padding:9px 0; color:var(--muted); font-size:.61rem; }.si-latest-row { min-height:34px; border-bottom:1px solid var(--line); font-size:.68rem; }
.si-latest-row span,.si-latest-row time { color:var(--muted); }

/* Tradeoff Sheet */
.ts-hero { display:grid; grid-template-columns:minmax(0,5fr) minmax(0,7fr); min-height:430px; border-bottom:1px solid var(--line); }
.ts-hero-copy { display:flex; flex-direction:column; justify-content:center; padding:54px 54px 48px 20px; border-right:1px solid var(--line); }
.ts-hero h1 { max-width:10ch; margin:0; font:600 clamp(3rem,4.6vw,4.7rem)/1.12 var(--serif); letter-spacing:-.05em; }
.ts-hero-description { max-width:42ch; margin:26px 0; color:var(--ink-soft); line-height:1.85; }
.ts-hero-action,.ts-focus-action { color:var(--accent); font-size:.75rem; font-weight:700; }
.ts-hero-media { min-height:430px; overflow:hidden; padding:24px 0 24px 24px; background:transparent; }
.ts-hero-media > :is(img,.ts-hero-embed,.ts-media-empty,.content-skeleton-hero-anim) { width:100%; height:100%; object-fit:cover; }
.ts-focus { display:grid; grid-template-columns:130px minmax(0,1fr) 200px 100px; gap:24px; align-items:center; min-height:180px; border-bottom:1px solid var(--line); }
.ts-focus-label { color:var(--accent); font-size:.72rem; font-weight:700; }.ts-focus-copy h2 { margin:0 0 14px; font:600 clamp(1.7rem,2.3vw,2.45rem)/1.2 var(--serif); }
.ts-focus-copy h2 a { color:var(--ink); }.ts-focus-copy p { margin:0; color:var(--ink-soft); font-size:.76rem; line-height:1.7; }
.ts-focus-meta { display:flex; gap:16px; color:var(--muted); font-size:.66rem; }.ts-focus-action { text-align:right; }
.ts-lenses,.ts-worksheet { padding-top:28px; }
.ts-lenses nav { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); border-bottom:1px solid var(--line); }
.ts-lens { display:flex; flex-direction:column; min-height:140px; padding:28px 22px; border-right:1px solid var(--line); color:var(--ink); text-align:center; }
.ts-lens:last-child { border-right:0; }.ts-lens b { font:600 1.12rem var(--serif); }.ts-lens span { margin-top:12px; color:var(--muted); font-size:.68rem; line-height:1.55; }
.ts-lens strong { margin-top:auto; color:var(--accent); font-size:.75rem; }
.ts-row-head,.ts-row { display:grid; grid-template-columns:68px minmax(0,1fr) 150px 120px 30px; gap:18px; align-items:center; }
.ts-row-head { padding:9px 0; border-bottom:1px solid var(--line); color:var(--muted); font-size:.6rem; }
.ts-row { min-height:72px; border-bottom:1px solid var(--line); }.ts-row-index { font:400 1.7rem var(--serif); }
.ts-row h3 { margin:0 0 5px; font:600 1rem var(--serif); }.ts-row h3 a { color:var(--ink); }.ts-row p { margin:0; color:var(--muted); font-size:.67rem; }
.ts-row-category,.ts-row time { color:var(--muted); font-size:.66rem; }.ts-row-action { color:var(--ink); font-size:1.3rem; text-align:right; }

/* Progress Bulletin */
.pb-hero { display:grid; grid-template-columns:minmax(0,7fr) minmax(0,5fr); gap:46px; min-height:390px; padding:40px 0 38px; border-bottom:1px solid var(--line); }
.pb-hero.is-solo { grid-template-columns:minmax(0,760px); }.pb-hero-copy { align-self:center; padding-left:4px; }
.pb-hero h1 { max-width:12ch; margin:0; font:700 clamp(3rem,4.8vw,4.8rem)/1.14 var(--sans); letter-spacing:-.055em; }
.pb-hero-description { max-width:56ch; margin:24px 0; color:var(--ink-soft); font-size:.84rem; line-height:1.85; }
.pb-hero-cta { display:inline-block; padding:12px 18px; background:var(--accent); color:var(--on-accent,#fff); font-size:.72rem; font-weight:700; }
.pb-hero-media { min-height:300px; overflow:hidden; align-self:center; background:transparent; }
.pb-feature { display:grid; grid-template-columns:220px minmax(0,1fr) 330px; min-height:210px; border:1px solid var(--line); margin-top:28px; }
.pb-feature:not(:has(.pb-feature-cover)) { grid-template-columns:220px minmax(0,1fr); }
.pb-feature > * { padding:28px; border-right:1px solid var(--line); }.pb-feature > *:last-child { border-right:0; }
.pb-feature-meta { display:flex; flex-direction:column; gap:24px; color:var(--muted); font-size:.7rem; }.pb-feature-meta strong { color:var(--accent); }
.pb-feature-copy small,.pb-feature-copy > a { color:var(--accent); font-size:.68rem; font-weight:700; }
.pb-feature-copy h2 { margin:16px 0; font-size:clamp(1.7rem,2.5vw,2.7rem); line-height:1.2; }.pb-feature-copy h2 a { color:var(--ink); }
.pb-feature-copy p { color:var(--ink-soft); font-size:.72rem; line-height:1.7; }.pb-feature-cover { padding:0; overflow:hidden; }.pb-feature-cover img { width:100%; height:100%; object-fit:cover; }
.pb-categories,.pb-ledger { padding-top:30px; }.pb-categories nav { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); }
.pb-categories nav a { display:flex; flex-direction:column; min-height:126px; padding:18px; border-right:1px solid var(--line); color:var(--ink); }
.pb-categories nav a:first-child { padding-left:0; }.pb-categories nav a:last-child { border-right:0; }.pb-categories strong { color:var(--muted); font:1.35rem var(--mono); }
.pb-categories b { margin-top:12px; font-size:.78rem; }.pb-categories span,.pb-categories small { margin-top:6px; color:var(--muted); font-size:.62rem; line-height:1.45; }
.pb-ledger-row { display:grid; grid-template-columns:150px minmax(0,1fr) 130px 24px; gap:28px; align-items:center; min-height:62px; border-bottom:1px solid var(--line); color:var(--ink); }
.pb-ledger-row time,.pb-ledger-category { color:var(--muted); font: .66rem var(--mono); }.pb-ledger-copy b { display:block; font-size:.8rem; }
.pb-ledger-copy small { display:block; margin-top:5px; color:var(--muted); font-size:.64rem; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }

/* Margin Reading Room */
.margin-reading-room-page { padding-top:18px; }
.mr-intro { display:grid; grid-template-columns:4fr 5fr 3fr; min-height:340px; border:1px solid var(--line); }
.mr-intro.no-feature { grid-template-columns:7fr 5fr; }.mr-intro.no-media { grid-template-columns:4fr 8fr; }.mr-intro.no-feature.no-media { grid-template-columns:minmax(0,720px); }
.mr-intro > * { padding:32px; border-right:1px solid var(--line); }.mr-intro > *:last-child { border-right:0; }
.mr-hero-copy { display:flex; flex-direction:column; justify-content:center; }.mr-hero-copy h1 { margin:0; font:600 clamp(2.2rem,3.3vw,3.5rem)/1.14 var(--serif); }
.mr-hero-description,.mr-intro-feature p { color:var(--ink-soft); font-size:.75rem; line-height:1.75; }.mr-hero-copy > a,.mr-intro-feature > a { margin-top:18px; color:var(--accent); font-size:.7rem; }
.mr-intro-feature { display:flex; flex-direction:column; justify-content:center; }.mr-intro-feature small { color:#a96e2f; font-size:.68rem; font-weight:700; }
.mr-intro-feature h2 { margin:22px 0 12px; font:600 clamp(1.5rem,2.2vw,2.3rem)/1.25 var(--serif); }.mr-intro-feature h2 a { color:var(--ink); }
.mr-hero-media { padding:0; overflow:hidden; background:transparent; }.mr-reading-grid { display:grid; grid-template-columns:2fr 7fr 3fr; border:1px solid var(--line); border-top:0; }
.mr-reading-grid > * { padding:28px; border-right:1px solid var(--line); }.mr-reading-grid > *:last-child { border-right:0; }
.mr-lenses h2,.mr-companions header h2 { margin:0 0 16px; font:600 1rem var(--serif); }.mr-lenses nav a { display:grid; grid-template-columns:32px 1fr; gap:8px; padding:8px 0; border-bottom:1px solid var(--line); color:var(--ink); }
.mr-lenses strong { color:var(--accent); font:1.35rem var(--serif); }.mr-lenses b { font-size:.7rem; }.mr-lenses small { display:block; margin-top:3px; color:var(--muted); font-size:.56rem; }
.mr-lenses-all { display:inline-block; margin-top:12px; color:var(--accent); font-size:.65rem; }.mr-main-reading small { color:var(--accent); font-size:.68rem; font-weight:700; }
.mr-main-reading h2 { margin:20px 0; font:600 clamp(2rem,3vw,3.2rem)/1.18 var(--serif); }.mr-main-reading h2 a { color:var(--ink); }
.mr-main-reading p { color:var(--ink-soft); font:1rem/1.95 var(--serif); }.mr-main-reading > a { color:var(--accent); font-size:.7rem; }
.mr-companions header { display:flex; justify-content:space-between; border-bottom:1px solid var(--line); }.mr-companions header a { color:var(--accent); font-size:.62rem; }
.mr-companions > a { display:grid; grid-template-columns:minmax(0,1fr) 60px; gap:12px; padding:10px 0; border-bottom:1px solid var(--line); color:var(--ink); }
.mr-companions b { display:block; font: .8rem/1.35 var(--serif); }.mr-companions small { color:var(--muted); font-size:.57rem; }.mr-companions img { width:60px; height:42px; object-fit:cover; }
.mr-bibliography { padding:22px 8px 0; }.mr-bibliography-head,.mr-bibliography-row { display:grid; grid-template-columns:36px minmax(0,1fr) 180px 110px; gap:12px; align-items:center; }
.mr-bibliography-head { padding:8px 0; border-bottom:1px solid var(--ink); color:var(--muted); font-size:.58rem; }
.mr-bibliography-row { min-height:34px; border-bottom:1px solid var(--line); color:var(--ink); font-size:.65rem; }.mr-bibliography-row strong { color:var(--accent); }
.mr-bibliography-row small { margin-left:16px; color:var(--muted); }.mr-bibliography-row em,.mr-bibliography-row time { color:var(--muted); font-style:normal; }

/* Light Table */
.lt-hero { display:grid; grid-template-columns:5fr 7fr; gap:56px; min-height:420px; padding:34px 0 28px; border-bottom:1px solid var(--line); }
.lt-hero-copy { display:flex; flex-direction:column; justify-content:center; padding-left:24px; }.lt-hero h1 { max-width:11ch; margin:0; font:800 clamp(3rem,5vw,5.2rem)/1 var(--sans); letter-spacing:-.055em; }
.lt-hero-description { max-width:44ch; margin:24px 0; color:var(--ink-soft); font-size:.84rem; line-height:1.85; }.lt-hero-action { color:var(--accent); font-size:.74rem; font-weight:700; }
.lt-hero-visual { position:relative; min-height:340px; overflow:hidden; background:transparent; }.lt-hero-visual > :is(img,a,.lt-hero-embed,.lt-media-fallback,.content-skeleton-hero-anim) { width:100%; height:100%; }
.lt-hero-visual img { width:100%; height:100%; object-fit:cover; }.lt-media-fallback,.cp-media-fallback { display:grid!important; place-content:center; gap:12px; padding:28px; background:var(--accent-wash); color:var(--ink); text-align:center; }
.lt-media-fallback span,.cp-media-fallback span { color:var(--accent); font:5rem var(--serif); }.lt-hero-caption { position:absolute; right:0; bottom:0; left:0; display:flex; justify-content:space-between; padding:10px 0 0; background:var(--bg); color:var(--muted); font-size:.62rem; }
.lt-category-strip { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); padding:22px 0; border-bottom:1px solid var(--line); }
.lt-category-strip a { display:flex; flex-direction:column; align-items:center; border-right:1px solid var(--line); color:var(--ink); }.lt-category-strip a:last-child { border-right:0; }
.lt-category-strip strong { font-size:.72rem; }.lt-category-strip small { margin-top:5px; color:var(--muted); font-size:.59rem; }
.lt-feature { display:grid; grid-template-columns:8fr 4fr; min-height:300px; padding:28px 0; border-bottom:1px solid var(--line); }.lt-feature-media { overflow:hidden; background:var(--accent-wash); }
.lt-feature-media img { width:100%; height:100%; object-fit:cover; }.lt-feature-media.lt-media-empty { display:grid; place-items:center; color:var(--accent); font:7rem var(--serif); }
.lt-feature-copy { display:flex; flex-direction:column; justify-content:center; padding:34px 44px; }.lt-feature-copy > small { color:var(--accent); font-size:.68rem; font-weight:700; }
.lt-feature-copy h2 { margin:20px 0; font-size:clamp(1.8rem,2.7vw,2.9rem); line-height:1.18; }.lt-feature-copy h2 a { color:var(--ink); }
.lt-feature-copy p { color:var(--ink-soft); font-size:.74rem; line-height:1.75; }.lt-feature-copy footer { display:flex; justify-content:space-between; margin-top:24px; color:var(--muted); font-size:.65rem; }
.lt-feature-copy footer a { color:var(--accent); }.lt-latest { padding-top:24px; }.lt-contact-sheet { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); }
.lt-sheet-item { min-width:0; padding:18px; border-right:1px solid var(--line); border-bottom:1px solid var(--line); }.lt-sheet-item:nth-child(4n) { border-right:0; }
.lt-sheet-media { display:block; height:140px; overflow:hidden; background:var(--accent-wash); }.lt-sheet-media img { width:100%; height:100%; object-fit:cover; }
.lt-sheet-media.lt-media-empty { display:grid; place-items:center; color:var(--accent); font:4rem var(--serif); }.lt-sheet-meta { display:flex; align-items:baseline; gap:12px; margin-top:12px; }
.lt-sheet-meta strong { font-size:1.2rem; }.lt-sheet-meta small { color:var(--accent); font-size:.62rem; }.lt-sheet-item h3 { margin:9px 0; font-size:.9rem; line-height:1.35; }
.lt-sheet-item h3 a { color:var(--ink); }.lt-sheet-item time { color:var(--muted); font-size:.6rem; }

/* Counterpoint */
.cp-hero { display:grid; grid-template-columns:7fr 5fr; gap:48px; min-height:330px; padding:28px 22px; border-bottom:1px solid var(--line); }
.cp-hero-copy { display:flex; flex-direction:column; justify-content:center; }.cp-hero h1 { max-width:16ch; margin:0; color:var(--ink); font:600 clamp(2.7rem,4vw,4.2rem)/1.17 var(--serif); }
.cp-hero-description { max-width:58ch; margin:20px 0; color:var(--ink-soft); font-size:.8rem; line-height:1.75; }.cp-hero-copy > a { color:var(--accent); font-size:.7rem; }
.cp-hero-media { position:relative; min-height:250px; overflow:hidden; background:transparent; }.cp-hero-media > :is(img,a,.cp-hero-embed,.cp-media-fallback) { display:block; width:100%; height:100%; }
.cp-hero-media img { width:100%; height:100%; object-fit:cover; }.cp-hero-caption { position:absolute; right:0; bottom:0; left:0; display:flex!important; justify-content:space-between; align-items:center; height:auto!important; padding:9px 0 0; background:var(--bg); color:var(--muted); font-size:.6rem; }
.cp-premise { display:grid; grid-template-columns:180px 110px minmax(0,1fr) 120px; gap:24px; align-items:center; min-height:135px; padding:18px 22px; border-bottom:1px solid var(--line); }
.cp-premise-label { display:flex; flex-direction:column; gap:14px; color:var(--accent); }.cp-premise-label small { color:var(--muted); font-size:.6rem; }
.cp-premise-number { padding-right:20px; border-right:1px solid var(--line); color:var(--accent); font:700 3.6rem var(--sans); }.cp-premise-copy h2 { margin:0 0 10px; font:600 1.65rem var(--serif); }
.cp-premise-copy h2 a { color:var(--ink); }.cp-premise-copy p { margin:0; color:var(--ink-soft); font-size:.7rem; }.cp-premise-action { color:var(--accent); font-size:.7rem; text-align:right; }
.cp-reading { padding:18px 22px 0; }.cp-reading > header { display:grid; grid-template-columns:1fr auto 1fr; align-items:center; margin-bottom:10px; }
.cp-reading > header h2 { margin:0; font:600 1.15rem var(--serif); }.cp-reading > header span { grid-column:2; color:var(--muted); font-size:.68rem; }
.cp-pair-stream { position:relative; }.cp-pair-stream::before { content:""; position:absolute; top:0; bottom:0; left:50%; border-left:1px solid var(--line); }
.cp-path { position:relative; display:grid; grid-template-columns:160px minmax(0,1fr); gap:22px; width:calc(50% - 36px); min-height:150px; padding:18px 0; border-bottom:1px solid var(--line); }
.cp-path:nth-child(even) { margin-left:calc(50% + 36px); grid-template-columns:minmax(0,1fr) 160px; }.cp-path:nth-child(even) .cp-path-media { order:2; }
.cp-path-media { overflow:hidden; background:var(--accent-wash); }.cp-path-media img { width:100%; height:100%; object-fit:cover; }.cp-path-media.cp-media-empty { display:grid; place-items:center; color:var(--accent); font:4rem var(--serif); }
.cp-path-copy small { color:var(--accent); font-size:.62rem; }.cp-path-copy h3 { margin:10px 0; font:600 1.15rem/1.28 var(--serif); }.cp-path-copy h3 a { color:var(--ink); }
.cp-path-copy p { margin:0 0 10px; color:var(--muted); font-size:.66rem; line-height:1.55; }.cp-path-copy time { color:var(--muted); font-size:.6rem; }
.cp-path-marker { position:absolute; top:50%; right:-68px; display:flex; align-items:center; gap:8px; width:32px; transform:translateY(-50%); color:var(--muted); font-size:.65rem; }
.cp-path:nth-child(even) .cp-path-marker { right:auto; left:-68px; }.cp-path-marker i { width:8px; height:8px; border-radius:50%; background:var(--accent); }
.cp-ledger { position:relative; display:grid; grid-template-columns:110px minmax(0,1fr) 130px; gap:20px; align-items:start; margin:20px 22px 0; padding:18px 0; border-top:1px solid var(--ink); border-bottom:1px solid var(--line); }
.cp-ledger header h2 { margin:0; font:600 1.1rem var(--serif); }.cp-ledger-list { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); }
.cp-ledger-list a { min-width:0; min-height:74px; padding:0 16px; border-right:1px solid var(--line); color:var(--ink); }.cp-ledger-list b { display:block; font: .72rem/1.4 var(--serif); }
.cp-ledger-list span,.cp-ledger-list time { display:block; margin-top:7px; color:var(--muted); font-size:.56rem; }.cp-ledger-all { color:var(--accent); font-size:.68rem; text-align:right; }

/* Shared inner-page language for the six new skeletons. */
:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) :is(.index-wrap,.article-grid,.page-wrap,.search-wrap) {
  max-width:1180px; margin-inline:auto;
}
:is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) :is(.post-card,.article-card) {
  border-radius:0; box-shadow:none; border-color:var(--line);
}

@media (max-width:1100px) {
  .si-feature { grid-template-columns:150px minmax(0,1fr) 130px; }.si-feature-cover { display:none; }
  .si-shelf { grid-template-columns:170px minmax(0,1fr) 260px; }
  .ts-lenses nav { grid-template-columns:repeat(3,minmax(0,1fr)); }.ts-lens { border-bottom:1px solid var(--line); }
  .pb-feature { grid-template-columns:180px minmax(0,1fr); }.pb-feature-cover { display:none; }
  .mr-intro { grid-template-columns:4fr 5fr; }.mr-hero-media { min-height:260px; grid-column:1/-1; }
  .mr-reading-grid { grid-template-columns:2fr 6fr; }.mr-companions { grid-column:1/-1; border-top:1px solid var(--line); }
  .lt-hero,.cp-hero { gap:30px; }.cp-path { grid-template-columns:120px minmax(0,1fr); }.cp-path:nth-child(even) { grid-template-columns:minmax(0,1fr) 120px; }
  .cp-ledger { grid-template-columns:100px 1fr; }.cp-ledger-all { grid-column:2; }
}
@media (max-width:760px) {
  :is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) .ec-site-header { min-height:59px; height:auto; }
  :is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) .ec-header-grid { min-height:58px; height:58px; }
  :is([data-theme^="shelf-index"],[data-theme^="tradeoff-sheet"],[data-theme^="progress-bulletin"],[data-theme^="margin-reading-room"],[data-theme^="light-table"],[data-theme^="counterpoint"]) .ec-main-nav { top:58px; height:auto; }
  :is(.shelf-index-page,.tradeoff-sheet-page,.progress-bulletin-page,.margin-reading-room-page,.light-table-page,.counterpoint-page) { padding-inline:18px; }
  .si-hero,.ts-hero,.pb-hero,.lt-hero,.cp-hero { display:block; min-height:0; }
  .si-hero-copy,.ts-hero-copy { padding:38px 4px; border-right:0; border-bottom:1px solid var(--line); }
  .si-hero h1,.ts-hero h1,.pb-hero h1,.lt-hero h1,.cp-hero h1 { font-size:clamp(2.7rem,12vw,4.1rem); }
  .si-hero-media,.ts-hero-media,.pb-hero-media,.lt-hero-visual,.cp-hero-media { min-height:240px; padding:0; margin-top:24px; }
  .si-feature,.ts-focus,.pb-feature,.pb-feature:not(:has(.pb-feature-cover)) { display:block; }
  .si-feature > *,.ts-focus > *,.pb-feature > * { padding:22px 4px; border-right:0; border-bottom:1px solid var(--line); }
  .si-feature-cover,.pb-feature-cover { display:block; height:220px; padding:0; }
  .si-shelf { display:block; }.si-shelf > div { padding:22px 4px; border-right:0; border-bottom:1px solid var(--line); }
  .si-latest-head,.ts-row-head,.mr-bibliography-head { display:none; }
  .si-latest-row { grid-template-columns:1fr auto; padding:10px 0; }.si-latest-row span { display:none; }
  .ts-lenses nav { grid-template-columns:repeat(2,minmax(0,1fr)); }.ts-row { grid-template-columns:44px minmax(0,1fr) 24px; padding:12px 0; }.ts-row-category,.ts-row time { display:none; }
  .pb-hero { padding:34px 4px; }.pb-feature { margin-top:20px; }.pb-categories nav { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .pb-categories nav a { border-bottom:1px solid var(--line); }.pb-ledger-row { grid-template-columns:92px minmax(0,1fr) 20px; gap:12px; }.pb-ledger-category { display:none; }
  .mr-intro,.mr-intro.no-feature,.mr-intro.no-media,.mr-intro.no-feature.no-media,.mr-reading-grid { display:block; }
  .mr-intro > *,.mr-reading-grid > * { padding:28px 4px; border-right:0; border-bottom:1px solid var(--line); }.mr-hero-media { min-height:240px; padding:0; }
  .mr-bibliography-row { grid-template-columns:32px minmax(0,1fr) auto; padding:9px 0; }.mr-bibliography-row em { display:none; }.mr-bibliography-row small { display:none; }
  .lt-hero-copy,.cp-hero-copy { padding:28px 4px; }.lt-category-strip { grid-template-columns:repeat(2,minmax(0,1fr)); }.lt-category-strip a { min-height:58px; justify-content:center; border-bottom:1px solid var(--line); }
  .lt-feature { display:block; }.lt-feature-media { display:block; height:230px; }.lt-feature-copy { padding:28px 4px; }.lt-contact-sheet { grid-template-columns:repeat(2,minmax(0,1fr)); }.lt-sheet-item:nth-child(2n) { border-right:0; }
  .cp-premise { grid-template-columns:70px minmax(0,1fr); padding-inline:4px; }.cp-premise-label { grid-column:1/-1; }.cp-premise-number { grid-row:2; }.cp-premise-action { grid-column:2; text-align:left; }
  .cp-reading,.cp-ledger { margin-inline:0; padding-inline:4px; }.cp-pair-stream::before { display:none; }.cp-path,.cp-path:nth-child(even) { grid-template-columns:100px minmax(0,1fr); width:100%; margin-left:0; }
  .cp-path:nth-child(even) .cp-path-media { order:0; }.cp-path-marker { display:none; }.cp-ledger { display:block; }.cp-ledger-list { grid-template-columns:1fr; margin:16px 0; }.cp-ledger-list a { min-height:0; padding:10px 0; border-right:0; border-bottom:1px solid var(--line); }
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg:        #131210;
    --surface:   #1a1815;
    --ink:       #f0ede6;
    --ink-soft:  #d8d4cb;
    --muted:     #a39e93;
    --faint:     #7c776d;
    --line:      #2c2924;
    --line-soft: #221f1b;
    --accent:      #e0816e;
    --accent-soft: #ec9582;
    --accent-wash: #251b17;
    --code-bg:     #0d0c0a;
    --shadow: 0 1px 2px rgba(0,0,0,.3), 0 8px 24px rgba(0,0,0,.35);
  }
}

/* ---------- 重置 ---------- */
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 17px;
  line-height: 1.7;
  letter-spacing: .01em;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}
img, svg, video { max-width: 100%; height: auto; display: block; }
a { color: var(--accent); text-decoration: none; transition: color var(--speed); }
a:hover { color: var(--accent-soft); }
h1, h2, h3, h4 { font-family: var(--serif); color: var(--ink); font-weight: 600; line-height: 1.25; letter-spacing: 0; }
hr { border: 0; border-top: 1px solid var(--line); margin: 2.5rem 0; }
::selection { background: var(--accent-wash); color: var(--accent); }

/* ---------- 布局容器 ---------- */
.wrap { width: 100%; max-width: var(--w-wide); margin: 0 auto; padding: 0 24px; }
.read { max-width: var(--w-read); margin: 0 auto; }
.muted { color: var(--muted); }
.center { text-align: center; }

/* ---------- 顶部导航 ---------- */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: color-mix(in srgb, var(--bg) 86%, transparent);
  -webkit-backdrop-filter: saturate(180%) blur(12px);
  backdrop-filter: saturate(180%) blur(12px);
  border-bottom: 1px solid var(--line);
}
.site-header .wrap { display: flex; align-items: center; justify-content: space-between; height: 64px; }
.brand { display: flex; align-items: baseline; gap: .5rem; font-family: var(--serif); font-size: 1.3rem; font-weight: 600; color: var(--ink); letter-spacing: .02em; }
.brand .dot { color: var(--accent); }
.brand small { font-family: var(--sans); font-size: .68rem; letter-spacing: .28em; text-transform: uppercase; color: var(--faint); font-weight: 600; }
.nav { display: flex; align-items: center; gap: 1.6rem; }
.nav a { color: var(--ink-soft); font-size: .94rem; font-weight: 500; position: relative; }
.nav a:hover { color: var(--accent); }
/* 导航里嵌的按钮（如 factory-sidebar 竖栏底部「联系我们」）：上两条(0,1,1)/(0,2,1)
   会盖掉 .btn-primary(0,1,0) 的文字色与 .btn-primary:hover(0,2,0)——强调底上出灰字
   （看着像禁用态）、悬停变强调色压强调底（隐形）。用 :where(0 特异度)原位补回按钮
   文字链，且保持低于各皮肤 :root[data-theme=…] .btn-primary(0,3,0) 的深底浅字覆写。 */
.nav a:where(.btn) { color: var(--ink); font-size: .92rem; font-weight: 600; }
.nav a:where(.btn):hover { color: var(--accent); }
.nav a:where(.btn-primary), .nav a:where(.btn-primary):hover { color: #fff; }
.nav a[aria-current="page"] { color: var(--accent); }
.nav a[aria-current="page"]::after { content: ""; position: absolute; left: 0; right: 0; bottom: -22px; height: 2px; background: var(--accent); }
.nav .search-ico { display: inline-flex; opacity: .65; }
.nav .search-ico:hover { opacity: 1; }
.menu-toggle { display: none; align-items: center; justify-content: center; width: 40px; height: 40px; margin: 0 -8px 0 0; padding: 0; border: 0; background: none; color: var(--ink); border-radius: 9px; cursor: pointer; }
.menu-toggle:hover { background: var(--accent-wash); color: var(--accent); }
.menu-toggle svg { display: block; }
.brand-tagline { display: none; }
.search-label { display: none; }

/* ---------- 页脚 ---------- */
.site-footer { border-top: 1px solid var(--line); margin-top: 5rem; padding: 3rem 0; background: var(--surface); }
.site-footer .wrap { display: flex; flex-wrap: wrap; gap: 1.5rem; justify-content: space-between; align-items: flex-start; }
.site-footer .brand { font-size: 1.1rem; margin-bottom: .4rem; }
.site-footer .f-col h4 { font-family: var(--sans); font-size: .72rem; letter-spacing: .18em; text-transform: uppercase; color: var(--faint); margin: 0 0 .8rem; }
.site-footer .f-col a { display: block; color: var(--ink-soft); font-size: .92rem; padding: .22rem 0; }
.site-footer .f-col a:hover { color: var(--accent); }
.site-footer .copy { color: var(--faint); font-size: .85rem; margin-top: .4rem; }
.f-cols { display: flex; gap: 3.5rem; flex-wrap: wrap; }

/* ---------- 首页 Hero ---------- */
.hero { padding: 4.5rem 0 3.5rem; border-bottom: 1px solid var(--line); }
.hero-inner { display: grid; grid-template-columns: 1.02fr 0.98fr; gap: 3rem; align-items: center; }
.hero .eyebrow { font-size: .76rem; letter-spacing: .26em; text-transform: uppercase; color: var(--accent); font-weight: 700; margin-bottom: 1.1rem; }
.hero h1 { font-size: clamp(2.2rem, 5vw, 3.4rem); margin: 0 0 1.1rem; letter-spacing: -.01em; }
.hero-sub { font-size: 1.18rem; color: var(--muted); max-width: 42ch; margin: 0; }
.knowledge-docs { display: none; }
.knowledge-links { display: none; }

/* Hero 科技感图形 */
.hero-visual { position: relative; }
.hero-svg { width: 100%; height: auto; max-width: 520px; margin-inline: auto; display: block; overflow: visible; }
.hero-img { width: 100%; height: auto; max-width: 520px; margin-inline: auto; display: block; border-radius: var(--radius); object-fit: contain; }
.hero-embed { width: 100%; max-width: 520px; margin-inline: auto; }
.hero-embed svg, .hero-embed img { width: 100%; height: auto; display: block; }
.hero-svg .hv-grid   { fill: var(--ink); opacity: .05; }
.hero-svg .hv-orbit  { fill: none; stroke: var(--line); stroke-width: 1.4; stroke-dasharray: 2 7; stroke-linecap: round; opacity: .9; }
.hero-svg .hv-node   { fill: var(--accent); }
.hero-svg .hv-ring   { fill: none; stroke: var(--accent); stroke-width: 2; transform-origin: 240px 80px; }
.hero-svg .hv-flow   { fill: var(--accent); filter: drop-shadow(0 0 5px color-mix(in srgb, var(--accent) 70%, transparent)); offset-path: path('M55,220 A185,140 0 1,1 425,220 A185,140 0 1,1 55,220'); offset-distance: 0%; }
.hero-svg .hv-panel  { fill: var(--surface); stroke: var(--line); stroke-width: 1.5; }
.hero-svg .hv-panel.back { opacity: .5; }
.hero-svg .hv-panel.mid  { opacity: .8; }
.hero-svg .hv-card   { fill: var(--surface); stroke: var(--line); stroke-width: 1.5; }
.hero-svg .hv-bar    { stroke: var(--line); stroke-width: 1.5; }
.hero-svg .hv-tdot   { fill: var(--faint); }
.hero-svg .hv-tdot.accent { fill: var(--accent); }
.hero-svg .hv-line   { fill: var(--line); }
.hero-svg .hv-line.accent { fill: var(--accent); }
.hero-svg .hv-code   { fill: var(--code-bg); }
.hero-svg .hv-codeline { opacity: .55; }
.hero-svg .hv-codeline.a { fill: var(--accent); opacity: .9; }
.hero-svg .hv-codeline.b { fill: #fff; opacity: .22; }
.hero-svg .hv-codeline.c { fill: #fff; opacity: .32; }

@keyframes hvFlow { to { offset-distance: 100%; } }
@keyframes hvPing { 0% { transform: scale(1); opacity: .9; } 70%,100% { transform: scale(3.6); opacity: 0; } }
.hero-svg .hv-flow { animation: hvFlow 7s linear infinite; }
.hero-svg .hv-ring { animation: hvPing 3.2s ease-out infinite; }

@media (prefers-reduced-motion: reduce) {
  .hero-svg .hv-flow { animation: none; offset-distance: 32%; }
  .hero-svg .hv-ring { animation: none; opacity: .35; }
}

/* ---------- 默认动画（动画二）：SQLite 数据 → 单文件二进制 → 多语种页面 ---------- */
.hero-svg .hv2-grid { fill: var(--ink); opacity: .05; }
.hero-svg .hv2-glow { fill: var(--accent); filter: blur(20px); opacity: .5; transform-origin: 240px 206px; animation: hv2Glow 4.6s ease-in-out infinite; }
.hero-svg .hv2-pulse { fill: none; stroke: var(--accent); stroke-width: 1.5; opacity: 0; transform-origin: 240px 206px; animation: hv2Pulse 3.6s ease-out infinite; }
.hero-svg .hv2-pulse.p2 { animation-delay: 1.8s; }
.hero-svg .hv2-orbit { fill: none; stroke: var(--line); stroke-width: 1.4; stroke-dasharray: 1.5 7; stroke-linecap: round; opacity: .85; }
.hero-svg .hv2-orbiter { transform-origin: 240px 206px; animation: hv2Spin 9s linear infinite; }
.hero-svg .hv2-orbnode { fill: var(--accent); }
.hero-svg .hv2-wire { fill: none; stroke: var(--line); stroke-width: 1.6; stroke-dasharray: 2 6; stroke-linecap: round; }
.hero-svg .hv2-pkt { fill: var(--accent); filter: drop-shadow(0 0 5px color-mix(in srgb, var(--accent) 70%, transparent)); }
.hero-svg .hv2-db ellipse, .hero-svg .hv2-db path { fill: none; stroke: var(--accent); stroke-width: 1.8; stroke-linejoin: round; }
.hero-svg .hv2-db .hv2-db-top { fill: color-mix(in srgb, var(--accent) 14%, var(--surface)); }
.hero-svg .hv2-globe line, .hero-svg .hv2-globe ellipse, .hero-svg .hv2-globe path { fill: none; stroke: var(--muted); stroke-width: 1.4; }
.hero-svg .hv2-globe .hv2-globe-face { fill: var(--surface); stroke: var(--muted); stroke-width: 1.6; }
.hero-svg .hv2-win { fill: var(--surface); stroke: var(--line); stroke-width: 1.6; }
.hero-svg .hv2-win-bar { stroke: var(--line); stroke-width: 1.4; }
.hero-svg .hv2-win-dot { fill: var(--faint); }
.hero-svg .hv2-win-dot.accent { fill: var(--accent); }
.hero-svg .hv2-win-line { fill: var(--line); }
.hero-svg .hv2-win-line.accent { fill: var(--accent); }
.hero-svg .hv2-pins line { stroke: var(--accent); stroke-width: 2; stroke-linecap: round; opacity: .6; }
.hero-svg .hv2-chip { fill: var(--surface); stroke: var(--accent); stroke-width: 2; }
.hero-svg .hv2-chip-glow { fill: none; stroke: var(--accent); stroke-width: 2.4; opacity: 0; animation: hv2Chip 3.6s ease-in-out infinite; }
.hero-svg .hv2-cl { fill: var(--line); }
.hero-svg .hv2-cl.accent { fill: var(--accent); }
.hero-svg .hv2-cl.dim { fill: var(--faint); }
.hero-svg .hv2-cursor { fill: var(--accent); animation: hv2Blink 1.1s step-end infinite; }

@keyframes hv2Glow { 0%, 100% { opacity: .42; } 50% { opacity: .9; } }
@keyframes hv2Pulse { 0% { opacity: .5; transform: scale(.5); } 100% { opacity: 0; transform: scale(1.9); } }
@keyframes hv2Spin { to { transform: rotate(360deg); } }
@keyframes hv2Chip { 0%, 100% { opacity: 0; } 50% { opacity: .5; } }
@keyframes hv2Blink { 0%, 50% { opacity: 1; } 51%, 100% { opacity: 0; } }

@media (prefers-reduced-motion: reduce) {
  .hero-svg .hv2-glow, .hero-svg .hv2-pulse, .hero-svg .hv2-orbiter, .hero-svg .hv2-chip-glow, .hero-svg .hv2-cursor { animation: none; }
  .hero-svg .hv2-glow { opacity: .5; }
  .hero-svg .hv2-pulse { opacity: .22; }
  .hero-svg .hv2-pkt { display: none; }
}

/* ---------- 区块标题 ---------- */
.section-head { display: flex; align-items: baseline; justify-content: space-between; margin: 3rem 0 1.6rem; }
.section-head h2 { font-size: 1.05rem; font-family: var(--sans); font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--faint); margin: 0; }
.section-head a { font-size: .9rem; }

/* ---------- 精选文章（大卡） ---------- */
.feature { display: grid; grid-template-columns: 1.1fr 1fr; gap: 2.5rem; align-items: center; padding: 2.5rem 0; }
.feature.no-cover { grid-template-columns: 1fr; }
.feature-more { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-top: 1rem; }
.card-excerpt { margin: .5rem 0 0; font-size: .92rem; color: var(--muted); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
@media (max-width: 860px) { .feature-more { grid-template-columns: 1fr 1fr; } }
@media (max-width: 560px) { .feature-more { grid-template-columns: 1fr; } }
.feature .cover { aspect-ratio: 16/10; border-radius: var(--radius); background: linear-gradient(135deg, #d9c7bd, #b79b8c 55%, #8d6f63); box-shadow: var(--shadow); position: relative; overflow: hidden; }
.feature .cover::after { content: ""; position: absolute; inset: 0; background: radial-gradient(120% 80% at 20% 10%, rgba(255,255,255,.35), transparent 60%); }
.feature .meta { margin-bottom: .9rem; }
.feature h3 { font-size: clamp(1.6rem, 3vw, 2.1rem); margin: 0 0 .9rem; }
.feature h3 a { color: var(--ink); }
.feature h3 a:hover { color: var(--accent); }
.feature p { color: var(--muted); margin: 0 0 1.2rem; font-size: 1.02rem; }

/* ---------- 文章列表 ---------- */
.post-list { display: flex; flex-direction: column; }
.post-item { display: grid; grid-template-columns: 88px 1fr; gap: 1.6rem; padding: 1.8rem 0; border-top: 1px solid var(--line); transition: background var(--speed); }
.post-item:hover { background: linear-gradient(90deg, transparent, var(--line-soft) 50%, transparent); }
.post-item .num { font-family: var(--serif); font-size: 1.1rem; color: var(--faint); padding-top: .2rem; }
.post-item h3 { font-size: 1.35rem; margin: .2rem 0 .5rem; }
.post-item h3 a { color: var(--ink); }
.post-item h3 a:hover { color: var(--accent); }
.post-item p { color: var(--muted); margin: 0 0 .7rem; font-size: .98rem; }

/* ---------- 元信息行 ---------- */
.meta { display: flex; flex-wrap: wrap; align-items: center; gap: .6rem; font-size: .82rem; color: var(--faint); }
.meta time, .meta .read-time { white-space: nowrap; }
.meta .sep { opacity: .5; }
.tag {
  display: inline-block; font-size: .76rem; font-weight: 600; letter-spacing: .03em;
  color: var(--accent); background: var(--accent-wash);
  padding: .18rem .6rem; border-radius: 100px; line-height: 1.5;
}
.tag:hover { background: var(--accent); color: #fff; }

/* ---------- 按钮 ---------- */
.btn { display: inline-flex; align-items: center; gap: .5rem; font-size: .92rem; font-weight: 600; padding: .6rem 1.2rem; border-radius: 8px; border: 1px solid var(--line); color: var(--ink); background: var(--surface); transition: all var(--speed); }
.btn:hover { border-color: var(--accent); color: var(--accent); }
.btn-primary { background: var(--accent); color: #fff; border-color: var(--accent); }
.btn-primary:hover { background: var(--accent-soft); border-color: var(--accent-soft); color: #fff; }
/* 禁用态（脏检查：无改动时保存置灰；防重复点击） */
.btn:disabled, .btn[disabled] { opacity: .42; cursor: default; pointer-events: none; }
.btn-primary:disabled, .btn-primary[disabled] { background: var(--accent); border-color: var(--accent); color: #fff; }
.arrow { transition: transform var(--speed); }
.btn:hover .arrow, a:hover .arrow { transform: translateX(3px); }

/* ---------- 面包屑 ---------- */
.breadcrumb { font-size: .82rem; color: var(--faint); padding: 1.8rem 0 0; }
.breadcrumb a { color: var(--muted); }
.breadcrumb a:hover { color: var(--accent); }
.breadcrumb .sep { margin: 0 .5rem; opacity: .5; }

/* ---------- 文章详情 ---------- */
.article-head { padding: 1.6rem 0 2rem; border-bottom: 1px solid var(--line); margin-bottom: 2.5rem; }
.article-head .kicker { color: var(--accent); font-size: .8rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; margin-bottom: 1rem; }
.article-head h1 { font-size: clamp(2rem, 4.5vw, 3rem); margin: 0 0 1.2rem; letter-spacing: -.01em; }
.article-head .lead { font-size: 1.18rem; color: var(--muted); margin: 0 0 1.5rem; }
.byline { display: flex; align-items: center; gap: .8rem; }
.avatar { width: 40px; height: 40px; border-radius: 50%; background: linear-gradient(135deg, var(--accent), var(--accent-soft)); display: grid; place-items: center; color: #fff; font-weight: 600; font-family: var(--serif); }
.byline .who { font-size: .92rem; color: var(--ink-soft); font-weight: 600; }
.byline .when { font-size: .8rem; color: var(--faint); }

.article-cover { aspect-ratio: 21/9; border-radius: var(--radius); margin-bottom: 2.5rem; background: linear-gradient(135deg, #cbb6a6, #9c7b6c 60%, #6f5348); box-shadow: var(--shadow); }

/* ---------- 正文排版（prose） ---------- */
.prose { font-size: 1.08rem; line-height: 1.85; color: var(--ink-soft); }
.prose > * { margin: 0; }
.prose > * + * { margin-top: 1.4rem; }
.prose h2 { font-size: 1.6rem; margin: 2.8rem 0 1rem; padding-top: .4rem; }
.prose h3 { font-size: 1.25rem; margin: 2.2rem 0 .8rem; }
.prose a { text-decoration: underline; text-decoration-color: var(--line); text-underline-offset: 3px; }
.prose a:hover { text-decoration-color: var(--accent); }
.prose strong { color: var(--ink); font-weight: 650; }
.prose ul, .prose ol { margin: 1.2rem 0; padding-left: 1.4rem; }
.prose li { margin: .5rem 0; }
.prose li::marker { color: var(--accent); }
.prose blockquote { margin: 2rem 0; padding: .4rem 0 .4rem 1.6rem; border-left: 3px solid var(--accent); color: var(--muted); font-family: var(--serif); font-style: italic; font-size: 1.15rem; }
.prose code { font-family: var(--mono); font-size: .88em; background: var(--line-soft); padding: .15em .45em; border-radius: 5px; color: var(--accent); }
.prose pre { background: #1c1a17; color: #ece7df; padding: 1.2rem 1.4rem; border-radius: var(--radius); overflow-x: auto; font-size: .9rem; line-height: 1.6; margin: 1.8rem 0; }
.prose pre code { background: none; padding: 0; color: inherit; font-size: inherit; }
.prose figure { margin: 2rem 0; }
.prose figcaption { font-size: .82rem; color: var(--faint); text-align: center; margin-top: .6rem; }
.prose img { border-radius: var(--radius); }
.prose table { width: 100%; border-collapse: collapse; margin: 1.8rem 0; font-size: .95rem; }
.prose th, .prose td { text-align: left; padding: .7rem 1rem; border-bottom: 1px solid var(--line); }
.prose th { color: var(--ink); font-weight: 600; border-bottom: 2px solid var(--line); }

/* 文章底部：标签 + 分享 */
.article-foot { margin-top: 3rem; padding-top: 2rem; border-top: 1px solid var(--line); display: flex; flex-wrap: wrap; gap: 1rem; justify-content: space-between; align-items: center; }
.tag-row { display: flex; flex-wrap: wrap; gap: .5rem; }
/* 文章末尾 Telegram 订阅 CTA（配置了频道链接才渲染；跟随主题变量，保持轻量） */
.article-foot .tg-cta { margin: 0; font-size: .9rem; color: var(--faint); }
.article-foot .tg-cta a { color: var(--accent); }

/* 上一篇/下一篇 */
.pager { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; margin-top: 2.5rem; }
.pager a { border: 1px solid var(--line); border-radius: var(--radius); padding: 1.1rem 1.3rem; color: var(--ink); transition: border-color var(--speed); }
.pager a:hover { border-color: var(--accent); }
.pager .dir { font-size: .74rem; letter-spacing: .12em; text-transform: uppercase; color: var(--faint); margin-bottom: .35rem; }
.pager .t { font-weight: 600; font-size: .98rem; }
.pager .next { text-align: right; }

/* 相关阅读 */
.related { margin-top: 4rem; }
.related-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
.comments { margin-top: 3.2rem; }
.giscus-comments { padding-top: 1.4rem; border-top: 1px solid var(--line-soft); }

/* 链接（资源 / 产品展示）卡片网格 */
.link-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 1.4rem; margin: 1.6rem 0; }
.link-card { display: flex; flex-direction: column; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; background: var(--surface); color: var(--ink); transition: border-color var(--speed), box-shadow var(--speed), transform var(--speed); }
.link-card:hover { border-color: var(--accent); box-shadow: 0 12px 32px rgba(0,0,0,.08); transform: translateY(-3px); }
.lc-cover { aspect-ratio: 16 / 9; overflow: hidden; background: var(--line-soft); display: grid; place-items: center; }
.lc-cover img { width: 100%; height: 100%; object-fit: cover; display: block; }
.lc-mono { width: 100%; height: 100%; display: grid; place-items: center; font-family: var(--serif); font-size: 2.6rem; font-weight: 700; color: #fff; background: linear-gradient(135deg, var(--accent), color-mix(in srgb, var(--accent) 50%, #1a1a1a)); }
.lc-body { flex: 1; padding: 1rem 1.1rem 1.2rem; display: flex; flex-direction: column; gap: .5rem; }
.lc-title { font-size: 1.05rem; margin: 0; display: flex; align-items: center; justify-content: space-between; gap: .5rem; line-height: 1.4; }
.lc-arrow { color: var(--accent); opacity: 0; transform: translateX(-4px); transition: opacity var(--speed), transform var(--speed); }
.link-card:hover .lc-arrow { opacity: 1; transform: none; }
.lc-intro { flex: 1; margin: 0; font-size: .9rem; line-height: 1.6; color: var(--ink-soft); }
.lc-foot { margin-top: .15rem; }
/* 链接详情：访问按钮行 + 网址 */
.link-visit-row { display: flex; align-items: center; flex-wrap: wrap; gap: .7rem 1rem; margin-top: 1rem; }
.link-url { font-size: .85rem; word-break: break-all; }
.ext-url { color: var(--ink-soft); }
.ext-url:hover { color: var(--accent); }
@media (max-width: 480px) { .link-grid { grid-template-columns: 1fr; } }

.card { border: 1px solid var(--line); border-radius: var(--radius); padding: 1.4rem; background: var(--surface); transition: transform var(--speed), border-color var(--speed); }
.card:hover { transform: translateY(-3px); border-color: var(--accent); }
.card .meta { margin-bottom: .6rem; }
.card h4 { font-size: 1.08rem; margin: 0; }
.card h4 a { color: var(--ink); }
.card h4 a:hover { color: var(--accent); }

/* ---------- 分页器 ---------- */
.pagination { display: flex; gap: .4rem; justify-content: center; margin: 3rem 0 0; }
.pagination a, .pagination span { min-width: 40px; height: 40px; display: grid; place-items: center; border-radius: 8px; font-size: .92rem; border: 1px solid var(--line); color: var(--ink-soft); }
.pagination a:hover { border-color: var(--accent); color: var(--accent); }
.pagination .cur { background: var(--accent); color: #fff; border-color: var(--accent); }

/* ---------- 分类/页面 头部 ---------- */
.page-head { padding: 4rem 0 2.5rem; border-bottom: 1px solid var(--line); }
.page-head .eyebrow { font-size: .76rem; letter-spacing: .24em; text-transform: uppercase; color: var(--accent); font-weight: 700; margin-bottom: .9rem; }
.page-head h1 { font-size: clamp(2rem, 4vw, 2.8rem); margin: 0 0 .8rem; }
.page-head p { color: var(--muted); font-size: 1.1rem; margin: 0; max-width: 52ch; }

/* 分类导航药丸 */
.cat-nav { display: flex; flex-wrap: wrap; gap: .6rem; margin: 2rem 0; }
.cat-nav a { padding: .45rem 1rem; border-radius: 100px; border: 1px solid var(--line); font-size: .9rem; color: var(--ink-soft); }
.cat-nav a:hover { border-color: var(--accent); color: var(--accent); }
.cat-nav a.active { background: var(--ink); color: var(--bg); border-color: var(--ink); }
.cat-nav a .muted { display: inline-block; margin-left: .18rem; color: var(--muted); font-size: .72em; font-weight: 700; line-height: 1; transform: translateY(-.02em); }
.cat-nav a.active .muted { color: currentColor; opacity: .68; }

/* ---------- 搜索框 ---------- */
.searchbox { display: flex; gap: .6rem; margin: 1.5rem 0; max-width: 520px; }
.searchbox input { flex: 1; padding: .7rem 1rem; border: 1px solid var(--line); border-radius: 8px; background: var(--surface); color: var(--ink); font-size: 1rem; font-family: inherit; }
.searchbox input:focus { outline: none; border-color: var(--accent); }
.post-list.search-results { margin-top: 1.8rem; margin-bottom: 3rem; }
.search-results .search-empty { margin: 0; padding: 1rem 1.15rem; border: 1px solid var(--line); border-radius: 10px; background: var(--surface); box-shadow: var(--shadow); }

/* ---------- 404 ---------- */
.notfound { text-align: center; padding: 7rem 0; }
.notfound .code { font-family: var(--serif); font-size: clamp(5rem, 18vw, 11rem); line-height: 1; color: var(--accent); opacity: .25; }
.notfound h1 { font-size: 2rem; margin: -1rem 0 1rem; }
.notfound p { color: var(--muted); margin: 0 0 2rem; }

/* ---------- 通用网格 ---------- */
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }

/* ---------- 响应式 ---------- */
@media (max-width: 860px) {
  .feature { grid-template-columns: 1fr; }
  .feature .cover { order: -1; }
  .related-grid, .grid-3 { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 620px) {
  body { font-size: 16px; }
  .menu-toggle { display: inline-flex; }
  .nav { display: none; position: absolute; top: 100%; left: 0; right: 0; flex-direction: column; align-items: stretch; gap: 0; background: var(--surface); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); box-shadow: 0 16px 30px rgba(0,0,0,.1); padding: .35rem .7rem .7rem; z-index: 55; }
  .site-header.nav-open .nav { display: flex; }
  .nav > a { display: block; padding: .8rem .35rem; font-size: 1rem; border-radius: 0; border-bottom: 1px solid var(--line-soft); }
  .nav .search-label { display: inline; }
  .nav > a[aria-current="page"]::after { display: none; }
  .nav .search-ico { padding: .8rem .35rem; opacity: 1; }
  .nav .lang-switch { flex-direction: column; align-items: stretch; align-self: stretch; border-left: 0; margin: 0; padding: 0; }
  .nav .lang-switch > summary { padding: .8rem .35rem; font-size: 1rem; }
  .nav .lang-switch .lang-cur { display: inline; }
  .nav .lang-menu { position: static; box-shadow: none; border: 0; padding: 0 0 .35rem .9rem; min-width: 0; }
  .nav .lang-menu li a { padding: .55rem .35rem; }
  .hero { padding: 3rem 0 2.2rem; }
  .post-item { grid-template-columns: 1fr; gap: .5rem; }
  .post-item .num { display: none; }
  .related-grid, .grid-3 { grid-template-columns: 1fr; }
  .pager { grid-template-columns: 1fr; }
  .f-cols { gap: 2rem; }
}

/* ---------- 打印 ---------- */
@media print {
  .site-header, .site-footer, .pager, .related, .article-foot { display: none; }
  body { background: #fff; color: #000; }
}

/* Hero 响应式 */
@media (max-width: 860px) {
  .hero-inner { grid-template-columns: 1fr; gap: 2rem; }
  .hero-sub { max-width: none; }
  .hero-svg { max-width: 360px; }
}

/* =====================================================================
   主题二 · 杂志 Magazine —— 无衬线、居中刊头、卡片网格
   ===================================================================== */
:root[data-theme="magazine"] {
  --bg: #ffffff; --surface: #ffffff;
  --ink: #14171f; --ink-soft: #2b3140; --muted: #5b6473; --faint: #98a1b0;
  --line: #e7e9ef; --line-soft: #f2f4f8;
  --accent: #1f5fff; --accent-soft: #4178ff; --accent-wash: #ebf1ff;
  --code-bg: #0f1320;
}
[data-theme="magazine"] h1, [data-theme="magazine"] h2,
[data-theme="magazine"] h3, [data-theme="magazine"] h4 { font-family: var(--sans); letter-spacing: -.015em; }

[data-theme="magazine"] .site-header { background: var(--surface); border-bottom: 2px solid var(--ink); }
[data-theme="magazine"] .site-header .wrap { flex-direction: column; height: auto; padding: 1.1rem 24px .85rem; gap: .7rem; }
[data-theme="magazine"] .site-header .brand { font-size: 1.75rem; letter-spacing: .18em; text-transform: uppercase; }
[data-theme="magazine"] .site-header .brand small { display: none; }
[data-theme="magazine"] .nav { gap: 2rem; }
[data-theme="magazine"] .nav a:not(.search-ico) { font-size: .8rem; letter-spacing: .14em; text-transform: uppercase; font-weight: 600; }
[data-theme="magazine"] .nav a[aria-current="page"]::after { display: none; }

[data-theme="magazine"] .hero { text-align: center; padding: 4rem 0 3rem; }
[data-theme="magazine"] .hero-inner { grid-template-columns: 1fr; gap: 1.6rem; }
[data-theme="magazine"] .hero-text { order: 2; max-width: 700px; margin: 0 auto; }
[data-theme="magazine"] .hero-sub { max-width: none; margin: 0 auto; }
[data-theme="magazine"] .hero h1 { font-size: clamp(2.4rem, 6vw, 4.1rem); }
[data-theme="magazine"] .hero-visual { order: 1; }
[data-theme="magazine"] .hero-svg { max-width: 280px; }

[data-theme="magazine"] .section-head { justify-content: center; gap: 1.2rem; border-bottom: 1px solid var(--line); padding-bottom: .9rem; margin-bottom: 2rem; }
[data-theme="magazine"] .section-head h2 { color: var(--ink); font-size: 1.15rem; letter-spacing: .04em; text-transform: none; }

[data-theme="magazine"] .feature { grid-template-columns: 1fr; gap: 0; padding: 0; border: 1px solid var(--line); border-radius: 14px; overflow: hidden; box-shadow: var(--shadow); }
[data-theme="magazine"] .feature .cover { aspect-ratio: 21/8; border-radius: 0; background: linear-gradient(135deg, #c7d4ff, #8aa6ff 55%, #5f7fe0); }
[data-theme="magazine"] .feature > div:not(.cover) { padding: 1.7rem 2rem 2rem; }

[data-theme="magazine"] .post-list { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.6rem; }
[data-theme="magazine"] .post-item { display: block; padding: 0; border: 1px solid var(--line); border-top: 1px solid var(--line); border-radius: 12px; overflow: hidden; background: var(--surface); transition: transform .15s, box-shadow .15s; }
[data-theme="magazine"] .post-item:hover { background: var(--surface); transform: translateY(-4px); box-shadow: 0 10px 30px rgba(20,23,31,.08); }
[data-theme="magazine"] .post-item::before { content: ""; display: block; height: 8px; background: linear-gradient(90deg, var(--accent), var(--accent-soft)); }
[data-theme="magazine"] .post-item .num { display: none; }
[data-theme="magazine"] .post-item > div:not(.num) { padding: 1.3rem 1.4rem 1.5rem; }
[data-theme="magazine"] .post-item h3 { font-size: 1.18rem; }
[data-theme="magazine"] .article-cover { background: linear-gradient(135deg, #c7d4ff, #8aa6ff 55%, #5f7fe0); }
@media (max-width: 860px) { [data-theme="magazine"] .post-list { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { [data-theme="magazine"] .post-list { grid-template-columns: 1fr; } }

/* =====================================================================
   主题三 · 极客 Terminal —— 等宽字体、深色、终端清单式
   ===================================================================== */
:root[data-theme="terminal"] {
  --bg: #0b0f14; --surface: #0f141b;
  --ink: #cdd6e3; --ink-soft: #aeb9c9; --muted: #7d8799; --faint: #586575;
  --line: #1e2630; --line-soft: #161c24;
  --accent: #3fb950; --accent-soft: #56d364; --accent-wash: #11251a;
  --code-bg: #060a0e;
  --shadow: 0 1px 2px rgba(0,0,0,.5), 0 12px 32px rgba(0,0,0,.5);
}
[data-theme="terminal"] body { font-family: var(--mono); letter-spacing: 0; }
[data-theme="terminal"] h1, [data-theme="terminal"] h2,
[data-theme="terminal"] h3, [data-theme="terminal"] h4 { font-family: var(--mono); font-weight: 600; letter-spacing: -.01em; }
[data-theme="terminal"] ::selection { background: var(--accent-wash); color: var(--accent-soft); }

[data-theme="terminal"] .site-header { background: var(--surface); border-bottom: 1px solid var(--line); }
[data-theme="terminal"] .site-header .brand { font-family: var(--mono); font-size: 1.05rem; }
[data-theme="terminal"] .site-header .brand::before { content: "~/"; color: var(--accent); margin-right: .12rem; }
[data-theme="terminal"] .site-header .brand .dot { display: none; }
[data-theme="terminal"] .site-header .brand small { color: var(--faint); letter-spacing: .12em; }
[data-theme="terminal"] .nav a { font-family: var(--mono); font-size: .86rem; }
[data-theme="terminal"] .nav a:not(.search-ico)::before { content: "["; color: var(--faint); }
[data-theme="terminal"] .nav a:not(.search-ico)::after { content: "]"; color: var(--faint); position: static; height: auto; background: none; inset: auto; }
[data-theme="terminal"] .nav a[aria-current="page"] { color: var(--accent); }

[data-theme="terminal"] .hero { padding: 3.5rem 0 3rem; }
[data-theme="terminal"] .hero h1 { font-family: var(--mono); }

[data-theme="terminal"] .section-head h2 { color: var(--accent); }
[data-theme="terminal"] .section-head h2::before { content: "$ "; opacity: .8; }

[data-theme="terminal"] .feature { grid-template-columns: 1fr; gap: 1.2rem; padding: 1.4rem; border: 1px solid var(--line); border-radius: 8px; background: var(--surface); }
[data-theme="terminal"] .feature .cover { aspect-ratio: 21/7; border-radius: 6px; border: 1px solid var(--line); box-shadow: none; background: linear-gradient(135deg, #10271a, #0a1c12 70%); }
[data-theme="terminal"] .feature .cover::after { background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(63,185,80,.06) 3px 4px); }

[data-theme="terminal"] .post-list { display: block; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; background: var(--surface); }
[data-theme="terminal"] .post-item { display: block; padding: 1rem 1.3rem; border-top: 1px solid var(--line); background: none; }
[data-theme="terminal"] .post-item:first-child { border-top: 0; }
[data-theme="terminal"] .post-item:hover { background: var(--line-soft); }
[data-theme="terminal"] .post-item .num { display: none; }
[data-theme="terminal"] .post-item h3 { font-family: var(--mono); font-size: 1.04rem; margin: .15rem 0 .4rem; }
[data-theme="terminal"] .post-item h3 a::before { content: "> "; color: var(--accent); }
[data-theme="terminal"] .post-item p { font-size: .9rem; }
[data-theme="terminal"] .tag { background: none; border: 1px solid var(--line); color: var(--accent); border-radius: 4px; }
[data-theme="terminal"] .tag::before { content: "#"; opacity: .65; }
[data-theme="terminal"] .btn { border-radius: 6px; font-family: var(--mono); }
[data-theme="terminal"] .btn-primary { color: #04150a; }
[data-theme="terminal"] .card { border-radius: 6px; }
[data-theme="terminal"] .article-cover { background: linear-gradient(135deg, #10271a, #0a1c12 70%); border: 1px solid var(--line); }
[data-theme="terminal"] .pagination a, [data-theme="terminal"] .pagination span { border-radius: 5px; font-family: var(--mono); }

/* =====================================================================
   文章大纲（TOC）与带右栏的文章布局
   ===================================================================== */
.article-grid { display: grid; justify-content: center; column-gap: 3rem; align-items: start; grid-template-columns: minmax(0, var(--w-read)); }
.article-grid.has-toc { grid-template-columns: minmax(0, var(--w-read)) 240px; }
/* 面包屑横跨整行（第 1 行），与正文左缘一致 */
.article-bc { grid-column: 1 / -1; grid-row: 1; padding-bottom: .3rem; }
/* 正文与目录同在第 2 行起始 → 目录顶部与文章标题齐平 */
.article-col { grid-column: 1; grid-row: 2; min-width: 0; }
/* 让网格项本身 sticky：它在「与正文同高」的网格区域内有移动空间 */
.toc-rail { grid-column: 2; grid-row: 2; position: sticky; top: calc(var(--header-h, 72px) + 16px); align-self: start; }

.toc { font-size: .9rem; }
.toc > summary { list-style: none; pointer-events: none; font-size: .72rem; letter-spacing: .16em; text-transform: uppercase; color: var(--faint); font-weight: 700; margin-bottom: .8rem; padding-left: .9rem; }
.toc > summary::-webkit-details-marker { display: none; }
.toc ul { list-style: none; margin: 0; padding: 0; border-left: 1px solid var(--line); }
.toc li { margin: 0; }
.toc a { display: block; padding: .32rem .9rem; color: var(--muted); border-left: 2px solid transparent; margin-left: -1px; line-height: 1.45; transition: color .15s, border-color .15s; }
.toc li.lv3 a { padding-left: 1.7rem; font-size: .84rem; }
.toc a:hover { color: var(--accent); }
.toc a.active { color: var(--accent); border-left-color: var(--accent); font-weight: 600; }

.prose h2, .prose h3 { scroll-margin-top: calc(var(--header-h, 72px) + 20px); }

/* 阅读进度条 + 回到顶部（文章页） */
.read-progress { position: fixed; top: 0; left: 0; right: 0; height: 3px; z-index: 100; pointer-events: none; }
.read-progress > i { display: block; height: 100%; width: 100%; background: var(--accent); transform: scaleX(0); transform-origin: 0 50%; will-change: transform; }
/* 未显示时禁点：opacity:0 仍参与命中测试，曾吞掉同角落浮动询盘按钮的点击 */
.to-top { position: fixed; right: 1.5rem; bottom: 1.5rem; z-index: 90; width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--line); background: var(--surface); color: var(--ink); display: grid; place-items: center; cursor: pointer; opacity: 0; transform: translateY(12px); transition: opacity .2s, transform .2s, border-color .2s, color .2s; box-shadow: var(--shadow); pointer-events: none; }
.to-top.show { opacity: 1; transform: translateY(0); pointer-events: auto; }
.to-top:hover { border-color: var(--accent); color: var(--accent); }

@media (max-width: 1100px) {
  .article-grid.has-toc { grid-template-columns: minmax(0, var(--w-read)); }
  .article-bc { grid-row: 1; }
  .toc-rail { grid-column: 1; grid-row: 2; position: static; margin-bottom: 1.6rem; }
  .article-col { grid-row: 3; }
  .toc { border: 1px solid var(--line); border-radius: var(--radius); padding: .9rem 1.2rem; background: var(--surface); }
  .toc > summary { pointer-events: auto; cursor: pointer; margin-bottom: 0; padding-left: 0; }
  .toc > summary::after { content: "▾"; float: right; transition: transform .2s; }
  .toc[open] > summary { margin-bottom: .8rem; }
  .toc[open] > summary::after { transform: rotate(180deg); }
  .toc ul { border-left: 0; }
  .toc a { padding-left: 0; }
  .toc li.lv3 a { padding-left: .9rem; }
}

/* 设置页主题预览色板（扩展主题） */
.tc-brutalist { background: #f3f3ee; }
.tc-brutalist i { border-radius: 0; }
.tc-brutalist .b1 { background: #1f23ff; flex: 0 0 28%; }
.tc-brutalist .b2, .tc-brutalist .b3 { background: #000; }
.tc-notebook { background: #fbf7ec; }
.tc-notebook .b1 { background: #c2691f; flex: 0 0 30%; }
.tc-notebook .b2, .tc-notebook .b3 { background: #e3d8c0; }
.tc-swiss { background: #fff; }
.tc-swiss .b1 { background: #e30613; flex: 0 0 22%; }
.tc-swiss .b2, .tc-swiss .b3 { background: #111; }
.tc-pastel { background: linear-gradient(135deg, #f3e9ff, #ffe9f3); }
.tc-pastel .b1 { background: #8b5cf6; }
.tc-pastel .b2 { background: #ff7eb6; }
.tc-pastel .b3 { background: #7ad7ff; }
.tc-newspaper { background: #f6f4ee; }
.tc-newspaper i { background: #1a1a1a; }
.tc-newspaper .b1 { background: #8b0000; flex: 0 0 24%; }
.tc-darkpro { background: #0e1016; }
.tc-darkpro .b1 { background: #7c7cf8; flex: 0 0 28%; }
.tc-darkpro .b2 { background: #db2777; }
.tc-darkpro .b3 { background: #232838; }

/* =====================================================================
   主题四 · 粗野 Brutalist —— 黑白高对比、粗黑边、硬阴影、无圆角
   ===================================================================== */
:root[data-theme="brutalist"] {
  --bg: #f3f3ee; --surface: #ffffff;
  --ink: #000; --ink-soft: #111; --muted: #333; --faint: #555;
  --line: #000; --line-soft: #e6e6e0;
  --accent: #1f23ff; --accent-soft: #1f23ff; --accent-wash: #e6e7ff;
  --code-bg: #000;
}
[data-theme="brutalist"] h1, [data-theme="brutalist"] h2, [data-theme="brutalist"] h3, [data-theme="brutalist"] h4 { font-family: var(--sans); font-weight: 800; letter-spacing: -.02em; }
[data-theme="brutalist"] .site-header { background: var(--surface); border-bottom: 3px solid #000; }
[data-theme="brutalist"] .site-header .brand { font-weight: 900; text-transform: uppercase; }
[data-theme="brutalist"] .nav a { font-weight: 700; }
[data-theme="brutalist"] .nav a[aria-current="page"]::after { display: none; }
[data-theme="brutalist"] .hero { border-bottom: 3px solid #000; }
[data-theme="brutalist"] .hero h1 { font-weight: 900; font-size: clamp(2.4rem, 6vw, 4.2rem); text-transform: uppercase; }
[data-theme="brutalist"] .hero .eyebrow { display: inline-block; background: #000; color: #fff; padding: .25rem .7rem; }
[data-theme="brutalist"] .hero-svg .hv-card, [data-theme="brutalist"] .hero-svg .hv-panel { stroke: #000; stroke-width: 2.5; }
[data-theme="brutalist"] .section-head h2 { display: inline-block; background: #000; color: #fff; padding: .2rem .6rem; }
[data-theme="brutalist"] .feature { grid-template-columns: 1fr; gap: 0; padding: 0; border: 3px solid #000; border-radius: 0; overflow: hidden; background: #fff; box-shadow: 8px 8px 0 #000; }
[data-theme="brutalist"] .feature .cover { aspect-ratio: 21/8; border-radius: 0; border-bottom: 3px solid #000; background: var(--accent); }
[data-theme="brutalist"] .feature > div:not(.cover) { padding: 1.6rem; }
[data-theme="brutalist"] .post-list { display: grid; grid-template-columns: 1fr 1fr; gap: 1.4rem; }
[data-theme="brutalist"] .post-item { display: block; border: 2.5px solid #000; border-radius: 0; padding: 1.3rem; background: #fff; box-shadow: 6px 6px 0 #000; transition: transform .1s, box-shadow .1s; }
[data-theme="brutalist"] .post-item:hover { transform: translate(-2px, -2px); box-shadow: 8px 8px 0 var(--accent); background: #fff; }
[data-theme="brutalist"] .post-item .num { display: none; }
[data-theme="brutalist"] .post-item > div:not(.num) { padding: 0; }
[data-theme="brutalist"] .tag { border: 2px solid #000; border-radius: 0; background: #fff; color: #000; font-weight: 700; }
[data-theme="brutalist"] .tag:hover { background: var(--accent); color: #fff; }
[data-theme="brutalist"] .btn { border: 2.5px solid #000; border-radius: 0; box-shadow: 4px 4px 0 #000; font-weight: 700; }
[data-theme="brutalist"] .btn-primary { background: var(--accent); color: #fff; }
[data-theme="brutalist"] .pagination a, [data-theme="brutalist"] .pagination span { border: 2px solid #000; border-radius: 0; }
[data-theme="brutalist"] .pagination .cur { background: var(--accent); }
[data-theme="brutalist"] .card { border: 2.5px solid #000; border-radius: 0; box-shadow: 5px 5px 0 #000; }
@media (max-width: 860px) { [data-theme="brutalist"] .post-list { grid-template-columns: 1fr; } }

/* =====================================================================
   主题五 · 手账 Notebook —— 米黄横格纸、衬线、暖橙、虚线分隔
   ===================================================================== */
:root[data-theme="notebook"] {
  --bg: #fbf7ec; --surface: #fffdf6;
  --ink: #3a3326; --ink-soft: #52493a; --muted: #857a64; --faint: #a99c80;
  --line: #e6dcc4; --line-soft: #f0e9d8;
  --accent: #c2691f; --accent-soft: #d67c2c; --accent-wash: #f6ead7;
  --code-bg: #2a2418;
}
[data-theme="notebook"] body { background-color: var(--bg); background-image: repeating-linear-gradient(transparent, transparent 31px, color-mix(in srgb, var(--line) 42%, transparent) 31px, color-mix(in srgb, var(--line) 42%, transparent) 32px); }
[data-theme="notebook"] .site-header { background: color-mix(in srgb, var(--bg) 94%, transparent); border-bottom: 0; }
[data-theme="notebook"] .nav a[aria-current="page"]::after { display: none; }
[data-theme="notebook"] .hero { border-bottom: 0; }
[data-theme="notebook"] .hero .eyebrow { color: var(--accent); }
[data-theme="notebook"] .hero-sub { font-family: var(--serif); font-style: italic; }
[data-theme="notebook"] .section-head h2 { color: var(--accent); }
[data-theme="notebook"] .feature { grid-template-columns: 1fr; gap: 0; padding: 0; border: 1px dashed var(--accent); border-radius: 8px; overflow: hidden; background: var(--surface); }
[data-theme="notebook"] .feature .cover { aspect-ratio: 21/8; border-radius: 0; background: linear-gradient(135deg, #e8cfa6, #d8a86a); }
[data-theme="notebook"] .feature > div:not(.cover) { padding: 1.5rem 1.8rem; }
[data-theme="notebook"] .post-item { border-top: 1px dashed var(--line); }
[data-theme="notebook"] .post-item .num { font-family: var(--serif); color: var(--accent); }
[data-theme="notebook"] .post-item h3 a::before { content: "✦ "; color: var(--accent); }
[data-theme="notebook"] .tag { background: var(--accent-wash); color: var(--accent); border-radius: 4px; }
[data-theme="notebook"] .card { border-style: dashed; }

/* =====================================================================
   主题六 · 瑞士 Swiss —— 国际主义网格、红黑、巨号编号、无衬线
   ===================================================================== */
:root[data-theme="swiss"] {
  --bg: #ffffff; --surface: #ffffff;
  --ink: #111; --ink-soft: #222; --muted: #555; --faint: #999;
  --line: #111; --line-soft: #e6e6e6;
  --accent: #e30613; --accent-soft: #ff1a2b; --accent-wash: #ffe8ea;
  --code-bg: #111;
}
[data-theme="swiss"] h1, [data-theme="swiss"] h2, [data-theme="swiss"] h3, [data-theme="swiss"] h4 { font-family: var(--sans); font-weight: 700; letter-spacing: -.02em; }
[data-theme="swiss"] .site-header { background: #fff; border-bottom: 2px solid #111; }
[data-theme="swiss"] .site-header .brand { font-weight: 800; text-transform: uppercase; }
[data-theme="swiss"] .site-header .brand small { display: none; }
[data-theme="swiss"] .nav a { text-transform: uppercase; font-size: .8rem; letter-spacing: .1em; font-weight: 600; }
[data-theme="swiss"] .nav a[aria-current="page"] { color: var(--accent); }
[data-theme="swiss"] .nav a[aria-current="page"]::after { display: none; }
[data-theme="swiss"] .hero { border-bottom: 2px solid #111; }
