  --accent:#8c624d; --accent-soft:#a97a5f; --accent-wash:#eee3da; --hero-accent:#7f5946;
  --hero-ink:#171a1d; --hero-muted:#4d5358; --radius:0px;
}
:root[data-theme="night-corridor-white"] {
  --bg:#fff; --surface:#fff; --ink:#151617; --ink-soft:#414446;
  --muted:#717579; --faint:#a8aaab; --line:#d5d5d4; --line-soft:#eeeeed;
