}
.nc-guide b,.nc-guide small { display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.nc-guide b { font-size:.76rem; }.nc-guide small { margin-top:6px; color:var(--hero-muted); font-size:.6rem; }
.nc-guide strong { color:var(--accent); font:500 .72rem var(--mono); text-align:right; }
.nc-guide-all { display:inline-block; margin-top:16px; color:var(--hero-ink); font-size:.66rem; }
.nc-hero-index {
  position:absolute; right:0; bottom:0; left:0; z-index:3;
  display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); min-height:108px; padding-inline:var(--media-frame-gutter);
  border-top:1px solid color-mix(in srgb,var(--hero-ink) 28%,transparent);
  background:color-mix(in srgb,var(--bg) 46%,transparent);
}
.nc-hero-index a {
  display:grid; grid-template-columns:46px minmax(0,1fr); gap:14px; align-items:center;
  min-width:0; padding:22px clamp(16px,2vw,30px);
  border-right:1px solid color-mix(in srgb,var(--hero-ink) 22%,transparent); color:var(--hero-ink);
}
.nc-hero-index a:last-child { border-right:0; }
.nc-hero-index strong { color:var(--accent); font:500 .9rem var(--mono); }
.nc-hero-index b,.nc-hero-index small { display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.nc-hero-index b { font-size:.72rem; }.nc-hero-index small { margin-top:6px; color:var(--hero-muted); font-size:.59rem; }
.nc-curation {
  display:grid; grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr); gap:clamp(50px,7vw,112px);
}
.nc-curation-articles > a {
  display:grid; grid-template-columns:42px minmax(0,1fr) auto; gap:18px; align-items:center;
  min-height:86px; border-bottom:1px solid var(--line); color:var(--ink);
}
.nc-curation-articles > a > strong { color:var(--accent); font:500 .8rem var(--mono); }
.nc-curation-articles b,.nc-curation-articles small,.nc-curation-links b,.nc-curation-links small { display:block; }
.nc-curation-articles small,.nc-curation-links small {
  margin-top:6px; color:var(--muted); font-size:.64rem; line-height:1.5;
}
.nc-curation-articles time { color:var(--muted); font-size:.62rem; }
.nc-curation-links > a {
  display:flex; justify-content:space-between; gap:18px; min-height:70px; padding:16px 0;
  border-bottom:1px solid var(--line); color:var(--ink);
}
.nc-curation-links em { color:var(--muted); font-size:.62rem; font-style:normal; white-space:nowrap; }

/* Open Ascent — 明亮建筑媒体与左侧索引、右侧精选共同占据首屏。 */
.oa-hero {
  position:relative; min-height:clamp(860px,84vh,920px); overflow:hidden;
  color:var(--hero-ink); isolation:isolate;
}
.oa-hero.no-media { background:var(--bg); }
[data-theme="open-ascent-dark"] .oa-hero-media > img,
[data-theme="open-ascent-dark"] .oa-hero-embed { filter:brightness(.45) saturate(.85); }
.oa-hero-copy {
  position:relative; z-index:2; display:flex; flex-direction:column; justify-content:center;
  width:min(46%,calc(var(--oa-frame-gutter) + 410px)); min-height:clamp(530px,62vh,665px);
  padding:clamp(130px,12vh,170px) 0 80px var(--oa-frame-gutter);
}
.oa-hero h1 {
  max-width:8.5ch; margin:0; color:var(--hero-ink);
  font:650 clamp(3.3rem,4.6vw,4.8rem)/.94 var(--serif); letter-spacing:-.055em; text-wrap:balance;
  text-shadow:0 1px 18px color-mix(in srgb,var(--bg) 38%,transparent);
}
.oa-description {
  max-width:46ch; margin:28px 0 0; color:var(--hero-muted); font-size:.86rem; line-height:1.8;
  text-shadow:0 1px 12px color-mix(in srgb,var(--bg) 45%,transparent);
}
.oa-action {
  margin-top:24px; padding-bottom:0; border-bottom:0; line-height:1.4;
}
.oa-hero-list {
  position:absolute; bottom:35px; left:var(--oa-frame-gutter); z-index:3;
  width:min(44%,590px); border-top:1px solid color-mix(in srgb,var(--hero-ink) 38%,transparent);
}
.oa-hero-list a {
  display:grid; grid-template-columns:50px minmax(0,1fr); gap:15px; min-height:48px; padding:6px 0;
  border-bottom:1px solid color-mix(in srgb,var(--hero-ink) 26%,transparent); color:var(--hero-ink);
}
.oa-hero-list strong { color:var(--accent); font:500 .72rem var(--mono); }
.oa-hero-list b,.oa-hero-list small { display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.oa-hero-list b { font-size:.74rem; }.oa-hero-list small { margin-top:5px; color:var(--hero-muted); font-size:.6rem; }
.oa-feature {
  position:absolute; right:var(--oa-frame-gutter); bottom:35px; z-index:3;
  width:min(33%,430px); padding-top:15px; border-top:1px solid color-mix(in srgb,var(--hero-ink) 48%,transparent);
}
.oa-feature small,.oa-feature > a { color:var(--accent); font-size:.65rem; font-weight:700; }
.oa-feature h2 { margin:12px 0; font:650 clamp(1.5rem,2.5vw,2.6rem)/1.08 var(--serif); }
.oa-feature h2 a { color:var(--hero-ink); }
.oa-feature p { display:-webkit-box; overflow:hidden; margin:0 0 14px; color:var(--hero-muted); font-size:.68rem; line-height:1.55; -webkit-box-orient:vertical; -webkit-line-clamp:2; }
.oa-categories { padding:clamp(52px,7vw,90px) clamp(34px,6.3vw,90px) 0; }
.oa-categories nav { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); }
.oa-categories { width:100%; max-width:1440px; margin-inline:auto; }
.oa-categories nav > a {
  display:flex; flex-direction:column; min-height:178px; padding:25px;
  border-right:1px solid var(--line); color:var(--ink);
}
.oa-categories nav > a:first-child { padding-left:0; }
.oa-categories nav > a:last-child { border-right:0; }
.oa-categories nav strong { color:var(--accent); font:.75rem var(--mono); }
.oa-categories nav b { margin-top:18px; font:650 1.08rem var(--serif); }
.oa-categories nav span { margin-top:12px; color:var(--muted); font-size:.66rem; line-height:1.5; }
.oa-curation {
  display:grid; grid-template-columns:minmax(0,1.45fr) minmax(300px,.55fr); gap:clamp(50px,7vw,112px);
}
.oa-curation-articles > div { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); }
.oa-curation-articles article {
  min-height:210px; padding:24px; border-right:1px solid var(--line);
}
.oa-curation-articles article:first-child { padding-left:0; }
.oa-curation-articles article:last-child { border-right:0; }
.oa-curation-articles article > small { color:var(--accent); font:.65rem var(--mono); }
.oa-curation-articles h3 { margin:22px 0 12px; font:650 1.25rem/1.25 var(--serif); }
.oa-curation-articles h3 a { color:var(--ink); }
.oa-curation-articles p {
  display:-webkit-box; overflow:hidden; margin:0; color:var(--muted); font-size:.68rem; line-height:1.65;
  -webkit-box-orient:vertical; -webkit-line-clamp:3;
}
.oa-curation-links > a {
  display:grid; grid-template-columns:38px minmax(0,1fr); gap:14px; min-height:70px; padding:16px 0;
  border-bottom:1px solid var(--line); color:var(--ink);
}
.oa-curation-links > a > strong { color:var(--accent); font:500 .72rem var(--mono); }
.oa-curation-links b,.oa-curation-links small { display:block; }
.oa-curation-links small { margin-top:6px; color:var(--muted); font-size:.63rem; line-height:1.45; }

@media (max-width:1100px) {
  :is(.seamless-canvas-page,.night-corridor-page) { --media-frame-gutter:38px; }
  .sc-hero-copy,.nc-hero-copy,.oa-hero-copy { padding-left:38px; }
  .sc-hero h1,.nc-hero h1,.oa-hero h1 { font-size:clamp(3.35rem,5.4vw,4.8rem); }
  .oa-hero { min-height:880px; }
  .oa-hero h1 { font-size:clamp(3.3rem,5vw,4.4rem); }
  .nc-guide,.oa-feature { right:38px; }
  .oa-hero-list { left:38px; }
  .nc-guide { width:330px; }
  .sc-hero-index a,.nc-hero-index a { grid-template-columns:34px minmax(0,1fr); gap:10px; padding-inline:16px; }
  .sc-feature { gap:44px; }
}
@media (max-width:820px) {
  .sc-hero-index,.nc-hero-index { grid-template-columns:repeat(2,minmax(0,1fr)); position:relative; }
  .sc-hero-index a:nth-child(n),.nc-hero-index a:nth-child(n) { border-bottom:1px solid color-mix(in srgb,var(--hero-ink) 20%,transparent); }
  .sc-hero-index a:nth-child(2n),.nc-hero-index a:nth-child(2n) { border-right:0; }
  .sc-feature { grid-template-columns:1fr; gap:26px; }
  .sc-curation,.nc-curation,.oa-curation { grid-template-columns:1fr; gap:46px; }
  .sc-latest-row { grid-template-columns:48px minmax(0,1fr) 100px; }
  .sc-latest-row time { display:none; }
  .oa-categories nav { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .oa-categories nav > a:nth-child(n) { border-right:1px solid var(--line); border-bottom:1px solid var(--line); padding-left:20px; }
  .oa-categories nav > a:nth-child(2n) { border-right:0; }
}
@media (max-width:760px) {
  :is(
