    html:has(.night-corridor-page),
    html:has(.open-ascent-page)
  ) .ec-site-header .menu-toggle {
    display:grid; margin-left:auto; color:var(--hero-ink);
  }
  :is(
    html:has(.seamless-canvas-page),
    html:has(.night-corridor-page),
    html:has(.open-ascent-page)
  ) .ec-main-nav {
    position:absolute; top:58px; right:0; left:0; z-index:50; display:none; height:auto;
    padding:12px 18px; border-bottom:1px solid var(--line); background:var(--bg);
  }
  :is(
    html:has(.seamless-canvas-page),
    html:has(.night-corridor-page),
    html:has(.open-ascent-page)
  ) .ec-main-nav.open {
    display:flex; flex-direction:column;
  }
  :is(
    html:has(.seamless-canvas-page),
    html:has(.night-corridor-page),
    html:has(.open-ascent-page)
  ) .ec-main-nav a {
    min-height:42px; padding:0; color:var(--ink);
  }
  .seamless-canvas-page,.night-corridor-page,.open-ascent-page { min-width:0; }
  :is(.seamless-canvas-page,.night-corridor-page) { --media-frame-gutter:20px; }
  .sc-hero,.nc-hero,.oa-hero { min-height:auto; padding-top:58px; }
  .media-content-hero-anim,
  .oa-hero-media .media-content-hero-anim {
    inset:76px 20px auto 42%; height:390px; opacity:.52;
  }
  .nc-hero-media .media-content-hero-anim {
    inset:76px 20px auto 42%;
  }
  .sc-hero-copy,.nc-hero-copy,.oa-hero-copy {
    width:100%; min-height:520px; padding:82px 20px 48px;
  }
  .sc-hero h1,.nc-hero h1,.oa-hero h1 { max-width:9ch; font-size:clamp(3.25rem,14vw,5.1rem); }
  .sc-description,.nc-description,.oa-description { max-width:38ch; }
  .sc-hero-index,.nc-hero-index { min-height:0; background:color-mix(in srgb,var(--bg) 92%,transparent); }
  .nc-guide {
    position:relative; top:auto; right:auto; z-index:3; width:auto; margin:0 20px 34px;
  }
  .oa-hero-copy { min-height:500px; padding-bottom:54px; }
  .oa-hero-list,.oa-feature {
    position:relative; right:auto; bottom:auto; left:auto; width:auto; margin:0 20px;
  }
  .oa-feature { margin-top:38px; padding-bottom:36px; }
  .sc-feature,.sc-latest,.sc-curation,.nc-curation,.oa-categories,.oa-curation { padding-inline:20px; }
  .sc-latest-row { grid-template-columns:42px minmax(0,1fr); gap:14px; }
