@media (min-width: 901px) {
  :root:is([data-theme="atelier"], [data-theme="festival"]) .poster-cover-foot {
    width: min(58vw, 720px);
    max-width: none;
  }
  :root:is([data-theme="atelier"], [data-theme="festival"]) .poster-title {
    max-width: 9ch;
    font-size: clamp(3.6rem, 7.2vw, 7rem);
    line-height: .9;
  }
}
:root[data-theme="atelier"] .poster-scrim {
  background: linear-gradient(to top, rgba(12,12,12,.78), rgba(12,12,12,.18) 54%, rgba(12,12,12,.36));
}
