:root:is([data-theme="paperfilm"], [data-theme="azurefilm"]) .cin-scope,
:root:is([data-theme="paperfilm"], [data-theme="azurefilm"]) .cin-logline,
:root:is([data-theme="paperfilm"], [data-theme="azurefilm"]) .cin-cut,
:root:is([data-theme="paperfilm"], [data-theme="azurefilm"]) .cin-scenes,
