:root:is([data-theme="paperfilm"], [data-theme="azurefilm"]) .cin-scope-title,
:root:is([data-theme="paperfilm"], [data-theme="azurefilm"]) .cin-h1,
:root:is([data-theme="paperfilm"], [data-theme="azurefilm"]) .cin-scene-title { color: var(--ink); font-family: var(--serif); }

