  color-scheme: light; --bg: #f2f6f1; --surface: #ffffff; --ink: #22372a; --ink-soft: #405846;
  --muted: #708176; --faint: #9daaa1; --line: #d9e3da; --line-soft: #e9f0ea;
  --accent: #3f7248; --accent-soft: #db6b32; --accent-wash: #e0ece2; --radius: 6px;
  --code-bg: #edf4ee; --shadow: 0 7px 20px rgba(34,55,42,.07);
}
:root[data-theme="bluebook"] {
  color-scheme: light; --bg: #eaf2fb; --surface: #ffffff; --ink: #1b2f50; --ink-soft: #3c5374;
  --muted: #6e829c; --faint: #9babbc; --line: #d4e0ed; --line-soft: #e5edf6;
  --accent: #2b58ad; --accent-soft: #b73b38; --accent-wash: #dce7fa; --radius: 4px;
  --code-bg: #e7eff9; --shadow: 0 7px 20px rgba(27,47,80,.07);
}

/* almanac */
:root[data-theme="sunclock"] {
  color-scheme: light; --bg: #fff7cf; --surface: #fffdf3; --ink: #303247; --ink-soft: #505269;
  --muted: #7b7b8c; --faint: #a7a6b1; --line: #e3dba9; --line-soft: #f0e8bd;
  --accent: #c84a2f; --accent-soft: #293f76; --accent-wash: #f8dfd4; --radius: 10px;
  --shadow: 0 8px 22px rgba(75,66,34,.07);
}
:root[data-theme="seedcalendar"] {
  color-scheme: light; --bg: #edf4e8; --surface: #fbfdf8; --ink: #2c3b2b; --ink-soft: #4b5b49;
  --muted: #758173; --faint: #9faa9d; --line: #d6e1d1; --line-soft: #e6ede2;
  --accent: #4e7848; --accent-soft: #d05d52; --accent-wash: #dce9d8; --radius: 12px;
  --shadow: 0 8px 22px rgba(78,120,72,.07);
}

/* inbox */
:root[data-theme="postbox"] {
  color-scheme: light; --bg: #f3f5f8; --surface: #ffffff; --ink: #1b2a42; --ink-soft: #3c4d66;
  --muted: #6d7d92; --faint: #9aa7b6; --line: #d9e1ea; --line-soft: #e9eef4;
  --accent: #c53835; --accent-soft: #294e91; --accent-wash: #f5e1df; --radius: 8px;
  --shadow: 0 8px 24px rgba(27,42,66,.07);
}
:root[data-theme="airmail"] {
  color-scheme: light; --bg: #e9f4fb; --surface: #ffffff; --ink: #18344f; --ink-soft: #39546f;
  --muted: #6a8198; --faint: #98aaba; --line: #d1e0eb; --line-soft: #e3edf4;
  --accent: #3067b4; --accent-soft: #df6757; --accent-wash: #dce8f8; --radius: 12px;
  --shadow: 0 8px 24px rgba(48,103,180,.08);
}

/* catalog */
:root[data-theme="apothecary"] {
  color-scheme: light; --bg: #eaf5ef; --surface: #fbfffc; --ink: #1d382e; --ink-soft: #3c594e;
  --muted: #6e8179; --faint: #9ba9a3; --line: #d3e2da; --line-soft: #e4eee9;
  --accent: #30765b; --accent-soft: #df6754; --accent-wash: #dcebe3; --w-wide: 1240px;
  --radius: 12px; --shadow: 0 9px 28px rgba(48,118,91,.08);
}
:root[data-theme="toolroom"] {
  color-scheme: light; --bg: #eef1f5; --surface: #ffffff; --ink: #1b2a40; --ink-soft: #3d4e65;
  --muted: #6e7e92; --faint: #9ba7b6; --line: #d9dfe7; --line-soft: #e8ecf1;
  --accent: #2d61b5; --accent-soft: #e1732f; --accent-wash: #e0e9fa; --w-wide: 1240px;
  --radius: 6px; --shadow: 0 9px 28px rgba(45,97,181,.08);
}

/* broadcast */
:root[data-theme="publicradio"] {
  color-scheme: light; --bg: #f5f6f8; --surface: #ffffff; --ink: #182238; --ink-soft: #3a455d;
  --muted: #6c768a; --faint: #9aa2b1; --line: #dce1e8; --line-soft: #eceff3;
  --accent: #bf2e36; --accent-soft: #243d72; --accent-wash: #f4dfe1; --w-wide: 1180px;
  --radius: 4px; --shadow: 0 9px 28px rgba(24,34,56,.07);
}
:root[data-theme="morningfm"] {
  color-scheme: light; --bg: #eaf6fb; --surface: #ffffff; --ink: #173a42; --ink-soft: #365a62;
  --muted: #688189; --faint: #96a9ae; --line: #d1e3e8; --line-soft: #e2eff2;
  --accent: #1b8078; --accent-soft: #d5a318; --accent-wash: #d9efeb; --w-wide: 1180px;
  --radius: 18px; --shadow: 0 10px 30px rgba(27,128,120,.08);
}
:root[data-theme="morningfm"] .bc-play { background: #f0c63d; color: #173a42; }

/* exhibit */
:root[data-theme="whitecube"] {
  color-scheme: light; --bg: #f7f7f6; --surface: #ffffff; --ink: #1d1f22; --ink-soft: #404247;
  --muted: #74767a; --faint: #a1a2a5; --line: #dddddc; --line-soft: #ececeb;
  --accent: #b6312e; --accent-soft: #333f70; --accent-wash: #f2dfdd; --w-wide: 1320px;
  --radius: 0; --shadow: none;
}
:root[data-theme="botanical"] {
  color-scheme: light; --bg: #edf3ea; --surface: #fbfdf9; --ink: #263729; --ink-soft: #465a49;
  --muted: #718075; --faint: #9eaaa0; --line: #d6dfd2; --line-soft: #e6ece3;
  --accent: #3e7049; --accent-soft: #315fbd; --accent-wash: #dce8da; --w-wide: 1320px;
  --radius: 4px; --shadow: none;
}

/* ===== 联系方式与询盘（工厂/外贸站 P1）：全部吃主题 CSS 变量 ===== */
/* 询盘区块（product 详情页） */
.inquiry { margin: 2rem 0 1.4rem; padding: 1.25rem 1.35rem; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); }
.inquiry-title { margin: 0 0 .3rem; font-size: 1.12rem; color: var(--ink); }
.inquiry-note { margin: 0 0 .95rem; font-size: .92rem; color: var(--muted); }
.inquiry-actions { display: flex; flex-wrap: wrap; gap: .6rem; }
.inquiry-btn { display: inline-flex; align-items: center; gap: .45rem; padding: .55rem 1rem; border: 1px solid var(--line); border-radius: 999px; background: var(--surface); color: var(--ink); font: inherit; font-size: .92rem; text-decoration: none; cursor: pointer; transition: border-color .15s, color .15s, background .15s; }
.inquiry-btn:hover { border-color: var(--accent); color: var(--accent); }
.inquiry-btn.inquiry-wa { background: var(--accent); border-color: var(--accent); color: var(--surface); }
.inquiry-btn.inquiry-wa:hover { background: var(--accent-soft, var(--accent)); border-color: var(--accent-soft, var(--accent)); color: var(--surface); }

/* 右下角浮动联系按钮 + 面板 */
/* 层级在 .to-top(90) 之上：两者同占右下角，询盘按钮必须赢得点击 */
.contact-float { position: fixed; right: 1.1rem; bottom: 1.1rem; z-index: 91; display: flex; flex-direction: column; align-items: flex-end; gap: .6rem; }
.contact-float-btn { display: inline-flex; align-items: center; justify-content: center; width: 52px; height: 52px; border: 0; border-radius: 50%; background: var(--accent); color: var(--surface); cursor: pointer; box-shadow: 0 6px 18px color-mix(in srgb, var(--ink) 22%, transparent); transition: transform .15s, background .15s; }
.contact-float-btn:hover { transform: translateY(-1px); }
.contact-float .cf-ico-close { display: none; }
.contact-float.open .cf-ico-close { display: block; }
.contact-float.open .cf-ico-open { display: none; }
.contact-float-panel { display: none; min-width: 230px; max-width: 78vw; padding: .45rem; background: var(--surface); border: 1px solid var(--line); border-radius: calc(var(--radius) + 4px); box-shadow: 0 12px 32px color-mix(in srgb, var(--ink) 18%, transparent); }
.contact-float.open .contact-float-panel { display: block; }
.cf-item { display: flex; align-items: center; gap: .55rem; width: 100%; padding: .55rem .7rem; border: 0; border-radius: var(--radius); background: none; color: var(--ink); font: inherit; font-size: .9rem; text-align: left; text-decoration: none; cursor: pointer; }
.cf-item:hover { background: var(--line-soft, var(--line)); }
.cf-item svg { flex: none; color: var(--accent); }
.cf-item span { flex: none; font-weight: 550; }
.cf-item em { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-style: normal; color: var(--muted); font-size: .82rem; text-align: right; }

/* 微信二维码弹层（JS hidden 开关，不用 :target，避免页面跳动） */
.wechat-modal { position: fixed; inset: 0; z-index: 94; display: flex; align-items: center; justify-content: center; padding: 1.5rem; } /* 高于 contact-float(91)，低于 pd-lightbox(95) */
.wechat-modal[hidden] { display: none; }
.wechat-backdrop { position: absolute; inset: 0; border: 0; padding: 0; background: color-mix(in srgb, var(--ink) 45%, transparent); cursor: pointer; }
.wechat-card { position: relative; display: flex; flex-direction: column; align-items: center; gap: .7rem; padding: 1.6rem 1.6rem 1.25rem; background: var(--surface); border: 1px solid var(--line); border-radius: calc(var(--radius) + 4px); box-shadow: 0 18px 44px color-mix(in srgb, var(--ink) 26%, transparent); }
.wechat-card img { width: min(240px, 62vw); height: auto; border-radius: var(--radius); }
.wechat-card p { margin: 0; font-size: .9rem; color: var(--muted); }
.wechat-x { position: absolute; top: .5rem; right: .6rem; border: 0; background: none; color: var(--muted); font-size: 1.2rem; line-height: 1; padding: .25rem .4rem; cursor: pointer; border-radius: var(--radius); }
.wechat-x:hover { color: var(--ink); background: var(--line-soft, var(--line)); }
html.wechat-modal-open { overflow: hidden; }

/* ============================================================================
   FACTORY 工厂主题族（工厂/外贸站 P2）
   两骨架：factory-catalog（目录：hero 条 + 商品栅格 + 弱化文章区）
          factory-showcase（展台：大图 hero + 精选横排 + 工厂实力 + 动态）
   全部吃主题 CSS 变量；皮肤在文末以 :root[data-theme=...] 定义。
   ========================================================================== */

/* ---- factory-catalog 骨架（气质：专业密集——编号 eyebrow、2px 重分隔、紧凑栅格） ---- */
/* 容器规约：工厂骨架所有内容容器 = 站点标准容器 .wrap 的内容盒
   （max-width: var(--w-wide)，两侧 24px 留白）→ width: min(100% - 48px, var(--w-wide) - 48px)。
   绝不自造一套宽度：页眉 logo、内容区、页脚三条左缘在任何视口必须对齐。 */
[data-theme-layout="factory-catalog"] body { background: var(--bg); }
[data-theme-layout="factory-catalog"] .fc-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 2.2rem 0 4rem; }
[data-theme-layout="factory-catalog"] .fc-hero { position: relative; display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(300px, .75fr); gap: 0; border: 1px solid var(--line); background-color: var(--surface); background-image: repeating-linear-gradient(135deg, color-mix(in srgb, var(--ink) 3%, transparent) 0 1px, transparent 1px 16px); overflow: hidden; }
[data-theme-layout="factory-catalog"] .fc-hero::before,
[data-theme-layout="factory-catalog"] .fc-hero::after { content: ""; position: absolute; width: 18px; height: 18px; pointer-events: none; z-index: 1; }
[data-theme-layout="factory-catalog"] .fc-hero::before { top: 8px; left: 8px; border-top: 2px solid var(--accent); border-left: 2px solid var(--accent); }
[data-theme-layout="factory-catalog"] .fc-hero::after { right: 8px; bottom: 8px; border-bottom: 2px solid var(--accent); border-right: 2px solid var(--accent); }
[data-theme-layout="factory-catalog"] .fc-hero-copy { padding: clamp(2rem, 4.5vw, 3.6rem); border-right: 1px solid var(--line); }
[data-theme-layout="factory-catalog"] .fc-eyebrow { width: fit-content; margin: 0 0 1.1rem; padding: .3rem .6rem; background: var(--accent); color: #fff; font-family: var(--mono); font-size: .7rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }
[data-theme-layout="factory-catalog"] .fc-h1 { margin: 0; max-width: 16em; font-family: var(--sans); font-size: clamp(1.9rem, 4vw, 3rem); font-weight: 760; line-height: 1.12; letter-spacing: -.01em; }
[data-theme-layout="factory-catalog"] .fc-lede { max-width: 60ch; margin: 1rem 0 0; color: var(--muted); font-size: 1rem; line-height: 1.75; }
[data-theme-layout="factory-catalog"] .fc-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="factory-catalog"] .fc-hero-side { display: grid; align-content: center; padding: clamp(1.3rem, 2.4vw, 2rem); background: color-mix(in srgb, var(--surface) 55%, var(--line-soft)); }
[data-theme-layout="factory-catalog"] .fc-stats { grid-template-columns: 1fr 1fr; gap: .7rem; }
[data-theme-layout="factory-catalog"] .fc-stats .f-stat { padding: .95rem 1rem .85rem; }
[data-theme-layout="factory-catalog"] .fc-stats .f-stat dt { font-size: clamp(1.35rem, 2vw, 1.8rem); }
[data-theme-layout="factory-catalog"] .fc-section { padding-top: 3.2rem; }
[data-theme-layout="factory-catalog"] .fc-section-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem; margin-bottom: 1.2rem; padding-bottom: .8rem; border-bottom: 2px solid var(--ink); }
[data-theme-layout="factory-catalog"] .fc-section-head h2 { margin: 0; font-family: var(--sans); font-size: 1.45rem; font-weight: 750; }
[data-theme-layout="factory-catalog"] .fc-section-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-catalog"] .fc-section-head > a:hover { color: var(--accent); }
[data-theme-layout="factory-catalog"] .fc-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1rem; }
[data-theme-layout="factory-catalog"] .fc-card { display: flex; min-width: 0; flex-direction: column; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); overflow: hidden; transition: border-color var(--speed), transform var(--speed), box-shadow var(--speed); }
[data-theme-layout="factory-catalog"] .fc-card:hover { border-color: var(--accent); transform: translateY(-3px); box-shadow: 0 0 0 1px var(--accent), var(--shadow); color: var(--ink); }
[data-theme-layout="factory-catalog"] .fc-card-media { display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-catalog"] .fc-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
[data-theme-layout="factory-catalog"] .fc-card:hover .fc-card-media img { transform: scale(1.03); }
[data-theme-layout="factory-catalog"] .fc-card-gen b { font-family: var(--sans); font-size: 3rem; color: var(--accent); }
[data-theme-layout="factory-catalog"] .fc-card-body { display: flex; flex: 1; flex-direction: column; gap: .3rem; padding: .85rem .95rem 1rem; }
[data-theme-layout="factory-catalog"] .fc-card-cat { width: fit-content; color: var(--accent); font-family: var(--mono); font-size: .66rem; font-weight: 750; letter-spacing: .06em; text-transform: uppercase; }
[data-theme-layout="factory-catalog"] .fc-card-title { font-size: .98rem; font-weight: 700; line-height: 1.4; }
[data-theme-layout="factory-catalog"] .fc-card-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .8rem; line-height: 1.55; -webkit-box-orient: vertical; -webkit-line-clamp: 1; }
[data-theme-layout="factory-catalog"] .fc-empty { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center; }
[data-theme-layout="factory-catalog"] .fc-news-head { border-bottom-width: 1px; border-bottom-color: var(--line); }
[data-theme-layout="factory-catalog"] .fc-news-head h2 { font-size: 1.1rem; color: var(--ink-soft); }
[data-theme-layout="factory-catalog"] .fc-news-list { border-top: 0; }
[data-theme-layout="factory-catalog"] .fc-news-item { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem; padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .92rem; }
[data-theme-layout="factory-catalog"] .fc-news-item:hover { color: var(--accent); }
[data-theme-layout="factory-catalog"] .fc-news-item time { color: var(--faint); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-catalog"] .fc-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* ---- factory-showcase 骨架（气质：大气留白——eyebrow + 大标题、区块间距拉开） ---- */
[data-theme-layout="factory-showcase"] body { background: var(--bg); }
[data-theme-layout="factory-showcase"] .fs-wrap { padding-bottom: 4.5rem; }
[data-theme-layout="factory-showcase"] .fs-hero { position: relative; display: grid; align-items: center; min-height: clamp(420px, 56vh, 620px); padding: clamp(3rem, 8vw, 6rem) 0; background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 16%, var(--bg)), var(--bg) 55%, color-mix(in srgb, var(--accent) 7%, var(--bg))); border-bottom: 1px solid var(--line); overflow: hidden; }
[data-theme-layout="factory-showcase"] .fs-hero:not(.has-img)::before { content: ""; position: absolute; inset: 0; background-image: linear-gradient(color-mix(in srgb, var(--ink) 6%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in srgb, var(--ink) 6%, transparent) 1px, transparent 1px); background-size: 36px 36px; -webkit-mask-image: radial-gradient(120% 115% at 74% 36%, #000 28%, transparent 74%); mask-image: radial-gradient(120% 115% at 74% 36%, #000 28%, transparent 74%); pointer-events: none; }
[data-theme-layout="factory-showcase"] .fs-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="factory-showcase"] .fs-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, color-mix(in srgb, var(--bg) 88%, transparent) 0%, color-mix(in srgb, var(--bg) 55%, transparent) 55%, transparent 100%); }
[data-theme-layout="factory-showcase"] .fs-hero-inner { position: relative; z-index: 1; width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; }
/* hero 动画态（hero.visual=default）：文案 | 图纸机械动画 双栏；动画裸贴在自带网格纹理上 */
[data-theme-layout="factory-showcase"] .fs-hero.has-anim .fs-hero-inner { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, .9fr); align-items: center; gap: clamp(1.6rem, 4vw, 3.2rem); }
[data-theme-layout="factory-showcase"] .fs-hero-anim { justify-self: end; width: min(100%, 460px); }
[data-theme-layout="factory-showcase"] .fs-eyebrow { width: fit-content; margin: 0 0 1.2rem; color: var(--accent); font-family: var(--mono); font-size: .74rem; font-weight: 800; letter-spacing: .22em; text-transform: uppercase; }
[data-theme-layout="factory-showcase"] .fs-h1 { margin: 0; max-width: 14em; font-family: var(--sans); font-size: clamp(2.3rem, 5.5vw, 4.2rem); font-weight: 780; line-height: 1.06; letter-spacing: -.015em; }
[data-theme-layout="factory-showcase"] .fs-lede { max-width: 54ch; margin: 1.2rem 0 0; color: var(--ink-soft); font-size: 1.08rem; line-height: 1.75; }
[data-theme-layout="factory-showcase"] .fs-cta { display: flex; flex-wrap: wrap; gap: .75rem; margin-top: 2rem; }
[data-theme-layout="factory-showcase"] .fs-section, [data-theme-layout="factory-showcase"] .fs-strength { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding-top: clamp(3.6rem, 7vw, 4.6rem); }
[data-theme-layout="factory-showcase"] .fs-section-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem; margin-bottom: 1.7rem; }
[data-theme-layout="factory-showcase"] .fs-section-head h2 { margin: 0; font-family: var(--sans); font-size: clamp(1.6rem, 2.6vw, 1.95rem); font-weight: 780; letter-spacing: -.01em; }
[data-theme-layout="factory-showcase"] .fs-section-head > a { flex: none; color: var(--ink-soft); font-size: .88rem; }
[data-theme-layout="factory-showcase"] .fs-section-head > a:hover { color: var(--accent); }
[data-theme-layout="factory-showcase"] .fs-featured-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.4rem; }
[data-theme-layout="factory-showcase"] .fs-card { display: flex; min-width: 0; flex-direction: column; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); overflow: hidden; box-shadow: var(--shadow); transition: border-color var(--speed), transform var(--speed), box-shadow var(--speed); }
[data-theme-layout="factory-showcase"] .fs-card:hover { border-color: var(--accent); transform: translateY(-4px); box-shadow: 0 0 0 1px var(--accent), var(--shadow); color: var(--ink); }
[data-theme-layout="factory-showcase"] .fs-card-media { display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-showcase"] .fs-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="factory-showcase"] .fs-card:hover .fs-card-media img { transform: scale(1.035); }
[data-theme-layout="factory-showcase"] .fs-card-gen b { font-family: var(--sans); font-size: 4rem; color: var(--accent); }
[data-theme-layout="factory-showcase"] .fs-card-body { display: flex; flex: 1; flex-direction: column; gap: .4rem; padding: 1.15rem 1.25rem 1.3rem; }
[data-theme-layout="factory-showcase"] .fs-card-cat { width: fit-content; color: var(--accent); font-family: var(--mono); font-size: .68rem; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="factory-showcase"] .fs-card-title { font-size: 1.15rem; font-weight: 730; line-height: 1.35; }
[data-theme-layout="factory-showcase"] .fs-card-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .88rem; line-height: 1.6; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="factory-showcase"] .fs-card-go { margin-top: auto; padding-top: .8rem; color: var(--accent); font-size: .82rem; font-weight: 700; }
[data-theme-layout="factory-showcase"] .fs-empty { grid-column: 1 / -1; margin: 0; padding: 1.8rem; border: 1px dashed var(--line); border-radius: var(--radius); text-align: center; }
[data-theme-layout="factory-showcase"] .fs-strength { margin-top: clamp(3.6rem, 7vw, 4.6rem); padding: clamp(2.2rem, 4.5vw, 3.2rem) 0; background: var(--surface); border-block: 1px solid var(--line); width: 100%; }
[data-theme-layout="factory-showcase"] .fs-strength > * { width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto; }
[data-theme-layout="factory-showcase"] .fs-strength .fs-section-head { margin-bottom: 1.6rem; }
[data-theme-layout="factory-showcase"] .fs-stats { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.2rem; }
[data-theme-layout="factory-showcase"] .fs-strength .f-stat { background-color: var(--bg); }
[data-theme-layout="factory-showcase"] .fs-strength .f-certs { margin-top: 2.2rem; padding-top: 1.6rem; border-top: 1px dashed var(--line); }
[data-theme-layout="factory-showcase"] .fs-news-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.2rem; }
[data-theme-layout="factory-showcase"] .fs-news-card { display: flex; flex-direction: column; gap: .45rem; padding: 1.1rem 1.2rem 1.25rem; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); transition: border-color var(--speed); }
[data-theme-layout="factory-showcase"] .fs-news-card:hover { border-color: var(--accent); color: var(--ink); }
[data-theme-layout="factory-showcase"] .fs-news-card time { color: var(--faint); font-family: var(--mono); font-size: .72rem; }
[data-theme-layout="factory-showcase"] .fs-news-title { font-weight: 700; line-height: 1.45; }
[data-theme-layout="factory-showcase"] .fs-news-card:hover .fs-news-title { color: var(--accent); }
[data-theme-layout="factory-showcase"] .fs-news-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .84rem; line-height: 1.6; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }

/* ============================================================
   工厂骨架共用组件：eyebrow / 数字卡 / 关于我们拆分块 / 流程条 /
   认证章 / 规格 chip / CTA 通栏 —— 全吃主题变量，两骨架 8 皮通用
   ============================================================ */
/* 区块标题规约：小号英文 eyebrow（等宽字体 + 尾线，目录骨架带编号）+ 大标题 */
[data-theme-layout^="factory-"] .f-head-copy { min-width: 0; }
[data-theme-layout^="factory-"] .f-eyebrow { display: flex; align-items: center; gap: .6rem; margin: 0 0 .5rem; font-family: var(--mono); font-size: .68rem; font-weight: 800; letter-spacing: .2em; text-transform: uppercase; color: var(--accent); }
[data-theme-layout^="factory-"] .f-eyebrow::after { content: ""; flex: none; width: 34px; height: 2px; background: color-mix(in srgb, var(--accent) 40%, transparent); }
[data-theme-layout^="factory-"] .f-eyebrow > span { color: var(--faint); }

/* 大数字卡：超大等宽数字（强调色）+ 细标签 + 强调色角标 + 细网格纹理 */
/* 只清 block 向 margin（dl 的 UA 默认）；绝不写 margin: 0 —— 它与
   .fs-strength > * 的 margin-inline: auto 同特异度且靠后，会把展台骨架
   「工厂实力」数字卡带的居中打掉，整条 dl 贴死视口左缘（宽屏溢出事故）。 */
[data-theme-layout^="factory-"] .f-stats { display: grid; margin-block: 0; }
[data-theme-layout^="factory-"] .f-stat { position: relative; padding: 1.15rem 1.2rem 1.05rem; border: 1px solid var(--line); border-radius: 3px; background-color: var(--surface); background-image: linear-gradient(color-mix(in srgb, var(--ink) 4%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in srgb, var(--ink) 4%, transparent) 1px, transparent 1px); background-size: 16px 16px; }
[data-theme-layout^="factory-"] .f-stat::before,
[data-theme-layout^="factory-"] .f-stat::after { content: ""; position: absolute; width: 13px; height: 13px; pointer-events: none; }
[data-theme-layout^="factory-"] .f-stat::before { top: -1px; left: -1px; border-top: 2px solid var(--accent); border-left: 2px solid var(--accent); }
[data-theme-layout^="factory-"] .f-stat::after { right: -1px; bottom: -1px; border-bottom: 2px solid var(--accent); border-right: 2px solid var(--accent); }
[data-theme-layout^="factory-"] .f-stat dt { margin: 0; font-family: var(--mono); font-weight: 800; font-size: clamp(1.7rem, 3vw, 2.4rem); line-height: 1.05; letter-spacing: -.02em; color: var(--accent); font-variant-numeric: tabular-nums; }
[data-theme-layout^="factory-"] .f-stat dd { margin: .4rem 0 0; color: var(--muted); font-size: .72rem; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; }

/* 「关于我们」拆分块（工厂实力兜底）：装饰线 + 竖排大标题 + 限宽文案 + 淡图纸网格底纹 */
[data-theme-layout^="factory-"] .f-about { position: relative; display: flex; align-items: stretch; gap: 1.2rem; padding: clamp(1.4rem, 3vw, 2.2rem); border: 1px solid var(--line); border-radius: 3px; background-color: var(--surface); background-image: linear-gradient(color-mix(in srgb, var(--ink) 4%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in srgb, var(--ink) 4%, transparent) 1px, transparent 1px); background-size: 22px 22px; overflow: hidden; }
[data-theme-layout^="factory-"] .f-about::after { content: "···"; position: absolute; right: .4rem; bottom: -.95rem; font-family: var(--mono); font-weight: 800; font-size: 3.4rem; letter-spacing: .06em; color: color-mix(in srgb, var(--ink) 8%, transparent); pointer-events: none; user-select: none; }
[data-theme-layout^="factory-"] .f-about-rail { display: flex; flex: none; gap: .8rem; }
[data-theme-layout^="factory-"] .f-about-rail::before { content: ""; width: 3px; background: linear-gradient(180deg, var(--accent) 0 62%, color-mix(in srgb, var(--accent) 30%, transparent) 62%); }
[data-theme-layout^="factory-"] .f-about-title { margin: 0; writing-mode: vertical-rl; font-family: var(--sans); font-size: 1.3rem; font-weight: 800; letter-spacing: .38em; line-height: 1; color: var(--ink); }
[data-theme-layout^="factory-"] .f-about-copy { position: relative; align-self: center; margin: 0; max-width: 56ch; color: var(--ink-soft); font-size: .95rem; line-height: 1.85; }

/* 合作流程条：询盘→打样→量产→出货，编号大字 + 连接线（零配置渲染） */
[data-theme-layout^="factory-"] .f-process { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.2rem; margin: 0; padding: 0; list-style: none; }
[data-theme-layout^="factory-"] .f-step { position: relative; display: flex; flex-direction: column; min-width: 0; }
[data-theme-layout^="factory-"] .f-step::before { content: ""; position: absolute; top: 1rem; left: 0; right: 0; height: 2px; background: var(--line); }
[data-theme-layout^="factory-"] .f-step:last-child::before { background: linear-gradient(90deg, var(--line) 55%, transparent); }
[data-theme-layout^="factory-"] .f-step-num { position: relative; z-index: 1; width: fit-content; padding-right: .7rem; background: var(--bg); font-family: var(--mono); font-weight: 800; font-size: 2rem; line-height: 1; color: var(--accent); }
[data-theme-layout^="factory-"] .f-step-title { margin: .6rem 0 .2rem; font-size: 1.02rem; font-weight: 750; color: var(--ink); }
[data-theme-layout^="factory-"] .f-step-note { color: var(--muted); font-size: .82rem; line-height: 1.6; }

/* 分类入口卡区（零配置）：分类名 + 商品数 + 首个商品封面的横条卡 */
[data-theme-layout^="factory-"] .f-cats { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 1rem; }
[data-theme-layout^="factory-"] .f-cat-card { display: grid; grid-template-columns: 74px minmax(0, 1fr) auto; align-items: center; gap: .9rem; padding: .7rem .95rem .7rem .7rem; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); transition: border-color var(--speed), transform var(--speed); }
[data-theme-layout^="factory-"] .f-cat-card:hover { border-color: var(--accent); transform: translateY(-2px); color: var(--ink); }
[data-theme-layout^="factory-"] .f-cat-card:hover .arrow { color: var(--accent); }
[data-theme-layout^="factory-"] .f-cat-media { display: grid; place-items: center; width: 74px; aspect-ratio: 4 / 3; border-radius: 2px; background: var(--line-soft); overflow: hidden; }
[data-theme-layout^="factory-"] .f-cat-media img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout^="factory-"] .f-cat-gen b { font-family: var(--sans); font-size: 1.5rem; color: var(--accent); }
[data-theme-layout^="factory-"] .f-cat-body { display: flex; min-width: 0; flex-direction: column; gap: .2rem; }
[data-theme-layout^="factory-"] .f-cat-name { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-size: .98rem; font-weight: 720; }
[data-theme-layout^="factory-"] .f-cat-count { color: var(--muted); font-family: var(--mono); font-size: .7rem; letter-spacing: .04em; }
[data-theme-layout^="factory-"] .f-cat-card .arrow { color: var(--faint); }

/* 应用行业条：行业名 + 一句话的小卡（左缘强调条，工业标签气质） */
[data-theme-layout^="factory-"] .f-industries { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: .9rem; margin: 0; padding: 0; list-style: none; }
[data-theme-layout^="factory-"] .f-industry { position: relative; display: flex; flex-direction: column; gap: .25rem; min-width: 0; padding: .85rem 1rem .8rem 1.05rem; border: 1px solid var(--line); border-radius: 2px; background: var(--surface); }
[data-theme-layout^="factory-"] .f-industry::before { content: ""; position: absolute; top: -1px; bottom: -1px; left: -1px; width: 3px; background: linear-gradient(180deg, var(--accent) 0 58%, color-mix(in srgb, var(--accent) 30%, transparent) 58%); }
[data-theme-layout^="factory-"] .f-industry-name { font-size: .95rem; font-weight: 720; color: var(--ink); }
[data-theme-layout^="factory-"] .f-industry-note { color: var(--muted); font-size: .8rem; line-height: 1.55; }

/* 工厂图集「车间与设备」：横向滚动图带（scroll-snap；未配置整块不渲染，绝不占位假照片） */
[data-theme-layout^="factory-"] .f-gallery { display: flex; gap: .9rem; padding-bottom: .6rem; overflow-x: auto; scroll-snap-type: x proximity; scrollbar-width: thin; }
[data-theme-layout^="factory-"] .f-gallery-item { flex: none; margin: 0; scroll-snap-align: start; border: 1px solid var(--line); border-radius: var(--radius); background: var(--line-soft); overflow: hidden; }
[data-theme-layout^="factory-"] .f-gallery-item img { display: block; height: clamp(180px, 24vw, 260px); width: auto; max-width: 78vw; object-fit: cover; }

/* FAQ 手风琴：原生 details/summary，等宽 Q 记号 + 折角箭头（site.js 渐进增强为互斥展开） */
[data-theme-layout^="factory-"] .f-faq { border-top: 2px solid var(--ink); }
[data-theme-layout^="factory-"] .f-faq-item { border-bottom: 1px solid var(--line); }
[data-theme-layout^="factory-"] .f-faq-q { display: flex; align-items: baseline; gap: .75rem; padding: .95rem .2rem; font-size: .98rem; font-weight: 700; color: var(--ink); cursor: pointer; list-style: none; }
[data-theme-layout^="factory-"] .f-faq-q::-webkit-details-marker { display: none; }
[data-theme-layout^="factory-"] .f-faq-q:hover { color: var(--accent); }
[data-theme-layout^="factory-"] .f-faq-marker { flex: none; font-family: var(--mono); font-size: .72rem; font-weight: 800; color: var(--accent); }
[data-theme-layout^="factory-"] .f-faq-caret { flex: none; margin-left: auto; align-self: center; width: 8px; height: 8px; border-right: 2px solid var(--faint); border-bottom: 2px solid var(--faint); transform: rotate(45deg); transition: transform var(--speed); }
[data-theme-layout^="factory-"] .f-faq-item[open] .f-faq-caret { transform: rotate(-135deg); }
[data-theme-layout^="factory-"] .f-faq-a { margin: 0; padding: 0 .2rem 1.05rem 2.15rem; max-width: 78ch; color: var(--muted); font-size: .9rem; line-height: 1.75; }

/* 认证徽章条：纯 CSS 文字图章（双线框 + 轻微错位角度） */
[data-theme-layout^="factory-"] .f-certs { display: flex; flex-wrap: wrap; align-items: center; gap: .9rem 1.1rem; }
[data-theme-layout^="factory-"] .f-certs-label { margin-right: .3rem; font-family: var(--mono); font-size: .68rem; font-weight: 800; letter-spacing: .18em; text-transform: uppercase; color: var(--muted); }
[data-theme-layout^="factory-"] .f-cert { display: inline-flex; flex-direction: column; align-items: center; gap: .1rem; margin: 3px; padding: .5rem .95rem .45rem; border: 1px solid color-mix(in srgb, var(--ink) 45%, transparent); border-radius: 2px; outline: 1px solid color-mix(in srgb, var(--ink) 28%, transparent); outline-offset: 2px; color: var(--ink-soft); }
[data-theme-layout^="factory-"] .f-cert:nth-child(odd) { transform: rotate(-.8deg); }
[data-theme-layout^="factory-"] .f-cert:nth-child(even) { transform: rotate(.6deg); }
[data-theme-layout^="factory-"] .f-cert b { font-family: var(--mono); font-size: .92rem; font-weight: 800; letter-spacing: .05em; line-height: 1.1; }
[data-theme-layout^="factory-"] .f-cert i { font-style: normal; font-size: .54rem; letter-spacing: .26em; text-transform: uppercase; color: var(--muted); }

/* 规格 chip：商品卡上从 specs 嗅探的材质/起订量（最多 2 个，没有不显示） */
[data-theme-layout^="factory-"] .f-chips { display: flex; flex-wrap: wrap; gap: .3rem; margin-top: .5rem; min-width: 0; }
[data-theme-layout^="factory-"] .f-chip { display: inline-flex; align-items: center; gap: .35rem; min-width: 0; max-width: 100%; padding: .16rem .45rem; border: 1px solid var(--line); border-radius: 2px; background: color-mix(in srgb, var(--line-soft) 60%, transparent); font-family: var(--mono); font-size: .64rem; line-height: 1.5; color: var(--ink-soft); }
[data-theme-layout^="factory-"] .f-chip b { flex: none; font-weight: 650; color: var(--muted); }
[data-theme-layout^="factory-"] .f-chip i { font-style: normal; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* CTA 通栏：页脚前「获取报价」反色大字带 + 斜纹肌理（hero 联系 CTA 锚到 #factory-contact） */
[data-theme-layout^="factory-"] .f-cta { position: relative; padding: clamp(2.4rem, 6vw, 3.6rem) 0; background: var(--ink); color: var(--bg); overflow: hidden; scroll-margin-top: 84px; }
[data-theme-layout^="factory-"] .f-cta::before { content: ""; position: absolute; inset: 0; background-image: repeating-linear-gradient(135deg, color-mix(in srgb, var(--bg) 7%, transparent) 0 1px, transparent 1px 13px); pointer-events: none; }
[data-theme-layout^="factory-"] .f-cta-inner { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 1.4rem 2.5rem; width: min(100% - 48px, var(--w-wide, 1200px) - 48px); margin: 0 auto; }
[data-theme-layout^="factory-"] .f-cta .f-eyebrow { color: color-mix(in srgb, var(--accent) 60%, var(--bg)); }
[data-theme-layout^="factory-"] .f-cta .f-eyebrow::after { background: color-mix(in srgb, var(--accent) 40%, var(--bg)); }
[data-theme-layout^="factory-"] .f-cta h2 { margin: 0; font-family: var(--sans); font-size: clamp(1.7rem, 4vw, 2.6rem); font-weight: 800; letter-spacing: -.01em; line-height: 1.15; color: var(--bg); }
[data-theme-layout^="factory-"] .f-cta-note { margin: .6rem 0 0; max-width: 54ch; color: color-mix(in srgb, var(--bg) 72%, transparent); font-size: .95rem; line-height: 1.7; }
[data-theme-layout^="factory-"] .f-cta-actions { justify-content: flex-end; }
[data-theme-layout^="factory-"] .f-cta .inquiry-btn { border-color: transparent; }

/* 联系/询盘主按钮的悬停态：全局默认换 accent-soft 底，在工厂族的十来张浅皮上
   白字只剩 3.1~4.3:1（36 皮对比度抽查结论）。工厂族内统一改为「底色不变，
   悬停加 accent 光圈 + 上浮」——静息态配色已全数 ≥4.5:1，悬停不再降级。 */
[data-theme-layout^="factory-"] .btn-primary:hover { background: var(--accent); border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 28%, transparent); }
[data-theme-layout^="factory-"] .inquiry-btn.inquiry-wa:hover { background: var(--accent); border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 28%, transparent); }

/* HERO 默认动画（hero.visual=default/anim*）：工厂风变体——图纸网格底（容器画）
   + SVG 运转齿轮 / 流水线传送带 / 尺寸标注线（templates 的 factory_hero_anim define）。
   内容主题的 hv2 动画讲「数据库→芯片→页面」，放工厂站气质违和，这里换成机械叙事；
   纯 CSS 动画零 JS，配色全吃主题变量，prefers-reduced-motion 时全部静止。
   容器形态：默认=图纸网格底卡（叠在各骨架的 media 边框卡里）；.f-heroanim-plain=
   去底裸贴（展台骨架 hero 自带网格纹理，不再双重画格）。 */
/* 容器一律 <div>：type 选择器把特异度抬到 (0,2,1)，压过后文各骨架 media 卡
   （.fo-hero-media 等）的 background: var(--line-soft) 平级覆盖 */
[data-theme-layout^="factory-"] div.f-heroanim { position: relative; display: grid; place-items: center; min-height: 200px; background-color: color-mix(in srgb, var(--accent) 5%, var(--surface)); background-image: linear-gradient(color-mix(in srgb, var(--accent) 14%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in srgb, var(--accent) 14%, transparent) 1px, transparent 1px), linear-gradient(color-mix(in srgb, var(--accent) 7%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in srgb, var(--accent) 7%, transparent) 1px, transparent 1px); background-size: 72px 72px, 72px 72px, 18px 18px, 18px 18px; overflow: hidden; }
[data-theme-layout^="factory-"] div.f-heroanim-plain { background: none; min-height: 0; overflow: visible; }
[data-theme-layout^="factory-"] .factory-hero-slot {
  position: relative;
  width: 100%;
  min-width: 0;
  min-height: clamp(190px, 24vw, 330px);
  overflow: hidden;
  background: transparent;
}
[data-theme-layout^="factory-"] .factory-hero-slot > img,
[data-theme-layout^="factory-"] .factory-hero-slot-svg,
[data-theme-layout^="factory-"] .factory-hero-slot-svg > svg,
[data-theme-layout^="factory-"] .factory-hero-slot > .f-heroanim {
  display: block;
  width: 100%;
  height: 100%;
  min-height: inherit;
}
[data-theme-layout^="factory-"] .factory-hero-slot > img { object-fit: cover; }
[data-theme-layout^="factory-"] .factory-hero-slot-svg > svg { max-width: 100%; object-fit: contain; }
[data-theme-layout^="factory-"] .factory-hero-slot.is-image,
[data-theme-layout^="factory-"] .factory-hero-slot.is-svg { background: transparent; }
[data-theme-layout^="factory-"] .factory-hero-slot > .f-heroanim { place-items: center; }
[data-theme-layout^="factory-"] .f-heroanim .f-animsvg { display: block; width: min(100%, 480px); height: auto; max-height: 100%; }
[data-theme-layout^="factory-"] .f-heroanim .fa-cross path { stroke: var(--accent); stroke-width: 1.6; stroke-linecap: round; opacity: .4; }
[data-theme-layout^="factory-"] .f-heroanim .fa-dim line { stroke: var(--muted); stroke-width: 1.4; stroke-linecap: round; opacity: .55; }
/* 大齿轮：齿圈=粗描边虚线圆（弧段即齿），体盘垫底色让格线不透穿 */
[data-theme-layout^="factory-"] .f-heroanim .fa-body { fill: color-mix(in srgb, var(--surface) 88%, transparent); stroke: var(--accent); stroke-width: 3; }
[data-theme-layout^="factory-"] .f-heroanim .fa-teeth { fill: none; stroke: var(--accent); stroke-width: 15; stroke-dasharray: 17 16.5; opacity: .9; }
[data-theme-layout^="factory-"] .f-heroanim .fa-ring { fill: none; stroke: var(--accent); stroke-width: 2.5; opacity: .8; }
[data-theme-layout^="factory-"] .f-heroanim .fa-spokes line { stroke: var(--accent); stroke-width: 3; stroke-linecap: round; opacity: .65; }
[data-theme-layout^="factory-"] .f-heroanim .fa-hub { fill: var(--accent); }
/* 小齿轮：ink 系降一档，别跟大齿轮抢 */
[data-theme-layout^="factory-"] .f-heroanim .fa-gear-small .fa-body { stroke: color-mix(in srgb, var(--ink) 55%, transparent); stroke-width: 2.5; }
[data-theme-layout^="factory-"] .f-heroanim .fa-gear-small .fa-teeth { stroke: color-mix(in srgb, var(--ink) 55%, transparent); stroke-width: 11; stroke-dasharray: 12 11.7; opacity: 1; }
[data-theme-layout^="factory-"] .f-heroanim .fa-gear-small .fa-hub { fill: color-mix(in srgb, var(--ink) 60%, transparent); }
/* 流水线：带体实底 + 外沿虚线循环（履带转动），滚轮/托辊、货箱（accent 封箱带） */
[data-theme-layout^="factory-"] .f-heroanim .fa-belt { fill: color-mix(in srgb, var(--surface) 90%, transparent); stroke: color-mix(in srgb, var(--ink) 55%, transparent); stroke-width: 2; }
[data-theme-layout^="factory-"] .f-heroanim .fa-belt-line { fill: none; stroke: color-mix(in srgb, var(--ink) 40%, transparent); stroke-width: 2; stroke-dasharray: 7 6; }
[data-theme-layout^="factory-"] .f-heroanim .fa-roller { fill: var(--surface); stroke: color-mix(in srgb, var(--ink) 55%, transparent); stroke-width: 2; }
[data-theme-layout^="factory-"] .f-heroanim .fa-dot { fill: color-mix(in srgb, var(--ink) 30%, transparent); }
[data-theme-layout^="factory-"] .f-heroanim .fa-box rect { fill: var(--surface); stroke: color-mix(in srgb, var(--ink) 50%, transparent); stroke-width: 2; }
[data-theme-layout^="factory-"] .f-heroanim .fa-box line { stroke: var(--accent); stroke-width: 3; opacity: .85; }
/* 运转：齿轮对转、履带循环、货箱左进右出（裁切区内平移） */
[data-theme-layout^="factory-"] .f-heroanim .fa-gear-big { transform-origin: 170px 150px; animation: faGearSpin 18s linear infinite; }
[data-theme-layout^="factory-"] .f-heroanim .fa-gear-small { transform-origin: 268px 102px; animation: faGearSpinBack 11s linear infinite; }
[data-theme-layout^="factory-"] .f-heroanim .fa-belt-line { animation: faBeltMove 1.2s linear infinite; }
[data-theme-layout^="factory-"] .f-heroanim .fa-box { animation: faBoxRun 9s linear infinite; }
[data-theme-layout^="factory-"] .f-heroanim .fa-box.b2 { animation-delay: -4.5s; }
@keyframes faGearSpin { to { transform: rotate(360deg); } }
@keyframes faGearSpinBack { to { transform: rotate(-360deg); } }
@keyframes faBeltMove { to { stroke-dashoffset: -26; } }
@keyframes faBoxRun { from { transform: translateX(-90px); } to { transform: translateX(350px); } }
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout^="factory-"] .f-heroanim .fa-gear-big,
  [data-theme-layout^="factory-"] .f-heroanim .fa-gear-small,
  [data-theme-layout^="factory-"] .f-heroanim .fa-belt-line,
  [data-theme-layout^="factory-"] .f-heroanim .fa-box { animation: none; }
  [data-theme-layout^="factory-"] .f-heroanim .fa-box { transform: translateX(60px); }
  [data-theme-layout^="factory-"] .f-heroanim .fa-box.b2 { transform: translateX(210px); }
}

/* ---- 工厂骨架共用：列表/归档页收紧成商品栅格气质 ---- */
[data-theme-layout^="factory-"] .page-head { padding: 2.6rem 0 1.8rem; }
[data-theme-layout^="factory-"] .cat-nav { margin: 1.4rem 0; }
[data-theme-layout^="factory-"] .cat-nav a { border-radius: calc(var(--radius) * .6); }
[data-theme-layout^="factory-"] .link-grid { grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 1rem; }
[data-theme-layout^="factory-"] .lc-cover { aspect-ratio: 4 / 3; }
[data-theme-layout^="factory-"] .lc-body { padding: .85rem .95rem 1rem; gap: .35rem; }
[data-theme-layout^="factory-"] .lc-title { font-size: .98rem; font-family: var(--sans); font-weight: 700; }
[data-theme-layout^="factory-"] .lc-intro { font-size: .82rem; display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout^="factory-"] h1, [data-theme-layout^="factory-"] h2,
[data-theme-layout^="factory-"] h3, [data-theme-layout^="factory-"] h4 { font-family: var(--sans); }

/* ---- 商品详情（工厂骨架专属模板 product_detail）---- */
.pd-main { padding-bottom: 4rem; }
.pd-bc { padding-bottom: 1.4rem; }
.pd-top { display: grid; grid-template-columns: minmax(0, 1.02fr) minmax(0, .98fr); gap: clamp(1.6rem, 4vw, 3rem); align-items: start; }
.pd-gallery { min-width: 0; }
.pd-media { display: grid; place-items: center; aspect-ratio: 4 / 3; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); overflow: hidden; cursor: zoom-in; }
.pd-media img { width: 100%; height: 100%; object-fit: contain; }
.pd-media-gen { cursor: default; background: var(--line-soft); }
.pd-media-gen b { font-family: var(--sans); font-size: clamp(4rem, 9vw, 7rem); color: var(--accent); }
.pd-thumbs { display: grid; grid-template-columns: repeat(auto-fill, minmax(74px, 1fr)); gap: .55rem; margin-top: .65rem; }
.pd-thumb { display: grid; place-items: center; aspect-ratio: 1; padding: 0; border: 1px solid var(--line); border-radius: calc(var(--radius) * .7); background: var(--surface); overflow: hidden; cursor: pointer; transition: border-color var(--speed); }
.pd-thumb img { width: 100%; height: 100%; object-fit: cover; }
.pd-thumb:hover { border-color: var(--accent-soft); }
.pd-thumb.is-active { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
.pd-info { min-width: 0; }
.pd-kicker { margin: 0 0 .6rem; font-family: var(--mono); font-size: .72rem; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; }
.pd-kicker a { color: var(--accent); }
.pd-title { margin: 0 0 .7rem; font-size: clamp(1.5rem, 3vw, 2.2rem); line-height: 1.2; }
.pd-lead { margin: 0 0 1.1rem; color: var(--muted); font-size: 1.02rem; line-height: 1.7; }
.pd-meta { margin: 0 0 1.2rem; border-top: 1px solid var(--line); }
.pd-meta-row { display: grid; grid-template-columns: minmax(6.5rem, auto) minmax(0, 1fr); gap: 1rem; padding: .55rem 0; border-bottom: 1px solid var(--line-soft); font-size: .92rem; }
.pd-meta-row dt { margin: 0; color: var(--muted); }
.pd-meta-row dd { margin: 0; color: var(--ink); font-weight: 550; overflow-wrap: anywhere; }
.pd-inquiry { margin: 0; }
.pd-sec-title { margin: 0 0 1rem; font-size: 1.25rem; }
.pd-specs, .pd-desc, .pd-related { margin-top: 2.6rem; }
.pd-specs-tablewrap { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
.pd-specs-table { width: 100%; border-collapse: collapse; font-size: .92rem; }
.pd-specs-table th, .pd-specs-table td { padding: .65rem 1rem; border-bottom: 1px solid var(--line-soft); text-align: left; vertical-align: top; }
.pd-specs-table tr:last-child th, .pd-specs-table tr:last-child td { border-bottom: 0; }
.pd-specs-table th { width: 32%; min-width: 9rem; color: var(--muted); font-weight: 550; background: color-mix(in srgb, var(--line-soft) 55%, transparent); }
.pd-specs-table td { color: var(--ink); }
/* 标题与「查看全部」按文字基线对齐（flex-end 会把 h2 的下 margin 算进对齐盒，链接被压低一截） */
.pd-related-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; margin-bottom: 1rem; }
.pd-related-head .pd-sec-title { margin-bottom: 0; }
.pd-related-head > a { color: var(--ink-soft); font-size: .86rem; }
.pd-related-head > a:hover { color: var(--accent); }
.pd-rel-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1rem; }
.pd-rel-card { display: flex; min-width: 0; flex-direction: column; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); overflow: hidden; transition: border-color var(--speed), transform var(--speed); }
.pd-rel-card:hover { border-color: var(--accent); transform: translateY(-2px); color: var(--ink); }
.pd-rel-media { display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
.pd-rel-media img { width: 100%; height: 100%; object-fit: cover; }
.pd-rel-gen b { font-family: var(--sans); font-size: 2.4rem; color: var(--accent); }
.pd-rel-title { padding: .75rem .9rem .9rem; font-size: .92rem; font-weight: 700; line-height: 1.4; }

/* 图集灯箱（JS class/hidden 开关，绝不用 :target） */
.pd-lightbox { position: fixed; inset: 0; z-index: 95; display: flex; align-items: center; justify-content: center; padding: clamp(1rem, 4vw, 3rem); }
.pd-lightbox[hidden] { display: none; }
.pd-lightbox-backdrop { position: absolute; inset: 0; border: 0; padding: 0; background: color-mix(in srgb, var(--ink) 62%, transparent); cursor: zoom-out; }
.pd-lightbox-figure { position: relative; margin: 0; max-width: min(1100px, 94vw); max-height: 90vh; }
.pd-lightbox-figure img { max-width: 100%; max-height: 90vh; width: auto; height: auto; display: block; border-radius: var(--radius); background: var(--surface); box-shadow: 0 24px 70px rgba(0,0,0,.4); }
.pd-lightbox-x { position: absolute; top: -.6rem; right: -.6rem; z-index: 1; width: 34px; height: 34px; display: grid; place-items: center; border: 0; border-radius: 50%; background: var(--surface); color: var(--ink); font-size: 1.15rem; line-height: 1; cursor: pointer; box-shadow: 0 4px 14px rgba(0,0,0,.3); }
.pd-lightbox-x:hover { color: var(--accent); }
html.pd-lightbox-open { overflow: hidden; }

/* ---- 工厂骨架响应式 ---- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-catalog"] .fc-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .pd-rel-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 900px) {
  [data-theme-layout="factory-catalog"] .fc-hero { grid-template-columns: 1fr; }
  [data-theme-layout="factory-catalog"] .fc-hero-copy { border-right: 0; border-bottom: 1px solid var(--line); }
  [data-theme-layout="factory-showcase"] .fs-featured-row,
  [data-theme-layout="factory-showcase"] .fs-news-row { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-showcase"] .fs-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  /* hero 动画态：窄屏收回单列并藏动画（大字陈述优先，纹理仍在）。
     div 前缀对齐基础规则 div.f-heroanim 的特异度，否则藏不掉。 */
  [data-theme-layout="factory-showcase"] .fs-hero.has-anim .fs-hero-inner { grid-template-columns: 1fr; }
  [data-theme-layout="factory-showcase"] div.fs-hero-anim { display: none; }
  [data-theme-layout^="factory-"] .f-process { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.4rem 1rem; }
  [data-theme-layout^="factory-"] .f-cta-inner { grid-template-columns: 1fr; }
  [data-theme-layout^="factory-"] .f-cta-actions { justify-content: flex-start; }
  .pd-top { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  /* 宽度不再单独覆盖：统一走「min(100% - 48px, var(--w-wide) - 48px)」容器规约，
     保证窄屏下内容区与页眉/页脚（.wrap 两侧 24px）左缘依旧对齐。 */
  [data-theme-layout="factory-catalog"] .fc-wrap { padding-top: 1.2rem; }
  [data-theme-layout="factory-catalog"] .fc-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .7rem; }
  [data-theme-layout="factory-catalog"] .fc-card-ex { display: none; }
  [data-theme-layout="factory-catalog"] .fc-card .f-chips { display: none; }
  [data-theme-layout="factory-showcase"] .fs-featured-row,
  [data-theme-layout="factory-showcase"] .fs-news-row { grid-template-columns: 1fr; }
  [data-theme-layout="factory-showcase"] .fs-stats { gap: .7rem; }
  [data-theme-layout^="factory-"] .f-process { gap: 1.2rem .9rem; }
  [data-theme-layout^="factory-"] .f-step-num { font-size: 1.6rem; }
  [data-theme-layout^="factory-"] .f-step::before { top: .8rem; }
  [data-theme-layout^="factory-"] .f-about { gap: 1rem; padding: 1.2rem 1.1rem; }
  [data-theme-layout^="factory-"] .f-cats { grid-template-columns: 1fr; gap: .7rem; }
  [data-theme-layout^="factory-"] .f-industries { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .7rem; }
  [data-theme-layout^="factory-"] .f-gallery-item img { height: 160px; }
  [data-theme-layout^="factory-"] .f-faq-a { padding-left: 1.9rem; }
  .pd-thumbs { grid-template-columns: repeat(auto-fill, minmax(60px, 1fr)); }
  .pd-rel-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .7rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout^="factory-"] .fc-card, [data-theme-layout^="factory-"] .fc-card-media img,
  [data-theme-layout^="factory-"] .fs-card, [data-theme-layout^="factory-"] .fs-card-media img,
  [data-theme-layout^="factory-"] .f-cat-card, [data-theme-layout^="factory-"] .f-faq-caret,
  .pd-rel-card, .pd-thumb { transition: none; }
}

/* ---- 工厂皮肤 ×8（Category=factory；4 皮 × factory-catalog + 4 皮 × factory-showcase） ---- */
/* 工业蓝 · Industrial：钢青蓝 + 冷白车间底，直角硬边 */
:root[data-theme="industrial"] {
  --bg: #f2f4f6; --surface: #ffffff; --ink: #16232e; --ink-soft: #35444f;
  --muted: #64727e; --faint: #93a0aa; --line: #d5dce2; --line-soft: #e6ebef;
  --accent: #1f5e8f; --accent-soft: #3679ac; --accent-wash: #e3eef6; --w-wide: 1280px;
  --radius: 2px; --shadow: 0 6px 22px rgba(22,35,46,.07);
}
:root[data-theme="industrial"] .site-header { background: color-mix(in srgb, var(--surface) 88%, transparent); border-bottom: 2px solid var(--ink); }

/* 机械灰 · Machinist：石墨灰 + 安全橙信号 */
:root[data-theme="machinist"] {
  --bg: #eceef0; --surface: #f9fafb; --ink: #1d2126; --ink-soft: #3c434b;
  --muted: #6b7480; --faint: #98a0ab; --line: #d0d5db; --line-soft: #e0e4e9;
  --accent: #e0611f; --accent-soft: #f07a38; --accent-wash: #fbeadf; --w-wide: 1280px;
  --radius: 2px; --shadow: 0 6px 20px rgba(29,33,38,.08);
}
:root[data-theme="machinist"] .site-header { border-bottom: 2px solid var(--accent); }
/* 安全橙上白字只有 3.5:1（联系/询盘钮首当其冲）：橙底改深字，同暗皮「亮强调配深字」惯例 */
:root[data-theme="machinist"] .btn-primary { color: #16130f; }
:root[data-theme="machinist"] .inquiry-btn.inquiry-wa { color: #16130f; }

/* 外贸绿 · Tradewind：米白纸底 + 深松绿 */
:root[data-theme="tradewind"] {
  --bg: #f7f6f0; --surface: #fffefa; --ink: #1e2a24; --ink-soft: #3d4b43;
  --muted: #6e7a72; --faint: #9aa59d; --line: #dcdad0; --line-soft: #eae8df;
  --accent: #2f6b4f; --accent-soft: #468a69; --accent-wash: #e4efe8; --w-wide: 1280px;
  --radius: 6px; --shadow: 0 8px 24px rgba(30,42,36,.07);
}

/* 铸坊 · Foundry：近黑展墙 + 熔铸琥珀（深色展厅，目录骨架） */
:root[data-theme="foundry"] {
  --bg: #141110; --surface: #1d1917; --ink: #f1ece4; --ink-soft: #d3ccc1;
  --muted: #9d968b; --faint: #6c665d; --line: #383129; --line-soft: #262019;
  --accent: #e8983d; --accent-soft: #f4b164; --accent-wash: #3a2a15; --code-bg: #0b0908;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 14px 40px rgba(0,0,0,.45);
}
:root[data-theme="foundry"] .btn-primary { color: #16100a; }
:root[data-theme="foundry"] .fc-eyebrow { color: #16100a; }
:root[data-theme="foundry"] .site-header { background: rgba(20,17,16,.88); }
:root[data-theme="foundry"] .fc-card-media { box-shadow: inset 0 0 34px rgba(232,152,61,.05); }
:root[data-theme="foundry"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #16100a; }

/* 展销 · Showroom：亮白展厅 + 工业蓝（展台骨架原生皮） */
:root[data-theme="showroom"] {
  --bg: #fafbfc; --surface: #ffffff; --ink: #17222c; --ink-soft: #36424d;
  --muted: #66727e; --faint: #94a0ab; --line: #dee3e9; --line-soft: #ecf0f4;
  --accent: #2563b0; --accent-soft: #3f7dc9; --accent-wash: #e6eef8; --w-wide: 1200px;
  --radius: 6px; --shadow: 0 10px 30px rgba(23,34,44,.07);
}

/* 装配 · Assembly：浅钢灰 + 安全橙（展台骨架产线皮） */
:root[data-theme="assembly"] {
  --bg: #f0f1f3; --surface: #fbfbfc; --ink: #21252b; --ink-soft: #414750;
  --muted: #6e7681; --faint: #9aa2ac; --line: #d4d8de; --line-soft: #e4e7eb;
  --accent: #e35f22; --accent-soft: #ef7a41; --accent-wash: #fceade; --w-wide: 1200px;
  --radius: 4px; --shadow: 0 8px 26px rgba(33,37,43,.08);
}
:root[data-theme="assembly"] .fs-hero { background: linear-gradient(135deg, #e7e9ec, var(--bg) 60%, #f5e9e0); }
/* 同 machinist：安全橙底配深字（白字 3.5:1 不达标） */
:root[data-theme="assembly"] .btn-primary { color: #17130f; }
:root[data-theme="assembly"] .inquiry-btn.inquiry-wa { color: #17130f; }

/* 海贸 · Harbor：雾蓝纸底 + 深海青（展台骨架外贸皮） */
:root[data-theme="harbor"] {
  --bg: #f1f6f6; --surface: #ffffff; --ink: #163033; --ink-soft: #35504f;
  --muted: #62797a; --faint: #90a4a4; --line: #d2e0e0; --line-soft: #e3edec;
  --accent: #136a72; --accent-soft: #2c8891; --accent-wash: #ddeef0; --w-wide: 1200px;
  --radius: 10px; --shadow: 0 10px 28px rgba(22,48,51,.08);
}
:root[data-theme="harbor"] .fs-card-go { color: #c2593a; }

/* 枪灰 · Gunmetal：枪灰黑底 + 金属银蓝（深色发布厅，展台骨架） */
:root[data-theme="gunmetal"] {
  --bg: #101418; --surface: #171d24; --ink: #e8eef4; --ink-soft: #c4cdd6;
  --muted: #8b96a2; --faint: #5d6873; --line: #2c353f; --line-soft: #1e252d;
  --accent: #8fb6d9; --accent-soft: #aecde8; --accent-wash: #22303d; --code-bg: #0a0d10;
  --w-wide: 1200px; --radius: 4px; --shadow: 0 16px 44px rgba(0,0,0,.5);
}
:root[data-theme="gunmetal"] .btn-primary { color: #0d1319; }
:root[data-theme="gunmetal"] .site-header { background: rgba(16,20,24,.88); }
:root[data-theme="gunmetal"] .fs-hero { background: linear-gradient(140deg, #1a2530, var(--bg) 55%, #131b22); }
:root[data-theme="gunmetal"] .f-stat dt { text-shadow: 0 0 18px rgba(143,182,217,.35); }
:root[data-theme="gunmetal"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #0d1319; }

/* ============================================================================
   FACTORY 工厂主题族追加三骨架（单页 / 方案 / 技术）
   factory-onepage     单页：整站一页滚到底（主打产品→实力→流程→FAQ→询盘），页头导航即页内锚点
   factory-solutions   方案：应用行业大卡一级入口 + 定制流程 + 商品作为「案例产出」
   factory-engineering 技术：规格对比表 + 产品索引 + 认证墙，数据手册密度
   容器规约与两骨架前辈一致：width: min(100% - 48px, var(--w-wide) - 48px)，
   页眉 logo、内容区、页脚三条左缘在任何视口必须对齐；皮肤在本段文末定义。
   ========================================================================== */

/* ---- factory-onepage 骨架（气质：直给——居中大字 hero + 胶带警示条 + 居中区块标题） ---- */
html[data-theme-layout="factory-onepage"] { scroll-behavior: smooth; }
[data-theme-layout="factory-onepage"] body { background: var(--bg); }
[data-theme-layout="factory-onepage"] .fo-wrap { padding-bottom: 4.5rem; }
