[data-theme-layout="factory-engineering"] .fe-index tr:last-child td { border-bottom: 0; }
[data-theme-layout="factory-engineering"] .fe-index tr:hover td { background: color-mix(in srgb, var(--accent) 6%, transparent); }
[data-theme-layout="factory-engineering"] .fe-index-sku { width: 1%; white-space: nowrap; color: var(--accent); font-family: var(--mono); font-size: .78rem; font-weight: 700; }
[data-theme-layout="factory-engineering"] .fe-index-title a { color: var(--ink); font-weight: 650; }
[data-theme-layout="factory-engineering"] .fe-index-title a:hover { color: var(--accent); }
[data-theme-layout="factory-engineering"] .fe-index-cat { color: var(--muted); font-family: var(--mono); font-size: .74rem; text-align: right; white-space: nowrap; }
[data-theme-layout="factory-engineering"] .fe-index-go { width: 1%; color: var(--faint); text-align: right; }
/* 回落商品栅格（带规格商品 <2 或无共有键时） */
[data-theme-layout="factory-engineering"] .fe-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .9rem; }
[data-theme-layout="factory-engineering"] .fe-card { display: flex; min-width: 0; flex-direction: column; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); overflow: hidden; transition: border-color var(--speed); }
[data-theme-layout="factory-engineering"] .fe-card:hover { border-color: var(--accent); color: var(--ink); }
[data-theme-layout="factory-engineering"] .fe-card-media { display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-engineering"] .fe-card-media img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="factory-engineering"] .fe-card-gen b { font-family: var(--sans); font-size: 2.6rem; color: var(--accent); }
[data-theme-layout="factory-engineering"] .fe-card-body { display: flex; flex: 1; flex-direction: column; gap: .3rem; padding: .8rem .9rem .95rem; }
[data-theme-layout="factory-engineering"] .fe-card-sku { width: fit-content; color: var(--accent); font-family: var(--mono); font-size: .68rem; font-weight: 750; letter-spacing: .05em; }
[data-theme-layout="factory-engineering"] .fe-card-title { font-size: .94rem; font-weight: 700; line-height: 1.4; }
[data-theme-layout="factory-engineering"] .fe-empty { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center; }
/* 认证墙：图章铺成规则网格，去掉展台骨架的错位角度（工程气质=精确） */
[data-theme-layout="factory-engineering"] .fe-certs { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: .8rem; }
[data-theme-layout="factory-engineering"] .fe-certs .f-cert { margin: 0; padding: .85rem 1rem .75rem; transform: none; }
[data-theme-layout="factory-engineering"] .fe-stats { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .9rem; }
/* 技术骨架的列表/归档页：眉标与分页吃等宽（与首页同一手册质感） */
[data-theme-layout="factory-engineering"] .page-head .eyebrow { font-family: var(--mono); letter-spacing: .14em; }

/* ---- 追加三骨架响应式 ---- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-solutions"] .fx-case-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  [data-theme-layout="factory-engineering"] .fe-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 900px) {
  [data-theme-layout="factory-onepage"] .fo-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
  [data-theme-layout="factory-onepage"] .fo-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-solutions"] .fx-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-engineering"] .fe-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  /* hero 槽视觉（图/动画同规）：窄屏收成单列，视觉位落到文字下方 */
  [data-theme-layout="factory-onepage"] .fo-hero.has-img .fo-hero-inner,
  [data-theme-layout="factory-onepage"] .fo-hero.has-anim .fo-hero-inner,
  [data-theme-layout="factory-solutions"] .fx-hero.has-img .fx-hero-inner,
  [data-theme-layout="factory-solutions"] .fx-hero.has-anim .fx-hero-inner { grid-template-columns: 1fr; }
  [data-theme-layout="factory-engineering"] .fe-hero.has-img,
  [data-theme-layout="factory-engineering"] .fe-hero.has-anim { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  [data-theme-layout="factory-onepage"] .fo-grid { grid-template-columns: 1fr; }
  [data-theme-layout="factory-onepage"] .fo-stats { gap: .7rem; }
  [data-theme-layout="factory-solutions"] .fx-case-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .7rem; }
  [data-theme-layout="factory-solutions"] .fx-sol-card { padding: 1.2rem 1.15rem 1.1rem; }
  [data-theme-layout="factory-engineering"] .fe-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .7rem; }
  [data-theme-layout="factory-engineering"] .fe-index-cat { display: none; }
  [data-theme-layout="factory-engineering"] .fe-hero { padding-top: 1.1rem; }
  /* 手册气质：小屏藏 hero 小图/动画，参数信息优先（div 前缀压过 div.f-heroanim 的特异度） */
  [data-theme-layout="factory-engineering"] .fe-hero-media,
  [data-theme-layout="factory-engineering"] div.fe-hero-media { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  html[data-theme-layout="factory-onepage"] { scroll-behavior: auto; }
  [data-theme-layout="factory-onepage"] .fo-card, [data-theme-layout="factory-onepage"] .fo-card-media img,
  [data-theme-layout="factory-solutions"] .fx-sol-card, [data-theme-layout="factory-solutions"] .fx-case-card,
  [data-theme-layout="factory-engineering"] .fe-card { transition: none; }
}

/* ---- 工厂皮肤 ×12（Category=factory；单页/方案/技术三骨架各 4 皮） ---- */
/* 胶带黄 · Packline：暖纸仓储底 + 打包胶带黄黑警示条（单页骨架原生皮） */
:root[data-theme="packline"] {
  --bg: #f7f5ef; --surface: #fffdf7; --ink: #211d12; --ink-soft: #423c2c;
  --muted: #6e6957; --faint: #9b9584; --line: #ddd7c4; --line-soft: #ebe6d6;
  --accent: #8f6a02; --accent-soft: #b08a1a; --accent-wash: #f3ecd2; --w-wide: 1200px;
  --radius: 4px; --shadow: 0 8px 24px rgba(33,29,18,.07);
}
:root[data-theme="packline"] .site-header { border-bottom: 2px solid var(--ink); }
/* 胶带警示条换成正牌胶带黄黑（皮肤专属记忆点；文本仍用暗金 accent 保对比度） */
:root[data-theme="packline"] .fo-hero::after { background: repeating-linear-gradient(-45deg, #f2b705 0 16px, #171410 16px 32px); }

/* 深炭 · Carbon：深炭黑底 + 安全黄信号（单页骨架暗色皮） */
:root[data-theme="carbon"] {
  --bg: #141414; --surface: #1d1d1b; --ink: #eeece5; --ink-soft: #cfccc2;
  --muted: #9a958a; --faint: #6b665c; --line: #363531; --line-soft: #232320;
  --accent: #f5c81d; --accent-soft: #ffd94d; --accent-wash: #3a3212; --code-bg: #0c0c0b;
  --w-wide: 1200px; --radius: 4px; --shadow: 0 14px 40px rgba(0,0,0,.45);
}
:root[data-theme="carbon"] .btn-primary { color: #171410; }
:root[data-theme="carbon"] .fo-eyebrow { color: #171410; }
:root[data-theme="carbon"] .site-header { background: rgba(20,20,20,.88); }
:root[data-theme="carbon"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #171410; }
:root[data-theme="carbon"] .site-header .nav > a.fo-nav-cta { color: #171410; }
:root[data-theme="carbon"] .site-header .nav > a.fo-nav-cta:hover { color: #171410; }

/* 亚麻 · Linen：亚麻本白纸底 + 胡桃棕点缀（单页骨架素色皮） */
:root[data-theme="linen"] {
  --bg: #f8f6f1; --surface: #fffefb; --ink: #2a2620; --ink-soft: #4a453c;
  --muted: #75705f; --faint: #a09a8c; --line: #ded9cc; --line-soft: #ebe7dd;
  --accent: #7c5c38; --accent-soft: #97754e; --accent-wash: #efe7db; --w-wide: 1200px;
  --radius: 8px; --shadow: 0 8px 24px rgba(42,38,32,.06);
}
:root[data-theme="linen"] .fo-hero::after { height: 6px; background: repeating-linear-gradient(90deg, var(--accent) 0 22px, color-mix(in srgb, var(--accent) 22%, var(--bg)) 22px 44px); }

/* 信号红 · Redline：冷白底 + 信号红一击（单页骨架高转化皮） */
:root[data-theme="redline"] {
  --bg: #f7f7f6; --surface: #ffffff; --ink: #1c1e21; --ink-soft: #3c4046;
  --muted: #6b7076; --faint: #989da3; --line: #d9dbdd; --line-soft: #e8e9ea;
  --accent: #cf3527; --accent-soft: #e0553f; --accent-wash: #fbe6e2; --w-wide: 1200px;
  --radius: 2px; --shadow: 0 8px 24px rgba(28,30,33,.07);
}
:root[data-theme="redline"] .site-header { border-bottom: 2px solid var(--accent); }

/* 图纸青 · Drafting：浅青图纸底 + 制图青强调（方案骨架原生皮） */
:root[data-theme="drafting"] {
  --bg: #eef3f4; --surface: #ffffff; --ink: #14313a; --ink-soft: #34505a;
  --muted: #62787f; --faint: #90a3a8; --line: #d2dee0; --line-soft: #e2eaec;
  --accent: #0f7286; --accent-soft: #2b8fa3; --accent-wash: #dcedf0; --w-wide: 1240px;
  --radius: 4px; --shadow: 0 8px 26px rgba(20,49,58,.07);
}

/* 深海军 · Flagship：深海军蓝底 + 浅钢蓝辉光（方案骨架暗色皮） */
:root[data-theme="flagship"] {
  --bg: #0d1626; --surface: #142034; --ink: #e7edf7; --ink-soft: #c3cddd;
  --muted: #8d9cb4; --faint: #5f6d84; --line: #2a3a54; --line-soft: #1c2940;
  --accent: #7db1e8; --accent-soft: #a2c8f2; --accent-wash: #1d3350; --code-bg: #080f1b;
  --w-wide: 1240px; --radius: 6px; --shadow: 0 16px 44px rgba(0,0,0,.5);
}
:root[data-theme="flagship"] .btn-primary { color: #0b1322; }
:root[data-theme="flagship"] .site-header { background: rgba(13,22,38,.88); }
:root[data-theme="flagship"] .fx-hero { background: linear-gradient(120deg, #16253e, var(--bg) 58%); }
:root[data-theme="flagship"] .f-stat dt { text-shadow: 0 0 18px rgba(125,177,232,.35); }
:root[data-theme="flagship"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #0b1322; }

/* 混凝土 · Concrete：混凝土灰底 + 钢青蓝强调（方案骨架工程皮） */
:root[data-theme="concrete"] {
  --bg: #efeeec; --surface: #f9f8f6; --ink: #26262a; --ink-soft: #46464c;
  --muted: #717176; --faint: #9c9ca1; --line: #d5d4d0; --line-soft: #e3e2de;
  --accent: #3e5c76; --accent-soft: #587a97; --accent-wash: #e2e9ef; --w-wide: 1240px;
  --radius: 2px; --shadow: 0 8px 24px rgba(38,38,42,.08);
}
:root[data-theme="concrete"] .site-header { border-bottom: 2px solid var(--ink); }

/* 琥珀 · Amberpress：暖琥珀纸底 + 衬线大标题（方案骨架老牌工坊皮） */
:root[data-theme="amberpress"] {
  --bg: #faf6ed; --surface: #fffdf6; --ink: #2e2418; --ink-soft: #4f4232;
  --muted: #7a6c58; --faint: #a49685; --line: #e2d9c6; --line-soft: #efe8d8;
  --accent: #9c6520; --accent-soft: #b8823c; --accent-wash: #f4e8d3; --w-wide: 1240px;
  --radius: 6px; --shadow: 0 8px 24px rgba(46,36,24,.07);
}
:root[data-theme="amberpress"] h1, :root[data-theme="amberpress"] h2,
:root[data-theme="amberpress"] h3, :root[data-theme="amberpress"] h4 { font-family: var(--serif); }
:root[data-theme="amberpress"] .fx-h1 { font-family: var(--serif); font-weight: 640; letter-spacing: 0; }

/* 示波绿 · Phosphor：示波器暗底 + 磷光绿读数（技术骨架暗色皮） */
:root[data-theme="phosphor"] {
  --bg: #0b100d; --surface: #121a15; --ink: #e0eae2; --ink-soft: #bccabf;
  --muted: #8ba192; --faint: #5c7263; --line: #263a2d; --line-soft: #17251c;
  --accent: #43d17c; --accent-soft: #6fe3a0; --accent-wash: #123324; --code-bg: #070b08;
  --w-wide: 1280px; --radius: 4px; --shadow: 0 16px 44px rgba(0,0,0,.5);
}
:root[data-theme="phosphor"] .btn-primary { color: #08130c; }
:root[data-theme="phosphor"] .fe-eyebrow { text-shadow: 0 0 12px rgba(67,209,124,.4); }
:root[data-theme="phosphor"] .site-header { background: rgba(11,16,13,.88); }
:root[data-theme="phosphor"] .f-stat dt { text-shadow: 0 0 18px rgba(67,209,124,.35); }
:root[data-theme="phosphor"] .fe-compare thead th { border-bottom-color: var(--accent); }
:root[data-theme="phosphor"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #08130c; }

/* 制图蓝 · Schematic：制图白底 + 工程蓝墨线（技术骨架图纸皮） */
:root[data-theme="schematic"] {
  --bg: #f3f7fb; --surface: #ffffff; --ink: #16283e; --ink-soft: #364a62;
  --muted: #64768c; --faint: #92a1b3; --line: #d3dde8; --line-soft: #e3eaf2;
  --accent: #1d5fbd; --accent-soft: #3d7cd4; --accent-wash: #e1ecfa; --w-wide: 1280px;
  --radius: 2px; --shadow: 0 8px 26px rgba(22,40,62,.07);
}
:root[data-theme="schematic"] .fe-hero { border-bottom-color: var(--accent); }

/* 钛灰 · Titanium：钛灰冷底 + 青灰蓝强调（技术骨架金属皮） */
:root[data-theme="titanium"] {
  --bg: #eef0f2; --surface: #f9fafb; --ink: #24282c; --ink-soft: #444a50;
  --muted: #6e757c; --faint: #99a0a7; --line: #d4d8dc; --line-soft: #e3e6e9;
  --accent: #47637a; --accent-soft: #628099; --accent-wash: #e3eaef; --w-wide: 1280px;
  --radius: 2px; --shadow: 0 8px 24px rgba(36,40,44,.08);
}

/* 警示橙 · Hazard：浅灰纸底 + 警示橙信号（技术骨架安全规格皮） */
:root[data-theme="hazard"] {
  --bg: #f5f4f1; --surface: #fdfdfa; --ink: #201f1d; --ink-soft: #413f3b;
  --muted: #6d6b66; --faint: #999792; --line: #dad8d2; --line-soft: #e8e6e1;
  --accent: #b9430e; --accent-soft: #d55c24; --accent-wash: #f8e5db; --w-wide: 1280px;
