[data-theme-layout="factory-trade"] .ft-cat-list a:last-child { border-bottom: 0; }
[data-theme-layout="factory-trade"] .ft-cat-list a:hover { color: var(--accent); background: color-mix(in srgb, var(--accent) 5%, transparent); }
[data-theme-layout="factory-trade"] .ft-cat-list a small { color: var(--faint); font-family: var(--mono); font-size: .7rem; }
[data-theme-layout="factory-trade"] .ft-cat-list .ft-cat-all { color: var(--accent); font-size: .84rem; font-weight: 650; }
[data-theme-layout="factory-trade"] .ft-contact-row { display: flex; flex-direction: column; gap: .1rem; padding: .55rem .9rem; border-bottom: 1px solid var(--line-soft); color: var(--ink); font-size: .88rem; overflow-wrap: anywhere; }
