[data-theme-layout="factory-trade"] .ft-section-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; margin-bottom: 1rem; padding-bottom: .65rem; border-bottom: 2px solid var(--ink); }
[data-theme-layout="factory-trade"] .ft-section-head h2 { margin: 0; font-family: var(--sans); font-size: 1.3rem; font-weight: 760; }
[data-theme-layout="factory-trade"] .ft-section-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-trade"] .ft-section-head > a:hover { color: var(--accent); }
[data-theme-layout="factory-trade"] .ft-section + .ft-section { margin-top: 2.4rem; }
[data-theme-layout="factory-trade"] .ft-full { padding-top: 2.8rem; }
[data-theme-layout="factory-trade"] .ft-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .9rem; }
[data-theme-layout="factory-trade"] .ft-card { display: flex; min-width: 0; flex-direction: column; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); overflow: hidden; transition: border-color var(--speed), transform var(--speed); }
[data-theme-layout="factory-trade"] .ft-card:hover { border-color: var(--accent); transform: translateY(-2px); color: var(--ink); }
[data-theme-layout="factory-trade"] .ft-card-media { display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-trade"] .ft-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
[data-theme-layout="factory-trade"] .ft-card:hover .ft-card-media img { transform: scale(1.03); }
[data-theme-layout="factory-trade"] .ft-card-gen b { font-family: var(--sans); font-size: 2.8rem; color: var(--accent); }
[data-theme-layout="factory-trade"] .ft-card-body { display: flex; flex: 1; flex-direction: column; gap: .28rem; padding: .8rem .9rem .95rem; }
[data-theme-layout="factory-trade"] .ft-card-cat { width: fit-content; color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 750; letter-spacing: .06em; text-transform: uppercase; }
