[data-theme-layout="factory-trade"] .ft-foot-contact a, [data-theme-layout="factory-trade"] .ft-foot-wechat { display: flex; flex-direction: column; gap: .05rem; padding: .28rem 0; border: 0; background: none; text-align: left; color: var(--ink-soft); font-size: .9rem; cursor: pointer; overflow-wrap: anywhere; }
[data-theme-layout="factory-trade"] .ft-foot-contact a b, [data-theme-layout="factory-trade"] .ft-foot-wechat b { font-family: var(--mono); font-size: .62rem; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--faint); }
