/* ---- factory-sidebar 骨架（气质：数据库感的密集目录——左侧常驻竖栏 + 行式清单） ---- */
[data-theme-layout="factory-sidebar"] { --fb-rail: 264px; }
[data-theme-layout="factory-sidebar"] body { padding-left: var(--fb-rail); background: var(--bg); }
[data-theme-layout="factory-sidebar"] .site-header { position: fixed; inset: 0 auto 0 0; width: var(--fb-rail); height: 100vh; border-right: 1px solid var(--line); border-bottom: 0; background: var(--surface); overflow-y: auto; z-index: 50; -webkit-backdrop-filter: none; backdrop-filter: none; }
[data-theme-layout="factory-sidebar"] .site-header .wrap { flex-direction: column; align-items: stretch; justify-content: flex-start; height: auto; min-height: 100%; max-width: none; padding: 26px 18px 18px; gap: 0; }
[data-theme-layout="factory-sidebar"] .site-header .brand { margin: 0 .2rem .3rem; font-family: var(--sans); font-size: 1.25rem; font-weight: 760; line-height: 1.2; }
[data-theme-layout="factory-sidebar"] .site-header .brand.has-logo { display: flex; align-items: center; gap: .5rem; }
[data-theme-layout="factory-sidebar"] .site-header .brand-logo { height: 28px; width: auto; }
[data-theme-layout="factory-sidebar"] .brand-tagline { display: block; margin: 0 .2rem 1.2rem; color: var(--muted); font-size: .78rem; line-height: 1.5; }
[data-theme-layout="factory-sidebar"] .nav { flex: 1; flex-direction: column; align-items: stretch; gap: .1rem; width: 100%; }
[data-theme-layout="factory-sidebar"] .nav > a { display: flex; align-items: center; gap: .5rem; padding: .48rem .65rem; border-radius: calc(var(--radius) + 3px); color: var(--ink-soft); font-size: .92rem; font-weight: 550; white-space: nowrap; transition: background var(--speed), color var(--speed); }
[data-theme-layout="factory-sidebar"] .nav > a:hover { background: color-mix(in srgb, var(--accent) 9%, transparent); color: var(--ink); }
[data-theme-layout="factory-sidebar"] .nav > a[aria-current="page"] { background: color-mix(in srgb, var(--accent) 13%, transparent); color: var(--accent); font-weight: 700; }
[data-theme-layout="factory-sidebar"] .nav > a[aria-current="page"]::after { display: none; }
[data-theme-layout="factory-sidebar"] .search-label { display: inline; }
[data-theme-layout="factory-sidebar"] .nav .search-ico { opacity: 1; color: var(--muted); }
[data-theme-layout="factory-sidebar"] .fb-rail-group { margin-top: 1rem; padding-top: .9rem; border-top: 1px solid var(--line); }
[data-theme-layout="factory-sidebar"] .fb-rail-title { margin: 0 0 .4rem; padding: 0 .65rem; font-family: var(--mono); font-size: .62rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; color: var(--faint); }
[data-theme-layout="factory-sidebar"] .fb-rail-cat { display: flex; align-items: baseline; justify-content: space-between; gap: .6rem; padding: .4rem .65rem; border-radius: calc(var(--radius) + 3px); color: var(--ink-soft); font-size: .88rem; }
[data-theme-layout="factory-sidebar"] .fb-rail-cat:hover { background: color-mix(in srgb, var(--accent) 9%, transparent); color: var(--ink); }
[data-theme-layout="factory-sidebar"] .fb-rail-cat small { color: var(--faint); font-family: var(--mono); font-size: .68rem; }
[data-theme-layout="factory-sidebar"] .fb-rail-news { display: flex; align-items: center; gap: .4rem; padding: .4rem .65rem; border-radius: calc(var(--radius) + 3px); color: var(--ink-soft); font-size: .88rem; }
[data-theme-layout="factory-sidebar"] .fb-rail-news:hover { background: color-mix(in srgb, var(--accent) 9%, transparent); color: var(--ink); }
[data-theme-layout="factory-sidebar"] .nav .lang-switch { align-self: stretch; width: 100%; margin: 1rem 0 0; padding: .9rem 0 0; border-left: 0; border-top: 1px solid var(--line); }
[data-theme-layout="factory-sidebar"] .nav .lang-switch summary { width: 100%; justify-content: flex-start; padding: .4rem .65rem; border-radius: calc(var(--radius) + 3px); }
[data-theme-layout="factory-sidebar"] .nav .lang-switch summary:hover { background: color-mix(in srgb, var(--accent) 9%, transparent); }
[data-theme-layout="factory-sidebar"] .nav .lang-menu { top: auto; bottom: calc(100% + .3rem); left: 0; right: auto; }
[data-theme-layout="factory-sidebar"] .fb-rail-cta { margin-top: auto; padding-top: 1.1rem; }
[data-theme-layout="factory-sidebar"] .fb-rail-cta .btn { width: 100%; justify-content: center; }
/* 右侧内容：统一 24px 内边距、左缘与竖栏对齐；封顶站宽 */
[data-theme-layout="factory-sidebar"] .wrap { width: min(100%, calc(var(--w-wide) + 48px)); max-width: none; margin: 0; padding: 0 24px; }
[data-theme-layout="factory-sidebar"] .fb-wrap { width: min(100%, calc(var(--w-wide) + 48px)); padding: 1.7rem 24px 3.6rem; }
[data-theme-layout="factory-sidebar"] .f-cta-inner { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 0 0 24px; }
[data-theme-layout="factory-sidebar"] .fb-eyebrow { width: fit-content; margin: 0 0 .8rem; padding: .26rem .55rem; border: 1px solid var(--accent); color: var(--accent); font-family: var(--mono); font-size: .66rem; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; }
[data-theme-layout="factory-sidebar"] .fb-h1 { margin: 0; max-width: 18em; font-family: var(--sans); font-size: clamp(1.7rem, 3.4vw, 2.5rem); font-weight: 770; line-height: 1.14; letter-spacing: -.01em; }
[data-theme-layout="factory-sidebar"] .fb-lede { max-width: 64ch; margin: .8rem 0 0; color: var(--muted); font-size: .98rem; line-height: 1.7; }
[data-theme-layout="factory-sidebar"] .fb-intro { padding-bottom: 1.9rem; border-bottom: 2px solid var(--ink); }
/* hero 槽图：内容区顶部横幅位（竖栏不动）；未配置零变化。 */
/* hero 双栏:文字左、媒体右(有图/动画时);≤900px 单列媒体落文字下。 */
[data-theme-layout="factory-sidebar"] .fb-hero { margin: 0 0 2.2rem; }
[data-theme-layout="factory-sidebar"] .fb-hero.has-media { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, .85fr); gap: 2.2rem; align-items: center; }
[data-theme-layout="factory-sidebar"] .fb-hero-banner { margin: 0; border: 1px solid var(--line); border-radius: var(--radius); background: var(--line-soft); overflow: hidden; }
/* 有图（figure）：去底板不裁剪——横幅位改为裸图 + 轻阴影，按自身比例限高（竖图横图都不裁）；
   动画横幅（div.f-heroanim）维持底色边框卡现状。 */
[data-theme-layout="factory-sidebar"] figure.fb-hero-banner { border: 0; border-radius: 0; background: none; box-shadow: none; overflow: visible; }
[data-theme-layout="factory-sidebar"] .fb-hero-banner img { display: block; width: auto; max-width: 100%; height: auto; max-height: clamp(200px, 30vw, 360px); margin-inline: auto; border-radius: var(--radius); }
/* hero 动画态：横幅高度与图片位一致，动画按高缩放居中在图纸网格带上 */
[data-theme-layout="factory-sidebar"] .fb-hero-banner.f-heroanim { height: clamp(170px, 24vw, 300px); min-height: 0; }
[data-theme-layout="factory-sidebar"] .fb-hero-banner.f-heroanim .f-animsvg { width: auto; height: 100%; }
[data-theme-layout="factory-sidebar"] .fb-statline { display: flex; flex-wrap: wrap; gap: .9rem 2.4rem; margin: 1.5rem 0 0; }
[data-theme-layout="factory-sidebar"] .fb-stat { display: flex; align-items: baseline; gap: .55rem; }
[data-theme-layout="factory-sidebar"] .fb-stat dt { margin: 0; color: var(--accent); font-family: var(--mono); font-size: 1.4rem; font-weight: 800; letter-spacing: -.01em; font-variant-numeric: tabular-nums; }
[data-theme-layout="factory-sidebar"] .fb-stat dd { margin: 0; color: var(--muted); font-size: .72rem; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; }
[data-theme-layout="factory-sidebar"] .fb-intro .f-about { margin-top: 1.4rem; }
[data-theme-layout="factory-sidebar"] .fb-section { padding-top: 2.6rem; }
[data-theme-layout="factory-sidebar"] .fb-section-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; margin-bottom: 1rem; padding-bottom: .6rem; border-bottom: 1px solid var(--line); }
[data-theme-layout="factory-sidebar"] .fb-section-head h2 { margin: 0; font-family: var(--sans); font-size: 1.25rem; font-weight: 760; }
[data-theme-layout="factory-sidebar"] .fb-section-head > a { flex: none; color: var(--ink-soft); font-family: var(--mono); font-size: .8rem; }
[data-theme-layout="factory-sidebar"] .fb-section-head > a:hover { color: var(--accent); }
/* 行式商品清单（数据库行） */
[data-theme-layout="factory-sidebar"] .fb-rows { border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); overflow: hidden; }
[data-theme-layout="factory-sidebar"] .fb-row { display: grid; grid-template-columns: 58px minmax(0, 1fr) auto auto; align-items: center; gap: .95rem; padding: .55rem .85rem .55rem .55rem; border-bottom: 1px solid var(--line-soft); color: var(--ink); transition: background var(--speed); }
[data-theme-layout="factory-sidebar"] .fb-row:last-child { border-bottom: 0; }
[data-theme-layout="factory-sidebar"] .fb-row:hover { background: color-mix(in srgb, var(--accent) 5%, transparent); color: var(--ink); }
[data-theme-layout="factory-sidebar"] .fb-row-media { display: grid; place-items: center; width: 58px; aspect-ratio: 4 / 3; border-radius: 2px; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-sidebar"] .fb-row-media img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="factory-sidebar"] .fb-row-gen b { font-family: var(--sans); font-size: 1.2rem; color: var(--accent); }
[data-theme-layout="factory-sidebar"] .fb-row-main { display: flex; min-width: 0; flex-direction: column; gap: .18rem; }
[data-theme-layout="factory-sidebar"] .fb-row-main .f-chips { margin-top: 0; }
[data-theme-layout="factory-sidebar"] .fb-row-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-size: .95rem; font-weight: 680; }
[data-theme-layout="factory-sidebar"] .fb-row:hover .fb-row-title { color: var(--accent); }
[data-theme-layout="factory-sidebar"] .fb-row-cat { color: var(--muted); font-family: var(--mono); font-size: .72rem; white-space: nowrap; }
[data-theme-layout="factory-sidebar"] .fb-row .arrow { color: var(--faint); }
[data-theme-layout="factory-sidebar"] .fb-empty { margin: 0; padding: 1.6rem; text-align: center; }
[data-theme-layout="factory-sidebar"] .fb-news-list { border-top: 0; }
[data-theme-layout="factory-sidebar"] .fb-news-item { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem; padding: .6rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .92rem; }
[data-theme-layout="factory-sidebar"] .fb-news-item:hover { color: var(--accent); }
[data-theme-layout="factory-sidebar"] .fb-news-item time { color: var(--faint); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-sidebar"] .fb-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
/* 一行极简页脚 */
[data-theme-layout="factory-sidebar"] .fb-footer { margin-top: 3rem; padding: 1rem 0; }
[data-theme-layout="factory-sidebar"] .fb-foot-in { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: .4rem 1.4rem; }
[data-theme-layout="factory-sidebar"] .fb-footer .copy { margin: 0; color: var(--faint); font-size: .82rem; }
[data-theme-layout="factory-sidebar"] .fb-foot-links { display: flex; flex-wrap: wrap; gap: .2rem 1.1rem; }
[data-theme-layout="factory-sidebar"] .fb-foot-links a { color: var(--muted); font-size: .82rem; }
[data-theme-layout="factory-sidebar"] .fb-foot-links a:hover { color: var(--accent); }
/* ≤920px：竖栏折叠为顶部抽屉（menu-toggle + .nav-open，JS class） */
@media (max-width: 920px) {
  [data-theme-layout="factory-sidebar"] .fb-hero.has-media { grid-template-columns: 1fr; gap: 1.4rem; }
  [data-theme-layout="factory-sidebar"] body { padding-left: 0; }
  [data-theme-layout="factory-sidebar"] .site-header { position: sticky; top: 0; width: auto; height: auto; min-height: 0; border-right: 0; border-bottom: 1px solid var(--line); overflow: visible; }
  [data-theme-layout="factory-sidebar"] .site-header .wrap { flex-direction: row; align-items: center; justify-content: space-between; min-height: 0; height: 58px; padding: 0 24px; }
  [data-theme-layout="factory-sidebar"] .site-header .brand { margin: 0; font-size: 1.15rem; }
  [data-theme-layout="factory-sidebar"] .menu-toggle { display: inline-flex; }
  [data-theme-layout="factory-sidebar"] .brand-tagline { display: none; }
  [data-theme-layout="factory-sidebar"] .nav { display: none; position: absolute; top: 100%; left: 0; right: 0; width: auto; max-height: calc(100vh - 58px); overflow-y: auto; flex-direction: column; align-items: stretch; gap: 0; background: var(--surface); border-bottom: 1px solid var(--line); box-shadow: 0 16px 30px rgba(0,0,0,.12); padding: .35rem .9rem .9rem; z-index: 55; }
  [data-theme-layout="factory-sidebar"] .site-header.nav-open .nav { display: flex; }
  [data-theme-layout="factory-sidebar"] .nav > a { padding: .7rem .35rem; border-radius: 0; border-bottom: 1px solid var(--line-soft); }
  [data-theme-layout="factory-sidebar"] .nav > a[aria-current="page"] { background: none; }
  [data-theme-layout="factory-sidebar"] .fb-rail-group { margin-top: .6rem; padding-top: .6rem; }
  [data-theme-layout="factory-sidebar"] .fb-rail-cta { margin-top: .8rem; padding-top: 0; }
  [data-theme-layout="factory-sidebar"] .nav .lang-switch { margin-top: .6rem; padding-top: .6rem; }
  [data-theme-layout="factory-sidebar"] .nav .lang-menu { position: static; box-shadow: none; border: 0; padding: 0 0 .35rem .9rem; top: auto; bottom: auto; }
  [data-theme-layout="factory-sidebar"] .f-cta-inner { margin-inline: auto; }
}

/* ---- factory-vision 骨架（气质：沉浸——全屏大图页头、大留白视觉流、页脚即 CTA） ---- */
[data-theme-layout="factory-vision"] body { background: var(--bg); }
/* 导航透明悬浮（js-fnav 由 site.js 在首页 hero 存在时加上；无 JS 恒实底可用）。
   文字色不特判图片：hero 罩层用 --bg 调和（亮皮=晨雾白纱、暗皮=夜幕压暗），
   主题 ink 在任何皮肤/有无图下都可读。 */
