:root[data-theme="portwhite"] .ft-utility .lang-switch > summary:hover,
:root[data-theme="portwhite"] .ft-utility .lang-switch[open] > summary { color: var(--ink); }
:root[data-theme="portwhite"] .site-header { border-bottom-width: 1px; border-bottom-color: var(--line); }
:root[data-theme="portwhite"] .ft-hero { background: var(--accent); }
:root[data-theme="portwhite"] .ft-hero::before { content: none; }
:root[data-theme="portwhite"] .ft-section-head { border-bottom-width: 1px; border-bottom-color: var(--line); }
:root[data-theme="portwhite"] .ft-footer { border-top-width: 1px; border-top-color: var(--line); }

/* ---- 架白 · Rackwhite（factory-sidebar）：白竖栏+细分隔，导语重线降细 ---- */
:root[data-theme="rackwhite"] .fb-intro { border-bottom: 1px solid var(--line); }

/* ---- 白厅 · Whitehall（factory-vision）：浅色沉浸展馆，hero 去渐变去网格 ---- */
:root[data-theme="whitehall"] .fv-hero { background: var(--bg); }
:root[data-theme="whitehall"] .fv-hero:not(.has-img)::before { content: none; }

/* ---- 门白 · Archwhite（factory-herofold）：白门楣容器=发丝线描边，去渐变去网格 ---- */
:root[data-theme="archwhite"] .fh-hero { background: var(--bg); }
:root[data-theme="archwhite"] .fh-hero:not(.has-img)::before { content: none; }

/* ============================================================================
   DTC 外贸独立站主题族（Category=dtc）
   三骨架：dtc-flagship 品牌旗舰（生活方式 hero + 系列大卡 + 畅销栅格 + 品牌故事 + 评价）
          dtc-solo     单品爆款（痛点 hero→卖点分解→规格→场景→评价→大 CTA 长转化流）
          dtc-lookbook 系列画册（通栏大图墙 + 分类系列陈列 + 悬停出品名，极少文字）
   气质=零售感、大图、故事性，与工厂族的工业感彻底区分（无图纸网格/角标/等宽货号）。
   容器规约同工厂族：width: min(100% - 48px, var(--w-wide) - 48px)，绝不自造宽度。
   皮肤 12 款（各骨架 ×4）在本节文末以 :root[data-theme=...] 定义。
   ========================================================================== */

/* ---- DTC 共用（dt-*）：眉标 / 区块头 / 数字带 / 评价卡 / CTA / 按钮语言 ---- */
[data-theme-layout^="dtc-"] body { background: var(--bg); }
/* 零售感按钮：旗舰/单品全走胶囊；主按钮全族统一「ink 底 + surface 字」——
   这是每个皮肤对比度最高的一对（亮皮=近黑底白字的经典 DTC 按钮，暗皮自动反转），
   悬停底色不变、加 accent 光圈（45 皮审计的既定规则：绝不悬停降对比）。 */
[data-theme-layout="dtc-flagship"] .btn, [data-theme-layout="dtc-solo"] .btn { border-radius: 999px; }
[data-theme-layout^="dtc-"] .btn-primary { background: var(--ink); border-color: var(--ink); color: var(--surface); }
[data-theme-layout^="dtc-"] .btn-primary:hover { background: var(--ink); border-color: var(--ink); color: var(--surface); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 32%, transparent); }
[data-theme-layout^="dtc-"] .dt-btn-ghost { background: transparent; }
[data-theme-layout^="dtc-"] .inquiry-btn { border-radius: 999px; }
[data-theme-layout^="dtc-"] .inquiry-btn.inquiry-wa { background: var(--ink); border-color: var(--ink); color: var(--surface); }
[data-theme-layout^="dtc-"] .inquiry-btn.inquiry-wa:hover { background: var(--ink); border-color: var(--ink); color: var(--surface); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 32%, transparent); }

[data-theme-layout^="dtc-"] .dt-eyebrow { margin: 0 0 .8rem; color: var(--accent); font-family: var(--sans); font-size: .74rem; font-weight: 750; letter-spacing: .2em; text-transform: uppercase; }
[data-theme-layout^="dtc-"] .dt-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem; margin-bottom: 1.6rem; }
[data-theme-layout^="dtc-"] .dt-head .dt-eyebrow { margin-bottom: .45rem; }
[data-theme-layout^="dtc-"] .dt-head h2 { margin: 0; font-family: var(--dt-display, var(--serif)); font-size: clamp(1.5rem, 2.6vw, 2.05rem); font-weight: 650; letter-spacing: -.01em; }
[data-theme-layout^="dtc-"] .dt-head > a { flex: none; padding-bottom: .3rem; color: var(--ink-soft); font-size: .88rem; }
[data-theme-layout^="dtc-"] .dt-head > a:hover { color: var(--accent); }

/* 品牌数字带（factory.stats 复用；空回落站点简介段落） */
[data-theme-layout^="dtc-"] .dt-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 1rem; margin: 0; }
[data-theme-layout^="dtc-"] .dt-stat { padding: 1.4rem 1.2rem 1.25rem; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); text-align: center; }
[data-theme-layout^="dtc-"] .dt-stat dt { margin: 0 0 .3rem; font-family: var(--dt-display, var(--serif)); font-size: clamp(1.6rem, 2.6vw, 2.2rem); font-weight: 650; letter-spacing: -.01em; color: var(--ink); }
[data-theme-layout^="dtc-"] .dt-stat dd { margin: 0; color: var(--muted); font-size: .85rem; }

/* 用户评价卡（dtc.testimonials；未配置整个区块不渲染——绝不放假评价） */
[data-theme-layout^="dtc-"] .dt-testis { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(260px, 100%), 1fr)); gap: 1rem; }
[data-theme-layout^="dtc-"] .dt-testi { display: flex; flex-direction: column; gap: 1rem; margin: 0; padding: 1.4rem 1.4rem 1.25rem; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
[data-theme-layout^="dtc-"] .dt-testi-quote { position: relative; margin: 0; color: var(--ink-soft); font-size: .95rem; line-height: 1.8; }
[data-theme-layout^="dtc-"] .dt-testi-mark { display: block; height: .35em; color: var(--accent); font-family: var(--serif); font-size: 2.1rem; line-height: .8; }
[data-theme-layout^="dtc-"] .dt-testi-by { display: flex; align-items: center; gap: .55rem; margin-top: auto; }
[data-theme-layout^="dtc-"] .dt-testi-ini { display: grid; flex: none; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: var(--accent-wash); color: var(--accent); font-family: var(--sans); font-size: .85rem; font-weight: 700; }
[data-theme-layout^="dtc-"] .dt-testi-name { font-size: .86rem; font-weight: 650; color: var(--ink); }
[data-theme-layout^="dtc-"] .dt-testi-region { color: var(--faint); font-size: .78rem; }

/* 页脚前联系 CTA：柔和整卡（accent-wash 底），非工厂的反色斜纹通栏 */
[data-theme-layout^="dtc-"] .dt-cta { width: min(100% - 48px, var(--w-wide) - 48px); margin: 4rem auto; scroll-margin-top: 90px; }
[data-theme-layout^="dtc-"] .dt-cta-inner { padding: clamp(2.4rem, 5vw, 4rem) clamp(1.4rem, 4vw, 3rem); border-radius: calc(var(--radius) * 1.5); background: var(--accent-wash); text-align: center; }
[data-theme-layout^="dtc-"] .dt-cta h2 { margin: 0 0 .7rem; font-family: var(--dt-display, var(--serif)); font-size: clamp(1.7rem, 3.4vw, 2.5rem); font-weight: 650; letter-spacing: -.01em; }
[data-theme-layout^="dtc-"] .dt-cta-note { max-width: 52ch; margin: 0 auto 1.6rem; color: var(--muted); font-size: .98rem; line-height: 1.8; }
[data-theme-layout^="dtc-"] .dt-cta-actions { justify-content: center; }

/* 生成块 / 空态 / 内嵌 SVG */
[data-theme-layout^="dtc-"] .dt-gen { background: var(--accent-wash); }
[data-theme-layout^="dtc-"] .dt-gen b { font-family: var(--dt-display, var(--serif)); font-size: 2.6rem; color: var(--accent); }
[data-theme-layout^="dtc-"] .dt-empty { grid-column: 1 / -1; margin: 0; padding: 1.8rem; border: 1px dashed var(--line); border-radius: var(--radius); text-align: center; }
[data-theme-layout^="dtc-"] .dt-embed svg { display: block; width: 100%; height: auto; }

/* FAQ / 图集 / 卖点 chip：复用工厂 define 的类名，独立站语言重排（发丝线 + 圆角胶囊） */
[data-theme-layout^="dtc-"] .f-faq { border-top: 1px solid var(--line); }
[data-theme-layout^="dtc-"] .f-faq-item { border-bottom: 1px solid var(--line); }
[data-theme-layout^="dtc-"] .f-faq-q { display: flex; align-items: baseline; gap: .75rem; padding: 1.05rem .2rem; font-size: 1rem; font-weight: 650; color: var(--ink); cursor: pointer; list-style: none; }
[data-theme-layout^="dtc-"] .f-faq-q::-webkit-details-marker { display: none; }
[data-theme-layout^="dtc-"] .f-faq-q:hover { color: var(--accent); }
[data-theme-layout^="dtc-"] .f-faq-marker { flex: none; font-family: var(--sans); font-size: .72rem; font-weight: 800; color: var(--accent); }
[data-theme-layout^="dtc-"] .f-faq-caret { flex: none; margin-left: auto; align-self: center; width: 8px; height: 8px; border-right: 2px solid var(--faint); border-bottom: 2px solid var(--faint); transform: rotate(45deg); transition: transform var(--speed); }
[data-theme-layout^="dtc-"] .f-faq-item[open] .f-faq-caret { transform: rotate(-135deg); }
[data-theme-layout^="dtc-"] .f-faq-a { margin: 0; padding: 0 .2rem 1.15rem 1.9rem; max-width: 78ch; color: var(--muted); font-size: .92rem; line-height: 1.8; }
[data-theme-layout^="dtc-"] .f-gallery { display: flex; gap: 1rem; padding-bottom: .6rem; overflow-x: auto; scroll-snap-type: x proximity; scrollbar-width: thin; }
[data-theme-layout^="dtc-"] .f-gallery-item { flex: none; margin: 0; scroll-snap-align: start; border-radius: calc(var(--radius) * 1.2); background: var(--line-soft); overflow: hidden; }
[data-theme-layout^="dtc-"] .f-gallery-item img { display: block; height: clamp(200px, 26vw, 300px); width: auto; max-width: 78vw; object-fit: cover; }
[data-theme-layout^="dtc-"] .f-chips { display: flex; flex-wrap: wrap; gap: .4rem; margin-top: .6rem; min-width: 0; }
[data-theme-layout^="dtc-"] .f-chip { display: inline-flex; align-items: center; gap: .35rem; min-width: 0; max-width: 100%; padding: .22rem .7rem; border: 1px solid var(--line); border-radius: 999px; background: var(--surface); font-family: var(--sans); font-size: .72rem; line-height: 1.5; color: var(--ink-soft); }
[data-theme-layout^="dtc-"] .f-chip b { flex: none; font-weight: 650; color: var(--muted); }
[data-theme-layout^="dtc-"] .f-chip i { font-style: normal; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* ---- DTC 风 hero 轻动画（dtc_hero_anim）：渐变光斑漂移 + 浮动产品卡 ----
   工厂齿轮动画是图纸机械风，与品牌店气质不合；这套克制零 JS、配色全吃主题变量。
   SVG 元素做 transform 动画必须 transform-box: fill-box + origin center，否则绕视口原点转。 */
[data-theme-layout^="dtc-"] .dt-heroanim { display: grid; place-items: center; min-height: 240px; }
[data-theme-layout^="dtc-"] .dt-animsvg { display: block; width: min(100%, 460px); height: auto; }
[data-theme-layout^="dtc-"] .da-blob { transform-box: fill-box; transform-origin: center; filter: blur(26px); }
[data-theme-layout^="dtc-"] .da-blob-a { fill: var(--accent); opacity: .2; animation: daDriftA 14s ease-in-out infinite alternate; }
[data-theme-layout^="dtc-"] .da-blob-b { fill: var(--accent-soft, var(--accent)); opacity: .14; animation: daDriftB 18s ease-in-out infinite alternate; }
[data-theme-layout^="dtc-"] .da-blob-c { fill: var(--accent); opacity: .1; animation: daDriftC 11s ease-in-out infinite alternate; }
[data-theme-layout^="dtc-"] .da-card { transform-box: fill-box; transform-origin: center; animation: daFloat 6s ease-in-out infinite alternate; filter: drop-shadow(0 14px 26px color-mix(in srgb, var(--ink) 14%, transparent)); }
[data-theme-layout^="dtc-"] .da-card-bg { fill: var(--surface); stroke: var(--line); }
[data-theme-layout^="dtc-"] .da-card-img { fill: var(--accent-wash); }
[data-theme-layout^="dtc-"] .da-card-dot { fill: var(--accent); opacity: .8; }
[data-theme-layout^="dtc-"] .da-line { fill: var(--line); }
[data-theme-layout^="dtc-"] .da-line.a { fill: var(--ink); opacity: .82; }
[data-theme-layout^="dtc-"] .da-pill { fill: var(--accent); }
[data-theme-layout^="dtc-"] .da-chip { transform-box: fill-box; transform-origin: center; animation: daFloat 7.5s ease-in-out 1.2s infinite alternate-reverse; }
[data-theme-layout^="dtc-"] .da-chip-bg { fill: var(--surface); stroke: var(--line); }
[data-theme-layout^="dtc-"] .da-chip-dot { fill: var(--accent); }
[data-theme-layout^="dtc-"] .da-chip-line { fill: var(--line); }
[data-theme-layout^="dtc-"] .da-spark { fill: var(--accent); opacity: .45; transform-box: fill-box; transform-origin: center; animation: daPulse 3.6s ease-in-out infinite; }
@keyframes daDriftA { to { transform: translate(26px, 20px) scale(1.08); } }
@keyframes daDriftB { to { transform: translate(-30px, -16px) scale(1.05); } }
@keyframes daDriftC { to { transform: translate(14px, -22px); } }
@keyframes daFloat { to { transform: translateY(-12px); } }
@keyframes daPulse { 50% { opacity: .12; transform: scale(.68); } }
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout^="dtc-"] .da-blob, [data-theme-layout^="dtc-"] .da-card,
  [data-theme-layout^="dtc-"] .da-chip, [data-theme-layout^="dtc-"] .da-spark { animation: none; }
}

/* ---- dtc-flagship 骨架（df-*）：品牌旗舰——大留白、系列大卡、方图商品栅格 ---- */
[data-theme-layout="dtc-flagship"] .df-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-flagship"] .df-hero { position: relative; margin-top: 1.6rem; border-radius: calc(var(--radius) * 1.5); background: linear-gradient(135deg, var(--accent-wash), var(--surface)); overflow: hidden; }
[data-theme-layout="dtc-flagship"] .df-hero-inner { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(280px, .95fr); align-items: center; gap: clamp(1.2rem, 3vw, 2.6rem); padding: clamp(2.2rem, 5vw, 4rem); }
[data-theme-layout="dtc-flagship"] .df-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-flagship"] .df-hero.has-img { min-height: min(72vh, 560px); display: flex; align-items: flex-end; }
/* 压图 scrim：左列（文案区）+ 底部双向压暗——白字要在任意亮度的用户图上可读 */
[data-theme-layout="dtc-flagship"] .df-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(102deg, rgba(10,10,12,.66) 0%, rgba(10,10,12,.4) 46%, rgba(10,10,12,.05) 74%), linear-gradient(200deg, rgba(10,10,12,0) 42%, rgba(10,10,12,.5) 96%); }
[data-theme-layout="dtc-flagship"] .df-hero.has-img .df-hero-inner { position: relative; z-index: 1; grid-template-columns: minmax(0, 1fr); }
[data-theme-layout="dtc-flagship"] .df-hero.has-img .df-hero-copy { color: #fff; }
[data-theme-layout="dtc-flagship"] .df-hero.has-img .dt-eyebrow { color: #fff; opacity: .82; }
[data-theme-layout="dtc-flagship"] .df-hero.has-img .df-h1 { color: #fff; } /* 全局 h1 色规则会盖过容器继承，压图必须显式白字 */
[data-theme-layout="dtc-flagship"] .df-hero.has-img .df-lede { color: rgba(255,255,255,.85); }
[data-theme-layout="dtc-flagship"] .df-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-flagship"] .df-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-flagship"] .df-hero.has-img .btn-primary { background: #fff; border-color: #fff; color: #14151a; }
[data-theme-layout="dtc-flagship"] .df-h1 { margin: 0; max-width: 15em; font-family: var(--dt-display, var(--serif)); font-size: clamp(2.1rem, 4.6vw, 3.4rem); font-weight: 650; line-height: 1.12; letter-spacing: -.015em; }
[data-theme-layout="dtc-flagship"] .df-lede { max-width: 56ch; margin: 1rem 0 0; color: var(--muted); font-size: 1.02rem; line-height: 1.8; }
[data-theme-layout="dtc-flagship"] .df-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.8rem; }
[data-theme-layout="dtc-flagship"] .df-hero-side { min-width: 0; }
[data-theme-layout="dtc-flagship"] .df-section { padding-top: clamp(3rem, 6vw, 4.5rem); }
[data-theme-layout="dtc-flagship"] .df-series-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(250px, 100%), 1fr)); gap: 1rem; }
[data-theme-layout="dtc-flagship"] .df-series-card { position: relative; display: flex; flex-direction: column; min-width: 0; border-radius: calc(var(--radius) * 1.2); background: var(--surface); border: 1px solid var(--line); color: var(--ink); overflow: hidden; transition: transform var(--speed), box-shadow var(--speed), border-color var(--speed); }
[data-theme-layout="dtc-flagship"] .df-series-card:hover { transform: translateY(-3px); border-color: var(--accent); box-shadow: var(--shadow); color: var(--ink); }
[data-theme-layout="dtc-flagship"] .df-series-media { display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-flagship"] .df-series-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-flagship"] .df-series-card:hover .df-series-media img { transform: scale(1.04); }
[data-theme-layout="dtc-flagship"] .df-series-body { display: flex; flex-direction: column; gap: .15rem; padding: 1rem 1.1rem 1.05rem; }
[data-theme-layout="dtc-flagship"] .df-series-name { font-family: var(--dt-display, var(--serif)); font-size: 1.12rem; font-weight: 650; }
[data-theme-layout="dtc-flagship"] .df-series-count { color: var(--muted); font-size: .8rem; }
[data-theme-layout="dtc-flagship"] .df-series-card > .arrow { position: absolute; right: 1rem; bottom: 1.1rem; color: var(--faint); transition: color var(--speed), transform var(--speed); }
[data-theme-layout="dtc-flagship"] .df-series-card:hover > .arrow { color: var(--accent); transform: translateX(3px); }
[data-theme-layout="dtc-flagship"] .df-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(210px, 100%), 1fr)); gap: 1.1rem; }
[data-theme-layout="dtc-flagship"] .df-card { display: flex; min-width: 0; flex-direction: column; color: var(--ink); }
[data-theme-layout="dtc-flagship"] .df-card-media { display: grid; place-items: center; aspect-ratio: 1 / 1; border-radius: calc(var(--radius) * 1.2); background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-flagship"] .df-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-flagship"] .df-card:hover .df-card-media img { transform: scale(1.05); }
[data-theme-layout="dtc-flagship"] .df-card:hover { color: var(--ink); }
[data-theme-layout="dtc-flagship"] .df-card-body { display: flex; flex-direction: column; gap: .2rem; padding: .8rem .15rem 0; }
[data-theme-layout="dtc-flagship"] .df-card-cat { color: var(--accent); font-size: .72rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-flagship"] .df-card-title { font-size: .98rem; font-weight: 650; line-height: 1.45; }
[data-theme-layout="dtc-flagship"] .df-card:hover .df-card-title { color: var(--accent); }
[data-theme-layout="dtc-flagship"] .df-card-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .82rem; line-height: 1.6; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="dtc-flagship"] .df-story .dt-stats { grid-template-columns: repeat(auto-fit, minmax(min(170px, 100%), 1fr)); }
[data-theme-layout="dtc-flagship"] .df-about { max-width: 64ch; margin: 0; font-family: var(--dt-display, var(--serif)); font-size: clamp(1.05rem, 1.8vw, 1.3rem); line-height: 2; color: var(--ink-soft); }

/* ---- dtc-solo 骨架（ds-*）：单品爆款——超大标题、左右交替卖点、规格表、长转化流 ---- */
[data-theme-layout="dtc-solo"] .ds-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-solo"] .ds-hero { display: grid; grid-template-columns: minmax(0, 1.02fr) minmax(300px, .98fr); align-items: center; gap: clamp(1.4rem, 4vw, 3rem); padding: clamp(2.4rem, 6vw, 4.5rem) 0 1rem; }
[data-theme-layout="dtc-solo"] .ds-h1 { margin: 0; font-family: var(--dt-display, var(--sans)); font-size: clamp(2.2rem, 5vw, 3.6rem); font-weight: 800; line-height: 1.08; letter-spacing: -.02em; }
[data-theme-layout="dtc-solo"] .ds-lede { max-width: 54ch; margin: 1.1rem 0 0; color: var(--muted); font-size: 1.05rem; line-height: 1.8; }
[data-theme-layout="dtc-solo"] .ds-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.8rem; }
[data-theme-layout="dtc-solo"] .ds-cta .btn-primary { padding: .75rem 1.6rem; font-size: 1rem; }
[data-theme-layout="dtc-solo"] .ds-hero-chips { margin-top: 1.1rem; }
[data-theme-layout="dtc-solo"] .ds-hero-visual { min-width: 0; border-radius: calc(var(--radius) * 1.5); background: var(--accent-wash); overflow: hidden; }
/* 有图：去底板不裁剪——裸图 + 轻阴影，按图片自身比例限高渲染（竖图横图都不裁）；
   动画/SVG 态维持 accent-wash 底色卡现状。 */
[data-theme-layout="dtc-solo"] .ds-hero-visual.has-img { background: none; border-radius: 0; overflow: visible; }
[data-theme-layout="dtc-solo"] .ds-hero-img { display: block; width: auto; max-width: 100%; height: auto; max-height: clamp(320px, 46vw, 560px); margin-inline: auto; border-radius: calc(var(--radius) * 1.5); }
[data-theme-layout="dtc-solo"] .ds-hero-visual .dt-heroanim { padding: 1.4rem; }
[data-theme-layout="dtc-solo"] .ds-empty { margin-top: 2rem; }
[data-theme-layout="dtc-solo"] .ds-section { padding-top: clamp(3rem, 6vw, 4.5rem); }
[data-theme-layout="dtc-solo"] .ds-point { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: center; gap: clamp(1.2rem, 3.5vw, 3rem); margin-top: 2.2rem; }
[data-theme-layout="dtc-solo"] .ds-point-list .ds-point:first-child { margin-top: 0; }
[data-theme-layout="dtc-solo"] .ds-point-list .ds-point:nth-child(even) .ds-point-media { order: 2; }
[data-theme-layout="dtc-solo"] .ds-point-media { margin: 0; aspect-ratio: 4 / 3; border-radius: calc(var(--radius) * 1.5); background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-solo"] .ds-point-media img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-solo"] .ds-point-num { display: block; margin-bottom: .5rem; color: var(--accent); font-family: var(--sans); font-size: .82rem; font-weight: 800; letter-spacing: .16em; }
[data-theme-layout="dtc-solo"] .ds-point-copy h3 { margin: 0 0 .6rem; font-family: var(--dt-display, var(--sans)); font-size: clamp(1.3rem, 2.4vw, 1.75rem); font-weight: 720; letter-spacing: -.01em; }
[data-theme-layout="dtc-solo"] .ds-point-copy p { max-width: 46ch; margin: 0; color: var(--muted); font-size: .98rem; line-height: 1.85; }
[data-theme-layout="dtc-solo"] .ds-stats-sec .dt-stats { grid-template-columns: repeat(auto-fit, minmax(min(160px, 100%), 1fr)); }
[data-theme-layout="dtc-solo"] .ds-spec-table { max-width: 760px; margin: 0; border-top: 1px solid var(--line); }
[data-theme-layout="dtc-solo"] .ds-spec-row { display: grid; grid-template-columns: minmax(120px, 220px) minmax(0, 1fr); gap: 1rem; padding: .85rem .2rem; border-bottom: 1px solid var(--line); }
[data-theme-layout="dtc-solo"] .ds-spec-row dt { margin: 0; color: var(--muted); font-size: .9rem; }
[data-theme-layout="dtc-solo"] .ds-spec-row dd { margin: 0; min-width: 0; overflow-wrap: anywhere; color: var(--ink); font-size: .93rem; font-weight: 550; }
[data-theme-layout="dtc-solo"] .ds-scene-row { display: flex; gap: 1rem; padding-bottom: .6rem; overflow-x: auto; scroll-snap-type: x proximity; scrollbar-width: thin; }
[data-theme-layout="dtc-solo"] .ds-scene { flex: none; margin: 0; scroll-snap-align: start; border-radius: calc(var(--radius) * 1.2); background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-solo"] .ds-scene img { display: block; height: clamp(200px, 26vw, 300px); width: auto; max-width: 78vw; object-fit: cover; }

/* ---- dtc-lookbook 骨架（dl-*）：系列画册——大图墙、系列陈列、悬停出品名、极少文字 ---- */
[data-theme-layout="dtc-lookbook"] .dl-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-lookbook"] .dl-masthead { max-width: 720px; margin: 0 auto; padding: clamp(2.4rem, 6vw, 4.2rem) 0 clamp(1.6rem, 4vw, 2.8rem); text-align: center; }
[data-theme-layout="dtc-lookbook"] .dl-masthead .dt-eyebrow { margin-bottom: .9rem; }
[data-theme-layout="dtc-lookbook"] .dl-h1 { margin: 0; font-family: var(--dt-display, var(--serif)); font-size: clamp(2rem, 4.4vw, 3.1rem); font-weight: 600; line-height: 1.15; letter-spacing: -.01em; }
[data-theme-layout="dtc-lookbook"] .dl-lede { max-width: 54ch; margin: 1rem auto 0; color: var(--muted); font-size: .98rem; line-height: 1.8; }
[data-theme-layout="dtc-lookbook"] .dl-wall { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(260px, 100%), 1fr)); gap: 10px; }
[data-theme-layout="dtc-lookbook"] .dl-wall-item { position: relative; margin: 0; aspect-ratio: 4 / 5; border-radius: var(--radius); background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-lookbook"] .dl-wall-item img { width: 100%; height: 100%; object-fit: cover; transition: transform .35s ease; }
[data-theme-layout="dtc-lookbook"] .dl-wall-item:hover img { transform: scale(1.03); }
[data-theme-layout="dtc-lookbook"] .dl-series { padding-top: clamp(2.8rem, 5.5vw, 4rem); }
[data-theme-layout="dtc-lookbook"] .dl-series-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; margin-bottom: 1.1rem; }
[data-theme-layout="dtc-lookbook"] .dl-series-head h2 { margin: 0; font-family: var(--dt-display, var(--serif)); font-size: clamp(1.3rem, 2.2vw, 1.7rem); font-weight: 620; letter-spacing: -.01em; }
[data-theme-layout="dtc-lookbook"] .dl-series-head a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="dtc-lookbook"] .dl-series-head a:hover { color: var(--accent); }
[data-theme-layout="dtc-lookbook"] .dl-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(190px, 100%), 1fr)); gap: 10px; }
[data-theme-layout="dtc-lookbook"] .dl-tile { position: relative; display: block; aspect-ratio: 4 / 5; border-radius: var(--radius); background: var(--line-soft); overflow: hidden; color: var(--ink); }
[data-theme-layout="dtc-lookbook"] .dl-tile img { width: 100%; height: 100%; object-fit: cover; transition: transform .35s ease; }
[data-theme-layout="dtc-lookbook"] .dl-tile:hover img { transform: scale(1.04); }
[data-theme-layout="dtc-lookbook"] .dl-tile-gen { display: grid; place-items: center; width: 100%; height: 100%; background: var(--accent-wash); color: var(--accent); font-family: var(--dt-display, var(--serif)); font-size: 2.4rem; }
[data-theme-layout="dtc-lookbook"] .dl-tile-name { position: absolute; right: 0; bottom: 0; left: 0; padding: 1.6rem .8rem .7rem; background: linear-gradient(rgba(10,10,12,0), rgba(10,10,12,.58)); color: #fff; font-size: .84rem; font-weight: 600; line-height: 1.4; opacity: 0; transition: opacity .2s ease; }
[data-theme-layout="dtc-lookbook"] .dl-tile:hover .dl-tile-name,
[data-theme-layout="dtc-lookbook"] .dl-tile:focus-visible .dl-tile-name { opacity: 1; }
@media (hover: none) { /* 触屏没有悬停：品名常显，别把信息藏死 */
  [data-theme-layout="dtc-lookbook"] .dl-tile-name { opacity: 1; }
}
[data-theme-layout="dtc-lookbook"] .dl-empty { margin-top: 1.5rem; }
[data-theme-layout="dtc-lookbook"] .dt-cta-inner { border-radius: var(--radius); } /* 画册极简：CTA 圆角跟皮肤（galleria/blackbox=0） */

/* ---- DTC 响应式：中屏折单列，375 无横向溢出（图带/表格各自内滚） ---- */
@media (max-width: 900px) {
  [data-theme-layout="dtc-flagship"] .df-hero-inner { grid-template-columns: 1fr; padding: clamp(1.6rem, 5vw, 2.6rem); }
  [data-theme-layout="dtc-flagship"] .df-hero-side { max-width: 420px; }
  [data-theme-layout="dtc-solo"] .ds-hero { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-solo"] .ds-point { grid-template-columns: 1fr; gap: 1rem; }
  [data-theme-layout="dtc-solo"] .ds-point-list .ds-point:nth-child(even) .ds-point-media { order: 0; }
  [data-theme-layout^="dtc-"] .dt-head { flex-direction: column; align-items: flex-start; gap: .35rem; }
}
@media (max-width: 560px) {
  [data-theme-layout^="dtc-"] .dt-stats { grid-template-columns: 1fr 1fr; }
  [data-theme-layout^="dtc-"] .dt-testis { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-flagship"] .df-grid { grid-template-columns: 1fr 1fr; gap: .8rem; }
  [data-theme-layout="dtc-flagship"] .df-hero.has-img { min-height: 62vh; }
  [data-theme-layout="dtc-solo"] .ds-spec-row { grid-template-columns: 1fr; gap: .15rem; }
  [data-theme-layout="dtc-lookbook"] .dl-wall { grid-template-columns: 1fr 1fr; gap: 8px; }
  [data-theme-layout="dtc-lookbook"] .dl-grid { grid-template-columns: 1fr 1fr; gap: 8px; }
}

/* ============================================================================
   DTC 皮肤 ×12（各骨架 ×4）。全部变量成套覆写（:root[data-theme=…] 特异度高于
   基础 :root 的深色媒体查询，皮肤在 OS 亮/暗模式下都锁定自己的调色板）；
   accent 均按各自 --bg 通过 4.5:1 小字对比（与 web.go themeAccentDefault 同步）。
   ========================================================================== */

/* ---- 奶油白 · Cream（dtc-flagship）：奶油纸底 + 暖近黑，净白系语言的品牌店 ---- */
:root[data-theme="cream"] {
  --bg: #fdfbf6; --surface: #ffffff; --ink: #241f19; --ink-soft: #4c4438;
  --muted: #7a7267; --faint: #a59c8e; --line: #e9e3d7; --line-soft: #f4f0e6;
  --accent: #4a3f35; --accent-soft: #6a5c4b; --accent-wash: #f1ebdf;
  --radius: 14px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(36,31,25,.05), 0 10px 28px rgba(36,31,25,.07);
}

/* ---- 琥珀暖调 · Amberglow（dtc-flagship）：暖琥珀纸底 + 蜜糖橙点缀、衬线大标题 ---- */
:root[data-theme="amberglow"] {
  --bg: #faf3e8; --surface: #fffdf9; --ink: #2c2116; --ink-soft: #52402c;
  --muted: #7d6b56; --faint: #a8977f; --line: #ecdfc9; --line-soft: #f5ecdc;
  --accent: #9a5a14; --accent-soft: #c07a2e; --accent-wash: #f6e7cf;
  --radius: 16px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(44,33,22,.05), 0 10px 28px rgba(44,33,22,.08);
}

/* ---- 墨蓝 · Ink Navy（dtc-flagship，暗）：墨蓝深底 + 香槟金点睛、高级感夜场 ---- */
:root[data-theme="inknavy"] {
  --bg: #0e1420; --surface: #141c2c; --ink: #e9e4d8; --ink-soft: #c6c0b0;
  --muted: #9aa2b4; --faint: #6b7386; --line: #263043; --line-soft: #1a2334;
  --accent: #d3b078; --accent-soft: #e2c693; --accent-wash: #1d2537;
  --radius: 12px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(0,0,0,.4), 0 12px 32px rgba(0,0,0,.42);
}
:root[data-theme="inknavy"] .df-hero.has-img .btn-primary { background: var(--accent); border-color: var(--accent); color: #14161c; }

/* ---- 橄榄绿 · Oliveleaf（dtc-flagship）：米纸底 + 橄榄绿、圆角大卡的自然系 ---- */
:root[data-theme="oliveleaf"] {
  --bg: #f4f4ec; --surface: #fcfcf7; --ink: #242820; --ink-soft: #474d3d;
  --muted: #676d5e; --faint: #939a88; --line: #e0e2d3; --line-soft: #ecede1;
  --accent: #556740; --accent-soft: #6d8054; --accent-wash: #e8ecdb;
  --radius: 18px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(36,40,32,.05), 0 10px 28px rgba(36,40,32,.07);
}

/* ---- 晨白 · Dawnfair（dtc-flagship）：Shopify 默认店（Dawn）气质——纯白底 +
   系统无衬线细字重大标题、发丝线分隔、细描边按钮悬停反转、商品/系列卡无框无阴影、
   全局零圆角。accent=近黑 #121212（白底 17.9:1，随便过 4.5:1）。 ---- */
:root[data-theme="dawnfair"] {
  --bg: #ffffff; --surface: #ffffff; --ink: #121212; --ink-soft: #3a3a3a;
  --muted: #707070; --faint: #a3a3a3; --line: #e8e8e8; --line-soft: #f6f6f6;
  --accent: #121212; --accent-soft: #3a3a3a; --accent-wash: #f6f6f6;
  --radius: 0px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(18,18,18,.04), 0 8px 22px rgba(18,18,18,.05);
  /* Dawn 通体系统无衬线：连列表/详情等吃 --serif 的标题也一并转 sans（同 lucid 等皮的做法） */
  --serif: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
  --dt-display: var(--sans); /* Dawn：大标题走系统无衬线 */
}
/* 细字重排版：巨题/区块头/数字/CTA 全降字重、放松字距（Dawn 的轻盈大字） */
:root[data-theme="dawnfair"] .df-h1 { font-weight: 420; letter-spacing: .01em; }
:root[data-theme="dawnfair"] .dt-head h2, :root[data-theme="dawnfair"] .dt-cta h2 { font-weight: 440; letter-spacing: .01em; }
:root[data-theme="dawnfair"] .dt-stat dt { font-weight: 440; }
:root[data-theme="dawnfair"] .df-series-name { font-weight: 480; }
:root[data-theme="dawnfair"] .df-card-title { font-weight: 480; }
:root[data-theme="dawnfair"] .dt-eyebrow { font-weight: 550; letter-spacing: .14em; }
/* 按钮=细描边黑字，悬停反转（黑底白字）；直角压过族内胶囊规则 */
:root[data-theme="dawnfair"] .btn, :root[data-theme="dawnfair"] .inquiry-btn { border-radius: 0; }
:root[data-theme="dawnfair"] .btn-primary,
:root[data-theme="dawnfair"] .inquiry-btn.inquiry-wa { background: transparent; border: 1px solid var(--ink); color: var(--ink); }
:root[data-theme="dawnfair"] .btn-primary:hover,
:root[data-theme="dawnfair"] .inquiry-btn.inquiry-wa:hover { background: var(--ink); border-color: var(--ink); color: #fff; box-shadow: none; }
/* 商品/系列卡无框无阴影：图 + 名 + 说明三行，靠留白分隔；悬停只保留图片微缩放 */
:root[data-theme="dawnfair"] .df-series-card { border: 0; background: transparent; overflow: visible; }
:root[data-theme="dawnfair"] .df-series-card:hover { transform: none; box-shadow: none; }
:root[data-theme="dawnfair"] .df-series-body { padding: .8rem .1rem 0; }
:root[data-theme="dawnfair"] .df-series-card > .arrow { right: .2rem; bottom: .3rem; }
/* 数字/评价卡也走发丝线（--line 已是发丝灰）；hero 无图态的渐变底收成纯白 + 发丝线圈边 */
:root[data-theme="dawnfair"] .df-hero { background: var(--surface); border: 1px solid var(--line); }
:root[data-theme="dawnfair"] .dt-cta-inner { background: var(--surface); border: 1px solid var(--line); }

/* ---- 纯白 · Solo White（dtc-solo）：纯白 + 靛蓝转化按钮、超大标题的单品长页 ---- */
:root[data-theme="solowhite"] {
  --bg: #ffffff; --surface: #ffffff; --ink: #17181c; --ink-soft: #3c3f46;
  --muted: #6b7078; --faint: #9a9fa7; --line: #e8e9ec; --line-soft: #f4f5f7;
  --accent: #2f56d9; --accent-soft: #5273e2; --accent-wash: #edf1fd;
  --radius: 12px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(23,24,28,.05), 0 10px 28px rgba(23,24,28,.07);
}
/* 纯白单品：主按钮走靛蓝（转化色即品牌色；白字 6.1:1 过审） */
:root[data-theme="solowhite"] .btn-primary,
:root[data-theme="solowhite"] .inquiry-btn.inquiry-wa { background: var(--accent); border-color: var(--accent); color: #fff; }
:root[data-theme="solowhite"] .btn-primary:hover,
:root[data-theme="solowhite"] .inquiry-btn.inquiry-wa:hover { background: var(--accent); border-color: var(--accent); color: #fff; }

/* ---- 炭黑 · Charcoal（dtc-solo，暗）：炭黑底 + 琥珀金 CTA 的暗色发布页 ---- */
:root[data-theme="charcoal"] {
  --bg: #17181a; --surface: #1f2124; --ink: #eceae4; --ink-soft: #c9c6bd;
  --muted: #a4a49c; --faint: #77786f; --line: #32343a; --line-soft: #232529;
  --accent: #e8b64c; --accent-soft: #f0c86e; --accent-wash: #2a2617;
  --radius: 12px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(0,0,0,.4), 0 12px 32px rgba(0,0,0,.42);
}
/* 炭黑：主按钮走琥珀金 + 近黑字（金底白字不过审，金底黑字 8+:1） */
:root[data-theme="charcoal"] .btn-primary,
:root[data-theme="charcoal"] .inquiry-btn.inquiry-wa { background: var(--accent); border-color: var(--accent); color: #17181a; }
:root[data-theme="charcoal"] .btn-primary:hover,
:root[data-theme="charcoal"] .inquiry-btn.inquiry-wa:hover { background: var(--accent); border-color: var(--accent); color: #17181a; }

/* ---- 珊瑚 · Coral Pop（dtc-solo）：奶白底 + 珊瑚橙、大圆角的元气单品 ---- */
:root[data-theme="coralpop"] {
  --bg: #fff6f2; --surface: #ffffff; --ink: #2a211e; --ink-soft: #55443e;
  --muted: #7d6f6a; --faint: #a8968f; --line: #f2ded6; --line-soft: #faece6;
  --accent: #c73a22; --accent-soft: #e8543c; --accent-wash: #ffe9e1;
  --radius: 18px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(42,33,30,.05), 0 10px 28px rgba(42,33,30,.08);
}
/* 珊瑚：主按钮走珊瑚红（白字 4.86:1 过审） */
:root[data-theme="coralpop"] .btn-primary,
:root[data-theme="coralpop"] .inquiry-btn.inquiry-wa { background: var(--accent); border-color: var(--accent); color: #fff; }
:root[data-theme="coralpop"] .btn-primary:hover,
:root[data-theme="coralpop"] .inquiry-btn.inquiry-wa:hover { background: var(--accent); border-color: var(--accent); color: #fff; }

/* ---- 石灰绿 · Limewash（dtc-solo）：浅灰绿底 + 苔绿、粗衬线标题的自然清爽单品 ---- */
:root[data-theme="limewash"] {
  --bg: #f2f6ee; --surface: #fbfdf8; --ink: #232920; --ink-soft: #45503c;
  --muted: #68715f; --faint: #949e8a; --line: #dde5d4; --line-soft: #eaf0e3;
  --accent: #4c7136; --accent-soft: #61854a; --accent-wash: #e5eedb;
  --radius: 14px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(35,41,32,.05), 0 10px 28px rgba(35,41,32,.07);
  --dt-display: var(--serif); /* 单品骨架默认无衬线大字，这皮要粗衬线标题 */
}

/* ---- 画廊白 · Galleria（dtc-lookbook）：画廊纯白 + 近黑细字、零圆角 ---- */
:root[data-theme="galleria"] {
  --bg: #fafafa; --surface: #ffffff; --ink: #171717; --ink-soft: #3d3d3d;
  --muted: #6d6d6d; --faint: #9c9c9c; --line: #e7e7e7; --line-soft: #f2f2f2;
  --accent: #2b2b2b; --accent-soft: #4a4a4a; --accent-wash: #efefef;
  --radius: 0px; --w-wide: 1240px; --shadow: 0 1px 2px rgba(23,23,23,.05), 0 10px 28px rgba(23,23,23,.06);
}

/* ---- 暗厅 · Blackbox（dtc-lookbook，暗）：近黑展墙 + 暖金展签的夜场画册 ---- */
:root[data-theme="blackbox"] {
  --bg: #0c0c0e; --surface: #131316; --ink: #eae6dd; --ink-soft: #c6c1b6;
  --muted: #a09c92; --faint: #726f67; --line: #27272b; --line-soft: #19191c;
  --accent: #cbb27e; --accent-soft: #dcc697; --accent-wash: #201d15;
  --radius: 0px; --w-wide: 1240px; --shadow: 0 1px 2px rgba(0,0,0,.45), 0 12px 32px rgba(0,0,0,.5);
}

