  top:auto;
  background:var(--bg);
  border-bottom:1px solid var(--line);
  backdrop-filter:none;
}
:is([data-theme^="field-ledger"],[data-theme^="signal-archive"],[data-theme^="night-watch"]) .ct-header-grid {
  display:grid;
