  margin:0;
}
[data-theme^="paper-current"] .pc-article-grid.has-toc .toc {
  position:sticky;
  top:24px;
}
[data-theme^="paper-current"] .pc-article-grid.has-toc :is(.article-foot,.pager) {
  grid-column:1 / -1;
}
[data-theme^="paper-current"] .pc-article-grid .article-col {
  padding-bottom:clamp(72px,7vw,96px);
}
[data-theme^="paper-current"] .article-head {
  text-align:center;
}
[data-theme^="paper-current"] .article-head h1 {
  margin:0 auto 18px;
  font:clamp(2.8rem,4.7vw,4.7rem)/1.04 var(--serif);
  letter-spacing:-.04em;
}
[data-theme^="paper-current"] .article-head .lead {
  margin-right:auto;
  margin-left:auto;
}
[data-theme^="paper-current"] .byline {
  justify-content:center;
}
[data-theme^="paper-current"] .prose {
  font-family:var(--serif);
  font-size:1.08rem;
  line-height:2;
}
[data-theme^="paper-current"] .prose :is(code,pre,figcaption) {
  font-family:var(--mono);
}
[data-theme^="paper-current"] .post-item h3,
[data-theme^="paper-current"] .lc-title {
  font-family:var(--serif);
}
[data-theme^="paper-current"] .notfound .code {
  color:var(--accent);
  opacity:.9;
}

/* Night Watch 内页：暗色观察站、粗体标题与证据表格。 */
[data-theme^="night-watch"] .page-head h1 {
  max-width:13ch;
  margin:0 0 12px;
  font:800 clamp(3.4rem,6.4vw,6.6rem)/.93 var(--sans);
  letter-spacing:-.055em;
}
[data-theme^="night-watch"] .article-head {
  border-bottom-color:var(--line);
}
[data-theme^="night-watch"] .article-head h1 {
  margin:0 0 18px;
  font:800 clamp(3rem,5.6vw,5.8rem)/.95 var(--sans);
  letter-spacing:-.055em;
}
[data-theme^="night-watch"] .article-cover {
  filter:grayscale(1) contrast(1.15);
  opacity:.82;
}
[data-theme^="night-watch"] .prose h2,
[data-theme^="night-watch"] .prose h3,
[data-theme^="night-watch"] .post-item h3,
[data-theme^="night-watch"] .lc-title,
[data-theme^="night-watch"] .related h2 {
  font-family:var(--sans);
}
[data-theme^="night-watch"] .prose pre {
  border:1px solid var(--line);
  background:var(--surface);
}
[data-theme^="night-watch"] .post-item {
  grid-template-columns:72px minmax(0,1fr);
}
[data-theme^="night-watch"] .post-item .num {
  color:var(--accent);
  font:1.2rem var(--mono);
}
[data-theme^="night-watch"] .link-card,
[data-theme^="night-watch"] .related-grid .card,
[data-theme^="night-watch"] .searchbox input {
  background:var(--surface);
}
[data-theme^="night-watch"] .notfound .code {
  color:var(--accent);
  font-family:var(--mono);
  opacity:1;
}

@media (max-width:900px) {
  :is([data-theme^="field-ledger"],[data-theme^="signal-archive"],[data-theme^="paper-current"],[data-theme^="night-watch"]) .link-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
  :is([data-theme^="field-ledger"],[data-theme^="signal-archive"],[data-theme^="paper-current"],[data-theme^="night-watch"]) .article-grid.has-toc { grid-template-columns:minmax(0,760px); }
  [data-theme^="signal-archive"] .page-head .wrap { display:block; }
  [data-theme^="signal-archive"] .page-head > .wrap > p:last-child:not(.eyebrow) { padding:0; border:0; }
}

@media (max-width:1100px) {
  [data-theme^="paper-current"] .pc-article-grid.has-toc .article-main {
    grid-template-columns:minmax(0,760px);
  }
  [data-theme^="paper-current"] .pc-article-grid.has-toc .toc-rail {
    grid-column:1;
    grid-row:1;
    align-self:start;
    margin-bottom:1.6rem;
  }
  [data-theme^="paper-current"] .pc-article-grid.has-toc .toc {
    position:static;
  }
  [data-theme^="paper-current"] .pc-article-grid.has-toc .article-reading {
    grid-column:1;
    grid-row:2;
  }
}

@media (max-width:600px) {
  :is([data-theme^="field-ledger"],[data-theme^="signal-archive"],[data-theme^="paper-current"],[data-theme^="night-watch"]) .page-head { padding:36px 0 26px; }
  :is([data-theme^="field-ledger"],[data-theme^="signal-archive"],[data-theme^="paper-current"],[data-theme^="night-watch"]) .page-head h1 { font-size:clamp(2.8rem,15vw,4.4rem); }
  :is([data-theme^="field-ledger"],[data-theme^="signal-archive"],[data-theme^="paper-current"],[data-theme^="night-watch"]) .post-item { grid-template-columns:48px minmax(0,1fr); gap:14px; }
  :is([data-theme^="field-ledger"],[data-theme^="signal-archive"],[data-theme^="paper-current"],[data-theme^="night-watch"]) .link-grid { grid-template-columns:1fr; }
  :is([data-theme^="field-ledger"],[data-theme^="signal-archive"],[data-theme^="paper-current"],[data-theme^="night-watch"]) .article-head { padding-top:26px; }
  :is([data-theme^="field-ledger"],[data-theme^="signal-archive"],[data-theme^="paper-current"],[data-theme^="night-watch"]) .article-head h1 { font-size:clamp(2.5rem,13vw,4rem); }
}

/* =====================================================================
   Product Design 2026-07：三套彼此独立的内容骨架
   Orbit Index / Column Stage / Type Cascade
   设计图只决定结构与视觉；标题、分类、数量、日期、摘要与封面全部读取既有数据。
   ===================================================================== */

:root[data-theme="orbit-index"] { --bg:#f7f5ef; --surface:#fffdf8; --ink:#0e1012; --ink-soft:#292d31; --muted:#6e716f; --line:#cfcdc5; --accent:#174ea6; --accent-wash:#e5ecf7; --oi-latest:#c84220; --oi-secondary:#72b7a7; --ct-swatch-1:#174ea6; --ct-swatch-2:#c84220; --ct-swatch-3:#111315; --ct-swatch-4:#72b7a7; --ct-swatch-5:#d9d6ce; --radius:0px; }
:root[data-theme="orbit-index-coral"] { --bg:#fff3ed; --surface:#fffaf6; --ink:#231713; --ink-soft:#4a3029; --muted:#806a61; --line:#e2c9bd; --accent:#d94b2b; --accent-wash:#f8ded4; --oi-latest:#2b6ba6; --oi-secondary:#4e9d87; --ct-swatch-1:#d94b2b; --ct-swatch-2:#2b6ba6; --ct-swatch-3:#231713; --ct-swatch-4:#4e9d87; --ct-swatch-5:#ead2c6; --radius:0px; }
:root[data-theme="orbit-index-forest"] { --bg:#eef4ef; --surface:#f9fcf8; --ink:#13221c; --ink-soft:#2d483c; --muted:#65786f; --line:#c9d7cf; --accent:#347460; --accent-wash:#dcebe3; --oi-latest:#d16833; --oi-secondary:#7e99c7; --ct-swatch-1:#347460; --ct-swatch-2:#d16833; --ct-swatch-3:#13221c; --ct-swatch-4:#7e99c7; --ct-swatch-5:#d6e0d8; --radius:0px; }
:root[data-theme="orbit-index-violet"] { --bg:#f3eff9; --surface:#fcfaff; --ink:#20182e; --ink-soft:#47385e; --muted:#746886; --line:#d8cfe5; --accent:#7452b8; --accent-wash:#e8dff5; --oi-latest:#d25145; --oi-secondary:#4baaa0; --ct-swatch-1:#7452b8; --ct-swatch-2:#d25145; --ct-swatch-3:#20182e; --ct-swatch-4:#4baaa0; --ct-swatch-5:#ded7e7; --radius:0px; }

:root[data-theme="column-stage"] { --bg:#f4f0e7; --surface:#fffdf8; --ink:#101113; --ink-soft:#333438; --muted:#77736b; --line:#c8c2b6; --accent:#c81258; --accent-wash:#f2d8e3; --cs-one:#f4f0e7; --cs-two:#29bfd0; --cs-feature:#c81258; --cs-four:#d4a52e; --cs-five:#0e3157; --ct-swatch-1:#f4ead7; --ct-swatch-2:#c81258; --ct-swatch-3:#29bfd0; --ct-swatch-4:#d4a52e; --ct-swatch-5:#0e3157; --radius:0px; }
:root[data-theme="column-stage-citrus"] { --bg:#fff2df; --surface:#fff9ef; --ink:#24170e; --ink-soft:#543727; --muted:#896d58; --line:#e2c8aa; --accent:#f06a24; --accent-wash:#fae1cf; --cs-one:#fff4df; --cs-two:#68c1a4; --cs-feature:#f06a24; --cs-four:#f2bf32; --cs-five:#55336d; --ct-swatch-1:#fff4df; --ct-swatch-2:#f06a24; --ct-swatch-3:#68c1a4; --ct-swatch-4:#f2bf32; --ct-swatch-5:#55336d; --radius:0px; }
:root[data-theme="column-stage-mineral"] { --bg:#eaf2f1; --surface:#f8fbfa; --ink:#102324; --ink-soft:#28494a; --muted:#61797a; --line:#bfd1cf; --accent:#147c84; --accent-wash:#d3e8e8; --cs-one:#edf1ed; --cs-two:#56a6a6; --cs-feature:#147c84; --cs-four:#b78c54; --cs-five:#173e55; --ct-swatch-1:#edf1ed; --ct-swatch-2:#147c84; --ct-swatch-3:#56a6a6; --ct-swatch-4:#b78c54; --ct-swatch-5:#173e55; --radius:0px; }
:root[data-theme="column-stage-noir"] { --bg:#101315; --surface:#171b1d; --ink:#f1f2eb; --ink-soft:#d4d6ce; --muted:#969d97; --line:#343b3a; --accent:#d8f32f; --accent-wash:#26301a; --cs-one:#e7e5dc; --cs-two:#1b8fa5; --cs-feature:#d8f32f; --cs-four:#b7802b; --cs-five:#111e2d; --ct-swatch-1:#e7e5dc; --ct-swatch-2:#d8f32f; --ct-swatch-3:#1b8fa5; --ct-swatch-4:#b7802b; --ct-swatch-5:#111e2d; --radius:0px; }

:root[data-theme="type-cascade"] { --bg:#fff; --surface:#fff; --ink:#050607; --ink-soft:#27292b; --muted:#6f7374; --line:#cfd1cf; --accent:#b9ec00; --accent-wash:#efffb7; --tc-second:#9878f5; --tc-third:#df3518; --ct-swatch-1:#b9ec00; --ct-swatch-2:#9878f5; --ct-swatch-3:#df3518; --ct-swatch-4:#050607; --ct-swatch-5:#fff; --radius:0px; }
:root[data-theme="type-cascade-cobalt"] { --bg:#f2f5ff; --surface:#fbfcff; --ink:#081127; --ink-soft:#283752; --muted:#66738b; --line:#cbd5e7; --accent:#2e5fd0; --accent-wash:#dce6fb; --tc-second:#8a63e8; --tc-third:#ea5b32; --ct-swatch-1:#2e5fd0; --ct-swatch-2:#8a63e8; --ct-swatch-3:#ea5b32; --ct-swatch-4:#081127; --ct-swatch-5:#fbfcff; --radius:0px; }
:root[data-theme="type-cascade-coral"] { --bg:#fff3ef; --surface:#fffaf7; --ink:#21100b; --ink-soft:#4a2c23; --muted:#806a62; --line:#e4c9be; --accent:#e14624; --accent-wash:#f8ddd3; --tc-second:#7863d8; --tc-third:#1d8f82; --ct-swatch-1:#e14624; --ct-swatch-2:#7863d8; --ct-swatch-3:#1d8f82; --ct-swatch-4:#21100b; --ct-swatch-5:#fffaf7; --radius:0px; }
:root[data-theme="type-cascade-cyan"] { --bg:#edf8f8; --surface:#f9fdfd; --ink:#071d20; --ink-soft:#24474b; --muted:#637e80; --line:#c5dddd; --accent:#17a6b8; --accent-wash:#d3eef1; --tc-second:#6651cd; --tc-third:#e25c2d; --ct-swatch-1:#17a6b8; --ct-swatch-2:#6651cd; --ct-swatch-3:#e25c2d; --ct-swatch-4:#071d20; --ct-swatch-5:#f9fdfd; --radius:0px; }

:is([data-theme^="orbit-index"],[data-theme^="column-stage"],[data-theme^="type-cascade"]) { --w-wide:1487px; }
:is([data-theme^="orbit-index"],[data-theme^="column-stage"],[data-theme^="type-cascade"]) body { background:var(--bg); color:var(--ink); font-size:16px; line-height:1.6; }
:is([data-theme^="orbit-index"],[data-theme^="column-stage"],[data-theme^="type-cascade"]) :is(h1,h2,h3,h4) { color:inherit; }

/* 新主题页头：源设计均为品牌 / 居中导航 / 右侧工具的精确三段结构。 */
:is([data-theme^="orbit-index"],[data-theme^="column-stage"]) .site-header { position:relative; top:auto; z-index:40; background:var(--bg); border-bottom:1px solid var(--line); backdrop-filter:none; }
.oi-header-grid,.cs-header-grid { display:grid; grid-template-columns:minmax(220px,1fr) auto minmax(220px,1fr); gap:24px; align-items:center; height:74px; padding:0 28px; }
.oi-header-brand,.cs-header-brand { justify-self:start; min-width:0; }
:is(.oi-header-brand,.cs-header-brand) .brand { color:var(--ink); font:800 1.08rem/1 var(--sans); letter-spacing:.13em; text-transform:uppercase; }
:is(.oi-header-brand,.cs-header-brand) .brand::before { content:none !important; display:none !important; }
:is(.oi-main-nav,.cs-main-nav) { justify-self:center; gap:clamp(22px,3.4vw,54px); }
:is(.oi-main-nav,.cs-main-nav) a { color:var(--ink); font-size:.76rem; font-weight:650; white-space:nowrap; }
:is(.oi-main-nav,.cs-main-nav) a[aria-current="page"] { color:var(--accent); }
:is(.oi-main-nav,.cs-main-nav) a[aria-current="page"]::after { bottom:-27px; background:var(--accent); }
.oi-header-tools,.cs-header-tools { justify-self:end; display:flex; align-items:center; gap:22px; }
.oi-header-tools > span { width:1px; height:22px; background:var(--line); }
:is(.oi-header-tools,.cs-header-tools) > a { color:var(--ink); font-size:.76rem; font-weight:650; white-space:nowrap; }
:is(.oi-header-tools,.cs-header-tools) .search-ico { display:inline-flex; gap:8px; align-items:center; color:var(--ink); opacity:1; }
:is(.oi-header-tools,.cs-header-tools) .search-label { display:inline; font-size:.76rem; }

/* Orbit Index — 轨道就是导航，不以传统 hero 代替。 */
[data-theme^="orbit-index"] .orbit-index-page { background:var(--bg); }
[data-theme^="orbit-index"] .oi-orbit-shell { position:relative; height:765px; overflow:hidden; border-bottom:1px solid var(--line); }
[data-theme^="orbit-index"] .oi-orbit { position:absolute; left:50%; top:49%; border:1px dashed color-mix(in srgb,var(--muted) 70%,transparent); border-radius:50%; transform:translate(-50%,-50%); pointer-events:none; }
[data-theme^="orbit-index"] .oi-orbit-outer { width:min(78vw,1135px); height:650px; }
[data-theme^="orbit-index"] .oi-orbit-inner { width:min(43vw,620px); height:492px; }
[data-theme^="orbit-index"] .oi-feature { position:absolute; left:50%; top:48%; z-index:3; width:500px; height:450px; padding:44px 48px 0; overflow:hidden; border:2px solid var(--accent); border-radius:50%; background:var(--bg); text-align:center; transform:translate(-50%,-50%); }
[data-theme^="orbit-index"] .oi-feature > small { color:var(--accent); font-size:.72rem; font-weight:800; letter-spacing:.1em; }
[data-theme^="orbit-index"] .oi-feature h1 { max-width:18ch; margin:20px auto 12px; font:750 1.72rem/1.22 var(--sans); letter-spacing:.005em; }
[data-theme^="orbit-index"] .oi-feature h1 a { color:var(--ink); }
[data-theme^="orbit-index"] .oi-feature p { display:-webkit-box; max-width:38ch; margin:0 auto; overflow:hidden; color:var(--ink-soft); font-size:.76rem; line-height:1.68; -webkit-box-orient:vertical; -webkit-line-clamp:3; }
[data-theme^="orbit-index"] .oi-feature time { display:block; margin-top:13px; color:var(--muted); font-size:.68rem; }
[data-theme^="orbit-index"] .oi-feature-cover { position:absolute; left:10%; right:10%; bottom:-2px; height:166px; overflow:hidden; border-radius:50% 50% 0 0 / 100% 100% 0 0; }
[data-theme^="orbit-index"] .oi-feature-cover img { width:100%; height:100%; object-fit:cover; filter:saturate(.72) contrast(1.03); }
[data-theme^="orbit-index"] .oi-category-node { position:absolute; z-index:5; display:grid; grid-template-columns:48px auto; grid-template-rows:auto auto; column-gap:12px; align-items:center; color:var(--ink); }
[data-theme^="orbit-index"] .oi-category-node > span { grid-row:1 / 3; display:grid; place-items:center; width:48px; height:48px; border-radius:50%; background:var(--accent); color:#fff; font:800 1rem var(--sans); }
[data-theme^="orbit-index"] .oi-category-node:nth-child(even) > span { background:var(--oi-secondary); }
[data-theme^="orbit-index"] .oi-category-node b { align-self:end; font-size:.83rem; white-space:nowrap; }
[data-theme^="orbit-index"] .oi-category-node small { align-self:start; color:var(--ink); font-size:.74rem; white-space:nowrap; }
[data-theme^="orbit-index"] .oi-category-node-0 { left:50%; top:25px; transform:translateX(-50%); }
[data-theme^="orbit-index"] .oi-category-node-1 { left:10.5%; top:252px; }
[data-theme^="orbit-index"] .oi-category-node-2 { right:10%; top:280px; }
[data-theme^="orbit-index"] .oi-category-node-3 { left:20%; bottom:133px; }
[data-theme^="orbit-index"] .oi-category-node-4 { right:20%; bottom:115px; }
[data-theme^="orbit-index"] .oi-latest-note { position:absolute; z-index:4; display:flex; width:230px; flex-direction:column; gap:4px; color:var(--ink); font-size:.74rem; line-height:1.45; }
[data-theme^="orbit-index"] .oi-latest-note i { position:absolute; width:12px; height:12px; border:2px solid var(--bg); border-radius:50%; background:var(--oi-latest); box-shadow:0 0 0 1px var(--oi-latest); }
[data-theme^="orbit-index"] .oi-latest-note b { font-weight:650; }
[data-theme^="orbit-index"] .oi-latest-note time { color:var(--muted); font-size:.66rem; }
[data-theme^="orbit-index"] .oi-latest-note-0 { left:21%; top:130px; }
[data-theme^="orbit-index"] .oi-latest-note-0 i { left:25px; top:-20px; }
[data-theme^="orbit-index"] .oi-latest-note-1 { right:18%; top:136px; }
[data-theme^="orbit-index"] .oi-latest-note-1 i { right:14px; top:-22px; }
[data-theme^="orbit-index"] .oi-latest-note-2 { left:18.5%; top:438px; }
[data-theme^="orbit-index"] .oi-latest-note-2 i { right:-6px; top:-8px; }
[data-theme^="orbit-index"] .oi-latest-note-3 { right:18%; top:438px; }
[data-theme^="orbit-index"] .oi-latest-note-3 i { left:-18px; top:-8px; }
[data-theme^="orbit-index"] .oi-latest-note-4 { left:43%; bottom:89px; text-align:center; }
[data-theme^="orbit-index"] .oi-latest-note-4 i { left:-8px; top:2px; }
[data-theme^="orbit-index"] .oi-total { position:absolute; left:50%; bottom:10px; color:var(--accent); font-size:.76rem; font-weight:800; letter-spacing:.08em; transform:translateX(-50%); }
[data-theme^="orbit-index"] .oi-total::after { content:""; position:absolute; left:50%; top:25px; width:1px; height:18px; background:var(--line); }
[data-theme^="orbit-index"] .oi-legend { position:absolute; right:42px; bottom:9px; display:flex; gap:26px; color:var(--muted); font-size:.68rem; }
[data-theme^="orbit-index"] .oi-legend span { display:flex; align-items:center; gap:8px; }
[data-theme^="orbit-index"] .oi-legend i { width:9px; height:9px; border-radius:50%; background:var(--accent); }
[data-theme^="orbit-index"] .oi-legend span:last-child i { background:var(--oi-latest); }
[data-theme^="orbit-index"] .oi-reading-queue { display:grid; grid-template-columns:220px repeat(3,minmax(0,1fr)); min-height:151px; padding:0 28px; border-bottom:1px solid var(--line); }
[data-theme^="orbit-index"] .oi-queue-label { display:flex; align-items:center; justify-content:space-between; padding:0 38px 0 18px; border-right:1px solid var(--line); font-size:.8rem; }
[data-theme^="orbit-index"] .oi-queue-card { display:grid; grid-template-columns:35px 84px minmax(0,1fr); gap:14px; align-items:center; padding:16px 20px; border-right:1px dashed var(--line); color:var(--ink); }
[data-theme^="orbit-index"] .oi-queue-card:last-child { border-right:0; }
[data-theme^="orbit-index"] .oi-queue-card > strong { align-self:start; padding-top:4px; color:var(--accent); font:1rem var(--sans); }
[data-theme^="orbit-index"] .oi-queue-card img { width:84px; height:84px; border-radius:50%; object-fit:cover; filter:grayscale(1) contrast(1.05); }
[data-theme^="orbit-index"] .oi-queue-card span { display:flex; min-width:0; flex-direction:column; gap:4px; }
[data-theme^="orbit-index"] .oi-queue-card span b { font-size:.76rem; line-height:1.45; }
[data-theme^="orbit-index"] .oi-queue-card time { color:var(--muted); font-size:.62rem; }
[data-theme^="orbit-index"] .oi-queue-card em { display:-webkit-box; overflow:hidden; color:var(--muted); font-size:.65rem; font-style:normal; line-height:1.45; -webkit-box-orient:vertical; -webkit-line-clamp:2; }

/* Column Stage — 五栏占满剩余视口；悬停/键盘聚焦会展开当前栏。 */
[data-theme^="column-stage"] .column-stage-page { background:var(--bg); }
[data-theme^="column-stage"] .cs-manifesto { display:grid; grid-template-columns:minmax(0,1fr) auto auto; gap:36px; align-items:center; height:88px; padding:0 38px; background:#090d0c; color:#f6f1e6; }
[data-theme^="column-stage"] .cs-manifesto strong { font:600 1.02rem var(--serif); letter-spacing:.08em; }
[data-theme^="column-stage"] .cs-manifesto span,[data-theme^="column-stage"] .cs-manifesto time { font:10px var(--mono); letter-spacing:.08em; }
[data-theme^="column-stage"] .cs-manifesto time { padding-left:32px; border-left:1px solid #686b65; }
[data-theme^="column-stage"] .cs-stage { display:flex; width:100%; height:calc(100vh - 262px); min-height:600px; overflow:hidden; background:var(--ink); }
