  .oi-header-tools > span,.oi-header-tools > a,.oi-header-tools .search-label { display:none; }
  [data-theme^="orbit-index"] .oi-orbit-shell { height:auto; padding:36px 20px 26px; overflow:visible; }
  [data-theme^="orbit-index"] .oi-orbit { display:none; }
  [data-theme^="orbit-index"] .oi-feature { position:relative; left:auto; top:auto; width:min(100%,560px); height:auto; min-height:450px; margin:0 auto; transform:none; }
