  [data-theme^="orbit-index"] .oi-total,[data-theme^="orbit-index"] .oi-legend { display:none; }
  [data-theme^="orbit-index"] .oi-reading-queue { grid-template-columns:1fr; padding:0 20px; }
  [data-theme^="orbit-index"] .oi-queue-label { min-height:68px; border-right:0; border-bottom:1px solid var(--line); }
  [data-theme^="orbit-index"] .oi-queue-card { border-right:0; border-bottom:1px solid var(--line); }
  [data-theme^="column-stage"] .cs-manifesto { grid-template-columns:1fr auto; height:auto; min-height:82px; padding:18px 22px; }
  [data-theme^="column-stage"] .cs-manifesto span { display:none; }
  [data-theme^="column-stage"] .cs-stage { height:auto; min-height:0; flex-direction:column; }
  [data-theme^="column-stage"] .cs-panel,[data-theme^="column-stage"] .cs-panel-feature { flex:none; min-height:300px; border-right:0; border-bottom:2px solid #111; }
  [data-theme^="column-stage"] .cs-panel-feature { order:-1; min-height:520px; }
  [data-theme^="column-stage"] .cs-panel-copy { height:auto; min-height:190px; }
  [data-theme^="column-stage"] .cs-panel-cover { height:150px; }
  [data-theme^="column-stage"] .cs-panel-feature .cs-panel-cover { height:230px; }
  [data-theme^="type-cascade"] body { padding-left:0; }
  [data-theme^="type-cascade"] .tc-site-rail { position:relative; inset:auto; width:auto; height:64px; padding:0 20px; justify-content:center; border-right:0; border-bottom:1px solid var(--line); }
  [data-theme^="type-cascade"] .tc-rail-brand .brand { font-size:1.1rem; }
  [data-theme^="type-cascade"] :is(.tc-rail-manifesto,.tc-rail-total,.tc-rail-links) { display:none; }
  [data-theme^="type-cascade"] .tc-site-header { position:absolute !important; top:0 !important; right:0; left:0; height:64px; border-bottom:0; background:transparent; pointer-events:none; }
  [data-theme^="type-cascade"] .tc-site-header .menu-toggle { display:inline-flex; margin:12px 20px 0 auto; pointer-events:auto; }
  [data-theme^="type-cascade"] .tc-main-nav { position:absolute; top:64px; left:16px; right:16px; z-index:50; display:none; height:auto; flex-direction:column; align-items:stretch; gap:0; padding:12px; border:1px solid var(--line); background:var(--surface); }
  [data-theme^="type-cascade"] .tc-main-nav { pointer-events:auto; }
  [data-theme^="type-cascade"] .tc-site-header.nav-open .tc-main-nav { display:flex; }
  [data-theme^="type-cascade"] .tc-main-nav a { padding:10px; }
  [data-theme^="type-cascade"] .type-cascade-page { min-height:0; padding:28px 20px; }
  [data-theme^="type-cascade"] .tc-feature { grid-template-columns:64px minmax(0,1fr); }
  [data-theme^="type-cascade"] .tc-feature-detail { grid-column:2; padding-top:8px; }
  [data-theme^="type-cascade"] .tc-category-index { position:static; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); width:auto; margin:24px 0 0 64px; }
  [data-theme^="type-cascade"] .tc-category-index > b { grid-column:1 / -1; }
  [data-theme^="type-cascade"] .tc-category-index a { padding-right:18px; }
  [data-theme^="type-cascade"] .tc-row { margin-left:0 !important; grid-template-columns:60px minmax(0,1fr) 72px; }
  [data-theme^="type-cascade"] .tc-row-cover { grid-column:2; width:100%; }
  [data-theme^="type-cascade"] .tc-row time { grid-column:3; grid-row:1; }
