  :is(.oi-footer,.cs-footer) { grid-template-columns:1fr auto; }
  .cs-footer > p { justify-self:end; }
  :is([data-theme^="orbit-index"],[data-theme^="column-stage"],[data-theme^="type-cascade"]) .article-grid.has-toc { grid-template-columns:minmax(0,760px); }
}

@media (max-width:620px) {
  .oi-header-grid,.cs-header-grid { padding:0 18px; }
