  .oi-footer nav,.cs-footer > div { gap:18px; }
  :is([data-theme^="orbit-index"],[data-theme^="column-stage"],[data-theme^="type-cascade"]) .page-head { padding:36px 0 26px; }
  :is([data-theme^="orbit-index"],[data-theme^="column-stage"],[data-theme^="type-cascade"]) .post-item { grid-template-columns:52px minmax(0,1fr); gap:14px; }
  [data-theme^="type-cascade"] .post-item { margin-left:0 !important; }
}

/* =====================================================================
   Web3 指南内容骨架：Briefing Desk / Decision Wall / Route Atlas
   仅固定布局与视觉令牌；标题、栏目、数字、日期、图片和链接全部来自现有站点数据。
   ===================================================================== */

:root[data-theme="briefing-desk"] {
  --bg:#f7f3eb; --surface:#fffdf8; --ink:#111a34; --ink-soft:#28324d;
  --muted:#646a76; --faint:#8b8b86; --line:#273557; --line-soft:#e6ded0;
  --accent:#b52b24; --accent-soft:#d24439; --accent-wash:#f7e5df; --radius:0;
}
:root[data-theme="briefing-desk-white"] {
  --bg:#fff; --surface:#fff; --ink:#101b37; --ink-soft:#2b3650;
  --muted:#687080; --faint:#9297a1; --line:#233354; --line-soft:#e8e9ec;
  --accent:#9f251f; --accent-soft:#c33d34; --accent-wash:#f9ece9; --radius:0;
}
:root[data-theme="briefing-desk-sage"] {
  --bg:#eef2ed; --surface:#f8faf7; --ink:#183029; --ink-soft:#30493f;
  --muted:#64736c; --faint:#87948e; --line:#345648; --line-soft:#d8e1db;
  --accent:#3f6a58; --accent-soft:#5f8876; --accent-wash:#dce8e1; --radius:0;
}
:root[data-theme="briefing-desk-ink"] {
  --bg:#111723; --surface:#171f2d; --ink:#f4efe5; --ink-soft:#ddd8cd;
  --muted:#aaa99f; --faint:#7f8490; --line:#aeb7c7; --line-soft:#2a3445;
  --accent:#e5b44f; --accent-soft:#f1c96f; --accent-wash:#2b2a24; --radius:0;
}

:root[data-theme="decision-wall"] {
  --bg:#f7f2e9; --surface:#fffaf1; --ink:#080b11; --ink-soft:#22252b;
  --muted:#5c6068; --faint:#85878c; --line:#1c2028; --line-soft:#ddd7cc;
  --accent:#ff5a4f; --accent-soft:#ff766c; --accent-wash:#ffe7e2; --radius:0;
  --dw-hero:#0d4dd5; --dw-hero-ink:#fff; --dw-rail:#08090c; --dw-rail-ink:#fff;
}
:root[data-theme="decision-wall-white"] {
  --bg:#fff; --surface:#fff; --ink:#0b1222; --ink-soft:#2a3241;
  --muted:#657080; --faint:#9299a4; --line:#17223a; --line-soft:#e4e7ec;
  --accent:#154fc3; --accent-soft:#2f68d3; --accent-wash:#e9effc; --radius:0;
  --dw-hero:#fff; --dw-hero-ink:#0b1222; --dw-rail:#154fc3; --dw-rail-ink:#fff;
}
:root[data-theme="decision-wall-mint"] {
  --bg:#e9f4ef; --surface:#f8fcfa; --ink:#102a24; --ink-soft:#29453e;
  --muted:#63766f; --faint:#899a94; --line:#1d4e43; --line-soft:#d4e4dc;
  --accent:#087f69; --accent-soft:#249982; --accent-wash:#d8eee7; --radius:0;
  --dw-hero:#0b705f; --dw-hero-ink:#fff; --dw-rail:#0a1613; --dw-rail-ink:#f3fff9;
}
:root[data-theme="decision-wall-carbon"] {
  --bg:#11141a; --surface:#181c24; --ink:#f2f4f8; --ink-soft:#d7dbe4;
  --muted:#a8afbc; --faint:#7d8491; --line:#d3d8e1; --line-soft:#2d333e;
  --accent:#74a7ff; --accent-soft:#9bc0ff; --accent-wash:#1e2c43; --radius:0;
  --dw-hero:#2456c4; --dw-hero-ink:#fff; --dw-rail:#07090d; --dw-rail-ink:#fff;
}

:root[data-theme="route-atlas"] {
  --bg:#f3eadb; --surface:#f8f1e6; --ink:#171713; --ink-soft:#34342e;
  --muted:#6f6a61; --faint:#969084; --line:#bcae9a; --line-soft:#dfd4c2;
  --accent:#b33a2b; --accent-soft:#cf5140; --accent-wash:#edddd0; --radius:0;
  --ra-blue:#225c9a; --ra-green:#617445;
}
:root[data-theme="route-atlas-white"] {
  --bg:#fff; --surface:#fff; --ink:#161614; --ink-soft:#363630;
  --muted:#6f706c; --faint:#969793; --line:#c8c8c3; --line-soft:#e8e8e5;
  --accent:#9f3024; --accent-soft:#bc4a3c; --accent-wash:#f6e7e2; --radius:0;
  --ra-blue:#245b91; --ra-green:#5d7148;
}
:root[data-theme="route-atlas-indigo"] {
  --bg:#eef1fa; --surface:#f8f9fd; --ink:#17213e; --ink-soft:#323e5d;
  --muted:#68718a; --faint:#8d95a9; --line:#aeb8d0; --line-soft:#dce1ee;
  --accent:#365aa8; --accent-soft:#5576bc; --accent-wash:#dce4f5; --radius:0;
  --ra-blue:#365aa8; --ra-green:#5c7288;
}
:root[data-theme="route-atlas-moss"] {
  --bg:#edf1e8; --surface:#f7f9f4; --ink:#1d2a1d; --ink-soft:#394737;
  --muted:#687365; --faint:#8b9687; --line:#aebba7; --line-soft:#d9e1d4;
  --accent:#526b42; --accent-soft:#6e875d; --accent-wash:#dce6d6; --radius:0;
  --ra-blue:#456b6a; --ra-green:#526b42;
}

:is([data-theme^="briefing-desk"],[data-theme^="decision-wall"],[data-theme^="route-atlas"]) {
  color-scheme:light;
}
:is([data-theme="briefing-desk-ink"],[data-theme="decision-wall-carbon"]) { color-scheme:dark; }
:is([data-theme^="briefing-desk"],[data-theme^="decision-wall"],[data-theme^="route-atlas"]) body {
  background:var(--bg); color:var(--ink);
}
:is([data-theme^="briefing-desk"],[data-theme^="decision-wall"],[data-theme^="route-atlas"]) .wrap { max-width:1260px; }

.wg-site-header { position:relative; top:auto; z-index:50; border-bottom:1px solid var(--line); background:var(--bg); backdrop-filter:none; -webkit-backdrop-filter:none; }
.wg-header-grid { display:grid; grid-template-columns:minmax(210px,.8fr) minmax(0,1.55fr) minmax(160px,.65fr); align-items:center; min-height:64px; padding:0 clamp(24px,3vw,46px); }
.wg-header-brand { min-width:0; }
.wg-header-brand .brand { width:max-content; max-width:100%; font-size:1.4rem; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.wg-header-brand .wg-wordmark { font-family:var(--serif); font-size:1.55rem; font-weight:700; letter-spacing:.02em; }
.wg-main-nav { justify-content:center; gap:clamp(18px,2.6vw,42px); }
.wg-main-nav a { font-size:.88rem; white-space:nowrap; }
.wg-main-nav a[aria-current="page"]::after { bottom:-21px; }
.wg-header-tools { display:flex; align-items:center; justify-content:flex-end; gap:18px; }
.wg-header-tools .search-ico { display:inline-flex; align-items:center; gap:6px; color:var(--ink); }
.wg-header-tools .search-label { display:inline; font-size:.82rem; }
.wg-footer { margin:0; padding:0; background:var(--bg); border-color:var(--line); }
.wg-footer-row { display:grid; grid-template-columns:1fr auto; align-items:center; min-height:58px; gap:24px; padding:12px 24px; }
.wg-footer p { margin:0; color:var(--muted); font-size:.78rem; letter-spacing:.08em; }
.wg-footer nav { display:flex; gap:22px; }
.wg-footer a { color:var(--ink-soft); font-size:.78rem; }

[data-theme^="decision-wall"] .wg-site-header { border-color:color-mix(in srgb,var(--dw-hero-ink) 25%,transparent); background:var(--dw-hero); }
[data-theme^="decision-wall"] .wg-site-header :is(.brand,.wg-main-nav a,.wg-header-tools .search-ico,.menu-toggle) { color:var(--dw-hero-ink); }
[data-theme^="decision-wall"] .wg-header-brand .wg-wordmark { font-family:var(--sans); font-size:1.28rem; font-weight:850; letter-spacing:-.03em; }
[data-theme^="decision-wall"] .wg-main-nav a[aria-current="page"]::after { background:var(--dw-hero-ink); }
[data-theme^="route-atlas"] .wg-site-header { border-top:1px solid var(--accent); border-bottom-color:var(--accent); }

@media (max-width:900px) {
  .wg-header-grid { display:flex; justify-content:space-between; min-height:62px; padding:0 18px; }
  .wg-site-header .menu-toggle { display:inline-flex; margin-left:auto; }
  .wg-main-nav { position:absolute; top:62px; left:12px; right:12px; z-index:60; display:none; flex-direction:column; align-items:stretch; gap:0; padding:10px; border:1px solid var(--line); background:var(--surface); box-shadow:var(--shadow); }
  .wg-site-header.nav-open .wg-main-nav { display:flex; }
  .wg-main-nav a { padding:9px 10px; color:var(--ink) !important; }
  .wg-main-nav a[aria-current="page"]::after { display:none; }
  .wg-header-tools { margin-left:12px; }
  .wg-header-tools .search-label,.wg-header-tools .lang-cur { display:none; }
}

/* Briefing Desk ------------------------------------------------------- */
.briefing-desk-page { width:100%; padding:0 24px; font-family:var(--serif); }
.bd-briefline { display:grid; grid-template-columns:1fr 1fr; gap:28px; align-items:center; min-height:46px; padding:8px 10px; border-bottom:1px solid var(--line); color:var(--muted); font-family:var(--sans); font-size:.76rem; }
.bd-briefline > * { min-width:0; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; }
.bd-briefline strong { justify-self:end; color:var(--accent); font-weight:650; text-align:right; }
.bd-lead { display:grid; grid-template-columns:minmax(0,2.45fr) minmax(300px,.9fr); border-bottom:2px solid var(--line); }
.bd-lead-wide { grid-template-columns:1fr; }
.bd-lead-main { position:relative; min-width:0; padding:16px 26px 16px 16px; }
.bd-eyebrow { margin:0 0 8px; color:var(--accent); font-family:var(--sans); font-size:.72rem; font-weight:700; letter-spacing:.16em; text-transform:uppercase; }
.bd-lead h1 { max-width:none; margin:0 0 12px; font:700 clamp(2.8rem,4vw,3.8rem)/1.02 var(--serif); letter-spacing:-.042em; text-wrap:balance; }
.bd-lead-copy { display:-webkit-box; overflow:hidden; max-width:62ch; margin:0 0 16px; color:var(--ink-soft); font-family:var(--sans); font-size:.9rem; line-height:1.55; -webkit-box-orient:vertical; -webkit-line-clamp:3; }
.bd-lead-media { display:block; width:100%; max-height:300px; aspect-ratio:3.28/1; overflow:hidden; border:1px solid var(--line); background:var(--line-soft); color:var(--ink); }
.bd-lead-media img { width:100%; height:100%; object-fit:cover; filter:saturate(.72) contrast(1.03); }
.bd-media-empty { display:flex; align-items:center; justify-content:center; min-height:130px; padding:30px; background:var(--line-soft); color:var(--muted); text-align:center; }
.bd-media-empty span { font:600 clamp(1.3rem,2vw,2rem)/1.2 var(--serif); }
.bd-feature-caption { position:absolute; right:26px; bottom:16px; left:16px; display:grid; grid-template-columns:auto minmax(0,1fr) auto; gap:12px; align-items:center; padding:8px 10px; border-top:1px solid color-mix(in srgb,var(--line) 42%,transparent); background:color-mix(in srgb,var(--surface) 88%,transparent); color:var(--ink); font-family:var(--sans); font-size:.72rem; }
.bd-feature-caption small { color:var(--accent); font-size:.65rem; font-weight:750; white-space:nowrap; }
.bd-feature-caption span { overflow:hidden; white-space:nowrap; text-overflow:ellipsis; }
.bd-checks { min-width:0; padding:34px 12px 18px 26px; border-left:1px solid var(--line); }
.bd-checks h2 { margin:0 0 0; padding:0 0 12px; border-bottom:2px solid var(--line); color:var(--ink); font-size:1.45rem; }
.bd-checks > a { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:14px; padding:13px 0; border-bottom:1px dashed color-mix(in srgb,var(--line) 42%,transparent); color:var(--ink); }
.bd-checks > a:hover b { color:var(--accent); }
.bd-checks b { display:block; font-size:1.1rem; line-height:1.2; }
.bd-checks small { display:-webkit-box; overflow:hidden; margin-top:5px; color:var(--muted); font-family:var(--sans); font-size:.69rem; line-height:1.4; -webkit-box-orient:vertical; -webkit-line-clamp:2; }
.bd-checks strong { color:var(--accent); font-size:1.2rem; font-weight:700; }
.bd-guides { border-bottom:1px solid var(--line); }
.bd-guide-row { display:grid; grid-template-columns:minmax(190px,.7fr) minmax(0,1.45fr) auto auto; gap:26px; align-items:center; min-height:62px; padding:9px 8px; border-top:1px solid var(--line); }
.bd-guide-row h2,.bd-guide-row p { margin:0; }
.bd-guide-row h2 { font-size:1.35rem; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.bd-guide-row h2 a { color:var(--ink); }
.bd-guide-row p { overflow:hidden; color:var(--muted); font-family:var(--sans); font-size:.78rem; white-space:nowrap; text-overflow:ellipsis; }
.bd-guide-row time,.bd-guide-action { font-family:var(--sans); font-size:.75rem; white-space:nowrap; }
.bd-guide-action { padding-left:20px; border-left:1px solid var(--line); color:var(--ink); text-decoration:underline; text-underline-offset:5px; }
.bd-latest { padding:10px 0 28px; }
.bd-latest > header { display:flex; align-items:center; justify-content:space-between; padding:0 8px 7px; border-bottom:1px solid var(--line); }
.bd-latest > header h2 { margin:0; font-size:1.05rem; }
.bd-latest > header a { color:var(--ink); font-family:var(--sans); font-size:.76rem; }
.bd-latest-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:16px; padding-top:12px; }
.bd-latest-grid article { min-width:0; }
.bd-latest-cover { display:flex; width:100%; aspect-ratio:2.45/1; overflow:hidden; border:1px solid var(--line-soft); }
.bd-latest-cover img { width:100%; height:100%; object-fit:cover; filter:saturate(.68); }
.bd-latest-grid time { display:block; margin-top:8px; color:var(--muted); font-family:var(--sans); font-size:.68rem; }
.bd-latest-grid h3 { margin:3px 0 2px; font-size:1rem; line-height:1.35; }
.bd-latest-grid h3 a { color:var(--ink); }
.bd-latest-grid p { display:-webkit-box; overflow:hidden; margin:0; color:var(--muted); font-family:var(--sans); font-size:.7rem; line-height:1.45; -webkit-box-orient:vertical; -webkit-line-clamp:2; }
[data-theme="briefing-desk-ink"] .bd-lead-media img,[data-theme="briefing-desk-ink"] .bd-latest-cover img { opacity:.78; }

@media (max-width:980px) {
  .bd-lead { grid-template-columns:1fr; }
  .bd-checks { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); padding:22px 0; border-top:1px solid var(--line); border-left:0; }
  .bd-checks h2 { grid-column:1 / -1; padding:0 16px 12px; }
  .bd-checks > a { padding:14px 16px; }
