.dw-feature-copy { min-width:0; align-self:center; }
.dw-feature-copy > small { display:inline-block; margin-bottom:16px; padding:4px 10px; background:var(--accent); color:#fff; font-size:.68rem; font-weight:750; letter-spacing:.08em; }
.dw-feature h2 { display:-webkit-box; overflow:hidden; margin:0 0 8px; font:850 clamp(1.45rem,2vw,2.05rem)/1.12 var(--sans); letter-spacing:-.035em; -webkit-box-orient:vertical; -webkit-line-clamp:3; }
.dw-feature h2 a { color:var(--ink); }
.dw-feature time { display:block; color:var(--muted); font-family:var(--mono); font-size:.68rem; }
.dw-feature p { display:-webkit-box; overflow:hidden; margin:16px 0; color:var(--ink-soft); font-size:.75rem; line-height:1.52; -webkit-box-orient:vertical; -webkit-line-clamp:4; }
.dw-read { display:inline-block; color:var(--ink); font-size:.76rem; font-weight:700; text-decoration:underline; text-underline-offset:7px; }
.dw-topic-rail { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); min-height:58px; background:var(--dw-rail); color:var(--dw-rail-ink); }
.dw-topic-rail a { display:flex; align-items:center; justify-content:center; border-right:1px solid color-mix(in srgb,var(--dw-rail-ink) 28%,transparent); color:inherit; font-weight:750; font-size:.95rem; }
