.dw-guides h3 { margin:0 0 6px; font:800 1.45rem/1.2 var(--sans); }
.dw-guides h3 a { color:var(--ink); }
.dw-guides time { display:block; color:var(--muted); font-family:var(--mono); font-size:.68rem; }
.dw-guides p { margin:10px 0; color:var(--ink-soft); font-size:.76rem; line-height:1.55; }
.dw-guides article > a { color:var(--ink); font-size:.72rem; font-weight:750; text-decoration:underline; text-underline-offset:6px; }
.dw-latest { padding-left:48px; }
.dw-latest h2 { margin-bottom:12px; font-size:2.3rem; }
.dw-latest-row { display:grid; grid-template-columns:40px 140px minmax(0,1fr); gap:14px; align-items:center; min-height:88px; padding:8px 0; border-bottom:1px solid var(--line); color:var(--ink); }
.dw-latest-row > strong { font:500 1.45rem/1 var(--sans); }
.dw-latest-cover { display:flex; width:140px; height:72px; overflow:hidden; }
