.dw-latest-row b { display:-webkit-box; overflow:hidden; font-size:.78rem; line-height:1.35; -webkit-box-orient:vertical; -webkit-line-clamp:2; }
.dw-latest-row time { display:block; margin-top:3px; color:var(--muted); font-family:var(--mono); font-size:.62rem; }
.dw-latest-row em { display:-webkit-box; overflow:hidden; margin-top:4px; color:var(--muted); font-size:.65rem; font-style:normal; line-height:1.35; -webkit-box-orient:vertical; -webkit-line-clamp:2; }
