/* Route Atlas --------------------------------------------------------- */
.route-atlas-page { width:100%; padding:0; font-family:var(--serif); }
.ra-layout { display:grid; grid-template-columns:minmax(210px,16%) minmax(0,1fr) minmax(280px,22%); min-height:780px; border-bottom:1px solid var(--line); }
.ra-index { min-width:0; padding:34px 22px 26px clamp(24px,3vw,44px); }
.ra-index h2,.ra-latest h2 { margin:0 0 28px; color:var(--accent); font-size:1.45rem; letter-spacing:.04em; }
.ra-index nav { position:relative; }
.ra-index nav::before { content:""; position:absolute; top:12px; bottom:12px; left:4px; border-left:1px solid var(--accent); }
.ra-index nav a { position:relative; display:block; margin-left:18px; padding:0 0 24px; color:var(--ink); }
.ra-index nav a::before { content:""; position:absolute; top:8px; left:-18px; width:7px; height:7px; border-radius:50%; background:var(--accent); }
.ra-index nav span { display:block; color:var(--accent); font-size:.78rem; }
.ra-index nav small { display:block; margin-top:8px; color:var(--muted); font-family:var(--sans); font-size:.66rem; line-height:1.55; }
.ra-index-links { display:grid; gap:0; margin-top:42px; padding-top:20px; border-top:1px solid var(--line); }
.ra-index-links a { padding:10px 0; color:var(--ink-soft); font-family:var(--sans); font-size:.74rem; }
.ra-main { min-width:0; padding:0; border-right:1px solid var(--line); border-left:1px solid var(--line); }
.ra-hero { position:relative; display:block; min-height:328px; overflow:hidden; border-bottom:1px solid var(--line); }
.ra-hero::after { content:""; position:absolute; inset:0; z-index:1; background:linear-gradient(90deg,color-mix(in srgb,var(--surface) 96%,transparent) 0%,color-mix(in srgb,var(--surface) 88%,transparent) 42%,color-mix(in srgb,var(--surface) 24%,transparent) 72%,transparent 100%); pointer-events:none; }
.ra-hero-copy { position:relative; z-index:2; width:min(68%,680px); padding:40px 44px 32px; }
.ra-hero-copy > p { margin:0 0 8px; color:var(--accent); font-family:var(--sans); font-size:.7rem; font-weight:700; letter-spacing:.15em; text-transform:uppercase; }
.ra-hero h1 { max-width:100%; margin:0; font:700 clamp(2.9rem,3.65vw,3.6rem)/1 var(--serif); letter-spacing:-.042em; text-wrap:balance; }
.ra-hero-copy > div { display:-webkit-box; overflow:hidden; max-width:32ch; margin-top:18px; color:var(--ink-soft); font-size:.94rem; letter-spacing:.12em; line-height:1.65; -webkit-box-orient:vertical; -webkit-line-clamp:2; }
.ra-feature-caption { display:grid; grid-template-columns:auto minmax(0,1fr) auto; gap:10px; align-items:center; max-width:34rem; margin-top:22px; padding-top:10px; border-top:1px solid var(--line); color:var(--ink); font-family:var(--sans); font-size:.7rem; letter-spacing:0; }
.ra-feature-caption small { color:var(--accent); font-size:.62rem; font-weight:750; white-space:nowrap; }
.ra-feature-caption span { overflow:hidden; white-space:nowrap; text-overflow:ellipsis; }
.ra-hero-media { position:absolute; inset:0; z-index:0; display:flex; min-height:0; overflow:hidden; color:var(--ink); }
.ra-hero-media img { width:100%; height:100%; object-fit:contain; object-position:right center; filter:sepia(.34) saturate(.72) contrast(1.24) brightness(.86); mix-blend-mode:multiply; }
.ra-media-empty { align-items:center; justify-content:center; padding:32px; background:var(--line-soft); color:var(--muted); text-align:center; }
.ra-media-empty > span,.ra-media-empty > i { font-style:normal; font-weight:700; }
.ra-stages { position:relative; padding:0 42px; }
.ra-stage { display:grid; grid-template-columns:58px 140px minmax(0,1fr) 96px; gap:18px; align-items:center; min-height:136px; padding:18px 0; border-bottom:1px solid var(--line); }
.ra-stage > strong { display:flex; align-items:center; justify-content:center; width:56px; height:56px; border-radius:50%; background:var(--accent); color:#fff; font:600 1.45rem/1 var(--serif); }
.ra-stage-1 > strong { background:var(--ra-blue); }
.ra-stage-2 > strong { background:var(--ra-green); }
.ra-stage > h2 { margin:0; color:var(--accent); font-size:1.45rem; }
.ra-stage-1 > h2 { color:var(--ra-blue); }
.ra-stage-2 > h2 { color:var(--ra-green); }
.ra-stage h3 { margin:0 0 7px; font-size:1rem; }
.ra-stage h3 a { color:var(--ink); }
.ra-stage p { display:-webkit-box; overflow:hidden; margin:0; color:var(--muted); font-family:var(--sans); font-size:.7rem; line-height:1.55; -webkit-box-orient:vertical; -webkit-line-clamp:2; }
.ra-stage > span { display:grid; gap:10px; }
.ra-stage > span a { color:var(--accent); font-family:var(--sans); font-size:.7rem; white-space:nowrap; }
.ra-stage > span time { color:var(--muted); font-family:var(--mono); font-size:.62rem; }
.ra-links { padding:18px 42px 0; }
.ra-links h2 { margin:0; padding-bottom:8px; border-bottom:1px solid var(--ink); font-size:.9rem; }
.ra-links > a { display:grid; grid-template-columns:minmax(170px,.45fr) minmax(0,1fr) 24px; gap:18px; align-items:center; min-height:48px; padding:7px 6px; border-bottom:1px solid var(--line); color:var(--ink); }
.ra-links > a span { font-size:.9rem; }
.ra-links > a small { overflow:hidden; color:var(--muted); font-family:var(--sans); font-size:.68rem; white-space:nowrap; text-overflow:ellipsis; }
.ra-links > a strong { justify-self:end; font-weight:500; }
.ra-latest { min-width:0; padding:34px clamp(20px,2vw,34px) 26px 20px; }
.ra-latest > a:not(.ra-all) { display:grid; grid-template-columns:minmax(64px,86px) minmax(0,1fr) 14px; gap:13px; align-items:center; min-height:116px; padding:12px 0; border-bottom:1px solid var(--line); color:var(--ink); }
.ra-latest-cover { display:flex; width:100%; height:78px; overflow:hidden; }
.ra-latest-cover img { width:100%; height:100%; object-fit:cover; filter:sepia(.24) saturate(.66); }
.ra-latest b { display:-webkit-box; overflow:hidden; font-size:.85rem; line-height:1.45; -webkit-box-orient:vertical; -webkit-line-clamp:3; }
.ra-latest time { display:block; margin-top:10px; color:var(--muted); font-family:var(--mono); font-size:.62rem; }
.ra-latest > a > strong { color:var(--accent); font-weight:500; }
.ra-all { display:block; margin-top:18px; color:var(--accent); font-family:var(--sans); font-size:.72rem; text-align:right; }

@media (max-width:980px) {
  .ra-layout { grid-template-columns:190px minmax(0,1fr) 250px; }
  .ra-main { padding:26px 24px; }
  .ra-hero { grid-template-columns:1fr; }
  .ra-hero-media { min-height:220px; max-height:280px; }
  .ra-stage { grid-template-columns:54px 110px minmax(0,1fr); }
