  .ra-latest-cover { width:70px; height:66px; }
}
@media (max-width:860px) {
  .route-atlas-page { padding:0 18px; }
  .ra-layout { grid-template-columns:1fr; }
  .ra-index { padding:22px 0; border-bottom:1px solid var(--line); }
  .ra-index h2 { margin-bottom:14px; }
  .ra-index nav { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; }
  .ra-index nav::before,.ra-index nav a::before { display:none; }
  .ra-index nav a { margin:0; padding:12px; border:1px solid var(--line); }
  .ra-index-links { display:flex; flex-wrap:wrap; gap:18px; margin-top:14px; padding-top:10px; }
  .ra-main { padding:28px 0; border-right:0; border-left:0; }
  .ra-latest { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:0 18px; padding:28px 0; border-top:1px solid var(--line); }
  .ra-latest h2,.ra-all { grid-column:1 / -1; }
}
@media (max-width:580px) {
  .ra-index nav { grid-template-columns:1fr; }
  .ra-hero h1 { font-size:clamp(3rem,16vw,4.6rem); }
  .ra-hero-media { min-height:190px; }
  .ra-stage { grid-template-columns:48px minmax(0,1fr); gap:10px 16px; padding:20px 0; }
  .ra-stage > strong { width:46px; height:46px; font-size:1.15rem; }
  .ra-stage > h2 { font-size:1.2rem; }
  .ra-stage > div,.ra-stage > span { grid-column:2; }
  .ra-stage > span { grid-row:auto; }
  .ra-links > a { grid-template-columns:minmax(0,1fr) 24px; }
  .ra-links > a small { grid-column:1; grid-row:2; }
  .ra-links > a strong { grid-column:2; grid-row:1 / 3; }
  .ra-latest { grid-template-columns:1fr; }
  .ra-latest h2,.ra-all { grid-column:auto; }
}

