[data-theme^="decision-wall"] .page-head :is(h1,.eyebrow,p,.breadcrumb,.breadcrumb a) { color:inherit; }
[data-theme^="decision-wall"] .page-head h1,[data-theme^="decision-wall"] .article-head h1 { font-family:var(--sans); font-weight:850; }
[data-theme^="decision-wall"] .cat-nav { background:var(--dw-rail); }
[data-theme^="decision-wall"] .cat-nav a { color:var(--dw-rail-ink); border-color:color-mix(in srgb,var(--dw-rail-ink) 25%,transparent); }
[data-theme^="decision-wall"] .cat-nav a:first-child { padding-left:18px; }
[data-theme^="decision-wall"] .cat-nav a.active { color:var(--accent); }
[data-theme^="decision-wall"] .post-item { grid-template-columns:90px minmax(0,1fr); }
[data-theme^="decision-wall"] .post-item .num { font:800 2.2rem/1 var(--sans); }
[data-theme^="decision-wall"] .post-item h3 { font-family:var(--sans); font-weight:820; }
[data-theme^="decision-wall"] .article-main { padding:0 28px 34px; border-right:1px solid var(--line); border-left:1px solid var(--line); }
[data-theme^="decision-wall"] .article-head { margin-right:-28px; margin-left:-28px; padding:38px 28px; background:var(--surface); }
[data-theme^="decision-wall"] .content-page-about .page-head { min-height:440px; display:flex; align-items:flex-end; }
[data-theme^="decision-wall"] .content-page-about .page-head h1 { max-width:10ch; font-size:clamp(4rem,9vw,8rem); }
[data-theme^="decision-wall"] .content-page-about .prose { max-width:980px; padding:52px 0 76px; }

[data-theme^="route-atlas"] .page-head { border-top:1px solid var(--accent); }
[data-theme^="route-atlas"] .page-head .wrap { padding-left:clamp(28px,8vw,132px); }
[data-theme^="route-atlas"] .page-head h1,[data-theme^="route-atlas"] .article-head h1 { font-family:var(--serif); font-weight:700; }
[data-theme^="route-atlas"] .post-list { margin-left:clamp(0px,7vw,110px); border-left:1px solid var(--line); }
[data-theme^="route-atlas"] .post-list.search-results:has(> .search-empty) { border-bottom:0; border-left:0; }
[data-theme^="route-atlas"] .post-item { padding-right:18px; padding-left:24px; }
[data-theme^="route-atlas"] .article-head { position:relative; padding-left:34px; }
[data-theme^="route-atlas"] .article-head::before { content:""; position:absolute; top:26px; bottom:30px; left:0; border-left:4px solid var(--accent); }
[data-theme^="route-atlas"] .content-page-about .page-head { min-height:420px; padding-top:86px; }
[data-theme^="route-atlas"] .content-page-about .page-head h1 { max-width:9ch; }
[data-theme^="route-atlas"] .content-page-about .prose { max-width:920px; margin-left:clamp(0px,8vw,130px); padding:48px 0 80px; border-left:1px solid var(--line); padding-left:42px; }

@media (max-width:900px) {
  :is([data-theme^="briefing-desk"],[data-theme^="decision-wall"],[data-theme^="route-atlas"]) .article-grid.has-toc { grid-template-columns:minmax(0,760px); }
  [data-theme^="briefing-desk"] .content-page-about .page-head .wrap { display:block; }
  [data-theme^="briefing-desk"] .content-page-about .page-head p { margin-top:18px; }
  [data-theme^="briefing-desk"] .content-page-about .prose { columns:1; }
}
@media (max-width:620px) {
  .wg-footer-row { grid-template-columns:1fr; gap:6px; padding:14px 18px; }
  .wg-footer nav { flex-wrap:wrap; gap:14px; }
  :is([data-theme^="briefing-desk"],[data-theme^="decision-wall"],[data-theme^="route-atlas"]) .page-head { padding:36px 0 26px; }
  :is([data-theme^="briefing-desk"],[data-theme^="decision-wall"],[data-theme^="route-atlas"]) .page-head h1 { font-size:clamp(2.8rem,15vw,4.7rem); }
  :is([data-theme^="briefing-desk"],[data-theme^="decision-wall"],[data-theme^="route-atlas"]) .post-item { grid-template-columns:46px minmax(0,1fr); gap:12px; }
  :is([data-theme^="briefing-desk"],[data-theme^="decision-wall"],[data-theme^="route-atlas"]) .article-head h1 { font-size:clamp(2.6rem,13vw,4.2rem); }
  [data-theme^="decision-wall"] .article-main { padding:0 16px 26px; }
  [data-theme^="decision-wall"] .article-head { margin-right:-16px; margin-left:-16px; padding:28px 16px; }
  [data-theme^="route-atlas"] .post-list { margin-left:0; }
  [data-theme^="route-atlas"] .content-page-about .prose { margin-left:0; padding-left:22px; }
}
/* ==========================================================================
   2026-07 独立内容骨架：Answer Desk / Portrait Journal / Casebook
   三套首页只消费现有 Site、Categories、Featured 与 Posts；样式不依赖演示文案。
   ========================================================================== */
:root[data-theme="answer-desk"] {
  --bg:#fbfaf7; --surface:#ffffff; --ink:#101218; --ink-soft:#42464f;
  --muted:#747984; --faint:#aeb2ba; --line:#d8d7d2; --line-soft:#ebeae6;
  --accent:#2457d6; --accent-soft:#386be9; --accent-wash:#edf2ff;
  --radius:0px;
}
:root[data-theme="answer-desk-white"] {
  --bg:#ffffff; --surface:#ffffff; --ink:#101218; --ink-soft:#3f444d;
  --muted:#707680; --faint:#a9aeb6; --line:#d7d9dd; --line-soft:#eef0f3;
  --accent:#2457d6; --accent-soft:#386be9; --accent-wash:#edf2ff;
  --radius:0px;
}
:root[data-theme="answer-desk-dark"] {
  --bg:#0c111b; --surface:#121a27; --ink:#f5f7fb; --ink-soft:#c7cfdb;
  --muted:#949faf; --faint:#687487; --line:#303b4b; --line-soft:#1b2635;
  --accent:#78a0ff; --accent-soft:#9ab8ff; --accent-wash:#17284f; --on-accent:#0c111b;
  --radius:0px;
}
:root[data-theme="portrait-journal"] {
  --bg:#f6f7f4; --surface:#fbfcf9; --ink:#171a17; --ink-soft:#3f463f;
  --muted:#727a72; --faint:#aab0aa; --line:#d4d8d2; --line-soft:#e6e9e4;
  --accent:#304b32; --accent-soft:#486b4b; --accent-wash:#e8eee7;
  --radius:0px;
}
:root[data-theme="portrait-journal-white"] {
  --bg:#ffffff; --surface:#ffffff; --ink:#171a17; --ink-soft:#3d453e;
  --muted:#707970; --faint:#a8afa8; --line:#d4d9d4; --line-soft:#edf0ed;
  --accent:#304b32; --accent-soft:#486b4b; --accent-wash:#e8eee7;
  --radius:0px;
}
:root[data-theme="portrait-journal-dark"] {
  --bg:#0d120f; --surface:#131a15; --ink:#f3f6f2; --ink-soft:#c8d0c8;
  --muted:#929d93; --faint:#667268; --line:#303a32; --line-soft:#1c261f;
  --accent:#8eb893; --accent-soft:#acd0b0; --accent-wash:#1d3322;
  --radius:0px;
}
:root[data-theme="casebook"] {
  --bg:#fbfbfa; --surface:#ffffff; --ink:#0b1020; --ink-soft:#3c4350;
  --muted:#747b86; --faint:#a8adb4; --line:#d4d6d9; --line-soft:#e8e9eb;
  --accent:#c34b2d; --accent-soft:#db6547; --accent-wash:#f7ebe7;
  --radius:0px;
}
:root[data-theme="casebook-white"] {
  --bg:#ffffff; --surface:#ffffff; --ink:#0b1020; --ink-soft:#3b424e;
  --muted:#727984; --faint:#a8adb4; --line:#d5d7da; --line-soft:#eef0f2;
  --accent:#c34b2d; --accent-soft:#db6547; --accent-wash:#f7ebe7;
  --radius:0px;
}
:root[data-theme="casebook-dark"] {
  --bg:#11100f; --surface:#181614; --ink:#f7f4f1; --ink-soft:#d2cac4;
  --muted:#a0968e; --faint:#746b64; --line:#3b3531; --line-soft:#241f1c;
  --accent:#f07a5c; --accent-soft:#ff9b81; --accent-wash:#42231c;
  --radius:0px;
}
:is([data-theme^="answer-desk"],[data-theme^="portrait-journal"],[data-theme^="casebook"]) body {
  background:var(--bg); color:var(--ink); font-family:var(--sans);
}
:is([data-theme^="answer-desk"],[data-theme^="portrait-journal"],[data-theme^="casebook"])
main:has(> :is(.answer-desk-page,.portrait-journal-page,.casebook-page)) {
  overflow:hidden;
}
:is([data-theme^="answer-desk"],[data-theme^="portrait-journal"],[data-theme^="casebook"]) .ec-site-header {
  position:sticky; top:0; z-index:20; height:59px; border-top:0;
  border-bottom:1px solid var(--line); background:var(--bg); backdrop-filter:none;
}
.ec-header-grid {
  display:grid; grid-template-columns:minmax(220px,1fr) auto minmax(220px,1fr);
  align-items:center; width:100%; max-width:1280px; height:58px; margin-inline:auto; padding:0 30px;
}
.ec-header-brand { display:flex; align-items:center; gap:12px; min-width:0; }
.ec-header-brand .brand { color:var(--ink); font-family:var(--serif); font-size:1.15rem; font-weight:700; }
.ec-header-brand .brand-logo { max-height:31px; }
.ec-header-brand > small { max-width:18rem; overflow:hidden; color:var(--muted); font-size:.67rem; line-height:1.25; white-space:nowrap; text-overflow:ellipsis; }
.ec-main-nav { display:flex; align-items:stretch; justify-content:center; height:58px; gap:0; }
.ec-main-nav a { display:flex; align-items:center; padding:0 22px; border-bottom:2px solid transparent; color:var(--ink-soft); font-size:.78rem; }
.ec-main-nav a[aria-current="page"] { border-bottom-color:var(--accent); color:var(--accent); }
.ec-main-nav a[aria-current="page"]::after { display:none; }
.ec-header-tools { display:flex; justify-content:flex-end; align-items:center; gap:18px; }
.ec-header-tools .search-ico { gap:6px; color:var(--ink); font-size:.74rem; }
.ec-header-tools .lang-switch { padding-left:18px; border-left:1px solid var(--line); }
.ec-footer {
  display:grid; grid-template-columns:1fr auto 1fr; align-items:center; gap:2rem;
  width:calc(100% - 60px); max-width:1220px; margin:0 auto; padding:24px 10px; border-top:1px solid var(--line); background:var(--bg);
}
.ec-footer-brand { display:flex; align-items:center; gap:12px; }
.ec-footer-brand .brand { color:var(--ink); font-family:var(--serif); font-weight:700; }
.ec-footer-brand small { color:var(--muted); font-size:.68rem; }
.ec-footer nav { display:flex; gap:24px; }
.ec-footer nav a,.ec-footer p { color:var(--muted); font-size:.68rem; }
.ec-footer p { justify-self:end; margin:0; }
[data-theme^="answer-desk"] .ec-header-brand > small,
[data-theme^="casebook"] .ec-header-brand > small { display:none; }

/* Answer Desk — 搜索先行；Hero、精选答案、问题表与主题索引。 */
.answer-desk-page { width:100%; max-width:1280px; margin-inline:auto; padding:0 30px 34px; }
.ad-hero {
  display:grid; grid-template-columns:minmax(0,1.1fr) minmax(360px,.9fr); gap:clamp(2rem,6vw,7rem);
  min-height:370px; padding:38px 40px 34px; border-bottom:1px solid var(--line); align-items:center;
}
.ad-hero:has(.ad-hero-media:empty) { grid-template-columns:minmax(0,780px); }
.ad-eyebrow { margin:0 0 14px; color:var(--accent); font-size:.78rem; font-weight:700; letter-spacing:.06em; }
.ad-hero h1 { max-width:15ch; margin:0; font:600 clamp(2.7rem,3.8vw,3.45rem)/1.04 var(--serif); letter-spacing:-.05em; }
.ad-hero-description { max-width:58ch; margin:18px 0 20px; color:var(--ink-soft); font-size:.88rem; line-height:1.8; }
.ad-search { display:grid; grid-template-columns:minmax(0,1fr) 72px; width:min(610px,100%); height:48px; border:1px solid var(--ink); background:var(--surface); }
.ad-search input { min-width:0; border:0; padding:0 17px; outline:0; background:transparent; color:var(--ink); font:inherit; }
.ad-search input:focus { box-shadow:inset 0 0 0 2px var(--accent-wash); }
.ad-search button { border:0; border-left:1px solid var(--ink); background:var(--accent); color:var(--on-accent,#fff); font-weight:700; cursor:pointer; }
.ad-suggestions { display:flex; align-items:center; flex-wrap:wrap; gap:0; margin-top:12px; color:var(--muted); font-size:.7rem; }
.ad-suggestions small { margin-right:12px; }
.ad-suggestions a { padding:0 12px; border-left:1px solid var(--line); color:var(--accent); }
.ad-hero-media { min-height:250px; max-height:290px; overflow:hidden; }
.ad-hero-media:empty { display:none; }
.ad-hero-media img,.ad-hero-embed,.ad-hero-embed svg { width:100%; height:100%; min-height:250px; max-height:290px; object-fit:cover; }
.ad-feature {
  display:grid; grid-template-columns:minmax(250px,.8fr) minmax(0,1.35fr) minmax(250px,.75fr);
  align-items:center; gap:28px; min-height:190px; padding:30px 40px; border-bottom:1px solid var(--line);
}
.ad-feature:not(:has(.ad-feature-cover)) { grid-template-columns:minmax(250px,.8fr) minmax(0,1.35fr); }
.ad-feature-title { padding-right:28px; border-right:1px solid var(--line); }
.ad-feature-title small,.ad-feature-answer a { color:var(--accent); font-size:.72rem; font-weight:700; }
.ad-feature-title h2 { margin:12px 0 18px; font:600 clamp(1.8rem,2.6vw,2.75rem)/1.12 var(--serif); letter-spacing:-.035em; }
.ad-feature-title h2 a { color:var(--ink); }
.ad-feature-title p { margin:0; color:var(--muted); font-size:.72rem; }
.ad-feature-answer p { margin:0 0 18px; color:var(--ink-soft); font-size:.87rem; line-height:1.9; }
.ad-feature-cover { height:145px; overflow:hidden; }
.ad-feature-cover img { width:100%; height:100%; object-fit:cover; }
.ad-popular,.ad-bottom { padding:18px 40px 0; }
.ad-popular header,.ad-topics > h2,.ad-updates > h2,.cb-selected header,.cb-ledger header,.pj-content header {
  display:flex; justify-content:space-between; align-items:baseline; min-height:36px; margin:0; border-bottom:1px solid var(--ink);
}
.ad-popular h2,.ad-topics h2,.ad-updates h2,.cb-selected h2,.cb-ledger h2,.pj-content h2 { margin:0 0 10px; font-size:1.2rem; }
.ad-popular header a,.cb-selected header a,.cb-ledger header a,.pj-content header a { color:var(--accent); font-size:.7rem; }
.ad-question-head,.ad-question-row { display:grid; grid-template-columns:minmax(0,1fr) 180px 120px; gap:18px; align-items:center; }
.ad-question-head { padding:8px 2px; border-bottom:1px solid var(--line); color:var(--muted); font-size:.62rem; }
.ad-question-row { min-height:48px; border-bottom:1px solid var(--line); color:var(--ink); }
.ad-question-row b { display:block; overflow:hidden; font-size:.82rem; white-space:nowrap; text-overflow:ellipsis; }
.ad-question-row em { display:none; }
.ad-question-row small,.ad-question-row time { color:var(--muted); font-size:.66rem; font-style:normal; }
.ad-bottom { display:grid; grid-template-columns:minmax(0,2fr) minmax(280px,1fr); gap:30px; padding-top:18px; }
.ad-topics > h2,.ad-updates > h2 { padding-bottom:10px; }
.ad-topics > div { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); }
.ad-topics > div > a { position:relative; min-height:102px; padding:18px 22px 16px 8px; border-right:1px solid var(--line); color:var(--ink); }
.ad-topics > div > a:nth-child(3n) { border-right:0; }
.ad-topics b { display:block; font-size:.84rem; }
.ad-topics span { display:block; margin-top:7px; color:var(--muted); font-size:.66rem; line-height:1.5; }
.ad-topics strong { position:absolute; left:8px; bottom:8px; color:var(--accent); font-size:.68rem; }
.ad-updates { padding-left:24px; border-left:1px solid var(--line); }
.ad-updates > a { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:12px; padding:8px 0; color:var(--ink); font-size:.68rem; }
.ad-updates > a span { overflow:hidden; white-space:nowrap; text-overflow:ellipsis; }
.ad-updates time { color:var(--muted); font-size:.62rem; }

/* Portrait Journal — 人物主访谈、档案卡墙与最近对话。 */
.portrait-journal-page { width:100%; max-width:1280px; margin-inline:auto; padding:0 30px 34px; }
.pj-lead { display:grid; grid-template-columns:180px 380px minmax(0,1fr); min-height:490px; border-bottom:1px solid var(--line); }
.pj-topic-rail { padding:42px 24px 24px 0; border-right:1px solid var(--line); }
.pj-topic-rail h2 { margin:0 0 16px; padding-bottom:16px; border-bottom:1px solid var(--ink); font:1.1rem var(--serif); }
.pj-topic-rail > a { display:flex; justify-content:space-between; gap:10px; padding:10px 12px; color:var(--ink-soft); font-size:.75rem; }
.pj-topic-rail > a strong { color:var(--muted); font-weight:500; }
.pj-topic-rail > a.active { border-left:3px solid var(--accent); color:var(--accent); font-weight:700; }
.pj-topic-rail > a.active strong { color:var(--accent); }
.pj-topic-rail .pj-topic-all { justify-content:flex-start; margin-top:12px; color:var(--ink); }
.pj-lead-copy { display:flex; flex-direction:column; justify-content:center; padding:40px 44px; }
.pj-lead-copy > p { margin:0 0 18px; color:var(--accent); font-size:.7rem; font-weight:700; letter-spacing:.08em; }
.pj-lead-copy h1 { margin:0; font:600 clamp(2.6rem,3.4vw,3.25rem)/1.05 var(--serif); letter-spacing:-.05em; }
.pj-lead-copy > i { margin-top:24px; color:var(--accent); font:3.2rem/.8 var(--serif); }
.pj-lead-copy blockquote { margin:8px 0 20px; padding:0; border:0; color:var(--ink-soft); font:1rem/1.8 var(--serif); }
.pj-lead-copy > a { color:var(--accent); font-size:.75rem; font-weight:700; }
.pj-lead-copy > time { margin-top:24px; color:var(--muted); font-size:.65rem; }
.pj-feature { position:relative; min-width:0; overflow:hidden; background:var(--accent-wash); }
.pj-feature > a { display:block; width:100%; height:100%; min-height:490px; }
.pj-feature img { width:100%; height:100%; object-fit:cover; filter:saturate(.78); }
.pj-feature.no-cover > a { display:grid; place-items:center; color:var(--accent); font:clamp(8rem,18vw,18rem)/1 var(--serif); }
.pj-feature > div { position:absolute; right:0; bottom:0; left:0; padding:26px 38px 30px; background:rgba(0,0,0,.68); color:#fff; }
.pj-feature h2 { display:-webkit-box; overflow:hidden; margin:0 0 12px; font:600 clamp(1.8rem,2.5vw,2.65rem)/1.04 var(--serif); text-align:right; -webkit-box-orient:vertical; -webkit-line-clamp:2; }
.pj-feature h2 a { color:#fff; }
.pj-feature p { margin:0; font-size:.7rem; text-align:right; }
.pj-content { display:grid; grid-template-columns:minmax(0,2.1fr) minmax(300px,1fr); gap:36px; padding:28px 22px 0; }
.pj-profile-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); }
.pj-profile-grid article { min-width:0; padding:18px 16px 8px 0; border-right:1px solid var(--line); }
.pj-profile-grid article + article { padding-left:16px; }
.pj-profile-cover { display:block; height:150px; overflow:hidden; background:var(--accent-wash); }
.pj-profile-cover img { width:100%; height:100%; object-fit:cover; filter:saturate(.72); transition:filter .2s; }
.pj-profile-cover:hover img { filter:saturate(1); }
.pj-profile-cover.no-cover { display:grid; place-items:center; color:var(--accent); font:4.6rem var(--serif); }
.pj-profile-grid h3 { margin:12px 0 7px; font:1.25rem/1.2 var(--serif); }
.pj-profile-grid h3 a { color:var(--ink); }
.pj-profile-grid p { min-height:3.9em; margin:0 0 12px; color:var(--muted); font-size:.7rem; line-height:1.55; }
.pj-profile-grid small { color:var(--muted); font-size:.62rem; }
.pj-arrow { display:block; margin-top:10px; color:var(--accent); }
.pj-recent > a { display:grid; grid-template-columns:minmax(0,1fr) 100px 76px; gap:8px; padding:15px 0; border-bottom:1px solid var(--line); color:var(--ink); }
.pj-recent b { font:1rem/1.35 var(--serif); }
.pj-recent span,.pj-recent time { align-self:center; color:var(--muted); font-size:.62rem; text-align:right; }

/* Casebook — 旗舰案例、行业轨、模块化案例切片与紧凑速览。 */
.casebook-page { width:100%; max-width:1280px; margin-inline:auto; padding:0 26px 28px; }
.cb-lead { display:grid; grid-template-columns:340px minmax(0,1fr); min-height:350px; border-bottom:1px solid var(--line); }
.cb-proposition { display:flex; flex-direction:column; justify-content:center; padding:38px 38px 38px 40px; border-right:1px solid var(--line); }
.cb-proposition > p { color:var(--accent); font-size:.7rem; font-weight:700; letter-spacing:.05em; }
.cb-proposition h1 { margin:10px 0 20px; font:700 clamp(1.9rem,2.3vw,2.35rem)/1.09 var(--sans); letter-spacing:-.05em; }
.cb-proposition > div { color:var(--ink-soft); font-size:.76rem; line-height:1.75; }
.cb-proposition > a { margin-top:24px; color:var(--accent); font-size:.7rem; }
.cb-feature { display:grid; grid-template-columns:140px minmax(0,1fr) minmax(350px,.9fr); min-width:0; }
.cb-feature > strong { align-self:center; padding-left:30px; color:var(--ink); font:800 clamp(6.5rem,10vw,10rem)/.78 var(--sans); letter-spacing:-.1em; transform:scaleX(.65); transform-origin:left center; }
.cb-feature-copy { display:flex; flex-direction:column; justify-content:center; padding:30px; }
.cb-feature-copy small { color:var(--muted); font-size:.66rem; }
