.cb-feature-cover.no-cover { display:grid; place-items:center; color:var(--accent); font:9rem var(--sans); }
.cb-industries { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); border-bottom:1px solid var(--line); }
