.cb-selected,.cb-ledger { padding:18px 14px 0; }
.cb-case-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:18px; padding:12px 0 18px; }
.cb-case-grid article { display:grid; grid-template-columns:minmax(0,1.1fr) minmax(100px,.9fr); min-width:0; min-height:245px; border:1px solid var(--line); }
.cb-case-copy { display:flex; flex-direction:column; padding:15px 12px; min-width:0; }
