.cb-case-copy small { margin-top:7px; color:var(--muted); font-size:.56rem; }
.cb-case-copy h3 { margin:13px 0 8px; font-size:1rem; line-height:1.35; }
.cb-case-copy h3 a { color:var(--ink); }
.cb-case-copy p { display:-webkit-box; overflow:hidden; margin:0; color:var(--muted); font-size:.64rem; line-height:1.55; -webkit-box-orient:vertical; -webkit-line-clamp:3; }
.cb-case-copy > a { margin-top:auto; color:var(--accent); font-size:.62rem; }
.cb-case-cover { min-width:0; overflow:hidden; background:var(--accent-wash); }
.cb-case-cover img { width:100%; height:100%; object-fit:cover; filter:saturate(.75); }
.cb-case-cover.no-cover { display:grid; place-items:center; color:var(--accent); font:4.4rem var(--sans); }
.cb-ledger-head,.cb-ledger > a { display:grid; grid-template-columns:minmax(0,1fr) 210px 120px 24px; gap:14px; align-items:center; }
.cb-ledger-head { padding:7px 0; border-bottom:1px solid var(--ink); color:var(--muted); font-size:.6rem; }
.cb-ledger > a { min-height:29px; border-bottom:1px solid var(--line); color:var(--ink); font-size:.65rem; }
.cb-ledger > a b { overflow:hidden; white-space:nowrap; text-overflow:ellipsis; }
.cb-ledger > a span,.cb-ledger > a time { color:var(--muted); }
.cb-ledger > a strong { color:var(--accent); text-align:right; }

/* 三套主题的公共内页语言：保持各自色彩和直线构成，不把首页模板数据带入内页。 */
