/* Pilot Flight Deck — one responsive skeleton, three palette cards. */
:root[data-theme="pilot-flight-deck"] {
  --bg:#f5f7fb; --surface:#fff; --text:#0c1017; --ink:#0c1017; --ink-soft:#3e495b;
  --muted:#667085; --faint:#98a2b3; --line:#dce2ec; --line-soft:#e9edf4;
  --accent:#1763e8; --accent-soft:#3e7cea; --accent-wash:#eaf1ff; --code-bg:#101b2d; --radius:8px;
}
:root[data-theme="pilot-flight-deck-white"] {
  --bg:#fff; --surface:#fff; --text:#0a0d13; --ink:#0a0d13; --ink-soft:#3d4654;
  --muted:#667085; --faint:#98a2b3; --line:#e1e5eb; --line-soft:#eef1f5;
  --accent:#1763e8; --accent-soft:#3e7cea; --accent-wash:#edf3ff; --code-bg:#101b2d; --radius:8px;
}
:root[data-theme="pilot-flight-deck-dark"] {
  --bg:#0b111b; --surface:#111a28; --text:#f5f8ff; --ink:#f5f8ff; --ink-soft:#cad3e2;
  --muted:#a8b2c4; --faint:#758299; --line:#263247; --line-soft:#1c2738;
  --accent:#76a9ff; --accent-soft:#9bc0ff; --accent-wash:#16284a; --code-bg:#070b12; --radius:8px;
}
[data-theme-layout="pilot-flight-deck"] body { background:var(--bg); color:var(--text); }
[data-theme-layout="pilot-flight-deck"] .ct-site-header {
  position:sticky; top:0; z-index:40; border:0; border-bottom:1px solid var(--line);
  background:color-mix(in srgb,var(--bg) 92%,transparent); backdrop-filter:blur(16px);
}
[data-theme-layout="pilot-flight-deck"] .ct-header-grid { width:min(1180px,calc(100% - 48px)); height:54px; margin:auto; padding:0; }
[data-theme-layout="pilot-flight-deck"] .ct-main-nav a { font-weight:650; }
[data-theme-layout="pilot-flight-deck"] .ct-main-nav a[aria-current="page"] { color:var(--accent); }
.pfd-page { overflow:hidden; }
.pfd-page :is(h1,h2,h3,h4) { font-family:var(--sans); }
.pfd-wrap { width:min(1180px,calc(100% - 48px)); margin-inline:auto; }
.pfd-hero { padding:34px 0 38px; border-bottom:1px solid var(--line); }
.pfd-hero-grid { min-height:420px; display:grid; grid-template-columns:minmax(0,4fr) minmax(0,6fr); gap:42px; align-items:center; }
.pfd-kicker { margin:0 0 14px; color:var(--accent); font-size:.66rem; line-height:1.4; font-weight:800; letter-spacing:.12em; text-transform:uppercase; }
.pfd-hero h1 { max-width:11em; margin:0; font-size:clamp(2rem,3vw,3rem); line-height:1.06; letter-spacing:-.04em; font-weight:820; }
.pfd-hero h1 br { display:none; }
.pfd-lede { max-width:440px; margin:18px 0 0; color:var(--muted); font-size:.86rem; line-height:1.66; }
.pfd-actions { display:flex; flex-wrap:wrap; gap:10px; margin-top:22px; }
.pfd-btn { display:inline-flex; align-items:center; justify-content:space-between; gap:24px; min-height:42px; padding:0 15px; border:1px solid var(--line); border-radius:6px; color:var(--text); font-size:.8rem; font-weight:750; }
.pfd-btn.primary { color:#fff; border-color:var(--accent); background:var(--accent); }
.pfd-release { display:flex; gap:12px; margin-top:14px; color:var(--muted); font-size:.68rem; }
.pfd-release a,.pfd-release>span { display:flex; gap:10px; color:inherit; }
.pfd-hero-media { min-width:0; min-height:0; display:grid; place-items:center; }
.pfd-hero-media>img,.pfd-hero-embed { width:100%; max-height:440px; object-fit:contain; display:block; }
.pfd-hero-embed>svg { display:block; width:100%; height:auto; max-height:440px; }
.pfd-hero-animation { width:100%; max-height:440px; aspect-ratio:1.48; display:grid; place-items:center; color:var(--accent); }
.pfd-hero-animation>svg { width:100%; height:100%; }
.pfd-section-head { display:flex; align-items:end; justify-content:space-between; gap:20px; margin-bottom:22px; }
.pfd-section-head h2,.pfd-trust h2,.pfd-downloads h2 { margin:0; font-size:clamp(1.55rem,2.5vw,2.6rem); line-height:1.05; letter-spacing:-.035em; }
.pfd-section-head p,.pfd-trust>div>div>p,.pfd-downloads header p { color:var(--muted); }
.pfd-section-head a { color:var(--accent); font-size:.78rem; font-weight:750; }
.pfd-workflow { background:var(--surface); border-bottom:1px solid var(--line); }
.pfd-step-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(0,1fr)); border-left:1px solid var(--line); }
.pfd-step-grid article { min-width:0; min-height:102px; padding:18px 20px; border-right:1px solid var(--line); }
.pfd-step-grid article:last-child { border-right:0; }
.pfd-step-grid span { color:var(--accent); font:700 .66rem ui-monospace,SFMono-Regular,monospace; }
.pfd-step-grid h3 { margin:18px 0 6px; font-size:.9rem; }
.pfd-step-grid p { margin:0; color:var(--muted); font-size:.72rem; line-height:1.5; }
.pfd-demo,.pfd-capabilities,.pfd-cases,.pfd-resources { padding:50px 0; border-bottom:1px solid var(--line); }
.pfd-demo-grid { display:grid; grid-template-columns:minmax(0,1.16fr) minmax(260px,.84fr); gap:42px; align-items:center; }
.pfd-shot { background:var(--surface); border:1px solid var(--line); border-radius:8px; box-shadow:0 14px 44px rgb(15 31 57 / .09); overflow:hidden; }
.pfd-shot img { display:block; width:100%; max-height:350px; object-fit:contain; }
.pfd-demo-copy h2 { margin:0 0 14px; font-size:clamp(1.7rem,2.8vw,2.8rem); line-height:1.06; letter-spacing:-.04em; }
.pfd-demo-copy>p { color:var(--muted); font-size:.82rem; line-height:1.68; }
.pfd-demo-copy>a { display:inline-block; margin-top:14px; color:var(--accent); font-size:.76rem; font-weight:750; }
.pfd-capabilities>.pfd-wrap { display:grid; grid-template-columns:minmax(200px,.72fr) minmax(0,1.28fr); gap:48px; align-items:start; }
.pfd-capabilities .pfd-section-head { display:block; margin:0; }
.pfd-capabilities .pfd-section-head a { display:inline-block; margin-top:20px; }
.pfd-cap-grid { display:grid; grid-template-columns:repeat(2,1fr); border-top:1px solid var(--line); }
.pfd-cap-grid a { min-height:112px; padding:18px 20px; border-right:1px solid var(--line); border-bottom:1px solid var(--line); color:var(--text); }
.pfd-cap-grid a:nth-child(2n) { border-right:0; }
.pfd-cap-grid span { color:var(--accent); font:700 .66rem ui-monospace,SFMono-Regular,monospace; }
.pfd-cap-grid h3 { margin:16px 0 6px; font-size:.94rem; }
.pfd-cap-grid p { margin:0; color:var(--muted); font-size:.7rem; line-height:1.5; }
.pfd-trust { padding:48px 0; background:var(--surface); color:var(--text); border-bottom:1px solid var(--line); }
.pfd-trust-grid { display:grid; grid-template-columns:.72fr 1.28fr; gap:48px; }
.pfd-trust-grid>div:first-child>p { color:var(--muted); font-size:.78rem; line-height:1.6; }
.pfd-trust-list { display:grid; grid-template-columns:1fr 1fr; }
.pfd-trust-list article { padding:18px 0; border-top:1px solid var(--line); }
.pfd-trust-list article:nth-child(odd) { padding-right:22px; }
.pfd-trust-list article:nth-child(even) { padding-left:22px; border-left:1px solid var(--line); }
.pfd-trust-list h3 { margin:0 0 7px; font-size:.94rem; }
.pfd-trust-list p { margin:0; color:var(--muted); font-size:.72rem; line-height:1.55; }
.pfd-case-grid { display:grid; grid-template-columns:1.3fr 1fr 1fr; gap:18px; }
.pfd-case-grid article { min-width:0; }
.pfd-cover { display:block; aspect-ratio:16/9; overflow:hidden; background:var(--surface); border:1px solid var(--line); border-radius:6px; }
.pfd-cover img { width:100%; height:100%; object-fit:cover; transition:transform .35s ease; }
.pfd-cover:hover img { transform:scale(1.025); }
.pfd-case-grid h3 { margin:12px 0 7px; font-size:.96rem; line-height:1.28; }
.pfd-case-grid .lead h3 { font-size:1.15rem; }
.pfd-case-grid p { margin:0; color:var(--muted); font-size:.72rem; line-height:1.55; }
.pfd-resources { padding:26px 0; }
.pfd-resources .pfd-section-head { margin-bottom:16px; }
.pfd-resource-list { display:grid; grid-template-columns:repeat(auto-fit,minmax(130px,1fr)); border-top:1px solid var(--line); border-left:1px solid var(--line); }
.pfd-resource-list a { display:grid; grid-template-columns:1fr auto; gap:6px 12px; align-content:center; min-height:80px; padding:14px 16px; border-right:1px solid var(--line); border-bottom:1px solid var(--line); color:var(--text); }
.pfd-resource-list span { font-size:.82rem; font-weight:750; }
.pfd-resource-list small { grid-column:1/-1; color:var(--muted); font-size:.66rem; line-height:1.45; }
.pfd-resource-list b { color:var(--accent); }
.pfd-downloads { padding:42px 0 52px; background:var(--surface); }
.pfd-download-grid { display:grid; grid-template-columns:.72fr 1.28fr; gap:48px; }
.pfd-download-grid>div { border-top:1px solid var(--line); }
.pfd-download-grid a { display:grid; grid-template-columns:1fr 1fr auto; gap:18px; align-items:center; min-height:66px; border-bottom:1px solid var(--line); color:var(--text); font-size:.78rem; }
.pfd-download-grid a span { color:var(--muted); font-size:.7rem; }
.pfd-download-grid a b { color:var(--accent); }
