    position:absolute; top:54px; right:0; left:0; z-index:55; display:none;
    width:100%; margin:0; box-sizing:border-box; justify-self:stretch;
    flex-direction:column; align-items:stretch; gap:0; padding:8px 12px 12px;
    border-top:1px solid var(--line); border-bottom:1px solid var(--line);
    background:var(--surface); box-shadow:0 16px 30px rgb(15 31 57 / .1);
  }
  [data-theme-layout="pilot-flight-deck"] .ct-site-header.nav-open .ct-main-nav { display:flex; }
  [data-theme-layout="pilot-flight-deck"] .ct-main-nav a { display:block; min-height:42px; padding:11px 4px; border-bottom:1px solid var(--line-soft); }
  [data-theme-layout="pilot-flight-deck"] .ct-main-nav a:last-child { border-bottom:0; }
  [data-theme-layout="pilot-flight-deck"] .ct-main-nav a[aria-current="page"]::after { display:none; }
  .pfd-hero { padding:38px 0 48px; }
  .pfd-hero h1 { font-size:clamp(2.45rem,12vw,3.6rem); }
  .pfd-hero-media { min-height:0; }
  .pfd-hero-grid,.pfd-demo-grid,.pfd-capabilities>.pfd-wrap,.pfd-trust-grid,.pfd-download-grid { grid-template-columns:1fr; gap:38px; }
  .pfd-step-grid,.pfd-cap-grid,.pfd-case-grid,.pfd-trust-list { grid-template-columns:1fr; }
  .pfd-step-grid article,.pfd-cap-grid a,.pfd-trust-list article:nth-child(n) { border-right:0; border-left:0; padding-inline:0; }
  .pfd-resource-list a,.pfd-download-grid a { grid-template-columns:1fr auto; padding:18px 0; }
  .pfd-resource-list small,.pfd-download-grid a span { grid-column:1/-1; grid-row:2; }
  .pfd-demo,.pfd-capabilities,.pfd-cases,.pfd-trust,.pfd-downloads { padding:56px 0; }
}

/* =========================================================================
   LAYOUT: tracklist — 唱片集 album tracklist home (pure CSS, no JS)
   every selector scoped under [data-theme-layout="tracklist"], classes tl-*
   left = sleeve cover square (typography + CSS vinyl disc) / right = tracks
   ========================================================================= */
[data-theme-layout="tracklist"] main { display: block; }
[data-theme-layout="tracklist"] .tl-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding: clamp(1.4rem, 3vw, 2.4rem) 0 clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: header/footer become a slim label strip ------------- */
[data-theme-layout="tracklist"] .site-header { background: var(--bg); border-bottom: 1px solid var(--line); }
[data-theme-layout="tracklist"] .site-header .brand { font-family: var(--mono); font-size: .95rem; letter-spacing: .16em; text-transform: uppercase; }
[data-theme-layout="tracklist"] .site-header .nav a { font-family: var(--mono); font-size: .78rem; letter-spacing: .1em; text-transform: uppercase; }
[data-theme-layout="tracklist"] .site-footer { background: var(--bg); border-top: 1px solid var(--line); }

/* ---- record spread: cover square + tracklist pane ----------------------- */
[data-theme-layout="tracklist"] .tl-record {
  display: grid; grid-template-columns: minmax(0, .92fr) minmax(0, 1.08fr);
  gap: clamp(1.4rem, 3.5vw, 2.8rem); align-items: start;
}

/* cover: pure typography + vinyl disc peeking out of the sleeve corner */
[data-theme-layout="tracklist"] .tl-cover {
  position: relative; overflow: hidden;
  display: flex; flex-direction: column; align-items: flex-start; gap: .6rem;
  aspect-ratio: 1 / 1;
  padding: clamp(1.2rem, 2.6vw, 2rem);
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); box-shadow: var(--shadow);
}
[data-theme-layout="tracklist"] .tl-cover > * { position: relative; z-index: 1; min-width: 0; }
[data-theme-layout="tracklist"] .tl-imprint {
  padding: .3rem .6rem; border: 1px solid var(--line);
  font-family: var(--mono); font-size: .7rem; font-weight: 700;
  letter-spacing: .22em; text-transform: uppercase; color: var(--accent);
  overflow-wrap: anywhere;
}
[data-theme-layout="tracklist"] .tl-title {
  margin: .4rem 0 0; font-family: var(--sans); font-weight: 850;
  font-size: clamp(2.1rem, 4.6vw, 3.5rem); line-height: 1.04; letter-spacing: -.015em;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="tracklist"] .tl-year {
  align-self: stretch; margin-top: .4rem; padding-top: .6rem; border-top: 1px solid var(--line);
  font-family: var(--mono); font-size: .72rem; letter-spacing: .18em;
  text-transform: uppercase; font-variant-numeric: tabular-nums; color: var(--muted);
}
[data-theme-layout="tracklist"] .tl-note {
  margin: .1rem 0 0; max-width: 44ch;
  font-size: .92rem; line-height: 1.6; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="tracklist"] .tl-disc {
  position: absolute; z-index: 0; right: -20%; bottom: -20%;
  width: 62%; aspect-ratio: 1 / 1; border-radius: 50%; pointer-events: none;
  /* vinyl is black on every skin: constant near-black grooves, token label */
  background:
    repeating-radial-gradient(circle at 50% 50%, rgba(255, 255, 255, .07) 0 1px, transparent 1px 6px),
    radial-gradient(circle at 50% 50%, #17140f 0 62%, #0b0a08 100%);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, .08), 0 10px 30px rgba(0, 0, 0, .35);
}
[data-theme-layout="tracklist"] .tl-disc i {
  position: absolute; inset: 33%; border-radius: 50%;
  background: radial-gradient(circle at 50% 50%, #0b0a08 0 11%, var(--accent) 11% 100%);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, .4);
}

/* ---- side facets: category capsules, first one highlighted -------------- */
[data-theme-layout="tracklist"] .tl-sides { display: flex; flex-wrap: wrap; gap: .45rem; margin: 0 0 1.15rem; }
[data-theme-layout="tracklist"] .tl-side {
  display: inline-flex; align-items: baseline; gap: .45rem; min-width: 0;
  padding: .34rem .8rem; border: 1px solid var(--line); border-radius: 999px;
  font-family: var(--mono); font-size: .76rem; letter-spacing: .08em; text-transform: uppercase;
  color: var(--ink-soft); text-decoration: none; background: var(--surface);
  transition: color .15s, border-color .15s;
}
[data-theme-layout="tracklist"] .tl-side:hover { border-color: var(--accent); color: var(--accent); }
[data-theme-layout="tracklist"] .tl-side-name { overflow-wrap: anywhere; }
[data-theme-layout="tracklist"] .tl-side-n { font-size: .66rem; color: var(--faint); font-variant-numeric: tabular-nums; }
[data-theme-layout="tracklist"] .tl-side:first-child { background: var(--accent); border-color: var(--accent); color: var(--bg); }
[data-theme-layout="tracklist"] .tl-side:first-child:hover { color: var(--bg); }
[data-theme-layout="tracklist"] .tl-side:first-child .tl-side-n { color: inherit; }
[data-theme-layout="tracklist"] .tl-side-all { color: var(--accent); }

/* ---- running track numbers: lead + rows share one counter (A1, A2 …) ---- */
[data-theme-layout="tracklist"] .tl-tracks { counter-reset: tl-track; min-width: 0; }
[data-theme-layout="tracklist"] .tl-lead,
[data-theme-layout="tracklist"] .tl-track { counter-increment: tl-track; }
[data-theme-layout="tracklist"] .tl-no {
  font-family: var(--mono); font-variant-numeric: tabular-nums;
  font-size: .8rem; color: var(--faint);
}
[data-theme-layout="tracklist"] .tl-no::before { content: "A" counter(tl-track); }

/* lead track: enlarged featured row */
[data-theme-layout="tracklist"] .tl-lead {
  display: grid; grid-template-columns: 3.2rem 96px minmax(0, 1fr);
  gap: 1rem; align-items: center;
  margin: 0 0 1.25rem; padding: 1rem;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); box-shadow: var(--shadow);
  text-decoration: none; color: var(--ink);
  transition: border-color .15s;
}
[data-theme-layout="tracklist"] .tl-lead:hover { border-color: var(--accent); }
[data-theme-layout="tracklist"] .tl-lead .tl-no { font-size: 1.05rem; font-weight: 700; color: var(--accent); }
[data-theme-layout="tracklist"] .tl-lead-art {
  width: 96px; aspect-ratio: 1 / 1; overflow: hidden;
  display: grid; place-items: center;
  border: 1px solid var(--line-soft); border-radius: calc(var(--radius) * .6);
  background: var(--accent-wash);
}
[data-theme-layout="tracklist"] .tl-lead-art img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="tracklist"] .tl-lead-art b { font-family: var(--mono); font-size: 2rem; color: var(--accent); }
[data-theme-layout="tracklist"] .tl-lead-body { min-width: 0; }
[data-theme-layout="tracklist"] .tl-kicker {
  display: inline-flex; align-items: baseline; gap: .5rem;
  font-family: var(--mono); font-size: .66rem; font-weight: 800;
  letter-spacing: .16em; text-transform: uppercase; color: var(--accent);
}
[data-theme-layout="tracklist"] .tl-kicker-sep { color: var(--faint); font-weight: 400; }
[data-theme-layout="tracklist"] .tl-kicker-cat { color: var(--muted); overflow-wrap: anywhere; }
[data-theme-layout="tracklist"] .tl-lead-h {
  display: block; margin-top: .3rem;
  font-size: clamp(1.25rem, 2.4vw, 1.7rem); font-weight: 800; line-height: 1.18;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="tracklist"] .tl-lead:hover .tl-lead-h { color: var(--accent); }
[data-theme-layout="tracklist"] .tl-lead-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  margin-top: .35rem; font-size: .88rem; line-height: 1.55; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="tracklist"] .tl-lead-date {
  display: block; margin-top: .5rem;
  font-family: var(--mono); font-size: .66rem; letter-spacing: .1em;
  text-transform: uppercase; color: var(--faint);
}

/* tracklist rows */
[data-theme-layout="tracklist"] .tl-list-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  padding-bottom: .45rem; border-bottom: 2px solid var(--ink);
}
[data-theme-layout="tracklist"] .tl-list-t {
  margin: 0; font-family: var(--mono); font-size: .72rem; font-weight: 800;
  letter-spacing: .2em; text-transform: uppercase; color: var(--ink);
}
[data-theme-layout="tracklist"] .tl-list-all {
  display: inline-flex; align-items: center; gap: .3rem; flex: 0 0 auto;
  font-family: var(--mono); font-size: .7rem; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase;
  color: var(--accent); text-decoration: none;
}
[data-theme-layout="tracklist"] .tl-list { list-style: none; margin: 0; padding: 0; }
[data-theme-layout="tracklist"] .tl-track-in {
  display: grid; grid-template-columns: 3.2rem minmax(0, 1fr) auto;
  gap: .3rem 1rem; align-items: baseline;
  padding: .78rem .2rem; border-bottom: 1px solid var(--line-soft);
  text-decoration: none; color: var(--ink);
  transition: background .15s;
}
[data-theme-layout="tracklist"] .tl-track-in:hover { background: var(--accent-wash); }
[data-theme-layout="tracklist"] .tl-track-body { min-width: 0; }
[data-theme-layout="tracklist"] .tl-track-h {
  display: block; font-size: 1.02rem; font-weight: 700; line-height: 1.35;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="tracklist"] .tl-track-in:hover .tl-track-h { color: var(--accent); }
[data-theme-layout="tracklist"] .tl-track-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  margin-top: .15rem; font-size: .82rem; line-height: 1.5; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="tracklist"] .tl-track-meta {
  display: flex; align-items: baseline; gap: .7rem; justify-self: end; text-align: right;
  font-family: var(--mono); font-size: .68rem; letter-spacing: .06em;
  text-transform: uppercase; font-variant-numeric: tabular-nums; color: var(--faint);
}
[data-theme-layout="tracklist"] .tl-track-cat { color: var(--muted); overflow-wrap: anywhere; }

/* ---- credits: two-column colophon --------------------------------------- */
[data-theme-layout="tracklist"] .tl-credits {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr));
  gap: clamp(1.2rem, 3vw, 2.4rem);
  margin-top: clamp(1.8rem, 4vw, 2.8rem); padding-top: 1.1rem;
  border-top: 3px solid var(--ink);
}
[data-theme-layout="tracklist"] .tl-credit-h {
  margin: 0 0 .45rem; font-family: var(--mono); font-size: .7rem; font-weight: 800;
  letter-spacing: .2em; text-transform: uppercase; color: var(--ink);
}
[data-theme-layout="tracklist"] .tl-credit {
  display: flex; align-items: center; gap: .6rem; min-width: 0;
  padding: .5rem 0; border-bottom: 1px dotted var(--line);
  text-decoration: none; color: var(--ink);
}
[data-theme-layout="tracklist"] .tl-credit-ic {
  flex: 0 0 auto; width: 34px; height: 34px; overflow: hidden;
  display: grid; place-items: center; border-radius: 999px;
  background: var(--accent-wash); color: var(--accent);
}
[data-theme-layout="tracklist"] .tl-credit-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="tracklist"] .tl-credit-ic b { font-family: var(--mono); font-size: .95rem; }
[data-theme-layout="tracklist"] .tl-credit-t { font-size: .92rem; font-weight: 600; overflow-wrap: anywhere; transition: color .15s; }
[data-theme-layout="tracklist"] .tl-credit:hover .tl-credit-t { color: var(--accent); }
[data-theme-layout="tracklist"] .tl-credit-nav { display: flex; flex-direction: column; align-items: flex-start; gap: .5rem; }
[data-theme-layout="tracklist"] .tl-credit-nav a {
  font-family: var(--mono); font-size: .8rem; letter-spacing: .12em; text-transform: uppercase;
  color: var(--ink-soft); text-decoration: none; transition: color .15s;
}
[data-theme-layout="tracklist"] .tl-credit-nav a:hover { color: var(--accent); }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="tracklist"] .tl-record { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="tracklist"] .tl-cover { aspect-ratio: auto; padding-bottom: clamp(4.5rem, 14vw, 6rem); }
  [data-theme-layout="tracklist"] .tl-disc { width: min(46%, 260px); right: -12%; bottom: -34%; }
}
@media (max-width: 720px) {
  [data-theme-layout="tracklist"] .tl-title { font-size: clamp(1.8rem, 9vw, 2.6rem); }
  [data-theme-layout="tracklist"] .tl-lead { grid-template-columns: 2.5rem 64px minmax(0, 1fr); gap: .8rem; padding: .8rem; }
  [data-theme-layout="tracklist"] .tl-lead-art { width: 64px; }
  [data-theme-layout="tracklist"] .tl-lead-art b { font-size: 1.4rem; }
  [data-theme-layout="tracklist"] .tl-track-in { grid-template-columns: 2.5rem minmax(0, 1fr); }
  [data-theme-layout="tracklist"] .tl-track-meta { grid-column: 2; justify-self: start; text-align: left; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="tracklist"] .tl-side,
  [data-theme-layout="tracklist"] .tl-lead,
  [data-theme-layout="tracklist"] .tl-lead-h,
  [data-theme-layout="tracklist"] .tl-track-in,
  [data-theme-layout="tracklist"] .tl-track-h,
  [data-theme-layout="tracklist"] .tl-list-all,
  [data-theme-layout="tracklist"] .tl-credit-t,
  [data-theme-layout="tracklist"] .tl-credit-nav a { transition: none; }
}

/* ============================================================
   黑胶 · Tracklist —— Tracklist 骨架默认皮：近黑胶盘、金标、米白字
   ============================================================ */
:root[data-theme="tracklist"] {
  --bg: #14120f; --surface: #1c1915;
  --ink: #f2ead9; --ink-soft: #d9d0bd; --muted: #aca289; --faint: #8d8470;
  --line: #353026; --line-soft: #262219;
  --accent: #c9a227; --accent-soft: #e0bc45; --accent-wash: #2a2412;
  --w-wide: 1200px; --radius: 10px; --code-bg: #0b0a08;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 12px 32px rgba(0, 0, 0, .5);
}
:root[data-theme="tracklist"] .btn-primary { color: #14120f; }
:root[data-theme="tracklist"] .site-header { background: rgba(20, 18, 15, .92); }

/* ============================================================
   封套 · Sleeve —— Tracklist 骨架 + 米白卡纸封套皮（墨黑衬线、烧橙标）
   ============================================================ */
:root[data-theme="sleeve"] {
  --bg: #f3ede1; --surface: #faf6ec;
  --ink: #1d1a15; --ink-soft: #3b362c; --muted: #655d4d; --faint: #726955;
  --line: #d9d1bd; --line-soft: #e7e0cd;
  --accent: #993a10; --accent-soft: #7c2f0d; --accent-wash: #efdfd0;
  --w-wide: 1200px; --radius: 2px;
  --shadow: 0 1px 2px rgba(29, 26, 21, .06), 0 8px 22px rgba(29, 26, 21, .08);
}
:root[data-theme="sleeve"] .btn-primary { color: #fff; }
:root[data-theme="sleeve"] .site-header .brand,
:root[data-theme="sleeve"] .site-header .nav a { font-family: var(--serif); font-variant: small-caps; text-transform: none; letter-spacing: .12em; }
/* 卡纸印刷味：标题改衬线，唱片名不再全大写压缩 */
:root[data-theme="sleeve"] .tl-title,
:root[data-theme="sleeve"] .tl-lead-h,
:root[data-theme="sleeve"] .tl-track-h,
:root[data-theme="sleeve"] .tl-credit-t { font-family: var(--serif); }
:root[data-theme="sleeve"] .tl-title { font-weight: 700; letter-spacing: 0; }
:root[data-theme="sleeve"] .tl-note { font-family: var(--serif); font-style: italic; }
:root[data-theme="sleeve"] .tl-list-t,
:root[data-theme="sleeve"] .tl-credit-h { font-family: var(--serif); font-variant: small-caps; text-transform: none; letter-spacing: .18em; }
:root[data-theme="sleeve"] .tl-side { font-family: var(--serif); font-variant: small-caps; text-transform: none; letter-spacing: .08em; font-size: .88rem; }
/* 烧橙实底厂牌标（反白），主打曲卡片改细墨线框 */
:root[data-theme="sleeve"] .tl-imprint { background: var(--accent); border-color: var(--accent); color: #fff; }
:root[data-theme="sleeve"] .tl-cover,
:root[data-theme="sleeve"] .tl-lead { border-color: var(--ink); }
:root[data-theme="sleeve"] .tl-lead { box-shadow: none; }

/* =========================================================================
   LAYOUT: departure — 发车牌 station departures board (pure CSS, no JS)
   every selector scoped under [data-theme-layout="departure"], classes dp-*
   带状页头 / 表头栏 / 「即将发车」放大首行 / counter 车次编号 / 候车厅指路牌
   ========================================================================= */
[data-theme-layout="departure"] { --dp-mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace; }
[data-theme-layout="departure"] main { display: block; }
[data-theme-layout="departure"] .dp-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding: clamp(1.4rem, 3vw, 2.4rem) 0 clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: header/footer restyled as station signage ----------- */
[data-theme-layout="departure"] .site-header { background: var(--bg); border-bottom: 1px solid var(--line); }
[data-theme-layout="departure"] .site-header .brand { font-family: var(--dp-mono); text-transform: uppercase; letter-spacing: .16em; }
[data-theme-layout="departure"] .site-header .nav a { font-family: var(--dp-mono); font-size: .85em; text-transform: uppercase; letter-spacing: .08em; }
[data-theme-layout="departure"] .site-footer { border-top: 3px solid var(--accent); }

/* ---- band: station name (wide tracking) + notice text on the right ------ */
[data-theme-layout="departure"] .dp-band {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1.2rem 2.5rem;
  background: var(--surface); border-top: 3px solid var(--ink); border-bottom: 1px solid var(--line);
  border-radius: var(--radius); padding: 1.15rem 1.3rem 1.25rem;
  margin-bottom: clamp(1.4rem, 3vw, 2.2rem);
}
[data-theme-layout="departure"] .dp-band-main { min-width: 0; }
[data-theme-layout="departure"] .dp-eyebrow {
  display: block; margin-bottom: .5rem;
  font-family: var(--dp-mono); font-size: .7rem; letter-spacing: .26em; text-transform: uppercase;
  color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="departure"] .dp-station {
  margin: 0; font-family: var(--dp-mono); font-weight: 700;
  font-size: clamp(1.9rem, 5vw, 3.4rem); line-height: 1.08;
  letter-spacing: .18em; text-transform: uppercase;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="departure"] .dp-notice {
  margin: 0; max-width: 34ch; flex: 0 1 auto;
  font-size: .92rem; line-height: 1.6; text-align: right;
  color: var(--muted); overflow-wrap: anywhere;
}

/* ---- board: head strip / column labels / lead row / timetable rows ------ */
[data-theme-layout="departure"] .dp-board {
  --dp-grid: 8.5rem minmax(0, 1fr) 9rem 4.5rem;
  counter-reset: dp-train;
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--radius); overflow: hidden;
}
[data-theme-layout="departure"] .dp-board-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  padding: .85rem 1.2rem; border-bottom: 1px solid var(--line);
}
[data-theme-layout="departure"] .dp-board-t {
  margin: 0; font-family: var(--dp-mono); font-size: .78rem; font-weight: 700;
  letter-spacing: .22em; text-transform: uppercase; color: var(--ink);
}
[data-theme-layout="departure"] .dp-board-all {
  display: inline-flex; align-items: center; gap: .3rem; flex: 0 0 auto;
  font-family: var(--dp-mono); font-size: .72rem; letter-spacing: .08em; text-transform: uppercase;
  color: var(--accent); text-decoration: none;
}
[data-theme-layout="departure"] .dp-board-all:hover { text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="departure"] .dp-cols {
  display: grid; grid-template-columns: var(--dp-grid); gap: 0 1.2rem;
  padding: .5rem 1.2rem; border-bottom: 2px solid var(--ink);
  font-family: var(--dp-mono); font-size: .68rem; letter-spacing: .22em; text-transform: uppercase;
  color: var(--faint);
}
[data-theme-layout="departure"] .dp-col { min-width: 0; overflow-wrap: anywhere; }
[data-theme-layout="departure"] .dp-col-no { text-align: right; }

/* lead row: the enlarged "boarding now" departure with a thick accent edge */
[data-theme-layout="departure"] .dp-lead {
  display: grid; grid-template-columns: var(--dp-grid); gap: .35rem 1.2rem; align-items: start;
  counter-increment: dp-train;
  padding: 1.15rem 1.2rem 1.3rem; border-left: 6px solid var(--accent); border-bottom: 1px solid var(--line);
  background: var(--accent-wash); text-decoration: none; color: var(--ink);
}
[data-theme-layout="departure"] .dp-lead:focus-visible { outline-offset: -3px; }
[data-theme-layout="departure"] .dp-lead-time { display: flex; flex-direction: column; align-items: flex-start; gap: .5rem; min-width: 0; }
[data-theme-layout="departure"] .dp-lead-time time {
  font-family: var(--dp-mono); font-weight: 700; font-size: 1rem;
  letter-spacing: .03em; font-variant-numeric: tabular-nums; color: var(--accent);
}
[data-theme-layout="departure"] .dp-lead-kicker {
  font-family: var(--dp-mono); font-weight: 700; font-size: .62rem;
  letter-spacing: .18em; text-transform: uppercase;
  background: var(--accent); color: #fff; border-radius: 3px; padding: .3rem .5rem;
  overflow-wrap: anywhere;
}
[data-theme-layout="departure"] .dp-lead-dest { display: flex; flex-direction: column; gap: .45rem; min-width: 0; }
[data-theme-layout="departure"] .dp-lead-h {
  font-weight: 800; font-size: clamp(1.35rem, 3vw, 2.1rem); line-height: 1.12;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="departure"] .dp-lead:hover .dp-lead-h { color: var(--accent); }
[data-theme-layout="departure"] .dp-lead-ex {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .95rem; line-height: 1.6; color: var(--ink-soft); overflow-wrap: anywhere;
}
[data-theme-layout="departure"] .dp-lead-cover { display: block; margin-top: .35rem; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
[data-theme-layout="departure"] .dp-lead-cover img { display: block; width: 100%; height: auto; max-height: 340px; object-fit: cover; }
[data-theme-layout="departure"] .dp-lead-more {
  display: inline-flex; align-items: center; gap: .35rem; margin-top: .2rem;
  font-family: var(--dp-mono); font-size: .72rem; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase; color: var(--accent);
}

/* timetable rows */
/* explicit cell placement: 无分类（.dp-plat 缺席）时防止车次编号滑进站台列 */
[data-theme-layout="departure"] .dp-lead-time, [data-theme-layout="departure"] .dp-time { grid-column: 1; }
[data-theme-layout="departure"] .dp-lead-dest, [data-theme-layout="departure"] .dp-dest { grid-column: 2; }
[data-theme-layout="departure"] .dp-plat { grid-column: 3; }
[data-theme-layout="departure"] .dp-no { grid-column: 4; }
[data-theme-layout="departure"] .dp-row { border-bottom: 1px solid var(--line-soft); counter-increment: dp-train; }
[data-theme-layout="departure"] .dp-row:last-child { border-bottom: 0; }
[data-theme-layout="departure"] .dp-row-in {
  display: grid; grid-template-columns: var(--dp-grid); gap: .2rem 1.2rem; align-items: start;
  padding: .95rem 1.2rem; text-decoration: none; color: var(--ink);
  transition: background .15s;
}
[data-theme-layout="departure"] .dp-row-in:hover { background: var(--accent-wash); }
[data-theme-layout="departure"] .dp-row-in:focus-visible { outline-offset: -3px; }
[data-theme-layout="departure"] .dp-time {
  font-family: var(--dp-mono); font-weight: 700; font-size: .95rem;
  letter-spacing: .03em; font-variant-numeric: tabular-nums; color: var(--accent);
}
[data-theme-layout="departure"] .dp-dest { min-width: 0; }
[data-theme-layout="departure"] .dp-dest-t {
  display: block; font-weight: 700; font-size: 1.06rem; line-height: 1.3;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="departure"] .dp-row-in:hover .dp-dest-t { color: var(--accent); }
[data-theme-layout="departure"] .dp-dest-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  margin-top: .2rem; font-size: .85rem; line-height: 1.5; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="departure"] .dp-plat {
  justify-self: start; min-width: 0; overflow-wrap: anywhere;
  font-family: var(--dp-mono); font-size: .72rem; letter-spacing: .12em; text-transform: uppercase;
  color: var(--ink-soft); background: var(--bg); border: 1px solid var(--line);
  border-radius: 3px; padding: .28rem .55rem;
}
[data-theme-layout="departure"] .dp-no {
  font-family: var(--dp-mono); font-size: .85rem; letter-spacing: .1em;
  font-variant-numeric: tabular-nums; text-align: right; color: var(--faint);
}
[data-theme-layout="departure"] .dp-no::before { content: counter(dp-train, decimal-leading-zero); }

/* ---- transfer strip: featured links as round passes --------------------- */
[data-theme-layout="departure"] .dp-transfer { margin-top: clamp(1.6rem, 4vw, 2.4rem); }
[data-theme-layout="departure"] .dp-transfer-h {
  margin: 0 0 .7rem; font-family: var(--dp-mono); font-size: .7rem; font-weight: 700;
  letter-spacing: .22em; text-transform: uppercase; color: var(--muted);
}
[data-theme-layout="departure"] .dp-transfer-list { display: flex; flex-wrap: wrap; gap: .6rem; }
[data-theme-layout="departure"] .dp-pass {
  display: inline-flex; align-items: center; gap: .55rem; min-width: 0;
  background: var(--surface); border: 1px solid var(--line); border-radius: 999px;
  padding: .35rem .85rem .35rem .4rem; text-decoration: none; color: var(--ink-soft);
  transition: border-color .15s, color .15s;
}
[data-theme-layout="departure"] .dp-pass:hover { border-color: var(--accent); color: var(--ink); }
[data-theme-layout="departure"] .dp-pass-ic {
  flex: 0 0 auto; width: 26px; height: 26px; border-radius: 50%; overflow: hidden;
  display: grid; place-items: center; background: var(--accent-wash); color: var(--accent);
}
[data-theme-layout="departure"] .dp-pass-ic b { font-family: var(--dp-mono); font-size: .78rem; line-height: 1; }
[data-theme-layout="departure"] .dp-pass-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="departure"] .dp-pass-t { font-size: .85rem; min-width: 0; overflow-wrap: anywhere; }

/* ---- hall: categories as waiting-hall wayfinding signs ------------------ */
[data-theme-layout="departure"] .dp-hall {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: clamp(.7rem, 1.6vw, 1rem); margin-top: clamp(1.8rem, 4vw, 2.8rem);
}
[data-theme-layout="departure"] .dp-sign {
  display: flex; align-items: flex-end; justify-content: space-between; gap: .8rem;
  min-height: 108px; min-width: 0; padding: .9rem 1rem;
  background: var(--accent); color: #fff; border-radius: var(--radius); box-shadow: var(--shadow);
  text-decoration: none; transition: transform .15s, box-shadow .15s;
}
[data-theme-layout="departure"] .dp-sign:nth-child(4n+2) { background: var(--accent-soft); }
[data-theme-layout="departure"] .dp-sign:nth-child(4n+3) { background: color-mix(in srgb, var(--accent) 72%, #000); }
[data-theme-layout="departure"] .dp-sign:nth-child(4n) { background: color-mix(in srgb, var(--accent) 60%, var(--ink)); }
[data-theme-layout="departure"] .dp-sign:hover { transform: translateY(-3px); }
[data-theme-layout="departure"] .dp-sign-name { font-weight: 800; font-size: 1.05rem; line-height: 1.25; overflow-wrap: anywhere; }
[data-theme-layout="departure"] .dp-sign-n { flex: 0 0 auto; font-family: var(--dp-mono); font-size: .95rem; font-variant-numeric: tabular-nums; }
[data-theme-layout="departure"] .dp-sign-arrow { flex: 0 0 auto; font-family: var(--dp-mono); font-size: 1rem; }
[data-theme-layout="departure"] .dp-sign.dp-sign-all { background: var(--surface); color: var(--ink); border: 1px dashed var(--line); box-shadow: none; }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="departure"] .dp-band { flex-direction: column; align-items: flex-start; }
  [data-theme-layout="departure"] .dp-notice { text-align: left; max-width: 60ch; }
  [data-theme-layout="departure"] .dp-board { --dp-grid: 7rem minmax(0, 1fr) 7.5rem; }
  [data-theme-layout="departure"] .dp-no, [data-theme-layout="departure"] .dp-col-no { display: none; }
}
@media (max-width: 720px) {
  [data-theme-layout="departure"] .dp-station { letter-spacing: .1em; }
  [data-theme-layout="departure"] .dp-cols { display: none; }
  [data-theme-layout="departure"] .dp-lead,
  [data-theme-layout="departure"] .dp-row-in { display: flex; flex-direction: column; align-items: flex-start; gap: .45rem; }
  [data-theme-layout="departure"] .dp-lead { padding: 1rem 1rem 1.15rem; }
  [data-theme-layout="departure"] .dp-lead-time { flex-direction: row; align-items: center; gap: .7rem; flex-wrap: wrap; }
  [data-theme-layout="departure"] .dp-row-in { padding: .85rem 1rem; }
  [data-theme-layout="departure"] .dp-hall { grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); }
  [data-theme-layout="departure"] .dp-sign { min-height: 88px; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="departure"] .dp-lead-h,
  [data-theme-layout="departure"] .dp-dest-t,
  [data-theme-layout="departure"] .dp-row-in,
  [data-theme-layout="departure"] .dp-pass,
  [data-theme-layout="departure"] .dp-sign { transition: none; }
  [data-theme-layout="departure"] .dp-sign:hover { transform: none; }
}

/* ============================================================
   夜航 · Departure —— Departure 骨架默认皮：黑夜站厅、琥珀翻牌字、等宽主导
   ============================================================ */
:root[data-theme="departure"] {
  --bg: #0d0e10; --surface: #15161a;
  --ink: #f2f0ea; --ink-soft: #cfccc2; --muted: #9a968a; --faint: #8a857a;
  --line: #26282d; --line-soft: #1b1d21;
  --accent: #ffb340; --accent-soft: #ffc866; --accent-wash: #241a09;
  --w-wide: 1200px; --radius: 6px; --code-bg: #000000;
  --shadow: 0 1px 2px rgba(0,0,0,.5), 0 12px 30px rgba(0,0,0,.55);
}
:root[data-theme="departure"] .site-header { background: rgba(13,14,16,.92); }
:root[data-theme="departure"] .btn-primary { color: #101112; }
/* 翻牌规矩:琥珀色块上的字一律近黑反衬,不用白 */
:root[data-theme="departure"] .dp-lead-kicker { color: #101112; }
:root[data-theme="departure"] .dp-sign:not(.dp-sign-all) { color: #101112; }
/* 等宽主导:目的地标题也进等宽翻牌字 */
:root[data-theme="departure"] .dp-lead-h,
:root[data-theme="departure"] .dp-dest-t { font-family: var(--dp-mono); letter-spacing: .02em; }

/* ============================================================
   日间 · Dayline —— Departure 骨架 + 暖白日间站厅皮（墨绿站牌、黑体收字距）
   ============================================================ */
:root[data-theme="dayline"] {
  --bg: #faf6ee; --surface: #fffdf7;
  --ink: #1c1b17; --ink-soft: #3a372f; --muted: #5c574b; --faint: #6f695b;
  --line: #ddd5c4; --line-soft: #eae4d6;
  --accent: #1f5b46; --accent-soft: #2e6f57; --accent-wash: #e8efe8;
  --w-wide: 1200px; --radius: 6px;
  --shadow: 0 1px 2px rgba(28,27,23,.06), 0 8px 22px rgba(28,27,23,.08);
}
:root[data-theme="dayline"] .site-header { background: rgba(250,246,238,.92); }
:root[data-theme="dayline"] .btn-primary { color: #fff; }
/* 日间字面:站名换黑体、收字距;时刻/编号列仍保留等宽 */
:root[data-theme="dayline"] .dp-station { font-family: var(--sans); font-weight: 800; letter-spacing: .06em; }
:root[data-theme="dayline"] .dp-eyebrow, :root[data-theme="dayline"] .dp-board-t { letter-spacing: .14em; }
:root[data-theme="dayline"] .dp-band { border-top-color: var(--accent); }

/* =========================================================================
   LAYOUT: lexicon — 辞书正文页 dictionary page (pure CSS, no JS)
   spine band + featured entry + dense entry rows + thumb-index rail + legend
   every selector scoped under [data-theme-layout="lexicon"], classes lx-*
   ========================================================================= */
[data-theme-layout="lexicon"] main { display: block; }
[data-theme-layout="lexicon"] .lx-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto;
  padding: clamp(1.4rem, 3vw, 2.4rem) 0 clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: header/footer take on frontmatter typography -------- */
[data-theme-layout="lexicon"] .site-header { background: var(--bg); border-bottom: 1px solid var(--line); }
[data-theme-layout="lexicon"] .site-header .brand { font-family: var(--serif); font-variant: small-caps; letter-spacing: .14em; }
[data-theme-layout="lexicon"] .site-header .nav a { font-family: var(--serif); font-variant: small-caps; letter-spacing: .1em; }
[data-theme-layout="lexicon"] .site-footer { border-top: 4px double var(--line); }

/* ---- spine band: reversed HeroTitle + HeroEyebrow as the edition line --- */
[data-theme-layout="lexicon"] .lx-spine {
  position: relative; text-align: center;
  background: var(--accent); color: var(--bg);
  padding: clamp(1.5rem, 4vw, 2.4rem) clamp(1rem, 4vw, 2.5rem);
  border-radius: var(--radius); box-shadow: var(--shadow);
  margin-bottom: clamp(1.4rem, 3vw, 2rem);
}
[data-theme-layout="lexicon"] .lx-spine::before,
[data-theme-layout="lexicon"] .lx-spine::after {
  content: ""; position: absolute; left: 14px; right: 14px;
  border-top: 1px solid color-mix(in srgb, var(--bg) 45%, transparent);
}
[data-theme-layout="lexicon"] .lx-spine::before { top: 9px; }
[data-theme-layout="lexicon"] .lx-spine::after { bottom: 9px; }
[data-theme-layout="lexicon"] .lx-title {
  margin: 0; font-family: var(--serif); font-weight: 800;
  font-size: clamp(1.75rem, 4.5vw, 2.8rem); line-height: 1.12; letter-spacing: .03em;
  color: inherit; overflow-wrap: anywhere;
}
[data-theme-layout="lexicon"] .lx-edition {
  margin: .55rem 0 0; font-family: var(--mono); font-size: .7rem;
  letter-spacing: .24em; text-transform: uppercase; overflow-wrap: anywhere;
}

/* ---- page grid: thumb-index rail (category initials) + main column ------ */
[data-theme-layout="lexicon"] .lx-page {
  display: grid; grid-template-columns: 48px minmax(0, 1fr);
  gap: clamp(1rem, 2.5vw, 1.8rem); align-items: start;
}
[data-theme-layout="lexicon"] .lx-page-solo { grid-template-columns: minmax(0, 1fr); }
[data-theme-layout="lexicon"] .lx-thumb { position: sticky; top: 84px; display: flex; flex-direction: column; gap: .35rem; }
[data-theme-layout="lexicon"] .lx-tab {
  position: relative; display: grid; place-items: center;
  width: 48px; height: 42px; border: 1px solid var(--line); border-radius: 0 999px 999px 0;
  background: var(--surface); color: var(--ink-soft); text-decoration: none;
  transition: background .15s, color .15s, border-color .15s;
}
[data-theme-layout="lexicon"] .lx-tab b { font-family: var(--serif); font-weight: 800; font-size: 1rem; line-height: 1; }
[data-theme-layout="lexicon"] .lx-tab:hover,
[data-theme-layout="lexicon"] .lx-tab:focus-visible { background: var(--accent); border-color: var(--accent); color: var(--bg); }
[data-theme-layout="lexicon"] .lx-tab-all { color: var(--accent); }
[data-theme-layout="lexicon"] .lx-tab-name {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap;
}

/* ---- featured entry: headword / part-of-speech / numbered definition ---- */
[data-theme-layout="lexicon"] .lx-lead {
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); box-shadow: var(--shadow);
  padding: clamp(1.1rem, 3vw, 1.8rem);
}
[data-theme-layout="lexicon"] .lx-lead-label {
  margin: 0 0 .8rem; padding-bottom: .55rem; border-bottom: 1px solid var(--line);
  font-family: var(--sans); font-size: .72rem; font-weight: 800;
  letter-spacing: .22em; text-transform: uppercase; color: var(--accent-soft);
}
[data-theme-layout="lexicon"] .lx-lead-in { display: block; min-width: 0; text-decoration: none; color: var(--ink); }
[data-theme-layout="lexicon"] .lx-lead-hw { display: flex; align-items: baseline; flex-wrap: wrap; gap: .3rem .7rem; }
[data-theme-layout="lexicon"] .lx-headword {
  font-family: var(--serif); font-weight: 800;
  font-size: clamp(1.9rem, 4.5vw, 3rem); line-height: 1.08; letter-spacing: -.01em;
  color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="lexicon"] .lx-lead-in:hover .lx-headword { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 6px; }
[data-theme-layout="lexicon"] .lx-pos { font-family: var(--serif); font-style: italic; font-size: .95rem; color: var(--accent-soft); overflow-wrap: anywhere; }
[data-theme-layout="lexicon"] .lx-lead-fig {
  display: block; margin-top: 1rem; overflow: hidden;
  border: 1px solid var(--line); border-radius: calc(var(--radius) * .6);
}
[data-theme-layout="lexicon"] .lx-lead-fig img { display: block; width: 100%; height: auto; max-height: 400px; object-fit: cover; }
[data-theme-layout="lexicon"] .lx-def { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: .6rem; margin-top: 1rem; }
[data-theme-layout="lexicon"] .lx-def-no { font-family: var(--mono); font-weight: 700; font-size: .85rem; line-height: 2; color: var(--muted); }
[data-theme-layout="lexicon"] .lx-def-t { font-family: var(--serif); font-size: 1.03rem; line-height: 1.7; color: var(--ink-soft); overflow-wrap: anywhere; }
[data-theme-layout="lexicon"] .lx-lead-foot {
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: .5rem 1rem;
  margin-top: 1.1rem; padding-top: .65rem; border-top: 1px solid var(--line-soft);
  font-family: var(--mono); font-size: .72rem; color: var(--muted);
}
[data-theme-layout="lexicon"] .lx-lead-more {
  display: inline-flex; align-items: center; gap: .35rem;
  font-family: var(--sans); font-size: .74rem; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase; color: var(--accent);
}

/* ---- latest: dense entry rows (headword col / pos / definition / date) -- */
[data-theme-layout="lexicon"] .lx-entries { margin-top: clamp(1.6rem, 4vw, 2.4rem); }
[data-theme-layout="lexicon"] .lx-entries-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  border-bottom: 2px solid var(--ink); padding-bottom: .45rem; margin-bottom: .3rem;
}
[data-theme-layout="lexicon"] .lx-entries-t { margin: 0; font-family: var(--sans); font-size: .76rem; font-weight: 800; letter-spacing: .22em; text-transform: uppercase; color: var(--ink); }
[data-theme-layout="lexicon"] .lx-entries-all {
  flex: 0 0 auto; display: inline-flex; align-items: center; gap: .3rem;
  font-family: var(--sans); font-size: .72rem; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase; color: var(--accent); text-decoration: none;
}
[data-theme-layout="lexicon"] .lx-row {
  display: grid; grid-template-columns: 12rem auto minmax(0, 1fr) auto;
  align-items: baseline; gap: .25rem 1rem; padding: .58rem .35rem;
  border-bottom: 1px solid var(--line-soft);
  text-decoration: none; color: var(--ink); transition: background .15s;
}
[data-theme-layout="lexicon"] .lx-row:hover { background: var(--accent-wash); }
[data-theme-layout="lexicon"] .lx-row-hw { grid-column: 1; font-family: var(--serif); font-weight: 700; font-size: 1.02rem; line-height: 1.3; color: var(--accent); overflow-wrap: anywhere; }
[data-theme-layout="lexicon"] .lx-row:hover .lx-row-hw { text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="lexicon"] .lx-row-pos { grid-column: 2; font-family: var(--serif); font-style: italic; font-size: .8rem; color: var(--accent-soft); white-space: nowrap; }
[data-theme-layout="lexicon"] .lx-row-def { grid-column: 3; font-family: var(--serif); font-size: .9rem; color: var(--muted); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
[data-theme-layout="lexicon"] .lx-row-date { grid-column: 4; font-family: var(--mono); font-size: .68rem; font-variant-numeric: tabular-nums; color: var(--muted); white-space: nowrap; }

/* ---- cross references (FeatLinks as see-also chips) --------------------- */
[data-theme-layout="lexicon"] .lx-xref {
  margin-top: clamp(1.6rem, 4vw, 2.4rem); padding: 1rem 1.15rem 1.15rem;
  border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface);
}
[data-theme-layout="lexicon"] .lx-xref-h {
  margin: 0 0 .6rem; padding-bottom: .5rem; border-bottom: 1px solid var(--line);
  font-family: var(--sans); font-size: .72rem; font-weight: 800;
