  display: flex; align-items: flex-start; justify-content: space-between;
  gap: clamp(1rem, 3vw, 2rem);
  margin: 0 0 clamp(1.4rem, 3vw, 2.2rem); padding-bottom: clamp(1rem, 2.4vw, 1.5rem);
  border-bottom: 4px double var(--ink);
}
[data-theme-layout="serial"] .srl-head-main { min-width: 0; }
