  margin: 0; font-family: var(--serif); font-weight: 800;
  font-size: clamp(2rem, 6vw, 3.4rem); line-height: 1.14; letter-spacing: .04em;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="serial"] .srl-lede {
  margin: .7rem 0 0; font-size: .96rem; line-height: 1.7; color: var(--muted);
