/* ---- 续读条：竖签 + 回目大字 + 继续阅读按钮 ------------------------------ */
[data-theme-layout="serial"] .srl-resume {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center;
  margin: 0 0 clamp(1.4rem, 3vw, 2rem); overflow: hidden;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); box-shadow: var(--shadow);
}
[data-theme-layout="serial"] .srl-resume-tag {
  align-self: stretch; display: grid; place-items: center;
  writing-mode: vertical-rl; padding: 1rem .55rem;
  background: var(--accent); color: var(--bg);
  font-size: .8rem; font-weight: 700; letter-spacing: .3em;
}
[data-theme-layout="serial"] .srl-resume-main {
  display: flex; flex-direction: column; gap: .5rem; min-width: 0;
  padding: clamp(1rem, 2.5vw, 1.5rem); text-decoration: none; color: var(--ink);
}
[data-theme-layout="serial"] .srl-resume-h {
  font-family: var(--serif); font-weight: 800;
  font-size: clamp(1.35rem, 3.4vw, 2.1rem); line-height: 1.22;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="serial"] .srl-resume-main:hover .srl-resume-h { color: var(--accent); }
[data-theme-layout="serial"] .srl-resume-meta {
  font-size: .78rem; letter-spacing: .08em; color: var(--muted); font-variant-numeric: tabular-nums;
}
[data-theme-layout="serial"] .srl-resume-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .92rem; line-height: 1.66; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="serial"] .srl-resume-btn {
  display: inline-flex; align-items: center; gap: .4rem; white-space: nowrap;
  margin-right: clamp(1rem, 2.5vw, 1.5rem); padding: .6rem 1.1rem;
  background: var(--accent); color: var(--bg); border-radius: var(--radius);
  font-size: .82rem; font-weight: 700; letter-spacing: .1em; text-decoration: none;
  transition: background .15s;
}
[data-theme-layout="serial"] .srl-resume-btn:hover { background: var(--accent-soft); }

/* ---- 卷页签：分类胶囊排 --------------------------------------------------- */
[data-theme-layout="serial"] .srl-tabs {
  display: flex; flex-wrap: wrap; gap: .5rem .55rem;
  margin: 0 0 clamp(1.6rem, 3.5vw, 2.4rem);
}
[data-theme-layout="serial"] .srl-tab {
  display: inline-flex; align-items: baseline; gap: .4rem; min-width: 0;
  padding: .32rem .85rem; border: 1px solid var(--line); border-left: 3px solid var(--accent);
  border-radius: 999px; background: var(--surface);
  font-size: .84rem; letter-spacing: .06em; color: var(--ink-soft); text-decoration: none;
  transition: color .15s, border-color .15s, background .15s;
}
[data-theme-layout="serial"] .srl-tab:hover { color: var(--accent); border-color: var(--accent); background: var(--accent-wash); }
[data-theme-layout="serial"] .srl-tab-name { overflow-wrap: anywhere; }
[data-theme-layout="serial"] .srl-tab-count { font-size: .68rem; color: var(--muted); font-variant-numeric: tabular-nums; }
[data-theme-layout="serial"] .srl-tab-all { color: var(--accent); font-weight: 700; }

/* ---- 章回目录：其N 汉字序号（CSS counter, cjk-ideographic）--------------- */
[data-theme-layout="serial"] .srl-toc-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  border-bottom: 2px solid var(--ink); padding-bottom: .5rem; margin: 0 0 .3rem;
}
[data-theme-layout="serial"] .srl-toc-t {
  margin: 0; font-family: var(--serif); font-size: 1.02rem; font-weight: 800;
  letter-spacing: .22em; color: var(--ink);
}
[data-theme-layout="serial"] .srl-toc-all {
  flex: 0 0 auto; display: inline-flex; align-items: center; gap: .3rem;
  font-size: .78rem; font-weight: 700; letter-spacing: .1em;
  color: var(--accent); text-decoration: none; transition: color .15s;
}
[data-theme-layout="serial"] .srl-toc-all:hover { color: var(--accent-soft); }
[data-theme-layout="serial"] .srl-list { list-style: none; margin: 0; padding: 0; counter-reset: srl-ch; }
[data-theme-layout="serial"] .srl-item { counter-increment: srl-ch; }
[data-theme-layout="serial"] .srl-item-in {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline;
  gap: .35rem clamp(.8rem, 2.5vw, 1.6rem);
  padding: .95rem .2rem; border-bottom: 1px dashed var(--line);
  text-decoration: none; color: var(--ink); transition: background .15s;
}
[data-theme-layout="serial"] .srl-item-in:hover { background: var(--surface); }
[data-theme-layout="serial"] .srl-item-no {
  min-width: 3.4em; white-space: nowrap;
  font-family: var(--serif); font-weight: 700; font-size: .95rem;
  letter-spacing: .1em; color: var(--accent);
}
[data-theme-layout="serial"] .srl-item-no::before { content: "其" counter(srl-ch, cjk-ideographic); }
[data-theme-layout="serial"] .srl-item-main { display: flex; flex-direction: column; gap: .3rem; min-width: 0; }
[data-theme-layout="serial"] .srl-item-h {
  font-family: var(--serif); font-weight: 700; font-size: 1.1rem; line-height: 1.35;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="serial"] .srl-item-in:hover .srl-item-h {
  color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 4px;
}
[data-theme-layout="serial"] .srl-item-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .86rem; line-height: 1.6; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="serial"] .srl-item-date {
  font-family: var(--mono); font-size: .74rem; letter-spacing: .04em;
  color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap;
}

/* ---- 卷外别册：友链书脊排 ------------------------------------------------- */
[data-theme-layout="serial"] .srl-shelf {
  margin: clamp(1.6rem, 3.5vw, 2.4rem) 0 0;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); padding: 1rem 1.1rem 1.1rem;
}
[data-theme-layout="serial"] .srl-shelf-h {
  margin: 0 0 .6rem; font-size: .78rem; font-weight: 800; letter-spacing: .24em; color: var(--ink);
}
[data-theme-layout="serial"] .srl-shelf-row { display: flex; flex-wrap: wrap; gap: .55rem .7rem; }
[data-theme-layout="serial"] .srl-shelf-link {
  display: inline-flex; align-items: center; gap: .5rem; min-width: 0;
  padding: .32rem .8rem .32rem .42rem; border: 1px solid var(--line); border-radius: 999px;
  background: var(--bg); color: var(--ink-soft); font-size: .85rem; text-decoration: none;
  transition: color .15s, border-color .15s;
}
[data-theme-layout="serial"] .srl-shelf-link:hover { color: var(--accent); border-color: var(--accent); }
[data-theme-layout="serial"] .srl-shelf-ic {
  flex: 0 0 auto; width: 26px; height: 26px; border-radius: 50%; overflow: hidden;
  display: grid; place-items: center; background: var(--accent); color: var(--bg);
}
[data-theme-layout="serial"] .srl-shelf-ic b { font-family: var(--serif); font-weight: 800; font-size: .8rem; line-height: 1; }
[data-theme-layout="serial"] .srl-shelf-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="serial"] .srl-shelf-t { overflow-wrap: anywhere; }

/* ---- 卷尾：双细线 + 右下待续印章（纯 CSS 旋转方框，字为装饰性生成内容）--- */
[data-theme-layout="serial"] .srl-fin {
  display: flex; justify-content: space-between; align-items: center; gap: 1rem;
  margin-top: clamp(1.8rem, 4vw, 2.8rem); padding-top: 1.1rem;
  border-top: 4px double var(--ink);
}
[data-theme-layout="serial"] .srl-fin-more {
  font-family: var(--serif); font-size: .9rem; letter-spacing: .2em;
  color: var(--ink-soft); text-decoration: none; transition: color .15s;
}
[data-theme-layout="serial"] .srl-fin-more:hover { color: var(--accent); }
[data-theme-layout="serial"] .srl-seal {
  flex: 0 0 auto; width: 58px; height: 58px; display: grid; place-items: center;
  border: 2px solid currentColor; border-radius: 4px; color: var(--accent);
  outline: 1px solid currentColor; outline-offset: -6px;
  transform: rotate(-8deg);
}
[data-theme-layout="serial"] .srl-seal::after {
  content: "待续"; writing-mode: vertical-rl;
  font-family: var(--serif); font-weight: 800; font-size: 1.05rem;
  letter-spacing: .22em; line-height: 1; margin-bottom: -.22em;
}

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="serial"] .srl-resume { grid-template-columns: auto minmax(0, 1fr); }
  [data-theme-layout="serial"] .srl-resume-tag { grid-row: 1 / span 2; }
  [data-theme-layout="serial"] .srl-resume-main { padding-bottom: .5rem; }
  [data-theme-layout="serial"] .srl-resume-btn {
    grid-column: 2; justify-self: start;
    margin: 0 clamp(1rem, 2.5vw, 1.5rem) 1.1rem;
  }
}
@media (max-width: 720px) {
  [data-theme-layout="serial"] .srl-wrap { padding-left: 16px; }
  [data-theme-layout="serial"] .srl-head { flex-direction: column; }
  [data-theme-layout="serial"] .srl-ear {
    writing-mode: horizontal-tb; max-height: none; max-width: 100%;
    padding: .3rem .8rem; letter-spacing: .24em;
  }
  [data-theme-layout="serial"] .srl-resume { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="serial"] .srl-resume-tag {
    writing-mode: horizontal-tb; grid-row: auto; justify-content: start;
    padding: .45rem 1rem; justify-items: start;
  }
  [data-theme-layout="serial"] .srl-resume-btn { grid-column: 1; margin: 0 1.1rem 1.1rem; }
  [data-theme-layout="serial"] .srl-item-in { grid-template-columns: auto minmax(0, 1fr); }
  [data-theme-layout="serial"] .srl-item-no { min-width: 0; }
  [data-theme-layout="serial"] .srl-item-date { grid-column: 2; }
  [data-theme-layout="serial"] .srl-fin { flex-wrap: wrap; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="serial"] .srl-resume-h,
  [data-theme-layout="serial"] .srl-resume-btn,
  [data-theme-layout="serial"] .srl-tab,
  [data-theme-layout="serial"] .srl-toc-all,
  [data-theme-layout="serial"] .srl-item-in,
  [data-theme-layout="serial"] .srl-item-h,
  [data-theme-layout="serial"] .srl-shelf-link,
  [data-theme-layout="serial"] .srl-fin-more { transition: none; }
}

/* ============================================================
   书局 · Serial —— Serial 骨架默认皮：仿古米纸、靛蓝书墨、朱印红章
   ============================================================ */
:root[data-theme="serial"] {
  --bg: #f5efdd; --surface: #faf6ea;
  --ink: #26221a; --ink-soft: #443d2f; --muted: #6b6250; --faint: #857b63;
  --line: #d9d0b6; --line-soft: #e7dfc8;
  --accent: #2a3b66; --accent-soft: #40548a; --accent-wash: #ece4cd;
  --w-wide: 1080px; --radius: 3px;
  --shadow: 0 1px 2px rgba(38, 34, 26, .06), 0 8px 22px rgba(38, 34, 26, .08);
}
:root[data-theme="serial"] .site-header { background: var(--bg); }
:root[data-theme="serial"] .btn-primary { color: #fff; }
/* 朱印红章：印章独用朱砂，不入正文（4.5:1 以上，且为装饰元素） */
:root[data-theme="serial"] .srl-seal { color: #a8321f; }

/* ============================================================
   夜读灯 · Nightlamp —— Serial 骨架 + 暖黑烛黄夜读皮（灯下细字、暖晕）
   ============================================================ */
:root[data-theme="nightlamp"] {
  --bg: #171310; --surface: #201b16;
  --ink: #f2e8d5; --ink-soft: #ddd2bc; --muted: #b3a689; --faint: #8a7f68;
  --line: #3a3226; --line-soft: #2a241b;
  --accent: #e2b25c; --accent-soft: #f0c97e; --accent-wash: #2e2515;
  --w-wide: 1080px; --radius: 3px; --code-bg: #0d0a08;
  --shadow: 0 1px 2px rgba(0, 0, 0, .55), 0 12px 32px rgba(0, 0, 0, .5);
}
:root[data-theme="nightlamp"] .site-header { background: rgba(23, 19, 16, .92); }
:root[data-theme="nightlamp"] .btn-primary { color: #171310; }
/* 灯下细字：标题降字重、拉字距；续读条带一圈烛光暖晕 */
:root[data-theme="nightlamp"] .srl-title { font-weight: 600; letter-spacing: .1em; }
:root[data-theme="nightlamp"] .srl-resume-h,
:root[data-theme="nightlamp"] .srl-item-h { font-weight: 600; }
:root[data-theme="nightlamp"] .srl-ear { border-style: dashed; }
:root[data-theme="nightlamp"] .srl-resume {
  box-shadow: 0 0 0 1px var(--line), 0 0 44px rgba(226, 178, 92, .1), 0 14px 34px rgba(0, 0, 0, .5);
}
/* 印章改烛黄铜印，微光 */
:root[data-theme="nightlamp"] .srl-seal { color: var(--accent-soft); box-shadow: 0 0 24px rgba(240, 201, 126, .22); }

/* =========================================================================
   LAYOUT: verse — 诗笺 vertical-verse sheet (pure CSS, no JS)
   every selector scoped under [data-theme-layout="verse"], classes vs-*
   左=导航留白区(慢文案沉底) / 右=朱丝栏界格竖排卷 / 笺条卡两列 / 朱印落款
   非中文降级：html[lang] 不以 zh 开头时竖排块回落横排
   ========================================================================= */
[data-theme-layout="verse"] main { display: block; }
[data-theme-layout="verse"] .vs-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding: clamp(1.6rem, 4vw, 3rem) 0 clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: header/footer reshaped by CSS only ------------------ */
[data-theme-layout="verse"] .site-header { background: var(--bg); border-bottom: 1px solid var(--line); }
[data-theme-layout="verse"] .site-header .brand { font-family: var(--serif); letter-spacing: .3em; }
[data-theme-layout="verse"] .site-header .nav a { font-family: var(--serif); letter-spacing: .14em; }
[data-theme-layout="verse"] .site-footer { background: var(--bg); border-top: 1px solid var(--line); }
[data-theme-layout="verse"] .site-footer .f-col h4 { font-family: var(--serif); letter-spacing: .26em; }

/* ---- hero: left margin area + right ruled vertical scroll --------------- */
[data-theme-layout="verse"] .vs-hero {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, clamp(240px, 30vw, 340px));
  gap: clamp(1.8rem, 5vw, 4rem); align-items: stretch;
  padding-bottom: clamp(1.6rem, 4vw, 2.6rem); border-bottom: 1px solid var(--ink);
}
[data-theme-layout="verse"] .vs-margin { display: flex; flex-direction: column; gap: clamp(1.4rem, 3vw, 2.2rem); min-width: 0; }

/* category nav lives in the margin whitespace */
[data-theme-layout="verse"] .vs-nav { display: flex; flex-direction: column; max-width: 420px; }
[data-theme-layout="verse"] .vs-nav-item {
  display: flex; align-items: baseline; gap: .55rem; min-width: 0;
  padding: .5rem 0; border-bottom: 1px solid var(--line-soft);
  font-family: var(--serif); font-size: 1.02rem; letter-spacing: .06em;
  color: var(--ink-soft); text-decoration: none;
  transition: color .15s;
}
[data-theme-layout="verse"] .vs-nav-item:hover { color: var(--accent); }
[data-theme-layout="verse"] .vs-nav-name { overflow-wrap: anywhere; }
[data-theme-layout="verse"] .vs-nav-n { margin-left: auto; font-family: var(--sans); font-size: .72rem; color: var(--muted); }
[data-theme-layout="verse"] .vs-nav-all { border-bottom: 0; color: var(--accent); font-size: .92rem; }

/* featured links: small sealed slips */
[data-theme-layout="verse"] .vs-links { max-width: 420px; min-width: 0; }
[data-theme-layout="verse"] .vs-links-h {
  margin: 0 0 .3rem; font-family: var(--sans); font-size: .72rem; font-weight: 700;
  letter-spacing: .22em; color: var(--muted);
}
[data-theme-layout="verse"] .vs-link {
  display: flex; align-items: center; gap: .6rem; min-width: 0;
  padding: .45rem 0; text-decoration: none; color: var(--ink);
}
[data-theme-layout="verse"] .vs-link + .vs-link { border-top: 1px dotted var(--line); }
[data-theme-layout="verse"] .vs-link-ic {
  flex: 0 0 auto; width: 34px; height: 34px; overflow: hidden;
  display: grid; place-items: center;
  background: var(--accent-wash); color: var(--accent); border: 1px solid var(--line);
}
[data-theme-layout="verse"] .vs-link-ic b { font-family: var(--serif); font-weight: 700; font-size: 1rem; line-height: 1; }
[data-theme-layout="verse"] .vs-link-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="verse"] .vs-link-t { font-size: .95rem; overflow-wrap: anywhere; transition: color .15s; }
[data-theme-layout="verse"] .vs-link:hover .vs-link-t { color: var(--accent); }

/* slow copy sinks to the bottom of the margin column */
[data-theme-layout="verse"] .vs-slow {
  margin: auto 0 0; max-width: 46ch;
  font-family: var(--serif); font-size: 1.02rem; line-height: 2;
  letter-spacing: .06em; color: var(--ink-soft); overflow-wrap: anywhere;
}

/* right column: cinnabar ruled sheet + true vertical writing */
[data-theme-layout="verse"] .vs-scroll {
  display: flex; flex-direction: row-reverse; justify-content: flex-start; align-items: stretch;
  gap: clamp(.9rem, 2vw, 1.5rem);
  min-height: clamp(380px, 55vh, 560px); min-width: 0; overflow: hidden;
  padding: clamp(1.2rem, 2.5vw, 1.8rem);
  border: 1px solid color-mix(in srgb, var(--accent) 55%, var(--line));
  outline: 1px solid color-mix(in srgb, var(--accent) 28%, transparent); outline-offset: 3px;
  background:
    repeating-linear-gradient(to left,
      transparent 0 calc(2.4em - 1px),
      color-mix(in srgb, var(--accent) 30%, transparent) calc(2.4em - 1px) 2.4em)
    var(--surface);
}
[data-theme-layout="verse"] .vs-title {
  margin: 0; min-width: 0;
  writing-mode: vertical-rl; letter-spacing: .5em;
  font-family: var(--serif); font-weight: 700; font-size: clamp(1.9rem, 4.2vw, 3rem);
  line-height: 1.9; color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="verse"] .vs-eyebrow {
  writing-mode: vertical-rl; letter-spacing: .5em;
  font-family: var(--serif); font-size: .85rem; color: var(--accent);
}
/* 非中文降级：竖排块回落横排，界格转横栏 */
[data-theme-layout="verse"]:not([lang^="zh"]) .vs-scroll {
  flex-direction: column; justify-content: center; align-items: flex-start;
  background:
    repeating-linear-gradient(to bottom,
      transparent 0 calc(2.4em - 1px),
      color-mix(in srgb, var(--accent) 30%, transparent) calc(2.4em - 1px) 2.4em)
    var(--surface);
}
[data-theme-layout="verse"]:not([lang^="zh"]) .vs-title { writing-mode: horizontal-tb; letter-spacing: .02em; line-height: 1.2; }
[data-theme-layout="verse"]:not([lang^="zh"]) .vs-eyebrow { writing-mode: horizontal-tb; letter-spacing: .22em; order: -1; }

/* ---- list: slip cards in two ruled columns ------------------------------ */
[data-theme-layout="verse"] .vs-list { padding-top: clamp(1.2rem, 3vw, 1.8rem); }
[data-theme-layout="verse"] .vs-list-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  border-bottom: 2px solid var(--ink); padding-bottom: .45rem;
  margin: 0 0 clamp(1rem, 2.5vw, 1.5rem);
}
[data-theme-layout="verse"] .vs-list-t { margin: 0; font-family: var(--serif); font-size: 1rem; font-weight: 700; letter-spacing: .3em; color: var(--ink); }
[data-theme-layout="verse"] .vs-list-all {
  display: inline-flex; align-items: center; gap: .3rem; flex: 0 0 auto;
  font-family: var(--sans); font-size: .76rem; font-weight: 700; letter-spacing: .12em;
  color: var(--accent); text-decoration: none;
}
[data-theme-layout="verse"] .vs-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: clamp(1rem, 2.5vw, 1.6rem); }
[data-theme-layout="verse"] .vs-card { min-width: 0; }
[data-theme-layout="verse"] .vs-card-lead { grid-column: 1 / -1; }
[data-theme-layout="verse"] .vs-card-in {
  display: flex; min-width: 0; height: 100%;
  background: var(--surface); border: 1px solid var(--line); box-shadow: var(--shadow);
  text-decoration: none; color: var(--ink);
  transition: border-color .15s;
}
[data-theme-layout="verse"] .vs-card-in:hover { border-color: var(--accent); }
/* 40px left edge strip: vertical date + hairline divider */
[data-theme-layout="verse"] .vs-edge {
  flex: 0 0 40px; display: flex; justify-content: center;
  padding: .9rem 0; border-right: 1px solid var(--line);
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
}
[data-theme-layout="verse"] .vs-edge-date {
  writing-mode: vertical-rl; letter-spacing: .18em;
  font-family: var(--sans); font-size: .72rem; font-variant-numeric: tabular-nums;
  color: var(--muted);
}
[data-theme-layout="verse"] .vs-card-body { display: flex; flex-direction: column; gap: .5rem; min-width: 0; flex: 1 1 auto; padding: 1rem 1.1rem 1.05rem; }
[data-theme-layout="verse"] .vs-kicker {
  align-self: flex-start; font-family: var(--sans); font-size: .7rem; font-weight: 700;
  letter-spacing: .2em; color: var(--accent);
  border-bottom: 2px solid var(--accent); padding-bottom: .25rem;
}
[data-theme-layout="verse"] .vs-card-cover { display: block; border: 1px solid var(--line); }
[data-theme-layout="verse"] .vs-card-cover img { display: block; width: 100%; height: auto; max-height: 380px; object-fit: cover; }
[data-theme-layout="verse"] .vs-card-t {
  font-family: var(--serif); font-weight: 700; font-size: 1.14rem; line-height: 1.45;
  letter-spacing: .02em; overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="verse"] .vs-card-lead .vs-card-t { font-size: clamp(1.5rem, 3vw, 2.1rem); line-height: 1.3; }
[data-theme-layout="verse"] .vs-card-in:hover .vs-card-t { color: var(--accent); }
[data-theme-layout="verse"] .vs-card-ex {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .92rem; line-height: 1.7; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="verse"] .vs-card-lead .vs-card-body { gap: .7rem; padding: clamp(1.2rem, 3vw, 1.7rem) clamp(1.2rem, 3vw, 2rem); }
[data-theme-layout="verse"] .vs-card-cat { margin-top: auto; font-family: var(--sans); font-size: .74rem; letter-spacing: .14em; color: var(--faint); overflow-wrap: anywhere; }

/* ---- colophon: square cinnabar seal + plain links ----------------------- */
[data-theme-layout="verse"] .vs-colophon {
  display: flex; justify-content: center; align-items: center; gap: .9rem;
  margin-top: clamp(1.8rem, 4vw, 2.8rem); padding-top: clamp(1.2rem, 3vw, 1.8rem);
  border-top: 1px solid var(--ink);
  font-family: var(--serif); letter-spacing: .16em; font-size: .92rem; color: var(--faint);
}
[data-theme-layout="verse"] .vs-seal {
  width: 44px; height: 44px; display: grid; place-items: center;
  background: var(--accent); color: #fff; border-radius: 6px; box-shadow: var(--shadow);
  font-family: var(--serif); font-weight: 700; font-size: 1.35rem; line-height: 1;
}
[data-theme-layout="verse"] .vs-colophon a { color: var(--ink-soft); text-decoration: none; transition: color .15s; }
[data-theme-layout="verse"] .vs-colophon a:hover { color: var(--accent); }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="verse"] .vs-hero { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="verse"] .vs-scroll { order: -1; min-height: clamp(300px, 45vh, 420px); }
  [data-theme-layout="verse"] .vs-slow { margin-top: 0; }
}
@media (max-width: 720px) {
  [data-theme-layout="verse"] .vs-grid { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="verse"] .vs-card-lead { grid-column: auto; }
  [data-theme-layout="verse"] .vs-title { font-size: clamp(1.6rem, 7.5vw, 2.2rem); }
  [data-theme-layout="verse"] .vs-list-head { flex-wrap: wrap; }
  [data-theme-layout="verse"] .vs-card-lead .vs-card-body { padding: 1rem 1.1rem 1.05rem; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="verse"] .vs-nav-item,
  [data-theme-layout="verse"] .vs-link-t,
  [data-theme-layout="verse"] .vs-card-in,
  [data-theme-layout="verse"] .vs-card-t,
  [data-theme-layout="verse"] .vs-colophon a { transition: none; }
}

/* ============================================================
   诗笺 · Verse —— Verse 骨架默认皮：宣纸暖白、松烟墨、朱砂界格
   ============================================================ */
:root[data-theme="verse"] {
  --bg: #f7f2e7; --surface: #fdfaf1;
  --ink: #241f17; --ink-soft: #453c2d; --muted: #6b6250; --faint: #776e57;
  --line: #ded3ba; --line-soft: #ebe3d0;
  --accent: #b23a2a; --accent-soft: #96291b; --accent-wash: #f2e0d2;
  --serif: "Hiragino Mincho ProN", "Songti SC", "Noto Serif CJK SC", Georgia, serif;
  --w-wide: 1200px; --radius: 0px;
  --shadow: 0 1px 2px rgba(36,31,23,.05), 0 8px 22px rgba(36,31,23,.07);
}
:root[data-theme="verse"] .site-header { background: var(--bg); }

/* ============================================================
   靛夜 · Indigonight —— Verse 骨架 + 靛青夜色皮：月白字、陶红印、界格转月色
   ============================================================ */
:root[data-theme="indigonight"] {
  --bg: #101c30; --surface: #182742;
  --ink: #e9eef7; --ink-soft: #c6d2e4; --muted: #93a4c0; --faint: #8093ae;
  --line: #2c3d5c; --line-soft: #20304a;
  --accent: #e08159; --accent-soft: #eb9a76; --accent-wash: #31221d;
  --w-wide: 1200px; --radius: 0px; --code-bg: #0a1220;
  --shadow: 0 1px 2px rgba(0,0,0,.5), 0 10px 30px rgba(0,0,0,.55);
}
:root[data-theme="indigonight"] .btn-primary { color: #101c30; }
:root[data-theme="indigonight"] .site-header { background: rgba(16,28,48,.92); }
:root[data-theme="indigonight"] .site-header .brand,
:root[data-theme="indigonight"] .site-header .nav a { letter-spacing: .22em; }
/* 夜色下笔画放轻：竖排大字减重加距（仅中文竖排时加距），印文改靛底色 */
:root[data-theme="indigonight"] .vs-title { font-weight: 500; }
:root[data-theme="indigonight"][lang^="zh"] .vs-title { letter-spacing: .62em; }
:root[data-theme="indigonight"] .vs-eyebrow { color: var(--accent-soft); }
:root[data-theme="indigonight"] .vs-kicker { background: var(--accent); color: #101c30; border-bottom: 0; padding: .3rem .55rem; }
:root[data-theme="indigonight"] .vs-seal { color: #101c30; }
:root[data-theme="indigonight"] .vs-card-t { font-weight: 600; }
:root[data-theme="indigonight"] .vs-edge { background: color-mix(in srgb, var(--accent) 7%, var(--surface)); }
:root[data-theme="indigonight"] .vs-link-ic { color: var(--accent-soft); }

/* ============================================================
   内容骨架第三批 · 纯白系 —— 六骨架各一张纯白背景色卡：
   中性灰基底共享（对齐 answer-desk-white），accent 保留各族色相并压深到
   白底可读（实算：tracklist 5.07 / departure 7.95 / lexicon 11.32 /
   bistro 9.65 / serial 10.96 / verse 5.95，hover 走更深的 soft 只升不降）。
   ============================================================ */
:root[data-theme="tracklist-white"] {
  --bg:#ffffff; --surface:#fafaf8; --ink:#101218; --ink-soft:#3f444d;
  --muted:#707680; --faint:#a9aeb6; --line:#d7d9dd; --line-soft:#eef0f3;
  --accent:#8a6a08; --accent-soft:#6f5506; --accent-wash:#f8f2df;
  --w-wide:1200px; --radius:10px;
}
:root[data-theme="tracklist-white"] .btn-primary { color:#fff; }
:root[data-theme="departure-white"] {
  --bg:#ffffff; --surface:#fafaf8; --ink:#101218; --ink-soft:#3f444d;
  --muted:#707680; --faint:#a9aeb6; --line:#d7d9dd; --line-soft:#eef0f3;
  --accent:#1f5b46; --accent-soft:#17453a; --accent-wash:#e9f2ee;
  --w-wide:1200px; --radius:6px;
}
:root[data-theme="departure-white"] .btn-primary { color:#fff; }
:root[data-theme="departure-white"] .dp-lead-kicker { color:#fff; }
:root[data-theme="departure-white"] .dp-sign:not(.dp-sign-all) { color:#fff; }
:root[data-theme="lexicon-white"] {
  --bg:#ffffff; --surface:#fafaf8; --ink:#101218; --ink-soft:#3f444d;
  --muted:#707680; --faint:#a9aeb6; --line:#d7d9dd; --line-soft:#eef0f3;
  --accent:#1f3a66; --accent-soft:#96301c; --accent-wash:#edf1fa;
  --w-wide:1200px; --radius:6px;
}
:root[data-theme="lexicon-white"] .btn-primary { color:#fff; }
:root[data-theme="bistro-white"] {
  --bg:#ffffff; --surface:#fafaf8; --ink:#101218; --ink-soft:#3f444d;
  --muted:#707680; --faint:#a9aeb6; --line:#d7d9dd; --line-soft:#eef0f3;
  --accent:#1d4d3b; --accent-soft:#8a5a00; --accent-wash:#e9f2ed;
  --w-wide:1200px; --radius:0px;
}
:root[data-theme="bistro-white"] .btn-primary { color:#fff; }
:root[data-theme="bistro-white"] .bt-special-tag { background:var(--accent); color:#fff; }
:root[data-theme="serial-white"] {
  --bg:#ffffff; --surface:#fafaf8; --ink:#101218; --ink-soft:#3f444d;
  --muted:#707680; --faint:#a9aeb6; --line:#d7d9dd; --line-soft:#eef0f3;
  --accent:#2a3b66; --accent-soft:#a8321f; --accent-wash:#edeff8;
  --w-wide:1200px; --radius:3px;
}
:root[data-theme="serial-white"] .btn-primary { color:#fff; }
:root[data-theme="verse-white"] {
  --bg:#ffffff; --surface:#fafaf8; --ink:#101218; --ink-soft:#3f444d;
  --muted:#707680; --faint:#a9aeb6; --line:#d7d9dd; --line-soft:#eef0f3;
  --accent:#b23a2a; --accent-soft:#8f2e21; --accent-wash:#faece8;
  --w-wide:1200px; --radius:0px;
}
:root[data-theme="verse-white"] .btn-primary { color:#fff; }

/* =========================================================================
   LAYOUT: archway — 门坊 centered archway gate home (pure CSS, no JS)
   every selector scoped under [data-theme-layout="archway"], classes aw-*
   标准页头 CSS 重塑为居中门坊：.brand 居中在上、.nav 居中其下被细线夹住、
   项间 ::before 菱形分隔（末项后不加）；home：拱门线框精选（200px 上圆角）
   / 菱形花标居中条目行（右侧等宽日期）/ FeatLinks 居中双列小卡
   ========================================================================= */
[data-theme-layout="archway"] main { display: block; }
[data-theme-layout="archway"] .aw-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-block: clamp(1.6rem, 4vw, 2.8rem) clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: the standard header recast as a centered gateway ----
   细线三明治：.nav 自己的 border-top 是上线，.site-header 原生 border-bottom
   是下线；≤620px 交还基础汉堡菜单（列布局不变，抽屉照常） */
[data-theme-layout="archway"] .site-header { background: var(--bg); }
[data-theme-layout="archway"] .site-header .wrap {
  flex-direction: column; justify-content: center; height: auto;
  gap: .55rem; padding-top: 1rem; padding-bottom: .7rem;
}
[data-theme-layout="archway"] .site-header .brand {
  justify-content: center; text-align: center;
  font-size: 1.5rem; letter-spacing: .12em;
}
[data-theme-layout="archway"] .menu-toggle { margin: 0; }
[data-theme-layout="archway"] .site-footer { border-top: 1px solid var(--line); background: var(--bg); }
@media (min-width: 621px) {
  [data-theme-layout="archway"] .site-header .wrap { padding-bottom: 0; }
  [data-theme-layout="archway"] .nav {
    align-self: stretch; justify-content: center; flex-wrap: wrap;
    gap: .15rem 0; border-top: 1px solid var(--line); padding: .5rem 0 .6rem;
  }
  [data-theme-layout="archway"] .nav > a {
    padding: .1rem 1.05rem; min-width: 0; overflow-wrap: anywhere;
    font-family: var(--serif); font-variant: small-caps; letter-spacing: .12em; font-size: .97rem;
  }
  /* 菱形分隔只画在相邻两项之间（a+a），最后一项后自然不加 */
  [data-theme-layout="archway"] .nav > a + a::before {
    content: ""; position: absolute; left: -3.5px; top: 50%;
    width: 5px; height: 5px; margin-top: -3.5px;
    border: 1px solid var(--faint); transform: rotate(45deg);
  }
  [data-theme-layout="archway"] .nav a[aria-current="page"]::after { display: none; }
}

/* ---- hero: centered eyebrow / serif title / italic lede / category row -- */
[data-theme-layout="archway"] .aw-hero { text-align: center; margin: 0 0 clamp(1.8rem, 4vw, 2.6rem); }
[data-theme-layout="archway"] .aw-eyebrow {
  margin: 0 0 .5rem; font-size: .76rem; text-transform: uppercase;
  letter-spacing: .32em; text-indent: .32em; color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="archway"] .aw-title {
  font-family: var(--serif); font-weight: 700;
  font-size: clamp(2rem, 5.5vw, 3.3rem); line-height: 1.08; letter-spacing: -.01em;
  margin: 0 0 .6rem; color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="archway"] .aw-lede {
  font-family: var(--serif); font-style: italic;
  font-size: 1rem; line-height: 1.6; color: var(--muted);
  max-width: 58ch; margin: 0 auto; overflow-wrap: anywhere;
}
[data-theme-layout="archway"] .aw-cats {
  display: flex; flex-wrap: wrap; justify-content: center; gap: .3rem 1.1rem;
  margin-top: clamp(.9rem, 2.5vw, 1.3rem); padding-top: .75rem; border-top: 1px solid var(--line-soft);
}
[data-theme-layout="archway"] .aw-cat {
  display: inline-flex; align-items: baseline; gap: .35rem; min-width: 0;
  font-family: var(--serif); font-variant: small-caps; letter-spacing: .12em;
  font-size: .95rem; color: var(--ink-soft); text-decoration: none; transition: color .15s;
}
[data-theme-layout="archway"] .aw-cat:hover { color: var(--accent); }
[data-theme-layout="archway"] .aw-cat-name { overflow-wrap: anywhere; }
[data-theme-layout="archway"] .aw-cat-n { font-variant: normal; font-size: .68rem; color: var(--muted); }
[data-theme-layout="archway"] .aw-cat-all { color: var(--accent); }
[data-theme-layout="archway"] .aw-cat-all:hover { text-decoration: underline; text-underline-offset: 3px; }

/* ---- shared fleuron: small outlined diamond ----------------------------- */
[data-theme-layout="archway"] .aw-gem {
  flex: 0 0 auto; align-self: center; width: 6px; height: 6px;
  border: 1px solid var(--accent); transform: rotate(45deg);
}

/* ---- featured inside the archway frame: 200px top-rounded thin border --- */
[data-theme-layout="archway"] .aw-front { display: flex; justify-content: center; }
[data-theme-layout="archway"] .aw-arch {
  display: flex; flex-direction: column; align-items: center; gap: .8rem;
  width: min(100%, 640px); min-width: 0; text-align: center;
  border: 1px solid var(--ink); border-radius: 200px 200px 0 0;
  background: var(--surface); box-shadow: var(--shadow);
  padding: clamp(2.4rem, 7vw, 3.6rem) clamp(1.4rem, 5vw, 3rem) clamp(1.5rem, 4vw, 2.1rem);
  text-decoration: none; color: var(--ink);
}
[data-theme-layout="archway"] .aw-arch-cover {
  display: block; width: min(100%, 340px); overflow: hidden;
  border: 1px solid var(--line); border-radius: 999px 999px 0 0;
}
[data-theme-layout="archway"] .aw-arch-cover img { display: block; width: 100%; height: auto; aspect-ratio: 1 / 1; object-fit: cover; }
[data-theme-layout="archway"] .aw-arch-mark {
  display: grid; place-items: center; width: 64px; height: 72px;
  border: 1px solid var(--accent); border-radius: 999px 999px 0 0; color: var(--accent);
}
[data-theme-layout="archway"] .aw-arch-mark b { font-family: var(--serif); font-weight: 700; font-size: 1.5rem; line-height: 1; }
[data-theme-layout="archway"] .aw-kicker {
  display: inline-flex; align-items: baseline; gap: .55rem; min-width: 0;
  font-size: .72rem; font-weight: 800; letter-spacing: .22em; text-transform: uppercase; color: var(--accent);
}
[data-theme-layout="archway"] .aw-kicker-cat { color: var(--muted); overflow-wrap: anywhere; }
[data-theme-layout="archway"] .aw-arch-t {
  font-family: var(--serif); font-weight: 700;
  font-size: clamp(1.5rem, 3.6vw, 2.25rem); line-height: 1.15;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="archway"] .aw-arch:hover .aw-arch-t { color: var(--accent); }
[data-theme-layout="archway"] .aw-arch-ex {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  font-family: var(--serif); font-size: .98rem; line-height: 1.62;
  color: var(--ink-soft); max-width: 52ch; overflow-wrap: anywhere;
}
[data-theme-layout="archway"] .aw-arch-btn {
  display: inline-flex; align-items: center; gap: .4rem; margin-top: .3rem;
  padding: .55rem 1.5rem; border: 1px solid var(--accent); border-radius: 999px;
  font-size: .74rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase;
  color: var(--accent); transition: background .15s, color .15s;
}
[data-theme-layout="archway"] .aw-arch:hover .aw-arch-btn { background: var(--accent); color: #fff; }
[data-theme-layout="archway"] .aw-arch-date {
  font-family: var(--mono); font-size: .74rem; letter-spacing: .04em;
  font-variant-numeric: tabular-nums; color: var(--muted);
}

/* ---- section head: rule-flanked centered strip (roll & gates share) ----- */
[data-theme-layout="archway"] .aw-roll,
[data-theme-layout="archway"] .aw-gates { margin-top: clamp(2rem, 5vw, 3rem); }
[data-theme-layout="archway"] .aw-head {
  display: flex; align-items: baseline; justify-content: center; flex-wrap: wrap;
  gap: .3rem 1rem; margin: 0 0 clamp(1rem, 2.5vw, 1.4rem); text-align: center;
}
[data-theme-layout="archway"] .aw-head::before,
[data-theme-layout="archway"] .aw-head::after {
  content: ""; flex: 1 1 28px; align-self: center; height: 1px; background: var(--line);
}
[data-theme-layout="archway"] .aw-head-t {
  margin: 0; font-size: .8rem; font-weight: 800;
  letter-spacing: .26em; text-transform: uppercase; color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="archway"] .aw-head-all {
  min-width: 0; font-size: .74rem; font-weight: 700; letter-spacing: .1em;
  text-transform: uppercase; color: var(--accent); text-decoration: none;
}
[data-theme-layout="archway"] .aw-head-all:hover { text-decoration: underline; text-underline-offset: 3px; }

/* ---- roll: centered single-column entry rows ---------------------------- */
[data-theme-layout="archway"] .aw-rows {
  list-style: none; margin: 0 auto; padding: 0;
  max-width: 680px; border-top: 1px solid var(--line-soft);
}
[data-theme-layout="archway"] .aw-row-in {
  display: flex; align-items: baseline; gap: .7rem; min-width: 0;
  padding: .7rem .15rem; border-bottom: 1px solid var(--line-soft);
  text-decoration: none; color: var(--ink);
}
[data-theme-layout="archway"] .aw-row-body {
  display: flex; align-items: baseline; flex-wrap: wrap; gap: .2rem .6rem;
  flex: 1 1 auto; min-width: 0;
}
[data-theme-layout="archway"] .aw-row-t {
  font-family: var(--serif); font-weight: 700; font-size: 1.05rem; line-height: 1.35;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="archway"] .aw-row-in:hover .aw-row-t { color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
[data-theme-layout="archway"] .aw-row-cat {
  font-size: .72rem; letter-spacing: .12em; text-transform: uppercase;
  color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="archway"] .aw-row-date {
  flex: 0 0 auto; margin-left: auto; font-family: var(--mono);
  font-size: .78rem; letter-spacing: .03em; font-variant-numeric: tabular-nums; color: var(--muted);
}

/* ---- gates: centered two-column small cards (arch-topped initials) ------ */
[data-theme-layout="archway"] .aw-gate-grid {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(.8rem, 2vw, 1.2rem); max-width: 860px; margin-inline: auto;
}
[data-theme-layout="archway"] .aw-gate {
  display: flex; align-items: center; gap: .75rem; min-width: 0;
  padding: .7rem .9rem; background: var(--surface);
  border: 1px solid var(--line); border-radius: var(--radius);
  text-decoration: none; color: var(--ink); transition: border-color .15s;
}
[data-theme-layout="archway"] .aw-gate:hover { border-color: var(--accent); }
[data-theme-layout="archway"] .aw-gate-ic {
  flex: 0 0 auto; width: 44px; height: 52px; overflow: hidden;
  display: grid; place-items: center; border: 1px solid var(--line);
  border-radius: 999px 999px 0 0; background: var(--accent-wash); color: var(--accent);
}
[data-theme-layout="archway"] .aw-gate-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="archway"] .aw-gate-ic b { font-family: var(--serif); font-weight: 700; font-size: 1.15rem; line-height: 1; }
[data-theme-layout="archway"] .aw-gate-body { min-width: 0; }
[data-theme-layout="archway"] .aw-gate-t {
  display: block; font-family: var(--serif); font-weight: 700;
  font-size: .98rem; line-height: 1.3; overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="archway"] .aw-gate:hover .aw-gate-t { color: var(--accent); }
[data-theme-layout="archway"] .aw-gate-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  margin-top: .15rem; font-size: .8rem; line-height: 1.45; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="archway"] .aw-arch { width: min(100%, 560px); }
  [data-theme-layout="archway"] .aw-arch-cover { width: min(100%, 300px); }
}
@media (max-width: 720px) {
  [data-theme-layout="archway"] .aw-title { font-size: clamp(1.7rem, 8vw, 2.3rem); }
  [data-theme-layout="archway"] .aw-eyebrow { letter-spacing: .22em; text-indent: .22em; }
