:root[data-theme="gutter-white"] .gt-lead-foot,
:root[data-theme="gutter-white"] .gt-lead-ex,
:root[data-theme="gutter-white"] .gt-spine-n,
:root[data-theme="gutter-white"] .gt-row-meta { color: #636973; }

/* =========================================================================
   LAYOUT: cover — 封面 3:4 杂志封面居中大卡（导航居中批 · pure CSS, no JS）
   every selector scoped under [data-theme-layout="cover"], classes cv-*
   页头融合（选了融合法）：标准 .site-header 重塑成封面「顶部切片」——与
   .cv-cover 同宽同底、边框相接零间距：brand 缩成小字居中，.nav 居中细行
   上下细线（上=.nav border-top，下=页头 border-bottom）。首页封面卡从切片
   下方无缝续接；内页页头自然收成一块居中门楣牌，全站一致。
   ========================================================================= */
[data-theme-layout="cover"] { --cv-w: 720px; }
[data-theme-layout="cover"] main { display: block; padding: 0; }
[data-theme-layout="cover"] .cv-desk {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding: 0 0 clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: site-header = 封面顶部切片（居中导航门面） ---------- */
[data-theme-layout="cover"] .site-header {
  position: relative; top: auto;
  width: min(100% - 48px, var(--cv-w));
  margin-inline: auto;
  background: var(--surface);
  border: 1px solid var(--line);
  -webkit-backdrop-filter: none; backdrop-filter: none;
}
[data-theme-layout="cover"] .site-header .wrap { flex-direction: column; justify-content: center; height: auto; gap: .4rem; padding: .85rem 24px 0; }
[data-theme-layout="cover"] .site-header .brand { font-family: var(--sans); font-size: .82rem; font-weight: 700; letter-spacing: .34em; text-transform: uppercase; }
[data-theme-layout="cover"] .site-header .brand-logo { height: 22px; width: auto; }
[data-theme-layout="cover"] .site-header .nav {
  width: 100%; justify-content: center; flex-wrap: wrap; gap: .1rem 1.5rem;
  border-top: 1px solid var(--line);
  margin-top: .45rem; padding: .52rem 0 .58rem;
}
[data-theme-layout="cover"] .site-header .nav a { font-size: .78rem; font-weight: 600; letter-spacing: .22em; text-transform: uppercase; }
[data-theme-layout="cover"] .site-header .nav a:hover { color: var(--accent-soft); }
[data-theme-layout="cover"] .nav a[aria-current="page"]::after { bottom: -.62rem; }

/* ---- 封面大卡：3:4，与页头切片同宽拼接，外缘留桌面底色 ------------------ */
[data-theme-layout="cover"] .cv-cover {
  position: relative;
  width: min(100%, var(--cv-w));
  margin-inline: auto;
  aspect-ratio: 3 / 4;
  display: flex; flex-direction: column;
  background: var(--surface);
  border: 1px solid var(--line); border-top: 0;
  box-shadow: var(--shadow);
  padding: clamp(1.3rem, 4vw, 2.1rem) clamp(1.2rem, 3.5vw, 2.2rem) clamp(8rem, 20vw, 9.5rem);
}

/* 期号行：等宽小字居中三段（眉标 / 日期 / 篇数） */
[data-theme-layout="cover"] .cv-issue {
  display: flex; justify-content: center; align-items: baseline; flex-wrap: wrap; gap: .25rem 0;
  margin: 0 0 clamp(.9rem, 2.4vw, 1.4rem);
  font-family: var(--mono); font-size: .7rem; letter-spacing: .16em; text-transform: uppercase;
  color: var(--muted);
}
[data-theme-layout="cover"] .cv-issue-seg { min-width: 0; overflow-wrap: anywhere; }
[data-theme-layout="cover"] .cv-issue-seg + .cv-issue-seg::before { content: "·"; color: var(--faint); padding: 0 .9rem; }

/* 刊名：900 字重大字距居中 */
[data-theme-layout="cover"] .cv-name {
  margin: 0; text-align: center;
  font-family: var(--sans); font-weight: 900;
  font-size: clamp(2.2rem, 6.4vw, 4rem); line-height: 1.04;
  letter-spacing: .08em; text-transform: uppercase; text-wrap: balance;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="cover"] .cv-sub {
  /* 34ch + 右上 coverline 24%：两条车道互不相交（46ch 时右上 coverline 会压住描述，实测撞过） */
  margin: .65rem auto 0; max-width: 34ch; text-align: center;
  font-size: .94rem; line-height: 1.55; color: var(--muted); overflow-wrap: anywhere;
}

/* 封面故事：金色 kicker + 大标题 + 摘要，左对齐偏中 */
[data-theme-layout="cover"] .cv-story {
  display: flex; flex-direction: column; gap: .65rem; min-width: 0;
  width: 56%; margin: auto 0; margin-left: 5%;
  text-decoration: none; color: var(--ink);
}
[data-theme-layout="cover"] .cv-kicker {
  display: inline-flex; align-items: baseline; gap: .5rem; align-self: flex-start;
  font-size: .68rem; font-weight: 800; letter-spacing: .2em; text-transform: uppercase;
  color: var(--accent); border-bottom: 2px solid var(--accent); padding-bottom: .28rem;
}
[data-theme-layout="cover"] .cv-kicker i { font-style: normal; font-weight: 400; color: var(--faint); }
[data-theme-layout="cover"] .cv-kicker span { color: var(--muted); overflow-wrap: anywhere; }
[data-theme-layout="cover"] .cv-story-plate { display: block; border: 1px solid var(--line); }
[data-theme-layout="cover"] .cv-story-plate img { display: block; width: 100%; height: auto; max-height: 165px; object-fit: cover; }
[data-theme-layout="cover"] .cv-story-h {
  font-family: var(--sans); font-weight: 800;
  font-size: clamp(1.4rem, 3.4vw, 2.15rem); line-height: 1.12; letter-spacing: -.01em;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="cover"] .cv-story:hover .cv-story-h { color: var(--accent); text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 4px; }
[data-theme-layout="cover"] .cv-story-ex {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .94rem; line-height: 1.6; color: var(--ink-soft); overflow-wrap: anywhere;
}
[data-theme-layout="cover"] .cv-story-foot {
  display: flex; align-items: center; gap: 1rem; flex-wrap: wrap;
  font-size: .7rem; letter-spacing: .08em; text-transform: uppercase; color: var(--muted);
}
[data-theme-layout="cover"] .cv-story-more { display: inline-flex; align-items: center; gap: .35rem; font-weight: 700; color: var(--accent); }

/* coverlines：前 4 条 Posts 绝对定位散布右上 / 左下 / 右下 */
[data-theme-layout="cover"] .cv-lines { list-style: none; margin: 0; padding: 0; }
[data-theme-layout="cover"] .cv-line { position: absolute; margin: 0; min-width: 0; }
[data-theme-layout="cover"] .cv-line a { display: block; text-decoration: none; }
[data-theme-layout="cover"] .cv-line-t {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-weight: 800; font-size: .95rem; line-height: 1.3; color: var(--ink);
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="cover"] .cv-line-c { display: block; margin-top: .3rem; font-size: .64rem; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; color: var(--accent); overflow-wrap: anywhere; }
[data-theme-layout="cover"] .cv-line a:hover .cv-line-t { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="cover"] .cv-line:nth-child(1) { top: 33%; right: 4.5%; width: 24%; text-align: right; }
[data-theme-layout="cover"] .cv-line:nth-child(2) { bottom: 13%; left: 5%; width: 30%; }
[data-theme-layout="cover"] .cv-line:nth-child(3) { bottom: 5%; right: 4.5%; width: 28%; text-align: right; }
[data-theme-layout="cover"] .cv-line:nth-child(4) { top: 51%; right: 4.5%; width: 26%; text-align: right; }

/* 左下条码装饰（纯渐变，无文字） */
[data-theme-layout="cover"] .cv-barcode {
  position: absolute; left: 5%; bottom: 4.5%;
  width: 118px; height: 34px; opacity: .85;
  background: repeating-linear-gradient(90deg, var(--ink) 0 2px, transparent 2px 5px, var(--ink) 5px 6px, transparent 6px 9px);
}

/* ---- 封面下：推荐位（FeatLinks）+ 本期目录 + 分类索引 ------------------- */
[data-theme-layout="cover"] .cv-sec-h { margin: 0; font-family: var(--sans); font-size: .72rem; font-weight: 800; letter-spacing: .24em; text-transform: uppercase; color: var(--ink); }
[data-theme-layout="cover"] .cv-rack,
[data-theme-layout="cover"] .cv-toc { width: min(100%, var(--cv-w)); margin: clamp(2rem, 5vw, 2.8rem) auto 0; }
[data-theme-layout="cover"] .cv-rack-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: .7rem; margin-top: .7rem; }
[data-theme-layout="cover"] .cv-pick {
  display: flex; align-items: center; gap: .65rem; min-width: 0;
  padding: .6rem .7rem; border: 1px solid var(--line); background: var(--surface);
  text-decoration: none; transition: border-color .15s;
}
[data-theme-layout="cover"] .cv-pick:hover { border-color: var(--accent); }
[data-theme-layout="cover"] .cv-pick-ic { flex: 0 0 auto; width: 34px; height: 34px; overflow: hidden; display: grid; place-items: center; background: var(--accent-wash); color: var(--accent); }
[data-theme-layout="cover"] .cv-pick-ic b { font-weight: 800; font-size: 1rem; line-height: 1; }
[data-theme-layout="cover"] .cv-pick-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="cover"] .cv-pick-t {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .9rem; font-weight: 600; line-height: 1.35; color: var(--ink); overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="cover"] .cv-pick:hover .cv-pick-t { color: var(--accent); }
[data-theme-layout="cover"] .cv-toc-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  border-bottom: 2px solid var(--ink); padding-bottom: .45rem; margin-bottom: .3rem;
}
[data-theme-layout="cover"] .cv-toc-all { display: inline-flex; align-items: center; gap: .3rem; flex: 0 0 auto; font-size: .72rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--accent); text-decoration: none; }
[data-theme-layout="cover"] .cv-toc-all:hover { color: var(--accent-soft); }
[data-theme-layout="cover"] .cv-row {
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: baseline; gap: 1rem;
  padding: .78rem 2px; border-bottom: 1px solid var(--line-soft);
  text-decoration: none;
}
[data-theme-layout="cover"] .cv-row-t { font-size: 1.02rem; font-weight: 600; color: var(--ink); overflow-wrap: anywhere; transition: color .15s; }
[data-theme-layout="cover"] .cv-row:hover .cv-row-t { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="cover"] .cv-row-c { font-size: .66rem; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--accent); overflow-wrap: anywhere; }
[data-theme-layout="cover"] .cv-row-d { font-size: .72rem; color: var(--muted); font-variant-numeric: tabular-nums; }
[data-theme-layout="cover"] .cv-cats { display: flex; flex-wrap: wrap; justify-content: center; gap: .5rem; margin-top: clamp(2rem, 5vw, 2.8rem); }
[data-theme-layout="cover"] .cv-cat {
  display: inline-flex; align-items: baseline; gap: .45rem; min-width: 0;
  padding: .34rem .8rem; border: 1px solid var(--line);
  font-size: .78rem; font-weight: 600; letter-spacing: .1em; text-transform: uppercase;
  color: var(--ink-soft); text-decoration: none; transition: color .15s, border-color .15s;
}
[data-theme-layout="cover"] .cv-cat small { font-size: .66rem; color: var(--muted); }
[data-theme-layout="cover"] .cv-cat:hover { color: var(--accent); border-color: var(--accent); }
[data-theme-layout="cover"] .cv-cat-all { color: var(--accent); border-color: var(--accent); }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="cover"] .cv-name { font-size: clamp(2rem, 8vw, 3.2rem); }
  [data-theme-layout="cover"] .cv-story { width: 62%; margin-left: 3%; }
  [data-theme-layout="cover"] .cv-story-plate { display: none; }
  [data-theme-layout="cover"] .cv-line:nth-child(1), [data-theme-layout="cover"] .cv-line:nth-child(3) { width: 30%; }
}
@media (max-width: 720px) {
  [data-theme-layout="cover"] .cv-cover { aspect-ratio: auto; padding: 1.5rem 1.15rem 1.7rem; }
  [data-theme-layout="cover"] .cv-name { font-size: clamp(1.9rem, 9vw, 2.6rem); letter-spacing: .05em; }
  [data-theme-layout="cover"] .cv-story { width: 100%; margin: 1.6rem 0 0; }
  [data-theme-layout="cover"] .cv-story-plate { display: block; }
  /* coverlines 降级为普通列表行 */
  [data-theme-layout="cover"] .cv-lines { margin-top: 1.5rem; border-top: 1px solid var(--line); }
  [data-theme-layout="cover"] .cv-line:nth-child(n) { position: static; inset: auto; width: auto; text-align: left; }
  [data-theme-layout="cover"] .cv-line a { padding: .75rem 2px; border-bottom: 1px solid var(--line-soft); }
  [data-theme-layout="cover"] .cv-barcode { position: static; display: block; margin-top: 1.4rem; }
  [data-theme-layout="cover"] .cv-row { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="cover"] .cv-rack-row { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 620px) {
  /* 基础版 620 抽屉导航接管：还原抽屉内衬，切片按钮居中 */
  [data-theme-layout="cover"] .site-header .nav { margin-top: 0; padding: .35rem .7rem .7rem; }
  [data-theme-layout="cover"] .site-header .menu-toggle { margin: 0 0 .5rem; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="cover"] .cv-story-h,
  [data-theme-layout="cover"] .cv-line-t,
  [data-theme-layout="cover"] .cv-pick,
  [data-theme-layout="cover"] .cv-pick-t,
  [data-theme-layout="cover"] .cv-row-t,
  [data-theme-layout="cover"] .cv-cat { transition: none; }
}

/* ============================================================
   封面 · Cover —— Cover 骨架默认皮：夜蓝黑封面、月白刊名、暖金 kicker
   ============================================================ */
:root[data-theme="cover"] {
  --bg: #171c23; --surface: #101317;
  --ink: #f4f6f2; --ink-soft: #ccd2d8; --muted: #a7b0b9; --faint: #7e8792;
  --line: #2a3038; --line-soft: #21262d;
  --accent: #ffc247; --accent-soft: #ffd47a; --accent-wash: #2a2312;
  --w-wide: 1200px; --radius: 0px; --code-bg: #0a0c0f;
  --shadow: 0 1px 2px rgba(0,0,0,.5), 0 18px 44px rgba(0,0,0,.5);
}
:root[data-theme="cover"] .btn-primary { color: #14181e; }

/* ============================================================
   红刊 · Scarlet —— Cover 骨架反差皮：正红封面底（压深到白字 7:1）+
   白字 + 黑细节（kicker 黑章、黑条码），accent 走米白、hover 升到纯白
   ============================================================ */
:root[data-theme="scarlet"] {
  --bg: #1a1214; --surface: #a32b21;
  --ink: #ffffff; --ink-soft: #ffe4de; --muted: #f6cfc8; --faint: #f5c6bf;
  --line: #7f231a; --line-soft: #93291f;
  --accent: #ffe4de; --accent-soft: #ffffff; --accent-wash: #7c150c;
  --w-wide: 1200px; --radius: 0px; --code-bg: #14090b;
  --shadow: 0 1px 2px rgba(0,0,0,.45), 0 18px 44px rgba(0,0,0,.55);
}
:root[data-theme="scarlet"] .btn-primary { color: #7c1408; }
:root[data-theme="scarlet"] .cv-kicker { background: #16090b; color: #fff; border-bottom: 0; padding: .3rem .55rem; }
:root[data-theme="scarlet"] .cv-kicker i { color: #f5c6bf; }
:root[data-theme="scarlet"] .cv-kicker span { color: #ffcfc7; }
:root[data-theme="scarlet"] .cv-barcode { background: repeating-linear-gradient(90deg, #16090b 0 2px, transparent 2px 5px, #16090b 5px 6px, transparent 6px 9px); opacity: 1; }
:root[data-theme="scarlet"] .cv-toc-head { border-bottom-color: #16090b; }

/* ============================================================
   Cover 纯白系 —— cover-white：中性灰基底照抄第三批纯白段，
   金 accent 压深到白底可读（#8f6400，实算 5.26 / 卡面 5.04）
   ============================================================ */
:root[data-theme="cover-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #8f6400; --accent-soft: #6f4e00; --accent-wash: #f9f1dd;
  --w-wide: 1200px; --radius: 0px;
}
:root[data-theme="cover-white"] .btn-primary { color: #fff; }
/* 卡面 #fafaf8 上 muted #707680 只有 4.38——压深一档到 4.76 */
:root[data-theme="cover-white"] .cv-issue,
:root[data-theme="cover-white"] .cv-sub,
:root[data-theme="cover-white"] .cv-story-foot { color: #6b707a; }

/* =========================================================================
   LAYOUT: marquee — 戏台 theatre marquee front (pure CSS, no JS)
   every selector scoped under [data-theme-layout="marquee"], classes mq-*
   页头=剧院门头板（灯泡两列+霓虹 brand+胶囊导航全部居中）/ home=场次单
   ========================================================================= */
[data-theme-layout="marquee"] main { display: block; }
[data-theme-layout="marquee"] .mq-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding: clamp(1.6rem, 4vw, 2.8rem) 0 clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: the site-header becomes the theatre door board ------ */
/* 门头板不跟随滚动（剧院门脸留在入口），标准 sticky 改 relative */
[data-theme-layout="marquee"] .site-header {
  position: relative; z-index: 50;
  background: var(--bg); border-bottom: 1px solid var(--line-soft);
  -webkit-backdrop-filter: none; backdrop-filter: none;
  padding: clamp(.9rem, 2.5vw, 1.5rem) 0;
}
[data-theme-layout="marquee"] .site-header .wrap {
  position: relative; flex-direction: column; align-items: center; justify-content: center;
  gap: .7rem; height: auto;
  width: min(100% - 48px, 780px);
  padding: 2rem clamp(1.2rem, 4vw, 2.6rem) 1.9rem;
  background: var(--surface);
  border: 3px solid var(--accent);
  border-radius: calc(var(--radius) + 10px);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 22%, transparent),
              0 0 30px color-mix(in srgb, var(--accent) 26%, transparent),
              var(--shadow);
}
/* 上下两排灯泡：亮/暗两层点列 repeat-x，动画=背景位互换的走马灯（step 保持） */
[data-theme-layout="marquee"] .site-header .wrap::before,
[data-theme-layout="marquee"] .site-header .wrap::after {
  content: ""; position: absolute; left: 18px; right: 18px; height: 8px;
  background-image:
    radial-gradient(circle at 50% 50%, var(--accent) 0 2.6px, transparent 3.2px),
    radial-gradient(circle at 50% 50%, color-mix(in srgb, var(--accent) 45%, var(--surface)) 0 2.6px, transparent 3.2px);
  background-size: 36px 8px, 36px 8px;
  background-position: 0 50%, 18px 50%;
  background-repeat: repeat-x, repeat-x;
  animation: mq-chase 1.5s step-end infinite;
  pointer-events: none;
}
[data-theme-layout="marquee"] .site-header .wrap::before { top: 9px; }
[data-theme-layout="marquee"] .site-header .wrap::after { bottom: 9px; }
@keyframes mq-chase {
  0%, 49.9% { background-position: 0 50%, 18px 50%; }
  50%, 100% { background-position: 18px 50%, 0 50%; }
}
/* brand 霓虹大字距居中（灯金辉光） */
[data-theme-layout="marquee"] .site-header .brand {
  justify-content: center; text-align: center;
  font-family: var(--serif); font-size: clamp(1.4rem, 3.4vw, 2rem); font-weight: 800;
  letter-spacing: .3em; text-indent: .3em; text-transform: uppercase; color: var(--ink);
  text-shadow: 0 0 12px color-mix(in srgb, var(--accent) 55%, transparent),
               0 0 30px color-mix(in srgb, var(--accent) 30%, transparent);
}
/* 导航居中一排胶囊：首项实底（:first-child）、其余描边 */
[data-theme-layout="marquee"] .site-header .nav { justify-content: center; flex-wrap: wrap; gap: .5rem .55rem; }
[data-theme-layout="marquee"] .site-header .nav > a {
  padding: .32rem 1.05rem; border: 1px solid var(--line); border-radius: 999px;
  font-size: .88rem; font-weight: 600; letter-spacing: .04em; color: var(--ink-soft);
  transition: color .15s, border-color .15s, background .15s;
}
[data-theme-layout="marquee"] .site-header .nav > a:hover { color: var(--accent); border-color: var(--accent); }
[data-theme-layout="marquee"] .site-header .nav > a[aria-current="page"] { color: var(--accent); border-color: var(--accent); }
[data-theme-layout="marquee"] .site-header .nav > a[aria-current="page"]::after { display: none; }
/* 实底首项文字用 --bg：对比=accent 对 bg（各皮实算 ≥4.5），hover 走 soft 只升 */
[data-theme-layout="marquee"] .site-header .nav > a:first-child {
  background: var(--accent); border-color: var(--accent); color: var(--bg);
}
[data-theme-layout="marquee"] .site-header .nav > a:first-child:hover {
  background: var(--accent-soft); border-color: var(--accent-soft); color: var(--bg);
}
[data-theme-layout="marquee"] .site-header .nav .search-ico { opacity: 1; }
[data-theme-layout="marquee"] .site-header .menu-toggle { position: absolute; top: .6rem; right: .6rem; margin: 0; }

/* ---- stage: centered hero + category slate ------------------------------ */
[data-theme-layout="marquee"] .mq-stage { text-align: center; margin: 0 0 clamp(1.4rem, 3.5vw, 2.2rem); }
[data-theme-layout="marquee"] .mq-eyebrow {
  margin: 0 0 .8rem; font-size: .74rem; font-weight: 700;
  letter-spacing: .3em; text-transform: uppercase; color: var(--accent);
}
[data-theme-layout="marquee"] .mq-title {
  margin: 0 0 .7rem; font-family: var(--serif); font-weight: 800;
  font-size: clamp(2rem, 5.4vw, 3.4rem); line-height: 1.12; letter-spacing: -.01em;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="marquee"] .mq-desc {
  max-width: 60ch; margin: 0 auto; font-size: 1.02rem; line-height: 1.7;
  color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="marquee"] .mq-slate {
  display: flex; flex-wrap: wrap; justify-content: center; gap: .5rem;
  margin-top: clamp(1rem, 2.5vw, 1.5rem);
}
[data-theme-layout="marquee"] .mq-slot {
  display: inline-flex; align-items: baseline; gap: .4rem; min-width: 0;
  padding: .28rem .85rem; border: 1px solid var(--line); border-radius: 999px;
  font-size: .86rem; color: var(--ink-soft); text-decoration: none;
  transition: color .15s, border-color .15s;
}
[data-theme-layout="marquee"] .mq-slot:hover { color: var(--accent); border-color: var(--accent); }
[data-theme-layout="marquee"] .mq-slot-name { overflow-wrap: anywhere; }
[data-theme-layout="marquee"] .mq-slot-n { font-size: .68rem; color: var(--muted); }
[data-theme-layout="marquee"] .mq-slot-all { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 55%, var(--line)); }

/* ---- feature: 主打场次大行（左缘金边 + 「主打」徽签=HomeFeatured） ------- */
[data-theme-layout="marquee"] .mq-feature {
  display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr);
  gap: clamp(1.1rem, 3vw, 2rem); align-items: center;
  padding: clamp(1.1rem, 3vw, 1.8rem) clamp(1rem, 3vw, 1.8rem);
  background: var(--surface);
  border: 1px solid var(--line); border-left: 5px solid var(--accent);
  border-radius: var(--radius); box-shadow: var(--shadow);
  text-decoration: none; color: var(--ink);
  transition: border-color .15s;
}
[data-theme-layout="marquee"] .mq-feature:hover { border-color: var(--accent); }
[data-theme-layout="marquee"] .mq-feature-solo { grid-template-columns: minmax(0, 1fr); }
[data-theme-layout="marquee"] .mq-feature-body { display: flex; flex-direction: column; gap: .7rem; min-width: 0; }
[data-theme-layout="marquee"] .mq-billing { display: flex; align-items: center; flex-wrap: wrap; gap: .6rem; }
[data-theme-layout="marquee"] .mq-billing-tag {
  font-family: var(--sans); font-size: .7rem; font-weight: 800;
  letter-spacing: .18em; text-transform: uppercase;
  background: var(--accent); color: var(--bg);
  padding: .3rem .6rem; border-radius: 4px;
}
[data-theme-layout="marquee"] .mq-billing-cat {
  font-size: .74rem; letter-spacing: .14em; text-transform: uppercase;
  color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="marquee"] .mq-feature-h {
  font-family: var(--serif); font-weight: 800;
  font-size: clamp(1.5rem, 3.4vw, 2.3rem); line-height: 1.15;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="marquee"] .mq-feature:hover .mq-feature-h { color: var(--accent); }
[data-theme-layout="marquee"] .mq-feature-ex {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .98rem; line-height: 1.66; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="marquee"] .mq-feature-foot {
  display: flex; justify-content: space-between; align-items: center; gap: 1rem;
  border-top: 1px solid var(--line-soft); padding-top: .6rem;
  font-size: .78rem; letter-spacing: .04em; color: var(--muted);
}
[data-theme-layout="marquee"] .mq-feature-more {
  display: inline-flex; align-items: center; gap: .35rem;
  font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--accent);
}
[data-theme-layout="marquee"] .mq-feature-cover {
  display: block; min-width: 0; overflow: hidden;
  border: 1px solid var(--line); border-radius: calc(var(--radius) - 4px);
}
[data-theme-layout="marquee"] .mq-feature-cover img { display: block; width: 100%; height: auto; aspect-ratio: 16 / 10; object-fit: cover; }

/* ---- booths: FeatLinks 一排「售票口」胶囊 ------------------------------- */
[data-theme-layout="marquee"] .mq-booths { margin-top: clamp(1.2rem, 3vw, 1.8rem); text-align: center; }
[data-theme-layout="marquee"] .mq-booths-h {
  margin: 0 0 .7rem; font-family: var(--sans); font-size: .74rem; font-weight: 800;
  letter-spacing: .24em; text-transform: uppercase; color: var(--muted);
}
[data-theme-layout="marquee"] .mq-booths-row { display: flex; flex-wrap: wrap; justify-content: center; gap: .6rem; }
[data-theme-layout="marquee"] .mq-booth {
  display: inline-flex; align-items: center; gap: .55rem; min-width: 0;
  padding: .3rem .95rem .3rem .3rem;
  background: var(--surface); border: 1px solid var(--line); border-radius: 999px;
  text-decoration: none; color: var(--ink);
  transition: border-color .15s;
}
[data-theme-layout="marquee"] .mq-booth:hover { border-color: var(--accent); }
[data-theme-layout="marquee"] .mq-booth-ic {
  flex: 0 0 auto; width: 30px; height: 30px; overflow: hidden;
  display: grid; place-items: center; border-radius: 999px;
  background: var(--accent-wash); color: var(--accent);
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--line));
}
[data-theme-layout="marquee"] .mq-booth-ic b { font-family: var(--serif); font-weight: 800; font-size: .95rem; line-height: 1; }
[data-theme-layout="marquee"] .mq-booth-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="marquee"] .mq-booth-t { font-size: .9rem; font-weight: 600; overflow-wrap: anywhere; transition: color .15s; }
[data-theme-layout="marquee"] .mq-booth:hover .mq-booth-t { color: var(--accent); }

/* ---- bill: 场次行卡（等宽期号列=CSS counter，右侧分类描边小签） ---------- */
[data-theme-layout="marquee"] .mq-bill { margin-top: clamp(1.6rem, 4vw, 2.4rem); }
[data-theme-layout="marquee"] .mq-bill-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  border-bottom: 2px solid var(--ink); padding-bottom: .5rem;
  margin: 0 0 clamp(.9rem, 2.5vw, 1.3rem);
}
[data-theme-layout="marquee"] .mq-bill-t {
  margin: 0; font-family: var(--sans); font-size: .78rem; font-weight: 800;
  letter-spacing: .24em; text-transform: uppercase; color: var(--ink);
}
[data-theme-layout="marquee"] .mq-bill-all {
  display: inline-flex; align-items: center; gap: .3rem; flex: 0 0 auto;
  font-family: var(--sans); font-size: .74rem; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase;
  color: var(--accent); text-decoration: none;
}
[data-theme-layout="marquee"] .mq-rows {
  list-style: none; margin: 0; padding: 0; counter-reset: mq-bill;
  display: flex; flex-direction: column; gap: .65rem;
}
[data-theme-layout="marquee"] .mq-row { counter-increment: mq-bill; min-width: 0; }
[data-theme-layout="marquee"] .mq-row-in {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 1rem; align-items: center;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  overflow: hidden; text-decoration: none; color: var(--ink);
  transition: border-color .15s;
}
[data-theme-layout="marquee"] .mq-row-in:hover { border-color: var(--accent); }
[data-theme-layout="marquee"] .mq-no {
  align-self: stretch; min-width: 3.3rem; display: grid; place-items: center;
  padding: .85rem .6rem; border-right: 1px solid var(--line-soft);
  background: color-mix(in srgb, var(--accent) 6%, var(--surface));
}
[data-theme-layout="marquee"] .mq-no::before {
  content: counter(mq-bill, decimal-leading-zero);
  font-family: var(--serif); font-weight: 800; font-size: 1.05rem;
  font-variant-numeric: tabular-nums; color: var(--accent);
}
[data-theme-layout="marquee"] .mq-row-body { display: flex; flex-direction: column; gap: .25rem; min-width: 0; padding: .8rem 0; }
[data-theme-layout="marquee"] .mq-row-h {
  font-family: var(--serif); font-weight: 700; font-size: 1.12rem; line-height: 1.3;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="marquee"] .mq-row-in:hover .mq-row-h { color: var(--accent); }
[data-theme-layout="marquee"] .mq-row-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .9rem; line-height: 1.55; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="marquee"] .mq-row-side {
  display: flex; flex-direction: column; align-items: flex-end; gap: .35rem;
  padding: .8rem 1rem .8rem 0;
}
[data-theme-layout="marquee"] .mq-row-cat {
  padding: .14rem .6rem; border: 1px solid color-mix(in srgb, var(--accent) 55%, var(--line));
  border-radius: 999px; font-family: var(--sans); font-size: .68rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase; color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="marquee"] .mq-row-date {
  font-family: var(--sans); font-size: .72rem; letter-spacing: .05em;
  font-variant-numeric: tabular-nums; color: var(--muted);
}

/* ---- exit colophon ------------------------------------------------------- */
[data-theme-layout="marquee"] .mq-exit {
  display: flex; justify-content: center; align-items: baseline; gap: .8rem;
  margin-top: clamp(1.8rem, 4vw, 2.8rem); padding-top: .9rem;
  border-top: 3px double var(--line);
  font-size: .92rem; letter-spacing: .1em; color: var(--faint);
}
[data-theme-layout="marquee"] .mq-exit a { color: var(--ink-soft); text-decoration: none; transition: color .15s; }
[data-theme-layout="marquee"] .mq-exit a:hover { color: var(--accent); }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="marquee"] .mq-feature { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="marquee"] .mq-feature-cover { order: -1; }
}
@media (max-width: 720px) {
  [data-theme-layout="marquee"] .site-header .wrap { padding: 1.9rem 1rem 1.5rem; }
  [data-theme-layout="marquee"] .mq-title { font-size: clamp(1.7rem, 8vw, 2.3rem); }
  [data-theme-layout="marquee"] .mq-feature-foot { flex-wrap: wrap; }
  [data-theme-layout="marquee"] .mq-row-in { grid-template-columns: auto minmax(0, 1fr); gap: .8rem; }
  [data-theme-layout="marquee"] .mq-row-side {
    grid-column: 1 / -1; flex-direction: row; align-items: center; justify-content: flex-start;
    padding: 0 1rem .8rem; border-top: 0;
  }
}
/* ≤620px：base 的 menu-toggle 抽屉接管，胶囊还原成整行菜单项 */
@media (max-width: 620px) {
  [data-theme-layout="marquee"] .site-header .nav > a,
  [data-theme-layout="marquee"] .site-header .nav > a:first-child {
    background: transparent; border: 0; border-bottom: 1px solid var(--line-soft);
    border-radius: 0; color: var(--ink); padding: .8rem .35rem; font-size: 1rem;
  }
  [data-theme-layout="marquee"] .site-header .nav > a:hover,
  [data-theme-layout="marquee"] .site-header .nav > a:first-child:hover,
  [data-theme-layout="marquee"] .site-header .nav > a[aria-current="page"] { color: var(--accent); background: transparent; }
}

/* ---- reduced motion：灯泡不闪不动（亮暗双层静态可见），过渡全关 ---------- */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="marquee"] .site-header .wrap::before,
  [data-theme-layout="marquee"] .site-header .wrap::after { animation: none; }
  [data-theme-layout="marquee"] .site-header .nav > a,
  [data-theme-layout="marquee"] .mq-slot,
  [data-theme-layout="marquee"] .mq-feature,
  [data-theme-layout="marquee"] .mq-feature-h,
  [data-theme-layout="marquee"] .mq-booth,
  [data-theme-layout="marquee"] .mq-booth-t,
  [data-theme-layout="marquee"] .mq-row-in,
  [data-theme-layout="marquee"] .mq-row-h,
  [data-theme-layout="marquee"] .mq-exit a { transition: none; }
}

/* ============================================================
   戏台 · Marquee —— Marquee 骨架默认皮：夜幕、绛栗天幕板、灯金霓虹
   ============================================================ */
:root[data-theme="marquee"] {
  --bg: #191214; --surface: #2b1c20;
  --ink: #f4e9dc; --ink-soft: #d9c9b8; --muted: #b5a390; --faint: #94836f;
  --line: #4a363b; --line-soft: #37262b;
  --accent: #e8b25c; --accent-soft: #f2c67f; --accent-wash: #3a2a1c;
  --w-wide: 1200px; --radius: 14px; --code-bg: #120c0e;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 12px 32px rgba(0, 0, 0, .5);
}
/* 灯金实底上走深字（accent 对 bg 9.63），别用默认白字 */
:root[data-theme="marquee"] .btn-primary { color: #191214; }
:root[data-theme="marquee"] .site-header { background: var(--bg); }

/* ============================================================
   日场 · Daybill —— Marquee 骨架 + 日场戏单皮：米纸、朱红门头、墨字
   ============================================================ */
:root[data-theme="daybill"] {
  --bg: #f6eedd; --surface: #fdf8ec;
  --ink: #262019; --ink-soft: #4c4335; --muted: #6e6350; --faint: #8a7e69;
  --line: #dccdb0; --line-soft: #ebdfc8;
  --accent: #b0331d; --accent-soft: #8f2410; --accent-wash: #f3decf;
  --w-wide: 1200px; --radius: 14px;
  --shadow: 0 1px 2px rgba(38, 32, 25, .06), 0 10px 26px rgba(38, 32, 25, .08);
}
:root[data-theme="daybill"] .btn-primary { color: #fff; }
/* 白日辉光收敛：brand 只留一层淡朱晕，门头板外圈光减弱 */
:root[data-theme="daybill"] .site-header .brand { text-shadow: 0 0 14px color-mix(in srgb, var(--accent) 22%, transparent); }
:root[data-theme="daybill"] .site-header .wrap {
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 12%, transparent), var(--shadow);
}

/* ============================================================
   戏台纯白 · Marquee White —— 中性灰基底（照抄纯白系），灯金压深铜金：
   #8a6408 on #fff 5.37 / hover #6f5106 7.35 只升
   ============================================================ */
:root[data-theme="marquee-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #8a6408; --accent-soft: #6f5106; --accent-wash: #f7f0dd;
  --w-wide: 1200px; --radius: 14px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .05), 0 8px 22px rgba(16, 18, 24, .06);
}
:root[data-theme="marquee-white"] .btn-primary { color: #fff; }
/* 白底收敛：brand 不发光、门头板光晕转中性、卡面回纯白（muted 对 #fff 4.57 达标） */
:root[data-theme="marquee-white"] .site-header .brand { text-shadow: none; }
:root[data-theme="marquee-white"] .site-header .wrap { border-width: 2px; box-shadow: var(--shadow); }
:root[data-theme="marquee-white"] .mq-feature,
:root[data-theme="marquee-white"] .mq-row-in,
:root[data-theme="marquee-white"] .mq-booth { background: var(--bg); }
:root[data-theme="marquee-white"] .mq-no { background: var(--accent-wash); }

/* =========================================================================
   LAYOUT: triptych — 三联祭坛画 triptych altarpiece (pure CSS, no JS)
   every selector scoped under [data-theme-layout="triptych"], classes tp-*
   楣梁页头：标准 .site-header 收窄居中成横梁（浅底细框 + 底边双线），
   brand 与 .nav 同行并列、整体居中；home = 翼|中央拱顶|翼（1fr 1.4fr 1fr）
   ========================================================================= */
[data-theme-layout="triptych"] main { display: block; }
[data-theme-layout="triptych"] .tp-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding: clamp(1rem, 2.5vw, 1.8rem) 0 clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: 标准页头 CSS 重塑为「楣梁」———— .site-header 退为
   透明托座，.wrap 收窄居中成横梁：浅底细框、底边双线；brand 在左组、
   .nav 紧随，整体居中（模板零改动；≤620px 沿用默认 menu-toggle 抽屉） ---- */
[data-theme-layout="triptych"] .site-header {
  position: relative; z-index: 50;
  background: transparent; border-bottom: 0;
  -webkit-backdrop-filter: none; backdrop-filter: none;
  padding: clamp(.8rem, 2.2vw, 1.3rem) 24px 0;
}
[data-theme-layout="triptych"] .site-header .wrap {
  height: auto; min-height: 56px;
  max-width: min(100%, calc(var(--w-wide) - 240px));
  flex-wrap: wrap; justify-content: center;
  column-gap: clamp(1.4rem, 3.5vw, 2.8rem); row-gap: .15rem;
  padding: .45rem clamp(1.1rem, 3vw, 2.2rem);
  background: var(--surface);
  border: 1px solid var(--line);
  border-bottom: 5px double var(--accent);
}
[data-theme-layout="triptych"] .brand { font-size: 1.16rem; letter-spacing: .05em; }
[data-theme-layout="triptych"] .nav { gap: clamp(.9rem, 2.2vw, 1.5rem); }
[data-theme-layout="triptych"] .nav a { font-size: .9rem; letter-spacing: .04em; }
[data-theme-layout="triptych"] .nav a[aria-current="page"]::after { bottom: -6px; }

/* ---- pediment: 楣梁下的居中山花（hero 眉标/大标题/描述） ------------------ */
[data-theme-layout="triptych"] .tp-pediment {
  text-align: center; max-width: 72ch;
  margin: clamp(1.4rem, 4vw, 2.6rem) auto clamp(1.6rem, 3.6vw, 2.6rem);
}
[data-theme-layout="triptych"] .tp-eyebrow {
  margin: 0 0 .6rem; font-size: .74rem; font-weight: 700;
  letter-spacing: .3em; text-transform: uppercase; color: var(--accent);
}
[data-theme-layout="triptych"] .tp-title {
  margin: 0; font-family: var(--serif); font-weight: 700;
  font-size: clamp(1.9rem, 4.6vw, 3rem); line-height: 1.14; letter-spacing: -.01em;
  overflow-wrap: anywhere;
}
[data-theme-layout="triptych"] .tp-motto {
  margin: .7rem auto 0; max-width: 56ch;
  font-size: 1.02rem; line-height: 1.65; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- altar grid: 翼|中央|翼；DOM 里中央在前（920px 纵排时自然置顶），
   桌面用显式 grid-column 摆回三联；稀疏数据走 tp-noleft/tp-noright/tp-flat ---- */
[data-theme-layout="triptych"] .tp-altar {
  display: grid; align-items: start;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr) minmax(0, 1fr);
  gap: clamp(1.1rem, 2.6vw, 2rem);
}
[data-theme-layout="triptych"] .tp-apse { grid-column: 2; grid-row: 1; }
[data-theme-layout="triptych"] .tp-wing-l { grid-column: 1; grid-row: 1; }
[data-theme-layout="triptych"] .tp-wing-r { grid-column: 3; grid-row: 1; }
/* 无最新列表：中央+右翼两联 */
[data-theme-layout="triptych"] .tp-altar.tp-noleft { grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); }
[data-theme-layout="triptych"] .tp-altar.tp-noleft .tp-apse { grid-column: 1; }
[data-theme-layout="triptych"] .tp-altar.tp-noleft .tp-wing-r { grid-column: 2; }
/* 无右翼数据：左翼+中央两联 */
[data-theme-layout="triptych"] .tp-altar.tp-noright { grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr); }
/* 只剩中央：单联居中 */
[data-theme-layout="triptych"] .tp-altar.tp-noleft.tp-noright { grid-template-columns: minmax(0, 1fr); }
[data-theme-layout="triptych"] .tp-altar.tp-noleft.tp-noright .tp-apse { max-width: 620px; width: 100%; justify-self: center; }
/* 无头条（tp-flat）：两翼平铺 */
[data-theme-layout="triptych"] .tp-altar.tp-flat { grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr)); }
[data-theme-layout="triptych"] .tp-altar.tp-flat .tp-wing-l,
[data-theme-layout="triptych"] .tp-altar.tp-flat .tp-wing-r { grid-column: auto; grid-row: auto; }

/* ---- apse: 中央圆拱大卡（上半拱 + 外圈细拱框；封面嵌拱、无图落款印章） --- */
[data-theme-layout="triptych"] .tp-apse {
  --tp-arch: clamp(150px, 19vw, 225px);
  --tp-pad-t: clamp(2.6rem, 6vw, 3.6rem);
  --tp-pad-x: clamp(1.3rem, 3vw, 2.2rem);
  --tp-pad-b: clamp(1.5rem, 3.2vw, 2.1rem);
  display: flex; flex-direction: column; align-items: center; text-align: center;
  gap: .8rem; min-width: 0; text-decoration: none; color: var(--ink);
  padding: var(--tp-pad-t) var(--tp-pad-x) var(--tp-pad-b);
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--tp-arch) var(--tp-arch) var(--radius) var(--radius);
  box-shadow: 0 0 0 4px var(--bg), 0 0 0 5px var(--line-soft), var(--shadow);
  transition: transform .18s ease, box-shadow .18s ease;
}
[data-theme-layout="triptych"] .tp-apse:hover { transform: translateY(-3px); }
[data-theme-layout="triptych"] .tp-apse-cover {
  display: block; align-self: stretch;
  margin: calc(-1 * var(--tp-pad-t)) calc(-1 * var(--tp-pad-x)) .15rem;
  border-radius: calc(var(--tp-arch) - 1px) calc(var(--tp-arch) - 1px) 0 0;
  overflow: hidden; border-bottom: 1px solid var(--line);
}
[data-theme-layout="triptych"] .tp-apse-cover img { display: block; width: 100%; height: auto; aspect-ratio: 4 / 3; object-fit: cover; }
[data-theme-layout="triptych"] .tp-apse-seal {
  display: grid; place-items: center; width: 82px; height: 82px; border-radius: 50%;
  background: var(--accent-wash); color: var(--accent); border: 1px solid var(--line);
  font-family: var(--serif); font-weight: 700; font-size: 1.8rem; line-height: 1;
}
[data-theme-layout="triptych"] .tp-apse-kicker {
  display: inline-flex; align-items: baseline; gap: .5rem; min-width: 0;
  font-size: .72rem; font-weight: 800; letter-spacing: .24em; text-transform: uppercase;
  color: var(--accent);
}
[data-theme-layout="triptych"] .tp-apse-kicker i { font-style: normal; color: var(--faint); }
[data-theme-layout="triptych"] .tp-apse-cat { overflow-wrap: anywhere; }
[data-theme-layout="triptych"] .tp-apse-h {
  font-family: var(--serif); font-weight: 700;
  font-size: clamp(1.5rem, 3.4vw, 2.2rem); line-height: 1.16; letter-spacing: -.012em;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="triptych"] .tp-apse:hover .tp-apse-h { color: var(--accent); }
[data-theme-layout="triptych"] .tp-apse-ex {
  display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden;
  max-width: 46ch; font-size: .98rem; line-height: 1.66; color: var(--ink-soft); overflow-wrap: anywhere;
}
[data-theme-layout="triptych"] .tp-apse-foot { display: flex; flex-direction: column; align-items: center; gap: .55rem; margin-top: .2rem; }
[data-theme-layout="triptych"] .tp-enter {
  display: inline-flex; align-items: center; gap: .4rem;
  padding: .55rem 1.35rem; border-radius: 999px;
  background: var(--accent); color: var(--bg);
  font-size: .78rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase;
  transition: background .15s;
}
[data-theme-layout="triptych"] .tp-apse:hover .tp-enter { background: var(--accent-soft); }
[data-theme-layout="triptych"] .tp-apse-date { font-size: .72rem; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); }

/* ---- wings: 两翼紧凑条目列（小节标 + 标题/小字/日期行） ------------------- */
[data-theme-layout="triptych"] .tp-wing { display: flex; flex-direction: column; min-width: 0; }
[data-theme-layout="triptych"] .tp-wing-h {
  margin: 0 0 .2rem; padding-bottom: .55rem; border-bottom: 2px solid var(--ink);
  font-family: var(--sans); font-size: .74rem; font-weight: 800;
  letter-spacing: .22em; text-transform: uppercase; color: var(--ink);
}
[data-theme-layout="triptych"] .tp-row {
  display: flex; flex-direction: column; gap: .28rem; min-width: 0;
  padding: .72rem 0; border-bottom: 1px solid var(--line-soft);
  text-decoration: none; color: var(--ink);
}
[data-theme-layout="triptych"] .tp-row-t {
  font-family: var(--serif); font-weight: 700; font-size: .98rem; line-height: 1.32;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="triptych"] .tp-row:hover .tp-row-t { color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
[data-theme-layout="triptych"] .tp-row-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .82rem; line-height: 1.5; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="triptych"] .tp-row-d { font-size: .7rem; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
[data-theme-layout="triptych"] .tp-row-cat { flex-direction: row; align-items: baseline; justify-content: space-between; gap: .6rem; }
[data-theme-layout="triptych"] .tp-row-n { flex: 0 0 auto; font-size: .74rem; color: var(--muted); font-variant-numeric: tabular-nums; }
[data-theme-layout="triptych"] .tp-wing-all {
  margin-top: .9rem; align-self: flex-start;
  display: inline-flex; align-items: center; gap: .35rem;
  font-size: .74rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: var(--accent); text-decoration: none; transition: color .15s;
}
[data-theme-layout="triptych"] .tp-wing-all:hover { color: var(--accent-soft); }

/* ---- colophon: 底部居中落款条（双细线呼应楣梁底边） ----------------------- */
[data-theme-layout="triptych"] .tp-colophon {
  display: flex; justify-content: center; align-items: baseline; gap: .8rem;
  margin-top: clamp(2rem, 5vw, 3.2rem); padding-top: .9rem;
  border-top: 5px double var(--line);
  font-size: .9rem; color: var(--muted);
}
[data-theme-layout="triptych"] .tp-colophon a { color: var(--ink-soft); text-decoration: none; transition: color .15s; }
[data-theme-layout="triptych"] .tp-colophon a:hover { color: var(--accent); }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  /* 三联纵排：DOM 顺序中央在前；显式列位全部放开（含稀疏修饰组合） */
  [data-theme-layout="triptych"] .tp-altar,
  [data-theme-layout="triptych"] .tp-altar.tp-noleft,
  [data-theme-layout="triptych"] .tp-altar.tp-noright { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="triptych"] .tp-altar .tp-apse,
  [data-theme-layout="triptych"] .tp-altar .tp-wing-l,
  [data-theme-layout="triptych"] .tp-altar .tp-wing-r,
  [data-theme-layout="triptych"] .tp-altar.tp-noleft .tp-apse,
  [data-theme-layout="triptych"] .tp-altar.tp-noleft .tp-wing-r { grid-column: auto; grid-row: auto; }
  [data-theme-layout="triptych"] .tp-apse { max-width: 620px; width: 100%; margin-inline: auto; }
}
@media (max-width: 720px) {
  [data-theme-layout="triptych"] .tp-apse { --tp-arch: clamp(100px, 24vw, 150px); --tp-pad-t: 2.2rem; --tp-pad-x: 1.15rem; --tp-pad-b: 1.4rem; }
  [data-theme-layout="triptych"] .tp-apse-ex { -webkit-line-clamp: 3; }
  [data-theme-layout="triptych"] .tp-colophon { flex-wrap: wrap; }
}
@media (max-width: 620px) {
  /* 楣梁交回默认抽屉导航：brand 左、menu-toggle 右 */
  [data-theme-layout="triptych"] .site-header { padding-inline: 16px; }
  [data-theme-layout="triptych"] .site-header .wrap { justify-content: space-between; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="triptych"] .tp-apse,
  [data-theme-layout="triptych"] .tp-apse-h,
  [data-theme-layout="triptych"] .tp-enter,
  [data-theme-layout="triptych"] .tp-row-t,
  [data-theme-layout="triptych"] .tp-wing-all,
  [data-theme-layout="triptych"] .tp-colophon a { transition: none; }
  [data-theme-layout="triptych"] .tp-apse:hover { transform: none; }
}

/* ============================================================
   三联 · Triptych —— Triptych 骨架默认皮：暖灰白祭坛、橄榄褐饰线、古铜拱
   ============================================================ */
:root[data-theme="triptych"] {
  --bg: #f3f1ea; --surface: #fbfaf5;
  --ink: #26231b; --ink-soft: #464235; --muted: #6b6555; --faint: #8f8867;
  --line: #d9d4c4; --line-soft: #e8e4d6;
  --accent: #7a5c2e; --accent-soft: #5e4620; --accent-wash: #efe8d8;
  --w-wide: 1200px; --radius: 14px;
  --shadow: 0 1px 2px rgba(38, 35, 27, .05), 0 12px 28px rgba(38, 35, 27, .08);
}
:root[data-theme="triptych"] .btn-primary { color: #fff; }

/* ============================================================
   夜厅 · Nighthall —— Triptych 骨架反差皮：炭黑展厅、暖白字、橄榄金拱框
   ============================================================ */
:root[data-theme="nighthall"] {
  --bg: #141310; --surface: #1d1b16;
  --ink: #f2ede1; --ink-soft: #d6d0bf; --muted: #a9a290; --faint: #736c5b;
  --line: #38342a; --line-soft: #2a2721;
  --accent: #c8a04e; --accent-soft: #dfc07a; --accent-wash: #2a2417;
  --w-wide: 1200px; --radius: 14px; --code-bg: #0c0b09;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 12px 30px rgba(0, 0, 0, .5);
}
:root[data-theme="nighthall"] .btn-primary { color: #141310; }
/* 橄榄金拱框：拱卡边线与外圈拱框染金 */
:root[data-theme="nighthall"] .tp-apse {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line));
  box-shadow: 0 0 0 4px var(--bg), 0 0 0 5px color-mix(in srgb, var(--accent) 40%, var(--bg)), var(--shadow);
}
:root[data-theme="nighthall"] .tp-apse-seal { border-color: color-mix(in srgb, var(--accent) 45%, var(--line)); }
:root[data-theme="nighthall"] .site-header .wrap { border-bottom-color: var(--accent); }

/* ============================================================
   三联纯白 · Triptych White —— Triptych 骨架纯白皮：中性灰基底（对齐
   answer-desk-white），古铜 accent 白底实算 6.18:1；拱卡改走 --bg，
   保证卡上 muted 小字 ≥4.5（#707680/#ffffff = 4.57）
   ============================================================ */
:root[data-theme="triptych-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #707680; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #7a5c2e; --accent-soft: #5e4620; --accent-wash: #f6efe2;
  --w-wide: 1200px; --radius: 14px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .04), 0 10px 24px rgba(16, 18, 24, .06);
}
:root[data-theme="triptych-white"] .btn-primary { color: #fff; }
:root[data-theme="triptych-white"] .tp-apse { background: var(--bg); }

/* =========================================================================
   LAYOUT: stubs — 票根 torn ticket-stub rows (pure CSS, no JS)
   every selector scoped under [data-theme-layout="stubs"], classes stb-*
   标准页头 CSS 重塑为居中影院刊头(≤620px 交还基础汉堡抽屉)；home：
   HeroEyebrow 当 ADMIT 小字行+灯泡点行 /「排」索引 / 放大版精选票(accent 描边)
   / 加映场小票胶囊 / No.NNN 三段票列：左票号段(counter+分类当排)·中段标题
   ·右段等宽日期+条码；段间打孔虚线+上下半圆缺口(伪元素圆片同底色)，
   缺口只贴票边不占文字车道，720px 三段归位上中下普通流并收起圆片
