[data-theme-layout="stubs"] .stb-extra:hover { border-color: var(--accent); }
[data-theme-layout="stubs"] .stb-extra-ic {
  flex: 0 0 auto; width: 30px; height: 30px; overflow: hidden;
  display: grid; place-items: center; border-radius: 50%;
  background: var(--accent-wash); color: var(--accent-soft);
}
[data-theme-layout="stubs"] .stb-extra-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="stubs"] .stb-extra-ic b { font-size: .85rem; font-weight: 800; line-height: 1; }
[data-theme-layout="stubs"] .stb-extra-t {
  min-width: 0; font-size: .88rem; font-weight: 700; line-height: 1.3;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="stubs"] .stb-extra:hover .stb-extra-t { color: var(--accent); }

/* ---- latest: No.NNN 三段撕边票列 ----------------------------------------- */
[data-theme-layout="stubs"] .stb-list { display: flex; flex-direction: column; gap: .85rem; counter-reset: stb-tk; }
[data-theme-layout="stubs"] .stb-ticket {
  counter-increment: stb-tk; position: relative;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: var(--shadow); transition: border-color .15s;
}
[data-theme-layout="stubs"] .stb-ticket:hover { border-color: var(--accent); }
[data-theme-layout="stubs"] .stb-ticket-in {
  display: grid; align-items: stretch; min-width: 0;
  grid-template-columns: clamp(96px, 12vw, 124px) minmax(0, 1fr) clamp(112px, 14vw, 140px);
  text-decoration: none; color: var(--ink);
}
/* 左票号段：counter 票号 + 分类当「排」；右缘打孔虚线 */
[data-theme-layout="stubs"] .stb-no {
  position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: .3rem; min-width: 0; padding: .9rem .5rem; text-align: center;
  border-right: 1px dashed var(--line);
}
[data-theme-layout="stubs"] .stb-no-num {
  font-family: var(--mono); font-size: .78rem; letter-spacing: .06em;
  font-variant-numeric: tabular-nums; color: var(--accent);
}
[data-theme-layout="stubs"] .stb-no-num::before { content: "No.0" counter(stb-tk, decimal-leading-zero); }
[data-theme-layout="stubs"] .stb-no-row {
  min-width: 0; font-size: .64rem; font-weight: 700; letter-spacing: .12em;
  text-transform: uppercase; color: var(--muted); overflow-wrap: anywhere;
}
/* 打孔缺口：伪元素圆片同底色，钉在两条虚线上下端，票边之外不占文字车道 */
[data-theme-layout="stubs"] .stb-no::before,
[data-theme-layout="stubs"] .stb-no::after,
[data-theme-layout="stubs"] .stb-tail::before,
[data-theme-layout="stubs"] .stb-tail::after {
  content: ""; position: absolute; width: 14px; height: 14px;
  border-radius: 50%; background: var(--bg);
}
[data-theme-layout="stubs"] .stb-no::before { top: -8px; right: -7px; }
[data-theme-layout="stubs"] .stb-no::after { bottom: -8px; right: -7px; }
[data-theme-layout="stubs"] .stb-tail::before { top: -8px; left: -7px; }
[data-theme-layout="stubs"] .stb-tail::after { bottom: -8px; left: -7px; }
/* 中段：标题 + 摘要 */
[data-theme-layout="stubs"] .stb-mid {
  display: flex; flex-direction: column; justify-content: center; gap: .3rem;
  min-width: 0; padding: .85rem clamp(.9rem, 2.4vw, 1.4rem);
}
[data-theme-layout="stubs"] .stb-t { font-size: 1.06rem; font-weight: 700; line-height: 1.35; overflow-wrap: anywhere; transition: color .15s; }
[data-theme-layout="stubs"] .stb-ticket-in:hover .stb-t { color: var(--accent); }
[data-theme-layout="stubs"] .stb-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .86rem; line-height: 1.55; color: var(--muted); overflow-wrap: anywhere;
}
/* 右段：等宽日期 + 条码；左缘打孔虚线 */
[data-theme-layout="stubs"] .stb-tail {
  position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: .45rem; min-width: 0; padding: .85rem .6rem; text-align: center;
  border-left: 1px dashed var(--line);
}
[data-theme-layout="stubs"] .stb-date {
  font-family: var(--mono); font-size: .72rem; letter-spacing: .03em;
  font-variant-numeric: tabular-nums; color: var(--muted);
}
[data-theme-layout="stubs"] .stb-tail .stb-bar { width: min(100%, 84px); height: 22px; }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="stubs"] .stb-lead { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="stubs"] .stb-lead-tail {
    flex-direction: row; flex-wrap: wrap; justify-content: space-between; text-align: left;
    border-left: 0; border-top: 1px dashed var(--accent);
  }
  [data-theme-layout="stubs"] .stb-lead-tail::before,
  [data-theme-layout="stubs"] .stb-lead-tail::after { display: none; }
  [data-theme-layout="stubs"] .stb-ticket-in { grid-template-columns: clamp(84px, 11vw, 104px) minmax(0, 1fr) clamp(96px, 13vw, 116px); }
}
@media (max-width: 720px) {
  [data-theme-layout="stubs"] .stb-title { font-size: clamp(1.7rem, 8vw, 2.4rem); }
  [data-theme-layout="stubs"] .stb-admit span { letter-spacing: .22em; text-indent: .22em; }
  [data-theme-layout="stubs"] .stb-row { padding: .15rem .7rem; }
  /* 票根归位普通流：三段改上中下，孔位圆片全部收起 */
  [data-theme-layout="stubs"] .stb-ticket-in { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="stubs"] .stb-no {
    flex-direction: row; justify-content: space-between; text-align: left;
    padding: .55rem .95rem; border-right: 0; border-bottom: 1px dashed var(--line);
  }
  [data-theme-layout="stubs"] .stb-tail {
    flex-direction: row; justify-content: space-between; text-align: left;
    padding: .55rem .95rem; border-left: 0; border-top: 1px dashed var(--line);
  }
  [data-theme-layout="stubs"] .stb-no::before,
  [data-theme-layout="stubs"] .stb-no::after,
  [data-theme-layout="stubs"] .stb-tail::before,
  [data-theme-layout="stubs"] .stb-tail::after { display: none; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="stubs"] .stb-row,
  [data-theme-layout="stubs"] .stb-lead-t,
  [data-theme-layout="stubs"] .stb-lead-more,
  [data-theme-layout="stubs"] .stb-head-all,
  [data-theme-layout="stubs"] .stb-extra,
  [data-theme-layout="stubs"] .stb-extra-t,
  [data-theme-layout="stubs"] .stb-ticket,
  [data-theme-layout="stubs"] .stb-t { transition: none; }
}

/* ============================================================
   票根 · Stubs —— Stubs 骨架默认皮：米纸、票纸、朱红
   实算：ink 14.65/16.37，ink-soft 8.46/9.45，muted 5.29/5.92，
   朱红作字 5.45/6.09（hover soft 7.77/8.68 只升不降），
   徽章白字压朱红 6.20，胶囊首字 soft 压 wash 7.10
   ============================================================ */
:root[data-theme="stubs"] {
  --bg: #f5f0e4; --surface: #fffdf6;
  --ink: #241d13; --ink-soft: #4c4434; --muted: #6b6250; --faint: #99917c;
  --line: #ddd3ba; --line-soft: #ebe4d1;
  --accent: #b2331f; --accent-soft: #8e2113; --accent-wash: #f6e3d6;
  --w-wide: 1100px; --radius: 10px;
  --shadow: 0 1px 2px rgba(36, 29, 19, .05), 0 10px 26px rgba(36, 29, 19, .08);
}
:root[data-theme="stubs"] .site-header { background: var(--bg); }
:root[data-theme="stubs"] .btn-primary { color: #fff; }

/* ============================================================
   午夜场 · Nightshow —— Stubs 骨架 + 深夜蓝黑荧光橙反差皮
   实算：ink 16.70/15.06，ink-soft 12.61/11.37，muted 7.51/6.77，
   荧光橙作字 9.00/8.11（hover soft 10.61/9.57 只升不降），
   徽章近黑字压橙 8.79，胶囊首字 soft 压 wash 9.21
   ============================================================ */
:root[data-theme="nightshow"] {
  --bg: #0d1020; --surface: #161b30;
  --ink: #eef1f8; --ink-soft: #ccd3e6; --muted: #9aa3bd; --faint: #6a7391;
  --line: #2c3352; --line-soft: #1e2440;
  --accent: #ff9b3d; --accent-soft: #ffb264; --accent-wash: #2a1d10;
  --w-wide: 1100px; --radius: 10px; --code-bg: #080b18;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 12px 30px rgba(0, 0, 0, .5);
}
:root[data-theme="nightshow"] .site-header { background: rgba(13, 16, 32, .92); }
:root[data-theme="nightshow"] .btn-primary { color: #1c1206; }
/* 荧光橙票字：精选徽章反转为橙底近黑字（8.79，白字在橙上不达标故必须覆写） */
:root[data-theme="nightshow"] .stb-kicker b { color: #1c1206; }

/* ============================================================
   票根纯白 · Stubs White —— 第五批纯白系：中性灰基底照抄纯白段，
   朱红族色白底实算 6.20（hover soft 8.96 只升不降，徽章白字 6.20，
   胶囊首字 soft 压 wash 7.65）；muted #707680 落 #fafaf8 只有 4.38
   ——精选票/票卡/胶囊底一律改回 --bg 纯白（muted 4.57 达标）
   ============================================================ */
:root[data-theme="stubs-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #707680; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #b2331f; --accent-soft: #8a2415; --accent-wash: #f9eae5;
  --w-wide: 1100px; --radius: 10px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .04), 0 10px 26px rgba(16, 18, 24, .07);
}
:root[data-theme="stubs-white"] .btn-primary { color: #fff; }
:root[data-theme="stubs-white"] .stb-lead,
:root[data-theme="stubs-white"] .stb-ticket,
:root[data-theme="stubs-white"] .stb-extra { background: var(--bg); }

/* =========================================================================
   LAYOUT: cardfile — 目录柜 card-catalog home (pure CSS, no JS)
   every selector scoped under [data-theme-layout="cardfile"], classes cdf-*
   标准页头 CSS 重塑为柜面木纹横条（重塑段全包 min-width:621px，
   ≤620px 交还基础汉堡抽屉）；home：木纹抽屉墙（铭牌 hero + Categories=
   抽屉卡：纸标签框+Count+黄铜拉手胶囊）→ 桌面浅色大板（Featured=放大首卡、
   Posts=打字机索引卡：卡号行→红横线 ::before→标题→底部穿孔圆，
   FeatLinks=借阅签）→ colophon。木纹/铁色只当外框区底色，正文卡面恒浅色；
   卡内元素全走 flex order 排布，零绝对定位、零竖排长文。
   ========================================================================= */
[data-theme-layout="cardfile"] main { display: block; }
[data-theme-layout="cardfile"] .cdf-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-block: clamp(1.4rem, 3.5vw, 2.4rem) clamp(3rem, 6vw, 5rem);
}
/* 外框/卡面配色兜底＝原生皮取值；三张皮在 :root[data-theme=…] 覆写（特异度更高） */
[data-theme-layout="cardfile"] {
  --cdf-wood: #6d4c33; --cdf-wood-hi: #7f5a3e; --cdf-wood-lo: #563823;
  --cdf-plate: #543823;
  --cdf-frame-ink: #f9efdc; --cdf-frame-soft: #eeddbc; --cdf-frame-accent: #ecc98d;
  --cdf-frame-hover: #ffffff;
  --cdf-brass-hi: #ecc98d; --cdf-brass: #c69c5d; --cdf-brass-lo: #8a6531;
  --cdf-label-frame: #c69c5d; --cdf-label-edge: #8a6531;
  --cdf-card: #fffbec; --cdf-card-line: #e5d8b1;
  --cdf-card-ink: #2b2011; --cdf-card-muted: #6b5a41;
  --cdf-card-accent: #a2381f; --cdf-card-hover: #140d04;
  --cdf-rule: #c23a24;
  --cdf-desk: #f8f1de; --cdf-desk-line: #dccda6;
}

/* ---- shared chrome: standard header recast as cabinet-face wood strip ----
   全部重塑收进 ≥621px；小屏零覆写，基础汉堡抽屉原样接管 */
@media (min-width: 621px) {
  [data-theme-layout="cardfile"] .site-header {
    background:
      repeating-linear-gradient(180deg, transparent 0 5px, rgba(0, 0, 0, .07) 5px 6px, transparent 6px 13px),
      linear-gradient(180deg, var(--cdf-wood-hi), var(--cdf-wood) 55%, var(--cdf-wood-lo));
    -webkit-backdrop-filter: none; backdrop-filter: none;
    border-bottom: 3px solid var(--cdf-brass-lo);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, .12);
  }
  [data-theme-layout="cardfile"] .site-header .brand {
    color: var(--cdf-frame-ink);
    font-family: var(--mono); font-size: 1.06rem; letter-spacing: .1em; text-transform: uppercase;
  }
  [data-theme-layout="cardfile"] .site-header .brand .dot { color: var(--cdf-frame-accent); }
  [data-theme-layout="cardfile"] .site-header .nav a {
    color: var(--cdf-frame-soft);
    font-family: var(--mono); font-size: .85rem; letter-spacing: .05em;
  }
  [data-theme-layout="cardfile"] .site-header .nav a:hover {
    color: var(--cdf-frame-hover);
    text-decoration: underline; text-underline-offset: 4px;
  }
  [data-theme-layout="cardfile"] .site-header .nav a[aria-current="page"] { color: var(--cdf-frame-ink); }
  [data-theme-layout="cardfile"] .site-header .nav a[aria-current="page"]::after { background: var(--cdf-brass-hi); }
}

/* ---- cabinet: wood wall holding the brass-edged name plate + drawers ---- */
[data-theme-layout="cardfile"] .cdf-cabinet {
  background:
    repeating-linear-gradient(180deg, transparent 0 6px, rgba(0, 0, 0, .05) 6px 7px, transparent 7px 16px),
    linear-gradient(180deg, var(--cdf-wood-hi), var(--cdf-wood) 55%, var(--cdf-wood-lo));
  border: 1px solid var(--cdf-wood-lo);
  border-radius: 10px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .12), var(--shadow);
  padding: clamp(1.1rem, 3vw, 2rem);
}
[data-theme-layout="cardfile"] .cdf-plate {
  width: min(100%, 760px); margin-inline: auto;
  background: var(--cdf-plate);
  border: 1px solid var(--cdf-label-edge);
  box-shadow: 0 0 0 3px var(--cdf-label-frame), inset 0 1px 0 rgba(255, 255, 255, .08);
  border-radius: 4px;
  padding: clamp(1rem, 2.6vw, 1.7rem) clamp(1rem, 3vw, 2rem);
  text-align: center;
}
[data-theme-layout="cardfile"] .cdf-eyebrow {
  margin: 0 0 .55rem; font-family: var(--mono); font-size: .72rem;
  letter-spacing: .3em; text-indent: .3em; text-transform: uppercase;
  color: var(--cdf-frame-accent); overflow-wrap: anywhere;
}
[data-theme-layout="cardfile"] .cdf-title {
  margin: 0; font-family: var(--mono); font-weight: 700;
  font-size: clamp(1.7rem, 4.2vw, 2.7rem); line-height: 1.14; letter-spacing: .01em;
  color: var(--cdf-frame-ink); overflow-wrap: anywhere;
}
[data-theme-layout="cardfile"] .cdf-lede {
  margin: .6rem auto 0; max-width: 58ch;
  font-size: .95rem; line-height: 1.6; color: var(--cdf-frame-soft); overflow-wrap: anywhere;
}

/* ---- drawer wall: Categories as drawer fronts -------------------------- */
[data-theme-layout="cardfile"] .cdf-drawers {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 10px; margin-top: clamp(1rem, 2.6vw, 1.6rem);
  padding-top: clamp(1rem, 2.6vw, 1.5rem);
  border-top: 1px solid rgba(0, 0, 0, .22);
}
[data-theme-layout="cardfile"] .cdf-drawer {
  display: flex; flex-direction: column; align-items: center; gap: .65rem;
  min-width: 0; padding: .85rem .7rem .75rem;
  background: linear-gradient(180deg, var(--cdf-wood-hi), var(--cdf-wood) 60%, var(--cdf-wood-lo));
  border: 1px solid var(--cdf-wood-lo); border-radius: 6px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .14), 0 2px 6px rgba(0, 0, 0, .18);
  text-decoration: none;
  transition: transform .15s ease, box-shadow .15s ease;
}
[data-theme-layout="cardfile"] .cdf-drawer:hover {
  transform: translateY(3px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .14), 0 6px 14px rgba(0, 0, 0, .24);
}
[data-theme-layout="cardfile"] .cdf-label {
  display: flex; align-items: baseline; justify-content: center; gap: .45rem;
  width: 100%; min-width: 0; padding: .36rem .5rem;
  background: var(--cdf-card); color: var(--cdf-card-ink);
  border: 1px solid var(--cdf-label-edge); border-radius: 3px;
  box-shadow: 0 0 0 2px var(--cdf-label-frame);
  font-family: var(--mono); font-size: .82rem; font-weight: 700; text-align: center;
}
[data-theme-layout="cardfile"] .cdf-label-name { overflow-wrap: anywhere; }
[data-theme-layout="cardfile"] .cdf-label-n { flex: 0 0 auto; font-size: .68rem; font-weight: 400; color: var(--cdf-card-muted); }
[data-theme-layout="cardfile"] .cdf-drawer-all .cdf-label-name { color: var(--cdf-card-accent); }
[data-theme-layout="cardfile"] .cdf-pull {
  width: 62px; max-width: 70%; height: 13px; border-radius: 999px;
  background: linear-gradient(180deg, var(--cdf-brass-hi), var(--cdf-brass) 45%, var(--cdf-brass-lo));
  box-shadow: 0 1px 2px rgba(0, 0, 0, .35), inset 0 1px 1px rgba(255, 255, 255, .4), inset 0 -2px 3px rgba(0, 0, 0, .25);
}

/* ---- desk: light board holding the pulled index cards ------------------- */
[data-theme-layout="cardfile"] .cdf-desk {
  margin-top: clamp(1.3rem, 3vw, 2rem);
  background: var(--cdf-desk);
  border: 1px solid var(--cdf-desk-line); border-radius: 12px;
  padding: clamp(1rem, 2.6vw, 1.7rem);
}
[data-theme-layout="cardfile"] .cdf-card {
  min-width: 0; background: var(--cdf-card);
  border: 1px solid var(--cdf-card-line); border-radius: 4px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, .08), 0 6px 16px rgba(0, 0, 0, .08);
}
/* 索引卡内容轴：卡号行 → 红横线 ::before → 标题 → 封面/摘要 → 穿孔圆 */
[data-theme-layout="cardfile"] .cdf-lead,
[data-theme-layout="cardfile"] .cdf-card-in {
  display: flex; flex-direction: column; gap: .5rem; min-width: 0; height: 100%;
  color: var(--cdf-card-ink); text-decoration: none;
}
[data-theme-layout="cardfile"] .cdf-lead { padding: clamp(1rem, 2.6vw, 1.5rem); }
[data-theme-layout="cardfile"] .cdf-card-in { padding: .95rem 1rem 1rem; }
[data-theme-layout="cardfile"] .cdf-lead::before,
[data-theme-layout="cardfile"] .cdf-card-in::before {
  content: ""; order: 2; height: 2px; margin-top: .1rem;
  background: var(--cdf-rule);
}
[data-theme-layout="cardfile"] .cdf-no {
  order: 1; display: flex; flex-wrap: wrap; align-items: baseline; gap: .45rem;
  min-width: 0; font-family: var(--mono); font-size: .72rem; letter-spacing: .06em;
  text-transform: uppercase; color: var(--cdf-card-muted); overflow-wrap: anywhere;
}
[data-theme-layout="cardfile"] .cdf-stamp { color: var(--cdf-card-accent); font-weight: 700; }
[data-theme-layout="cardfile"] .cdf-card-t {
  order: 3; font-family: var(--mono); font-weight: 700;
  font-size: 1.02rem; line-height: 1.35; overflow-wrap: anywhere;
  transition: color .15s;
}
[data-theme-layout="cardfile"] .cdf-lead .cdf-card-t { font-size: clamp(1.3rem, 3vw, 1.85rem); line-height: 1.22; }
[data-theme-layout="cardfile"] .cdf-lead:hover .cdf-card-t,
[data-theme-layout="cardfile"] .cdf-card-in:hover .cdf-card-t {
  color: var(--cdf-card-hover);
  text-decoration: underline; text-decoration-thickness: 1.5px; text-underline-offset: 3px;
}
[data-theme-layout="cardfile"] .cdf-lead-cover {
  order: 4; display: block; overflow: hidden;
  border: 1px solid var(--cdf-card-line); border-radius: 3px;
}
[data-theme-layout="cardfile"] .cdf-lead-cover img { display: block; width: 100%; height: auto; max-height: 340px; object-fit: cover; }
[data-theme-layout="cardfile"] .cdf-card-ex {
  order: 5; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .88rem; line-height: 1.55; color: var(--cdf-card-muted); overflow-wrap: anywhere;
}
[data-theme-layout="cardfile"] .cdf-lead .cdf-card-ex { font-size: .95rem; max-width: 72ch; }
[data-theme-layout="cardfile"] .cdf-more {
  order: 6; display: inline-flex; align-items: center; gap: .35rem; align-self: flex-start;
  font-family: var(--mono); font-size: .74rem; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase; color: var(--cdf-card-accent);
}
[data-theme-layout="cardfile"] .cdf-lead:hover .cdf-more { text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="cardfile"] .cdf-hole {
  order: 7; flex: 0 0 auto; align-self: center; margin-top: auto;
  width: 15px; height: 15px; border-radius: 50%;
  background: var(--cdf-desk); border: 1px solid var(--cdf-card-line);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .18);
}

/* ---- desk heads: paper chips (desk 大板上不落裸字，字全在纸片上) --------- */
[data-theme-layout="cardfile"] .cdf-desk-head {
  display: flex; justify-content: space-between; align-items: center; gap: .8rem;
  margin: clamp(1.1rem, 2.8vw, 1.6rem) 0 .9rem;
}
[data-theme-layout="cardfile"] .cdf-desk-head:first-child { margin-top: 0; }
[data-theme-layout="cardfile"] .cdf-chip {
  display: inline-flex; align-items: baseline; gap: .35rem; min-width: 0; margin: 0;
  padding: .4rem .7rem;
  background: var(--cdf-card); color: var(--cdf-card-ink);
  border: 1px solid var(--cdf-card-line); border-radius: 3px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, .08);
  font-family: var(--mono); font-size: .74rem; font-weight: 700;
  letter-spacing: .14em; text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="cardfile"] .cdf-chip-all {
  flex: 0 0 auto; color: var(--cdf-card-accent); text-decoration: none; transition: color .15s;
}
[data-theme-layout="cardfile"] .cdf-chip-all:hover { color: var(--cdf-card-hover); }
[data-theme-layout="cardfile"] .cdf-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 14px;
}
[data-theme-layout="cardfile"] .cdf-grid .cdf-card { display: flex; }
[data-theme-layout="cardfile"] .cdf-grid .cdf-card-in { flex: 1; }

/* ---- FeatLinks: lending-slip tabs --------------------------------------- */
[data-theme-layout="cardfile"] .cdf-tabs { margin-top: clamp(1.1rem, 2.8vw, 1.6rem); }
[data-theme-layout="cardfile"] .cdf-tabs .cdf-chip { margin: 0 0 .9rem; }
[data-theme-layout="cardfile"] .cdf-tab-row {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 12px;
}
[data-theme-layout="cardfile"] .cdf-tab {
  display: flex; align-items: flex-start; gap: .6rem; min-width: 0;
  padding: .7rem .75rem;
  background: var(--cdf-card); color: var(--cdf-card-ink);
  border: 1px solid var(--cdf-card-line); border-radius: 4px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, .08);
  text-decoration: none;
}
[data-theme-layout="cardfile"] .cdf-tab-ic {
  flex: 0 0 auto; width: 36px; height: 36px; overflow: hidden;
  display: grid; place-items: center; border-radius: 3px;
  background: var(--cdf-brass); color: var(--cdf-card-ink);
}
[data-theme-layout="cardfile"] .cdf-tab-ic b { font-family: var(--mono); font-weight: 700; font-size: 1rem; line-height: 1; }
[data-theme-layout="cardfile"] .cdf-tab-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="cardfile"] .cdf-tab-body { min-width: 0; }
[data-theme-layout="cardfile"] .cdf-tab-t {
  display: block; font-family: var(--mono); font-weight: 700;
  font-size: .88rem; line-height: 1.35; overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="cardfile"] .cdf-tab:hover .cdf-tab-t {
  color: var(--cdf-card-hover); text-decoration: underline; text-underline-offset: 3px;
}
[data-theme-layout="cardfile"] .cdf-tab-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  margin-top: .15rem; font-size: .78rem; line-height: 1.45; color: var(--cdf-card-muted); overflow-wrap: anywhere;
}

/* ---- colophon ------------------------------------------------------------ */
[data-theme-layout="cardfile"] .cdf-colophon {
  display: flex; justify-content: center; align-items: baseline; gap: .8rem;
  margin-top: clamp(1.6rem, 4vw, 2.4rem); padding-top: .9rem;
  border-top: 1px solid var(--line);
  font-family: var(--mono); font-size: .85rem; letter-spacing: .05em; color: var(--muted);
}
[data-theme-layout="cardfile"] .cdf-colophon a { color: var(--ink-soft); text-decoration: none; transition: color .15s; }
[data-theme-layout="cardfile"] .cdf-colophon a:hover { color: var(--ink); }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="cardfile"] .cdf-drawers { grid-template-columns: repeat(auto-fill, minmax(132px, 1fr)); }
  [data-theme-layout="cardfile"] .cdf-grid { grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); }
  [data-theme-layout="cardfile"] .cdf-lead-cover img { max-height: 300px; }
}
@media (max-width: 720px) {
  [data-theme-layout="cardfile"] .cdf-title { font-size: clamp(1.45rem, 6.5vw, 1.9rem); }
  [data-theme-layout="cardfile"] .cdf-plate { padding: .9rem .85rem; }
  [data-theme-layout="cardfile"] .cdf-drawers { grid-template-columns: repeat(auto-fill, minmax(124px, 1fr)); gap: 8px; }
  [data-theme-layout="cardfile"] .cdf-desk-head { flex-wrap: wrap; }
  [data-theme-layout="cardfile"] .cdf-grid,
  [data-theme-layout="cardfile"] .cdf-tab-row { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="cardfile"] .cdf-lead-cover img { max-height: 240px; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="cardfile"] .cdf-drawer,
  [data-theme-layout="cardfile"] .cdf-card-t,
  [data-theme-layout="cardfile"] .cdf-chip-all,
  [data-theme-layout="cardfile"] .cdf-tab-t,
  [data-theme-layout="cardfile"] .cdf-colophon a { transition: none; }
  [data-theme-layout="cardfile"] .cdf-drawer:hover { transform: none; }
}

/* ============================================================
   目录柜 · Cardfile —— Cardfile 骨架默认皮：橡木暖棕柜身、
   象牙卡纸、黄铜五金、索引红线（铭牌深木底承 hero 文字）
   ============================================================ */
:root[data-theme="cardfile"] {
  --bg: #eee3cb; --surface: #f8f1de;
  --ink: #26190b; --ink-soft: #4c3d28; --muted: #675640; --faint: #92805f;
  --line: #d6c5a0; --line-soft: #e4d6b6;
  --accent: #7c5313; --accent-soft: #5e3e0d; --accent-wash: #f0e2c1;
  --w-wide: 1200px; --radius: 8px;
  --shadow: 0 1px 2px rgba(38, 25, 11, .06), 0 10px 26px rgba(38, 25, 11, .1);
  --cdf-wood: #6d4c33; --cdf-wood-hi: #7f5a3e; --cdf-wood-lo: #563823;
  --cdf-plate: #543823;
  --cdf-frame-ink: #f9efdc; --cdf-frame-soft: #eeddbc; --cdf-frame-accent: #ecc98d;
  --cdf-frame-hover: #ffffff;
  --cdf-brass-hi: #ecc98d; --cdf-brass: #c69c5d; --cdf-brass-lo: #8a6531;
  --cdf-label-frame: #c69c5d; --cdf-label-edge: #8a6531;
  --cdf-card: #fffbec; --cdf-card-line: #e5d8b1;
  --cdf-card-ink: #2b2011; --cdf-card-muted: #6b5a41;
  --cdf-card-accent: #a2381f; --cdf-card-hover: #140d04;
  --cdf-rule: #c23a24;
  --cdf-desk: #f8f1de; --cdf-desk-line: #dccda6;
}
:root[data-theme="cardfile"] .btn-primary { color: #fff; }

/* ============================================================
   铁柜 · Steelcab —— Cardfile 骨架 + 军绿灰铁柜反差皮：
   铁灰绿柜身、米色卡纸、钢制拉手、锈红标签框与卡号
   ============================================================ */
:root[data-theme="steelcab"] {
  --bg: #272d24; --surface: #323931;
  --ink: #ece6d0; --ink-soft: #cfc8ad; --muted: #a8a189; --faint: #7d7660;
  --line: #4a5142; --line-soft: #3a4136;
  --accent: #e28a63; --accent-soft: #efa886; --accent-wash: #43291d;
  --w-wide: 1200px; --radius: 8px; --code-bg: #1b201a;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 12px 30px rgba(0, 0, 0, .45);
  --cdf-wood: #3c4436; --cdf-wood-hi: #4a5445; --cdf-wood-lo: #2c3328;
  --cdf-plate: #313830;
  --cdf-frame-ink: #eee8d2; --cdf-frame-soft: #ccc5a9; --cdf-frame-accent: #efa886;
  --cdf-frame-hover: #ffffff;
  --cdf-brass-hi: #d3d9d0; --cdf-brass: #a3aca0; --cdf-brass-lo: #6b756c;
  --cdf-label-frame: #96351e; --cdf-label-edge: #7c2b17;
  --cdf-card: #f2ecd6; --cdf-card-line: #d9d2b4;
  --cdf-card-ink: #24251c; --cdf-card-muted: #5e5d48;
  --cdf-card-accent: #96351e; --cdf-card-hover: #101107;
  --cdf-rule: #a03a22;
  --cdf-desk: #454f3e; --cdf-desk-line: #566149;
}
:root[data-theme="steelcab"] .btn-primary { color: #2f130a; }

/* ============================================================
   目录柜纯白 · Cardfile White —— 第五批纯白系：中性灰基底照抄
   纯白段；柜身褪成浅灰白漆面，黄铜压深为暗铜金 #7c5a14
   （白底 6.31，hover soft #61460e 8.78 只升不降）；muted #707680
   只落纯白卡面（4.57），desk #fafaf8 上零裸字（字全在白纸片上）
   ============================================================ */
:root[data-theme="cardfile-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #707680; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #7c5a14; --accent-soft: #61460e; --accent-wash: #f5eedd;
  --w-wide: 1200px; --radius: 8px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .04), 0 10px 26px rgba(16, 18, 24, .07);
  --cdf-wood: #f1f2f0; --cdf-wood-hi: #f7f7f5; --cdf-wood-lo: #e7e8e5;
  --cdf-plate: #ffffff;
  --cdf-frame-ink: #101218; --cdf-frame-soft: #3f444d; --cdf-frame-accent: #7c5a14;
  --cdf-frame-hover: #000000;
  --cdf-brass-hi: #c8a76e; --cdf-brass: #b3905c; --cdf-brass-lo: #8a6c3c;
  --cdf-label-frame: #d7d9dd; --cdf-label-edge: #b3905c;
  --cdf-card: #ffffff; --cdf-card-line: #d7d9dd;
  --cdf-card-ink: #101218; --cdf-card-muted: #707680;
  --cdf-card-accent: #7c5a14; --cdf-card-hover: #000000;
  --cdf-rule: #c23a24;
  --cdf-desk: #fafaf8; --cdf-desk-line: #d7d9dd;
}
:root[data-theme="cardfile-white"] .btn-primary { color: #fff; }

/* =========================================================================
   LAYOUT: script — 剧本 screenplay page (pure CSS, no JS)
   every selector scoped under [data-theme-layout="script"], classes scp-*
   整页居中窄栏(~640px)等宽排版：场景行(INT. 装饰 + HeroEyebrow + 右侧稿号
   胶囊「HomeLatest · N」) / 居中片名标题页 / V.O. 旁白段(Featured：角色名=
   HomeFeatured + 衬线居中对白 + 括注) / SCENE NN 条目(CSS counter) /
   片尾字幕两列(FeatLinks) / FADE OUT. 收尾。页头 ≥621px 重塑为居中等宽
   两行(品牌/导航)，≤620px 交还基础汉堡抽屉。
   ========================================================================= */
[data-theme-layout="script"] main { display: block; }
[data-theme-layout="script"] .scp-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto;
  padding: clamp(1.6rem, 4vw, 2.8rem) 0 clamp(3rem, 6vw, 4.5rem);
  font-family: var(--mono);
}
[data-theme-layout="script"] .scp-page { max-width: 640px; margin-inline: auto; }

/* ---- shared chrome: 页头重塑为居中打字机两行（≤620px 交还基础汉堡抽屉） -- */
@media (min-width: 621px) {
  [data-theme-layout="script"] .site-header { background: var(--bg); border-bottom: 1px solid var(--line); }
  [data-theme-layout="script"] .site-header .wrap {
    flex-direction: column; justify-content: center; height: auto; gap: .4rem;
    padding-top: .95rem; padding-bottom: .7rem;
  }
  [data-theme-layout="script"] .site-header .brand {
    justify-content: center; text-align: center;
    font-family: var(--mono); font-weight: 700; font-size: 1.02rem;
    letter-spacing: .28em; text-indent: .28em; text-transform: uppercase;
  }
  [data-theme-layout="script"] .site-header .nav {
    width: 100%; flex-wrap: wrap; justify-content: center; gap: .25rem 1.3rem;
    font-family: var(--mono); letter-spacing: .08em;
  }
}

/* ---- slugline: INT. + 眉标，右浮稿号胶囊 -------------------------------- */
[data-theme-layout="script"] .scp-slug {
  display: flex; justify-content: space-between; align-items: baseline; gap: .6rem 1rem;
  border-bottom: 2px solid var(--ink); padding-bottom: .55rem;
  font-size: .82rem; letter-spacing: .08em; text-transform: uppercase;
}
[data-theme-layout="script"] .scp-slug-l { display: inline-flex; align-items: baseline; gap: .55rem; min-width: 0; }
[data-theme-layout="script"] .scp-int { flex: 0 0 auto; font-weight: 700; letter-spacing: .14em; color: var(--accent); }
[data-theme-layout="script"] .scp-slug-txt { color: var(--ink-soft); overflow-wrap: anywhere; }
[data-theme-layout="script"] .scp-draft {
  flex: 0 0 auto; max-width: 45%; overflow-wrap: anywhere;
  border: 1px solid var(--line); border-radius: var(--radius);
  padding: .2rem .55rem; font-size: .7rem; letter-spacing: .06em; color: var(--muted);
}

/* ---- title page: 居中片名（下划线）+ 副行 -------------------------------- */
[data-theme-layout="script"] .scp-title-page {
  text-align: center;
  margin: clamp(1.9rem, 5vw, 3.1rem) 0 clamp(1.5rem, 4vw, 2.3rem);
}
[data-theme-layout="script"] .scp-title {
  margin: 0 0 .85rem; color: var(--ink); overflow-wrap: anywhere;
  font-family: var(--mono); font-weight: 700;
  font-size: clamp(1.55rem, 4.5vw, 2.45rem); line-height: 1.28;
  letter-spacing: .06em; text-transform: uppercase;
  text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: .32em;
}
[data-theme-layout="script"] .scp-byline {
  margin: 0 auto; max-width: 46ch;
  font-size: .92rem; line-height: 1.75; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- cast: 分类胶囊导航（居中一行流） ----------------------------------- */
[data-theme-layout="script"] .scp-cast {
  display: flex; flex-wrap: wrap; justify-content: center; gap: .45rem .55rem;
  margin: 0 0 clamp(1.8rem, 4vw, 2.6rem);
}
[data-theme-layout="script"] .scp-cast-item {
  display: inline-flex; align-items: baseline; gap: .4rem; min-width: 0;
  padding: .26rem .7rem; border: 1px solid var(--line); border-radius: var(--radius);
  font-size: .76rem; letter-spacing: .06em; text-transform: uppercase;
  color: var(--ink-soft); text-decoration: none;
  transition: color .15s, border-color .15s;
}
[data-theme-layout="script"] .scp-cast-item:hover { color: var(--accent); border-color: var(--accent); }
[data-theme-layout="script"] .scp-cast-name { overflow-wrap: anywhere; }
[data-theme-layout="script"] .scp-cast-n { font-size: .64rem; color: var(--muted); }
[data-theme-layout="script"] .scp-cast-all { color: var(--accent); border-color: var(--accent); }
[data-theme-layout="script"] .scp-cast-all:hover { color: var(--accent-soft); border-color: var(--accent-soft); }

/* ---- V.O. 旁白段：角色名行 + 衬线对白 + 括注 ----------------------------- */
[data-theme-layout="script"] .scp-vo { margin: 0 0 clamp(2rem, 4.5vw, 2.8rem); text-align: center; }
[data-theme-layout="script"] .scp-vo-in {
  display: flex; flex-direction: column; align-items: center; gap: .7rem;
  min-width: 0; text-decoration: none; color: var(--ink);
}
[data-theme-layout="script"] .scp-vo-char { font-size: .8rem; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--ink); overflow-wrap: anywhere; }
[data-theme-layout="script"] .scp-vo-char i { font-weight: 400; font-style: italic; letter-spacing: .04em; text-transform: none; color: var(--muted); }
[data-theme-layout="script"] .scp-vo-cover { display: block; width: 100%; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
[data-theme-layout="script"] .scp-vo-cover img { display: block; width: 100%; height: auto; max-height: 320px; object-fit: cover; }
[data-theme-layout="script"] .scp-vo-t {
  max-width: 34ch; overflow-wrap: anywhere;
  font-family: var(--serif); font-weight: 700;
  font-size: clamp(1.22rem, 3vw, 1.58rem); line-height: 1.32;
  transition: color .15s;
}
[data-theme-layout="script"] .scp-vo-in:hover .scp-vo-t { color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
[data-theme-layout="script"] .scp-vo-line {
  max-width: 44ch; overflow-wrap: anywhere;
  display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden;
  font-family: var(--serif); font-style: italic;
  font-size: 1.02rem; line-height: 1.7; color: var(--ink-soft);
}
[data-theme-layout="script"] .scp-vo-paren { font-size: .74rem; letter-spacing: .08em; color: var(--muted); overflow-wrap: anywhere; }

/* ---- scenes: SCENE NN 条目行（CSS counter） ------------------------------ */
[data-theme-layout="script"] .scp-scenes { counter-reset: scp-sc; margin: 0 0 clamp(2rem, 4.5vw, 2.8rem); }
[data-theme-layout="script"] .scp-scenes-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  border-bottom: 2px solid var(--ink); padding-bottom: .45rem;
}
[data-theme-layout="script"] .scp-scenes-t { margin: 0; font-size: .8rem; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; color: var(--ink); }
[data-theme-layout="script"] .scp-scenes-all {
  flex: 0 0 auto; display: inline-flex; align-items: center; gap: .3rem;
  font-size: .72rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  color: var(--accent); text-decoration: none; transition: color .15s;
}
[data-theme-layout="script"] .scp-scenes-all:hover { color: var(--accent-soft); }
[data-theme-layout="script"] .scp-scene { counter-increment: scp-sc; }
[data-theme-layout="script"] .scp-scene-in {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto;
  gap: .3rem 1.1rem; align-items: baseline;
  padding: .9rem 0; border-bottom: 1px dotted var(--line);
  text-decoration: none; color: var(--ink);
}
[data-theme-layout="script"] .scp-scene-no { font-size: .72rem; font-weight: 700; letter-spacing: .12em; color: var(--accent); white-space: nowrap; }
[data-theme-layout="script"] .scp-scene-no::before { content: "SCENE " counter(scp-sc, decimal-leading-zero); }
[data-theme-layout="script"] .scp-scene-body { min-width: 0; display: flex; flex-direction: column; gap: .28rem; }
[data-theme-layout="script"] .scp-scene-h {
  font-family: var(--serif); font-weight: 700; font-size: 1.08rem; line-height: 1.35;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="script"] .scp-scene-in:hover .scp-scene-h { color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
[data-theme-layout="script"] .scp-scene-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .84rem; line-height: 1.62; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="script"] .scp-scene-cat { align-self: flex-start; font-size: .66rem; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); overflow-wrap: anywhere; }
[data-theme-layout="script"] .scp-scene-date { font-size: .72rem; color: var(--muted); white-space: nowrap; font-variant-numeric: tabular-nums; }

/* ---- credits: 片尾字幕两列小字 ------------------------------------------ */
[data-theme-layout="script"] .scp-credits { margin: 0 0 clamp(1.8rem, 4vw, 2.4rem); text-align: center; }
[data-theme-layout="script"] .scp-credits-h {
  margin: 0 0 .9rem; padding-bottom: .5rem; border-bottom: 1px solid var(--line);
  font-size: .76rem; font-weight: 700; letter-spacing: .24em; text-transform: uppercase; color: var(--ink);
}
[data-theme-layout="script"] .scp-credits-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .1rem 2rem; }
[data-theme-layout="script"] .scp-credit { display: flex; flex-direction: column; gap: .18rem; min-width: 0; padding: .5rem .2rem; text-decoration: none; color: var(--ink-soft); }
[data-theme-layout="script"] .scp-credit-t { font-size: .84rem; font-weight: 700; line-height: 1.45; overflow-wrap: anywhere; transition: color .15s; }
[data-theme-layout="script"] .scp-credit:hover .scp-credit-t { color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
[data-theme-layout="script"] .scp-credit-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .74rem; line-height: 1.55; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- fade out ------------------------------------------------------------ */
[data-theme-layout="script"] .scp-fade {
  display: flex; flex-wrap: wrap; justify-content: center; align-items: baseline; gap: .55rem .8rem;
  border-top: 2px solid var(--ink); padding-top: 1.1rem; margin-top: clamp(1.6rem, 4vw, 2.4rem);
  font-size: .8rem; letter-spacing: .1em; text-transform: uppercase; color: var(--muted);
}
[data-theme-layout="script"] .scp-fade-word { flex-basis: 100%; text-align: center; font-weight: 700; letter-spacing: .22em; color: var(--accent); }
[data-theme-layout="script"] .scp-fade a { color: var(--ink-soft); text-decoration: none; transition: color .15s; }
[data-theme-layout="script"] .scp-fade a:hover { color: var(--accent); }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="script"] .scp-wrap { padding-top: clamp(1.2rem, 3vw, 1.8rem); }
  [data-theme-layout="script"] .scp-vo-cover img { max-height: 260px; }
}
@media (max-width: 720px) {
  [data-theme-layout="script"] .scp-slug { flex-wrap: wrap; }
  [data-theme-layout="script"] .scp-draft { max-width: 100%; }
  [data-theme-layout="script"] .scp-scene-in { grid-template-columns: auto minmax(0, 1fr); }
  [data-theme-layout="script"] .scp-scene-date { grid-column: 2; justify-self: start; }
  [data-theme-layout="script"] .scp-credits-grid { grid-template-columns: minmax(0, 1fr); }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="script"] .scp-cast-item,
  [data-theme-layout="script"] .scp-cast-all,
  [data-theme-layout="script"] .scp-scenes-all,
  [data-theme-layout="script"] .scp-vo-t,
  [data-theme-layout="script"] .scp-scene-h,
  [data-theme-layout="script"] .scp-credit-t,
  [data-theme-layout="script"] .scp-fade a { transition: none; }
}

/* ============================================================
   剧本 · Script —— Script 骨架默认皮：米白稿纸、黑墨、砖红场景字
   ============================================================ */
:root[data-theme="script"] {
  --bg: #faf7f0; --surface: #f2eddf;
  --ink: #191613; --ink-soft: #3d382f; --muted: #6b6455; --faint: #948c7a;
  --line: #ddd5c2; --line-soft: #eae4d3;
  --accent: #9a3b2f; --accent-soft: #7c2c22; --accent-wash: #f1e0da;
  --w-wide: 1200px; --radius: 3px;
  --shadow: 0 1px 2px rgba(25, 22, 19, .05), 0 6px 18px rgba(25, 22, 19, .07);
}
:root[data-theme="script"] .btn-primary { color: #fff; }

/* ============================================================
   夜稿 · Nightdraft —— Script 骨架 + 深蓝夜读本皮：夜蓝、暖米字、陶红
   ============================================================ */
:root[data-theme="nightdraft"] {
  --bg: #141a26; --surface: #1b2231;
  --ink: #f2e9da; --ink-soft: #d3c9b6; --muted: #a49a87; --faint: #78705f;
  --line: #333c4f; --line-soft: #222a3a;
  --accent: #e08a63; --accent-soft: #eda57f; --accent-wash: #31231d;
  --w-wide: 1200px; --radius: 3px; --code-bg: #0d121c;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 10px 30px rgba(0, 0, 0, .55);
}
:root[data-theme="nightdraft"] .btn-primary { color: #141a26; }
:root[data-theme="nightdraft"] .site-header { background: rgba(20, 26, 38, .92); }

/* ============================================================
   剧本 · 纯白 —— Script 骨架纯白皮：中性灰基底（对齐纯白系），砖红压深
   ============================================================ */
:root[data-theme="script-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #9c3a2b; --accent-soft: #7d2e22; --accent-wash: #f8e9e5;
  --w-wide: 1200px; --radius: 3px;
}
:root[data-theme="script-white"] .btn-primary { color: #fff; }

/* =========================================================================
   LAYOUT: postmark — 邮戳 postcard wall (pure CSS, no JS)
   every selector scoped under [data-theme-layout="postmark"], classes pmk-*
   页头 CSS 重塑为居中邮局刊头（brand 居中、导航细线行居中；重塑段整段包在
   min-width:621px 内，≤620px 交还基础汉堡抽屉）。home：两列明信片网格
   （article 奇偶 ±0.7deg 微旋，720px 归零）；卡右上齿孔邮票（radial-gradient
   齿边 + accent 票面放分类 initial）+ 红圆邮戳（旋转细环=分类名+ISO 短日期，
   等宽小字）——整组走 float 专属车道，与流内文字永不相交，地址区 clear 收底；
   摘要拆进 2~3 条地址下划线行（line-clamp 钳高），末行恒留一条空线。
   换肤钩子（皮肤可覆写，缺省回落基础令牌）：
   --pmk-red 戳红 / --pmk-stamp 票面底 / --pmk-stamp-ink 票面字 /
   --pmk-stamp-paper 票纸 / --pmk-card-bg 卡面 / --pmk-card-ink 卡标题 /
   --pmk-card-soft 卡正文 / --pmk-card-muted 卡次要 / --pmk-card-line 地址线 /
   --pmk-card-accent 卡上强调（kraft 深底+米白卡全靠这组分流）
   ========================================================================= */
[data-theme-layout="postmark"] main { display: block; }
[data-theme-layout="postmark"] .pmk-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-block: clamp(1.5rem, 4vw, 2.6rem) clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: 标准页头重塑为居中邮局刊头（只动 CSS 不动模板） ------- */
[data-theme-layout="postmark"] .site-header { background: var(--bg); border-bottom: 1px solid var(--line); }
[data-theme-layout="postmark"] .site-footer { border-top: 1px dashed var(--line); background: var(--bg); }
@media (min-width: 621px) {
  [data-theme-layout="postmark"] .site-header .wrap {
    flex-direction: column; justify-content: center; height: auto;
    gap: .5rem; padding-top: 1.05rem; padding-bottom: 0;
  }
  [data-theme-layout="postmark"] .site-header .brand {
    justify-content: center; text-align: center;
    font-family: var(--serif); font-size: 1.45rem; letter-spacing: .14em;
  }
  [data-theme-layout="postmark"] .site-header .brand-tagline { text-align: center; }
  [data-theme-layout="postmark"] .nav {
    align-self: stretch; justify-content: center; flex-wrap: wrap;
    gap: .1rem 1.4rem; border-top: 1px solid var(--line); padding: .45rem 0 .55rem;
  }
  [data-theme-layout="postmark"] .nav > a {
    min-width: 0; overflow-wrap: anywhere;
    font-family: var(--serif); font-variant: small-caps; letter-spacing: .12em; font-size: .97rem;
  }
}

/* ---- masthead: 居中眉标字距行（两侧邮戳波纹）/ 衬线大题 / 斜体引言 / 邮区 --- */
[data-theme-layout="postmark"] .pmk-masthead { text-align: center; margin: 0 0 clamp(1.8rem, 4vw, 2.6rem); }
[data-theme-layout="postmark"] .pmk-eyebrow {
  display: flex; align-items: center; justify-content: center; gap: .9rem;
  margin: 0 0 .6rem; color: var(--accent);
}
[data-theme-layout="postmark"] .pmk-eyebrow span {
  min-width: 0; overflow-wrap: anywhere;
  font-size: .74rem; font-weight: 800; letter-spacing: .3em; text-transform: uppercase;
}
[data-theme-layout="postmark"] .pmk-eyebrow::before,
[data-theme-layout="postmark"] .pmk-eyebrow::after {
  content: ""; flex: 0 1 84px; height: 9px;
  background: repeating-linear-gradient(to bottom, var(--faint) 0 1px, transparent 1px 4px);
}
[data-theme-layout="postmark"] .pmk-title {
  font-family: var(--serif); font-weight: 700;
  font-size: clamp(2rem, 5.5vw, 3.2rem); line-height: 1.1; letter-spacing: -.01em;
  margin: 0 0 .6rem; color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="postmark"] .pmk-lede {
  font-family: var(--serif); font-style: italic;
  font-size: 1rem; line-height: 1.6; color: var(--muted);
  max-width: 58ch; margin: 0 auto; overflow-wrap: anywhere;
}
[data-theme-layout="postmark"] .pmk-zones {
  display: flex; flex-wrap: wrap; justify-content: center; gap: .3rem 1.15rem;
  margin-top: clamp(.9rem, 2.5vw, 1.3rem); padding-top: .75rem;
  border-top: 1px dashed var(--faint);
}
[data-theme-layout="postmark"] .pmk-zone {
  display: inline-flex; align-items: baseline; gap: .35rem; min-width: 0;
  font-family: var(--serif); font-variant: small-caps; letter-spacing: .12em;
  font-size: .95rem; color: var(--ink-soft); text-decoration: none; transition: color .15s;
}
[data-theme-layout="postmark"] .pmk-zone:hover { color: var(--accent); }
[data-theme-layout="postmark"] .pmk-zone-name { overflow-wrap: anywhere; }
[data-theme-layout="postmark"] .pmk-zone-n { font-variant: normal; font-size: .68rem; color: var(--muted); font-variant-numeric: tabular-nums; }
[data-theme-layout="postmark"] .pmk-zone-all { color: var(--accent); }
[data-theme-layout="postmark"] .pmk-zone-all:hover { color: var(--accent-soft); text-decoration: underline; text-underline-offset: 3px; }

/* ---- board head: 虚线（齿孔）分隔的栏头 -------------------------------- */
[data-theme-layout="postmark"] .pmk-board-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  border-bottom: 1px dashed var(--faint); padding-bottom: .5rem;
  margin: 0 0 clamp(1.1rem, 2.5vw, 1.6rem);
}
[data-theme-layout="postmark"] .pmk-board-t {
  margin: 0; font-size: .8rem; font-weight: 800;
  letter-spacing: .24em; text-transform: uppercase; color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="postmark"] .pmk-board-all {
  display: inline-flex; align-items: center; gap: .3rem; flex: 0 0 auto;
  font-size: .74rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: var(--accent); text-decoration: none; transition: color .15s;
}
[data-theme-layout="postmark"] .pmk-board-all:hover { color: var(--accent-soft); }

/* ---- postcard grid: 两列，article 奇偶 ±0.7deg 微旋（720px 归零） -------- */
[data-theme-layout="postmark"] .pmk-grid {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(1rem, 2.6vw, 1.8rem) clamp(1rem, 2.4vw, 1.6rem);
}
[data-theme-layout="postmark"] .pmk-card { display: flex; min-width: 0; }
[data-theme-layout="postmark"] .pmk-grid > .pmk-card:nth-of-type(odd) { transform: rotate(.7deg); }
[data-theme-layout="postmark"] .pmk-grid > .pmk-card:nth-of-type(even) { transform: rotate(-.7deg); }
[data-theme-layout="postmark"] .pmk-card-in {
  flex: 1 1 auto; display: block; min-width: 0;
  padding: 1.05rem 1.1rem .95rem;
  background: var(--pmk-card-bg, var(--surface));
  border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: var(--shadow);
  text-decoration: none; color: var(--pmk-card-ink, var(--ink));
  transition: border-color .15s;
}
[data-theme-layout="postmark"] .pmk-card-in:hover { border-color: var(--pmk-card-accent, var(--accent)); }

/* ---- franking：右上邮票+邮戳专属车道（float，正文永不与之相交） ---------- */
[data-theme-layout="postmark"] .pmk-franking {
  float: right; position: relative;
  display: flex; align-items: flex-start;
  margin: .1rem 0 .55rem .85rem;
}
[data-theme-layout="postmark"] .pmk-stamp {
  position: relative; z-index: 1; flex: 0 0 auto;
  width: 60px; height: 68px; padding: 5px; box-sizing: border-box;
  background:
    radial-gradient(circle at 50% 0, var(--pmk-card-bg, var(--surface)) 2.1px, transparent 2.7px) left top / 8px 5px repeat-x,
    radial-gradient(circle at 50% 100%, var(--pmk-card-bg, var(--surface)) 2.1px, transparent 2.7px) left bottom / 8px 5px repeat-x,
    radial-gradient(circle at 0 50%, var(--pmk-card-bg, var(--surface)) 2.1px, transparent 2.7px) left top / 5px 8px repeat-y,
    radial-gradient(circle at 100% 50%, var(--pmk-card-bg, var(--surface)) 2.1px, transparent 2.7px) right top / 5px 8px repeat-y,
    var(--pmk-stamp-paper, #e7ebf1);
  box-shadow: 0 1px 4px rgba(0, 0, 0, .16);
}
[data-theme-layout="postmark"] .pmk-stamp-face {
  display: grid; place-items: center; width: 100%; height: 100%;
  background: var(--pmk-stamp, var(--accent)); color: var(--pmk-stamp-ink, #fff);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .3);
}
[data-theme-layout="postmark"] .pmk-stamp-face b { font-family: var(--serif); font-weight: 700; font-size: 1.35rem; line-height: 1; }
[data-theme-layout="postmark"] .pmk-cancel {
  position: relative; z-index: 2; flex: 0 0 auto;
  display: grid; align-content: center; justify-items: center; row-gap: 2px;
  width: 74px; height: 74px; padding: 9px; box-sizing: border-box;
  margin: 16px 0 0 -12px;
  border: 1.5px solid var(--pmk-red, #a8352c); border-radius: 50%;
  outline: 1px solid color-mix(in srgb, var(--pmk-red, #a8352c) 45%, transparent); outline-offset: -6px;
  color: var(--pmk-red, #a8352c);
  font-family: var(--mono); text-transform: uppercase; text-align: center;
  transform: rotate(-10deg);
}
[data-theme-layout="postmark"] .pmk-cancel-cat {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  max-width: 100%; font-size: .5rem; line-height: 1.25; letter-spacing: .06em; overflow-wrap: anywhere;
}
[data-theme-layout="postmark"] .pmk-cancel-d { font-size: .53rem; letter-spacing: .02em; font-variant-numeric: tabular-nums; white-space: nowrap; }

/* ---- card body: 衬线标题 / 地址线摘要（钳高）/ 底部分类字距行 ------------ */
[data-theme-layout="postmark"] .pmk-kicker {
  display: inline-flex; align-items: baseline; gap: .5rem; min-width: 0;
  margin-bottom: .35rem;
  font-size: .7rem; font-weight: 800; letter-spacing: .2em; text-transform: uppercase;
  color: var(--pmk-card-accent, var(--accent));
}
[data-theme-layout="postmark"] .pmk-kicker i { font-style: normal; color: var(--pmk-card-muted, var(--muted)); }
[data-theme-layout="postmark"] .pmk-kicker-cat { color: var(--pmk-card-muted, var(--muted)); overflow-wrap: anywhere; }
[data-theme-layout="postmark"] .pmk-card-h {
  display: block; font-family: var(--serif); font-weight: 700;
  font-size: 1.22rem; line-height: 1.3; overflow-wrap: anywhere;
  transition: color .15s;
}
[data-theme-layout="postmark"] .pmk-card-in:hover .pmk-card-h {
  color: var(--pmk-card-accent, var(--accent));
  text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px;
}
[data-theme-layout="postmark"] .pmk-addr { display: block; clear: right; margin-top: .65rem; --pmk-lh: 1.72rem; }
[data-theme-layout="postmark"] .pmk-addr-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .9rem; line-height: var(--pmk-lh); overflow-wrap: anywhere;
  color: var(--pmk-card-soft, var(--ink-soft));
  background-image: repeating-linear-gradient(to bottom,
    transparent 0 calc(var(--pmk-lh) - 1px),
    var(--pmk-card-line, var(--line)) calc(var(--pmk-lh) - 1px) var(--pmk-lh));
}
[data-theme-layout="postmark"] .pmk-addr-ex3 { -webkit-line-clamp: 3; }
[data-theme-layout="postmark"] .pmk-addr-blank { display: block; height: calc(var(--pmk-lh) - 1px); border-bottom: 1px solid var(--pmk-card-line, var(--line)); }
[data-theme-layout="postmark"] .pmk-card-foot {
  display: flex; justify-content: space-between; align-items: baseline; gap: .8rem;
  margin-top: .7rem;
}
[data-theme-layout="postmark"] .pmk-card-cat {
  min-width: 0; overflow-wrap: anywhere;
  font-size: .68rem; font-weight: 800; letter-spacing: .22em; text-transform: uppercase;
  color: var(--pmk-card-accent, var(--accent));
}
[data-theme-layout="postmark"] .pmk-card-d {
  flex: 0 0 auto; margin-left: auto; font-family: var(--mono);
  font-size: .72rem; letter-spacing: .03em; font-variant-numeric: tabular-nums;
  color: var(--pmk-card-muted, var(--muted));
}
[data-theme-layout="postmark"] .pmk-more {
  display: inline-flex; align-items: center; gap: .35rem;
  font-size: .72rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase;
  color: var(--pmk-card-accent, var(--accent)); transition: color .15s;
}

/* ---- lead: Featured 首卡跨两列放大（有封面时左照片右信面） -------------- */
[data-theme-layout="postmark"] .pmk-lead { grid-column: 1 / -1; }
[data-theme-layout="postmark"] .pmk-lead-split {
  display: grid; grid-template-columns: minmax(0, .9fr) minmax(0, 1.4fr);
  gap: clamp(1rem, 2.5vw, 1.5rem); align-items: stretch;
}
[data-theme-layout="postmark"] .pmk-lead-photo {
  display: block; overflow: hidden; min-width: 0;
  border: 1px solid var(--line); border-radius: calc(var(--radius) - 3px);
}
[data-theme-layout="postmark"] .pmk-lead-photo img { display: block; width: 100%; height: 100%; min-height: 220px; object-fit: cover; }
[data-theme-layout="postmark"] .pmk-lead-body { display: block; min-width: 0; }
[data-theme-layout="postmark"] .pmk-lead .pmk-card-h { font-size: clamp(1.45rem, 3vw, 2rem); line-height: 1.2; }
[data-theme-layout="postmark"] .pmk-lead .pmk-stamp { width: 66px; height: 76px; }
[data-theme-layout="postmark"] .pmk-lead .pmk-stamp-face b { font-size: 1.55rem; }

/* ---- rack: FeatLinks 分拣架（虚线小签） --------------------------------- */
[data-theme-layout="postmark"] .pmk-rack { margin-top: clamp(2rem, 5vw, 3rem); }
[data-theme-layout="postmark"] .pmk-rack-h {
  margin: 0 0 .9rem; padding-bottom: .5rem; border-bottom: 1px dashed var(--faint);
  font-size: .8rem; font-weight: 800; letter-spacing: .24em; text-transform: uppercase;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="postmark"] .pmk-rack-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: .8rem 1rem;
}
[data-theme-layout="postmark"] .pmk-slip {
  display: flex; align-items: flex-start; gap: .65rem; min-width: 0;
  padding: .7rem .8rem;
  background: var(--pmk-card-bg, var(--surface));
  border: 1px dashed var(--line); border-radius: calc(var(--radius) - 3px);
  text-decoration: none; color: var(--pmk-card-ink, var(--ink));
  transition: border-color .15s;
}
[data-theme-layout="postmark"] .pmk-slip:hover { border-color: var(--pmk-card-accent, var(--accent)); }
[data-theme-layout="postmark"] .pmk-slip-ic {
  flex: 0 0 auto; width: 40px; height: 40px; overflow: hidden;
  display: grid; place-items: center; border-radius: 4px;
  background: var(--accent-wash); color: var(--accent);
}
[data-theme-layout="postmark"] .pmk-slip-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="postmark"] .pmk-slip-ic b { font-family: var(--serif); font-weight: 700; font-size: 1.05rem; line-height: 1; }
[data-theme-layout="postmark"] .pmk-slip-body { min-width: 0; }
[data-theme-layout="postmark"] .pmk-slip-t {
  display: block; font-family: var(--serif); font-weight: 700;
  font-size: .95rem; line-height: 1.3; overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="postmark"] .pmk-slip:hover .pmk-slip-t { color: var(--pmk-card-accent, var(--accent)); }
[data-theme-layout="postmark"] .pmk-slip-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  margin-top: .15rem; font-size: .8rem; line-height: 1.45;
  color: var(--pmk-card-muted, var(--muted)); overflow-wrap: anywhere;
}

/* ---- colophon ------------------------------------------------------------ */
[data-theme-layout="postmark"] .pmk-colophon {
  display: flex; justify-content: center; align-items: baseline; gap: .8rem; flex-wrap: wrap;
  margin-top: clamp(2rem, 5vw, 3rem); padding-top: .85rem;
  border-top: 1px dashed var(--faint);
  font-family: var(--serif); font-variant: small-caps; letter-spacing: .14em;
  font-size: .92rem; color: var(--muted);
}
[data-theme-layout="postmark"] .pmk-colophon a { color: var(--ink-soft); text-decoration: none; transition: color .15s; }
[data-theme-layout="postmark"] .pmk-colophon a:hover { color: var(--accent); }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="postmark"] .pmk-grid { gap: 1.1rem 1rem; }
  [data-theme-layout="postmark"] .pmk-lead-split { grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr); }
}
@media (max-width: 720px) {
  [data-theme-layout="postmark"] .pmk-grid { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="postmark"] .pmk-grid > .pmk-card:nth-of-type(odd),
  [data-theme-layout="postmark"] .pmk-grid > .pmk-card:nth-of-type(even) { transform: none; }
  [data-theme-layout="postmark"] .pmk-lead-split { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="postmark"] .pmk-lead-photo img { height: auto; min-height: 0; aspect-ratio: 16 / 9; }
  [data-theme-layout="postmark"] .pmk-stamp { width: 54px; height: 62px; }
  [data-theme-layout="postmark"] .pmk-lead .pmk-stamp { width: 54px; height: 62px; }
  [data-theme-layout="postmark"] .pmk-cancel { width: 64px; height: 64px; margin: 14px 0 0 -10px; padding: 7px; }
  [data-theme-layout="postmark"] .pmk-eyebrow::before,
  [data-theme-layout="postmark"] .pmk-eyebrow::after { flex-basis: 40px; }
  [data-theme-layout="postmark"] .pmk-eyebrow span { letter-spacing: .22em; }
  [data-theme-layout="postmark"] .pmk-board-head { flex-wrap: wrap; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="postmark"] .pmk-zone,
  [data-theme-layout="postmark"] .pmk-zone-all,
  [data-theme-layout="postmark"] .pmk-board-all,
  [data-theme-layout="postmark"] .pmk-card-in,
  [data-theme-layout="postmark"] .pmk-card-h,
  [data-theme-layout="postmark"] .pmk-more,
  [data-theme-layout="postmark"] .pmk-slip,
  [data-theme-layout="postmark"] .pmk-slip-t,
  [data-theme-layout="postmark"] .pmk-colophon a { transition: none; }
}

/* ============================================================
   邮戳 · Postmark —— Postmark 骨架默认皮：奶油纸、乳白明信片、
   邮政蓝票面、戳红圆戳
   ============================================================ */
:root[data-theme="postmark"] {
  --bg: #efe6d5; --surface: #fffdf4;
  --ink: #211d15; --ink-soft: #4a4433; --muted: #675e49; --faint: #8a8069;
  --line: #d9cdb4; --line-soft: #e7ddc9;
  --accent: #2f5d8a; --accent-soft: #24496e; --accent-wash: #e3e9f0;
  --pmk-red: #a8352c; --pmk-stamp-paper: #e7ebf1;
  --w-wide: 1140px; --radius: 10px;
  --shadow: 0 1px 2px rgba(33, 29, 21, .06), 0 8px 22px rgba(33, 29, 21, .09);
}
:root[data-theme="postmark"] .site-header { background: var(--bg); }
:root[data-theme="postmark"] .btn-primary { color: #fff; }

/* ============================================================
   牛皮纸 · Kraft —— Postmark 骨架反差皮：深牛皮棕底 + 米白明信片 + 墨绿票
   （深底浅字走基础令牌；米白卡上的深字/墨绿强调全部走 --pmk-card-* 分流，
   实算：卡标题 13.66 / 卡正文 8.86 / 卡次要 5.78 / 墨绿作字 9.15 / 戳红 6.98）
   ============================================================ */
:root[data-theme="kraft"] {
  --bg: #43301c; --surface: #513b23;
  --ink: #f6efdd; --ink-soft: #e6dcc4; --muted: #d3c2a0; --faint: #b09f7d;
  --line: #6b5335; --line-soft: #5a4429;
  --accent: #cfe3c8; --accent-soft: #e0eed9; --accent-wash: #5c452a;
  --pmk-red: #8f2f25; --pmk-stamp-paper: #e2d4b4;
  --pmk-card-bg: #f5eedd; --pmk-card-ink: #2b2113; --pmk-card-soft: #4c3f28;
  --pmk-card-muted: #6a5a3c; --pmk-card-line: #cdbc97; --pmk-card-accent: #1e4636;
  --pmk-stamp: #1e4636; --pmk-stamp-ink: #f5eedd;
  --w-wide: 1140px; --radius: 10px; --code-bg: #2e2113;
  --shadow: 0 1px 2px rgba(0, 0, 0, .35), 0 10px 26px rgba(0, 0, 0, .4);
}
:root[data-theme="kraft"] .site-header { background: rgba(67, 48, 28, .94); }
:root[data-theme="kraft"] .btn-primary { color: #2b2113; }

/* ============================================================
   邮戳纯白 · Postmark White —— 第五批纯白系：中性灰基底照抄纯白段，
   邮政蓝原色相压深保持 #2f5d8a（白底 6.88，hover soft 9.32 只升不降）；
   muted #707680 在 #fafaf8 只有 4.38 → 卡面/分拣签覆写回纯白
   （--pmk-card-bg:#fff，muted 实算 4.57）
   ============================================================ */
:root[data-theme="postmark-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #707680; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #2f5d8a; --accent-soft: #24496e; --accent-wash: #e8eef4;
  --pmk-red: #a8352c; --pmk-stamp-paper: #eef1f5;
  --pmk-card-bg: #ffffff;
  --w-wide: 1140px; --radius: 10px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .04), 0 8px 22px rgba(16, 18, 24, .07);
}
:root[data-theme="postmark-white"] .btn-primary { color: #fff; }

/* =========================================================================
   LAYOUT: metro — 线网 transit-map home (pure CSS, no JS)
   every selector scoped under [data-theme-layout="metro"], classes mtr-*
   标准页头 CSS 重塑为「运营公告」细条（顶端四色线带；重塑段包 min-width:621px，
   ≤620px 交还基础汉堡抽屉）；home：白底圆角线网图卡——分类=胶囊线名徽章 +
   通长圆头色轨，Posts 轮转散作沿线站点（白底粗彩边圆点、站名在下、两行钳制），
   Featured=双圈换乘大站（ink 描边光环+放大标签）；FeatLinks=服务小卡；
   线网图下=「站点一览」编号列表。线色按 nth-child 从 --mtr-l1..4 取
   （皮肤令牌定义，缺省回落 accent 系）；线轨/线带纯装饰，站名一律 ink。
   ========================================================================= */
[data-theme-layout="metro"] main { display: block; }
[data-theme-layout="metro"] .mtr-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-block: clamp(1.6rem, 4vw, 2.6rem) clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: header as a slim service-notice strip --------------- */
[data-theme-layout="metro"] .site-header { background: var(--bg); border-bottom: 1px solid var(--line); }
[data-theme-layout="metro"] .site-footer { border-top: 1px solid var(--line); background: var(--bg); }
@media (min-width: 621px) {
  [data-theme-layout="metro"] .site-header { position: relative; }
  [data-theme-layout="metro"] .site-header::before {
    content: ""; position: absolute; inset: 0 0 auto 0; height: 4px;
    background: linear-gradient(90deg,
      var(--mtr-l1, var(--accent)) 0 25%, var(--mtr-l2, var(--accent-soft)) 25% 50%,
      var(--mtr-l3, var(--accent)) 50% 75%, var(--mtr-l4, var(--accent-soft)) 75% 100%);
  }
  [data-theme-layout="metro"] .site-header .wrap { height: 54px; }
  [data-theme-layout="metro"] .site-header .brand { font-size: .98rem; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; }
  [data-theme-layout="metro"] .site-header .nav a { font-size: .8rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
}

/* ---- hero: eyebrow with a small track chip / heavy sans title ----------- */
[data-theme-layout="metro"] .mtr-hero { margin: 0 0 clamp(1.6rem, 4vw, 2.4rem); }
[data-theme-layout="metro"] .mtr-eyebrow {
  margin: 0 0 .55rem; font-size: .76rem; font-weight: 800;
  letter-spacing: .28em; text-transform: uppercase; color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="metro"] .mtr-eyebrow::before {
  content: ""; display: inline-block; width: 26px; height: 8px; margin-right: .55rem;
  border-radius: 999px; background: var(--mtr-l1, var(--accent)); vertical-align: middle;
}
[data-theme-layout="metro"] .mtr-title {
  margin: 0 0 .6rem; font-weight: 800;
  font-size: clamp(2rem, 5.5vw, 3.4rem); line-height: 1.06; letter-spacing: -.02em;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="metro"] .mtr-lede {
  margin: 0; font-size: 1rem; line-height: 1.62; color: var(--muted);
  max-width: 62ch; overflow-wrap: anywhere;
}

/* ---- network card: one colored line row per category -------------------- */
[data-theme-layout="metro"] .mtr-map {
  display: flex; flex-direction: column; gap: clamp(1.3rem, 3vw, 1.9rem);
  background: var(--surface); border: 1px solid var(--line); border-radius: 22px;
  box-shadow: var(--shadow);
  padding: clamp(1.2rem, 3vw, 2rem) clamp(1.1rem, 3vw, 2rem) clamp(.9rem, 2.5vw, 1.4rem);
}
[data-theme-layout="metro"] .mtr-line { display: flex; align-items: flex-start; gap: clamp(.8rem, 2vw, 1.3rem); min-width: 0; }
/* 线色车道：按 nth-child 从皮肤令牌取，缺省回落 accent 系 */
[data-theme-layout="metro"] .mtr-line:nth-child(4n+1) { --mtr-lc: var(--mtr-l1, var(--accent)); }
[data-theme-layout="metro"] .mtr-line:nth-child(4n+2) { --mtr-lc: var(--mtr-l2, var(--accent-soft)); }
[data-theme-layout="metro"] .mtr-line:nth-child(4n+3) { --mtr-lc: var(--mtr-l3, var(--accent)); }
[data-theme-layout="metro"] .mtr-line:nth-child(4n+4) { --mtr-lc: var(--mtr-l4, var(--accent-soft)); }

/* line-name capsule badge */
[data-theme-layout="metro"] .mtr-badge {
  flex: 0 0 auto; display: inline-flex; align-items: center; gap: .45rem;
  min-width: 0; max-width: 200px; margin-top: 1px;
  background: var(--mtr-lc, var(--accent)); color: var(--mtr-badge-ink, #fff);
  border-radius: 999px; padding: .34rem .85rem;
  font-size: .8rem; font-weight: 800; letter-spacing: .04em;
  text-decoration: none; transition: box-shadow .15s;
}
[data-theme-layout="metro"] .mtr-badge:hover { box-shadow: 0 0 0 3px color-mix(in srgb, var(--mtr-lc, var(--accent)) 30%, transparent); }
[data-theme-layout="metro"] .mtr-badge-name {
  overflow-wrap: anywhere;
  display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden;
}
[data-theme-layout="metro"] .mtr-badge-n {
  flex: 0 0 auto; background: #fff; color: #16181d;
  border-radius: 999px; padding: .04rem .42rem; font-size: .66rem; font-weight: 800;
}

/* full-length round-capped track with stations riding on it */
[data-theme-layout="metro"] .mtr-track {
  position: relative; flex: 1 1 0; min-width: 0;
  display: flex; align-items: flex-start; gap: .5rem; padding: 0 .4rem;
}
[data-theme-layout="metro"] .mtr-track::before {
  content: ""; position: absolute; left: 0; right: 0; top: 8px; height: 10px;
  border-radius: 999px; background: var(--mtr-lc, var(--accent));
}
[data-theme-layout="metro"] .mtr-sta {
  position: relative; z-index: 1; flex: 1 1 0; min-width: 0; max-width: 220px;
  display: flex; flex-direction: column; align-items: center; gap: .55rem;
  padding-top: 4px; text-align: center; text-decoration: none; color: var(--ink);
}
[data-theme-layout="metro"] .mtr-dot {
  flex: 0 0 auto; width: 18px; height: 18px; border-radius: 50%;
  background: #fff; border: 5px solid var(--mtr-lc, var(--accent));
  transition: transform .15s;
}
[data-theme-layout="metro"] .mtr-sta:hover .mtr-dot { transform: scale(1.12); }
[data-theme-layout="metro"] .mtr-sta-body { display: flex; flex-direction: column; gap: .1rem; min-width: 0; }
[data-theme-layout="metro"] .mtr-sta-t {
  font-size: .82rem; font-weight: 700; line-height: 1.35; color: var(--ink);
  overflow-wrap: anywhere; transition: color .15s;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
[data-theme-layout="metro"] .mtr-sta:hover .mtr-sta-t { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
/* Featured = interchange hub: bigger dot, double ink halo, bigger label */
[data-theme-layout="metro"] .mtr-hub { padding-top: 0; }
[data-theme-layout="metro"] .mtr-hub .mtr-dot {
  width: 26px; height: 26px;
  box-shadow: 0 0 0 3px var(--surface), 0 0 0 5px var(--ink);
}
[data-theme-layout="metro"] .mtr-hub .mtr-sta-t { font-size: .95rem; font-weight: 800; }
[data-theme-layout="metro"] .mtr-hub-tag {
  display: block; font-style: normal; font-size: .62rem; font-weight: 800;
  letter-spacing: .18em; text-transform: uppercase; color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="metro"] .mtr-map-all {
  display: flex; justify-content: flex-end; align-items: center; gap: .3rem;
  border-top: 1px dashed var(--line); padding-top: .7rem;
  font-size: .76rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  color: var(--accent); text-decoration: none; transition: color .15s;
}
[data-theme-layout="metro"] .mtr-map-all:hover { color: var(--accent-soft); }

/* ---- service links: compact chips --------------------------------------- */
[data-theme-layout="metro"] .mtr-links { margin-top: clamp(1.6rem, 4vw, 2.2rem); }
[data-theme-layout="metro"] .mtr-links-h {
  margin: 0 0 .7rem; font-size: .78rem; font-weight: 800;
  letter-spacing: .2em; text-transform: uppercase; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="metro"] .mtr-links-row { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: .7rem; }
[data-theme-layout="metro"] .mtr-link {
  display: flex; align-items: center; gap: .65rem; min-width: 0;
  background: var(--surface); border: 1px solid var(--line); border-radius: 14px;
  padding: .6rem .75rem; text-decoration: none; color: var(--ink);
  transition: border-color .15s;
}
[data-theme-layout="metro"] .mtr-link:hover { border-color: var(--accent); }
[data-theme-layout="metro"] .mtr-link-ic {
  flex: 0 0 auto; width: 34px; height: 34px; border-radius: 50%; overflow: hidden;
  display: grid; place-items: center;
  background: var(--accent-wash); color: var(--accent); border: 2px solid var(--accent);
}
[data-theme-layout="metro"] .mtr-link-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="metro"] .mtr-link-ic b { font-weight: 800; font-size: 1rem; line-height: 1; }
[data-theme-layout="metro"] .mtr-link-t {
  font-size: .88rem; font-weight: 600; line-height: 1.35; overflow-wrap: anywhere;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  transition: color .15s;
}
[data-theme-layout="metro"] .mtr-link:hover .mtr-link-t { color: var(--accent); }

/* ---- station directory: numbered plain rows ----------------------------- */
[data-theme-layout="metro"] .mtr-list { margin-top: clamp(1.8rem, 4.5vw, 2.6rem); }
[data-theme-layout="metro"] .mtr-list-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  border-bottom: 2px solid var(--ink); padding-bottom: .5rem;
}
[data-theme-layout="metro"] .mtr-list-t {
  margin: 0; font-size: .82rem; font-weight: 800;
  letter-spacing: .2em; text-transform: uppercase; color: var(--ink);
}
[data-theme-layout="metro"] .mtr-list-all {
  flex: 0 0 auto; display: inline-flex; align-items: center; gap: .3rem;
  font-size: .74rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  color: var(--accent); text-decoration: none; transition: color .15s;
}
[data-theme-layout="metro"] .mtr-list-all:hover { color: var(--accent-soft); }
[data-theme-layout="metro"] .mtr-rows { list-style: none; margin: 0; padding: 0; counter-reset: mtr-sta; }
[data-theme-layout="metro"] .mtr-row { counter-increment: mtr-sta; }
[data-theme-layout="metro"] .mtr-row-in {
  display: flex; align-items: baseline; gap: .9rem; min-width: 0;
  padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft);
  text-decoration: none; color: var(--ink);
}
[data-theme-layout="metro"] .mtr-row-in::before {
  content: counter(mtr-sta, decimal-leading-zero);
  flex: 0 0 auto; font-size: .72rem; font-weight: 800;
  font-variant-numeric: tabular-nums; letter-spacing: .06em; color: var(--muted);
  border: 1px solid var(--line); border-radius: 999px; padding: .12rem .5rem;
}
[data-theme-layout="metro"] .mtr-row-t {
  flex: 1 1 auto; min-width: 0; font-size: 1.02rem; font-weight: 600; line-height: 1.4;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="metro"] .mtr-row-in:hover .mtr-row-t { color: var(--accent); }
[data-theme-layout="metro"] .mtr-row-meta {
  flex: 0 0 auto; display: inline-flex; align-items: baseline; gap: .45rem;
  font-size: .76rem; color: var(--muted);
}
[data-theme-layout="metro"] .mtr-row-cat {
  font-weight: 700; letter-spacing: .04em; text-transform: uppercase;
  max-width: 14ch; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  /* 线网图降级：每线一个竖列表——轨道转纵向色条，站点转行（圆点左、站名右） */
  [data-theme-layout="metro"] .mtr-line { flex-direction: column; align-items: stretch; gap: .8rem; }
  [data-theme-layout="metro"] .mtr-badge { align-self: flex-start; margin-top: 0; }
  [data-theme-layout="metro"] .mtr-track { flex-direction: column; align-items: stretch; gap: .9rem; padding: .2rem 0; }
  [data-theme-layout="metro"] .mtr-track::before { left: 5px; right: auto; top: 4px; bottom: 4px; width: 8px; height: auto; }
  [data-theme-layout="metro"] .mtr-sta {
    flex-direction: row; align-items: flex-start; gap: .7rem;
    max-width: none; padding-top: 0; text-align: left;
  }
  [data-theme-layout="metro"] .mtr-dot { margin-top: 1px; }
  [data-theme-layout="metro"] .mtr-sta-body { align-items: flex-start; }
  [data-theme-layout="metro"] .mtr-hub .mtr-dot { margin-left: -4px; }
}
@media (max-width: 720px) {
  [data-theme-layout="metro"] .mtr-title { font-size: clamp(1.7rem, 8vw, 2.2rem); }
  [data-theme-layout="metro"] .mtr-map { border-radius: 16px; }
  [data-theme-layout="metro"] .mtr-links-row { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="metro"] .mtr-row-in { flex-wrap: wrap; row-gap: .15rem; }
  [data-theme-layout="metro"] .mtr-row-meta { flex: 1 0 100%; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="metro"] .mtr-badge,
  [data-theme-layout="metro"] .mtr-dot,
  [data-theme-layout="metro"] .mtr-sta-t,
  [data-theme-layout="metro"] .mtr-link,
  [data-theme-layout="metro"] .mtr-link-t,
  [data-theme-layout="metro"] .mtr-row-t,
  [data-theme-layout="metro"] .mtr-map-all,
  [data-theme-layout="metro"] .mtr-list-all { transition: none; }
  [data-theme-layout="metro"] .mtr-sta:hover .mtr-dot { transform: none; }
}

/* ============================================================
   线网 · Metro —— Metro 骨架默认皮：近白底、红/蓝/绿/深橙彩线、近黑字
   （线轨纯装饰；胶囊白字实算 5.89/6.87/4.81/6.11，站名一律 ink）
   ============================================================ */
:root[data-theme="metro"] {
  --bg: #fbfbf8; --surface: #ffffff;
  --ink: #16181d; --ink-soft: #3c4046; --muted: #6b7076; --faint: #9aa0a7;
  --line: #dcdee2; --line-soft: #ecedef;
  --accent: #c8102e; --accent-soft: #a30d26; --accent-wash: #fdecef;
  --mtr-l1: #c8102e; --mtr-l2: #0057b8; --mtr-l3: #00843d; --mtr-l4: #9a4d00;
  --mtr-badge-ink: #ffffff;
  --w-wide: 1200px; --radius: 12px;
  --shadow: 0 1px 2px rgba(22, 24, 29, .05), 0 10px 26px rgba(22, 24, 29, .07);
}
:root[data-theme="metro"] .btn-primary { color: #fff; }

/* ============================================================
   夜航线 · Nightline —— Metro 骨架反差皮：深夜黑网、霓虹黄/青/绿/粉线、
   月白字（胶囊改深色字 13.78/10.77/11.17/7.35；换乘光环随 ink 转月白）
   ============================================================ */
:root[data-theme="nightline"] {
  --bg: #0b0d10; --surface: #14171c;
  --ink: #eef2f6; --ink-soft: #c8cfd8; --muted: #97a0ab; --faint: #6a737e;
  --line: #262b33; --line-soft: #1b2027;
  --accent: #ffd60a; --accent-soft: #ffe14d; --accent-wash: #2a2405;
  --mtr-l1: #ffd60a; --mtr-l2: #22d3ee; --mtr-l3: #4ade80; --mtr-l4: #f472b6;
  --mtr-badge-ink: #0b0d10;
  --w-wide: 1200px; --radius: 12px; --code-bg: #05070a;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 12px 30px rgba(0, 0, 0, .55);
}
:root[data-theme="nightline"] .btn-primary { color: #0b0d10; }
:root[data-theme="nightline"] .site-header { background: rgba(11, 13, 16, .92); }

/* ============================================================
   线网 · 纯白 —— metro-white：中性灰基底照抄「纯白系」段；accent 保留
   金属红压深到 #b60f28（白底 6.80，hover soft 9.37 只升不降）；线色同步
   压深（白字 6.80/6.87/4.81/6.11）。muted 只落 --bg 纯白（4.57），
   图卡/小卡内文字全为 ink/accent，不放 muted——后续加 muted 文案须覆写卡面回 --bg。
   ============================================================ */
:root[data-theme="metro-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #b60f28; --accent-soft: #8f0c20; --accent-wash: #faeaec;
  --mtr-l1: #b60f28; --mtr-l2: #0057b8; --mtr-l3: #00843d; --mtr-l4: #9a4d00;
  --mtr-badge-ink: #ffffff;
  --w-wide: 1200px; --radius: 10px;
}
:root[data-theme="metro-white"] .btn-primary { color: #fff; }

/* =========================================================================
   LAYOUT: circuit — 电路 PCB 大板 (pure CSS, no JS)
   every selector scoped under [data-theme-layout="circuit"], classes cir-*
   整版=PCB：焊点网格板面+圆角铜边 / 丝印行(板名 REV) / U1 主控芯片(左引脚
   +发光焊点车道) / J 接插件排 / 总线分类胶囊 / U2+ 芯片列(CSS counter)
   ========================================================================= */
[data-theme-layout="circuit"] main { display: block; }
[data-theme-layout="circuit"] .cir-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding: clamp(1.2rem, 3vw, 2rem) 0 clamp(2.6rem, 5vw, 4rem);
}

/* ---- shared chrome: 页头=板卡上边缘（铜边压条+等宽丝印字距）。
       重塑段整体包 min-width:621px，≤620px 交还基础汉堡抽屉 ------------- */
@media (min-width: 621px) {
  [data-theme-layout="circuit"] .site-header {
    background: var(--bg);
    border-bottom: 2px solid color-mix(in srgb, var(--accent) 55%, var(--line));
  }
  [data-theme-layout="circuit"] .site-header .brand {
    font-family: var(--mono); font-weight: 700;
    letter-spacing: .14em; text-transform: uppercase;
  }
  [data-theme-layout="circuit"] .site-header .nav a {
    font-family: var(--mono); font-size: .82rem;
    letter-spacing: .08em; text-transform: uppercase;
  }
}

/* ---- board: 深底板面 + 焊点 radial 网格纹 + 圆角铜边框 ------------------ */
[data-theme-layout="circuit"] .cir-board {
  background-color: var(--bg);
  background-image:
    radial-gradient(circle at 11px 11px, color-mix(in srgb, var(--accent) 22%, transparent) 0 1.6px, transparent 2.6px),
    linear-gradient(color-mix(in srgb, var(--line) 30%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--line) 30%, transparent) 1px, transparent 1px);
  background-size: 22px 22px;
  border: 2px solid color-mix(in srgb, var(--accent) 55%, var(--line));
  border-radius: calc(var(--radius) + 10px);
  box-shadow: var(--shadow);
  padding: clamp(1.1rem, 3vw, 2.2rem);
}

/* ---- silk: 丝印行——HeroTitle 当板名 REV 行（等宽大字距） ---------------- */
[data-theme-layout="circuit"] .cir-silk { margin-bottom: clamp(1rem, 2.6vw, 1.6rem); }
[data-theme-layout="circuit"] .cir-eyebrow {
  margin: 0 0 .55rem; font-family: var(--mono); font-size: .72rem; font-weight: 700;
  letter-spacing: .22em; text-transform: uppercase; color: var(--accent);
}
[data-theme-layout="circuit"] .cir-title {
  margin: 0; font-family: var(--mono); font-weight: 700;
  font-size: clamp(1.55rem, 4.2vw, 2.6rem); line-height: 1.18;
  letter-spacing: .06em; text-transform: uppercase;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="circuit"] .cir-desc {
  margin: .6rem 0 0; max-width: 70ch;
  font-size: .98rem; line-height: 1.7; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- bus: 「总线」横行——上下虚线走廊 + 分类胶囊 ------------------------- */
[data-theme-layout="circuit"] .cir-bus {
  display: flex; flex-wrap: wrap; gap: .5rem;
  padding: .8rem .1rem;
  border-block: 1px dashed color-mix(in srgb, var(--line) 75%, var(--accent));
  margin: 0 0 clamp(1.2rem, 3vw, 1.8rem);
}
[data-theme-layout="circuit"] .cir-bus-pin {
  display: inline-flex; align-items: baseline; gap: .45rem; min-width: 0;
  padding: .3rem .8rem;
  background: var(--surface); border: 1px solid var(--line); border-radius: 7px;
  font-family: var(--mono); font-size: .8rem; letter-spacing: .05em; text-transform: uppercase;
  color: var(--ink-soft); text-decoration: none;
  transition: color .15s, border-color .15s;
}
[data-theme-layout="circuit"] .cir-bus-pin:hover { color: var(--accent-soft); border-color: var(--accent); }
[data-theme-layout="circuit"] .cir-bus-name { overflow-wrap: anywhere; }
[data-theme-layout="circuit"] .cir-bus-n { font-size: .66rem; color: var(--muted); }
[data-theme-layout="circuit"] .cir-bus-all { color: var(--accent); border-color: color-mix(in srgb, var(--accent) 45%, var(--line)); }
[data-theme-layout="circuit"] .cir-bus-all:hover { color: var(--accent-soft); }

/* ---- 器件位号章：U1 / U2+ / J1+（CSS 生成，aria-hidden 纯装饰） ---------- */
[data-theme-layout="circuit"] .cir-u {
  display: inline-grid; place-items: center;
  min-width: 2.1em; padding: .18rem .42rem;
  background: var(--accent-wash); color: var(--accent-soft);
  border: 1px solid color-mix(in srgb, var(--accent) 45%, var(--line));
  border-radius: 5px;
  font-family: var(--mono); font-style: normal; font-weight: 700;
  font-size: .68rem; letter-spacing: .08em; line-height: 1;
}
[data-theme-layout="circuit"] .cir-u1::before { content: "U1"; }
[data-theme-layout="circuit"] .cir-ic-no::before { content: "U" counter(cir-u); }
[data-theme-layout="circuit"] .cir-jack-no::before { content: "J" counter(cir-j); }
[data-theme-layout="circuit"] .cir-chip-tag {
  display: inline-flex; align-items: center; gap: .5rem; align-self: flex-start;
  font-family: var(--mono); font-size: .7rem; font-weight: 700;
  letter-spacing: .16em; text-transform: uppercase; color: var(--accent);
}

/* ---- mcu: 主控大芯片卡（accent 描边 + 左引脚线/发光焊点专属车道） -------- */
[data-theme-layout="circuit"] .cir-mcu {
  position: relative;
  display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr);
  gap: clamp(1rem, 2.6vw, 1.8rem); align-items: center;
  padding: clamp(1rem, 2.8vw, 1.6rem);
  padding-left: calc(clamp(1rem, 2.8vw, 1.6rem) + 30px);
  background: var(--surface);
  border: 2px solid var(--accent); border-radius: calc(var(--radius) + 4px);
  box-shadow: var(--shadow);
  text-decoration: none; color: var(--ink);
  transition: border-color .15s;
}
[data-theme-layout="circuit"] .cir-mcu:hover { border-color: var(--accent-soft); }
[data-theme-layout="circuit"] .cir-mcu-solo { grid-template-columns: minmax(0, 1fr); }
/* 引脚线：30px 专属车道（padding 预留，与流内文字不相交），钳在卡高 14%~86% */
[data-theme-layout="circuit"] .cir-mcu::before {
  content: ""; position: absolute; left: 12px; top: 14%; bottom: 14%; width: 12px;
  background-image: repeating-linear-gradient(to bottom,
    transparent 0 6px, color-mix(in srgb, var(--accent) 75%, var(--surface)) 6px 8px, transparent 8px 14px);
  pointer-events: none;
}
/* 发光焊点：与引脚同节距的 repeat-y 亮点+光晕，呼吸动画（reduced-motion 关） */
[data-theme-layout="circuit"] .cir-mcu::after {
  content: ""; position: absolute; left: 3px; top: 14%; bottom: 14%; width: 10px;
  background-image: radial-gradient(circle at 5px 7px,
    var(--accent-soft) 0 1.7px, color-mix(in srgb, var(--accent) 45%, transparent) 2.8px, transparent 4.4px);
  background-size: 10px 14px; background-repeat: repeat-y;
  animation: cir-glow 2s ease-in-out infinite alternate;
  pointer-events: none;
}
@keyframes cir-glow { from { opacity: .5; } to { opacity: 1; } }
[data-theme-layout="circuit"] .cir-mcu-body { display: flex; flex-direction: column; gap: .6rem; min-width: 0; }
[data-theme-layout="circuit"] .cir-mcu-h {
  font-size: clamp(1.35rem, 3.2vw, 2.05rem); font-weight: 800; line-height: 1.22;
  letter-spacing: -.01em; overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="circuit"] .cir-mcu:hover .cir-mcu-h { color: var(--accent-soft); }
[data-theme-layout="circuit"] .cir-mcu-ex {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .96rem; line-height: 1.66; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="circuit"] .cir-mcu-cover {
  display: block; min-width: 0; overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--line));
  border-radius: var(--radius);
}
[data-theme-layout="circuit"] .cir-mcu-cover img { display: block; width: 100%; height: auto; aspect-ratio: 16 / 10; object-fit: cover; }

/* ---- pinrow: 引脚行——分类 ◈ 日期（等宽小字，虚线上缘当排针座） ---------- */
[data-theme-layout="circuit"] .cir-pinrow {
  display: flex; align-items: center; flex-wrap: wrap; gap: .35rem .55rem;
  margin-top: auto; padding-top: .6rem;
  border-top: 1px dashed var(--line);
  font-family: var(--mono); font-size: .72rem; letter-spacing: .05em;
  text-transform: uppercase; color: var(--muted);
}
[data-theme-layout="circuit"] .cir-pin-cat { color: var(--accent); overflow-wrap: anywhere; }
[data-theme-layout="circuit"] .cir-pin-sep { color: var(--muted); }
[data-theme-layout="circuit"] .cir-mcu-more {
  margin-left: auto; display: inline-flex; align-items: center; gap: .3rem;
  font-weight: 700; color: var(--accent); transition: color .15s;
}
[data-theme-layout="circuit"] .cir-mcu:hover .cir-mcu-more { color: var(--accent-soft); }

/* ---- jacks: 「接插件」一排小卡（J1/J2 位号 + 图标/首字母插座） ----------- */
[data-theme-layout="circuit"] .cir-jacks { margin-top: clamp(1.2rem, 3vw, 1.8rem); }
[data-theme-layout="circuit"] .cir-side-h {
  margin: 0 0 .7rem; font-family: var(--mono); font-size: .72rem; font-weight: 700;
  letter-spacing: .2em; text-transform: uppercase; color: var(--accent);
}
[data-theme-layout="circuit"] .cir-jacks-row { display: flex; flex-wrap: wrap; gap: .6rem; counter-reset: cir-j; }
[data-theme-layout="circuit"] .cir-jack {
  counter-increment: cir-j;
  display: inline-flex; align-items: center; gap: .55rem; min-width: 0;
  padding: .4rem .85rem .4rem .45rem;
  background: var(--surface); border: 1px solid var(--line); border-radius: 8px;
  text-decoration: none; color: var(--ink);
  transition: border-color .15s;
}
[data-theme-layout="circuit"] .cir-jack:hover { border-color: var(--accent); }
[data-theme-layout="circuit"] .cir-jack-ic {
  flex: 0 0 auto; width: 30px; height: 30px; overflow: hidden;
  display: grid; place-items: center; border-radius: 6px;
  background: var(--accent-wash); color: var(--accent-soft);
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--line));
}
[data-theme-layout="circuit"] .cir-jack-ic b { font-family: var(--mono); font-weight: 700; font-size: .92rem; line-height: 1; }
[data-theme-layout="circuit"] .cir-jack-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="circuit"] .cir-jack-t { font-size: .9rem; font-weight: 600; overflow-wrap: anywhere; transition: color .15s; }
[data-theme-layout="circuit"] .cir-jack:hover .cir-jack-t { color: var(--accent-soft); }

/* ---- ics: U2+ 芯片卡列（同构小一号，细引脚车道，CSS counter 位号） ------- */
[data-theme-layout="circuit"] .cir-ics { margin-top: clamp(1.4rem, 3.5vw, 2.2rem); }
[data-theme-layout="circuit"] .cir-ics-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  border-bottom: 2px solid color-mix(in srgb, var(--accent) 55%, var(--line));
  padding-bottom: .5rem; margin: 0 0 clamp(.9rem, 2.4vw, 1.3rem);
}
[data-theme-layout="circuit"] .cir-ics-t {
  margin: 0; font-family: var(--mono); font-size: .74rem; font-weight: 700;
  letter-spacing: .2em; text-transform: uppercase; color: var(--ink);
}
[data-theme-layout="circuit"] .cir-ics-all {
  display: inline-flex; align-items: center; gap: .3rem; flex: 0 0 auto;
  font-family: var(--mono); font-size: .72rem; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase;
  color: var(--accent); text-decoration: none; transition: color .15s;
}
[data-theme-layout="circuit"] .cir-ics-all:hover { color: var(--accent-soft); }
[data-theme-layout="circuit"] .cir-ics-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(265px, 1fr));
  gap: clamp(.8rem, 2vw, 1.2rem);
  counter-reset: cir-u 1;
}
[data-theme-layout="circuit"] .cir-ic { counter-increment: cir-u; min-width: 0; display: flex; }
[data-theme-layout="circuit"] .cir-ic-in {
  position: relative; flex: 1;
  display: flex; flex-direction: column; gap: .5rem;
  padding: .95rem 1rem .85rem; padding-left: calc(1rem + 22px);
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  text-decoration: none; color: var(--ink);
  transition: border-color .15s;
}
[data-theme-layout="circuit"] .cir-ic-in:hover { border-color: var(--accent); }
/* 小一号引脚线：22px 车道（padding 预留），无发光焊点 */
[data-theme-layout="circuit"] .cir-ic-in::before {
  content: ""; position: absolute; left: 8px; top: 16%; bottom: 16%; width: 8px;
  background-image: repeating-linear-gradient(to bottom,
    transparent 0 5px, color-mix(in srgb, var(--accent) 55%, var(--surface)) 5px 7px, transparent 7px 12px);
  pointer-events: none;
}
[data-theme-layout="circuit"] .cir-ic-cover { display: block; overflow: hidden; border: 1px solid var(--line); border-radius: calc(var(--radius) - 4px); }
[data-theme-layout="circuit"] .cir-ic-cover img { display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; object-fit: cover; }
[data-theme-layout="circuit"] .cir-ic-h { font-size: 1.08rem; font-weight: 700; line-height: 1.3; overflow-wrap: anywhere; transition: color .15s; }
[data-theme-layout="circuit"] .cir-ic-in:hover .cir-ic-h { color: var(--accent-soft); }
[data-theme-layout="circuit"] .cir-ic-ex {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .88rem; line-height: 1.58; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- edge: 板缘页脚——链接行 + 金手指条（定高装饰，钳死不撑页） ----------- */
[data-theme-layout="circuit"] .cir-edge {
  display: flex; flex-wrap: wrap; justify-content: center; align-items: baseline; gap: .7rem;
  margin-top: clamp(1.6rem, 4vw, 2.4rem); padding-top: .95rem;
  border-top: 1px dashed color-mix(in srgb, var(--line) 75%, var(--accent));
  font-family: var(--mono); font-size: .84rem; letter-spacing: .08em;
  text-transform: uppercase; color: var(--muted);
}
[data-theme-layout="circuit"] .cir-edge::after {
  content: ""; flex-basis: 100%; height: 10px; max-width: 380px;
  margin: .8rem auto 0;
  background-image: repeating-linear-gradient(90deg,
    color-mix(in srgb, var(--accent) 78%, var(--bg)) 0 16px, transparent 16px 26px);
  border-radius: 2px;
}
[data-theme-layout="circuit"] .cir-edge a { color: var(--ink-soft); text-decoration: none; transition: color .15s; }
[data-theme-layout="circuit"] .cir-edge a:hover { color: var(--accent-soft); }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="circuit"] .cir-mcu { grid-template-columns: minmax(0, 1fr); align-items: stretch; }
  [data-theme-layout="circuit"] .cir-mcu-cover { order: -1; }
}
@media (max-width: 720px) {
  [data-theme-layout="circuit"] .cir-board { padding: 1rem .9rem 1.2rem; }
  [data-theme-layout="circuit"] .cir-title { font-size: clamp(1.35rem, 6.4vw, 1.8rem); letter-spacing: .03em; }
  /* 引脚装饰归位：车道伪元素撤下，内边距还原普通流 */
  [data-theme-layout="circuit"] .cir-mcu::before,
  [data-theme-layout="circuit"] .cir-mcu::after,
  [data-theme-layout="circuit"] .cir-ic-in::before { display: none; }
  [data-theme-layout="circuit"] .cir-mcu { padding-left: clamp(1rem, 2.8vw, 1.6rem); }
  [data-theme-layout="circuit"] .cir-ic-in { padding-left: 1rem; }
  [data-theme-layout="circuit"] .cir-ics-grid { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="circuit"] .cir-pinrow { row-gap: .25rem; }
  [data-theme-layout="circuit"] .cir-mcu-more { margin-left: 0; flex-basis: 100%; }
}

/* ---- reduced motion：焊点不呼吸（静态可见），过渡全关 -------------------- */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="circuit"] .cir-mcu::after { animation: none; }
  [data-theme-layout="circuit"] .cir-mcu,
  [data-theme-layout="circuit"] .cir-mcu-h,
  [data-theme-layout="circuit"] .cir-mcu-more,
  [data-theme-layout="circuit"] .cir-bus-pin,
  [data-theme-layout="circuit"] .cir-bus-all,
  [data-theme-layout="circuit"] .cir-jack,
  [data-theme-layout="circuit"] .cir-jack-t,
  [data-theme-layout="circuit"] .cir-ic-in,
  [data-theme-layout="circuit"] .cir-ic-h,
  [data-theme-layout="circuit"] .cir-ics-all,
  [data-theme-layout="circuit"] .cir-edge a { transition: none; }
}

/* ============================================================
   电路 · Circuit —— Circuit 骨架默认皮：PCB 深绿、铜金丝印、浅绿白字
   （设计稿铜金 #c8933f 对 surface 只有 4.27，压亮到 #cf9d4a=4.76 达标；
   hover 走更亮的 soft #e3ba75=6.41 只升）
   ============================================================ */
:root[data-theme="circuit"] {
  --bg: #143324; --surface: #16402b;
  --ink: #eaf5e9; --ink-soft: #cfe3cf; --muted: #a8c4ab; --faint: #7fa287;
  --line: #2f5f45; --line-soft: #24503a;
  --accent: #cf9d4a; --accent-soft: #e3ba75; --accent-wash: #1d4a33;
  --w-wide: 1200px; --radius: 10px; --code-bg: #0d2418;
  --shadow: 0 1px 2px rgba(0, 0, 0, .45), 0 12px 30px rgba(0, 0, 0, .4);
}
/* 铜金实底上走深字（bg 对 accent 5.61），别用默认白字 */
:root[data-theme="circuit"] .btn-primary { color: #143324; }
:root[data-theme="circuit"] .site-header { background: var(--bg); }

/* ============================================================
   蓝图 · Bluetrace —— Circuit 骨架 + 工程蓝图皮：工程蓝底、白细线网格、冰蓝强调
   ============================================================ */
:root[data-theme="bluetrace"] {
  --bg: #12365c; --surface: #174270;
  --ink: #f1f6fb; --ink-soft: #cddeed; --muted: #a5c1d8; --faint: #7fa3c2;
  --line: #3c6790; --line-soft: #2b5480;
  --accent: #8fd9f2; --accent-soft: #b6e7f9; --accent-wash: #1b4a78;
  --w-wide: 1200px; --radius: 10px; --code-bg: #0c2a4a;
  --shadow: 0 1px 2px rgba(0, 0, 0, .4), 0 12px 30px rgba(0, 0, 0, .35);
}
/* 冰蓝实底上走深字（bg 对 accent 7.83） */
:root[data-theme="bluetrace"] .btn-primary { color: #12365c; }
:root[data-theme="bluetrace"] .site-header { background: var(--bg); }
/* 板面改蓝图网格纹：白细线双尺度（24px 细格 + 120px 粗格），铜边转白线 */
:root[data-theme="bluetrace"] .cir-board {
  background-image:
    linear-gradient(rgba(255, 255, 255, .05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, .05) 1px, transparent 1px),
    linear-gradient(rgba(255, 255, 255, .1) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, .1) 1px, transparent 1px);
  background-size: 24px 24px, 24px 24px, 120px 120px, 120px 120px;
  border-color: color-mix(in srgb, #ffffff 45%, var(--bg));
}
/* 主控芯片描边也转白细线；hover 回冰蓝（后写覆盖，只升不降） */
:root[data-theme="bluetrace"] .cir-mcu { border-color: color-mix(in srgb, #ffffff 62%, var(--bg)); }
:root[data-theme="bluetrace"] .cir-mcu:hover { border-color: var(--accent-soft); }

/* ============================================================
   电路纯白 · Circuit White —— 中性灰基底（照抄纯白系），铜金压深：
   #8a5c10 on #fff 5.80 / hover soft #6e480c 8.09 只升；
   卡面回纯白（muted 4.57 达标，#fafaf8 上 4.38 的坑避开），desc 压深 ink-soft
   ============================================================ */
:root[data-theme="circuit-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #8a5c10; --accent-soft: #6e480c; --accent-wash: #f6efdd;
  --w-wide: 1200px; --radius: 10px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .05), 0 8px 22px rgba(16, 18, 24, .06);
}
:root[data-theme="circuit-white"] .btn-primary { color: #fff; }
/* 板面浅灰当底板，芯片/接插件/总线卡面全部回 --bg 纯白 */
:root[data-theme="circuit-white"] .cir-board { background-color: var(--surface); }
:root[data-theme="circuit-white"] .cir-mcu,
:root[data-theme="circuit-white"] .cir-ic-in,
:root[data-theme="circuit-white"] .cir-jack,
:root[data-theme="circuit-white"] .cir-bus-pin { background: var(--bg); }
/* hover 描边跟着还原（同权重后写会盖掉布局段 hover，重申一遍） */
:root[data-theme="circuit-white"] .cir-mcu:hover { border-color: var(--accent-soft); }
:root[data-theme="circuit-white"] .cir-ic-in:hover,
:root[data-theme="circuit-white"] .cir-jack:hover { border-color: var(--accent); }
:root[data-theme="circuit-white"] .cir-bus-pin:hover { border-color: var(--accent); }
/* Hero 描述落在 #fafaf8 板面：muted 4.38 不够，压深到 ink-soft 9.37 */
:root[data-theme="circuit-white"] .cir-desc { color: var(--ink-soft); }

/* =========================================================================
   LAYOUT: specimen — 标本 botanical atlas plate home (pure CSS, no JS)
   every selector scoped under [data-theme-layout="specimen"], classes spc-*
   衬线图鉴大页：象牙台面上一张图版纸（.spc-sheet）；顶部 PLATE 罗马数字装饰行
   + HeroTitle 字距行；大标本区 = Featured 两栏（左图版框 aspect-ratio 钳高：
   有图用图 / 无图内联 SVG 叶脉线描 + 左上针脚圆点；右 = 拉丁式斜体副题 +
   大标题 + 摘要 + 采集地边框签）；FIG. N 小标本卡三列（CSS 计数器编号，
   Featured 视作 FIG.Ⅰ，针脚钉在卡内 padding 车道上、与文字不相交）；
   页脚 = 图例式 colophon（分类当图例条目）。页头只做衬线小型大写化重塑
   ========================================================================= */
[data-theme-layout="specimen"] main { display: block; }
[data-theme-layout="specimen"] .spc-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-block: clamp(1.5rem, 4vw, 2.6rem) clamp(3rem, 6vw, 5rem);
}
[data-theme-layout="specimen"] .spc-sheet {
  background: var(--surface); border: 1px solid var(--line); box-shadow: var(--shadow);
  padding: clamp(1.4rem, 4vw, 2.6rem) clamp(1.1rem, 3.5vw, 2.4rem) clamp(1.5rem, 4vw, 2.2rem);
}

/* ---- shared chrome: serif small-caps restyle only（抽屉行为不动） --------- */
[data-theme-layout="specimen"] .site-header { background: var(--bg); border-bottom: 1px solid var(--line); }
[data-theme-layout="specimen"] .site-header .brand { font-family: var(--serif); font-variant: small-caps; letter-spacing: .14em; }
[data-theme-layout="specimen"] .site-footer { border-top: 1px solid var(--line); background: var(--bg); }
@media (min-width: 621px) {
  [data-theme-layout="specimen"] .site-header .nav a { font-family: var(--serif); font-variant: small-caps; letter-spacing: .1em; }
}

/* ---- plate line: roman ornament / letterspaced atlas name / italic sub -- */
[data-theme-layout="specimen"] .spc-plateline { text-align: center; margin: 0 0 clamp(1.4rem, 3.5vw, 2.2rem); }
[data-theme-layout="specimen"] .spc-plate-no {
  display: flex; align-items: center; justify-content: center; gap: .9rem;
  margin: 0 0 .7rem; font-family: var(--sans); font-size: .7rem;
  letter-spacing: .42em; text-indent: .42em; color: var(--muted);
}
[data-theme-layout="specimen"] .spc-plate-no::before,
[data-theme-layout="specimen"] .spc-plate-no::after {
  content: ""; flex: 0 1 clamp(28px, 8vw, 72px); height: 1px; background: var(--line);
}
[data-theme-layout="specimen"] .spc-plate-name {
  margin: 0; font-family: var(--serif); font-weight: 700;
  font-size: clamp(1.7rem, 4.6vw, 2.7rem); line-height: 1.22;
  letter-spacing: .16em; text-indent: .16em; color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="specimen"] .spc-plate-sub {
  margin: .55rem auto 0; max-width: 60ch;
  font-family: var(--serif); font-style: italic; font-size: .95rem; line-height: 1.6;
  color: var(--muted); overflow-wrap: anywhere;
}

/* ---- featured: fig frame (pin dot lane = frame corner) + description ---- */
[data-theme-layout="specimen"] .spc-front { border-bottom: 1px solid var(--line-soft); padding-bottom: clamp(1.3rem, 3vw, 1.9rem); }
[data-theme-layout="specimen"] .spc-feat {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(1.2rem, 3vw, 2rem); align-items: start;
  text-decoration: none; color: var(--ink);
}
[data-theme-layout="specimen"] .spc-figbox {
  position: relative; display: grid; place-items: center; overflow: hidden;
  aspect-ratio: 4 / 3; min-width: 0;
  background: var(--accent-wash); border: 1px solid var(--line);
}
[data-theme-layout="specimen"] .spc-figbox::before {
  content: ""; position: absolute; left: 12px; top: 12px; z-index: 1;
  width: 7px; height: 7px; border-radius: 50%; background: var(--faint);
  box-shadow: 0 0 0 2px var(--surface);
}
[data-theme-layout="specimen"] .spc-figbox img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="specimen"] .spc-leaf { width: 56%; max-height: 82%; color: var(--accent); opacity: .85; }
[data-theme-layout="specimen"] .spc-desc { display: flex; flex-direction: column; gap: .55rem; min-width: 0; }
[data-theme-layout="specimen"] .spc-kicker {
  align-self: flex-start; font-family: var(--sans); font-size: .68rem; font-weight: 800;
  letter-spacing: .24em; text-transform: uppercase; color: var(--accent);
  border-bottom: 2px solid var(--accent); padding-bottom: .28rem;
}
[data-theme-layout="specimen"] .spc-latin {
  font-family: var(--serif); font-style: italic; font-size: .98rem; line-height: 1.5;
  color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="specimen"] .spc-feat-t {
  font-family: var(--serif); font-weight: 700;
  font-size: clamp(1.45rem, 3.2vw, 2.05rem); line-height: 1.22;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="specimen"] .spc-feat:hover .spc-feat-t { color: var(--accent); }
[data-theme-layout="specimen"] .spc-feat-ex {
  display: -webkit-box; -webkit-line-clamp: 5; -webkit-box-orient: vertical; overflow: hidden;
  font-family: var(--serif); font-size: .98rem; line-height: 1.8; color: var(--ink-soft);
  overflow-wrap: anywhere;
}
[data-theme-layout="specimen"] .spc-feat-foot {
  display: flex; flex-wrap: wrap; align-items: center; gap: .5rem .9rem; margin-top: .25rem;
}
[data-theme-layout="specimen"] .spc-tag {
  border: 1px solid var(--faint); background: var(--accent-wash);
  font-family: var(--sans); font-size: .68rem; letter-spacing: .16em;
  padding: .3rem .8rem; color: var(--ink-soft); overflow-wrap: anywhere;
}
[data-theme-layout="specimen"] .spc-date {
  font-family: var(--mono); font-size: .74rem; letter-spacing: .04em;
  font-variant-numeric: tabular-nums; color: var(--muted);
}
[data-theme-layout="specimen"] .spc-more {
  display: inline-flex; align-items: center; gap: .35rem; margin-left: auto;
  font-family: var(--sans); font-size: .7rem; font-weight: 700;
  letter-spacing: .12em; text-transform: uppercase; color: var(--accent); transition: color .15s;
}
[data-theme-layout="specimen"] .spc-feat:hover .spc-more { color: var(--accent-soft); }

/* ---- section head: rule-flanked centered strip -------------------------- */
[data-theme-layout="specimen"] .spc-figs,
[data-theme-layout="specimen"] .spc-index { margin-top: clamp(1.4rem, 3.5vw, 2rem); }
[data-theme-layout="specimen"] .spc-head {
  display: flex; align-items: baseline; justify-content: center; flex-wrap: wrap;
  gap: .3rem 1rem; margin: 0 0 clamp(.9rem, 2.5vw, 1.3rem);
}
[data-theme-layout="specimen"] .spc-head::before,
[data-theme-layout="specimen"] .spc-head::after {
  content: ""; flex: 1 1 24px; align-self: center; height: 1px; background: var(--line-soft);
}
[data-theme-layout="specimen"] .spc-head-t {
  margin: 0; font-family: var(--sans); font-size: .74rem; font-weight: 800;
  letter-spacing: .3em; text-indent: .3em; text-transform: uppercase;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="specimen"] .spc-head-all {
  min-width: 0; font-family: var(--sans); font-size: .7rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase; color: var(--accent);
  text-decoration: none; transition: color .15s;
}
[data-theme-layout="specimen"] .spc-head-all:hover { color: var(--accent-soft); }

/* ---- FIG minis: 3-col pinned cards, CSS counter (featured = FIG.Ⅰ) ------ */
[data-theme-layout="specimen"] .spc-minis {
  counter-reset: spcfig 1;
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(.7rem, 2vw, 1.1rem);
}
[data-theme-layout="specimen"] .spc-mini {
  counter-increment: spcfig;
  position: relative; display: flex; flex-direction: column; gap: .4rem; min-width: 0;
  border: 1px solid var(--line); background: var(--surface);
  padding: .8rem 2rem .85rem .95rem; /* 右侧 2rem = 针脚专属车道 */
  text-decoration: none; color: var(--ink); transition: border-color .15s;
}
[data-theme-layout="specimen"] .spc-mini::after {
  content: ""; position: absolute; right: 10px; top: 12px;
  width: 5px; height: 5px; border-radius: 50%; background: var(--faint);
}
[data-theme-layout="specimen"] .spc-mini:hover { border-color: var(--accent); }
[data-theme-layout="specimen"] .spc-fig-no {
  font-family: var(--sans); font-size: .64rem; letter-spacing: .16em; color: var(--muted);
}
[data-theme-layout="specimen"] .spc-fig-no::before { content: "FIG. " counter(spcfig); }
[data-theme-layout="specimen"] .spc-mini-t {
  font-family: var(--serif); font-weight: 700; font-size: 1.02rem; line-height: 1.35;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="specimen"] .spc-mini:hover .spc-mini-t { color: var(--accent); }
[data-theme-layout="specimen"] .spc-mini-meta {
  display: flex; flex-wrap: wrap; gap: .45rem; font-family: var(--sans);
  font-size: .72rem; letter-spacing: .06em; color: var(--muted);
}
[data-theme-layout="specimen"] .spc-mini-cat { overflow-wrap: anywhere; }

/* ---- index: FeatLinks as dashed herbarium pockets ----------------------- */
[data-theme-layout="specimen"] .spc-index-grid {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(.7rem, 2vw, 1rem);
}
[data-theme-layout="specimen"] .spc-card {
  display: flex; align-items: flex-start; gap: .7rem; min-width: 0;
  border: 1px dashed var(--line); background: var(--surface); padding: .7rem .85rem;
  text-decoration: none; color: var(--ink); transition: border-color .15s;
}
[data-theme-layout="specimen"] .spc-card:hover { border-color: var(--accent); }
[data-theme-layout="specimen"] .spc-card-ic {
  flex: 0 0 auto; width: 40px; height: 40px; overflow: hidden;
  display: grid; place-items: center; border: 1px solid var(--line); border-radius: 50%;
  background: var(--accent-wash); color: var(--accent);
}
[data-theme-layout="specimen"] .spc-card-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="specimen"] .spc-card-ic b { font-family: var(--serif); font-weight: 700; font-size: 1.05rem; line-height: 1; }
[data-theme-layout="specimen"] .spc-card-body { min-width: 0; }
[data-theme-layout="specimen"] .spc-card-t {
  display: block; font-family: var(--serif); font-weight: 700;
  font-size: .98rem; line-height: 1.3; overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="specimen"] .spc-card:hover .spc-card-t { color: var(--accent); }
[data-theme-layout="specimen"] .spc-card-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  margin-top: .15rem; font-size: .8rem; line-height: 1.45; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- colophon: legend-style（分类当图例条目 + 索引链接） ------------------ */
[data-theme-layout="specimen"] .spc-colophon {
  margin-top: clamp(1.6rem, 4vw, 2.4rem); padding-top: 1rem;
  border-top: 4px double var(--line); text-align: center;
}
[data-theme-layout="specimen"] .spc-legend {
  display: flex; flex-wrap: wrap; justify-content: center;
  gap: .45rem 1.4rem; margin-bottom: .8rem;
}
[data-theme-layout="specimen"] .spc-leg {
  display: inline-flex; align-items: baseline; gap: .45rem; min-width: 0;
  font-family: var(--serif); font-variant: small-caps; letter-spacing: .1em;
  font-size: .95rem; color: var(--ink-soft); text-decoration: none; transition: color .15s;
}
[data-theme-layout="specimen"] .spc-leg:hover { color: var(--accent); }
[data-theme-layout="specimen"] .spc-leg-dot {
  flex: 0 0 auto; align-self: center; width: 6px; height: 6px;
  border-radius: 50%; border: 1px solid var(--accent);
}
[data-theme-layout="specimen"] .spc-leg-name { overflow-wrap: anywhere; }
[data-theme-layout="specimen"] .spc-leg-n { font-variant: normal; font-size: .68rem; color: var(--muted); }
[data-theme-layout="specimen"] .spc-colophon-links {
  display: flex; justify-content: center; align-items: baseline; gap: .8rem;
  font-family: var(--serif); font-variant: small-caps; letter-spacing: .12em;
  font-size: .92rem; color: var(--muted);
}
[data-theme-layout="specimen"] .spc-colophon-links a { color: var(--ink-soft); text-decoration: none; transition: color .15s; }
[data-theme-layout="specimen"] .spc-colophon-links a:hover { color: var(--accent); }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="specimen"] .spc-feat { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="specimen"] .spc-minis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  [data-theme-layout="specimen"] .spc-plate-name { font-size: clamp(1.45rem, 6.4vw, 1.9rem); letter-spacing: .08em; text-indent: .08em; }
  [data-theme-layout="specimen"] .spc-plate-no { letter-spacing: .3em; text-indent: .3em; }
  [data-theme-layout="specimen"] .spc-minis,
  [data-theme-layout="specimen"] .spc-index-grid { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="specimen"] .spc-more { margin-left: 0; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="specimen"] .spc-feat-t,
  [data-theme-layout="specimen"] .spc-more,
  [data-theme-layout="specimen"] .spc-head-all,
  [data-theme-layout="specimen"] .spc-mini,
  [data-theme-layout="specimen"] .spc-mini-t,
  [data-theme-layout="specimen"] .spc-card,
  [data-theme-layout="specimen"] .spc-card-t,
  [data-theme-layout="specimen"] .spc-leg,
  [data-theme-layout="specimen"] .spc-colophon-links a { transition: none; }
}

/* ============================================================
   标本 · Specimen —— Specimen 骨架默认皮：象牙台面、图版纸、标本褐、墨字
   （实算见 notes：ink/纸 14.74、ink-soft 正文/纸 8.07、muted/纸 5.32、
     accent 褐作字/纸 6.83，hover 走 soft #423e26 10.12 只升不降）
   ============================================================ */
:root[data-theme="specimen"] {
  --bg: #f4f1e6; --surface: #faf8ee;
  --ink: #26231b; --ink-soft: #514c3a; --muted: #6d6750; --faint: #8a8468;
  --line: #d8d2ba; --line-soft: #e4ddc6;
  --accent: #5d5738; --accent-soft: #423e26; --accent-wash: #efe9d2;
  --w-wide: 1140px; --radius: 0px;
  --shadow: 0 1px 2px rgba(38, 35, 27, .05), 0 10px 26px rgba(38, 35, 27, .08);
}
:root[data-theme="specimen"] .btn-primary { color: #fff; }
:root[data-theme="specimen"] .site-header { background: var(--bg); }

/* ============================================================
   夜馆 · Nightplate —— Specimen 骨架 + 墨绿深底鎏金图版夜馆皮（暖纸字）
   （实算见 notes：暖纸 ink/深面 11.89、ink-soft 8.89、muted 5.58、
     鎏金 accent 作字 8.63，hover soft #e6dba6 10.28 只升不降；图版框描金）
   ============================================================ */
:root[data-theme="nightplate"] {
  --bg: #15241c; --surface: #1c2e23;
  --ink: #f0ead2; --ink-soft: #d3ccae; --muted: #a8a284; --faint: #79755c;
  --line: #3a4d3f; --line-soft: #2a3c30;
  --accent: #d8c98a; --accent-soft: #e6dba6; --accent-wash: #24382b;
  --w-wide: 1140px; --radius: 0px; --code-bg: #0f1a14;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 14px 34px rgba(0, 0, 0, .5);
}
:root[data-theme="nightplate"] .btn-primary { color: #15241c; }
:root[data-theme="nightplate"] .site-header { background: rgba(21, 36, 28, .92); }
/* 鎏金图版框 + 针脚描金（描金圈衬深底，对比只升） */
:root[data-theme="nightplate"] .spc-figbox { border-color: var(--accent); }
:root[data-theme="nightplate"] .spc-figbox::before { background: var(--accent); box-shadow: 0 0 0 2px var(--bg); }
:root[data-theme="nightplate"] .spc-tag { border-color: var(--muted); }

/* ============================================================
   标本纯白 · Specimen White —— 第五批纯白系：中性灰基底照抄纯白段，
   标本褐族色相压在白底 7.27（hover soft #423e26 10.77 只升不降）；
   muted #707680 只在 --bg 纯白作字（4.57），故图版纸/小卡/索引卡底改 --bg
   ============================================================ */
:root[data-theme="specimen-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #707680; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #5d5738; --accent-soft: #423e26; --accent-wash: #f2efdd;
  --w-wide: 1140px; --radius: 0px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .04), 0 10px 26px rgba(16, 18, 24, .07);
}
:root[data-theme="specimen-white"] .btn-primary { color: #fff; }
:root[data-theme="specimen-white"] .spc-sheet,
:root[data-theme="specimen-white"] .spc-mini,
:root[data-theme="specimen-white"] .spc-card { background: var(--bg); }

/* =========================================================================
   LAYOUT: lockers — 储物柜 locker-wall home (pure CSS, no JS)
   every selector scoped under [data-theme-layout="lockers"], classes lkr-*
   一墙柜门四列网格：每门=通风百叶（repeating-linear-gradient 短横条，钳定
   48×24 固定尺寸）+右上号码牌（等宽 counter 三位数，"1"+leading-zero=101 起）
   +标题+分类·日期；Featured=打开的门跨两列两行：左缘斜门板伪元素（专属车道
   =padding-left 预留 34px，任何宽度都不与文字相交）+浅色内里+阅读胶囊；
   Categories=顶部柜区索引条（金属条上名字+反白 Count 胶囊）；
   FeatLinks=底部失物招领小卡行。hover 一律加框/下划线/上浮，不动字色对比
   ========================================================================= */
[data-theme-layout="lockers"] main { display: block; }
[data-theme-layout="lockers"] .lkr-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-block: clamp(1.6rem, 4vw, 2.6rem) clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: utility header on the wall colour -------------------- */
[data-theme-layout="lockers"] .site-header { background: var(--bg); border-bottom: 1px solid var(--line); }
[data-theme-layout="lockers"] .site-header .brand { font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
[data-theme-layout="lockers"] .site-footer { border-top: 1px solid var(--line); background: var(--bg); }
@media (min-width: 621px) {
  [data-theme-layout="lockers"] .site-header .nav > a {
    font-size: .8rem; font-weight: 600; letter-spacing: .12em; text-transform: uppercase;
  }
}

/* ---- hero ---------------------------------------------------------------- */
[data-theme-layout="lockers"] .lkr-hero { margin: 0 0 clamp(1.1rem, 2.6vw, 1.6rem); }
[data-theme-layout="lockers"] .lkr-eyebrow {
  margin: 0 0 .5rem; font-family: var(--mono); font-size: .74rem;
  letter-spacing: .3em; text-transform: uppercase; color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="lockers"] .lkr-title {
  margin: 0 0 .55rem; font-weight: 800;
  font-size: clamp(2rem, 5.2vw, 3.2rem); line-height: 1.08; letter-spacing: -.015em;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="lockers"] .lkr-lede {
  margin: 0; max-width: 58ch;
  font-size: 1rem; line-height: 1.62; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- zones: locker-bay index strip (name + inverted count capsule) ------- */
[data-theme-layout="lockers"] .lkr-zones {
  display: flex; flex-wrap: wrap; align-items: center; gap: .2rem .3rem;
  margin: 0 0 clamp(1.4rem, 3.2vw, 2rem); padding: .45rem .6rem;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 30%, transparent),
              inset 0 -6px 12px color-mix(in srgb, var(--ink) 8%, transparent);
}
[data-theme-layout="lockers"] .lkr-zone {
  display: inline-flex; align-items: center; gap: .45rem; min-width: 0;
  padding: .28rem .65rem; border-radius: 6px;
  font-size: .86rem; font-weight: 600; color: var(--ink); text-decoration: none;
}
[data-theme-layout="lockers"] .lkr-zone:hover .lkr-zone-name { text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="lockers"] .lkr-zone-name { overflow-wrap: anywhere; }
[data-theme-layout="lockers"] .lkr-zone-n {
  flex: 0 0 auto; padding: .1rem .45rem; border-radius: 999px;
  background: var(--ink); color: var(--bg);
  font-family: var(--mono); font-size: .66rem; line-height: 1.3; font-variant-numeric: tabular-nums;
}
[data-theme-layout="lockers"] .lkr-zone-all { margin-left: auto; font-weight: 700; }
[data-theme-layout="lockers"] .lkr-zone-all:hover { text-decoration: underline; text-underline-offset: 3px; }

/* ---- wall head ----------------------------------------------------------- */
[data-theme-layout="lockers"] .lkr-wall-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  margin: 0 0 .9rem; padding-bottom: .45rem; border-bottom: 2px solid var(--ink);
}
[data-theme-layout="lockers"] .lkr-wall-t {
  margin: 0; font-size: .8rem; font-weight: 800;
  letter-spacing: .24em; text-transform: uppercase; color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="lockers"] .lkr-wall-all {
  flex: 0 0 auto; display: inline-flex; align-items: center; gap: .3rem;
  font-size: .74rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: var(--accent); text-decoration: none; transition: color .15s;
}
[data-theme-layout="lockers"] .lkr-wall-all:hover { color: var(--accent-soft); text-decoration: underline; text-underline-offset: 3px; }

/* ---- the wall: 4-column locker grid, numbered by CSS counter ------------- */
[data-theme-layout="lockers"] .lkr-grid {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: clamp(.7rem, 1.6vw, 1.1rem);
  counter-reset: lkr;
}
[data-theme-layout="lockers"] .lkr-open,
[data-theme-layout="lockers"] .lkr-door { counter-increment: lkr; }

/* number plate: fixed-width mono digits, engraved chip (skin can re-colour) */
[data-theme-layout="lockers"] .lkr-plate {
  flex: 0 0 auto; display: inline-block; padding: .16rem .42rem; border-radius: 4px;
  background: var(--ink); color: var(--bg);
  font-family: var(--mono); font-size: .72rem; line-height: 1;
  letter-spacing: .08em; font-variant-numeric: tabular-nums;
  box-shadow: inset 0 -1px 0 color-mix(in srgb, #fff 22%, transparent);
}
[data-theme-layout="lockers"] .lkr-plate::after { content: "1" counter(lkr, decimal-leading-zero); }

/* closed door: louvre vents + plate on top, title, meta pinned to bottom */
[data-theme-layout="lockers"] .lkr-door { display: flex; min-width: 0; }
[data-theme-layout="lockers"] .lkr-door-in {
  display: flex; flex-direction: column; gap: .6rem; flex: 1 1 auto; min-width: 0;
  min-height: 186px; padding: .85rem .9rem 1rem;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 32%, transparent),
              inset 0 -12px 22px color-mix(in srgb, var(--ink) 12%, transparent),
              var(--shadow);
  text-decoration: none; color: var(--ink);
  transition: border-color .15s, transform .15s;
}
[data-theme-layout="lockers"] .lkr-door-in:hover { border-color: var(--accent); transform: translateY(-2px); }
[data-theme-layout="lockers"] .lkr-door-top { display: flex; align-items: center; justify-content: space-between; gap: .6rem; }
/* 百叶：短横条 repeating-gradient，48×24 固定尺寸（钳高，绝不撑格） */
[data-theme-layout="lockers"] .lkr-vents {
  flex: 0 0 auto; width: 48px; height: 24px; border-radius: 3px;
  background: repeating-linear-gradient(180deg,
    color-mix(in srgb, var(--ink) 38%, var(--surface)) 0 3px, transparent 3px 8px);
}
[data-theme-layout="lockers"] .lkr-door-t {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  font-weight: 700; font-size: 1.02rem; line-height: 1.35; overflow-wrap: anywhere;
}
[data-theme-layout="lockers"] .lkr-door-in:hover .lkr-door-t { text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
[data-theme-layout="lockers"] .lkr-door-meta {
  margin-top: auto; display: flex; flex-wrap: wrap; gap: .35rem; min-width: 0;
  font-family: var(--mono); font-size: .72rem; letter-spacing: .04em;
  font-variant-numeric: tabular-nums; color: var(--muted);
}
[data-theme-layout="lockers"] .lkr-door-cat { text-transform: uppercase; overflow-wrap: anywhere; }

/* opened door (featured): spans 2×2, slanted panel on a reserved left lane */
[data-theme-layout="lockers"] .lkr-open {
  grid-column: span 2; grid-row: span 2;
  position: relative; overflow: hidden; min-width: 0;
  display: flex; flex-direction: column; gap: .7rem;
  padding: 1.1rem 1.2rem 1.15rem; padding-left: calc(34px + 1.15rem);
  background: var(--accent-wash); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 32%, transparent), var(--shadow);
  text-decoration: none; color: var(--ink);
  transition: border-color .15s, transform .15s;
}
[data-theme-layout="lockers"] .lkr-open::before {
  /* 斜门板：占住 34px 专属车道（内容 padding-left 已让位），不与文字相交 */
  content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 34px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--ink) 26%, var(--surface)), var(--surface));
  clip-path: polygon(0 0, 100% 5%, 100% 95%, 0 100%);
}
[data-theme-layout="lockers"] .lkr-open:hover { border-color: var(--accent); transform: translateY(-2px); }
[data-theme-layout="lockers"] .lkr-open-top { display: flex; align-items: flex-start; justify-content: space-between; gap: .7rem; }
[data-theme-layout="lockers"] .lkr-kicker {
  display: inline-flex; flex-wrap: wrap; align-items: baseline; gap: .5rem; min-width: 0;
  font-size: .7rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; color: var(--accent);
}
[data-theme-layout="lockers"] .lkr-kicker-cat { color: var(--ink-soft); overflow-wrap: anywhere; }
[data-theme-layout="lockers"] .lkr-open-t {
  font-weight: 800; font-size: clamp(1.35rem, 2.6vw, 1.9rem); line-height: 1.2; overflow-wrap: anywhere;
}
[data-theme-layout="lockers"] .lkr-open:hover .lkr-open-t { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 4px; }
[data-theme-layout="lockers"] .lkr-open-cover {
  display: block; overflow: hidden;
  border: 1px solid var(--line); border-radius: calc(var(--radius) - 4px);
}
[data-theme-layout="lockers"] .lkr-open-cover img { display: block; width: 100%; height: auto; max-height: 240px; object-fit: cover; }
[data-theme-layout="lockers"] .lkr-open-ex {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .95rem; line-height: 1.6; color: var(--ink-soft); overflow-wrap: anywhere;
}
[data-theme-layout="lockers"] .lkr-open-foot {
  margin-top: auto; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: .5rem .8rem;
}
[data-theme-layout="lockers"] .lkr-open-foot time {
  font-family: var(--mono); font-size: .76rem; letter-spacing: .04em;
  font-variant-numeric: tabular-nums; color: var(--ink-soft);
}
[data-theme-layout="lockers"] .lkr-cap {
  display: inline-flex; align-items: center; gap: .4rem;
  padding: .5rem 1.1rem; border-radius: 999px;
  background: var(--accent); color: #fff;
  font-size: .74rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  transition: background .15s;
}
[data-theme-layout="lockers"] .lkr-open:hover .lkr-cap { background: var(--accent-soft); }

/* ---- lost & found: small tag-card row ------------------------------------ */
[data-theme-layout="lockers"] .lkr-lost { margin-top: clamp(2rem, 5vw, 3rem); }
[data-theme-layout="lockers"] .lkr-lost-h {
  margin: 0 0 .9rem; padding-bottom: .45rem; border-bottom: 1px solid var(--line);
  font-size: .8rem; font-weight: 800; letter-spacing: .24em; text-transform: uppercase;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="lockers"] .lkr-lost-row {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: clamp(.7rem, 1.6vw, 1rem);
}
[data-theme-layout="lockers"] .lkr-tag {
  display: flex; align-items: center; gap: .7rem; min-width: 0;
  padding: .7rem .85rem;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 32%, transparent);
  text-decoration: none; color: var(--ink);
  transition: border-color .15s, transform .15s;
}
[data-theme-layout="lockers"] .lkr-tag:hover { border-color: var(--accent); transform: translateY(-2px); }
[data-theme-layout="lockers"] .lkr-tag-ic {
  flex: 0 0 auto; width: 42px; height: 42px; overflow: hidden;
  display: grid; place-items: center; border-radius: 8px;
  background: var(--ink); color: var(--bg);
}
[data-theme-layout="lockers"] .lkr-tag-ic b { font-family: var(--mono); font-weight: 800; font-size: 1.1rem; line-height: 1; }
[data-theme-layout="lockers"] .lkr-tag-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="lockers"] .lkr-tag-body { min-width: 0; }
[data-theme-layout="lockers"] .lkr-tag-t {
  display: block; font-weight: 700; font-size: .95rem; line-height: 1.3; overflow-wrap: anywhere;
}
[data-theme-layout="lockers"] .lkr-tag:hover .lkr-tag-t { text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="lockers"] .lkr-tag-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  margin-top: .15rem; font-size: .78rem; line-height: 1.45; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="lockers"] .lkr-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="lockers"] .lkr-open { grid-column: 1 / -1; grid-row: auto; }
  [data-theme-layout="lockers"] .lkr-door-in { min-height: 160px; }
}
@media (max-width: 720px) {
  [data-theme-layout="lockers"] .lkr-grid { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="lockers"] .lkr-title { font-size: clamp(1.7rem, 8vw, 2.3rem); }
  [data-theme-layout="lockers"] .lkr-zones { padding: .4rem .5rem; }
  [data-theme-layout="lockers"] .lkr-zone { padding: .26rem .5rem; }
  [data-theme-layout="lockers"] .lkr-zone-all { margin-left: 0; }
  [data-theme-layout="lockers"] .lkr-door-in { min-height: 0; }
  [data-theme-layout="lockers"] .lkr-open { padding: .95rem 1rem 1rem; padding-left: calc(28px + 1rem); }
  [data-theme-layout="lockers"] .lkr-open::before { width: 28px; }
  [data-theme-layout="lockers"] .lkr-lost-row { grid-template-columns: minmax(0, 1fr); }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="lockers"] .lkr-wall-all,
  [data-theme-layout="lockers"] .lkr-door-in,
  [data-theme-layout="lockers"] .lkr-open,
  [data-theme-layout="lockers"] .lkr-cap,
  [data-theme-layout="lockers"] .lkr-tag { transition: none; }
  [data-theme-layout="lockers"] .lkr-door-in:hover,
  [data-theme-layout="lockers"] .lkr-open:hover,
  [data-theme-layout="lockers"] .lkr-tag:hover { transform: none; }
}

/* ============================================================
   储物柜 · Lockers —— Lockers 骨架默认皮：薄荷绿柜门、灰绿墙、深绿字
   实算：ink/墙 13.24、ink/柜门 7.88、ink/内里 14.89、muted/柜门 4.76、
   muted/墙 8.00、ink-soft/内里 8.60、accent/墙 6.30、accent/内里 7.08、
   白字/accent 胶囊 7.99、号码牌墙色字/ink 13.24（hover accent-soft/墙 8.58 只升）
   ============================================================ */
:root[data-theme="lockers"] {
  --bg: #dfe6e2; --surface: #9db8a8;
  --ink: #142019; --ink-soft: #2f4a3c; --muted: #31463b; --faint: #6b7f72;
  --line: #b6c4bb; --line-soft: #ccd7d0;
  --accent: #1f5b40; --accent-soft: #17452f; --accent-wash: #ecf3ee;
  --w-wide: 1200px; --radius: 10px;
  --shadow: 0 1px 2px rgba(20, 32, 25, .06), 0 10px 24px rgba(20, 32, 25, .10);
}
:root[data-theme="lockers"] .site-header { background: var(--bg); }
:root[data-theme="lockers"] .btn-primary { color: #fff; }

/* ============================================================
   夜柜 · Nightlocker —— Lockers 骨架 + 工业夜皮：炭蓝灰柜、雾蓝字、琥珀号码牌
   实算：ink/墙 13.92、ink/柜门 10.47、ink/内里 7.91、muted/柜门 5.25、
   muted/墙 6.99、ink-soft/内里 5.54、accent/墙 8.48、accent/柜门 6.37、
   accent/内里 4.82、琥珀牌深字 8.48、胶囊深字/accent 8.48
  （hover accent-soft/墙 10.57、胶囊 hover 深字/soft 10.57 只升）
   ============================================================ */
:root[data-theme="nightlocker"] {
  --bg: #10151b; --surface: #232e3a;
  --ink: #d5e2ee; --ink-soft: #aebfd0; --muted: #8fa2b5; --faint: #5c6c7d;
  --line: #33414f; --line-soft: #1a232c;
  --accent: #e5a43c; --accent-soft: #f0bc6a; --accent-wash: #34414f;
  --w-wide: 1200px; --radius: 10px; --code-bg: #0a0e12;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 12px 30px rgba(0, 0, 0, .5);
}
:root[data-theme="nightlocker"] .site-header { background: rgba(16, 21, 27, .92); }
:root[data-theme="nightlocker"] .btn-primary { color: #10151b; }
/* 琥珀号码牌 + 琥珀胶囊一律压近黑字；柜区「全部」链接换琥珀（柜门上 6.37） */
:root[data-theme="nightlocker"] .lkr-plate { background: var(--accent); color: #10151b; }
:root[data-theme="nightlocker"] .lkr-cap { color: #10151b; }
:root[data-theme="nightlocker"] .lkr-zone-all { color: var(--accent); }

/* ============================================================
   储物柜纯白 · Lockers White —— 第五批纯白系：中性灰基底照抄纯白段，
   本族绿相压深到白底 7.99（hover soft 10.89 只升）；muted #707680 在
   #fafaf8 只有 4.38——带 muted 文字的柜门/小卡面覆写回 --bg 纯白（4.57）；
   打开的门内里 wash 上只用 ink-soft（8.58）/accent（7.00），不放 muted
   ============================================================ */
:root[data-theme="lockers-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #707680; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #1f5b40; --accent-soft: #17452f; --accent-wash: #e9f2ee;
  --w-wide: 1200px; --radius: 10px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .04), 0 10px 26px rgba(16, 18, 24, .07);
}
:root[data-theme="lockers-white"] .btn-primary { color: #fff; }
:root[data-theme="lockers-white"] .lkr-door-in,
:root[data-theme="lockers-white"] .lkr-tag { background: var(--bg); }

/* =========================================================================
   LAYOUT: auction — 拍卖图录 auction catalogue front page (pure CSS, no JS)
   every selector scoped under [data-theme-layout="auction"], classes auc-*
   刊头：站名大字距 + 双线框，HeroEyebrow 当 SALE 期号行；Featured=封面拍品
   大卡（LOT 001 红字 + HomeFeatured 实底签 + 图版区）；Posts=LOT NNN 计数器
   拍品行（右侧等宽日期当 EST. 行）；Categories=「专场」索引行；FeatLinks=
   「买家服务」小字两列。页头 ≥621px 重塑为居中拍卖行门面（serif 大字距品牌
   + 居中 small-caps 导航），≤620px 交还基础汉堡抽屉（重塑段包 min-width）。
   ========================================================================= */
[data-theme-layout="auction"] main { display: block; }
[data-theme-layout="auction"] .auc-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto;
  padding: clamp(1.3rem, 3vw, 2.2rem) 0 clamp(3rem, 6vw, 4.5rem);
}

/* ---- shared chrome: 颜色恒定，结构重塑只在 ≥621px（基础抽屉原样交还） ---- */
[data-theme-layout="auction"] .site-header {
  background: var(--bg); border-bottom: 1px solid var(--line);
  -webkit-backdrop-filter: none; backdrop-filter: none;
}
@media (min-width: 621px) {
  [data-theme-layout="auction"] .site-header { position: static; }
  [data-theme-layout="auction"] .site-header .wrap {
    flex-direction: column; justify-content: center; height: auto; gap: .3rem;
    padding-top: clamp(.85rem, 2vw, 1.25rem); padding-bottom: .6rem;
  }
  [data-theme-layout="auction"] .site-header .brand {
    justify-content: center; text-align: center; font-family: var(--serif);
    font-size: clamp(1.3rem, 2.6vw, 1.65rem); letter-spacing: .22em; text-indent: .22em;
  }
  [data-theme-layout="auction"] .site-header .nav { flex-wrap: wrap; justify-content: center; gap: .2rem 1.4rem; }
  [data-theme-layout="auction"] .site-header .nav a { font-family: var(--serif); font-variant: small-caps; letter-spacing: .12em; }
  [data-theme-layout="auction"] .site-header .nav a[aria-current="page"]::after { bottom: -5px; }
}

/* ---- masthead: 双线刊头（外双线框 + SALE 期号细线行） --------------------- */
[data-theme-layout="auction"] .auc-masthead {
  margin: clamp(.4rem, 1.5vw, 1rem) 0 clamp(1.6rem, 3.5vw, 2.6rem);
  padding: clamp(1.2rem, 2.8vw, 2rem) 0 clamp(.95rem, 2.4vw, 1.5rem);
  border-top: 6px double var(--ink); border-bottom: 6px double var(--ink);
  text-align: center;
}
[data-theme-layout="auction"] .auc-house {
  margin: 0; font-family: var(--serif); font-weight: 800; color: var(--ink);
  font-size: clamp(2rem, 5.6vw, 3.4rem); line-height: 1.12;
  letter-spacing: .18em; text-indent: .18em; overflow-wrap: anywhere;
}
[data-theme-layout="auction"] .auc-sale {
  margin: clamp(.85rem, 2vw, 1.25rem) 0 0; padding: .5rem 0;
  border-top: 1px solid var(--line); border-bottom: 1px solid var(--line);
  font-family: var(--sans); font-size: .78rem; font-weight: 800;
  letter-spacing: .3em; text-indent: .3em; text-transform: uppercase;
  color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="auction"] .auc-note {
  margin: .9rem auto 0; max-width: 62ch;
  font-family: var(--serif); font-style: italic;
  font-size: .98rem; line-height: 1.6; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- featured: 封面拍品大卡（LOT 001 红字 + 实底签 + 右侧图版区） --------- */
[data-theme-layout="auction"] .auc-cover { margin: 0 0 clamp(1.8rem, 4vw, 2.8rem); }
[data-theme-layout="auction"] .auc-cover-card {
  display: grid; grid-template-columns: minmax(0, 1fr); gap: clamp(1.1rem, 2.6vw, 1.8rem);
  padding: clamp(1.1rem, 2.8vw, 1.9rem);
  border: 1px solid var(--ink); background: var(--surface); box-shadow: var(--shadow);
  text-decoration: none; color: var(--ink);
}
[data-theme-layout="auction"] .auc-cover-has-img { grid-template-columns: minmax(0, 1.15fr) minmax(0, .85fr); }
[data-theme-layout="auction"] .auc-cover-body { display: flex; flex-direction: column; align-items: flex-start; gap: .8rem; min-width: 0; }
[data-theme-layout="auction"] .auc-cover-tag {
  display: inline-block; padding: .34rem .7rem;
  background: var(--accent); color: #fff;
  font-size: .68rem; font-weight: 800; letter-spacing: .2em; text-transform: uppercase;
  overflow-wrap: anywhere;
}
[data-theme-layout="auction"] .auc-cover-h {
  display: block; font-family: var(--serif); font-weight: 800;
  font-size: clamp(1.55rem, 3.6vw, 2.5rem); line-height: 1.14; letter-spacing: -.01em;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="auction"] .auc-cover-h::before {
  content: "LOT 001"; display: block; margin-bottom: .55rem;
  font-family: var(--mono); font-size: .8rem; font-weight: 700;
  letter-spacing: .3em; color: var(--accent); font-variant-numeric: tabular-nums;
}
[data-theme-layout="auction"] .auc-cover-card:hover .auc-cover-h { color: var(--accent); }
[data-theme-layout="auction"] .auc-cover-ex {
  display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .98rem; line-height: 1.66; color: var(--ink-soft); overflow-wrap: anywhere;
}
[data-theme-layout="auction"] .auc-cover-foot {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  width: 100%; margin-top: auto; padding-top: .6rem; border-top: 1px solid var(--line);
}
[data-theme-layout="auction"] .auc-cover-foot time {
  font-family: var(--mono); font-size: .78rem; letter-spacing: .06em;
  color: var(--muted); font-variant-numeric: tabular-nums;
}
[data-theme-layout="auction"] .auc-cover-more {
  display: inline-flex; align-items: center; gap: .35rem;
  font-size: .74rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: var(--accent); transition: color .15s;
}
[data-theme-layout="auction"] .auc-cover-card:hover .auc-cover-more { color: var(--accent-soft); }
/* 图版区：衬纸留白 + 细框；钳高防撑页 */
[data-theme-layout="auction"] .auc-cover-plate {
  display: block; align-self: center; min-width: 0;
  padding: clamp(.4rem, 1vw, .65rem); border: 1px solid var(--line); background: var(--accent-wash);
}
[data-theme-layout="auction"] .auc-cover-plate img { display: block; width: 100%; height: auto; max-height: 380px; object-fit: cover; }

/* ---- floor: 拍品行（左） + 专场/买家服务（右） --------------------------- */
[data-theme-layout="auction"] .auc-floor {
  display: grid; grid-template-columns: minmax(0, 1.9fr) minmax(0, 1fr);
  gap: clamp(1.6rem, 4vw, 3rem); align-items: start;
}
[data-theme-layout="auction"] .auc-sec-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  border-bottom: 2px solid var(--ink); padding-bottom: .5rem; margin: 0 0 .2rem;
}
[data-theme-layout="auction"] .auc-sec-t,
[data-theme-layout="auction"] .auc-side-t {
  margin: 0; font-family: var(--sans); font-size: .76rem; font-weight: 800;
  letter-spacing: .24em; text-transform: uppercase; color: var(--ink);
}
[data-theme-layout="auction"] .auc-side-t { border-bottom: 2px solid var(--ink); padding-bottom: .5rem; margin-bottom: .2rem; }
[data-theme-layout="auction"] .auc-sec-all {
  display: inline-flex; align-items: center; gap: .3rem; flex: 0 0 auto;
  font-size: .72rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  color: var(--accent); text-decoration: none; transition: color .15s;
}
[data-theme-layout="auction"] .auc-sec-all:hover { color: var(--accent-soft); }

/* lots：LOT NNN 计数器红字定宽列 | 标题+摘要 | 等宽日期（EST. 位） */
[data-theme-layout="auction"] .auc-lots { list-style: none; margin: 0; padding: 0; counter-reset: auc-lot; }
[data-theme-layout="auction"] .auc-lots-offset { counter-reset: auc-lot 1; } /* Featured 占 LOT 001，行拍品从 002 起拍 */
[data-theme-layout="auction"] .auc-lot { counter-increment: auc-lot; }
[data-theme-layout="auction"] .auc-lot-in {
  display: grid; grid-template-columns: 5.4em minmax(0, 1fr) auto;
  gap: .25rem 1.1rem; align-items: baseline;
  padding: .9rem 0; border-bottom: 1px solid var(--line-soft);
  text-decoration: none; color: var(--ink);
}
[data-theme-layout="auction"] .auc-lot-in::before {
  content: "LOT 0" counter(auc-lot, decimal-leading-zero);
  font-family: var(--mono); font-size: .76rem; font-weight: 700;
  letter-spacing: .12em; color: var(--accent);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
[data-theme-layout="auction"] .auc-lot-body { display: flex; flex-direction: column; gap: .3rem; min-width: 0; }
[data-theme-layout="auction"] .auc-lot-h {
  font-family: var(--serif); font-weight: 700; font-size: 1.12rem; line-height: 1.3;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="auction"] .auc-lot-in:hover .auc-lot-h { color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
[data-theme-layout="auction"] .auc-lot-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .86rem; line-height: 1.5; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="auction"] .auc-lot-cat { font-size: .66rem; font-weight: 800; letter-spacing: .18em; text-transform: uppercase; color: var(--accent); overflow-wrap: anywhere; }
[data-theme-layout="auction"] .auc-lot-est {
  font-family: var(--mono); font-size: .76rem; letter-spacing: .04em;
  color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap;
}

/* side：「专场」索引行 + 「买家服务」小字两列 */
[data-theme-layout="auction"] .auc-side { display: flex; flex-direction: column; gap: clamp(1.6rem, 3.5vw, 2.2rem); min-width: 0; }
[data-theme-layout="auction"] .auc-session {
  display: flex; justify-content: space-between; align-items: baseline; gap: .8rem; min-width: 0;
  padding: .62rem .1rem; border-bottom: 1px solid var(--line-soft);
  text-decoration: none; color: var(--ink-soft);
}
[data-theme-layout="auction"] .auc-session-name { font-family: var(--serif); font-weight: 600; font-size: .98rem; overflow-wrap: anywhere; transition: color .15s; }
[data-theme-layout="auction"] .auc-session:hover .auc-session-name { color: var(--accent); }
[data-theme-layout="auction"] .auc-session-n { flex: 0 0 auto; font-family: var(--mono); font-size: .74rem; color: var(--muted); font-variant-numeric: tabular-nums; }
[data-theme-layout="auction"] .auc-session-all {
  justify-content: flex-start; color: var(--accent);
  font-size: .78rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
  transition: color .15s;
}
[data-theme-layout="auction"] .auc-session-all:hover { color: var(--accent-soft); }
[data-theme-layout="auction"] .auc-services-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 1.4rem; }
[data-theme-layout="auction"] .auc-service {
  display: block; min-width: 0; padding: .55rem 0;
  border-bottom: 1px solid var(--line-soft);
  text-decoration: none; color: var(--ink-soft);
}
[data-theme-layout="auction"] .auc-service-t { display: block; font-size: .86rem; font-weight: 700; line-height: 1.35; overflow-wrap: anywhere; transition: color .15s; }
[data-theme-layout="auction"] .auc-service:hover .auc-service-t { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="auction"] .auc-service-ex {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  margin-top: .15rem; font-size: .74rem; line-height: 1.45; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="auction"] .auc-floor { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 720px) {
  [data-theme-layout="auction"] .auc-house { font-size: clamp(1.7rem, 8.5vw, 2.4rem); letter-spacing: .12em; text-indent: .12em; }
  [data-theme-layout="auction"] .auc-cover-card,
  [data-theme-layout="auction"] .auc-cover-has-img { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="auction"] .auc-cover-foot { flex-wrap: wrap; }
  [data-theme-layout="auction"] .auc-lot-in { grid-template-columns: minmax(0, 1fr); gap: .3rem; }
  [data-theme-layout="auction"] .auc-lot-est { white-space: normal; }
  [data-theme-layout="auction"] .auc-services-grid { grid-template-columns: minmax(0, 1fr); }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="auction"] .auc-cover-h,
  [data-theme-layout="auction"] .auc-cover-more,
  [data-theme-layout="auction"] .auc-sec-all,
  [data-theme-layout="auction"] .auc-lot-h,
  [data-theme-layout="auction"] .auc-session-name,
  [data-theme-layout="auction"] .auc-session-all,
  [data-theme-layout="auction"] .auc-service-t { transition: none; }
}

/* ============================================================
   拍卖 · Auction —— Auction 骨架默认皮：象牙纸、拍卖红、暖褐线
   实算：正文 14.42（surface 15.46）/ 次要 8.97（surface 9.62）/
   muted 5.26（surface 5.64）/ 红字 7.48（surface 8.02，hover soft
   9.92 只升）/ 实底签白字 8.36 / 红压 wash 6.48
   ============================================================ */
:root[data-theme="auction"] {
  --bg: #f6f2e8; --surface: #fdfaf3;
  --ink: #262019; --ink-soft: #4a4133; --muted: #6e6353; --faint: #998c78;
  --line: #d7cbb0; --line-soft: #e7dfcc;
  --accent: #8a2f24; --accent-soft: #6e2118; --accent-wash: #f0e0d1;
  --w-wide: 1200px; --radius: 0px;
  --shadow: 0 1px 2px rgba(38, 32, 25, .06), 0 8px 22px rgba(38, 32, 25, .08);
}
:root[data-theme="auction"] .btn-primary { color: #fff; }

/* ============================================================
   夜拍 · Nightsale —— Auction 骨架反差皮：近黑夜场、鎏金槌、米白字
   实算：正文 15.30（surface 14.27）/ 次要 11.48（surface 10.71）/
   muted 6.81（surface 6.35）/ 金字 8.49（surface 7.92，hover soft
   10.42 只升）/ 实底签黑字 8.49 / 金压 wash 7.12
   ============================================================ */
:root[data-theme="nightsale"] {
  --bg: #17130e; --surface: #201a12;
  --ink: #f1e9d7; --ink-soft: #d6cbb2; --muted: #a79c85; --faint: #7b7160;
  --line: #3b3325; --line-soft: #2a2418;
  --accent: #d9a848; --accent-soft: #e6bd67; --accent-wash: #2c2310;
  --w-wide: 1200px; --radius: 0px; --code-bg: #0d0a06;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 10px 28px rgba(0, 0, 0, .5);
}
:root[data-theme="nightsale"] .btn-primary { color: #17130e; }
/* 鎏金实底签上改深字（白字在金底只有 1.9） */
:root[data-theme="nightsale"] .auc-cover-tag { color: #17130e; }

/* ============================================================
   拍卖 · 纯白 —— Auction 骨架纯白皮：中性灰基底照抄「纯白系」段，
   拍卖红保留本族色相 #8a2f24（白底实算 8.36，hover soft 11.09 只升）；
   正文 18.72 / 次要 9.79 / muted 白底 4.57——muted 落 surface 只有
   4.38，封面大卡（卡内 muted 日期）基底覆写回纯白 --bg；
   实底签白字 8.36 / 红压 wash 7.23
   ============================================================ */
:root[data-theme="auction-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #707680; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #8a2f24; --accent-soft: #6e2118; --accent-wash: #f8ece8;
  --w-wide: 1200px; --radius: 0px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .05), 0 8px 20px rgba(16, 18, 24, .06);
}
:root[data-theme="auction-white"] .btn-primary { color: #fff; }
:root[data-theme="auction-white"] .auc-cover-card { background: var(--bg); }

/* =========================================================================
   LAYOUT: lattice — 花窗 garden-lattice home (pure CSS, no JS)
   every selector scoped under [data-theme-layout="lattice"], classes lw-*
   页头下黛瓦横带（repeating-linear-gradient 瓦纹，定高装饰不撑页）；居中题签；
   园林三列 grid：八角窗大框（外内两层同形 clip-path，外层背景即粗墨框，
   inset box-shadow 会被 clip 切角故不用）+ 圆洞门（正圆 aspect-ratio:1，
   920px 降级方圆角）+ 方窗卡（粗墨边框）；Categories 窗型胶囊（小八角双层）；
   FeatLinks 园外链接一行。皮肤可覆写 --lw-frame-c（窗框）/ --lw-tile（瓦色）
   ========================================================================= */
[data-theme-layout="lattice"] main { display: block; }
[data-theme-layout="lattice"] .lw-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-block: clamp(1.6rem, 4vw, 2.6rem) clamp(3rem, 6vw, 5rem);
}

/* ---- shared chrome: light recast only, drawer untouched ≤620px ---------- */
[data-theme-layout="lattice"] .site-header { background: var(--bg); }
[data-theme-layout="lattice"] .site-footer { border-top: 1px solid var(--line); background: var(--bg); }
@media (min-width: 621px) {
  [data-theme-layout="lattice"] .site-header { border-bottom: 0; }
  [data-theme-layout="lattice"] .site-header .brand { letter-spacing: .14em; }
  [data-theme-layout="lattice"] .site-header .nav a { letter-spacing: .08em; font-size: .93rem; }
}

/* ---- eave band: dark tile strip under the header (decorative, fixed h) -- */
[data-theme-layout="lattice"] .lw-eave {
  height: 20px;
  background:
    repeating-linear-gradient(90deg, transparent 0 26px, rgba(251, 250, 244, .28) 26px 28px),
    linear-gradient(180deg, rgba(255, 255, 255, .14), rgba(0, 0, 0, .2)),
    var(--lw-tile, #3a3f38);
  box-shadow: inset 0 -2px 0 rgba(0, 0, 0, .25);
}

/* ---- plaque: centered inscription (wide-tracked title + small lede) ----- */
[data-theme-layout="lattice"] .lw-plaque {
  max-width: 46rem; margin: 0 auto clamp(1.8rem, 4vw, 2.6rem);
  padding: clamp(1rem, 2.5vw, 1.4rem) .5rem;
  border-block: 1px solid var(--line-soft); text-align: center;
}
[data-theme-layout="lattice"] .lw-eyebrow {
  margin: 0 0 .55rem; font-size: .74rem; font-weight: 700;
  letter-spacing: .3em; text-indent: .3em; text-transform: uppercase;
  color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="lattice"] .lw-title {
  margin: 0 0 .6rem; font-family: var(--serif); font-weight: 700;
  font-size: clamp(1.9rem, 5vw, 3rem); line-height: 1.16;
  letter-spacing: .18em; text-indent: .18em;
  color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="lattice"] .lw-lede {
  margin: 0 auto; max-width: 56ch;
  font-size: .95rem; line-height: 1.7; color: var(--muted); overflow-wrap: anywhere;
}

/* ---- garden head --------------------------------------------------------- */
[data-theme-layout="lattice"] .lw-head {
  display: flex; justify-content: space-between; align-items: baseline; gap: 1rem;
  margin: 0 0 clamp(1rem, 2.5vw, 1.4rem);
  border-bottom: 2px solid var(--lw-frame-c, var(--ink)); padding-bottom: .5rem;
}
[data-theme-layout="lattice"] .lw-head-t {
  margin: 0; font-size: .8rem; font-weight: 800;
  letter-spacing: .24em; text-transform: uppercase; color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="lattice"] .lw-head-all {
  flex: 0 0 auto; font-size: .74rem; font-weight: 700; letter-spacing: .1em;
  text-transform: uppercase; color: var(--accent); text-decoration: none;
}
[data-theme-layout="lattice"] .lw-head-all:hover { text-decoration: underline; text-underline-offset: 3px; }

/* ---- garden grid: octagon (2 cols) + moon gate + square panes ----------- */
[data-theme-layout="lattice"] .lw-garden {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(.9rem, 2.2vw, 1.4rem);
}

/* featured octagon window: outer layer = thick ink frame, inner = paper */
[data-theme-layout="lattice"] .lw-oct {
  --lw-cut: clamp(30px, 5vw, 54px);
  grid-column: span 2; display: flex; min-width: 0;
  padding: 4px; background: var(--lw-frame-c, var(--ink));
  text-decoration: none; color: var(--ink); transition: background .15s;
}
[data-theme-layout="lattice"] .lw-oct,
[data-theme-layout="lattice"] .lw-oct-in {
  clip-path: polygon(var(--lw-cut) 0, calc(100% - var(--lw-cut)) 0, 100% var(--lw-cut),
    100% calc(100% - var(--lw-cut)), calc(100% - var(--lw-cut)) 100%, var(--lw-cut) 100%,
    0 calc(100% - var(--lw-cut)), 0 var(--lw-cut));
}
[data-theme-layout="lattice"] .lw-oct:hover { background: var(--accent); }
[data-theme-layout="lattice"] .lw-oct-in {
  flex: 1 1 auto; min-width: 0;
  display: flex; flex-direction: column; justify-content: center; align-items: center;
  gap: .7rem; text-align: center; background: var(--surface);
  /* 内衬 ≥ 切角深度：文字永远落在直边区，不贴斜框 */
  padding: clamp(2.2rem, 6vw, 3.2rem) clamp(2.4rem, 7vw, 3.8rem);
}
[data-theme-layout="lattice"] .lw-kicker {
  display: inline-flex; align-items: baseline; gap: .55rem; min-width: 0;
  font-size: .72rem; font-weight: 800; letter-spacing: .22em; text-transform: uppercase;
  color: var(--accent);
}
[data-theme-layout="lattice"] .lw-kicker-cat { color: var(--muted); overflow-wrap: anywhere; }
[data-theme-layout="lattice"] .lw-oct-t {
  font-family: var(--serif); font-weight: 700;
  font-size: clamp(1.45rem, 3.4vw, 2.1rem); line-height: 1.22; overflow-wrap: anywhere;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  transition: color .15s;
}
[data-theme-layout="lattice"] .lw-oct:hover .lw-oct-t { color: var(--accent); text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 4px; }
[data-theme-layout="lattice"] .lw-oct-ex {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  max-width: 52ch; font-size: .95rem; line-height: 1.66; color: var(--ink-soft); overflow-wrap: anywhere;
}
[data-theme-layout="lattice"] .lw-oct-date {
  font-family: var(--mono); font-size: .74rem; letter-spacing: .04em;
  font-variant-numeric: tabular-nums; color: var(--muted);
}

/* moon gate: perfect circle, short centered content, clamped */
[data-theme-layout="lattice"] .lw-moon {
  position: relative; aspect-ratio: 1; align-self: center; min-width: 0;
  border: 3px solid var(--lw-frame-c, var(--ink)); border-radius: 50%;
  background: var(--surface); overflow: hidden;
  text-decoration: none; color: var(--ink); transition: border-color .15s;
}
[data-theme-layout="lattice"] .lw-moon:hover { border-color: var(--accent); }
[data-theme-layout="lattice"] .lw-moon-in {
  position: absolute; inset: 0;
  display: flex; flex-direction: column; justify-content: center; align-items: center;
  gap: .45rem; text-align: center; padding: 18%;
}
[data-theme-layout="lattice"] .lw-moon-cat {
  font-size: .66rem; font-weight: 800; letter-spacing: .18em; text-transform: uppercase;
  color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="lattice"] .lw-moon-t {
  font-family: var(--serif); font-weight: 700;
  font-size: clamp(1rem, 1.6vw, 1.2rem); line-height: 1.3; overflow-wrap: anywhere;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  transition: color .15s;
}
[data-theme-layout="lattice"] .lw-moon:hover .lw-moon-t { color: var(--accent); }
[data-theme-layout="lattice"] .lw-moon-date {
  font-family: var(--mono); font-size: .7rem; font-variant-numeric: tabular-nums; color: var(--muted);
}

/* square window panes: thick ink border, roomy lining */
[data-theme-layout="lattice"] .lw-pane {
  display: flex; flex-direction: column; gap: .5rem; min-width: 0;
  border: 3px solid var(--lw-frame-c, var(--ink)); background: var(--surface);
  padding: 1.15rem 1.25rem 1.05rem;
  text-decoration: none; color: var(--ink); transition: border-color .15s;
}
[data-theme-layout="lattice"] .lw-pane:hover { border-color: var(--accent); }
[data-theme-layout="lattice"] .lw-pane-cat {
  align-self: flex-start; font-size: .66rem; font-weight: 800;
  letter-spacing: .18em; text-transform: uppercase; color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="lattice"] .lw-pane-t {
  font-family: var(--serif); font-weight: 700; font-size: 1.1rem; line-height: 1.32;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="lattice"] .lw-pane:hover .lw-pane-t { color: var(--accent); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
[data-theme-layout="lattice"] .lw-pane-ex {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .88rem; line-height: 1.6; color: var(--muted); overflow-wrap: anywhere;
}
[data-theme-layout="lattice"] .lw-pane-date {
  margin-top: auto; font-family: var(--mono); font-size: .72rem;
  font-variant-numeric: tabular-nums; color: var(--muted);
}

/* ---- categories: window-shaped capsules (small double-clip octagons) ---- */
[data-theme-layout="lattice"] .lw-cats {
  display: flex; flex-wrap: wrap; justify-content: center; gap: .55rem .6rem;
  margin-top: clamp(1.8rem, 4vw, 2.6rem);
}
[data-theme-layout="lattice"] .lw-cat {
  --lw-chip-cut: 9px;
  display: inline-flex; min-width: 0; padding: 2px;
  background: var(--lw-frame-c, var(--ink)); text-decoration: none;
}
[data-theme-layout="lattice"] .lw-cat,
[data-theme-layout="lattice"] .lw-cat-in {
  clip-path: polygon(var(--lw-chip-cut) 0, calc(100% - var(--lw-chip-cut)) 0, 100% var(--lw-chip-cut),
    100% calc(100% - var(--lw-chip-cut)), calc(100% - var(--lw-chip-cut)) 100%, var(--lw-chip-cut) 100%,
    0 calc(100% - var(--lw-chip-cut)), 0 var(--lw-chip-cut));
}
[data-theme-layout="lattice"] .lw-cat-in {
  display: inline-flex; align-items: baseline; gap: .4rem; min-width: 0;
  padding: .4rem 1rem; background: var(--bg); color: var(--ink-soft);
  font-size: .88rem; letter-spacing: .06em;
  transition: background .15s, color .15s;
}
[data-theme-layout="lattice"] .lw-cat-name { overflow-wrap: anywhere; }
[data-theme-layout="lattice"] .lw-cat-n { font-size: .68rem; color: var(--muted); transition: color .15s; }
[data-theme-layout="lattice"] .lw-cat:hover .lw-cat-in { background: var(--accent-wash); color: var(--ink); }
[data-theme-layout="lattice"] .lw-cat:hover .lw-cat-n { color: var(--ink-soft); }
[data-theme-layout="lattice"] .lw-cat-all .lw-cat-in { color: var(--accent); font-weight: 700; }

/* ---- outbound row: FeatLinks in one wrapping line ------------------------ */
[data-theme-layout="lattice"] .lw-links {
  margin-top: clamp(1.8rem, 4vw, 2.4rem);
  border-top: 1px solid var(--line); padding-top: 1.1rem;
}
[data-theme-layout="lattice"] .lw-links-h {
  margin: 0 0 .75rem; text-align: center; font-size: .74rem; font-weight: 800;
  letter-spacing: .26em; text-transform: uppercase; color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="lattice"] .lw-links-row {
  display: flex; flex-wrap: wrap; justify-content: center; gap: .6rem 1rem;
}
[data-theme-layout="lattice"] .lw-link {
  display: inline-flex; align-items: center; gap: .6rem; min-width: 0; max-width: 100%;
  padding: .45rem .8rem; border: 1px solid var(--line); background: var(--surface);
  text-decoration: none; color: var(--ink); transition: border-color .15s;
}
[data-theme-layout="lattice"] .lw-link:hover { border-color: var(--accent); }
[data-theme-layout="lattice"] .lw-link-ic {
  --lw-chip-cut: 6px;
  flex: 0 0 auto; width: 34px; height: 34px; overflow: hidden;
  display: grid; place-items: center;
  background: var(--accent-wash); color: var(--accent);
  clip-path: polygon(var(--lw-chip-cut) 0, calc(100% - var(--lw-chip-cut)) 0, 100% var(--lw-chip-cut),
    100% calc(100% - var(--lw-chip-cut)), calc(100% - var(--lw-chip-cut)) 100%, var(--lw-chip-cut) 100%,
    0 calc(100% - var(--lw-chip-cut)), 0 var(--lw-chip-cut));
}
[data-theme-layout="lattice"] .lw-link-ic img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-theme-layout="lattice"] .lw-link-ic b { font-family: var(--serif); font-weight: 700; font-size: 1rem; line-height: 1; }
[data-theme-layout="lattice"] .lw-link-t {
  font-weight: 600; font-size: .92rem; line-height: 1.3;
  overflow-wrap: anywhere; transition: color .15s;
}
[data-theme-layout="lattice"] .lw-link:hover .lw-link-t { color: var(--accent); }

/* ---- responsive ---------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="lattice"] .lw-garden { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="lattice"] .lw-oct { grid-column: auto; }
  /* 圆洞门降级方圆角：取消正圆比例，内容回归普通流 */
  [data-theme-layout="lattice"] .lw-moon { aspect-ratio: auto; border-radius: 22px; align-self: stretch; }
  [data-theme-layout="lattice"] .lw-moon-in { position: static; inset: auto; padding: 1.6rem 1.4rem; }
}
@media (max-width: 720px) {
  [data-theme-layout="lattice"] .lw-title { font-size: clamp(1.6rem, 7.5vw, 2.1rem); letter-spacing: .1em; text-indent: .1em; }
  [data-theme-layout="lattice"] .lw-eyebrow { letter-spacing: .22em; text-indent: .22em; }
  [data-theme-layout="lattice"] .lw-eave { height: 14px; }
  [data-theme-layout="lattice"] .lw-head { flex-wrap: wrap; }
  [data-theme-layout="lattice"] .lw-oct { --lw-cut: 26px; }
  [data-theme-layout="lattice"] .lw-oct-in { padding: 1.8rem 1.6rem; }
  [data-theme-layout="lattice"] .lw-cat-in { padding: .34rem .8rem; font-size: .84rem; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="lattice"] .lw-oct,
  [data-theme-layout="lattice"] .lw-oct-t,
  [data-theme-layout="lattice"] .lw-moon,
  [data-theme-layout="lattice"] .lw-moon-t,
  [data-theme-layout="lattice"] .lw-pane,
  [data-theme-layout="lattice"] .lw-pane-t,
  [data-theme-layout="lattice"] .lw-cat-in,
  [data-theme-layout="lattice"] .lw-cat-n,
  [data-theme-layout="lattice"] .lw-link,
  [data-theme-layout="lattice"] .lw-link-t { transition: none; }
}

/* ============================================================
   花窗 · Lattice —— Lattice 骨架默认皮：粉墙窗纸、黛墨窗框、竹绿点睛
   （竹绿压深到 #46734c：粉墙 4.82 / 窗纸 5.26，hover soft 只升）
   ============================================================ */
:root[data-theme="lattice"] {
  --bg: #f2f0e9; --surface: #fbfaf4;
  --ink: #262a24; --ink-soft: #454b41; --muted: #676e60; --faint: #8f968a;
  --line: #d9d6c9; --line-soft: #e8e5da;
  --accent: #46734c; --accent-soft: #35593a; --accent-wash: #e4ecdc;
  --w-wide: 1200px; --radius: 0px;
  --shadow: 0 1px 2px rgba(38, 42, 36, .05), 0 10px 26px rgba(38, 42, 36, .08);
  --lw-frame-c: #3a3f38; --lw-tile: #3a3f38;
}
:root[data-theme="lattice"] .site-header { background: var(--bg); }
:root[data-theme="lattice"] .btn-primary { color: #fff; }

/* ============================================================
   夜园 · Nightgarden —— Lattice 骨架 + 墨青夜月白字、苔绿框光反差皮
   （苔绿 #6fa276 夜底 5.44 / 面 4.94，hover soft #97c49d 7.43 只升）
   ============================================================ */
:root[data-theme="nightgarden"] {
  --bg: #1a2320; --surface: #212b27;
  --ink: #edf2ec; --ink-soft: #ccd6cd; --muted: #9dab9f; --faint: #71806f;
  --line: #35423b; --line-soft: #29332e;
  --accent: #6fa276; --accent-soft: #97c49d; --accent-wash: #24352a;
  --w-wide: 1200px; --radius: 0px; --code-bg: #131a17;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 14px 34px rgba(0, 0, 0, .5);
  --lw-frame-c: #6fa276; --lw-tile: #121917;
}
:root[data-theme="nightgarden"] .site-header { background: rgba(26, 35, 32, .92); }
:root[data-theme="nightgarden"] .btn-primary { color: #1a2320; }
/* 苔绿框光：八角窗随形 drop-shadow，圆洞门/方窗柔和外晕（纯装饰） */
:root[data-theme="nightgarden"] .lw-oct { filter: drop-shadow(0 0 14px rgba(111, 162, 118, .26)); }
:root[data-theme="nightgarden"] .lw-moon,
:root[data-theme="nightgarden"] .lw-pane { box-shadow: 0 0 18px rgba(111, 162, 118, .16); }

/* ============================================================
   花窗纯白 · Lattice White —— 第五批纯白系：中性灰基底照抄纯白段，
   竹绿压深到白底 #3a6a41 = 6.33（hover soft #2a4f30 = 9.29 只升）；
   muted #707680 在 #fafaf8 只有 4.38——凡有 muted 文字的窗面覆写回 --bg 纯白
   ============================================================ */
:root[data-theme="lattice-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #707680; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #3a6a41; --accent-soft: #2a4f30; --accent-wash: #e7f0e6;
  --w-wide: 1200px; --radius: 0px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .04), 0 10px 26px rgba(16, 18, 24, .07);
  --lw-frame-c: #101218; --lw-tile: #2a2d33;
}
:root[data-theme="lattice-white"] .btn-primary { color: #fff; }
:root[data-theme="lattice-white"] .lw-oct-in,
:root[data-theme="lattice-white"] .lw-moon,
:root[data-theme="lattice-white"] .lw-pane,
:root[data-theme="lattice-white"] .lw-link { background: var(--bg); }

/* =========================================================================
   LAYOUT: factory-line — 产线（工厂族第 10 骨架；partial home_factory_line）
   每条选择器限定 [data-theme-layout="factory-line"]，自有类名前缀 fln-（全仓未占用）。
   形态：整页读成一条流水线。
     页头 = 工位标签条：CSS 重塑标准 .site-header——导航项做成工位牌（等宽 ST-01…
            用 CSS 计数器 decimal-leading-zero 生成，不改 DOM），当前项底部粗强调线；
            整段包在 min-width:621px 内，≤620px 交还基础汉堡抽屉。
     hero  = 大标题 + factory.stats 工位牌（顶部 ST 编号条；未配置回落 factory_about），
            下接一条传送带纹横带（repeating-linear-gradient 滚轮纹 + 两端托辊，
            认证槽 f-certs 骑在带上；prefers-reduced-motion 静止）。
     商品  = 沿带排列的工位卡（顶部 5px 彩条对齐成带 + ST 序号牌）。
     流程  = 复用共享 f-process 标记，重塑成产线节点串（圆点 + 虚线连线）。
     内页  = 商品/归档列表重塑为工位流卡片（左侧 ST 序号列）；
            商品详情重塑为装配步骤条（面包屑路径条 + 缩略图工位串 + 规格表行序号）+ 规格。
   ========================================================================= */
[data-theme-layout="factory-line"] {
  --fln-hot: var(--accent);                                        /* 装饰橙：彩条/滚轮纹/节点圈，恒不作字 */
  --fln-belt: color-mix(in srgb, var(--ink) 6%, var(--surface));   /* 传送带带面 */
  --fln-rule: color-mix(in srgb, var(--ink) 26%, transparent);     /* 节点连线 */
}
[data-theme-layout="factory-line"] body { background: var(--bg); }
[data-theme-layout="factory-line"] .fln-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-bottom: clamp(3rem, 6vw, 4.4rem);
}

/* ---- 页头：工位标签条（标准 .site-header 的 CSS 重塑，无新增 DOM）---------- */
[data-theme-layout="factory-line"] .site-header {
  background: var(--surface); -webkit-backdrop-filter: none; backdrop-filter: none;
  border-bottom: 2px solid var(--ink);
}
@media (min-width: 621px) {
  [data-theme-layout="factory-line"] .site-header .wrap { height: 74px; align-items: stretch; gap: 0; }
  [data-theme-layout="factory-line"] .brand {
    align-self: center; margin-right: auto; padding-right: 1.1rem;
    font-family: var(--sans); font-weight: 780; letter-spacing: -.01em;
  }
  [data-theme-layout="factory-line"] .nav {
    counter-reset: fln-st; align-self: stretch; align-items: stretch;
    gap: 0; border-left: 1px solid var(--line);
  }
  [data-theme-layout="factory-line"] .nav > a {
    display: flex; flex-direction: column; justify-content: center; gap: .16rem;
    padding: 0 clamp(.55rem, 1.3vw, 1rem); border-right: 1px solid var(--line);
    font-size: .88rem; font-weight: 650; overflow-wrap: anywhere;
  }
  /* 工位号：CSS 计数器生成 ST-01…，搜索入口不占号 */
  [data-theme-layout="factory-line"] .nav > a:not(.search-ico)::before {
    counter-increment: fln-st; content: "№ " counter(fln-st, decimal-leading-zero);
    font-family: var(--mono); font-size: .56rem; font-weight: 700;
    letter-spacing: .16em; color: var(--muted);
  }
  [data-theme-layout="factory-line"] .nav > a:hover { background: color-mix(in srgb, var(--ink) 4%, transparent); }
  [data-theme-layout="factory-line"] .nav a[aria-current="page"] { color: var(--ink); }
  [data-theme-layout="factory-line"] .nav a[aria-current="page"]::before { color: var(--accent); }
  /* 当前项底部粗强调线（基础规则是 bottom:-22px 的 2px 细线，这里压到条底加粗） */
  [data-theme-layout="factory-line"] .nav a[aria-current="page"]::after { top: auto; bottom: 0; height: 5px; background: var(--fln-hot); }
  [data-theme-layout="factory-line"] .nav .search-ico { padding-inline: clamp(.55rem, 1.3vw, 1rem); opacity: 1; color: var(--muted); }
  [data-theme-layout="factory-line"] .nav .search-ico:hover { color: var(--accent); }
  [data-theme-layout="factory-line"] .nav .lang-switch { padding-left: .75rem; border-left: 0; }
}

/* ---- hero：大标题 + 工位牌数字卡 ---------------------------------------- */
[data-theme-layout="factory-line"] .fln-hero {
  display: grid; grid-template-columns: minmax(0, 1.12fr) minmax(280px, .88fr);
  align-items: end; gap: clamp(1.4rem, 3vw, 2.8rem);
  padding: clamp(2rem, 4.5vw, 3.4rem) 0 clamp(1.4rem, 3vw, 2rem);
}
[data-theme-layout="factory-line"] .fln-eyebrow {
  width: fit-content; max-width: 100%; margin: 0 0 1.1rem; padding: .28rem .62rem;
  background: var(--accent); color: var(--surface); font-family: var(--mono);
  font-size: .68rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase;
  overflow-wrap: anywhere;
}
[data-theme-layout="factory-line"] .fln-h1 {
  margin: 0; max-width: 15em; font-size: clamp(2rem, 4.6vw, 3.3rem);
  font-weight: 790; line-height: 1.08; letter-spacing: -.015em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-line"] .fln-lede { max-width: 56ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75; }
[data-theme-layout="factory-line"] .fln-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="factory-line"] .fln-hero-side { min-width: 0; }
[data-theme-layout="factory-line"] .fln-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .7rem; }
[data-theme-layout="factory-line"] .fln-stats .f-stat { padding: 1.8rem 1rem .95rem; border-radius: 0; }
/* 工位号条：覆写共用数字卡的左上角标（含 content/尺寸/边框全量重置） */
[data-theme-layout="factory-line"] .fln-stats .f-stat::before {
  counter-increment: fln-plate; content: "№ " counter(fln-plate, decimal-leading-zero);
  top: 0; left: 0; right: 0; width: auto; height: auto; padding: .2rem .55rem;
  border: 0; background: var(--ink); color: var(--bg); text-align: left;
  font-family: var(--mono); font-size: .56rem; font-weight: 700; letter-spacing: .16em; line-height: 1.6;
}
[data-theme-layout="factory-line"] .fln-stats { counter-reset: fln-plate; }
[data-theme-layout="factory-line"] .fln-stats .f-stat::after { border-color: var(--fln-hot); }
[data-theme-layout="factory-line"] .fln-stats .f-stat dt { font-size: clamp(1.35rem, 2.2vw, 1.9rem); }
[data-theme-layout="factory-line"] .fln-hero-side .f-about { border-radius: 0; }

/* ---- 传送带横带：滚轮纹 + 两端托辊 + 骑在带上的认证章 ------------------- */
[data-theme-layout="factory-line"] .fln-belt {
  position: relative; border: 1px solid var(--line); border-radius: 0;
  background: var(--fln-belt); overflow: hidden;
}
[data-theme-layout="factory-line"] .fln-belt-tread {
  display: block; height: 22px; border-bottom: 1px solid var(--line);
  background-image:
    repeating-linear-gradient(90deg, var(--fln-hot) 0 3px, transparent 3px 11px),
    repeating-linear-gradient(90deg, color-mix(in srgb, var(--ink) 18%, transparent) 0 1px, transparent 1px 44px);
  background-size: 44px 100%, 44px 100%;
  animation: flnRoll 2.2s linear infinite;
}
@keyframes flnRoll { to { background-position-x: -44px, -44px; } }
/* 托辊：专属车道=带体自身（22px 高的独立条），不散布到内容区 */
[data-theme-layout="factory-line"] .fln-belt::before,
[data-theme-layout="factory-line"] .fln-belt::after {
  content: ""; position: absolute; top: 3px; z-index: 1; width: 16px; height: 16px;
  border: 2px solid color-mix(in srgb, var(--ink) 34%, transparent); border-radius: 50%;
  background: var(--surface); pointer-events: none;
}
[data-theme-layout="factory-line"] .fln-belt::before { left: 8px; }
[data-theme-layout="factory-line"] .fln-belt::after { right: 8px; }
[data-theme-layout="factory-line"] .fln-certs { padding: .85rem clamp(.9rem, 2vw, 1.4rem) .9rem; gap: .6rem .9rem; }
[data-theme-layout="factory-line"] .fln-certs .f-cert:nth-child(odd),
[data-theme-layout="factory-line"] .fln-certs .f-cert:nth-child(even) { transform: none; border-radius: 0; }

/* ---- 区块头 ------------------------------------------------------------- */
[data-theme-layout="factory-line"] .fln-section { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-line"] .fln-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
  margin-bottom: 1.3rem; padding-bottom: .7rem; border-bottom: 2px solid var(--ink);
}
[data-theme-layout="factory-line"] .fln-head h2 { margin: 0; font-size: clamp(1.35rem, 2.4vw, 1.7rem); font-weight: 780; overflow-wrap: anywhere; }
[data-theme-layout="factory-line"] .fln-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-line"] .fln-head > a:hover { color: var(--accent); }

/* ---- 商品：沿带排列的工位卡（顶部彩条对齐成带 + ST 序号牌）-------------- */
[data-theme-layout="factory-line"] .fln-cells { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.5rem .6rem; }
[data-theme-layout="factory-line"] .fln-cell {
  position: relative; display: flex; min-width: 0; flex-direction: column; padding-top: 5px;
  border: 1px solid var(--line); border-radius: 0; background: var(--surface); color: var(--ink);
  overflow: hidden; transition: border-color var(--speed), transform var(--speed);
}
[data-theme-layout="factory-line"] .fln-cell::before {
  content: ""; position: absolute; top: 0; left: 0; right: 0; height: 5px;
  background: linear-gradient(90deg, var(--fln-hot) 0 64%, color-mix(in srgb, var(--fln-hot) 34%, transparent) 64%);
}
[data-theme-layout="factory-line"] .fln-cell:hover { border-color: var(--accent); transform: translateY(-3px); color: var(--ink); }
[data-theme-layout="factory-line"] .fln-cell-media { position: relative; display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-line"] .fln-cell-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
[data-theme-layout="factory-line"] .fln-cell:hover .fln-cell-media img { transform: scale(1.03); }
[data-theme-layout="factory-line"] .fln-cell-gen b { font-family: var(--sans); font-size: 2.9rem; color: var(--accent); }
[data-theme-layout="factory-line"] .fln-cell-tag {
  position: absolute; top: 0; left: 0; padding: .18rem .5rem; background: var(--ink); color: var(--bg);
  font-family: var(--mono); font-size: .58rem; font-weight: 700; letter-spacing: .14em; line-height: 1.6;
}
[data-theme-layout="factory-line"] .fln-cell-body { display: flex; flex: 1; flex-direction: column; gap: .3rem; padding: .8rem .9rem 1rem; }
[data-theme-layout="factory-line"] .fln-cell-cat { width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 750; letter-spacing: .07em; text-transform: uppercase; }
[data-theme-layout="factory-line"] .fln-cell-title { font-size: .97rem; font-weight: 720; line-height: 1.4; overflow-wrap: anywhere; }
[data-theme-layout="factory-line"] .fln-cell-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .8rem; line-height: 1.55; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="factory-line"] .fln-empty { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center; }

/* ---- 流程：共享 f-process 重塑成产线节点串（圆点 + 虚线连线）------------ */
[data-theme-layout="factory-line"] .fln-process-sec .f-process { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.3rem; }
[data-theme-layout="factory-line"] .fln-process-sec .f-step::before {
  top: 15px; height: 2px;
  background: repeating-linear-gradient(90deg, var(--fln-rule) 0 7px, transparent 7px 14px);
}
[data-theme-layout="factory-line"] .fln-process-sec .f-step:last-child::before { background: linear-gradient(90deg, var(--fln-rule) 22%, transparent); }
[data-theme-layout="factory-line"] .fln-process-sec .f-step-num {
  display: grid; place-items: center; width: 32px; height: 32px; padding: 0;
  border: 2px solid var(--fln-hot); border-radius: 50%; background: var(--bg);
  font-size: .84rem; line-height: 1; color: var(--accent);
}
[data-theme-layout="factory-line"] .fln-process-sec .f-step-title { margin-top: .75rem; }

/* ---- 分类 / 行业 / FAQ / 图集：跟随直角工业气质 ------------------------- */
[data-theme-layout="factory-line"] .fln-wrap .f-cat-card,
[data-theme-layout="factory-line"] .fln-wrap .f-industry,
[data-theme-layout="factory-line"] .fln-wrap .f-gallery-item { border-radius: 0; }
[data-theme-layout="factory-line"] .fln-wrap .f-cat-card:hover { transform: none; border-left: 3px solid var(--fln-hot); padding-left: calc(.7rem - 2px); }

/* ---- 动态：细行清单 ----------------------------------------------------- */
[data-theme-layout="factory-line"] .fln-news-head { border-bottom-width: 1px; border-bottom-color: var(--line); }
[data-theme-layout="factory-line"] .fln-news-head h2 { font-size: 1.15rem; color: var(--ink-soft); }
[data-theme-layout="factory-line"] .fln-news-item {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-line"] .fln-news-item:hover { color: var(--accent); }
[data-theme-layout="factory-line"] .fln-news-item time { color: var(--muted); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-line"] .fln-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* =========================================================================
   内页重塑（不改公共模板，只重塑既有类）
   ① 商品/归档列表 .link-grid → 工位流卡片：左侧 ST 序号列（CSS 计数器）+ 橙分隔筋
   ② 商品详情 .pd-* → 装配步骤条：面包屑=工位路径条、缩略图=工位串、规格表=带序号步骤
   ========================================================================= */
[data-theme-layout="factory-line"] .link-grid {
  grid-template-columns: minmax(0, 1fr); gap: 0; counter-reset: fln-row;
  border-top: 2px solid var(--ink);
}
[data-theme-layout="factory-line"] .link-card {
  display: grid; grid-template-columns: 74px 116px minmax(0, 1fr); align-items: center; gap: 0 1.1rem;
  padding: .75rem .4rem .75rem 0; border: 0; border-bottom: 1px solid var(--line);
  border-radius: 0; background: transparent;
}
[data-theme-layout="factory-line"] .link-card::before {
  counter-increment: fln-row; content: "№ " counter(fln-row, decimal-leading-zero);
  align-self: stretch; display: grid; place-items: center;
  border-right: 3px solid var(--fln-hot); color: var(--muted);
  font-family: var(--mono); font-size: .72rem; font-weight: 700; letter-spacing: .1em;
}
[data-theme-layout="factory-line"] .link-card:hover { transform: none; box-shadow: none; background: color-mix(in srgb, var(--fln-hot) 7%, transparent); }
[data-theme-layout="factory-line"] .link-card:hover::before { color: var(--accent); }
[data-theme-layout="factory-line"] .lc-cover { border-radius: 0; border: 1px solid var(--line); }
[data-theme-layout="factory-line"] .lc-body { padding: 0; gap: .25rem; }
[data-theme-layout="factory-line"] .lc-title { font-size: 1rem; }
[data-theme-layout="factory-line"] .lc-intro { -webkit-line-clamp: 1; }
[data-theme-layout="factory-line"] .pd-bc {
  display: flex; flex-wrap: wrap; align-items: center; gap: .2rem .5rem;
  margin-top: 1.1rem; padding: .5rem .85rem; border: 1px solid var(--line);
  border-left: 4px solid var(--fln-hot); background: var(--surface);
  font-family: var(--mono); font-size: .74rem;
}
[data-theme-layout="factory-line"] .pd-media,
[data-theme-layout="factory-line"] .pd-thumb,
[data-theme-layout="factory-line"] .pd-inquiry,
[data-theme-layout="factory-line"] .pd-specs-tablewrap,
[data-theme-layout="factory-line"] .pd-rel-card,
[data-theme-layout="factory-line"] .pd-rel-media { border-radius: 0; }
[data-theme-layout="factory-line"] .pd-thumbs { counter-reset: fln-th; }
[data-theme-layout="factory-line"] .pd-thumb { position: relative; }
[data-theme-layout="factory-line"] .pd-thumb::after {
  counter-increment: fln-th; content: counter(fln-th, decimal-leading-zero);
  position: absolute; left: 0; bottom: 0; padding: .05rem .28rem;
  background: var(--ink); color: var(--bg); font-family: var(--mono); font-size: .55rem; font-weight: 700; line-height: 1.7;
}
[data-theme-layout="factory-line"] .pd-inquiry { border-left: 4px solid var(--fln-hot); }
[data-theme-layout="factory-line"] .pd-specs-tablewrap { border-top: 2px solid var(--ink); }
[data-theme-layout="factory-line"] .pd-specs-table tbody { counter-reset: fln-spec; }
[data-theme-layout="factory-line"] .pd-specs-table th {
  position: relative; padding-left: 3.2rem; background: var(--surface);
  color: var(--ink-soft); font-weight: 650;
}
[data-theme-layout="factory-line"] .pd-specs-table th::before {
  counter-increment: fln-spec; content: counter(fln-spec, decimal-leading-zero);
  position: absolute; left: 1rem; top: .68rem; color: var(--accent);
  font-family: var(--mono); font-size: .7rem; font-weight: 800;
}
[data-theme-layout="factory-line"] .pd-rel-card { position: relative; padding-top: 4px; }
[data-theme-layout="factory-line"] .pd-rel-card::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 4px; background: var(--fln-hot); }

/* ---- 响应式 ------------------------------------------------------------- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-line"] .fln-cells { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-line"] .fln-hero { grid-template-columns: minmax(0, 1fr); align-items: start; gap: 1.6rem; }
  [data-theme-layout="factory-line"] .fln-cells { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-line"] .fln-process-sec .f-process { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 1.6rem; }
  [data-theme-layout="factory-line"] .link-card { grid-template-columns: 62px 96px minmax(0, 1fr); gap: 0 .9rem; }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-line"] .fln-belt-tread { height: 18px; }
  [data-theme-layout="factory-line"] .fln-belt::before,
  [data-theme-layout="factory-line"] .fln-belt::after { top: 2px; width: 12px; height: 12px; }
  [data-theme-layout="factory-line"] .fln-belt::before { left: 6px; }
  [data-theme-layout="factory-line"] .fln-belt::after { right: 6px; }
  [data-theme-layout="factory-line"] .fln-cells { gap: 1rem .5rem; }
  [data-theme-layout="factory-line"] .fln-cell-ex,
  [data-theme-layout="factory-line"] .fln-cell .f-chips { display: none; }
  [data-theme-layout="factory-line"] .fln-news-item { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="factory-line"] .fln-news-item .arrow { display: none; }
  [data-theme-layout="factory-line"] .fln-news-title { white-space: normal; }
  [data-theme-layout="factory-line"] .link-card { grid-template-columns: 52px 84px minmax(0, 1fr); gap: 0 .75rem; }
  [data-theme-layout="factory-line"] .link-card::before { font-size: .64rem; letter-spacing: .04em; }
  [data-theme-layout="factory-line"] .pd-specs-table th { padding-left: 2.6rem; }
  [data-theme-layout="factory-line"] .pd-specs-table th::before { left: .7rem; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-line"] .fln-process-sec .f-process { grid-template-columns: minmax(0, 1fr); gap: 1.1rem; }
  [data-theme-layout="factory-line"] .fln-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .5rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-line"] .fln-belt-tread { animation: none; }
  [data-theme-layout="factory-line"] .fln-cell,
  [data-theme-layout="factory-line"] .fln-cell-media img,
  [data-theme-layout="factory-line"] .link-card { transition: none; }
  [data-theme-layout="factory-line"] .fln-cell:hover { transform: none; }
}

/* =========================================================================
   factory-line 三皮（原生 line / 反差 conveyor / 纯白 line-white）
   实算对比度见每皮注释；--fln-hot 恒为装饰色（彩条/滚轮纹/节点圈），永不作字。
   ========================================================================= */
/* 产线灰 · Line：浅灰工业白 + 产线橙（原生皮）
   ink/bg 15.29、ink/surface 16.77、ink-soft/surface 10.25、muted/surface 5.76、muted/bg 5.25、
   accent 作字 5.56(surface) / 5.07(bg)，hover→accent-soft 7.38 / 6.74（只升不降），
   surface 字压 accent 底 5.56（eyebrow 牌 / WhatsApp 钮），ST 牌 bg 字压 ink 底 15.29，
   传送带带面 #edeeec 上 ink-soft 9.12 / muted 5.12，工位流行悬停底 #ede7e1 上 ink 14.15 / accent 4.70。
   装饰橙 #d7642e 对 surface 3.53（非文字图形件，≥3 达标）。 */
:root[data-theme="line"] {
  --bg: #eff1ef; --surface: #fbfbfa; --ink: #181b19; --ink-soft: #3a403c;
  --muted: #5f6561; --faint: #8f9591; --line: #d2d6d2; --line-soft: #e3e6e3;
  --accent: #ab4718; --accent-soft: #8d3a12; --accent-wash: #f6e6dd;
  --fln-hot: #d7642e;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 8px 24px rgba(24,27,25,.08);
}
:root[data-theme="line"] .btn-primary { color: #fff; }

/* 夜班 · Conveyor：近黑车间 + 琥珀拣灯（反差皮）
   ink/bg 16.30、ink/surface 15.13、ink-soft/surface 11.18、muted/surface 6.38、muted/bg 6.88、
   accent 作字 8.85(surface) / 9.53(bg)，hover→accent-soft 10.98 / 11.82（只升不降），
   深字压琥珀底 9.31（btn-primary #16110a）、surface 字压 accent 底 8.85（WhatsApp 钮），
   ST 牌 bg 字压 ink 底 16.30，带面 #222527 上 ink-soft 9.67 / muted 5.52。
   CTA 通栏在暗皮里翻成浅底（背景=ink），共用眉标的 mix(accent 60%, bg) 只有 4.03，
   本皮改用 #7a5212（5.85）。 */
:root[data-theme="conveyor"] {
  --bg: #0d0f10; --surface: #15181a; --ink: #e9edee; --ink-soft: #c7ced0;
  --muted: #949c9f; --faint: #69716f; --line: #2a3033; --line-soft: #1b2022;
  --accent: #efa93f; --accent-soft: #f7c274; --accent-wash: #3a2a10; --code-bg: #08090a;
  --fln-hot: #f08a2c;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 14px 40px rgba(0,0,0,.5);
}
:root[data-theme="conveyor"] .btn-primary { color: #16110a; }
:root[data-theme="conveyor"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #16110a; }
:root[data-theme="conveyor"] .f-cta .f-eyebrow { color: #7a5212; }
:root[data-theme="conveyor"] .f-stat dt { text-shadow: 0 0 16px rgba(239,169,63,.28); }

/* 白工位 · Line-white：纯白基底（中性灰对齐纯白系）+ 压深的产线橙
   ink/bg 18.72、ink/surface 17.91、ink-soft/surface 9.37、accent 作字 6.09(bg) / 5.83(surface)，
   hover→accent-soft 8.35 / 7.99（只升不降），白字压 accent 底 6.09。
   已知坑：muted #707680 在 surface #fafaf8 上只有 4.38 —— 本皮把所有承载 muted 文字的
   卡面/带面覆写回 --bg 纯白（4.57 达标），规格 chip 的键名改 ink-soft（9.79）。 */
:root[data-theme="line-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #a3461a; --accent-soft: #84360f; --accent-wash: #f7e7de;
  --fln-hot: #c8571f; --fln-belt: #ffffff;
  --w-wide: 1200px; --radius: 2px;
}
:root[data-theme="line-white"] .btn-primary { color: #fff; }
:root[data-theme="line-white"] .site-header { background: var(--bg); }
:root[data-theme="line-white"] .fln-cell,
:root[data-theme="line-white"] .f-stat,
:root[data-theme="line-white"] .f-industry,
:root[data-theme="line-white"] .f-cat-card { background-color: var(--bg); }
:root[data-theme="line-white"] .f-chip { background: var(--bg); }
:root[data-theme="line-white"] .f-chip b { color: var(--ink-soft); }

/* =========================================================================
   LAYOUT: factory-container — 集装箱（工厂族骨架；partial home_factory_container）
   每条选择器限定 [data-theme-layout="factory-container"]，自有类名前缀 ctn-
   （全仓 grep 仅本骨架模板/页头使用）。
   形态：整站读成一座集装箱堆场。
     页头 = 货运单条：自有 define header_factory_container——上层「单据条」
            （反色 ink 底，等宽大写宽字距的收发货格：MARKS 唛头 + 电话/邮箱/WhatsApp，
            未配置项不渲染）+ 下层唛头品牌 / 钢印大写导航 / 常驻 RFQ 报价牌（带 →）；
            ≤620px 回落基础汉堡抽屉，RFQ 收成纯唛头方牌。
     hero  = 箱门大牌：波纹钢竖纹门面（repeating-linear-gradient）左文右窗两栏 + 四缘吊装耳
            （border 车道上的绝对定位小块，不入内容流）+ 底部站点名钢印
            （aria-hidden 装饰，nowrap+clip 钳死绝不撑页）；右窗=「箱门视窗」：
            波纹钢窗框（密纹框带 + 双 2px ink 线）内嵌 hero 图 / 图集首图 / 图纸机械动画，
            右上箱号唛头小牌（ink 底 bg 字）+ 框底 accent 铅封圆点；窗体 aspect-ratio+max-height
            双钳绝不撑首屏，≤920px 图窗收到文案下方、动画窗收起。factory.stats 喷印成
            三色实底块（nth-child 3 色轮转，白字实算 ≥7.4），未配置回落 factory_about。
     商品  = 波纹钢箱面卡：顶梁按分类位次三色轮转（模板发 ctn-c0..N，CSS 只染 c0~c7，
            溢出/无分类回落 ink 默认梁），箱号位 = productSKU。
     图集  = 堆场图带：全宽 surface 横带 + 共享 f-gallery 横向滚动。
     流程  = 共享 f-process 重塑成「航次节点」：三色实底方块序号。
     内页  = 列表 .link-grid 重塑为堆场网格（密排箱面卡 + 顶梁三色轮转）；
            商品详情 .pd-* 重塑为箱单：面包屑=托运条、规格表=左右对照箱单
            （2px ink 外框 + 中缝重线 + 大写等宽键名）、缩略图=贝位号、相关=小箱卡。
   ========================================================================= */
[data-theme-layout="factory-container"] {
  --ctn-c1: #1d4e78;                                              /* 箱色一：远洋蓝 */
  --ctn-c2: #84391d;                                              /* 箱色二：氧化铁锈红 */
  --ctn-c3: #1f5440;                                              /* 箱色三：深海绿 */
  --ctn-onbox: #ffffff;                                           /* 箱面白字（三箱色上实算 ≥7.4） */
  --ctn-onaccent: #ffffff;                                        /* accent 实底上的字（皮可覆写） */
  --ctn-mf-dim: #9aa4ad;                                          /* 单据条标签字（ink 底上 ≥4.5） */
  --ctn-rib: color-mix(in srgb, var(--ink) 6%, transparent);      /* 波纹钢竖纹（纯装饰） */
}
[data-theme-layout="factory-container"] body { background: var(--bg); }
[data-theme-layout="factory-container"] .ctn-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
}
[data-theme-layout="factory-container"] .ctn-wrap:last-of-type { padding-bottom: clamp(3rem, 6vw, 4.4rem); }

/* ---- 页头：货运单条（header_factory_container 专有 DOM）------------------- */
[data-theme-layout="factory-container"] .ctn-header {
  background: var(--surface); -webkit-backdrop-filter: none; backdrop-filter: none;
  border-bottom: 2px solid var(--ink);
}
[data-theme-layout="factory-container"] .ctn-manifest { background: var(--ink); color: var(--bg); }
[data-theme-layout="factory-container"] .ctn-manifest-in {
  display: flex; align-items: center; gap: 1rem;
  width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto; min-height: 34px;
}
[data-theme-layout="factory-container"] .ctn-manifest-cells {
  display: flex; align-items: center; gap: 0; min-width: 0; overflow: hidden;
}
[data-theme-layout="factory-container"] .ctn-mf-cell {
  display: inline-flex; align-items: baseline; gap: .45rem; min-width: 0;
  padding: .3rem 1rem .3rem 0; white-space: nowrap; color: var(--bg); text-decoration: none;
}
[data-theme-layout="factory-container"] .ctn-mf-cell + .ctn-mf-cell {
  padding-left: 1rem; border-left: 1px solid color-mix(in srgb, var(--bg) 24%, transparent);
}
[data-theme-layout="factory-container"] .ctn-mf-cell b {
  flex: none; font-family: var(--mono); font-size: .55rem; font-weight: 800;
  letter-spacing: .18em; text-transform: uppercase; color: var(--ctn-mf-dim);
}
[data-theme-layout="factory-container"] .ctn-mf-cell i {
  overflow: hidden; text-overflow: ellipsis; font-style: normal;
  font-family: var(--mono); font-size: .7rem; letter-spacing: .05em; color: var(--bg);
}
[data-theme-layout="factory-container"] .ctn-mf-marks { flex: 0 1 auto; }
[data-theme-layout="factory-container"] a.ctn-mf-cell:hover i { text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="factory-container"] .ctn-manifest-tools { flex: none; margin-left: auto; }
[data-theme-layout="factory-container"] .ctn-manifest-tools .lang-switch { border-left-color: color-mix(in srgb, var(--bg) 24%, transparent); }
[data-theme-layout="factory-container"] .ctn-manifest-tools .lang-switch > summary { color: var(--ctn-mf-dim); }
[data-theme-layout="factory-container"] .ctn-manifest-tools .lang-switch > summary:hover,
[data-theme-layout="factory-container"] .ctn-manifest-tools .lang-switch[open] > summary { color: var(--bg); }
/* RFQ 报价牌：accent 实底 + 等宽唛头字（--ctn-onaccent 各皮实算 ≥7.3） */
[data-theme-layout="factory-container"] .ctn-rfq {
  display: inline-flex; align-items: center; gap: .5rem; flex: none;
  margin-left: clamp(.8rem, 2vw, 1.4rem); padding: .5rem .85rem;
  background: var(--accent); color: var(--ctn-onaccent); text-decoration: none;
  font-family: var(--mono); font-size: .74rem; font-weight: 800;
  letter-spacing: .1em; text-transform: uppercase; line-height: 1;
  transition: box-shadow var(--speed), transform var(--speed);
}
[data-theme-layout="factory-container"] .ctn-rfq b { font-weight: 800; }
[data-theme-layout="factory-container"] .ctn-rfq .arrow { color: var(--ctn-onaccent); }
[data-theme-layout="factory-container"] .ctn-rfq:hover {
  color: var(--ctn-onaccent); transform: translateY(-1px);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 30%, transparent);
}
@media (min-width: 621px) {
  [data-theme-layout="factory-container"] .ctn-header .wrap { height: 68px; align-items: stretch; }
  [data-theme-layout="factory-container"] .ctn-header .brand {
    align-self: center; margin-right: auto; font-family: var(--sans);
    font-weight: 800; letter-spacing: .12em; text-transform: uppercase;
  }
  [data-theme-layout="factory-container"] .ctn-header .nav { align-self: stretch; align-items: stretch; gap: 0; }
  [data-theme-layout="factory-container"] .ctn-header .nav > a {
    display: inline-flex; align-items: center; padding: 0 clamp(.5rem, 1.2vw, .95rem);
    font-size: .78rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase;
  }
  [data-theme-layout="factory-container"] .ctn-header .nav > a:hover { background: color-mix(in srgb, var(--ink) 5%, transparent); }
  [data-theme-layout="factory-container"] .ctn-header .nav a[aria-current="page"] { color: var(--accent); }
  [data-theme-layout="factory-container"] .ctn-header .nav a[aria-current="page"]::after { top: auto; bottom: 0; height: 4px; background: var(--accent); }
  [data-theme-layout="factory-container"] .ctn-header .nav .search-ico { padding-inline: clamp(.5rem, 1.2vw, .95rem); opacity: 1; color: var(--muted); }
  [data-theme-layout="factory-container"] .ctn-header .nav .search-ico:hover { color: var(--accent); }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-container"] a.ctn-mf-cell { display: none; } /* 联系格收进页脚/CTA，唛头保留 */
  [data-theme-layout="factory-container"] .ctn-mf-marks { padding-right: 0; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-container"] .ctn-header .menu-toggle { order: 3; }
  [data-theme-layout="factory-container"] .ctn-rfq { order: 2; margin-left: auto; padding: .45rem .6rem; }
  [data-theme-layout="factory-container"] .ctn-rfq-t,
  [data-theme-layout="factory-container"] .ctn-rfq .arrow { display: none; } /* 收成纯唛头方牌，可读名走 aria-label */
}

/* ---- hero：箱门大牌 ------------------------------------------------------ */
[data-theme-layout="factory-container"] .ctn-door { position: relative; margin-top: clamp(1.6rem, 3.5vw, 2.6rem); }
/* 吊装耳：绝对定位专属车道 = 门面顶缘 border 线上，宽 26px 小块，绝不入内容流 */
[data-theme-layout="factory-container"] .ctn-door::before,
[data-theme-layout="factory-container"] .ctn-door::after {
  content: ""; position: absolute; top: -5px; width: 26px; height: 10px;
  background: var(--ink); pointer-events: none;
}
[data-theme-layout="factory-container"] .ctn-door::before { left: 18px; }
[data-theme-layout="factory-container"] .ctn-door::after { right: 18px; }
[data-theme-layout="factory-container"] .ctn-door-face {
  position: relative; display: grid; align-content: center;
  min-height: clamp(300px, 42vw, 430px);
  padding: clamp(2rem, 4.5vw, 3.4rem) clamp(1.4rem, 4vw, 3.2rem) clamp(3.4rem, 6vw, 4.6rem);
  border: 2px solid var(--ink); background-color: var(--surface);
  background-image: repeating-linear-gradient(90deg, var(--ctn-rib) 0 3px, transparent 3px 30px);
  overflow: hidden;
}
/* 有视觉时门面开成左文右窗两栏（无视觉保持单栏居左，文案宽度不变） */
[data-theme-layout="factory-container"] .ctn-door.has-img .ctn-door-face,
[data-theme-layout="factory-container"] .ctn-door.has-anim .ctn-door-face {
  grid-template-columns: minmax(0, 1.1fr) minmax(260px, .9fr);
  align-items: center; column-gap: clamp(1.4rem, 3.5vw, 2.8rem);
}
[data-theme-layout="factory-container"] .ctn-door-copy { position: relative; z-index: 1; max-width: 62ch; }
/* 箱门视窗：波纹钢窗框（外 2px ink 框 + 密纹竖纹框带 + 内 2px ink 窗线）嵌图/动画；
   右上箱号唛头小牌（ink 底 bg 字，站点名装饰性钳单行，实算 container 15.30 /
   seafreight 16.45 / container-white 18.72），框底右侧挂 accent 铅封圆点（纯装饰非文字）。
   窗体 aspect-ratio 4/3 + max-height 双钳，图绝对定位 cover——任何图片比例都撑不高首屏。 */
[data-theme-layout="factory-container"] .ctn-port {
  position: relative; z-index: 1; min-width: 0;
  padding: clamp(.55rem, 1.4vw, .9rem);
  border: 2px solid var(--ink); background-color: var(--surface);
  background-image: repeating-linear-gradient(90deg, var(--ctn-rib) 0 3px, transparent 3px 14px);
}
[data-theme-layout="factory-container"] .ctn-port::after { /* 铅封 */
  content: ""; position: absolute; right: 16px; bottom: -8px; width: 13px; height: 13px;
  border-radius: 50%; background: var(--accent);
  box-shadow: 0 0 0 2px var(--surface), 0 0 0 3px var(--ink); pointer-events: none;
}
[data-theme-layout="factory-container"] .ctn-port-no {
  position: absolute; top: -2px; right: 14px; z-index: 2; max-width: calc(100% - 3rem);
  overflow: hidden; white-space: nowrap; padding: .18rem .5rem;
  background: var(--ink); color: var(--bg);
  font-family: var(--mono); font-size: .58rem; font-weight: 800;
  letter-spacing: .18em; text-transform: uppercase; line-height: 1.4;
  pointer-events: none; user-select: none;
}
[data-theme-layout="factory-container"] .ctn-port-win {
  position: relative; overflow: hidden;
  width: 100%; aspect-ratio: 4 / 3; max-height: 330px;
  border: 2px solid var(--ink); background: var(--line-soft);
}
[data-theme-layout="factory-container"] .ctn-port-img,
[data-theme-layout="factory-container"] div.ctn-port-anim {
  position: absolute; inset: 0; width: 100%; height: 100%; min-height: 0;
}
[data-theme-layout="factory-container"] .ctn-port-img { object-fit: cover; }
[data-theme-layout="factory-container"] .ctn-eyebrow {
  width: fit-content; max-width: 100%; margin: 0 0 1.1rem; padding: .3rem .62rem;
  background: var(--accent); color: var(--ctn-onaccent); font-family: var(--mono);
  font-size: .68rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase;
  overflow-wrap: anywhere;
}
[data-theme-layout="factory-container"] .ctn-h1 {
  margin: 0; max-width: 15em; font-family: var(--sans); font-size: clamp(2rem, 4.8vw, 3.4rem);
  font-weight: 800; line-height: 1.07; letter-spacing: -.01em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-container"] .ctn-lede { max-width: 54ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.03rem; line-height: 1.75; }
[data-theme-layout="factory-container"] .ctn-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.8rem; }
[data-theme-layout="factory-container"] .ctn-btn-ghost { border-color: var(--ink); color: var(--ink); }
[data-theme-layout="factory-container"] .ctn-btn-ghost:hover { background: var(--ink); border-color: var(--ink); color: var(--bg); }
/* 站点名钢印：aria-hidden 纯装饰——nowrap + clip 钳死，专属车道 = 门面底缘留出的 padding 带 */
[data-theme-layout="factory-container"] .ctn-brandmark {
  position: absolute; right: clamp(.9rem, 2.5vw, 2rem); bottom: .35rem; z-index: 1; margin: 0;
  max-width: calc(100% - 2rem); overflow: hidden; white-space: nowrap;
  font-family: var(--mono); font-size: clamp(1.7rem, 4.5vw, 3rem); font-weight: 800;
  letter-spacing: .3em; text-transform: uppercase; line-height: 1;
  color: color-mix(in srgb, var(--ink) 14%, transparent); pointer-events: none; user-select: none;
}

/* stats 三色喷印实底块：nth-child 3 色轮转，白字实算 ≥7.4（数字与标签同色） */
[data-theme-layout="factory-container"] .ctn-plates {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 2px; margin: 2px 0 0;
}
[data-theme-layout="factory-container"] .ctn-plate {
  min-width: 0; padding: 1.05rem 1.1rem .95rem; background: var(--ctn-c1); color: var(--ctn-onbox);
  background-image: repeating-linear-gradient(90deg, rgba(255,255,255,.07) 0 2px, transparent 2px 24px);
}
[data-theme-layout="factory-container"] .ctn-plate:nth-child(3n+2) { background-color: var(--ctn-c2); }
[data-theme-layout="factory-container"] .ctn-plate:nth-child(3n) { background-color: var(--ctn-c3); }
[data-theme-layout="factory-container"] .ctn-plate dt {
  margin: 0; font-family: var(--mono); font-size: clamp(1.45rem, 2.4vw, 2rem); font-weight: 800;
  line-height: 1.05; letter-spacing: -.01em; font-variant-numeric: tabular-nums; overflow-wrap: anywhere;
}
[data-theme-layout="factory-container"] .ctn-plate dd {
  margin: .4rem 0 0; font-size: .68rem; font-weight: 650; letter-spacing: .13em;
  text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="factory-container"] .ctn-door-about { margin-top: 2px; }
[data-theme-layout="factory-container"] .ctn-door-about .f-about { border-radius: 0; border-width: 2px; }
[data-theme-layout="factory-container"] .ctn-seals { margin-top: 1.1rem; }
[data-theme-layout="factory-container"] .ctn-seals .f-cert:nth-child(odd),
[data-theme-layout="factory-container"] .ctn-seals .f-cert:nth-child(even) { transform: none; border-radius: 0; }

/* ---- 堆场图带：全宽 surface 横带 + 共享 f-gallery -------------------------- */
[data-theme-layout="factory-container"] .ctn-yard {
  margin-top: clamp(2.4rem, 5vw, 3.4rem); padding: clamp(1.4rem, 3vw, 2rem) 0 1rem;
  border-block: 1px solid var(--line); background: var(--surface);
}
[data-theme-layout="factory-container"] .ctn-yard-in { width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto; }
[data-theme-layout="factory-container"] .ctn-yard-label {
  margin: 0 0 .8rem; font-family: var(--mono); font-size: .68rem; font-weight: 800;
  letter-spacing: .2em; text-transform: uppercase; color: var(--muted);
}
[data-theme-layout="factory-container"] .ctn-yard .f-gallery-item { border-radius: 0; }

/* ---- 区块头 -------------------------------------------------------------- */
[data-theme-layout="factory-container"] .ctn-section { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-container"] .ctn-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
  margin-bottom: 1.3rem; padding-bottom: .7rem; border-bottom: 2px solid var(--ink);
}
[data-theme-layout="factory-container"] .ctn-head h2 { margin: 0; font-size: clamp(1.35rem, 2.4vw, 1.7rem); font-weight: 790; overflow-wrap: anywhere; }
[data-theme-layout="factory-container"] .ctn-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-container"] .ctn-head > a:hover { color: var(--accent); }

/* ---- 商品：波纹钢箱面卡（顶梁三色轮转 + 箱号 = SKU）----------------------- */
[data-theme-layout="factory-container"] .ctn-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.1rem .8rem; }
[data-theme-layout="factory-container"] .ctn-box {
  display: flex; min-width: 0; flex-direction: column;
  border: 1px solid var(--line); border-radius: 0; background: var(--surface); color: var(--ink);
  overflow: hidden; transition: border-color var(--speed), transform var(--speed);
}
[data-theme-layout="factory-container"] .ctn-box:hover { border-color: var(--accent); transform: translateY(-3px); color: var(--ink); }
/* 顶梁：默认 ink 梁 + bg 字（分类溢出 c8+/无分类同样回落）；c0~c7 三色轮转吃 --ctn-boxc */
[data-theme-layout="factory-container"] .ctn-box-top {
  display: flex; align-items: baseline; justify-content: space-between; gap: .6rem;
  padding: .34rem .6rem; background: var(--ctn-boxc, var(--ink)); color: var(--ctn-boxt, var(--bg));
}
[data-theme-layout="factory-container"] .ctn-c0, [data-theme-layout="factory-container"] .ctn-c3, [data-theme-layout="factory-container"] .ctn-c6 { --ctn-boxc: var(--ctn-c1); --ctn-boxt: var(--ctn-onbox); }
[data-theme-layout="factory-container"] .ctn-c1, [data-theme-layout="factory-container"] .ctn-c4, [data-theme-layout="factory-container"] .ctn-c7 { --ctn-boxc: var(--ctn-c2); --ctn-boxt: var(--ctn-onbox); }
[data-theme-layout="factory-container"] .ctn-c2, [data-theme-layout="factory-container"] .ctn-c5 { --ctn-boxc: var(--ctn-c3); --ctn-boxt: var(--ctn-onbox); }
[data-theme-layout="factory-container"] .ctn-box-cat {
  min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
  font-family: var(--mono); font-size: .6rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase;
}
[data-theme-layout="factory-container"] .ctn-box-no {
  flex: none; font-family: var(--mono); font-size: .6rem; font-weight: 700; letter-spacing: .09em; text-transform: uppercase;
}
[data-theme-layout="factory-container"] .ctn-box-face {
  position: relative; display: grid; place-items: center; aspect-ratio: 4 / 3;
  background: var(--line-soft); overflow: hidden;
}
[data-theme-layout="factory-container"] .ctn-box-face img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
[data-theme-layout="factory-container"] .ctn-box:hover .ctn-box-face img { transform: scale(1.03); }
[data-theme-layout="factory-container"] .ctn-box-gen {
  background-color: var(--surface);
  background-image: repeating-linear-gradient(90deg, var(--ctn-rib) 0 3px, transparent 3px 22px);
}
[data-theme-layout="factory-container"] .ctn-box-gen b { font-family: var(--sans); font-size: 2.9rem; color: var(--accent); }
[data-theme-layout="factory-container"] .ctn-box-body { display: flex; flex: 1; flex-direction: column; gap: .3rem; padding: .8rem .9rem 1rem; }
[data-theme-layout="factory-container"] .ctn-box-title { font-size: .97rem; font-weight: 720; line-height: 1.4; overflow-wrap: anywhere; }
[data-theme-layout="factory-container"] .ctn-box-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .8rem; line-height: 1.55; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="factory-container"] .ctn-empty { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center; }

/* ---- 航次流程：共享 f-process 重塑成三色航段方块 -------------------------- */
[data-theme-layout="factory-container"] .ctn-voyage .f-step-num {
  display: grid; place-items: center; width: 34px; height: 34px; padding: 0;
  background: var(--ctn-c1); color: var(--ctn-onbox); font-size: .88rem;
}
[data-theme-layout="factory-container"] .ctn-voyage .f-step:nth-child(3n+2) .f-step-num { background: var(--ctn-c2); }
[data-theme-layout="factory-container"] .ctn-voyage .f-step:nth-child(3n) .f-step-num { background: var(--ctn-c3); }
[data-theme-layout="factory-container"] .ctn-voyage .f-step::before { top: 16px; }
[data-theme-layout="factory-container"] .ctn-voyage .f-step-title { margin-top: .7rem; }

/* ---- 分类 / 行业 / FAQ：直角箱体气质 ------------------------------------- */
[data-theme-layout="factory-container"] .ctn-wrap .f-cat-card,
[data-theme-layout="factory-container"] .ctn-wrap .f-cat-media,
[data-theme-layout="factory-container"] .ctn-wrap .f-industry { border-radius: 0; }
[data-theme-layout="factory-container"] .ctn-wrap .f-cat-card:hover { transform: none; border-left: 3px solid var(--accent); padding-left: calc(.7rem - 2px); }

/* ---- 动态：细行清单 ------------------------------------------------------ */
[data-theme-layout="factory-container"] .ctn-news .ctn-head { border-bottom-width: 1px; border-bottom-color: var(--line); }
[data-theme-layout="factory-container"] .ctn-news .ctn-head h2 { font-size: 1.15rem; color: var(--ink-soft); }
[data-theme-layout="factory-container"] .ctn-news-item {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-container"] .ctn-news-item:hover { color: var(--accent); }
[data-theme-layout="factory-container"] .ctn-news-item time { color: var(--muted); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-container"] .ctn-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* =========================================================================
   内页重塑（不改公共模板，只重塑既有类）
   ① 商品/归档列表 .link-grid → 堆场网格：密排直角箱面卡，顶梁 nth-child 三色轮转
   ② 商品详情 .pd-* → 箱单：面包屑=托运条、缩略图=贝位号、规格表=左右对照箱单、
      相关商品=顶梁三色小箱卡
   ========================================================================= */
[data-theme-layout="factory-container"] .link-grid { grid-template-columns: repeat(auto-fill, minmax(215px, 1fr)); gap: 1rem .8rem; }
[data-theme-layout="factory-container"] .link-card {
  position: relative; padding-top: 6px; border-radius: 0; background: var(--surface);
}
[data-theme-layout="factory-container"] .link-card::before {
  content: ""; position: absolute; top: 0; left: 0; right: 0; height: 6px; background: var(--ctn-c1);
}
[data-theme-layout="factory-container"] .link-card:nth-child(3n+2)::before { background: var(--ctn-c2); }
[data-theme-layout="factory-container"] .link-card:nth-child(3n)::before { background: var(--ctn-c3); }
[data-theme-layout="factory-container"] .link-card:hover { box-shadow: none; border-color: var(--accent); }
[data-theme-layout="factory-container"] .lc-cover {
  border-radius: 0; background-color: var(--line-soft);
  background-image: repeating-linear-gradient(90deg, var(--ctn-rib) 0 3px, transparent 3px 22px);
}
[data-theme-layout="factory-container"] .pd-bc {
  display: flex; flex-wrap: wrap; align-items: center; gap: .2rem .5rem;
  margin-top: 1.1rem; padding: .5rem .85rem; border: 1px solid var(--line);
  border-left: 5px solid var(--ctn-c1); background: var(--surface);
  font-family: var(--mono); font-size: .74rem;
}
[data-theme-layout="factory-container"] .pd-media,
[data-theme-layout="factory-container"] .pd-thumb,
[data-theme-layout="factory-container"] .pd-inquiry,
[data-theme-layout="factory-container"] .pd-rel-card,
[data-theme-layout="factory-container"] .pd-rel-media { border-radius: 0; }
/* 缩略图 = 贝位号（BAY 01…，CSS 计数器；ink 牌 + bg 字实算 ≥15.3） */
[data-theme-layout="factory-container"] .pd-thumbs { counter-reset: ctn-bay; }
[data-theme-layout="factory-container"] .pd-thumb { position: relative; }
[data-theme-layout="factory-container"] .pd-thumb::after {
  counter-increment: ctn-bay; content: "№ " counter(ctn-bay, decimal-leading-zero);
  position: absolute; right: 0; bottom: 0; padding: .05rem .3rem;
  background: var(--ink); color: var(--bg); font-family: var(--mono); font-size: .55rem; font-weight: 700; line-height: 1.7;
}
[data-theme-layout="factory-container"] .pd-inquiry { border-left: 5px solid var(--accent); }
/* 规格表 = 箱单左右对照：2px ink 外框、中缝重线、大写等宽键名右对齐、值列 tabular */
[data-theme-layout="factory-container"] .pd-specs-tablewrap { border: 2px solid var(--ink); }
[data-theme-layout="factory-container"] .pd-specs-table th {
  width: 38%; padding-right: 1.1rem; border-right: 2px solid var(--ink);
  background: var(--surface); color: var(--ink-soft); text-align: right;
  font-family: var(--mono); font-size: .78rem; font-weight: 700;
  letter-spacing: .07em; text-transform: uppercase;
}
[data-theme-layout="factory-container"] .pd-specs-table td { font-variant-numeric: tabular-nums; }
[data-theme-layout="factory-container"] .pd-rel-card { position: relative; padding-top: 5px; }
[data-theme-layout="factory-container"] .pd-rel-card::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 5px; background: var(--ctn-c1); }
[data-theme-layout="factory-container"] .pd-rel-card:nth-child(3n+2)::before { background: var(--ctn-c2); }
[data-theme-layout="factory-container"] .pd-rel-card:nth-child(3n)::before { background: var(--ctn-c3); }

/* ---- 响应式 -------------------------------------------------------------- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-container"] .ctn-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-container"] .ctn-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-container"] .ctn-door-face { min-height: 0; }
  /* 视窗收到文案下方：单栏、限宽限高；动画窗是补位视觉，窄屏整个收起绝不压文字 */
  [data-theme-layout="factory-container"] .ctn-door.has-img .ctn-door-face,
  [data-theme-layout="factory-container"] .ctn-door.has-anim .ctn-door-face { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="factory-container"] .ctn-door.has-anim .ctn-port { display: none; }
  [data-theme-layout="factory-container"] .ctn-port { justify-self: start; margin-top: 1.6rem; width: min(100%, 440px); }
  [data-theme-layout="factory-container"] .ctn-port-win { max-height: 260px; }
  [data-theme-layout="factory-container"] .ctn-voyage .f-process { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 1.6rem; }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-container"] .ctn-door::before,
  [data-theme-layout="factory-container"] .ctn-door::after { width: 18px; height: 8px; top: -4px; } /* 吊装耳归位收小 */
  [data-theme-layout="factory-container"] .ctn-door-face { padding-bottom: 2.8rem; }
  [data-theme-layout="factory-container"] .ctn-port { width: 100%; margin-top: 1.3rem; }
  [data-theme-layout="factory-container"] .ctn-port-win { max-height: 220px; }
  [data-theme-layout="factory-container"] .ctn-brandmark { font-size: 1.3rem; letter-spacing: .22em; }
  [data-theme-layout="factory-container"] .ctn-plates { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-container"] .ctn-grid { gap: 1rem .5rem; }
  [data-theme-layout="factory-container"] .ctn-box-ex,
  [data-theme-layout="factory-container"] .ctn-box .f-chips { display: none; }
  [data-theme-layout="factory-container"] .ctn-news-item { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="factory-container"] .ctn-news-item .arrow { display: none; }
  [data-theme-layout="factory-container"] .ctn-news-title { white-space: normal; }
  [data-theme-layout="factory-container"] .pd-specs-table th { width: 34%; min-width: 7.5rem; padding-right: .7rem; font-size: .7rem; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-container"] .ctn-voyage .f-process { grid-template-columns: minmax(0, 1fr); gap: 1.1rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-container"] .ctn-box,
  [data-theme-layout="factory-container"] .ctn-box-face img,
  [data-theme-layout="factory-container"] .ctn-rfq,
  [data-theme-layout="factory-container"] .link-card { transition: none; }
  [data-theme-layout="factory-container"] .ctn-box:hover,
  [data-theme-layout="factory-container"] .ctn-rfq:hover { transform: none; }
  [data-theme-layout="factory-container"] .ctn-box:hover .ctn-box-face img { transform: none; }
}

/* =========================================================================
   factory-container 三皮（原生 container / 反差 seafreight / 纯白 container-white）
   实算对比度见每皮注释；--ctn-c1/c2/c3 为箱色实底（白字 --ctn-onbox 全部 ≥7.4），
   --ctn-rib 恒为装饰竖纹，永不作字。
   ========================================================================= */
/* 港口蓝灰 · Container：蓝灰港雾底 + 远洋蓝（原生皮）
   ink/bg 15.30、ink/surface 16.90、ink-soft/surface 9.84、ink-soft/bg 8.90、
   muted/surface 5.88、muted/bg 5.32，accent 作字 7.05(surface) / 6.38(bg)，
   hover→accent-soft 9.90 / 8.96（只升不降），白字压 accent 底 7.30（RFQ 牌/eyebrow/btn-primary），
   箱色白字 c1 8.70 / c2 8.13 / c3 8.75，默认顶梁 bg 字压 ink 底 15.30，
   单据条标签 #9aa4ad 压 ink 底 6.91、值字 bg 压 ink 底 15.30，
   WhatsApp 钮 surface 字压 accent 底 7.05。装饰竖纹 ink 6% 非文字。 */
:root[data-theme="container"] {
  --bg: #edf0f2; --surface: #fafbfc; --ink: #151a1f; --ink-soft: #3a424b;
  --muted: #5b636c; --faint: #8a929b; --line: #d0d5da; --line-soft: #e3e7ea;
  --accent: #1f5a88; --accent-soft: #17436a; --accent-wash: #e2ecf4;
  --ctn-c1: #1d4e78; --ctn-c2: #84391d; --ctn-c3: #1f5440;
  --ctn-mf-dim: #9aa4ad;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 8px 24px rgba(21,26,31,.08);
}
:root[data-theme="container"] .btn-primary { color: #fff; }

/* 夜港 · Seafreight：深蓝黑夜港 + 岸桥橙（反差皮）
   ink/bg 16.45、ink/surface 15.08、ink-soft/surface 11.06、muted/surface 6.38、muted/bg 6.96，
   accent 作字 7.93(surface) / 8.65(bg)，hover→accent-soft 10.20 / 11.13（只升不降），
   深字 #1a1206 压 accent 底 8.29（RFQ 牌/eyebrow/btn-primary，--ctn-onaccent 覆写），
   箱色白字 c1 7.78 / c2 7.41 / c3 8.19，默认顶梁 bg 字压 ink 底 16.45（onbox 不上 ink 梁），
   单据条标签 #4a5560 压 ink(浅)底 6.47，WhatsApp 钮 surface 字压 accent 底 7.93。
   CTA 通栏翻浅底（背景=ink）：共用眉标 mix(accent 60%, bg) 只有 4.42，
   本皮覆写 #8a5a17（5.02）。 */
:root[data-theme="seafreight"] {
  --bg: #0a0e14; --surface: #121826; --ink: #e9edf2; --ink-soft: #c6cdd6;
  --muted: #939ca8; --faint: #67707c; --line: #27303f; --line-soft: #1a2130;
  --accent: #f09a3e; --accent-soft: #f6b96e; --accent-wash: #33230e; --code-bg: #060a10;
  --ctn-c1: #205585; --ctn-c2: #8f3c1e; --ctn-c3: #1e5943;
  --ctn-onaccent: #1a1206; --ctn-mf-dim: #4a5560;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 14px 40px rgba(0,0,0,.5);
}
:root[data-theme="seafreight"] .btn-primary { color: #1a1206; }
:root[data-theme="seafreight"] .f-cta .f-eyebrow { color: #8a5a17; }
:root[data-theme="seafreight"] .ctn-plate dt { text-shadow: 0 0 18px rgba(0,0,0,.35); }

/* 白堆场 · Container-white：纯白基底（中性灰对齐纯白系）+ 压深远洋蓝
   ink/bg 18.72、ink/surface 17.91、ink-soft/surface 9.37、accent 作字 7.98(bg) / 7.63(surface)，
   hover→accent-soft 10.62 / 10.16（只升不降），白字压 accent 底 7.98，
   箱色白字 c1 8.97 / c2 8.21 / c3 8.99，默认顶梁 bg 字压 ink 底 18.72，
   单据条标签 #a3a9b3 压 ink 底 7.92。
   已知坑：muted #707680 在 surface #fafaf8 上只有 4.38 —— 本皮把所有承载 muted 文字的
   卡面/横带覆写回 --bg 纯白（4.57 达标），规格 chip 的键名改 ink-soft（9.79）。 */
:root[data-theme="container-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #1d5480; --accent-soft: #164165; --accent-wash: #e7eff6;
  --ctn-c1: #1c4c75; --ctn-c2: #813a1e; --ctn-c3: #1e5240;
  --ctn-mf-dim: #a3a9b3;
  --w-wide: 1200px; --radius: 2px;
}
:root[data-theme="container-white"] .btn-primary { color: #fff; }
:root[data-theme="container-white"] .site-header { background: var(--bg); }
:root[data-theme="container-white"] .ctn-box,
:root[data-theme="container-white"] .ctn-yard,
:root[data-theme="container-white"] .f-industry,
:root[data-theme="container-white"] .f-cat-card,
:root[data-theme="container-white"] .link-card,
:root[data-theme="container-white"] .pd-rel-card { background-color: var(--bg); }
:root[data-theme="container-white"] .f-chip { background: var(--bg); }
:root[data-theme="container-white"] .f-chip b { color: var(--ink-soft); }

/* =========================================================================
   LAYOUT: factory-draftdesk — 图纸台（工厂族骨架；partial home_factory_draftdesk）
   每条选择器限定 [data-theme-layout="factory-draftdesk"]，自有类名前缀 dft-（全仓未占用）。
   形态：整站铺蓝图纸网格底（body 双层 linear-gradient，格距 96px/24px 固定像素，
         不随内容与视口变；纯白皮整片关掉）。
     页头 = 图层标签页：CSS 重塑标准 .site-header——导航项做成相连方框标签
            （margin-left:-1px 共边），当前项 accent 实底 + --dft-on 反白字；
            整段包在 min-width:621px 内，≤620px 交还基础汉堡抽屉。
     首屏 = 一整张图纸 .dft-sheet：双线图框（2px border + 偏移 outline 细线）；
            视图区（文案 + hero 槽）→ 修订表（factory.process 填成 REV 行，虚线行分隔）
            → 图签框（factory.stats 填进 th/td 细线格表格 + 右侧认证签署格）。
     商品 = 图纸卡：奇实线偶虚线边框交替，顶部 DWG 编号条（productSKU 嗅探，
            空则模板生成 DWG-001…）。
     内页 = 商品详情重塑为图纸标题栏（.pd-bc 双线框）+ 主图下缘尺寸标注引线
            （.pd-gallery 专属 22px 车道，纯 CSS，720px 撤线归位）+ 图签规格表；
            商品/归档列表重塑为零件明细表行（ITEM 序号列 + 表格线）。
   ========================================================================= */
[data-theme-layout="factory-draftdesk"] {
  --dft-pad: clamp(1.1rem, 2.6vw, 2.2rem);                              /* 图纸内边距（负 margin 对冲用） */
  --dft-frame: color-mix(in srgb, var(--ink) 62%, transparent);         /* 图框主线（蓝皮上自动翻白线） */
  --dft-frame-soft: color-mix(in srgb, var(--ink) 32%, transparent);    /* 图框副线/虚线 */
  --dft-grid-major: color-mix(in srgb, var(--accent) 15%, transparent); /* 蓝图大格 96px */
  --dft-grid-minor: color-mix(in srgb, var(--accent) 7%, transparent);  /* 蓝图小格 24px */
  --dft-on: var(--surface);                                             /* 当前标签实底上的字色（皮实配） */
  --dft-rule: color-mix(in srgb, var(--accent) 55%, var(--muted));      /* 尺寸标注线（非文字，皮实配≥3） */
}
/* 蓝图网格底：格距固定像素，绝不随内容/视口伸缩 */
[data-theme-layout="factory-draftdesk"] body {
  background-color: var(--bg);
  background-image:
    linear-gradient(var(--dft-grid-major) 1px, transparent 1px),
    linear-gradient(90deg, var(--dft-grid-major) 1px, transparent 1px),
    linear-gradient(var(--dft-grid-minor) 1px, transparent 1px),
    linear-gradient(90deg, var(--dft-grid-minor) 1px, transparent 1px);
  background-size: 96px 96px, 96px 96px, 24px 24px, 24px 24px;
}
[data-theme-layout="factory-draftdesk"] .dft-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-bottom: clamp(3rem, 6vw, 4.4rem);
}

/* ---- 页头：图层标签页（标准 .site-header 的 CSS 重塑，无新增 DOM）-------- */
[data-theme-layout="factory-draftdesk"] .site-header {
  background: var(--surface); -webkit-backdrop-filter: none; backdrop-filter: none;
  border-bottom: 2px solid var(--dft-frame);
}
@media (min-width: 621px) {
  [data-theme-layout="factory-draftdesk"] .site-header .wrap { height: 70px; align-items: end; }
  [data-theme-layout="factory-draftdesk"] .brand {
    align-self: center; margin-right: auto; padding-right: 1.1rem;
    font-family: var(--sans); font-weight: 780; letter-spacing: -.01em;
  }
  [data-theme-layout="factory-draftdesk"] .nav { align-items: stretch; gap: 0; }
  [data-theme-layout="factory-draftdesk"] .nav > a {
    display: flex; align-items: center; padding: .5rem clamp(.6rem, 1.4vw, 1rem) .55rem;
    border: 1px solid var(--line); border-bottom: 0; background: var(--surface);
    font-size: .88rem; font-weight: 650; color: var(--ink-soft); overflow-wrap: anywhere;
  }
  [data-theme-layout="factory-draftdesk"] .nav > a + a { margin-left: -1px; } /* 相连方框：共边 */
  [data-theme-layout="factory-draftdesk"] .nav > a:hover {
    background: color-mix(in srgb, var(--ink) 5%, var(--surface)); color: var(--ink);
  }
  [data-theme-layout="factory-draftdesk"] .nav a[aria-current="page"] {
    background: var(--accent); border-color: var(--accent); color: var(--dft-on); /* 当前图层：实底 */
  }
  [data-theme-layout="factory-draftdesk"] .nav a[aria-current="page"]::after { display: none; } /* 撤基础下划线 */
  [data-theme-layout="factory-draftdesk"] .nav .search-ico { opacity: 1; color: var(--muted); }
  [data-theme-layout="factory-draftdesk"] .nav .search-ico:hover { color: var(--accent); }
  [data-theme-layout="factory-draftdesk"] .nav .lang-switch { align-self: center; margin-left: .7rem; padding-left: .75rem; border-left: 0; }
}

/* ---- 首屏：一整张图纸（双线图框）---------------------------------------- */
[data-theme-layout="factory-draftdesk"] .dft-sheet {
  margin-top: clamp(1.5rem, 3.2vw, 2.4rem);
  border: 2px solid var(--dft-frame); outline: 1px solid var(--dft-frame-soft); outline-offset: 4px;
  background: var(--surface); padding: var(--dft-pad) var(--dft-pad) 0;
}
[data-theme-layout="factory-draftdesk"] .dft-view { display: grid; grid-template-columns: minmax(0, 1fr); gap: clamp(1.2rem, 3vw, 2.4rem); padding-bottom: clamp(1.4rem, 3vw, 2rem); }
[data-theme-layout="factory-draftdesk"] .dft-view.has-visual { grid-template-columns: minmax(0, 1.1fr) minmax(300px, .9fr); align-items: center; }
[data-theme-layout="factory-draftdesk"] .dft-eyebrow {
  width: fit-content; max-width: 100%; margin: 0 0 1rem; padding: .3rem .62rem;
  border: 1px dashed var(--dft-frame-soft); color: var(--accent);
  font-family: var(--mono); font-size: .68rem; font-weight: 800; letter-spacing: .16em;
  text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="factory-draftdesk"] .dft-h1 {
  margin: 0; max-width: 15em; font-size: clamp(2rem, 4.6vw, 3.2rem);
  font-weight: 790; line-height: 1.08; letter-spacing: -.015em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-draftdesk"] .dft-lede { max-width: 56ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75; }
[data-theme-layout="factory-draftdesk"] .dft-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.6rem; }
[data-theme-layout="factory-draftdesk"] .dft-view-media { margin: 0; min-width: 0; border: 1px solid var(--dft-frame-soft); }
[data-theme-layout="factory-draftdesk"] .dft-view-media img { display: block; width: 100%; height: 100%; aspect-ratio: 4 / 3; object-fit: cover; }
[data-theme-layout="factory-draftdesk"] div.dft-view-media.f-heroanim-plain { border: 1px dashed var(--dft-frame-soft); padding: .6rem; }

/* 修订表：factory.process 填成 REV 行（虚线行分隔，贴图框满宽） */
[data-theme-layout="factory-draftdesk"] .dft-rev { list-style: none; margin: 0 calc(var(--dft-pad) * -1); padding: 0; border-top: 1px solid var(--line); }
[data-theme-layout="factory-draftdesk"] .dft-rev-row {
  display: grid; grid-template-columns: auto minmax(0, .8fr) minmax(0, 1.2fr);
  align-items: baseline; gap: .35rem 1rem; padding: .55rem var(--dft-pad);
  border-bottom: 1px dashed var(--line);
}
[data-theme-layout="factory-draftdesk"] .dft-rev-row:last-child { border-bottom: 0; }
[data-theme-layout="factory-draftdesk"] .dft-rev-no { color: var(--accent); font-family: var(--mono); font-size: .72rem; font-weight: 800; letter-spacing: .1em; }
[data-theme-layout="factory-draftdesk"] .dft-rev-no::before { content: "↻ "; color: var(--muted); font-weight: 700; }
[data-theme-layout="factory-draftdesk"] .dft-rev-t { font-size: .95rem; font-weight: 720; color: var(--ink); overflow-wrap: anywhere; }
[data-theme-layout="factory-draftdesk"] .dft-rev-n { color: var(--muted); font-size: .82rem; line-height: 1.6; overflow-wrap: anywhere; }

/* 图签框：factory.stats 填进细线格表格，右侧认证签署格 */
[data-theme-layout="factory-draftdesk"] .dft-tb { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, .75fr); margin: 0 calc(var(--dft-pad) * -1); border-top: 2px solid var(--dft-frame); }
[data-theme-layout="factory-draftdesk"] .dft-tb-tbl { width: 100%; border-collapse: collapse; font-size: .92rem; }
[data-theme-layout="factory-draftdesk"] .dft-tb-tbl caption {
  caption-side: top; padding: .55rem var(--dft-pad) .5rem; border-bottom: 1px solid var(--line);
  text-align: left; color: var(--accent);
  font-family: var(--mono); font-size: .68rem; font-weight: 800; letter-spacing: .18em; text-transform: uppercase;
}
[data-theme-layout="factory-draftdesk"] .dft-tb-tbl th,
[data-theme-layout="factory-draftdesk"] .dft-tb-tbl td { padding: .6rem .9rem; border: 1px solid var(--line); }
[data-theme-layout="factory-draftdesk"] .dft-tb-tbl th {
  width: 52%; border-left: 0; background: color-mix(in srgb, var(--ink) 3%, var(--surface));
  color: var(--ink-soft); font-size: .78rem; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
}
[data-theme-layout="factory-draftdesk"] .dft-tb-tbl td { color: var(--ink); font-family: var(--mono); font-size: 1.02rem; font-weight: 800; }
[data-theme-layout="factory-draftdesk"] .dft-tb-tbl tr:first-child th, [data-theme-layout="factory-draftdesk"] .dft-tb-tbl tr:first-child td { border-top: 0; }
[data-theme-layout="factory-draftdesk"] .dft-tb-tbl tr:last-child th, [data-theme-layout="factory-draftdesk"] .dft-tb-tbl tr:last-child td { border-bottom: 0; }
[data-theme-layout="factory-draftdesk"] .dft-tb .f-about { border: 0; border-radius: 0; background-color: transparent; }
[data-theme-layout="factory-draftdesk"] .dft-tb-sign { align-content: flex-start; padding: .9rem var(--dft-pad) 1.1rem 1.1rem; border-left: 1px solid var(--line); }
[data-theme-layout="factory-draftdesk"] .dft-tb-sign .f-certs-label { flex-basis: 100%; }

/* ---- 区块头 -------------------------------------------------------------- */
[data-theme-layout="factory-draftdesk"] .dft-sec { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-draftdesk"] .dft-sec-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
  margin-bottom: 1.3rem; padding-bottom: .7rem; border-bottom: 2px solid var(--dft-frame);
}
[data-theme-layout="factory-draftdesk"] .dft-sec-head h2 { margin: 0; font-size: clamp(1.35rem, 2.4vw, 1.7rem); font-weight: 780; overflow-wrap: anywhere; }
[data-theme-layout="factory-draftdesk"] .dft-sec-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-draftdesk"] .dft-sec-head > a:hover { color: var(--accent); }

/* ---- 商品：图纸卡（奇实偶虚边框交替 + DWG 编号条）------------------------ */
[data-theme-layout="factory-draftdesk"] .dft-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.2rem .9rem; }
[data-theme-layout="factory-draftdesk"] .dft-card {
  display: flex; min-width: 0; flex-direction: column;
  border: 1px solid var(--dft-frame-soft); border-radius: 0; background: var(--surface); color: var(--ink);
  transition: border-color var(--speed), transform var(--speed);
}
[data-theme-layout="factory-draftdesk"] .dft-card:nth-child(even) { border-style: dashed; }
[data-theme-layout="factory-draftdesk"] .dft-card:hover { border-style: solid; border-color: var(--accent); transform: translateY(-3px); color: var(--ink); }
[data-theme-layout="factory-draftdesk"] .dft-card-no {
  padding: .32rem .6rem; border-bottom: 1px dashed var(--line);
  color: var(--muted); font-family: var(--mono); font-size: .6rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase;
  overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
}
[data-theme-layout="factory-draftdesk"] .dft-card:hover .dft-card-no { color: var(--accent); }
[data-theme-layout="factory-draftdesk"] .dft-card-media { display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-draftdesk"] .dft-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
[data-theme-layout="factory-draftdesk"] .dft-card:hover .dft-card-media img { transform: scale(1.03); }
[data-theme-layout="factory-draftdesk"] .dft-card-gen b { font-family: var(--sans); font-size: 2.9rem; color: var(--accent); }
[data-theme-layout="factory-draftdesk"] .dft-card-body { display: flex; flex: 1; flex-direction: column; gap: .3rem; padding: .75rem .85rem 1rem; }
[data-theme-layout="factory-draftdesk"] .dft-card-cat { width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 750; letter-spacing: .07em; text-transform: uppercase; }
[data-theme-layout="factory-draftdesk"] .dft-card-title { font-size: .97rem; font-weight: 720; line-height: 1.4; overflow-wrap: anywhere; }
[data-theme-layout="factory-draftdesk"] .dft-empty { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center; }

/* ---- 共享件跟随制图气质：直角、虚线注记 chip、分类卡引线悬停 -------------- */
[data-theme-layout="factory-draftdesk"] .f-chip { background: none; border-style: dashed; border-radius: 0; }
[data-theme-layout="factory-draftdesk"] .dft-wrap .f-cat-card,
[data-theme-layout="factory-draftdesk"] .dft-wrap .f-industry,
[data-theme-layout="factory-draftdesk"] .dft-wrap .f-gallery-item { border-radius: 0; }
[data-theme-layout="factory-draftdesk"] .dft-wrap .f-cat-card:hover { transform: none; border-style: dashed; border-color: var(--accent); }
[data-theme-layout="factory-draftdesk"] .dft-wrap .f-industry::before { background: var(--accent); }

/* ---- 动态：细行清单（hover 只提字色不垫底，muted 件同步升 ink-soft）------ */
[data-theme-layout="factory-draftdesk"] .dft-news .dft-sec-head { border-bottom-width: 1px; border-bottom-color: var(--line); }
[data-theme-layout="factory-draftdesk"] .dft-news .dft-sec-head h2 { font-size: 1.15rem; color: var(--ink-soft); }
[data-theme-layout="factory-draftdesk"] .dft-news-list { border-top: 1px solid var(--line); }
[data-theme-layout="factory-draftdesk"] .dft-news-row {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px dashed var(--line); color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-draftdesk"] .dft-news-row time { color: var(--muted); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-draftdesk"] .dft-news-row:hover .dft-news-title { color: var(--accent); }
[data-theme-layout="factory-draftdesk"] .dft-news-row:hover time { color: var(--ink-soft); }
[data-theme-layout="factory-draftdesk"] .dft-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* =========================================================================
   内页重塑（不改公共模板，只重塑既有类）
   ① 商品/归档列表 .link-grid → 零件明细表行：ITEM 序号列（CSS 计数器）+ 表格线，
      悬停垫 accent 7% 淡底、muted 件升 ink-soft（不降对比）
   ② 商品详情 .pd-* → 图纸页：面包屑=双线图纸标题栏、主图下缘尺寸标注引线
      （.pd-gallery 22px 专属车道，720px 撤线归位）、缩略图=DET 详图编号、
      规格表=图签格（th 细线格+ink-soft）、相关商品=奇实偶虚图纸小卡
   ========================================================================= */
[data-theme-layout="factory-draftdesk"] .link-grid {
  grid-template-columns: minmax(0, 1fr); gap: 0; counter-reset: dft-item;
  border-top: 2px solid var(--dft-frame); border-bottom: 1px solid var(--line);
}
[data-theme-layout="factory-draftdesk"] .link-card {
  display: grid; grid-template-columns: 84px 108px minmax(0, 1fr); align-items: center; gap: 0 1rem;
  padding: .7rem .4rem .7rem 0; border: 0; border-bottom: 1px dashed var(--line);
  border-radius: 0; background: transparent;
}
[data-theme-layout="factory-draftdesk"] .link-card::before {
  counter-increment: dft-item; content: "№ " counter(dft-item, decimal-leading-zero);
  align-self: stretch; display: grid; place-items: center;
  border-right: 1px solid var(--line); color: var(--muted);
  font-family: var(--mono); font-size: .66rem; font-weight: 700; letter-spacing: .08em;
}
[data-theme-layout="factory-draftdesk"] .link-card:hover { transform: none; box-shadow: none; background: color-mix(in srgb, var(--accent) 7%, transparent); }
[data-theme-layout="factory-draftdesk"] .link-card:hover::before { color: var(--accent); }
[data-theme-layout="factory-draftdesk"] .link-card:hover .muted,
[data-theme-layout="factory-draftdesk"] .link-card:hover .lc-foot { color: var(--ink-soft); }
[data-theme-layout="factory-draftdesk"] .lc-cover { border: 1px solid var(--line); border-radius: 0; }
[data-theme-layout="factory-draftdesk"] .lc-body { padding: 0; gap: .25rem; }
[data-theme-layout="factory-draftdesk"] .lc-title { font-size: 1rem; }
[data-theme-layout="factory-draftdesk"] .lc-intro { -webkit-line-clamp: 1; }
[data-theme-layout="factory-draftdesk"] .pd-bc {
  display: flex; flex-wrap: wrap; align-items: center; gap: .2rem .5rem;
  margin-top: 1.2rem; padding: .55rem .9rem;
  border: 1px solid var(--dft-frame); outline: 1px solid var(--dft-frame-soft); outline-offset: 3px;
  background: var(--surface); font-family: var(--mono); font-size: .74rem;
}
/* 尺寸标注引线：主图下缘 22px 专属车道（绝对定位只住这条车道，720px 撤线归位） */
[data-theme-layout="factory-draftdesk"] .pd-gallery { position: relative; padding-bottom: 22px; }
[data-theme-layout="factory-draftdesk"] .pd-gallery::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 7px; height: 9px;
  border-left: 1px solid var(--dft-rule); border-right: 1px solid var(--dft-rule);
  background: linear-gradient(var(--dft-rule), var(--dft-rule)) center / 100% 1px no-repeat;
  pointer-events: none;
}
[data-theme-layout="factory-draftdesk"] .pd-media { border-radius: 0; border-color: var(--dft-frame-soft); }
[data-theme-layout="factory-draftdesk"] .pd-thumbs { counter-reset: dft-det; }
[data-theme-layout="factory-draftdesk"] .pd-thumb { position: relative; border-radius: 0; }
[data-theme-layout="factory-draftdesk"] .pd-thumb::after {
  counter-increment: dft-det; content: "◫ " counter(dft-det, decimal-leading-zero);
  position: absolute; left: 0; bottom: 0; padding: .05rem .3rem;
  background: var(--ink); color: var(--bg); font-family: var(--mono); font-size: .54rem; font-weight: 700; letter-spacing: .08em; line-height: 1.7;
}
[data-theme-layout="factory-draftdesk"] .pd-inquiry { border: 1px solid var(--dft-frame); border-radius: 0; }
[data-theme-layout="factory-draftdesk"] .pd-specs-tablewrap { border-radius: 0; border-top: 2px solid var(--dft-frame); }
[data-theme-layout="factory-draftdesk"] .pd-specs-table th {
  border-right: 1px solid var(--line); background: color-mix(in srgb, var(--ink) 3%, var(--surface));
  color: var(--ink-soft); font-weight: 650;
}
[data-theme-layout="factory-draftdesk"] .pd-rel-card { border-radius: 0; }
[data-theme-layout="factory-draftdesk"] .pd-rel-card:nth-child(even) { border-style: dashed; }
[data-theme-layout="factory-draftdesk"] .pd-rel-card:hover { border-style: solid; }
[data-theme-layout="factory-draftdesk"] .pd-rel-media { border-radius: 0; }

/* ---- 响应式 -------------------------------------------------------------- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-draftdesk"] .dft-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-draftdesk"] .dft-view.has-visual { grid-template-columns: minmax(0, 1fr); align-items: start; gap: 1.4rem; }
  [data-theme-layout="factory-draftdesk"] .dft-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-draftdesk"] .dft-tb { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="factory-draftdesk"] .dft-tb-sign { border-left: 0; border-top: 1px solid var(--line); padding-left: var(--dft-pad); }
  [data-theme-layout="factory-draftdesk"] .dft-tb-tbl th { width: 44%; }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-draftdesk"] .dft-sheet { outline-offset: 3px; }
  [data-theme-layout="factory-draftdesk"] .dft-rev-row { grid-template-columns: auto minmax(0, 1fr); }
  [data-theme-layout="factory-draftdesk"] .dft-rev-n { grid-column: 2; }
  [data-theme-layout="factory-draftdesk"] .dft-grid { gap: 1rem .6rem; }
  [data-theme-layout="factory-draftdesk"] .dft-card .f-chips { display: none; }
  [data-theme-layout="factory-draftdesk"] .dft-news-row { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="factory-draftdesk"] .dft-news-row .arrow { display: none; }
  [data-theme-layout="factory-draftdesk"] .dft-news-title { white-space: normal; }
  [data-theme-layout="factory-draftdesk"] .link-card { grid-template-columns: 62px 88px minmax(0, 1fr); gap: 0 .75rem; }
  [data-theme-layout="factory-draftdesk"] .link-card::before { font-size: .6rem; letter-spacing: .02em; }
  [data-theme-layout="factory-draftdesk"] .pd-gallery { padding-bottom: 0; } /* 标注引线撤线归位 */
  [data-theme-layout="factory-draftdesk"] .pd-gallery::after { content: none; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-draftdesk"] .dft-tb-tbl th,
  [data-theme-layout="factory-draftdesk"] .dft-tb-tbl td { padding: .5rem .7rem; }
  [data-theme-layout="factory-draftdesk"] .dft-tb-tbl td { font-size: .92rem; }
  [data-theme-layout="factory-draftdesk"] .dft-tb-sign { padding-right: 1rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-draftdesk"] .dft-card,
  [data-theme-layout="factory-draftdesk"] .dft-card-media img,
  [data-theme-layout="factory-draftdesk"] .link-card { transition: none; }
  [data-theme-layout="factory-draftdesk"] .dft-card:hover { transform: none; }
  [data-theme-layout="factory-draftdesk"] .dft-card:hover .dft-card-media img { transform: none; }
}

/* =========================================================================
   factory-draftdesk 三皮（原生 draftdesk / 反差 blueline / 纯白 draftdesk-white）
   实算对比度见每皮注释；--dft-rule 恒为非文字标注线（≥3 达标）、--dft-on 只在
   accent 实底上作字。图框/网格线全走 ink/accent 的 color-mix——蓝皮上自动翻白线。
   ========================================================================= */
/* 蓝图白 · Draftdesk：蓝图纸白 + 制图蓝（原生皮）
   ink/bg 13.60、ink/surface 15.17、ink-soft/surface 9.53、muted/bg 4.76、muted/surface 5.31、
   accent 作字 6.90(bg) / 7.70(surface)，hover→accent-soft 9.22 / 10.28（只升不降），
   当前标签白字压 accent 实底 7.70，CTA 反色通栏 bg 字压 ink 13.60、note 7.71、眉标 4.75，
   图签 th 面 #f8f9f9 上 ink-soft 9.03，标注线 #5c7fa3 对 bg 3.75 / surface 4.18（非文字≥3）。 */
:root[data-theme="draftdesk"] {
  --bg: #eef3f9; --surface: #ffffff; --ink: #0f2740; --ink-soft: #33475e;
  --muted: #5b6d82; --faint: #77879a; --line: #cbd8e6; --line-soft: #e2eaf3;
  --accent: #15558f; --accent-soft: #0f4272; --accent-wash: #e3edf8;
  --dft-on: #ffffff; --dft-rule: #5c7fa3;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 8px 24px rgba(15,39,64,.08);
}
:root[data-theme="draftdesk"] .btn-primary { color: #fff; }

/* 深蓝晒图 · Blueline：#10365c 晒图蓝底 + 白线 + 琥珀签批（反差皮）
   ink/bg 11.55、ink/surface 9.29、ink-soft/surface 7.91、muted/bg 6.77、muted/surface 5.45、
   accent 作字 6.69(bg) / 5.38(surface)，hover→accent-soft 7.88 / 6.34（只升不降），
   当前标签 #10365c 字压 accent 实底 6.69（btn-primary 同），图签 th 面 #1e4a73 上 ink-soft 7.34，
   CTA 反色通栏翻浅底：bg 字压 ink 带 11.55、note 5.12；共用眉标 mix(accent 60%, bg)
   在浅带上只有 3.49 —— 本皮改 #6f5f28（5.89）。标注线 #b9d3ec 对 bg 7.98（非文字）。
   网格/图框线吃 ink 的 color-mix 自动翻白＝晒图白线。 */
:root[data-theme="blueline"] {
  --bg: #10365c; --surface: #17456f; --ink: #f4f8fc; --ink-soft: #dbe7f4;
  --muted: #a9c3dd; --faint: #7e9cbc; --line: #3f6d9c; --line-soft: #1c4a79;
  --accent: #edb64b; --accent-soft: #f7c86b; --accent-wash: #2a4a6d; --code-bg: #0b2946;
  --dft-on: #10365c; --dft-rule: #b9d3ec;
  --dft-grid-major: color-mix(in srgb, var(--ink) 13%, transparent);
  --dft-grid-minor: color-mix(in srgb, var(--ink) 6%, transparent);
  --w-wide: 1280px; --radius: 2px; --shadow: 0 14px 40px rgba(0,0,0,.5);
}
:root[data-theme="blueline"] .btn-primary { color: #10365c; }
:root[data-theme="blueline"] .f-cta .f-eyebrow { color: #6f5f28; }

/* 白图台 · Draftdesk-white：纯白基底（中性灰对齐纯白系）+ 压深制图蓝，撤蓝图网格
   ink/bg 18.72、ink/surface 17.91、ink-soft/bg 9.79、accent 作字 9.41(bg) / 9.00(surface)，
   hover→accent-soft 12.87 / 12.31（只升不降），白字压 accent 实底 9.41，CTA note 9.95、眉标 5.78。
   已知坑：muted #707680 在 surface #fafaf8 上仅 4.38 —— 承载 muted 文字的图纸面/卡面
   （dft-sheet/dft-card/f-industry/f-cat-card）全覆写回 --bg 纯白（4.57 达标），
   chip 键名改 ink-soft（9.79）。标注线 #8b929b 对 bg 3.14（非文字）。 */
:root[data-theme="draftdesk-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #8e949c; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #24486f; --accent-soft: #173352; --accent-wash: #eaf0f7;
  --dft-on: #ffffff; --dft-rule: #8b929b;
  --w-wide: 1200px; --radius: 2px;
}
:root[data-theme="draftdesk-white"] .btn-primary { color: #fff; }
:root[data-theme="draftdesk-white"] body { background-image: none; } /* 纯白系身份=无装饰，撤网格 */
:root[data-theme="draftdesk-white"] .site-header { background: var(--bg); }
:root[data-theme="draftdesk-white"] .dft-sheet,
:root[data-theme="draftdesk-white"] .dft-card,
:root[data-theme="draftdesk-white"] .f-industry,
:root[data-theme="draftdesk-white"] .f-cat-card { background-color: var(--bg); }
:root[data-theme="draftdesk-white"] .dft-tb-tbl th { background: #f3f3f1; }
:root[data-theme="draftdesk-white"] .f-chip b { color: var(--ink-soft); }
:root[data-theme="draftdesk-white"] .f-cert { transform: none; border-color: var(--line); outline-color: var(--line-soft); }

/* =========================================================================
   LAYOUT: factory-inspection — 质检单（工厂族骨架；partial home_factory_inspection）
   每条选择器限定 [data-theme-layout="factory-inspection"]，自有类名前缀 insp-（全仓未占用）。
   形态：整页按一份出厂检验报告排版。
     页头 = 双层（header.html 的 header_factory_inspection）：上层「检验流程步骤条」
            （01–04 工序 + 段间虚线连接）+ 右侧圆形文档编号章（纯 CSS 双环圆章，
            rotate -12deg，flex 定位不用绝对定位）；下层 logo + 主导航；
            ≤620px 步骤条整条隐藏，交还基础汉堡抽屉。
     hero  = 报告头（.insp-sheet）：mono 文档眉标 + 双细线，正文=大标题｜样品图，
            factory.stats 渲染成绿描边「检测指标框」（1.5px accent 描边），
            认证槽压在虚线之下当「检验依据」条。
     商品  = 检验单行卡（.insp-row）：左缘 4px 绿粗边 + 中性编号列（productSKU，
            无型号回落行序号）+ 规格项计数徽章（productChips 条数）。
     流程  = 共享 f-process 重塑成检验工序：方形工位号牌 + 虚线连线。
   内页重塑（不改公共模板，只重塑既有类）：
     列表 .link-grid/.link-card/.lc-* → 批次单行：单列行卡 + 左侧 #NN 序号列
            （CSS 计数器）+ 绿色竖筋，悬停整行淡绿底。
     详情 .pd-bc → 报告眉标条（左缘 4px 绿边 + mono）；.pd-specs → 逐项规格表：
            斑马行（accent 6% 混色）+ 中性键列标记 + 右上角本地化规格章（CSS 画，-12deg，
            专属车道=标题行 padding-right 预留，720px 缩小仍归位右上）；
            .pd-inquiry 左缘绿边；.pd-thumb 直角。
   容器规约：width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto。
   ========================================================================= */
[data-theme-layout="factory-inspection"] body { background: var(--bg); }
[data-theme-layout="factory-inspection"] .insp-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding: clamp(1.6rem, 3.4vw, 2.6rem) 0 clamp(3rem, 6vw, 4.4rem);
}

/* ---- 页头：检验流程步骤条 + 圆形文档编号章（新 DOM 见 header_factory_inspection）---- */
[data-theme-layout="factory-inspection"] .insp-header {
  background: var(--surface); -webkit-backdrop-filter: none; backdrop-filter: none;
  border-bottom: 2px solid var(--ink);
}
[data-theme-layout="factory-inspection"] .insp-strip {
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--accent) 7%, var(--bg));
}
[data-theme-layout="factory-inspection"] .insp-strip-in {
  display: flex; align-items: center; gap: 1rem;
  width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto;
  padding-block: .4rem;
}
[data-theme-layout="factory-inspection"] .insp-steps {
  display: flex; flex-wrap: wrap; align-items: center; gap: .2rem 0;
  min-width: 0; margin: 0; padding: 0; list-style: none;
}
[data-theme-layout="factory-inspection"] .insp-steps li {
  display: flex; align-items: center; gap: .38rem; min-width: 0;
  color: var(--ink-soft); font-family: var(--mono); font-size: .68rem;
  font-weight: 650; letter-spacing: .06em; line-height: 1.5; white-space: nowrap;
}
[data-theme-layout="factory-inspection"] .insp-steps li > span {
  color: var(--accent); font-weight: 800; letter-spacing: .12em;
}
/* 工序间虚线连接（检验路径） */
[data-theme-layout="factory-inspection"] .insp-steps li + li::before {
  content: ""; flex: none; width: clamp(14px, 2.4vw, 30px); margin-inline: .65rem;
  border-top: 1px dashed color-mix(in srgb, var(--accent) 48%, transparent);
}
/* 圆形文档编号章：双环 + -12deg 盖章角度；flex 尾部专属位，不用绝对定位 */
[data-theme-layout="factory-inspection"] .insp-seal {
  flex: none; margin-left: auto; display: grid; place-content: center; gap: .04rem;
  width: 46px; height: 46px; border: 2px solid var(--accent); border-radius: 50%;
  outline: 1px solid color-mix(in srgb, var(--accent) 55%, transparent); outline-offset: 2px;
  background: color-mix(in srgb, var(--accent) 10%, var(--bg));
  color: var(--accent); text-align: center; transform: rotate(-12deg);
}
[data-theme-layout="factory-inspection"] .insp-seal b { font-family: var(--mono); font-size: .56rem; font-weight: 800; letter-spacing: .1em; line-height: 1; }
[data-theme-layout="factory-inspection"] .insp-seal i { font-style: normal; font-size: .4rem; font-weight: 700; letter-spacing: .3em; text-transform: uppercase; line-height: 1; }

/* ---- hero：报告头 ------------------------------------------------------- */
[data-theme-layout="factory-inspection"] .insp-sheet {
  border: 1px solid var(--line); border-top: 4px solid var(--accent);
  background: var(--surface); padding: clamp(1.2rem, 2.6vw, 2rem) clamp(1.2rem, 2.8vw, 2.4rem) clamp(1.3rem, 2.6vw, 2rem);
}
[data-theme-layout="factory-inspection"] .insp-sheet-head {
  display: flex; align-items: center; gap: 1rem;
  padding-bottom: .75rem; border-bottom: 1px dashed var(--line);
}
[data-theme-layout="factory-inspection"] .insp-doc { margin: 0; }
[data-theme-layout="factory-inspection"] .insp-doc::after { display: none; }
[data-theme-layout="factory-inspection"] .insp-rule { flex: 1; border-top: 4px double color-mix(in srgb, var(--ink) 62%, transparent); }
[data-theme-layout="factory-inspection"] .insp-sheet-body { padding-block: clamp(1.3rem, 2.6vw, 2rem) clamp(1.2rem, 2.4vw, 1.8rem); }
[data-theme-layout="factory-inspection"] .insp-sheet.has-shot .insp-sheet-body {
  display: grid; grid-template-columns: minmax(0, 1.08fr) minmax(0, .92fr);
  align-items: center; gap: clamp(1.4rem, 3vw, 2.6rem);
}
[data-theme-layout="factory-inspection"] .insp-eyebrow {
  width: fit-content; max-width: 100%; margin: 0 0 1rem; padding: .26rem .6rem;
  background: var(--accent); color: var(--bg); font-family: var(--mono);
  font-size: .68rem; font-weight: 800; letter-spacing: .14em; text-transform: uppercase;
  overflow-wrap: anywhere;
}
[data-theme-layout="factory-inspection"] .insp-h1 {
  margin: 0; max-width: 15em; font-size: clamp(1.9rem, 4.4vw, 3.1rem);
  font-weight: 790; line-height: 1.1; letter-spacing: -.015em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-inspection"] .insp-lede { max-width: 56ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75; }
[data-theme-layout="factory-inspection"] .insp-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.6rem; }
[data-theme-layout="factory-inspection"] .insp-shot { margin: 0; border: 1px solid var(--line); background: var(--line-soft); }
[data-theme-layout="factory-inspection"] .insp-shot img { display: block; width: 100%; aspect-ratio: 4 / 3; object-fit: cover; }
/* 检测指标框：绿描边数字卡（共享 f-stat 重塑；角标随共享规则已是 accent） */
[data-theme-layout="factory-inspection"] .insp-metrics { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .7rem; }
[data-theme-layout="factory-inspection"] .insp-metrics .f-stat { border: 1.5px solid var(--accent); border-radius: 0; }
[data-theme-layout="factory-inspection"] .insp-metrics .f-stat dt { font-size: clamp(1.3rem, 2.1vw, 1.8rem); }
[data-theme-layout="factory-inspection"] .insp-sheet-about .f-about { border-radius: 0; }
/* 检验依据条：认证槽压虚线下 */
[data-theme-layout="factory-inspection"] .insp-standards { margin-top: 1.2rem; padding-top: 1rem; border-top: 1px dashed var(--line); }
[data-theme-layout="factory-inspection"] .insp-standards .f-certs-label { color: var(--ink-soft); }
[data-theme-layout="factory-inspection"] .insp-standards .f-cert { border-radius: 0; }

/* ---- 区块头 ------------------------------------------------------------- */
[data-theme-layout="factory-inspection"] .insp-sec { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-inspection"] .insp-sec-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
  margin-bottom: 1.3rem; padding-bottom: .7rem; border-bottom: 2px solid var(--ink);
}
[data-theme-layout="factory-inspection"] .insp-sec-head h2 { margin: 0; font-size: clamp(1.35rem, 2.4vw, 1.7rem); font-weight: 780; overflow-wrap: anywhere; }
[data-theme-layout="factory-inspection"] .insp-sec-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-inspection"] .insp-sec-head > a:hover { color: var(--accent); }

/* ---- 商品：检验单行卡（左缘绿粗边 + 中性编号 + 规格项计数）-------------- */
[data-theme-layout="factory-inspection"] .insp-list { display: grid; gap: .7rem; }
[data-theme-layout="factory-inspection"] .insp-row {
  display: grid; grid-template-columns: auto 108px minmax(0, 1fr) auto; align-items: center;
  gap: 0 clamp(.8rem, 1.8vw, 1.2rem); padding: .7rem .95rem .7rem 0;
  border: 1px solid var(--line); border-left: 4px solid var(--accent); border-radius: 0;
  background: var(--surface); color: var(--ink);
  transition: border-color var(--speed), background-color var(--speed);
}
[data-theme-layout="factory-inspection"] .insp-row:hover {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 6%, var(--surface));
  color: var(--ink);
}
[data-theme-layout="factory-inspection"] .insp-row-qc {
  align-self: stretch; display: grid; place-items: center; min-width: 4.6rem;
  padding-inline: .8rem; border-right: 1px dashed var(--line);
  color: var(--accent); font-family: var(--mono); font-size: .7rem; font-weight: 800;
  letter-spacing: .08em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-inspection"] .insp-row-media {
  display: grid; place-items: center; width: 108px; aspect-ratio: 4 / 3;
  border: 1px solid var(--line); background: var(--line-soft); overflow: hidden;
}
[data-theme-layout="factory-inspection"] .insp-row-media img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="factory-inspection"] .insp-row-gen b { font-family: var(--sans); font-size: 1.9rem; color: var(--accent); }
[data-theme-layout="factory-inspection"] .insp-row-body { display: flex; min-width: 0; flex-direction: column; gap: .28rem; padding-block: .15rem; }
[data-theme-layout="factory-inspection"] .insp-row-cat { width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 750; letter-spacing: .07em; text-transform: uppercase; }
[data-theme-layout="factory-inspection"] .insp-row-title { font-size: 1rem; font-weight: 730; line-height: 1.4; overflow-wrap: anywhere; }
[data-theme-layout="factory-inspection"] .insp-row-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .8rem; line-height: 1.55; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="factory-inspection"] .insp-row .f-chips { margin-top: .35rem; }
[data-theme-layout="factory-inspection"] .insp-row-mark { display: flex; align-items: center; gap: .7rem; }
/* 规格项计数徽章：productChips 实际条数（wash 底 + accent 数字） */
[data-theme-layout="factory-inspection"] .insp-count {
  display: inline-flex; flex-direction: column; align-items: center; gap: .06rem;
  min-width: 3rem; padding: .34rem .55rem .3rem;
  border: 1px solid color-mix(in srgb, var(--accent) 45%, transparent);
  background: var(--accent-wash); color: var(--accent);
}
[data-theme-layout="factory-inspection"] .insp-count b { font-family: var(--mono); font-size: .95rem; font-weight: 800; line-height: 1; }
[data-theme-layout="factory-inspection"] .insp-count i { font-style: normal; font-size: .5rem; font-weight: 750; letter-spacing: .24em; text-transform: uppercase; }
[data-theme-layout="factory-inspection"] .insp-row-mark .arrow { color: var(--faint); }
[data-theme-layout="factory-inspection"] .insp-row:hover .arrow { color: var(--accent); }
[data-theme-layout="factory-inspection"] .insp-empty { margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center; }

/* ---- 流程：共享 f-process 重塑成检验工序（方形工位号牌 + 虚线）---------- */
[data-theme-layout="factory-inspection"] .insp-flow .f-step::before {
  top: 17px; height: 1px; background: none;
  border-top: 1px dashed color-mix(in srgb, var(--accent) 48%, transparent);
}
[data-theme-layout="factory-inspection"] .insp-flow .f-step:last-child::before { right: 45%; }
[data-theme-layout="factory-inspection"] .insp-flow .f-step-num {
  display: grid; place-items: center; width: 34px; height: 34px; padding: 0;
  border: 2px solid var(--accent); background: var(--surface);
  font-size: .88rem; line-height: 1; color: var(--accent);
}
[data-theme-layout="factory-inspection"] .insp-flow .f-step-title { margin-top: .7rem; }

/* ---- 分类 / 行业 / 图集：跟随单据直角气质 ------------------------------- */
[data-theme-layout="factory-inspection"] .insp-wrap .f-cat-card,
[data-theme-layout="factory-inspection"] .insp-wrap .f-cat-media,
[data-theme-layout="factory-inspection"] .insp-wrap .f-industry,
[data-theme-layout="factory-inspection"] .insp-wrap .f-gallery-item { border-radius: 0; }
[data-theme-layout="factory-inspection"] .insp-wrap .f-cat-card:hover { transform: none; border-left: 3px solid var(--accent); padding-left: calc(.7rem - 2px); }

/* ---- 动态：检验记录清单 -------------------------------------------------- */
[data-theme-layout="factory-inspection"] .insp-news .insp-sec-head { border-bottom-width: 1px; border-bottom-color: var(--line); }
[data-theme-layout="factory-inspection"] .insp-news .insp-sec-head h2 { font-size: 1.15rem; color: var(--ink-soft); }
[data-theme-layout="factory-inspection"] .insp-log-item {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-inspection"] .insp-log-item:hover { color: var(--accent); }
[data-theme-layout="factory-inspection"] .insp-log-item time { color: var(--muted); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-inspection"] .insp-log-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* =========================================================================
   内页重塑（不改公共模板，只重塑既有类）
   ① 商品/归档列表 .link-grid → 批次单行：#NN 序号列（CSS 计数器）+ 绿竖筋
   ② 商品详情 .pd-* → 逐项规格表：报告眉标条 + 斑马行 + 中性键列标记 + 规格章
   ========================================================================= */
[data-theme-layout="factory-inspection"] .link-grid {
  grid-template-columns: minmax(0, 1fr); gap: 0; counter-reset: insp-batch;
  border-top: 2px solid var(--ink);
}
[data-theme-layout="factory-inspection"] .link-card {
  display: grid; grid-template-columns: 80px 112px minmax(0, 1fr); align-items: center; gap: 0 1.1rem;
  padding: .75rem .4rem .75rem 0; border: 0; border-bottom: 1px solid var(--line);
  border-radius: 0; background: transparent;
}
[data-theme-layout="factory-inspection"] .link-card::before {
  counter-increment: insp-batch; content: "#" counter(insp-batch, decimal-leading-zero);
  align-self: stretch; display: grid; place-items: center;
  border-right: 3px solid var(--accent); color: var(--muted);
  font-family: var(--mono); font-size: .72rem; font-weight: 700; letter-spacing: .1em;
}
[data-theme-layout="factory-inspection"] .link-card:hover { transform: none; box-shadow: none; background: color-mix(in srgb, var(--accent) 6%, transparent); }
[data-theme-layout="factory-inspection"] .link-card:hover::before { color: var(--accent); }
[data-theme-layout="factory-inspection"] .lc-cover { border-radius: 0; border: 1px solid var(--line); }
[data-theme-layout="factory-inspection"] .lc-body { padding: 0; gap: .25rem; }
[data-theme-layout="factory-inspection"] .lc-title { font-size: 1rem; }
[data-theme-layout="factory-inspection"] .lc-intro { -webkit-line-clamp: 1; }
/* 详情：报告眉标条 + 逐项检验表 + 本地化规格章 */
[data-theme-layout="factory-inspection"] .pd-bc {
  display: flex; flex-wrap: wrap; align-items: center; gap: .2rem .5rem;
  margin-top: 1.1rem; padding: .5rem .85rem; border: 1px solid var(--line);
  border-left: 4px solid var(--accent); background: var(--surface);
  font-family: var(--mono); font-size: .74rem;
}
[data-theme-layout="factory-inspection"] .pd-media,
[data-theme-layout="factory-inspection"] .pd-thumb,
[data-theme-layout="factory-inspection"] .pd-inquiry,
[data-theme-layout="factory-inspection"] .pd-specs-tablewrap,
[data-theme-layout="factory-inspection"] .pd-rel-card,
[data-theme-layout="factory-inspection"] .pd-rel-media { border-radius: 0; }
[data-theme-layout="factory-inspection"] .pd-inquiry { border-left: 4px solid var(--accent); }
/* 规格章：只说明这里是规格表，不暗示任何未经配置的质检结论。 */
[data-theme-layout="factory-inspection"] .pd-specs { position: relative; }
[data-theme-layout="factory-inspection"] .pd-specs .pd-sec-title { padding-right: 96px; }
[data-theme-layout="factory-inspection"] .pd-specs::before {
  content: attr(data-spec-label); position: absolute; top: -14px; right: 6px; z-index: 1;
  display: grid; place-items: center; width: 68px; height: 68px;
  border: 2px solid var(--accent); border-radius: 50%;
  outline: 1px solid color-mix(in srgb, var(--accent) 55%, transparent); outline-offset: 3px;
  background: color-mix(in srgb, var(--accent) 10%, var(--bg));
  color: var(--accent); font-family: var(--mono); font-size: .78rem; font-weight: 800;
  letter-spacing: .14em; transform: rotate(-12deg); pointer-events: none;
}
[data-theme-layout="factory-inspection"] .pd-specs-tablewrap { border-top: 2px solid var(--ink); }
/* 斑马行 + 中性键列标记：th 底色交还斑马纹，键字提到 ink-soft（三皮全 ≥7 见皮注） */
[data-theme-layout="factory-inspection"] .pd-specs-table th { background: transparent; color: var(--ink-soft); font-weight: 650; }
[data-theme-layout="factory-inspection"] .pd-specs-table tr:nth-child(even) th,
[data-theme-layout="factory-inspection"] .pd-specs-table tr:nth-child(even) td { background: color-mix(in srgb, var(--accent) 6%, var(--surface)); }
[data-theme-layout="factory-inspection"] .pd-specs-table th::before { content: "· "; color: var(--accent); font-weight: 800; }
[data-theme-layout="factory-inspection"] .pd-rel-card { border-left: 3px solid var(--accent); }

/* ---- 响应式 ------------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="factory-inspection"] .insp-sheet.has-shot .insp-sheet-body { grid-template-columns: minmax(0, 1fr); gap: 1.4rem; }
  [data-theme-layout="factory-inspection"] .insp-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .6rem; }
  [data-theme-layout="factory-inspection"] .insp-steps li { font-size: .62rem; }
  [data-theme-layout="factory-inspection"] .insp-steps li + li::before { width: 12px; margin-inline: .45rem; }
  [data-theme-layout="factory-inspection"] .insp-seal { width: 40px; height: 40px; }
  [data-theme-layout="factory-inspection"] .link-card { grid-template-columns: 66px 96px minmax(0, 1fr); gap: 0 .9rem; }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-inspection"] .insp-row { grid-template-columns: auto 84px minmax(0, 1fr); padding-right: .75rem; }
  [data-theme-layout="factory-inspection"] .insp-row-qc { min-width: 3.4rem; padding-inline: .55rem; font-size: .62rem; }
  [data-theme-layout="factory-inspection"] .insp-row-media { width: 84px; }
  [data-theme-layout="factory-inspection"] .insp-row-mark { display: none; }
  [data-theme-layout="factory-inspection"] .insp-row-ex,
  [data-theme-layout="factory-inspection"] .insp-row .f-chips { display: none; }
  [data-theme-layout="factory-inspection"] .insp-log-item { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="factory-inspection"] .insp-log-item .arrow { display: none; }
  [data-theme-layout="factory-inspection"] .insp-log-title { white-space: normal; }
  [data-theme-layout="factory-inspection"] .pd-specs .pd-sec-title { padding-right: 72px; }
  [data-theme-layout="factory-inspection"] .pd-specs::before { top: -8px; right: 2px; width: 54px; height: 54px; font-size: .64rem; }
  [data-theme-layout="factory-inspection"] .link-card { grid-template-columns: 56px 84px minmax(0, 1fr); gap: 0 .75rem; }
  [data-theme-layout="factory-inspection"] .link-card::before { font-size: .64rem; letter-spacing: .04em; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-inspection"] .insp-strip { display: none; }
  [data-theme-layout="factory-inspection"] .insp-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .5rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-inspection"] .insp-row,
  [data-theme-layout="factory-inspection"] .link-card { transition: none; }
}

/* =========================================================================
   factory-inspection 三皮（原生 inspection / 反差 passmark / 纯白 inspection-white）
   实算对比度见每皮注释；绿描边/虚线/圆章边框为非文字件（accent 对面 ≥6 全达标）。
   ========================================================================= */
/* 检验绿白 · Inspection：漂白纸面 + 检验章绿（原生皮）
   ink/bg 15.30、ink/surface 16.83、ink-soft/surface 9.82、muted/surface 5.54、muted/bg 5.03、
   accent 作字 6.60(surface) / 6.00(bg)，hover→accent-soft 9.23 / 8.39（只升不降），
   bg 字压 accent 底 6.00（hero 眉标牌）、白字压 accent 底 6.60（btn-primary）、
   步骤条底 #e2ebe6 上 ink-soft 8.07 / accent 5.42，编号章底 #dce7e0 上 accent 5.20、
   斑马行 #f1f6f4 上 ink 15.41 / ink-soft(键) 8.99，通过徽章 accent/wash 5.57、
   行悬停底 #f1f6f4 上 ink 15.41 / muted(摘要) 5.07 / accent 6.04，
   CTA 反色带：bg 字 15.30 / note 8.44 / 共享眉标 mix60 5.78。 */
:root[data-theme="inspection"] {
  --bg: #f1f5f2; --surface: #ffffff; --ink: #132018; --ink-soft: #38473e;
  --muted: #5d6c63; --faint: #8a978f; --line: #d2dcd5; --line-soft: #e4ebe6;
  --accent: #1a6a41; --accent-soft: #125230; --accent-wash: #e2efe7;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 8px 24px rgba(19,32,24,.08);
}
:root[data-theme="inspection"] .btn-primary { color: #fff; }

/* 夜检 · Passmark：深绿黑车间 + 荧光合格绿（反差皮）
   ink/bg 16.59、ink/surface 15.24、ink-soft/surface 11.21、muted/surface 6.62、muted/bg 7.21、
   accent 作字 10.14(surface) / 11.04(bg)，hover→accent-soft 11.82 / 12.87（只升不降），
   荧光绿底配深字 #0b1310：btn-primary / WhatsApp 钮 / cat-nav active 均 11.04（白字只有 1.9，禁）、
   步骤条底 #0f2119 上 ink-soft 10.87 / accent 9.83，编号章底 #11281c 上 accent 9.16、
   斑马行 #15291e 上 ink 13.52 / ink-soft(键) 9.95，通过徽章 accent/wash 9.18、
   行悬停底 #15291e 上 muted(摘要) 5.87 / accent 9.00。
   CTA 通栏在暗皮翻成浅底（背景=ink #e9f3ec）：深 bg 字 16.59 / note 7.11，
   共享眉标 mix(accent 60%, bg) 只有 3.60 → 本皮覆写 #145232（8.10）。 */
:root[data-theme="passmark"] {
  --bg: #0b1310; --surface: #121d17; --ink: #e9f3ec; --ink-soft: #c4d4c9;
  --muted: #91a597; --faint: #7d9186; --line: #24342b; --line-soft: #18251e;
  --accent: #48e08b; --accent-soft: #7cebae; --accent-wash: #10281b; --code-bg: #060a08;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 14px 40px rgba(0,0,0,.5);
}
:root[data-theme="passmark"] .btn-primary { color: #0b1310; }
:root[data-theme="passmark"] .inquiry-btn.inquiry-wa { color: #0b1310; }
:root[data-theme="passmark"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #0b1310; }
:root[data-theme="passmark"] .f-cta .f-eyebrow { color: #145232; }
:root[data-theme="passmark"] .f-stat dt { text-shadow: 0 0 16px rgba(72,224,139,.25); }
:root[data-theme="passmark"] .insp-seal { box-shadow: 0 0 18px rgba(72,224,139,.22); }

/* 白检 · Inspection-white：纯白基底（中性灰对齐纯白系）+ 压深检验绿
   ink/bg 18.72、ink-soft/bg 9.79、accent 作字 7.23(bg) / 6.92(surface)，
   hover→accent-soft 10.13 / 9.69（只升不降），白字压 accent 底 7.23、
   步骤条底 #eff4f2 上 ink-soft 8.81 / accent 6.51，编号章底 #e8efec 上 accent 6.20、
   斑马行(surface面) #edf1ed 上 ink 16.41 / ink-soft(键) 8.58，通过徽章 accent/wash 6.26、
   CTA 反色带：白字 18.72 / note 9.95 / 眉标 6.46。
   已知坑：muted #707680 在 surface #fafaf8 上仅 4.38 —— 所有承载 muted 文字的
   卡面（报告头/检验行/数字卡/行业卡/分类卡/chip/about）覆写回 --bg 纯白（4.57 达标）；
   行悬停底 mix(accent 6%, bg)=#f1f6f4 上 muted 仍只有 4.19 → 行摘要与 chip 键名
   一并改 ink-soft（静息 9.79 / 悬停底 8.96）。 */
:root[data-theme="inspection-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #1a6340; --accent-soft: #124b2f; --accent-wash: #e7f1ea;
  --w-wide: 1200px; --radius: 2px;
}
:root[data-theme="inspection-white"] .btn-primary { color: #fff; }
:root[data-theme="inspection-white"] .site-header { background: var(--bg); }
:root[data-theme="inspection-white"] .insp-sheet,
:root[data-theme="inspection-white"] .insp-row,
:root[data-theme="inspection-white"] .f-stat,
:root[data-theme="inspection-white"] .f-industry,
:root[data-theme="inspection-white"] .f-cat-card,
:root[data-theme="inspection-white"] .f-about { background-color: var(--bg); }
:root[data-theme="inspection-white"] .insp-row:hover { background: color-mix(in srgb, var(--accent) 6%, var(--bg)); }
:root[data-theme="inspection-white"] .insp-row-ex { color: var(--ink-soft); }
:root[data-theme="inspection-white"] .f-chip { background: var(--bg); }
:root[data-theme="inspection-white"] .f-chip b { color: var(--ink-soft); }

/* =========================================================================
   LAYOUT: factory-rackwall — 货架 warehouse rack front (pure CSS, no JS)
   every selector scoped under [data-theme-layout="factory-rackwall"], classes rkw-*
   页头＝通道牌导航：标准 .site-header 纯 CSS 重塑——每个菜单项变一枚实底胶囊
  （近黑牌面 + 橙色圆牌里的 A/B/C 通道字母，字母由 CSS counter 生成，零 DOM 改动），
   当前项换货架橙实底；≤620px 全部规则撤出（capsule 规则整段关在 min-width:621px 里），
   自然回落基础汉堡抽屉。
   hero＝一格「货位」：上下两道橙色横梁夹住（专属 12px 车道，绝不压内容）+ 两侧立柱，
   左文案右「承重铭牌」（factory.stats 逐条＝一行载重读数 + 四角铆钉 + 虚线内框，
   未配置回落 factory_about），铭牌底缀认证钢印槽；横梁正下方续作业流程刻度带
  （factory.process）与库区实拍带（factory.gallery，横向 scroll-snap）。
   商品＝托盘位卡：整排被上下横梁夹住，每张卡顶一条黑底托盘编号签（静态占位，
   不做绝对定位，任何宽度都不与文字相交）。
   内页重塑：列表＝货架分层（.cat-nav 每分类一条带层号 L1/L2 的横梁层板、
   .link-grid 整排夹在横梁里、.link-card 顶黑签＝托盘位）；详情＝托盘标签大卡
  （.pd-info 顶橙梁 + 黑底分类签 + 铆钉铭牌参数表）。
   hover 一律「只加梁/加框/加下划线」，字色只往 ink 走，绝不降对比。
   ========================================================================= */
[data-theme-layout="factory-rackwall"] {
  --rkw-beam: var(--accent);      /* 货架橙横梁：纯装饰，不承载文字 */
  --rkw-beamink: var(--bg);       /* 橙牌面上的通道字母 */
  --rkw-signhi: var(--ink);       /* 通道牌 hover 底（各皮压到纯黑/纯白，对比只升） */
  --rkw-onacc: #fff;              /* 强调实底上的字 */
}
[data-theme-layout="factory-rackwall"] main { display: block; }
[data-theme-layout="factory-rackwall"] body { background: var(--bg); }
[data-theme-layout="factory-rackwall"] .rkw-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-block: clamp(1.4rem, 3.2vw, 2.2rem) clamp(3rem, 6vw, 4.4rem);
  counter-reset: rkwsec;
}

/* ---- 页头：通道牌导航（标准 .site-header 的 CSS 重塑，无 DOM 分支） ---------- */
[data-theme-layout="factory-rackwall"] .site-header {
  background: var(--bg); border-bottom: 0;
  box-shadow: inset 0 -4px 0 var(--rkw-beam), 0 1px 0 color-mix(in srgb, var(--ink) 18%, transparent);
}
[data-theme-layout="factory-rackwall"] .site-header .brand {
  font-family: var(--sans); font-weight: 800; letter-spacing: .06em; text-transform: uppercase;
}
[data-theme-layout="factory-rackwall"] .site-header .nav { counter-reset: rkwaisle; }
/* 基础态 hover 不换 accent（在浅皮上是降对比），一律走 ink + 下划线 */
[data-theme-layout="factory-rackwall"] .site-header .nav > a:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 4px; }
@media (min-width: 621px) {
  [data-theme-layout="factory-rackwall"] .site-header .nav { gap: .4rem; }
  [data-theme-layout="factory-rackwall"] .site-header .nav > a:not(.search-ico) {
    counter-increment: rkwaisle;
    display: inline-flex; align-items: center; gap: .45rem;
    padding: .34rem .8rem .34rem .38rem; border-radius: 999px;
    background: var(--ink); color: var(--bg);
    font-size: .82rem; font-weight: 700; letter-spacing: .03em;
    transition: background var(--speed), box-shadow var(--speed);
  }
  [data-theme-layout="factory-rackwall"] .site-header .nav > a:not(.search-ico)::before {
    content: counter(rkwaisle, upper-alpha);
    flex: none; display: grid; place-items: center; width: 19px; height: 19px; border-radius: 50%;
    background: var(--rkw-beam); color: var(--rkw-beamink);
    font-family: var(--mono); font-size: .64rem; font-weight: 800; line-height: 1;
  }
  [data-theme-layout="factory-rackwall"] .site-header .nav > a:not(.search-ico):hover {
    background: var(--rkw-signhi); color: var(--bg); text-decoration: none;
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--rkw-beam) 55%, transparent);
  }
  [data-theme-layout="factory-rackwall"] .site-header .nav > a[aria-current="page"] { background: var(--accent); color: var(--rkw-onacc); }
  [data-theme-layout="factory-rackwall"] .site-header .nav > a[aria-current="page"]::before { background: var(--rkw-onacc); color: var(--accent); }
  [data-theme-layout="factory-rackwall"] .site-header .nav > a[aria-current="page"]::after { display: none; }
}

/* ---- hero：一格货位（上下横梁 + 两侧立柱 + 承重铭牌） ---------------------- */
[data-theme-layout="factory-rackwall"] .rkw-bay { position: relative; padding-block: 12px; }
[data-theme-layout="factory-rackwall"] .rkw-bay::before,
[data-theme-layout="factory-rackwall"] .rkw-bay::after {
  content: ""; position: absolute; left: 0; right: 0; height: 12px; border-radius: 2px;
  background: var(--rkw-beam);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ink) 32%, transparent);
  pointer-events: none;
}
[data-theme-layout="factory-rackwall"] .rkw-bay::before { top: 0; }
[data-theme-layout="factory-rackwall"] .rkw-bay::after { bottom: 0; }
[data-theme-layout="factory-rackwall"] .rkw-bay-in {
  display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(290px, .7fr);
  gap: clamp(1.4rem, 3vw, 2.6rem);
  padding: clamp(1.6rem, 3.6vw, 2.8rem) clamp(1rem, 2.4vw, 1.7rem);
  border-inline: 3px solid color-mix(in srgb, var(--ink) 22%, transparent);
  background-image: repeating-linear-gradient(0deg, color-mix(in srgb, var(--ink) 4%, transparent) 0 1px, transparent 1px 30px);
}
[data-theme-layout="factory-rackwall"] .rkw-copy { min-width: 0; align-self: center; }
[data-theme-layout="factory-rackwall"] .rkw-eyebrow {
  width: fit-content; margin: 0 0 .9rem; padding: .26rem .6rem; border-radius: 2px;
  background: var(--accent); color: var(--rkw-onacc);
  font-family: var(--mono); font-size: .7rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase;
  overflow-wrap: anywhere;
}
[data-theme-layout="factory-rackwall"] .rkw-h1 {
  margin: 0; max-width: 15em; font-size: clamp(2rem, 4.6vw, 3.2rem); font-weight: 800;
  line-height: 1.08; letter-spacing: -.015em; color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="factory-rackwall"] .rkw-lede {
  margin: 1rem 0 0; max-width: 56ch; color: var(--ink-soft); font-size: 1rem; line-height: 1.75; overflow-wrap: anywhere;
}
[data-theme-layout="factory-rackwall"] .rkw-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
/* 承重铭牌：双框 + 四角铆钉（background 画，不占 DOM，也不撑高） */
[data-theme-layout="factory-rackwall"] .rkw-plate {
  position: relative; align-self: center; min-width: 0;
  padding: 1rem 1.05rem 1.1rem; border: 2px solid color-mix(in srgb, var(--ink) 40%, transparent); border-radius: 3px;
  background-color: var(--surface);
  background-image:
    radial-gradient(circle at 9px 9px, color-mix(in srgb, var(--ink) 34%, transparent) 0 2.4px, transparent 2.6px),
    radial-gradient(circle at calc(100% - 9px) 9px, color-mix(in srgb, var(--ink) 34%, transparent) 0 2.4px, transparent 2.6px),
    radial-gradient(circle at 9px calc(100% - 9px), color-mix(in srgb, var(--ink) 34%, transparent) 0 2.4px, transparent 2.6px),
    radial-gradient(circle at calc(100% - 9px) calc(100% - 9px), color-mix(in srgb, var(--ink) 34%, transparent) 0 2.4px, transparent 2.6px);
}
[data-theme-layout="factory-rackwall"] .rkw-plate::before {
  content: ""; position: absolute; inset: 6px; border: 1px dashed color-mix(in srgb, var(--ink) 20%, transparent); pointer-events: none;
}
[data-theme-layout="factory-rackwall"] .rkw-plate-t {
  position: relative; margin: 0 0 .5rem; padding-bottom: .45rem;
  border-bottom: 3px solid var(--rkw-beam);
  font-family: var(--mono); font-size: .7rem; font-weight: 800; letter-spacing: .2em; text-transform: uppercase;
  color: var(--ink); overflow-wrap: anywhere;
}
/* 数字卡改「载重读数行」：去角标、去纹理，行间发丝线 */
[data-theme-layout="factory-rackwall"] .rkw-stats { position: relative; grid-template-columns: minmax(0, 1fr); gap: 0; }
[data-theme-layout="factory-rackwall"] .rkw-stats .f-stat {
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: baseline; gap: .8rem;
  padding: .5rem .15rem; border: 0; border-bottom: 1px solid var(--line); border-radius: 0; background: none;
}
[data-theme-layout="factory-rackwall"] .rkw-stats .f-stat:last-child { border-bottom: 0; }
[data-theme-layout="factory-rackwall"] .rkw-stats .f-stat::before,
[data-theme-layout="factory-rackwall"] .rkw-stats .f-stat::after { content: none; }
[data-theme-layout="factory-rackwall"] .rkw-stats .f-stat dt { font-size: clamp(1.2rem, 2vw, 1.6rem); }
[data-theme-layout="factory-rackwall"] .rkw-stats .f-stat dd { justify-self: end; margin: 0; text-align: right; overflow-wrap: anywhere; }
[data-theme-layout="factory-rackwall"] .rkw-plate .f-about { position: relative; border: 0; background: none; padding: .2rem 0 0; }
[data-theme-layout="factory-rackwall"] .rkw-plate .f-about::after { content: none; }
[data-theme-layout="factory-rackwall"] .rkw-certs {
  position: relative; margin-top: .9rem; padding-top: .75rem; gap: .5rem .55rem;
  border-top: 1px dashed color-mix(in srgb, var(--ink) 24%, transparent);
}
[data-theme-layout="factory-rackwall"] .rkw-certs .f-cert { margin: 2px; padding: .35rem .6rem .3rem; }
[data-theme-layout="factory-rackwall"] .rkw-certs .f-cert b { font-size: .78rem; }

/* ---- 作业流程刻度带（贴在下横梁正下方） ---------------------------------- */
[data-theme-layout="factory-rackwall"] .rkw-rail {
  padding: 1rem clamp(1rem, 2.4vw, 1.7rem) 1.1rem;
  border: 1px solid var(--line); border-top: 0; background: var(--surface);
}
[data-theme-layout="factory-rackwall"] .rkw-rail-t {
  margin: 0 0 .85rem; font-family: var(--mono); font-size: .68rem; font-weight: 800;
  letter-spacing: .2em; text-transform: uppercase; color: var(--accent); overflow-wrap: anywhere;
}
[data-theme-layout="factory-rackwall"] .rkw-rail .f-step-num { background: var(--surface); }
[data-theme-layout="factory-rackwall"] .rkw-rail .f-step::before { background: color-mix(in srgb, var(--rkw-beam) 60%, var(--line)); }

/* ---- 区块头：通道号牌（序号 CSS counter，永远连续） ---------------------- */
[data-theme-layout="factory-rackwall"] .rkw-sec { padding-top: clamp(2.4rem, 5vw, 3.4rem); }
[data-theme-layout="factory-rackwall"] .rkw-head {
  counter-increment: rkwsec;
  display: flex; align-items: center; gap: .7rem; margin-bottom: 1.1rem;
  padding-bottom: .7rem; border-bottom: 2px solid var(--ink);
}
[data-theme-layout="factory-rackwall"] .rkw-head::before {
  content: counter(rkwsec, decimal-leading-zero);
  flex: none; padding: .18rem .45rem; border-radius: 2px;
  background: var(--accent-wash); color: var(--accent);
  font-family: var(--mono); font-size: .72rem; font-weight: 800; letter-spacing: .08em;
  font-variant-numeric: tabular-nums;
}
[data-theme-layout="factory-rackwall"] .rkw-head h2 {
  margin: 0; min-width: 0; font-size: clamp(1.3rem, 2.4vw, 1.6rem); font-weight: 780;
  letter-spacing: -.008em; color: var(--ink); overflow-wrap: anywhere;
}
[data-theme-layout="factory-rackwall"] .rkw-head > a {
  flex: none; margin-left: auto; color: var(--ink-soft); font-size: .84rem; font-weight: 600;
}
[data-theme-layout="factory-rackwall"] .rkw-head > a:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 3px; }

/* ---- 商品：托盘位（整排夹在上下横梁里，卡顶黑底编号签） ------------------ */
[data-theme-layout="factory-rackwall"] .rkw-shelf { position: relative; padding-block: 14px; }
[data-theme-layout="factory-rackwall"] .rkw-shelf::before,
[data-theme-layout="factory-rackwall"] .rkw-shelf::after {
  content: ""; position: absolute; left: 0; right: 0; height: 10px; border-radius: 2px;
  background: var(--rkw-beam);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ink) 32%, transparent);
  pointer-events: none;
}
[data-theme-layout="factory-rackwall"] .rkw-shelf::before { top: 0; }
[data-theme-layout="factory-rackwall"] .rkw-shelf::after { bottom: 0; }
[data-theme-layout="factory-rackwall"] .rkw-grid {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: clamp(.7rem, 1.5vw, 1rem);
  counter-reset: rkwslot;
}
[data-theme-layout="factory-rackwall"] .rkw-slot {
  counter-increment: rkwslot;
  display: flex; flex-direction: column; min-width: 0;
  border: 1px solid var(--line); border-radius: 2px; background: var(--surface); color: var(--ink);
  overflow: hidden; transition: border-color var(--speed), transform var(--speed), box-shadow var(--speed);
}
[data-theme-layout="factory-rackwall"] .rkw-slot:hover {
  border-color: var(--accent); transform: translateY(-3px); color: var(--ink);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--rkw-beam) 55%, transparent), var(--shadow);
}
[data-theme-layout="factory-rackwall"] .rkw-slot-tag {
  display: flex; align-items: center; flex: none; height: 22px; padding: 0 .55rem;
  background: var(--ink); color: var(--bg);
  font-family: var(--mono); font-size: .66rem; font-weight: 800; letter-spacing: .12em;
  font-variant-numeric: tabular-nums;
}
[data-theme-layout="factory-rackwall"] .rkw-slot-tag::before { content: "№ " counter(rkwslot, decimal-leading-zero); }
[data-theme-layout="factory-rackwall"] .rkw-slot-tag::after {
  content: ""; margin-left: auto; width: 26px; height: 4px; border-radius: 1px; background: var(--rkw-beam);
}
[data-theme-layout="factory-rackwall"] .rkw-slot-media { display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-rackwall"] .rkw-slot-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
[data-theme-layout="factory-rackwall"] .rkw-slot:hover .rkw-slot-media img { transform: scale(1.03); }
[data-theme-layout="factory-rackwall"] .rkw-slot-gen b { font-family: var(--sans); font-weight: 800; font-size: 2.8rem; color: var(--ink); }
[data-theme-layout="factory-rackwall"] .rkw-slot-body { display: flex; flex: 1; flex-direction: column; gap: .28rem; min-width: 0; padding: .75rem .85rem .95rem; }
[data-theme-layout="factory-rackwall"] .rkw-slot-cat {
  width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
  color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
}
[data-theme-layout="factory-rackwall"] .rkw-slot-title {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: .97rem; font-weight: 700; line-height: 1.4; overflow-wrap: anywhere;
}
[data-theme-layout="factory-rackwall"] .rkw-slot:hover .rkw-slot-title { text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="factory-rackwall"] .rkw-empty {
  grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); border-radius: 2px; text-align: center;
}

/* ---- 库区实拍带 / 共用组件的货架化 --------------------------------------- */
[data-theme-layout="factory-rackwall"] .rkw-zone .f-gallery { padding-bottom: .9rem; border-bottom: 3px solid var(--rkw-beam); }
[data-theme-layout="factory-rackwall"] .f-gallery-item { border-radius: 2px; }
[data-theme-layout="factory-rackwall"] .f-cat-card,
[data-theme-layout="factory-rackwall"] .f-industry { border-radius: 2px; }
[data-theme-layout="factory-rackwall"] .f-cat-card { border-left: 3px solid var(--rkw-beam); }
[data-theme-layout="factory-rackwall"] .f-cat-card:hover { box-shadow: 0 0 0 2px color-mix(in srgb, var(--rkw-beam) 55%, transparent); }
[data-theme-layout="factory-rackwall"] .f-faq { border-top-color: var(--rkw-beam); border-top-width: 3px; }
[data-theme-layout="factory-rackwall"] .f-faq-q:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="factory-rackwall"] .f-chip { border-radius: 2px; }

/* ---- 出库动态：单行清单 -------------------------------------------------- */
[data-theme-layout="factory-rackwall"] .rkw-news-item {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .93rem;
}
[data-theme-layout="factory-rackwall"] .rkw-news-item:hover { color: var(--ink); }
[data-theme-layout="factory-rackwall"] .rkw-news-item:hover .rkw-news-title { text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="factory-rackwall"] .rkw-news-item time { color: var(--ink-soft); font-family: var(--mono); font-size: .74rem; font-variant-numeric: tabular-nums; }
[data-theme-layout="factory-rackwall"] .rkw-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* ---- 内页重塑 A：列表/归档＝货架分层（.cat-nav 层板 + .link-grid 夹梁 + 托盘签卡） */
[data-theme-layout="factory-rackwall"] .page-head { border-bottom: 4px solid var(--rkw-beam); }
[data-theme-layout="factory-rackwall"] .page-head .eyebrow { font-family: var(--mono); letter-spacing: .18em; }
[data-theme-layout="factory-rackwall"] .cat-nav { counter-reset: rkwlvl; gap: .5rem; }
[data-theme-layout="factory-rackwall"] .cat-nav a {
  counter-increment: rkwlvl;
  display: inline-flex; align-items: baseline; gap: .45rem; min-width: 0;
  padding: .42rem .8rem; border-radius: 0; border-left: 3px solid var(--rkw-beam);
  background: var(--surface); font-size: .88rem;
}
[data-theme-layout="factory-rackwall"] .cat-nav a::before {
  content: "№ " counter(rkwlvl); flex: none;
  font-family: var(--mono); font-size: .64rem; font-weight: 800; letter-spacing: .06em; color: var(--accent);
}
[data-theme-layout="factory-rackwall"] .cat-nav a:hover { color: var(--ink); border-color: var(--accent); box-shadow: inset 0 -3px 0 var(--rkw-beam); }
[data-theme-layout="factory-rackwall"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: var(--rkw-onacc); }
[data-theme-layout="factory-rackwall"] .cat-nav a.active::before { color: var(--rkw-onacc); }
[data-theme-layout="factory-rackwall"] .link-grid { position: relative; padding-block: 14px; margin-block: 1.6rem; }
[data-theme-layout="factory-rackwall"] .link-grid::before,
[data-theme-layout="factory-rackwall"] .link-grid::after {
  content: ""; position: absolute; left: 0; right: 0; height: 10px; border-radius: 2px;
  background: var(--rkw-beam);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ink) 32%, transparent);
  pointer-events: none;
}
[data-theme-layout="factory-rackwall"] .link-grid::before { top: 0; }
[data-theme-layout="factory-rackwall"] .link-grid::after { bottom: 0; }
[data-theme-layout="factory-rackwall"] .link-card {
  border-radius: 2px; counter-increment: rkwlvl;
  transition: border-color var(--speed), transform var(--speed), box-shadow var(--speed);
}
/* 托盘签：静态占位条（不做绝对定位，任何宽度都不与文字相交） */
[data-theme-layout="factory-rackwall"] .link-card::before {
  content: "№ " counter(rkwlvl, decimal-leading-zero);
  display: flex; align-items: center; flex: none; height: 22px; padding: 0 .55rem;
  background: var(--ink); color: var(--bg);
  font-family: var(--mono); font-size: .66rem; font-weight: 800; letter-spacing: .12em; font-variant-numeric: tabular-nums;
}
[data-theme-layout="factory-rackwall"] .link-card:hover {
  border-color: var(--accent); box-shadow: 0 0 0 2px color-mix(in srgb, var(--rkw-beam) 55%, transparent);
}
[data-theme-layout="factory-rackwall"] .lc-cover { border-radius: 0; }
[data-theme-layout="factory-rackwall"] .lc-title { align-items: flex-start; }

/* ---- 内页重塑 B：商品详情＝托盘标签大卡 + 铆钉参数铭牌 -------------------- */
[data-theme-layout="factory-rackwall"] .pd-media { border-radius: 2px; border-bottom: 4px solid var(--rkw-beam); }
[data-theme-layout="factory-rackwall"] .pd-thumb { border-radius: 0; }
[data-theme-layout="factory-rackwall"] .pd-info {
  padding: 1.05rem 1.15rem 1.25rem; border: 1px solid var(--line); border-radius: 2px;
  background: var(--surface); box-shadow: inset 0 4px 0 var(--rkw-beam);
}
[data-theme-layout="factory-rackwall"] .pd-kicker {
  display: inline-flex; padding: .22rem .55rem; border-radius: 2px; background: var(--ink);
  letter-spacing: .14em;
}
[data-theme-layout="factory-rackwall"] .pd-kicker a { color: var(--bg); }
[data-theme-layout="factory-rackwall"] .pd-kicker a:hover { color: var(--bg); text-decoration: underline; text-underline-offset: 3px; }
[data-theme-layout="factory-rackwall"] .pd-title { font-weight: 800; letter-spacing: -.012em; }
[data-theme-layout="factory-rackwall"] .pd-meta { border-top: 3px solid var(--rkw-beam); }
[data-theme-layout="factory-rackwall"] .pd-meta-row dt { font-family: var(--mono); font-size: .78rem; letter-spacing: .06em; text-transform: uppercase; }
[data-theme-layout="factory-rackwall"] .pd-specs-tablewrap {
  border-width: 2px; border-color: color-mix(in srgb, var(--ink) 40%, transparent); border-radius: 3px;
  background-image:
    radial-gradient(circle at 9px 9px, color-mix(in srgb, var(--ink) 30%, transparent) 0 2.4px, transparent 2.6px),
    radial-gradient(circle at calc(100% - 9px) 9px, color-mix(in srgb, var(--ink) 30%, transparent) 0 2.4px, transparent 2.6px);
}
[data-theme-layout="factory-rackwall"] .pd-specs-table th { font-family: var(--mono); font-size: .78rem; letter-spacing: .05em; text-transform: uppercase; }
[data-theme-layout="factory-rackwall"] .pd-rel-card { border-radius: 2px; }
[data-theme-layout="factory-rackwall"] .pd-rel-card:hover { box-shadow: 0 0 0 2px color-mix(in srgb, var(--rkw-beam) 55%, transparent); }
[data-theme-layout="factory-rackwall"] .pd-related { padding-top: 1rem; border-top: 3px solid var(--rkw-beam); }

/* ---- 响应式 -------------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="factory-rackwall"] .rkw-bay-in { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="factory-rackwall"] .rkw-plate { align-self: stretch; }
  [data-theme-layout="factory-rackwall"] .rkw-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-rackwall"] .rkw-bay { padding-block: 9px; }
  [data-theme-layout="factory-rackwall"] .rkw-bay::before,
  [data-theme-layout="factory-rackwall"] .rkw-bay::after { height: 9px; }
  [data-theme-layout="factory-rackwall"] .rkw-bay-in { border-inline-width: 2px; padding: 1.3rem .9rem 1.5rem; }
  [data-theme-layout="factory-rackwall"] .rkw-h1 { font-size: clamp(1.7rem, 7.6vw, 2.3rem); }
  [data-theme-layout="factory-rackwall"] .rkw-stats .f-stat { grid-template-columns: minmax(0, 1fr); gap: .1rem; }
  [data-theme-layout="factory-rackwall"] .rkw-stats .f-stat dd { justify-self: start; text-align: left; }
  [data-theme-layout="factory-rackwall"] .rkw-grid { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="factory-rackwall"] .rkw-shelf,
  [data-theme-layout="factory-rackwall"] .link-grid { padding-block: 11px; }
  [data-theme-layout="factory-rackwall"] .rkw-shelf::before, [data-theme-layout="factory-rackwall"] .rkw-shelf::after,
  [data-theme-layout="factory-rackwall"] .link-grid::before, [data-theme-layout="factory-rackwall"] .link-grid::after { height: 8px; }
  [data-theme-layout="factory-rackwall"] .rkw-head { flex-wrap: wrap; gap: .45rem .6rem; }
  [data-theme-layout="factory-rackwall"] .rkw-head > a { margin-left: 0; }
  [data-theme-layout="factory-rackwall"] .rkw-news-item { grid-template-columns: minmax(0, 1fr) auto; gap: .2rem .8rem; }
  [data-theme-layout="factory-rackwall"] .rkw-news-item time { grid-column: 1 / -1; }
  [data-theme-layout="factory-rackwall"] .rkw-news-title { white-space: normal; }
}

/* ---- reduced motion ------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-rackwall"] .site-header .nav > a,
  [data-theme-layout="factory-rackwall"] .rkw-slot,
  [data-theme-layout="factory-rackwall"] .rkw-slot-media img,
  [data-theme-layout="factory-rackwall"] .link-card { transition: none; }
  [data-theme-layout="factory-rackwall"] .rkw-slot:hover { transform: none; }
  [data-theme-layout="factory-rackwall"] .rkw-slot:hover .rkw-slot-media img { transform: none; }
}

/* ============================================================
   货架 · Rackwall —— Rackwall 骨架默认皮：仓储灰混凝土底 + 货架橙
   橙分两支：--accent #943f05（承载文字，压深到可读）／--rkw-beam #ef7c1a
  （只做横梁/立柱/铆钉等纯装饰，不放任何文字）。
   实算：ink/bg 14.14、ink/surface 16.17、ink-soft/bg 8.83、ink-soft/surface 10.10、
   muted/bg 5.51、muted/surface 6.31、accent 字/bg 5.62、accent 字/surface 6.42、
   accent 字/wash（通道号牌）6.07、白字/accent（实底胶囊·眉标·当前通道）7.07、
   通道牌 bg 字/ink 底 14.14 → hover 压纯黑 16.69（只升）、
   托盘签 bg 字/ink 底 14.14、CTA bg 字/ink 通栏 14.14；
   hover accent-soft/bg 8.01、/surface 9.16、白字/accent-soft 10.08，全部只升
   ============================================================ */
:root[data-theme="rackwall"] {
  --bg: #e7e5e1; --surface: #f5f4f1;
  --ink: #16181b; --ink-soft: #383c41; --muted: #565a60; --faint: #878c93;
  --line: #c9c7c2; --line-soft: #dcdad5;
  --accent: #943f05; --accent-soft: #6f2f03; --accent-wash: #f8ecdf;
  --w-wide: 1240px; --radius: 2px;
  --shadow: 0 1px 2px rgba(22, 24, 27, .07), 0 10px 24px rgba(22, 24, 27, .10);
  --rkw-beam: #ef7c1a; --rkw-beamink: #14161a; --rkw-signhi: #000000; --rkw-onacc: #ffffff;
}
:root[data-theme="rackwall"] .site-header { background: var(--bg); }
:root[data-theme="rackwall"] .btn-primary { color: #fff; }

/* ============================================================
   通道 · Aisle —— Rackwall 骨架反差皮：夜库炭黑 + 高亮货架橙
   暗底上橙本身够亮，--accent 与 --rkw-beam 同为 #ef7c1a；通道牌在暗皮里
   是「浅色牌面」（--ink 亮灰底 + --bg 近黑字），hover 压纯白只升。
   实算：ink/bg 15.82、ink/surface 14.40、ink-soft/bg 11.13、ink-soft/surface 10.13、
   muted/bg 7.09、muted/surface 6.46、accent 字/bg 6.76、accent 字/surface 6.16、
   accent 字/wash 5.74、近黑字/accent（实底胶囊·眉标·当前通道）6.53、
   通道牌 bg 字/ink 牌面 15.82 → hover 压纯白 18.76（只升）、
   托盘签 bg 字/ink 底 15.82、CTA bg 字/ink 通栏 15.82；
   hover accent-soft/bg 9.61、/surface 8.75、近黑字/accent-soft 9.28，全部只升
   ============================================================ */
:root[data-theme="aisle"] {
  --bg: #101215; --surface: #191c21;
  --ink: #e9ecef; --ink-soft: #c2c8cf; --muted: #98a0a9; --faint: #6b737c;
  --line: #2c3138; --line-soft: #1e2228;
  --accent: #ef7c1a; --accent-soft: #ffa552; --accent-wash: #2a2018;
  --w-wide: 1240px; --radius: 2px; --code-bg: #0a0c0f;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 12px 30px rgba(0, 0, 0, .5);
  --rkw-beam: #ef7c1a; --rkw-beamink: #14161a; --rkw-signhi: #ffffff; --rkw-onacc: #14161a;
}
:root[data-theme="aisle"] .site-header { background: rgba(16, 18, 21, .92); }
:root[data-theme="aisle"] .btn-primary { color: #14161a; }
/* 亮橙实底一律配近黑字（白字在 #ef7c1a 上只有 2.2） */
:root[data-theme="aisle"] .rkw-eyebrow,
:root[data-theme="aisle"] .cat-nav a.active { color: #14161a; }

/* ============================================================
   货架纯白 · Rackwall White —— 纯白系：中性灰基底照抄纯白段，
   橙相压深到白底 6.81（hover soft 9.60 只升）；--rkw-beam 仍是 #ef7c1a
  （纯装饰横梁，不载字）。muted #707680 在 #fafaf8 上只有 4.38——
   带 muted 文字的铭牌/流程带/行业卡/分类卡/规格 chip 一律覆写回 --bg 纯白（4.57）。
   实算：ink/bg 18.72、ink/surface 17.91、ink-soft/bg 9.79、ink-soft/surface 9.37、
   muted/bg 4.57、accent 字/bg 6.81、accent 字/surface 6.51、accent 字/wash 5.97、
   白字/accent（实底胶囊·眉标·当前通道）6.81、通道牌 bg 字/ink 底 18.72 →
   hover 压纯黑 21.00（只升）、托盘签 18.72、CTA 18.72；
   hover accent-soft/bg 9.60、/surface 9.18、白字/accent-soft 9.60，全部只升
   ============================================================ */
:root[data-theme="rackwall-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #707680; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #95430a; --accent-soft: #733206; --accent-wash: #fbeee2;
  --w-wide: 1240px; --radius: 2px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .04), 0 10px 26px rgba(16, 18, 24, .07);
  --rkw-beam: #ef7c1a; --rkw-beamink: #14161a; --rkw-signhi: #000000; --rkw-onacc: #ffffff;
}
:root[data-theme="rackwall-white"] .btn-primary { color: #fff; }
/* muted 文字所在卡面覆写回纯白（#fafaf8 上 muted 只有 4.38） */
:root[data-theme="rackwall-white"] .rkw-plate,
:root[data-theme="rackwall-white"] .rkw-rail,
:root[data-theme="rackwall-white"] .f-industry,
:root[data-theme="rackwall-white"] .f-cat-card,
:root[data-theme="rackwall-white"] .f-chip { background-color: var(--bg); }
:root[data-theme="rackwall-white"] .rkw-rail .f-step-num { background: var(--bg); }
/* 纯白系语言：去铆钉/去纹理/去图章错位，只留发丝线与橙梁 */
:root[data-theme="rackwall-white"] .rkw-plate { background-image: none; border-width: 1px; border-color: var(--line); }
:root[data-theme="rackwall-white"] .rkw-plate::before { content: none; }
:root[data-theme="rackwall-white"] .rkw-bay-in { background-image: none; border-inline-color: var(--line); }
:root[data-theme="rackwall-white"] .rkw-head { border-bottom-width: 1px; border-bottom-color: var(--line); }
:root[data-theme="rackwall-white"] .pd-specs-tablewrap { background-image: none; border-width: 1px; border-color: var(--line); }
:root[data-theme="rackwall-white"] .f-cert { transform: none; border-color: var(--line); outline-color: var(--line-soft); }

/* =========================================================================
   LAYOUT: factory-exportmap — 航线图（出口导向的工厂骨架）
   每条选择器都限定在 [data-theme-layout="factory-exportmap"]，类名前缀 emap-（全仓未占用）。
   形态三件套：
     ① 页头「时区细条」：品牌/导航行 + 底缘等宽分段条（CSS 画的表盘刻度 + 等宽标签，
        段间虚线航路）；分段内容只吃真数据（多语种=语种台，单语种=联系方式），
        绝不写死城市与钟点；≤620px 整条隐藏，回落基础汉堡抽屉。
     ② hero「世界航线点阵图」：radial-gradient 光点矩阵（海面细点 + 三块陆块密点，mask 合成）
        + 三条虚线航弧 + 港口光点（.is-hub 更大更亮带光晕脉冲）；
        图的下沿直接压 factory.stats 实力数字 + 认证章条 = hero 数据融合。
     ③ 商品「航线卡」：左侧港口代码列（SKU/首字 + 两位序号 + 航线节点竖虚线）+ 缩略图 + 文案。
   内页重塑（不改公共模板，只重塑既有类）：
     列表 .cat-nav/.link-grid/.link-card/.lc-*  → 航线清单（左侧序号轨 + 右侧市场徽章车道）
     详情 .pd-bc/.pd-kicker/.pd-meta/.pd-specs-table/.pd-rel-card → 港口徽章行 + 点阵图版
   容器规约：width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto（与页眉/页脚左缘对齐）。
   ========================================================================= */
[data-theme-layout="factory-exportmap"] body { background: var(--bg); }
[data-theme-layout="factory-exportmap"] .emap-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding: clamp(1.4rem, 3vw, 2.2rem) 0 clamp(3rem, 6vw, 4.2rem);
}

/* ---- 页头：时区细条（等宽分段，纯静态） ---- */
[data-theme-layout="factory-exportmap"] .emap-header .wrap { height: 62px; }
[data-theme-layout="factory-exportmap"] .emap-zonebar {
  border-top: 1px solid var(--line);
  background: color-mix(in srgb, var(--accent) 5%, var(--bg));
}
[data-theme-layout="factory-exportmap"] .emap-zonebar-in {
  display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr);
  width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto;
}
[data-theme-layout="factory-exportmap"] .emap-zone {
  position: relative; display: flex; align-items: center; gap: .5rem; min-width: 0;
  padding: .4rem .7rem; color: var(--ink-soft);
  font-family: var(--mono); font-size: .7rem; line-height: 1.5;
  transition: background-color var(--speed);
}
[data-theme-layout="factory-exportmap"] .emap-zone + .emap-zone::before {
  content: ""; position: absolute; left: 0; top: 50%; height: 15px; margin-top: -7.5px;
  border-left: 1px dashed color-mix(in srgb, var(--accent) 42%, transparent);
}
[data-theme-layout="factory-exportmap"] .emap-zone b {
  flex: none; color: var(--accent); font-weight: 800; letter-spacing: .12em; text-transform: uppercase;
}
[data-theme-layout="factory-exportmap"] .emap-zone i {
  min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
  font-style: normal; color: var(--ink-soft);
}
[data-theme-layout="factory-exportmap"] .emap-zone:hover,
[data-theme-layout="factory-exportmap"] .emap-zone.is-on {
  background: color-mix(in srgb, var(--accent) 12%, transparent); color: var(--ink);
}
[data-theme-layout="factory-exportmap"] .emap-zone.is-on { box-shadow: inset 0 -2px 0 var(--accent); }
/* 表盘刻度：纯 CSS 画的时针/分针，给「时区」的形而不写任何钟点数字 */
[data-theme-layout="factory-exportmap"] .emap-dial {
  position: relative; flex: none; width: 12px; height: 12px; border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--accent) 70%, transparent);
}
[data-theme-layout="factory-exportmap"] .emap-dial::before {
  content: ""; position: absolute; left: 50%; top: 2px; width: 1px; height: 4px; background: var(--accent);
}
[data-theme-layout="factory-exportmap"] .emap-dial::after {
  content: ""; position: absolute; left: 50%; top: 50%; width: 4px; height: 1px; background: var(--accent);
}

/* ---- hero：世界航线点阵图 + 数字/认证融合带 ---- */
[data-theme-layout="factory-exportmap"] .emap-hero {
  display: grid; grid-template-columns: minmax(0, .92fr) minmax(0, 1.08fr);
  align-items: center; gap: clamp(1.4rem, 3.4vw, 2.8rem);
}
[data-theme-layout="factory-exportmap"] .emap-eyebrow {
  width: fit-content; margin: 0 0 1rem; color: var(--accent);
  font-family: var(--mono); font-size: .72rem; font-weight: 800; letter-spacing: .22em; text-transform: uppercase;
}
[data-theme-layout="factory-exportmap"] .emap-h1 {
  margin: 0; max-width: 15em; font-family: var(--sans);
  font-size: clamp(2rem, 4.4vw, 3.2rem); font-weight: 780; line-height: 1.1; letter-spacing: -.015em;
}
[data-theme-layout="factory-exportmap"] .emap-lede {
  max-width: 54ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75;
}
[data-theme-layout="factory-exportmap"] .emap-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.8rem; }
[data-theme-layout="factory-exportmap"] .emap-atlas {
  position: relative; aspect-ratio: 16 / 9; min-height: 230px;
  border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden;
  background-color: color-mix(in srgb, var(--accent) 6%, var(--surface));
}
[data-theme-layout="factory-exportmap"] .emap-atlas::before,
[data-theme-layout="factory-exportmap"] .emap-atlas::after {
  content: ""; position: absolute; z-index: 2; width: 16px; height: 16px; pointer-events: none;
}
[data-theme-layout="factory-exportmap"] .emap-atlas::before { top: 8px; left: 8px; border-top: 2px solid var(--accent); border-left: 2px solid var(--accent); }
[data-theme-layout="factory-exportmap"] .emap-atlas::after { right: 8px; bottom: 8px; border-bottom: 2px solid var(--accent); border-right: 2px solid var(--accent); }
[data-theme-layout="factory-exportmap"] .emap-atlas-img {
  position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover;
  opacity: .26; filter: grayscale(1) contrast(1.05);
}
[data-theme-layout="factory-exportmap"] .emap-sea,
[data-theme-layout="factory-exportmap"] .emap-lands,
[data-theme-layout="factory-exportmap"] .emap-arcs,
[data-theme-layout="factory-exportmap"] .emap-ports { position: absolute; inset: 0; display: block; pointer-events: none; }
/* 海面细点：等距点阵，边缘 mask 渐隐（不画硬边框住地图） */
[data-theme-layout="factory-exportmap"] .emap-sea {
  background-image: radial-gradient(circle at center, color-mix(in srgb, var(--accent) 34%, transparent) 1.4px, transparent 1.5px);
  background-size: 17px 17px;
  -webkit-mask-image: radial-gradient(118% 128% at 50% 46%, #000 40%, transparent 84%);
          mask-image: radial-gradient(118% 128% at 50% 46%, #000 40%, transparent 84%);
}
/* 三块陆块：同一点阵加密加亮，用三层椭圆 mask 叠出大陆轮廓（mask 多层默认 add 合成） */
[data-theme-layout="factory-exportmap"] .emap-lands {
  background-image: radial-gradient(circle at center, color-mix(in srgb, var(--accent) 80%, transparent) 1.9px, transparent 2px);
  background-size: 14px 14px;
  -webkit-mask-image: radial-gradient(20% 42% at 19% 54%, #000 56%, transparent 100%), radial-gradient(15% 30% at 46% 33%, #000 56%, transparent 100%), radial-gradient(19% 38% at 77% 57%, #000 54%, transparent 100%);
          mask-image: radial-gradient(20% 42% at 19% 54%, #000 56%, transparent 100%), radial-gradient(15% 30% at 46% 33%, #000 56%, transparent 100%), radial-gradient(19% 38% at 77% 57%, #000 54%, transparent 100%);
}
/* 航弧：只留 border-top 的 50% 圆角盒＝椭圆上半弧（纯 CSS，零 SVG） */
[data-theme-layout="factory-exportmap"] .emap-arc {
  position: absolute; height: 30%; border-top: 1.5px dashed color-mix(in srgb, var(--accent) 52%, transparent); border-radius: 50%;
}
[data-theme-layout="factory-exportmap"] .emap-arc.a1 { left: 17%; width: 32%; top: 30%; }
[data-theme-layout="factory-exportmap"] .emap-arc.a2 { left: 44%; width: 36%; top: 38%; }
[data-theme-layout="factory-exportmap"] .emap-arc.a3 { left: 24%; width: 54%; top: 18%; height: 40%; opacity: .58; }
/* 港口光点：全部关在 .emap-ports 这条专属车道里（百分比定位，随图等比缩放，绝不外溢到文字区） */
[data-theme-layout="factory-exportmap"] .emap-port {
  position: absolute; width: 6px; height: 6px; margin: -3px 0 0 -3px; border-radius: 50%;
  background: var(--accent); opacity: .78;
}
[data-theme-layout="factory-exportmap"] .emap-port.is-hub {
  width: 11px; height: 11px; margin: -5.5px 0 0 -5.5px; opacity: 1; background: var(--accent-soft);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 26%, transparent), 0 0 16px color-mix(in srgb, var(--accent) 55%, transparent);
}
[data-theme-layout="factory-exportmap"] .emap-port.is-hub::after {
  content: ""; position: absolute; inset: -6px; border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--accent) 45%, transparent);
  animation: emapPing 3.6s ease-out infinite;
}
[data-theme-layout="factory-exportmap"] .emap-port.p1 { left: 16%; top: 50%; }
[data-theme-layout="factory-exportmap"] .emap-port.p2 { left: 22%; top: 61%; }
[data-theme-layout="factory-exportmap"] .emap-port.p3 { left: 20%; top: 45%; }
[data-theme-layout="factory-exportmap"] .emap-port.p4 { left: 42%; top: 29%; }
[data-theme-layout="factory-exportmap"] .emap-port.p5 { left: 49%; top: 37%; }
[data-theme-layout="factory-exportmap"] .emap-port.p6 { left: 53%; top: 30%; }
[data-theme-layout="factory-exportmap"] .emap-port.p7 { left: 73%; top: 51%; }
[data-theme-layout="factory-exportmap"] .emap-port.p8 { left: 79%; top: 60%; }
[data-theme-layout="factory-exportmap"] .emap-port.p9 { left: 84%; top: 49%; }
@keyframes emapPing { 0% { transform: scale(.9); opacity: .75; } 70%, 100% { transform: scale(2.2); opacity: 0; } }
/* 数据融合带：航线尺（2px 重线）上压实力数字与认证章 */
[data-theme-layout="factory-exportmap"] .emap-fold {
  grid-column: 1 / -1; display: grid; grid-template-columns: minmax(0, 1fr) auto;
  align-items: center; gap: 1.2rem 2rem;
  margin-top: clamp(1.4rem, 3vw, 2.2rem); padding-top: 1.3rem; border-top: 2px solid var(--ink);
}
[data-theme-layout="factory-exportmap"] .emap-stats { grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: .8rem; }
[data-theme-layout="factory-exportmap"] .emap-stats .f-stat { padding: .9rem 1rem .8rem; }
[data-theme-layout="factory-exportmap"] .emap-stats .f-stat dt { font-size: clamp(1.4rem, 2.2vw, 1.95rem); }
[data-theme-layout="factory-exportmap"] .emap-certs { justify-content: flex-end; }

/* ---- 区块标题 ---- */
[data-theme-layout="factory-exportmap"] .emap-section { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-exportmap"] .emap-head {
  position: relative; display: flex; align-items: flex-end; justify-content: space-between;
  gap: 1rem; margin-bottom: 1.2rem; padding-bottom: .7rem; border-bottom: 1px solid var(--line);
}
[data-theme-layout="factory-exportmap"] .emap-head::after {
  content: ""; position: absolute; left: 0; bottom: -1px; width: 76px; height: 3px; background: var(--accent);
}
[data-theme-layout="factory-exportmap"] .emap-head h2 {
  margin: 0; font-family: var(--sans); font-size: clamp(1.35rem, 2.4vw, 1.7rem); font-weight: 760; letter-spacing: -.01em;
}
[data-theme-layout="factory-exportmap"] .emap-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-exportmap"] .emap-head > a:hover { color: var(--accent); }

/* ---- 商品：航线卡（左侧港口代码列 + 航线节点） ---- */
[data-theme-layout="factory-exportmap"] .emap-routes {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 clamp(1.2rem, 2.6vw, 2.4rem);
}
[data-theme-layout="factory-exportmap"] .emap-route {
  position: relative; display: grid; grid-template-columns: 58px 92px minmax(0, 1fr) auto;
  align-items: center; gap: .85rem; padding: .8rem .4rem; color: var(--ink);
  border-bottom: 1px dashed var(--line);
  transition: background-color var(--speed), border-color var(--speed);
}
[data-theme-layout="factory-exportmap"] .emap-route:hover {
  background: color-mix(in srgb, var(--accent) 8%, transparent); border-bottom-color: var(--accent); color: var(--ink);
}
[data-theme-layout="factory-exportmap"] .emap-route-code {
  position: relative; display: flex; flex-direction: column; gap: .15rem; min-width: 0;
  padding-left: .9rem; font-family: var(--mono);
}
[data-theme-layout="factory-exportmap"] .emap-route-code::before {
  content: ""; position: absolute; left: 3px; top: -.85rem; bottom: -.85rem;
  border-left: 1px dashed color-mix(in srgb, var(--accent) 38%, transparent);
}
[data-theme-layout="factory-exportmap"] .emap-route-code::after {
  content: ""; position: absolute; left: 0; top: 50%; width: 7px; height: 7px; margin-top: -3.5px;
  border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 2px var(--bg);
}
/* 港口代码是嗅探来的 SKU，长短不可控 —— 单行钳死，绝不撑格 */
[data-theme-layout="factory-exportmap"] .emap-route-code b {
  max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
  color: var(--accent); font-size: .72rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
}
[data-theme-layout="factory-exportmap"] .emap-route-code i {
  font-style: normal; font-size: .64rem; color: var(--muted); font-variant-numeric: tabular-nums;
}
[data-theme-layout="factory-exportmap"] .emap-route-media {
  display: grid; place-items: center; width: 92px; aspect-ratio: 4 / 3; overflow: hidden;
  border: 1px solid var(--line); border-radius: calc(var(--radius) * .7); background: var(--line-soft);
}
[data-theme-layout="factory-exportmap"] .emap-route-media img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="factory-exportmap"] .emap-route-gen b { font-family: var(--sans); font-size: 1.7rem; color: var(--accent); }
[data-theme-layout="factory-exportmap"] .emap-route-body { display: flex; min-width: 0; flex-direction: column; gap: .22rem; }
[data-theme-layout="factory-exportmap"] .emap-route-cat {
  width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
  color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 750; letter-spacing: .1em; text-transform: uppercase;
}
[data-theme-layout="factory-exportmap"] .emap-route-title { font-size: 1rem; font-weight: 700; line-height: 1.4; }
[data-theme-layout="factory-exportmap"] .emap-route-ex {
  display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 1;
  color: var(--muted); font-size: .82rem; line-height: 1.55;
}
[data-theme-layout="factory-exportmap"] .emap-route-go { color: var(--muted); }
[data-theme-layout="factory-exportmap"] .emap-route:hover .emap-route-go { color: var(--accent); }
[data-theme-layout="factory-exportmap"] .emap-empty {
  grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center;
}

/* ---- 动态：一行一条的航次清单 ---- */
[data-theme-layout="factory-exportmap"] .emap-news { border-top: 1px solid var(--line); }
[data-theme-layout="factory-exportmap"] .emap-news-item {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-exportmap"] .emap-news-item time { color: var(--muted); font-family: var(--mono); font-size: .72rem; }
[data-theme-layout="factory-exportmap"] .emap-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
[data-theme-layout="factory-exportmap"] .emap-news-item:hover { color: var(--accent); }

/* =========================================================================
   内页重塑（只重塑既有类，公共模板零改动）
   ========================================================================= */
/* ---- 商品/文章列表页：航线清单 —— 左侧序号轨 + 右侧市场徽章车道 ---- */
[data-theme-layout="factory-exportmap"] .page-head { padding: 2.4rem 0 1.4rem; }
[data-theme-layout="factory-exportmap"] .page-head h1 { font-family: var(--sans); font-weight: 780; letter-spacing: -.015em; }
/* 分类导航 = 航线（市场）选择条：等宽小号，横向可滚，选中实心 */
[data-theme-layout="factory-exportmap"] .cat-nav {
  display: flex; flex-wrap: wrap; gap: .4rem; margin: 1rem 0 1.4rem; padding-bottom: .7rem;
  border-bottom: 2px solid var(--ink);
}
[data-theme-layout="factory-exportmap"] .cat-nav a {
  padding: .3rem .7rem; border: 1px solid var(--line); border-radius: 2px;
  font-family: var(--mono); font-size: .72rem; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-soft);
}
[data-theme-layout="factory-exportmap"] .cat-nav a:hover { border-color: var(--accent); color: var(--accent); }
[data-theme-layout="factory-exportmap"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: var(--bg); }
[data-theme-layout="factory-exportmap"] .cat-nav a.active .muted { color: inherit; opacity: .85; }
[data-theme-layout="factory-exportmap"] .link-grid {
  display: grid; grid-template-columns: 1fr; gap: 0;
  border-top: 2px solid var(--ink); counter-reset: emapRow;
}
[data-theme-layout="factory-exportmap"] .link-card {
  position: relative; display: grid; grid-template-columns: 56px 104px minmax(0, 1fr);
  align-items: center; gap: 1rem; padding: .85rem 12rem .85rem .4rem;
  border: 0; border-bottom: 1px dashed var(--line); border-radius: 0; background: none; box-shadow: none;
  transition: background-color var(--speed);
}
[data-theme-layout="factory-exportmap"] .link-card:hover { background: color-mix(in srgb, var(--accent) 8%, transparent); border-bottom-color: var(--accent); }
/* 序号轨：等宽两位序号 + 航线节点竖虚线（与首页航线卡同一语言） */
[data-theme-layout="factory-exportmap"] .link-card::before {
  counter-increment: emapRow; content: counter(emapRow, decimal-leading-zero);
  grid-column: 1; align-self: center; padding-left: .9rem;
  font-family: var(--mono); font-size: .74rem; font-weight: 800; letter-spacing: .06em; color: var(--accent);
}
[data-theme-layout="factory-exportmap"] .link-card::after {
  content: ""; position: absolute; left: .4rem; top: 0; bottom: 0;
  border-left: 1px dashed color-mix(in srgb, var(--accent) 34%, transparent);
}
[data-theme-layout="factory-exportmap"] .lc-cover {
  width: 104px; aspect-ratio: 4 / 3; border: 1px solid var(--line); border-radius: calc(var(--radius) * .7);
  background: var(--line-soft); overflow: hidden;
}
[data-theme-layout="factory-exportmap"] .lc-cover img { width: 100%; height: 100%; object-fit: cover; }
/* 基础 .lc-mono 是「accent 渐变底 + 白字」，在暗皮上白字只有 1.9:1 —— 本骨架换成
   line-soft 素底 + accent 首字（5.82 / 6.91 / 8.48） */
[data-theme-layout="factory-exportmap"] .lc-mono {
  background: var(--line-soft); font-family: var(--sans); font-size: 1.8rem; font-weight: 700; color: var(--accent);
}
[data-theme-layout="factory-exportmap"] .lc-body { display: flex; flex-direction: column; gap: .25rem; padding: 0; min-width: 0; }
[data-theme-layout="factory-exportmap"] .lc-title { margin: 0; font-family: var(--sans); font-size: 1rem; font-weight: 700; line-height: 1.4; }
[data-theme-layout="factory-exportmap"] .lc-intro {
  margin: 0; display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2;
  color: var(--muted); font-size: .84rem; line-height: 1.6;
}
/* 市场徽章车道：分类名（=市场分组轴）单独占右侧一条车道，行与行的徽章上下对齐成一列，
   视觉上把清单按市场归拢；≤720px 车道撤销、徽章回到文案流里（绝不叠字） */
[data-theme-layout="factory-exportmap"] .lc-foot { position: absolute; top: 50%; right: .4rem; margin: 0; transform: translateY(-50%); }
[data-theme-layout="factory-exportmap"] .lc-foot .tag {
  display: inline-block; max-width: 11rem; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
  padding: .16rem .5rem; border: 1px solid var(--accent); border-radius: 2px; background: transparent;
  color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase;
}
/* 基础 .tag:hover 是「accent 实底 + 白字」，暗皮下白字只剩 1.9:1 —— 徽章改成
   淡 accent 底 + accent 字（静息 7.93/7.51/9.68，悬停只加底不换字，不降对比） */
[data-theme-layout="factory-exportmap"] .lc-foot .tag:hover {
  background: color-mix(in srgb, var(--accent) 14%, transparent); border-color: var(--accent); color: var(--accent);
}
[data-theme-layout="factory-exportmap"] .lc-arrow { color: var(--accent); }
[data-theme-layout="factory-exportmap"] .pagination { font-family: var(--mono); }

/* ---- 商品详情：面包屑=航路、主销市场徽章行、点阵图版 ---- */
[data-theme-layout="factory-exportmap"] .pd-bc {
  font-family: var(--mono); font-size: .72rem; letter-spacing: .06em; text-transform: uppercase;
}
[data-theme-layout="factory-exportmap"] .pd-bc .sep { color: color-mix(in srgb, var(--accent) 60%, transparent); }
[data-theme-layout="factory-exportmap"] .pd-kicker a {
  display: inline-block; padding: .18rem .55rem; border: 1px solid var(--accent); border-radius: 2px;
  font-family: var(--mono); letter-spacing: .12em;
}
[data-theme-layout="factory-exportmap"] .pd-kicker a:hover { background: color-mix(in srgb, var(--accent) 12%, transparent); color: var(--accent); }
[data-theme-layout="factory-exportmap"] .pd-title { font-family: var(--sans); font-weight: 780; letter-spacing: -.015em; }
[data-theme-layout="factory-exportmap"] .pd-media {
  background-color: color-mix(in srgb, var(--accent) 5%, var(--surface));
  background-image: radial-gradient(circle at center, color-mix(in srgb, var(--accent) 26%, transparent) 1.3px, transparent 1.4px);
  background-size: 16px 16px;
}
[data-theme-layout="factory-exportmap"] .pd-media img { background: var(--surface); }
/* 主销市场徽章行：把规格字段行（.pd-meta-row）从表格式改成徽章，横向铺开成一条「通达市场」条 */
[data-theme-layout="factory-exportmap"] .pd-meta {
  display: flex; flex-wrap: wrap; gap: .5rem; border-top: 0; padding-top: .2rem;
}
[data-theme-layout="factory-exportmap"] .pd-meta-row {
  display: flex; flex-direction: column; gap: .1rem; min-width: 0; max-width: 100%;
  padding: .42rem .7rem .4rem; border: 1px solid var(--line); border-bottom: 0; border-radius: 2px;
  box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--accent) 55%, transparent);
  background: var(--bg);
}
[data-theme-layout="factory-exportmap"] .pd-meta-row dt {
  color: var(--muted); font-family: var(--mono); font-size: .62rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase;
}
[data-theme-layout="factory-exportmap"] .pd-meta-row dd { color: var(--ink); font-size: .88rem; font-weight: 650; }
[data-theme-layout="factory-exportmap"] .pd-sec-title { font-family: var(--sans); font-weight: 760; }
[data-theme-layout="factory-exportmap"] .pd-specs-tablewrap { background: var(--bg); }
[data-theme-layout="factory-exportmap"] .pd-specs-table th {
  background: color-mix(in srgb, var(--accent) 6%, transparent); color: var(--ink-soft);
  font-family: var(--mono); font-size: .74rem; letter-spacing: .08em; text-transform: uppercase;
}
/* 相关商品：缩成带航线节点的小卡，与首页航线卡同源 */
[data-theme-layout="factory-exportmap"] .pd-rel-card { border-radius: calc(var(--radius) * .7); }
[data-theme-layout="factory-exportmap"] .pd-rel-title { position: relative; padding-left: 1.6rem; font-family: var(--sans); }
[data-theme-layout="factory-exportmap"] .pd-rel-title::before {
  content: ""; position: absolute; left: .9rem; top: 1.05rem; width: 6px; height: 6px; border-radius: 50%; background: var(--accent);
}

/* ---- 页脚：与航线尺同语言的等宽小标题 ---- */
[data-theme-layout="factory-exportmap"] .site-footer .f-col h4 {
  font-family: var(--mono); font-size: .7rem; font-weight: 800; letter-spacing: .18em; text-transform: uppercase; color: var(--accent);
}

/* =========================================================================
   响应式：1020 / 920 / 720 / 620（任何断点都不横溢）
   ========================================================================= */
@media (max-width: 1020px) {
  [data-theme-layout="factory-exportmap"] .emap-route { grid-template-columns: 52px 82px minmax(0, 1fr) auto; }
  [data-theme-layout="factory-exportmap"] .emap-route-media { width: 82px; }
  [data-theme-layout="factory-exportmap"] .link-card { padding-right: 9.5rem; }
  [data-theme-layout="factory-exportmap"] .lc-foot .tag { max-width: 8.5rem; }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-exportmap"] .emap-hero { grid-template-columns: 1fr; }
  [data-theme-layout="factory-exportmap"] .emap-atlas { aspect-ratio: 2 / 1; }
  [data-theme-layout="factory-exportmap"] .emap-fold { grid-template-columns: 1fr; }
  [data-theme-layout="factory-exportmap"] .emap-certs { justify-content: flex-start; }
  [data-theme-layout="factory-exportmap"] .emap-routes { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-exportmap"] .emap-atlas { aspect-ratio: 3 / 2; min-height: 200px; }
  [data-theme-layout="factory-exportmap"] .emap-port { width: 5px; height: 5px; margin: -2.5px 0 0 -2.5px; }
  [data-theme-layout="factory-exportmap"] .emap-port.is-hub { width: 9px; height: 9px; margin: -4.5px 0 0 -4.5px; box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 26%, transparent); }
  [data-theme-layout="factory-exportmap"] .emap-port.is-hub::after { display: none; }
  [data-theme-layout="factory-exportmap"] .emap-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .6rem; }
  [data-theme-layout="factory-exportmap"] .emap-route { grid-template-columns: 46px 72px minmax(0, 1fr); gap: .7rem; }
  [data-theme-layout="factory-exportmap"] .emap-route-media { width: 72px; }
  [data-theme-layout="factory-exportmap"] .emap-route-ex,
  [data-theme-layout="factory-exportmap"] .emap-route .f-chips,
  [data-theme-layout="factory-exportmap"] .emap-route-go { display: none; }
  /* 市场徽章归位：撤掉右侧车道，回到文案流末尾 */
  [data-theme-layout="factory-exportmap"] .link-card { grid-template-columns: 44px 78px minmax(0, 1fr); gap: .7rem; padding-right: .4rem; }
  [data-theme-layout="factory-exportmap"] .lc-cover { width: 78px; }
  [data-theme-layout="factory-exportmap"] .lc-foot { position: static; margin-top: .3rem; transform: none; }
  [data-theme-layout="factory-exportmap"] .lc-foot .tag { max-width: 100%; }
  [data-theme-layout="factory-exportmap"] .lc-intro { -webkit-line-clamp: 1; }
  [data-theme-layout="factory-exportmap"] .pd-meta-row { flex: 1 1 8rem; }
}
@media (max-width: 620px) {
  /* 时区细条收起，导航交还基础汉堡抽屉（.nav 绝对定位于 header 底缘，细条不能占位） */
  [data-theme-layout="factory-exportmap"] .emap-zonebar { display: none; }
  [data-theme-layout="factory-exportmap"] .emap-wrap { padding-top: 1.1rem; }
  [data-theme-layout="factory-exportmap"] .emap-atlas { aspect-ratio: 4 / 3; min-height: 180px; }
}
@media (min-width: 621px) {
  /* 细条已经在做语种切换时，导航里的语言下拉隐藏，避免两套切换器并存 */
  [data-theme-layout="factory-exportmap"] .emap-zoned .nav .lang-switch { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-exportmap"] .emap-port.is-hub::after { animation: none; opacity: .5; transform: none; }
  [data-theme-layout="factory-exportmap"] .emap-route,
  [data-theme-layout="factory-exportmap"] .emap-zone,
  [data-theme-layout="factory-exportmap"] .link-card,
  [data-theme-layout="factory-exportmap"] .lc-arrow { transition: none; }
}

/* =========================================================================
   皮肤 ×3（Category=factory / Layout=factory-exportmap）
   对比度实算见交付说明：正文 ≥7:1，次要与 accent 作字 ≥4.5:1，hover 只升不降。
   ========================================================================= */
/* 航线图 · Exportmap（原生）：深海蓝底 + 航标青光点 */
:root[data-theme="exportmap"] {
  --bg: #0a1826; --surface: #10263c; --ink: #eef4fa; --ink-soft: #c9d9e8;
  --muted: #9ab0c6; --faint: #74899f; --line: #23415f; --line-soft: #17324c;
  --accent: #58b6ea; --accent-soft: #8ccdf3; --accent-wash: #123553; --code-bg: #061019;
  --w-wide: 1280px; --radius: 3px; --shadow: 0 14px 38px rgba(0,0,0,.45);
}
:root[data-theme="exportmap"] .site-header { background: rgba(10,24,38,.9); }
:root[data-theme="exportmap"] .btn-primary { color: #06121e; }
:root[data-theme="exportmap"] .inquiry-btn.inquiry-wa { color: #06121e; }
:root[data-theme="exportmap"] .cat-nav a.active { color: #06121e; }
/* CTA 通栏在暗皮下是「反色浅底」：共享的 eyebrow 混色（accent 60% + bg）落到 4.42，压深到 40% = 7.00 */
:root[data-theme="exportmap"] .f-cta .f-eyebrow { color: color-mix(in srgb, var(--accent) 40%, var(--bg)); }

/* 昼港 · Nightport（反差）：白昼版——浅蓝白海面 + 深蓝港点 */
:root[data-theme="nightport"] {
  --bg: #eef5fb; --surface: #ffffff; --ink: #0c1a29; --ink-soft: #2c3e52;
  --muted: #5a6d83; --faint: #7d90a4; --line: #ccdaea; --line-soft: #e2ecf6;
  --accent: #14527f; --accent-soft: #0e3c60; --accent-wash: #dceaf6;
  --w-wide: 1280px; --radius: 3px; --shadow: 0 10px 28px rgba(12,26,41,.09);
}
:root[data-theme="nightport"] .site-header { background: color-mix(in srgb, var(--bg) 90%, transparent); border-bottom: 1px solid var(--line); }
:root[data-theme="nightport"] .btn-primary { color: #fff; }
:root[data-theme="nightport"] .cat-nav a.active { color: #fff; }
/* 白昼版的海面点要更实一点才看得见（浅底上淡点会糊） */
:root[data-theme="nightport"] .emap-sea { background-image: radial-gradient(circle at center, color-mix(in srgb, var(--accent) 42%, transparent) 1.4px, transparent 1.5px); }
:root[data-theme="nightport"] .emap-atlas { background-color: color-mix(in srgb, var(--accent) 4%, var(--surface)); }

/* 航线图 · 纯白 Exportmap White：中性灰基底（对齐纯白系色卡）+ 压深的深蓝 accent */
:root[data-theme="exportmap-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #17457a; --accent-soft: #0f2f55; --accent-wash: #e9f0f8;
  --w-wide: 1200px; --radius: 3px; --shadow: 0 8px 24px rgba(16,18,24,.07);
}
:root[data-theme="exportmap-white"] .btn-primary { color: #fff; }
:root[data-theme="exportmap-white"] .cat-nav a.active { color: #fff; }
/* 纯白皮的坑：--muted(#707680) 在 --surface(#fafaf8) 上只有 4.38 —— 凡是承载 muted 文字的
   卡面一律覆写回 --bg(#ffffff) = 4.57；chip 的键名改用 ink-soft（它坐在 line-soft 混色面上）。 */
:root[data-theme="exportmap-white"] .f-stat,
:root[data-theme="exportmap-white"] .f-cat-card,
:root[data-theme="exportmap-white"] .f-industry,
:root[data-theme="exportmap-white"] .pd-specs-tablewrap { background-color: var(--bg); }
:root[data-theme="exportmap-white"] .f-chip b { color: var(--ink-soft); }
:root[data-theme="exportmap-white"] .emap-sea { background-image: radial-gradient(circle at center, color-mix(in srgb, var(--accent) 40%, transparent) 1.4px, transparent 1.5px); }
:root[data-theme="exportmap-white"] .emap-atlas { background-color: color-mix(in srgb, var(--accent) 4%, var(--bg)); }

/* =========================================================================
   LAYOUT: factory-sampleroom — 样品间（工厂族）
   每条选择器都限定 [data-theme-layout="factory-sampleroom"]，类名前缀 smp-（全仓未占用）。
   气质=样品册：纸质页签导航 + 色卡样品条 + 挂签卡；圆角一律「上方切齐 / 下方挂圆」，
   模拟被册脊夹住的样品签。
   页头：标准 .site-header 的纯 CSS 重塑（无专属 DOM 分支）——导航项做成一叠纸质页签，
        每签顶缘一道色带、相邻签互压 1px，当前项深底并「上翘」（靠 padding-top 长高，
        底缘始终咬在册脊线上，绝不脱开留缝）。≤620px 整段不生效，回落基础汉堡抽屉。
   页脚：封底色带（三段）+ 页签式栏头，同样纯 CSS。
   ========================================================================= */
[data-theme-layout="factory-sampleroom"] body { background: var(--bg); }

/* ---- 页头：样品册页签（≥621px 才成立；以下回落基础抽屉） ---- */
[data-theme-layout="factory-sampleroom"] .site-header { border-bottom: 2px solid var(--ink); }
@media (min-width: 621px) {
  [data-theme-layout="factory-sampleroom"] .site-header .wrap { align-items: flex-end; height: 76px; }
  [data-theme-layout="factory-sampleroom"] .site-header .brand { margin-bottom: 1.05rem; }
  [data-theme-layout="factory-sampleroom"] .nav { align-items: flex-end; gap: 0; }
  [data-theme-layout="factory-sampleroom"] .nav > a:not(.search-ico) { position: relative; margin: 0 0 -2px; padding: .5rem .95rem .55rem; border: 1px solid var(--line); border-bottom: 0; border-radius: 9px 9px 0 0; background: color-mix(in srgb, var(--surface) 88%, var(--line-soft)); box-shadow: inset 0 3px 0 color-mix(in srgb, var(--accent) 30%, transparent); color: var(--ink-soft); font-size: .88rem; font-weight: 620; transition: padding var(--speed), background var(--speed), color var(--speed), box-shadow var(--speed); }
  [data-theme-layout="factory-sampleroom"] .nav > a:not(.search-ico):nth-child(3n+2) { box-shadow: inset 0 3px 0 color-mix(in srgb, var(--accent) 58%, transparent); }
  [data-theme-layout="factory-sampleroom"] .nav > a:not(.search-ico):nth-child(3n+3) { box-shadow: inset 0 3px 0 color-mix(in srgb, var(--ink) 32%, transparent); }
  [data-theme-layout="factory-sampleroom"] .nav > a:not(.search-ico) + a { margin-left: -1px; }
  /* 悬停：只抬高、文字从 ink-soft 走到 ink（对比只升不降），绝不换成低对比的强调色 */
  [data-theme-layout="factory-sampleroom"] .nav > a:not(.search-ico):hover { z-index: 2; padding-top: .74rem; background: var(--surface); box-shadow: inset 0 3px 0 var(--accent); color: var(--ink); }
  [data-theme-layout="factory-sampleroom"] .nav > a[aria-current="page"] { z-index: 3; padding-top: .82rem; border-color: var(--ink); background: var(--ink); box-shadow: inset 0 3px 0 var(--accent); color: var(--bg); }
  [data-theme-layout="factory-sampleroom"] .nav > a[aria-current="page"]::after { content: none; }
  [data-theme-layout="factory-sampleroom"] .nav .search-ico { align-self: center; margin: 0 0 .95rem .9rem; opacity: .85; }
  [data-theme-layout="factory-sampleroom"] .nav .lang-switch { align-self: center; margin-bottom: .95rem; }
}

/* ---- 页脚：封底三段色带 + 页签式栏头（faint 级标签统一抬到 muted，避免低对比） ---- */
[data-theme-layout="factory-sampleroom"] .site-footer { position: relative; border-top: 2px solid var(--ink); }
[data-theme-layout="factory-sampleroom"] .site-footer::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 6px; background: linear-gradient(90deg, var(--accent) 0 33.34%, color-mix(in srgb, var(--accent) 52%, var(--surface)) 33.34% 66.67%, color-mix(in srgb, var(--ink) 42%, var(--surface)) 66.67% 100%); }
[data-theme-layout="factory-sampleroom"] .site-footer .f-col h4 { width: fit-content; padding: .2rem .6rem .22rem; border-radius: 3px 9px 0 0; border-bottom: 2px solid var(--accent); background: color-mix(in srgb, var(--accent) 8%, transparent); color: var(--muted); }
[data-theme-layout="factory-sampleroom"] .site-footer .copy { color: var(--muted); }
[data-theme-layout="factory-sampleroom"] .site-footer .f-col a:hover { color: var(--ink); text-decoration: underline; text-decoration-color: var(--accent); text-underline-offset: 3px; }

/* ---- 容器 ---- */
[data-theme-layout="factory-sampleroom"] .smp-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto; padding: clamp(1.7rem, 3.6vw, 2.6rem) 0 clamp(3rem, 6vw, 4.4rem); }

/* ---- 首屏：样品册封面（左册脊三段色 + 纸纹） ---- */
[data-theme-layout="factory-sampleroom"] .smp-hero { position: relative; display: grid; grid-template-columns: minmax(0, 1.06fr) minmax(0, .94fr); gap: clamp(1.3rem, 3vw, 2.4rem); padding: clamp(1.5rem, 3.4vw, 2.6rem); padding-left: clamp(1.9rem, 4vw, 3.1rem); border: 1px solid var(--line); border-radius: 4px 4px calc(var(--radius) + 10px) calc(var(--radius) + 10px); background-color: var(--surface); background-image: repeating-linear-gradient(0deg, color-mix(in srgb, var(--ink) 4%, transparent) 0 1px, transparent 1px 9px); overflow: hidden; }
[data-theme-layout="factory-sampleroom"] .smp-hero::before { content: ""; position: absolute; top: 0; bottom: 0; left: 0; width: 7px; background: linear-gradient(180deg, var(--accent) 0 34%, color-mix(in srgb, var(--accent) 52%, var(--surface)) 34% 67%, color-mix(in srgb, var(--ink) 42%, var(--surface)) 67% 100%); }
[data-theme-layout="factory-sampleroom"] .smp-hero-copy { min-width: 0; }
[data-theme-layout="factory-sampleroom"] .smp-eyebrow { width: fit-content; max-width: 100%; margin: 0 0 1rem; padding: .28rem .7rem .3rem; border: 1px solid var(--line); border-radius: 2px 10px 10px 2px; background: var(--bg); color: var(--accent); font-family: var(--mono); font-size: .7rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; }
[data-theme-layout="factory-sampleroom"] .smp-h1 { margin: 0; max-width: 15em; font-family: var(--sans); font-size: clamp(1.95rem, 4.4vw, 3.1rem); font-weight: 770; line-height: 1.1; letter-spacing: -.015em; }
[data-theme-layout="factory-sampleroom"] .smp-lede { max-width: 52ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75; }
[data-theme-layout="factory-sampleroom"] .smp-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.6rem; }
[data-theme-layout="factory-sampleroom"] .smp-stats { grid-template-columns: repeat(auto-fit, minmax(118px, 1fr)); gap: .6rem; margin-top: 1.7rem; }
[data-theme-layout="factory-sampleroom"] .smp-stats .f-stat { padding: .8rem .9rem .75rem; border-radius: 2px 2px 12px 12px; background-image: none; }
[data-theme-layout="factory-sampleroom"] .smp-stats .f-stat::after { content: none; }
[data-theme-layout="factory-sampleroom"] .smp-stats .f-stat dt { font-size: clamp(1.3rem, 2vw, 1.75rem); }
/* 色卡样品条：三条等高样品带（图集图或 accent 系变奏），左缘一道签色 */
[data-theme-layout="factory-sampleroom"] .smp-swatch { display: flex; flex-direction: column; gap: .55rem; min-height: clamp(220px, 25vw, 320px); }
[data-theme-layout="factory-sampleroom"] .smp-sw { position: relative; flex: 1 1 0; min-height: 56px; margin: 0; border: 1px solid var(--line); border-radius: 3px 14px 14px 3px; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-sampleroom"] .smp-sw::before { content: ""; position: absolute; top: 0; bottom: 0; left: 0; z-index: 1; width: 6px; background: var(--accent); }
[data-theme-layout="factory-sampleroom"] .smp-sw:nth-child(2)::before { background: color-mix(in srgb, var(--accent) 52%, var(--surface)); }
[data-theme-layout="factory-sampleroom"] .smp-sw:nth-child(3)::before { background: color-mix(in srgb, var(--ink) 42%, var(--surface)); }
[data-theme-layout="factory-sampleroom"] .smp-sw img { display: block; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="factory-sampleroom"] .smp-sw-no { position: absolute; right: .5rem; bottom: .45rem; padding: .1rem .5rem .12rem; border-radius: 2px 8px 8px 2px; background: var(--bg); color: var(--ink); font-family: var(--mono); font-size: .66rem; font-weight: 800; letter-spacing: .08em; }
[data-theme-layout="factory-sampleroom"] .smp-swatch-gen .smp-sw { border-color: color-mix(in srgb, var(--ink) 14%, transparent); }
[data-theme-layout="factory-sampleroom"] .smp-swatch-gen .smp-sw::before { background: color-mix(in srgb, var(--ink) 22%, transparent); }
[data-theme-layout="factory-sampleroom"] .smp-swatch-gen .smp-sw:nth-child(1) { background: var(--accent); }
[data-theme-layout="factory-sampleroom"] .smp-swatch-gen .smp-sw:nth-child(2) { background: color-mix(in srgb, var(--accent) 58%, var(--surface)); }
[data-theme-layout="factory-sampleroom"] .smp-swatch-gen .smp-sw:nth-child(3) { background: color-mix(in srgb, var(--accent) 24%, var(--surface)); }
[data-theme-layout="factory-sampleroom"] .smp-certs { grid-column: 1 / -1; margin-top: .2rem; padding-top: 1.1rem; border-top: 1px dashed var(--line); }

/* ---- 区块头：页签索引条 ---- */
[data-theme-layout="factory-sampleroom"] .smp-section { padding-top: clamp(2.6rem, 5.5vw, 3.8rem); }
[data-theme-layout="factory-sampleroom"] .smp-head { position: relative; display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem; margin-bottom: 1.3rem; padding-bottom: .75rem; border-bottom: 1px solid var(--line); }
[data-theme-layout="factory-sampleroom"] .smp-head::after { content: ""; position: absolute; left: 0; bottom: -1px; width: 64px; height: 3px; border-radius: 2px 2px 0 0; background: var(--accent); }
[data-theme-layout="factory-sampleroom"] .smp-head h2 { margin: 0; font-family: var(--sans); font-size: clamp(1.4rem, 2.5vw, 1.85rem); font-weight: 770; letter-spacing: -.01em; }
[data-theme-layout="factory-sampleroom"] .smp-head > a { flex: none; color: var(--ink-soft); font-size: .88rem; }
[data-theme-layout="factory-sampleroom"] .smp-head > a:hover { color: var(--ink); text-decoration: underline; text-decoration-color: var(--accent); text-underline-offset: 4px; }

/* ---- 工序签条：流程步骤改成挂签卡（顶缘色带由深到浅） ---- */
[data-theme-layout="factory-sampleroom"] .smp-proc .f-process { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .9rem; }
[data-theme-layout="factory-sampleroom"] .smp-proc .f-step { padding: .9rem 1rem 1rem; border: 1px solid var(--line); border-radius: 2px 2px 13px 13px; background: var(--surface); overflow: hidden; }
[data-theme-layout="factory-sampleroom"] .smp-proc .f-step::before,
[data-theme-layout="factory-sampleroom"] .smp-proc .f-step:last-child::before { top: 0; left: 0; right: 0; height: 6px; background: var(--accent); }
[data-theme-layout="factory-sampleroom"] .smp-proc .f-step:nth-child(2)::before { background: color-mix(in srgb, var(--accent) 62%, var(--surface)); }
[data-theme-layout="factory-sampleroom"] .smp-proc .f-step:nth-child(3)::before { background: color-mix(in srgb, var(--accent) 32%, var(--surface)); }
[data-theme-layout="factory-sampleroom"] .smp-proc .f-step:nth-child(4)::before { background: color-mix(in srgb, var(--ink) 34%, var(--surface)); }
[data-theme-layout="factory-sampleroom"] .smp-proc .f-step-num { margin-top: .3rem; padding-right: 0; background: none; font-size: 1.5rem; }

/* ---- 商品：样品挂签卡（顶部三段色带 + 挂签孔 + 克重/幅宽签） ---- */
[data-theme-layout="factory-sampleroom"] .smp-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1rem; }
[data-theme-layout="factory-sampleroom"] .smp-card { position: relative; display: flex; min-width: 0; flex-direction: column; border: 1px solid var(--line); border-radius: 2px 2px 14px 14px; background: var(--surface); color: var(--ink); overflow: hidden; transition: border-color var(--speed), transform var(--speed), box-shadow var(--speed); }
[data-theme-layout="factory-sampleroom"] .smp-card:hover { border-color: var(--accent); transform: translateY(-3px); box-shadow: 0 0 0 1px var(--accent), var(--shadow); color: var(--ink); }
[data-theme-layout="factory-sampleroom"] .smp-card-bands { position: relative; display: grid; flex: none; grid-template-columns: repeat(3, 1fr); height: 14px; }
[data-theme-layout="factory-sampleroom"] .smp-card-bands i { display: block; background: var(--accent); }
[data-theme-layout="factory-sampleroom"] .smp-card-bands i:nth-child(2) { background: color-mix(in srgb, var(--accent) 52%, var(--surface)); }
[data-theme-layout="factory-sampleroom"] .smp-card-bands i:nth-child(3) { background: color-mix(in srgb, var(--ink) 42%, var(--surface)); }
/* 挂签孔：待在色带这条专属车道里，任何视口都压不到图片/文字 */
[data-theme-layout="factory-sampleroom"] .smp-card-bands::after { content: ""; position: absolute; top: 3px; right: 9px; width: 8px; height: 8px; border-radius: 50%; background: var(--bg); box-shadow: 0 0 0 1px color-mix(in srgb, var(--ink) 28%, transparent); }
[data-theme-layout="factory-sampleroom"] .smp-card-media { display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-sampleroom"] .smp-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="factory-sampleroom"] .smp-card:hover .smp-card-media img { transform: scale(1.03); }
[data-theme-layout="factory-sampleroom"] .smp-card-gen b { font-family: var(--sans); font-size: 3rem; font-weight: 780; color: var(--accent); }
[data-theme-layout="factory-sampleroom"] .smp-card-body { display: flex; flex: 1; min-width: 0; flex-direction: column; gap: .3rem; padding: .85rem .95rem 1rem; }
[data-theme-layout="factory-sampleroom"] .smp-card-cat { width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 780; letter-spacing: .1em; text-transform: uppercase; }
[data-theme-layout="factory-sampleroom"] .smp-card-title { font-size: 1rem; font-weight: 720; line-height: 1.4; }
[data-theme-layout="factory-sampleroom"] .smp-card-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .82rem; line-height: 1.55; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="factory-sampleroom"] .smp-card .f-chips { margin-top: auto; padding-top: .6rem; }
[data-theme-layout="factory-sampleroom"] .f-chips .f-chip { border-radius: 2px 9px 9px 2px; border-left: 3px solid color-mix(in srgb, var(--accent) 62%, transparent); }
[data-theme-layout="factory-sampleroom"] .smp-empty { grid-column: 1 / -1; margin: 0; padding: 1.8rem; border: 1px dashed var(--line); border-radius: var(--radius); text-align: center; }

/* ---- 分类色卡 / 行业 / 图集 / FAQ / 动态 ---- */
[data-theme-layout="factory-sampleroom"] .smp-cats .f-cat-card { position: relative; padding-left: 1.2rem; border-radius: 3px 12px 12px 3px; }
[data-theme-layout="factory-sampleroom"] .smp-cats .f-cat-card::before { content: ""; position: absolute; top: -1px; bottom: -1px; left: -1px; width: 7px; border-radius: 3px 0 0 3px; background: var(--accent); }
[data-theme-layout="factory-sampleroom"] .smp-cats .f-cat-card:nth-child(3n+2)::before { background: color-mix(in srgb, var(--accent) 52%, var(--surface)); }
[data-theme-layout="factory-sampleroom"] .smp-cats .f-cat-card:nth-child(3n+3)::before { background: color-mix(in srgb, var(--ink) 42%, var(--surface)); }
[data-theme-layout="factory-sampleroom"] .smp-inds .f-industry { border-radius: 2px 12px 12px 2px; }
[data-theme-layout="factory-sampleroom"] .smp-gal .f-gallery-item { border-radius: 3px 14px 14px 3px; }
[data-theme-layout="factory-sampleroom"] .f-faq { border-top-width: 1px; border-top-color: var(--ink); }
[data-theme-layout="factory-sampleroom"] .f-faq-q:hover { background: color-mix(in srgb, var(--accent) 8%, transparent); color: var(--ink); }
[data-theme-layout="factory-sampleroom"] .smp-news-list { border-top: 1px solid var(--line); }
[data-theme-layout="factory-sampleroom"] .smp-news-item { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: .3rem 1rem; padding: .75rem .35rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .93rem; }
[data-theme-layout="factory-sampleroom"] .smp-news-item:hover { background: color-mix(in srgb, var(--accent) 7%, transparent); color: var(--ink); }
[data-theme-layout="factory-sampleroom"] .smp-news-item time { color: var(--muted); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-sampleroom"] .smp-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
/* 幽灵按钮/标签的悬停：底色不变、文字不降级，只加强调色边与光圈 */
[data-theme-layout="factory-sampleroom"] .btn:hover { border-color: var(--accent); color: var(--ink); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 22%, transparent); }
[data-theme-layout="factory-sampleroom"] .tag:hover { background: var(--accent-wash); color: var(--accent); }

/* ---- 内页重塑 ①：商品/归档列表 = 色卡墙（方形色卡 + 顶缘三段色带 + 紧凑签体） ---- */
[data-theme-layout="factory-sampleroom"] .wrap .link-grid { grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: .85rem; }
[data-theme-layout="factory-sampleroom"] .wrap .cat-nav a { border-radius: 3px 11px 11px 3px; }
[data-theme-layout="factory-sampleroom"] .wrap .link-card { position: relative; border-radius: 2px 2px 13px 13px; overflow: hidden; }
[data-theme-layout="factory-sampleroom"] .wrap .link-card::before { content: ""; position: absolute; top: 0; left: 0; right: 0; z-index: 2; height: 8px; background: linear-gradient(90deg, var(--accent) 0 33.34%, color-mix(in srgb, var(--accent) 52%, var(--surface)) 33.34% 66.67%, color-mix(in srgb, var(--ink) 42%, var(--surface)) 66.67% 100%); }
[data-theme-layout="factory-sampleroom"] .link-card .lc-cover { margin-top: 8px; aspect-ratio: 1 / 1; }
[data-theme-layout="factory-sampleroom"] .link-card .lc-mono { background: var(--line-soft); color: var(--accent); font-family: var(--sans); font-size: 2.2rem; font-weight: 780; }
[data-theme-layout="factory-sampleroom"] .link-card .lc-body { gap: .3rem; padding: .7rem .8rem .85rem; }
[data-theme-layout="factory-sampleroom"] .link-card .lc-title { font-size: .93rem; font-weight: 710; }
[data-theme-layout="factory-sampleroom"] .link-card .lc-intro { font-size: .78rem; -webkit-line-clamp: 1; }
[data-theme-layout="factory-sampleroom"] .link-card .tag { border-radius: 2px 8px 8px 2px; font-size: .68rem; }
[data-theme-layout="factory-sampleroom"] .wrap .link-card:hover { box-shadow: 0 0 0 1px var(--accent), var(--shadow); }

/* ---- 内页重塑 ②：商品详情 = 材质参数签 + 批次说明卡 ---- */
[data-theme-layout="factory-sampleroom"] .pd-main .pd-gallery::before { content: ""; display: block; height: 10px; border-radius: 3px 3px 0 0; background: linear-gradient(90deg, var(--accent) 0 33.34%, color-mix(in srgb, var(--accent) 52%, var(--surface)) 33.34% 66.67%, color-mix(in srgb, var(--ink) 42%, var(--surface)) 66.67% 100%); }
[data-theme-layout="factory-sampleroom"] .pd-main .pd-media { border-radius: 0 0 14px 14px; }
[data-theme-layout="factory-sampleroom"] .pd-main .pd-thumb { border-radius: 2px 2px 9px 9px; }
[data-theme-layout="factory-sampleroom"] .pd-main .pd-kicker { width: fit-content; padding: .18rem .55rem .2rem; border-radius: 2px 9px 9px 2px; background: color-mix(in srgb, var(--accent) 9%, transparent); }
/* 材质参数签：表头列做成带色条的签（标签字抬到 ink-soft，纯白皮下也稳过 7:1） */
[data-theme-layout="factory-sampleroom"] .pd-main .pd-specs-tablewrap { border-radius: 2px 2px 13px 13px; }
[data-theme-layout="factory-sampleroom"] .pd-main .pd-specs-table th { position: relative; width: 34%; padding-left: 1.5rem; background: color-mix(in srgb, var(--accent) 7%, transparent); color: var(--ink-soft); font-family: var(--mono); font-size: .82rem; font-weight: 650; letter-spacing: .03em; }
[data-theme-layout="factory-sampleroom"] .pd-main .pd-specs-table th::before { content: ""; position: absolute; top: 50%; left: .6rem; width: 4px; height: 15px; margin-top: -7px; border-radius: 1px; background: color-mix(in srgb, var(--accent) 70%, transparent); }
[data-theme-layout="factory-sampleroom"] .pd-main .pd-meta-row dt { color: var(--ink-soft); font-family: var(--mono); font-size: .84rem; }
/* 批次说明：正文块收进一张挂签卡（顶缘三段色带），与规格签同一语言 */
[data-theme-layout="factory-sampleroom"] .pd-main .pd-desc { position: relative; padding: clamp(1.2rem, 3vw, 1.7rem) clamp(1.1rem, 3vw, 1.6rem) clamp(1.3rem, 3vw, 1.8rem); border: 1px solid var(--line); border-radius: 2px 2px 14px 14px; background: var(--surface); }
[data-theme-layout="factory-sampleroom"] .pd-main .pd-desc::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 7px; border-radius: 2px 2px 0 0; background: linear-gradient(90deg, var(--accent) 0 33.34%, color-mix(in srgb, var(--accent) 52%, var(--surface)) 33.34% 66.67%, color-mix(in srgb, var(--ink) 42%, var(--surface)) 66.67% 100%); }
[data-theme-layout="factory-sampleroom"] .pd-main .pd-rel-card { position: relative; padding-top: 8px; border-radius: 2px 2px 13px 13px; }
[data-theme-layout="factory-sampleroom"] .pd-main .pd-rel-card::before { content: ""; position: absolute; top: 0; left: 0; right: 0; z-index: 2; height: 8px; background: linear-gradient(90deg, var(--accent) 0 33.34%, color-mix(in srgb, var(--accent) 52%, var(--surface)) 33.34% 66.67%, color-mix(in srgb, var(--ink) 42%, var(--surface)) 66.67% 100%); }
[data-theme-layout="factory-sampleroom"] .pd-main .inquiry { border-radius: 2px 2px 13px 13px; }

/* ---- 响应式 ---- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-sampleroom"] .smp-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-sampleroom"] .smp-hero { grid-template-columns: 1fr; }
  [data-theme-layout="factory-sampleroom"] .smp-swatch { flex-direction: row; min-height: 0; height: clamp(96px, 16vw, 140px); }
  [data-theme-layout="factory-sampleroom"] .smp-sw { min-height: 0; min-width: 0; }
  [data-theme-layout="factory-sampleroom"] .smp-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-sampleroom"] .smp-proc .f-process { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-sampleroom"] .smp-hero { padding-left: clamp(1.5rem, 5vw, 2rem); }
  [data-theme-layout="factory-sampleroom"] .smp-grid { gap: .7rem; }
  [data-theme-layout="factory-sampleroom"] .smp-card-ex { -webkit-line-clamp: 1; }
  [data-theme-layout="factory-sampleroom"] .smp-news-item { grid-template-columns: minmax(0, 1fr) auto; }
  [data-theme-layout="factory-sampleroom"] .smp-news-item time { grid-column: 1 / -1; }
  [data-theme-layout="factory-sampleroom"] .wrap .link-grid { grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); }
  [data-theme-layout="factory-sampleroom"] .pd-main .pd-specs-table th { width: 40%; }
}
@media (max-width: 560px) {
  [data-theme-layout="factory-sampleroom"] .smp-grid { grid-template-columns: 1fr 1fr; }
  [data-theme-layout="factory-sampleroom"] .smp-card .f-chips { display: none; }
  [data-theme-layout="factory-sampleroom"] .smp-proc .f-process { grid-template-columns: 1fr; }
  [data-theme-layout="factory-sampleroom"] .smp-swatch { height: clamp(78px, 22vw, 110px); }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-sampleroom"] .smp-card,
  [data-theme-layout="factory-sampleroom"] .smp-card-media img,
  [data-theme-layout="factory-sampleroom"] .wrap .link-card,
  [data-theme-layout="factory-sampleroom"] .pd-main .pd-thumb,
  [data-theme-layout="factory-sampleroom"] .nav > a:not(.search-ico) { transition: none; }
  [data-theme-layout="factory-sampleroom"] .smp-card:hover { transform: none; }
  [data-theme-layout="factory-sampleroom"] .smp-card:hover .smp-card-media img { transform: none; }
}

/* =========================================================================
   SKINS ×3 — sampleroom（原生 米棕纸）/ swatchbook（反差 深胡桃）/ sampleroom-white（纯白）
   实算对比度见文末注释；hover 一律只升不降。
   ========================================================================= */
/* 米棕纸 · Sampleroom：米纸底 + 赭石棕（原生皮） */
:root[data-theme="sampleroom"] {
  --bg: #f4efe4; --surface: #fbf7ee; --ink: #2b2318; --ink-soft: #4a3f30;
  --muted: #6c5f4d; --faint: #9b8b76; --line: #ded1ba; --line-soft: #ece3d2;
  --accent: #8a4a22; --accent-soft: #6b3715; --accent-wash: #f1e2d4;
  --w-wide: 1240px; --radius: 4px; --shadow: 0 1px 2px rgba(43,35,24,.05), 0 10px 26px rgba(43,35,24,.07);
}

/* 深胡桃 · Swatchbook：暗棕木底 + 米金（反差皮） */
:root[data-theme="swatchbook"] {
  --bg: #1c1510; --surface: #271e16; --ink: #f3ead9; --ink-soft: #dacdb8;
  --muted: #ac9d89; --faint: #7b6e5d; --line: #3c2f23; --line-soft: #2c221a;
  --accent: #d8b473; --accent-soft: #e8ca94; --accent-wash: #382a19; --code-bg: #14100b;
  --w-wide: 1240px; --radius: 4px; --shadow: 0 14px 40px rgba(0,0,0,.45);
}
:root[data-theme="swatchbook"] .btn-primary { color: #1c1510; }
:root[data-theme="swatchbook"] .smp-sw-no { color: var(--ink); background: var(--surface); }
/* 深皮下 CTA 通栏是「浅底反色」：眉标默认的 accent60%+bg 只有 3.72，压到 34% 换 7.01 */
:root[data-theme="swatchbook"] .f-cta .f-eyebrow { color: color-mix(in srgb, var(--accent) 34%, var(--bg)); }
:root[data-theme="swatchbook"] .f-stat dt { text-shadow: 0 0 18px rgba(216,180,115,.28); }

/* 纯白 · Sampleroom-white：中性灰基底 + 压深的赭石棕（accent 保留原生色相） */
:root[data-theme="sampleroom-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #8a4a22; --accent-soft: #6b3715; --accent-wash: #f6e8de;
  --w-wide: 1240px; --radius: 4px; --shadow: 0 1px 2px rgba(16,18,24,.05), 0 10px 26px rgba(16,18,24,.06);
}
:root[data-theme="sampleroom-white"] .btn-primary { color: #fff; }
/* --muted 在 #fafaf8 上只有 4.38 —— 凡是承载 muted 文字的卡面一律覆写回纯白（4.57） */
:root[data-theme="sampleroom-white"] .smp-hero,
:root[data-theme="sampleroom-white"] .smp-card,
:root[data-theme="sampleroom-white"] .f-stat,
:root[data-theme="sampleroom-white"] .f-chip,
:root[data-theme="sampleroom-white"] .f-cat-card,
:root[data-theme="sampleroom-white"] .f-industry,
:root[data-theme="sampleroom-white"] .smp-proc .f-step,
:root[data-theme="sampleroom-white"] .link-card,
:root[data-theme="sampleroom-white"] .site-footer,
:root[data-theme="sampleroom-white"] .pd-desc,
:root[data-theme="sampleroom-white"] .pd-specs-tablewrap,
:root[data-theme="sampleroom-white"] .inquiry { background-color: var(--bg); }
/* 纯白皮去掉纸纹/网格，身份就是「无装饰」 */
:root[data-theme="sampleroom-white"] .smp-hero,
:root[data-theme="sampleroom-white"] .f-about { background-image: none; }
:root[data-theme="sampleroom-white"] .f-cert { transform: none; }

/* -------------------------------------------------------------------------
   WCAG 实算（sampleroom / swatchbook / sampleroom-white）
   正文 ink/bg          13.50 / 15.10 / 18.72      ink/surface  14.48 / 13.70 / 17.91
   ink-soft/bg           8.96 / 11.52 /  9.79      ink-soft/页签面 9.43 / 10.41 / 9.29
   muted/卡面            5.81 /  6.18 /  4.57(卡面已覆写回 #fff；#fafaf8 上仅 4.38)
   muted/chip 面         5.23 /  6.02 /  4.57(同上覆写)
   accent/bg             5.94 /  9.19 /  6.81      accent/卡面   6.37 / 8.33 / 6.81
   accent-soft/bg        8.39 / 11.43 /  9.62（hover 更深/更亮，只升不降）
   accent/wash           5.37 /  7.07 /  5.68      accent 首字/line-soft 5.35 / 7.92 / 5.97
   btn-primary 字/accent 6.81 /  9.19 /  6.81  → hover accent-soft 9.62 / 11.43 / 9.62
   当前页签 bg 字/ink 底  13.50 / 15.10 / 18.72（CTA 通栏同一组合）
   CTA note/ink 底        7.68 /  6.55 /  9.95     CTA eyebrow 5.11 / 7.01(覆写后) / 6.65
   ------------------------------------------------------------------------- */

/* =========================================================================
   LAYOUT: factory-gauge — 仪表墙 factory instrument-wall home (pure CSS, no JS)
   every selector scoped under [data-theme-layout="factory-gauge"], classes gau-*
   页头：标准 .site-header 用 CSS 重塑成「拨杆开关排」导航（每项一枚拨杆，
   ▮=当前页拨上、▯=拨下），重塑段整段包在 @media (min-width: 621px) 里，
   ≤620px 原样交还基础汉堡抽屉（DOM 零改动，故无 header/footer 专属 define）。
   home：hero 右侧一整块仪表盘面——factory.stats 变指针表盘（CSS 圆盘 + 刻度环 +
   量程弧 + 旋转指针 + 盘面读数，最多 4 只）、factory.process 变盘面下状态指示灯排、
   factory.gallery 首图当监视窗（扫描线）、认证槽做铭牌条；商品=控制模块卡
  （左窗右体 + 规格 chip 重塑成量程行）；流程区=管线流程图（管道 + 阀门节点 + 流动虚线）。
   内页重塑：商品列表 .link-grid/.link-card → CH 计数量程行 + 每 4 行一条分组带；
   .cat-nav → 量程选择拨杆；商品详情 .pd-specs-table → 参数仪表行（小表盘 + 读数轨），
   .pd-meta-row → 读数行，.pd-media → 带角标的仪表窗。
   ========================================================================= */
[data-theme-layout="factory-gauge"] body { background: var(--bg); }
[data-theme-layout="factory-gauge"] .gau-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto;
  padding: clamp(1.5rem, 3.2vw, 2.4rem) 0 clamp(2.8rem, 6vw, 4.2rem);
}

/* ---- 页头：拨杆开关排（≥621px 才重塑，颜色规则在外层对两态都生效） ---------- */
[data-theme-layout="factory-gauge"] .site-header {
  background: var(--bg); border-bottom: 2px solid var(--line);
  -webkit-backdrop-filter: none; backdrop-filter: none;
}
@media (min-width: 621px) {
  [data-theme-layout="factory-gauge"] .site-header .wrap { height: 72px; gap: 1rem; }
  [data-theme-layout="factory-gauge"] .site-header .brand {
    font-family: var(--sans); font-weight: 800; letter-spacing: .04em;
    padding-left: .7rem; border-left: 4px solid var(--accent); min-width: 0;
  }
  [data-theme-layout="factory-gauge"] .nav { gap: .4rem; flex-wrap: wrap; justify-content: flex-end; }
  [data-theme-layout="factory-gauge"] .nav > a:not(.search-ico) {
    display: inline-flex; align-items: center; gap: .5rem; max-width: 15rem;
    padding: .32rem .6rem .32rem .45rem; border: 1px solid var(--line); border-radius: 3px;
    background: color-mix(in srgb, var(--line-soft) 55%, transparent);
    color: var(--ink-soft); font-family: var(--mono); font-size: .74rem; font-weight: 700;
    letter-spacing: .08em; text-transform: uppercase; overflow: hidden;
    white-space: nowrap; text-overflow: ellipsis;
    transition: border-color var(--speed), color var(--speed), background var(--speed);
  }
  /* 拨杆本体：▯ 拨下（灰块在下半格） */
  [data-theme-layout="factory-gauge"] .nav > a:not(.search-ico)::before {
    content: ""; flex: none; width: 9px; height: 18px; border-radius: 2px;
    border: 1px solid var(--line);
    background: linear-gradient(180deg, transparent 0 50%, color-mix(in srgb, var(--ink) 38%, transparent) 50% 100%);
  }
  [data-theme-layout="factory-gauge"] .nav > a:not(.search-ico):hover {
    border-color: var(--accent); color: var(--accent);
    background: color-mix(in srgb, var(--accent) 12%, transparent);
  }
  /* ▮ 拨上=当前页（同时干掉基础页头的下划线指示） */
  [data-theme-layout="factory-gauge"] .nav > a[aria-current="page"] {
    border-color: var(--accent); background: var(--accent-wash); color: var(--accent);
  }
  [data-theme-layout="factory-gauge"] .nav > a[aria-current="page"]::before {
    border-color: var(--accent);
    background: linear-gradient(180deg, var(--accent) 0 50%, transparent 50% 100%);
  }
  [data-theme-layout="factory-gauge"] .nav > a[aria-current="page"]::after { content: none; }
  [data-theme-layout="factory-gauge"] .nav .search-ico {
    opacity: 1; padding: .3rem .45rem; border: 1px solid var(--line); border-radius: 3px; color: var(--ink-soft);
  }
  [data-theme-layout="factory-gauge"] .nav .search-ico:hover { border-color: var(--accent); color: var(--accent); }
}

/* ---- hero：文案 | 仪表盘面 ------------------------------------------------ */
[data-theme-layout="factory-gauge"] .gau-hero {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, .95fr);
  gap: clamp(1.4rem, 3.2vw, 2.6rem); align-items: center;
}
[data-theme-layout="factory-gauge"] .gau-hero-copy { min-width: 0; }
[data-theme-layout="factory-gauge"] .gau-eyebrow {
  width: fit-content; max-width: 100%; margin: 0 0 1rem; padding: .24rem .55rem;
  border: 1px solid var(--accent); border-radius: 2px; color: var(--accent);
  font-family: var(--mono); font-size: .68rem; font-weight: 800;
  letter-spacing: .18em; text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="factory-gauge"] .gau-h1 {
  margin: 0; max-width: 15em; font-family: var(--sans);
  font-size: clamp(1.9rem, 4.4vw, 3.1rem); font-weight: 800;
  line-height: 1.08; letter-spacing: -.018em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-gauge"] .gau-lede {
  max-width: 54ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75;
}
[data-theme-layout="factory-gauge"] .gau-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }

/* 盘面：细网格底 + 内嵌描边（仪表柜面板） */
[data-theme-layout="factory-gauge"] .gau-board {
  min-width: 0; padding: clamp(1rem, 2.2vw, 1.5rem);
  border: 1px solid var(--line); border-radius: calc(var(--radius) + 2px);
  background-color: var(--surface);
  background-image:
    linear-gradient(color-mix(in srgb, var(--ink) 4%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--ink) 4%, transparent) 1px, transparent 1px);
  background-size: 22px 22px;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ink) 7%, transparent);
}
[data-theme-layout="factory-gauge"] .gau-board-cap {
  display: flex; align-items: center; gap: .6rem; margin: 0 0 1rem;
  color: var(--muted); font-family: var(--mono); font-size: .66rem; font-weight: 800;
  letter-spacing: .2em; text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="factory-gauge"] .gau-board-cap::after {
  content: ""; flex: 1; height: 1px; background: var(--line);
}

/* ---- 指针表盘（factory.stats；最多 4 只，装载层已钳到 4） ------------------- */
[data-theme-layout="factory-gauge"] .gau-dials { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .7rem; }
[data-theme-layout="factory-gauge"] .f-stat.gau-dial {
  min-width: 0; padding: 0; border: 0; border-radius: 0; background: none; text-align: center;
}
[data-theme-layout="factory-gauge"] .f-stat.gau-dial::before,
[data-theme-layout="factory-gauge"] .f-stat.gau-dial::after { content: none; }
/* 盘面：量程弧 → 刻度环 → 内盘面（层序自下而上写在 background-image 里，末层在最下） */
[data-theme-layout="factory-gauge"] .gau-dial dt {
  position: relative; width: 100%; max-width: 128px; margin: 0 auto; aspect-ratio: 1;
  padding: 52% 15% 15%; border-radius: 50%; overflow: hidden;
  display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2;
  background-color: var(--surface);
  background-image:
    radial-gradient(circle at 50% 50%, var(--surface) 0 61%, transparent 61.5%),
    repeating-conic-gradient(from -128deg at 50% 50%, color-mix(in srgb, var(--ink) 32%, transparent) 0 1.2deg, transparent 1.2deg 12.8deg),
    conic-gradient(from 232deg at 50% 50%, color-mix(in srgb, var(--accent) 55%, transparent) 0 96deg, transparent 96deg);
  box-shadow: inset 0 0 0 2px var(--line);
  font-family: var(--mono); font-size: clamp(.72rem, 1.5vw, .95rem); font-weight: 800;
  line-height: 1.15; letter-spacing: -.01em; color: var(--accent); text-align: center;
  overflow-wrap: anywhere;
}
/* 指针 + 中心轴（静止角按位次分配；扫针动画只在允许动效时跑） */
[data-theme-layout="factory-gauge"] .gau-dial dt::before {
  content: ""; position: absolute; left: 50%; top: 16%; width: 2px; height: 34%;
  border-radius: 2px; transform-origin: 50% 100%;
  transform: translateX(-50%) rotate(var(--gau-a, 0deg));
  background: linear-gradient(180deg, var(--accent) 0 74%, color-mix(in srgb, var(--accent) 35%, transparent));
  animation: gauSweep .95s cubic-bezier(.22, .85, .3, 1) both;
}
[data-theme-layout="factory-gauge"] .gau-dial dt::after {
  content: ""; position: absolute; left: 50%; top: 50%; width: 9px; height: 9px;
  margin: -4.5px 0 0 -4.5px; border-radius: 50%; background: var(--accent);
  box-shadow: 0 0 0 2px var(--surface);
}
[data-theme-layout="factory-gauge"] .gau-dial:nth-child(1) { --gau-a: -54deg; }
[data-theme-layout="factory-gauge"] .gau-dial:nth-child(2) { --gau-a: -16deg; }
[data-theme-layout="factory-gauge"] .gau-dial:nth-child(3) { --gau-a: 24deg; }
[data-theme-layout="factory-gauge"] .gau-dial:nth-child(4) { --gau-a: 58deg; }
@keyframes gauSweep {
  from { transform: translateX(-50%) rotate(-120deg); }
  to { transform: translateX(-50%) rotate(var(--gau-a, 0deg)); }
}
[data-theme-layout="factory-gauge"] .gau-dial dd {
  margin: .55rem 0 0; color: var(--muted); font-size: .66rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase; overflow-wrap: anywhere;
  display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden;
}
/* 没配 stats 时的「关于我们」兜底：去掉巨字水印，缩进盘面 */
[data-theme-layout="factory-gauge"] .gau-board .f-about { border-radius: calc(var(--radius) * .6); background-color: var(--bg); }
[data-theme-layout="factory-gauge"] .gau-board .f-about::after { content: none; }

/* ---- 状态指示灯排（factory.process） -------------------------------------- */
[data-theme-layout="factory-gauge"] .gau-lamps {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .5rem .9rem;
  margin: 1.1rem 0 0; padding: .9rem 0 0; border-top: 1px dashed var(--line); list-style: none;
}
[data-theme-layout="factory-gauge"] .gau-lamp {
  display: flex; align-items: center; gap: .5rem; min-width: 0;
  color: var(--ink-soft); font-size: .78rem;
}
[data-theme-layout="factory-gauge"] .gau-lamp b {
  flex: none; display: grid; place-items: center; width: 1.4rem; height: 1.4rem;
  border: 1px solid var(--accent); border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 14%, transparent);
  color: var(--accent); font-family: var(--mono); font-size: .58rem; font-weight: 800;
}
[data-theme-layout="factory-gauge"] .gau-lamp span { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* ---- 监视窗（图集首图）+ 铭牌条（认证） ----------------------------------- */
[data-theme-layout="factory-gauge"] .gau-board-foot {
  display: flex; flex-wrap: wrap; align-items: center; gap: .9rem;
  margin-top: 1rem; padding-top: .9rem; border-top: 1px dashed var(--line);
}
[data-theme-layout="factory-gauge"] .gau-scope {
  position: relative; flex: none; margin: 0; width: 116px; aspect-ratio: 4 / 3;
  border: 1px solid var(--line); border-radius: 2px; background: var(--line-soft); overflow: hidden;
}
[data-theme-layout="factory-gauge"] .gau-scope img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="factory-gauge"] .gau-scope::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: repeating-linear-gradient(180deg, color-mix(in srgb, var(--ink) 14%, transparent) 0 1px, transparent 1px 4px);
}
[data-theme-layout="factory-gauge"] .gau-certs { flex: 1 1 200px; gap: .45rem; }
[data-theme-layout="factory-gauge"] .gau-certs .f-cert:nth-child(odd),
[data-theme-layout="factory-gauge"] .gau-certs .f-cert:nth-child(even) {
  margin: 0; padding: .3rem .5rem .26rem; border-radius: 2px; outline: 0; transform: none;
}
[data-theme-layout="factory-gauge"] .gau-certs .f-cert b { font-size: .7rem; }
[data-theme-layout="factory-gauge"] .gau-certs .f-cert i { font-size: .48rem; letter-spacing: .16em; }

/* ---- 区块头 --------------------------------------------------------------- */
[data-theme-layout="factory-gauge"] .gau-section { padding-top: clamp(2.4rem, 5vw, 3.4rem); }
[data-theme-layout="factory-gauge"] .gau-head {
  position: relative; display: flex; align-items: flex-end; justify-content: space-between;
  gap: 1rem; margin-bottom: 1.3rem; padding-bottom: .7rem; border-bottom: 1px solid var(--line);
}
[data-theme-layout="factory-gauge"] .gau-head::after {
  content: ""; position: absolute; left: 0; bottom: -1px; width: 88px; height: 3px; background: var(--accent);
}
[data-theme-layout="factory-gauge"] .gau-head h2 {
  margin: 0; font-size: clamp(1.3rem, 2.4vw, 1.7rem); font-weight: 780; letter-spacing: -.01em;
}
[data-theme-layout="factory-gauge"] .gau-head > a { flex: none; color: var(--ink-soft); font-family: var(--mono); font-size: .78rem; }
[data-theme-layout="factory-gauge"] .gau-head > a:hover { color: var(--accent); }

/* ---- 商品：控制模块卡（左窗右体 + 量程行） -------------------------------- */
[data-theme-layout="factory-gauge"] .gau-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .9rem; }
[data-theme-layout="factory-gauge"] .gau-mod {
  display: grid; grid-template-columns: 104px minmax(0, 1fr); min-width: 0;
  border: 1px solid var(--line); border-radius: calc(var(--radius) * .6);
  background: var(--surface); color: var(--ink); overflow: hidden;
  transition: border-color var(--speed), box-shadow var(--speed), transform var(--speed);
}
[data-theme-layout="factory-gauge"] .gau-mod:hover {
  border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent), var(--shadow);
  transform: translateY(-2px); color: var(--ink);
}
[data-theme-layout="factory-gauge"] .gau-mod-media {
  display: grid; place-items: center; aspect-ratio: 1; border-right: 1px solid var(--line);
  background: var(--line-soft); overflow: hidden;
}
[data-theme-layout="factory-gauge"] .gau-mod-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
[data-theme-layout="factory-gauge"] .gau-mod:hover .gau-mod-media img { transform: scale(1.04); }
[data-theme-layout="factory-gauge"] .gau-mod-gen b { font-family: var(--mono); font-size: 2rem; font-weight: 800; color: var(--accent); }
[data-theme-layout="factory-gauge"] .gau-mod-body { display: flex; min-width: 0; flex-direction: column; gap: .22rem; padding: .75rem .85rem .8rem; }
[data-theme-layout="factory-gauge"] .gau-mod-ch {
  max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
  color: var(--accent); font-family: var(--mono); font-size: .62rem; font-weight: 800;
  letter-spacing: .1em; text-transform: uppercase;
}
[data-theme-layout="factory-gauge"] .gau-mod-title {
  font-size: .96rem; font-weight: 720; line-height: 1.35; overflow-wrap: anywhere;
  display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden;
}
[data-theme-layout="factory-gauge"] .gau-mod-ex {
  color: var(--muted); font-size: .78rem; line-height: 1.5; overflow-wrap: anywhere;
  display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 1; overflow: hidden;
}
[data-theme-layout="factory-gauge"] .gau-empty {
  grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center;
}
/* 规格 chip → 量程行：键左 / 读数右 / 下衬量程轨（填充宽度按位次） */
[data-theme-layout="factory-gauge"] .gau-ranges { display: grid; gap: .34rem; width: 100%; margin-top: .5rem; }
[data-theme-layout="factory-gauge"] .gau-ranges .f-chip {
  position: relative; display: grid; grid-template-columns: minmax(0, auto) minmax(0, 1fr);
  align-items: baseline; gap: .5rem; max-width: 100%; padding: 0 0 .42rem;
  border: 0; border-radius: 0; background: none; font-family: var(--mono); font-size: .62rem; color: var(--ink);
}
[data-theme-layout="factory-gauge"] .gau-ranges .f-chip b {
  color: var(--ink-soft); font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
}
[data-theme-layout="factory-gauge"] .gau-ranges .f-chip i { justify-self: end; font-weight: 700; color: var(--ink); }
[data-theme-layout="factory-gauge"] .gau-ranges .f-chip::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 2px;
  background: linear-gradient(90deg, var(--accent) 0 var(--gau-w, 55%), var(--line) var(--gau-w, 55%));
}
[data-theme-layout="factory-gauge"] .gau-ranges .f-chip:nth-child(1) { --gau-w: 68%; }
[data-theme-layout="factory-gauge"] .gau-ranges .f-chip:nth-child(2) { --gau-w: 44%; }

/* ---- 流程：管线流程图（管道 + 阀门节点 + 流动虚线） ------------------------ */
[data-theme-layout="factory-gauge"] .gau-pipeline .f-process { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .9rem; }
[data-theme-layout="factory-gauge"] .gau-pipeline .f-step {
  padding: 3rem .95rem 1rem; border: 1px solid var(--line);
  border-radius: calc(var(--radius) * .6); background: var(--surface);
}
[data-theme-layout="factory-gauge"] .gau-pipeline .f-step::before {
  content: ""; position: absolute; top: 1.55rem; left: -1px; right: -1px; height: 12px;
  border-block: 1px solid var(--line);
  background-color: color-mix(in srgb, var(--line-soft) 70%, transparent);
  background-image: repeating-linear-gradient(90deg, color-mix(in srgb, var(--accent) 55%, transparent) 0 9px, transparent 9px 20px);
  animation: gauFlow 1.5s linear infinite;
}
[data-theme-layout="factory-gauge"] .gau-pipeline .f-step:last-child::before {
  right: 0; border-right: 1px solid var(--line);
  background-image: repeating-linear-gradient(90deg, color-mix(in srgb, var(--accent) 55%, transparent) 0 9px, transparent 9px 20px);
}
[data-theme-layout="factory-gauge"] .gau-pipeline .f-step-num {
  position: absolute; top: .82rem; left: .95rem; z-index: 1; display: grid; place-items: center;
  width: 2.4rem; height: 2.4rem; padding: 0; border: 2px solid var(--accent); border-radius: 50%;
  background: var(--surface); color: var(--accent); font-size: .8rem;
}
[data-theme-layout="factory-gauge"] .gau-pipeline .f-step-title { margin: .1rem 0 .25rem; overflow-wrap: anywhere; }
[data-theme-layout="factory-gauge"] .gau-pipeline .f-step-note { overflow-wrap: anywhere; }
@keyframes gauFlow { to { background-position: 20px 0; } }

/* ---- 分类 / 行业 / FAQ：跟随仪表柜气质（直角 + 等宽计数） ------------------ */
[data-theme-layout="factory-gauge"] .f-cat-card { border-radius: calc(var(--radius) * .6); }
[data-theme-layout="factory-gauge"] .f-cat-count { font-weight: 700; }
[data-theme-layout="factory-gauge"] .f-industry { border-radius: calc(var(--radius) * .6); }
[data-theme-layout="factory-gauge"] .f-faq { border-top-width: 3px; }
[data-theme-layout="factory-gauge"] .f-faq-q { font-family: var(--sans); }

/* ---- 动态：读数行 --------------------------------------------------------- */
[data-theme-layout="factory-gauge"] .gau-log { border-top: 1px solid var(--line); }
[data-theme-layout="factory-gauge"] .gau-log-row {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline;
  gap: 1rem; padding: .72rem .2rem; border-bottom: 1px solid var(--line-soft);
  color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-gauge"] .gau-log-row:hover { color: var(--accent); }
[data-theme-layout="factory-gauge"] .gau-log-row time { color: var(--muted); font-family: var(--mono); font-size: .72rem; }
[data-theme-layout="factory-gauge"] .gau-log-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* =========================================================================
   内页重塑（不改公共模板，只用既有类名）
   ========================================================================= */
/* 商品/归档列表：量程分组行 —— CH 计数器 + 缩略窗 + 行底量程轨，每 4 行一条分组带 */
[data-theme-layout="factory-gauge"] .link-grid {
  display: grid; grid-template-columns: 1fr; gap: 0; margin: 1.4rem 0 0;
  border-top: 3px solid var(--ink); counter-reset: gaurow;
}
[data-theme-layout="factory-gauge"] .link-card {
  display: grid; grid-template-columns: 4.4rem 84px minmax(0, 1fr); align-items: center;
  gap: 0 1rem; padding: .8rem .25rem .55rem; border: 0; border-bottom: 1px solid var(--line-soft);
  border-radius: 0; background: none; box-shadow: none;
  transition: background var(--speed), color var(--speed);
}
[data-theme-layout="factory-gauge"] .link-card::before {
  counter-increment: gaurow; content: "№ " counter(gaurow, decimal-leading-zero);
  align-self: center; color: var(--accent); font-family: var(--mono);
  font-size: .72rem; font-weight: 800; letter-spacing: .06em;
}
[data-theme-layout="factory-gauge"] .link-card::after {
  content: ""; grid-column: 1 / -1; height: 3px; margin-top: .55rem; border-radius: 2px;
  background: linear-gradient(90deg, var(--accent) 0 var(--gau-w, 46%), var(--line) var(--gau-w, 46%));
}
[data-theme-layout="factory-gauge"] .link-card:hover {
  border-color: var(--line-soft); box-shadow: none; transform: none;
  background: color-mix(in srgb, var(--accent) 8%, transparent); color: var(--ink);
}
/* 分组带：每 4 行起一组（组首行加重线），组内量程逐级递减 */
[data-theme-layout="factory-gauge"] .link-card:nth-child(4n+1) { --gau-w: 82%; border-top: 2px solid var(--line); }
[data-theme-layout="factory-gauge"] .link-card:nth-child(4n+2) { --gau-w: 64%; }
[data-theme-layout="factory-gauge"] .link-card:nth-child(4n+3) { --gau-w: 48%; }
[data-theme-layout="factory-gauge"] .link-card:nth-child(4n+4) { --gau-w: 33%; }
[data-theme-layout="factory-gauge"] .lc-cover { aspect-ratio: 4 / 3; border: 1px solid var(--line); border-radius: 2px; }
[data-theme-layout="factory-gauge"] .lc-mono {
  background: var(--line-soft); color: var(--accent); font-family: var(--mono); font-size: 1.5rem; font-weight: 800;
}
[data-theme-layout="factory-gauge"] .lc-body { padding: 0; gap: .25rem; }
[data-theme-layout="factory-gauge"] .lc-title { font-size: .98rem; font-weight: 720; }
[data-theme-layout="factory-gauge"] .lc-intro {
  font-size: .82rem; overflow-wrap: anywhere;
  display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 1; overflow: hidden;
}
[data-theme-layout="factory-gauge"] .lc-foot { margin-top: .1rem; }
/* 分类导航 → 量程选择拨杆（与页头同一开关语言） */
[data-theme-layout="factory-gauge"] .cat-nav a {
  display: inline-flex; align-items: center; gap: .45rem; padding: .34rem .7rem;
  border-radius: 3px; font-family: var(--mono); font-size: .78rem; letter-spacing: .04em;
}
[data-theme-layout="factory-gauge"] .cat-nav a::before {
  content: ""; flex: none; width: 8px; height: 16px; border: 1px solid var(--line); border-radius: 2px;
  background: linear-gradient(180deg, transparent 0 50%, color-mix(in srgb, var(--ink) 34%, transparent) 50% 100%);
}
[data-theme-layout="factory-gauge"] .cat-nav a.active::before {
  border-color: var(--bg);
  background: linear-gradient(180deg, var(--bg) 0 50%, transparent 50% 100%);
}
/* 商品详情：参数仪表行（小表盘 + 读数轨）+ 仪表窗大图 */
[data-theme-layout="factory-gauge"] .pd-media { position: relative; border-width: 2px; }
[data-theme-layout="factory-gauge"] .pd-media::before,
[data-theme-layout="factory-gauge"] .pd-media::after {
  content: ""; position: absolute; width: 14px; height: 14px; pointer-events: none;
}
[data-theme-layout="factory-gauge"] .pd-media::before { top: 7px; left: 7px; border-top: 2px solid var(--accent); border-left: 2px solid var(--accent); }
[data-theme-layout="factory-gauge"] .pd-media::after { right: 7px; bottom: 7px; border-bottom: 2px solid var(--accent); border-right: 2px solid var(--accent); }
[data-theme-layout="factory-gauge"] .pd-kicker a {
  display: inline-block; padding: .2rem .5rem; border: 1px solid var(--accent); border-radius: 2px; font-size: .68rem;
}
[data-theme-layout="factory-gauge"] .pd-title { letter-spacing: -.015em; font-weight: 800; }
[data-theme-layout="factory-gauge"] .pd-meta { border-top: 2px solid var(--line); }
[data-theme-layout="factory-gauge"] .pd-meta-row dt {
  color: var(--ink-soft); font-family: var(--mono); font-size: .76rem;
  letter-spacing: .06em; text-transform: uppercase;
}
[data-theme-layout="factory-gauge"] .pd-meta-row dd { font-family: var(--mono); font-weight: 700; }
[data-theme-layout="factory-gauge"] .pd-specs-tablewrap { border-radius: calc(var(--radius) * .6); }
[data-theme-layout="factory-gauge"] .pd-specs-table th {
  position: relative; width: 44%; min-width: 11rem; padding: .8rem 1rem .8rem 3.4rem;
  background: none; color: var(--ink-soft); font-family: var(--mono); font-size: .78rem;
  font-weight: 700; letter-spacing: .04em; overflow-wrap: anywhere;
}
/* 小表盘：中心轴 → 指针扇 → 盘面 → 刻度环（层序自上而下） */
[data-theme-layout="factory-gauge"] .pd-specs-table th::before {
  content: ""; position: absolute; left: 1rem; top: 50%; width: 26px; height: 26px; margin-top: -13px;
  border-radius: 50%; box-shadow: inset 0 0 0 1px var(--line);
  background-color: var(--bg);
  background-image:
    radial-gradient(circle at 50% 50%, var(--accent) 0 12%, transparent 13%),
    conic-gradient(from calc(var(--gau-a, 0deg) - 4deg) at 50% 50%, var(--accent) 0 8deg, transparent 8deg),
    radial-gradient(circle at 50% 50%, var(--bg) 0 63%, transparent 63.5%),
    repeating-conic-gradient(from 0deg at 50% 50%, color-mix(in srgb, var(--ink) 30%, transparent) 0 2deg, transparent 2deg 30deg);
}
[data-theme-layout="factory-gauge"] .pd-specs-table td {
  position: relative; padding: .8rem 1rem 1.25rem; font-family: var(--mono); font-weight: 700; overflow-wrap: anywhere;
}
[data-theme-layout="factory-gauge"] .pd-specs-table td::after {
  content: ""; position: absolute; left: 1rem; right: 1rem; bottom: .5rem; height: 3px; border-radius: 2px;
  background: linear-gradient(90deg, var(--accent) 0 var(--gau-w, 52%), var(--line-soft) var(--gau-w, 52%));
}
[data-theme-layout="factory-gauge"] .pd-specs-table tr:nth-child(4n+1) { --gau-a: -52deg; --gau-w: 78%; }
[data-theme-layout="factory-gauge"] .pd-specs-table tr:nth-child(4n+2) { --gau-a: -14deg; --gau-w: 60%; }
[data-theme-layout="factory-gauge"] .pd-specs-table tr:nth-child(4n+3) { --gau-a: 22deg; --gau-w: 45%; }
[data-theme-layout="factory-gauge"] .pd-specs-table tr:nth-child(4n+4) { --gau-a: 56deg; --gau-w: 30%; }
[data-theme-layout="factory-gauge"] .pd-rel-card { border-radius: calc(var(--radius) * .6); }
[data-theme-layout="factory-gauge"] .pd-rel-gen b { font-family: var(--mono); font-weight: 800; color: var(--accent); }
[data-theme-layout="factory-gauge"] .pd-rel-title { font-size: .9rem; }
[data-theme-layout="factory-gauge"] .pd-sec-title { font-family: var(--sans); font-weight: 780; }

/* ---- 响应式：1020 / 920 / 720 / 620 --------------------------------------- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-gauge"] .gau-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-gauge"] .gau-hero { grid-template-columns: 1fr; gap: 1.6rem; }
  [data-theme-layout="factory-gauge"] .gau-h1 { max-width: none; }
  [data-theme-layout="factory-gauge"] .gau-dials { gap: .6rem; }
  [data-theme-layout="factory-gauge"] .gau-pipeline .f-process { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
  [data-theme-layout="factory-gauge"] .gau-pipeline .f-step:nth-child(2)::before { right: 0; border-right: 1px solid var(--line); }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-gauge"] .gau-grid { grid-template-columns: 1fr; }
  [data-theme-layout="factory-gauge"] .gau-dials { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem .6rem; }
  [data-theme-layout="factory-gauge"] .gau-dial dt { max-width: 116px; }
  [data-theme-layout="factory-gauge"] .gau-lamps { grid-template-columns: 1fr; }
  [data-theme-layout="factory-gauge"] .gau-scope { width: 92px; }
  [data-theme-layout="factory-gauge"] .link-card { grid-template-columns: 3.6rem 64px minmax(0, 1fr); gap: 0 .7rem; }
  [data-theme-layout="factory-gauge"] .lc-intro { display: none; }
  [data-theme-layout="factory-gauge"] .pd-specs-table th { width: 46%; min-width: 0; padding-left: 2.9rem; font-size: .74rem; }
  [data-theme-layout="factory-gauge"] .pd-specs-table th::before { left: .7rem; width: 22px; height: 22px; margin-top: -11px; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-gauge"] .gau-mod { grid-template-columns: 84px minmax(0, 1fr); }
  [data-theme-layout="factory-gauge"] .gau-log-row { grid-template-columns: minmax(0, 1fr) auto; gap: .2rem .8rem; }
  [data-theme-layout="factory-gauge"] .gau-log-row time { grid-column: 1 / -1; }
  [data-theme-layout="factory-gauge"] .gau-log-title { white-space: normal; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-gauge"] .gau-dial dt::before,
  [data-theme-layout="factory-gauge"] .gau-pipeline .f-step::before { animation: none; }
  [data-theme-layout="factory-gauge"] .gau-mod,
  [data-theme-layout="factory-gauge"] .gau-mod-media img,
  [data-theme-layout="factory-gauge"] .link-card,
  [data-theme-layout="factory-gauge"] .nav > a:not(.search-ico) { transition: none; }
}

/* ============================================================
   仪表 · Gauge —— factory-gauge 原生皮：仪表深灰机柜 + 青绿荧光读数
   实算：正文 14.80（surface 13.39）/ 次要 10.62（9.61）/ muted 6.61（5.98）/
   青绿字 9.15（surface 8.28，hover soft 11.16 只升）/ 深底按钮字 9.15 /
   青绿压 wash 7.33 / 青绿压 line-soft 7.39（首字生成块、量程轨）
   ============================================================ */
:root[data-theme="gauge"] {
  --bg: #171b1d; --surface: #1f2426;
  --ink: #e8eef0; --ink-soft: #c3cccf; --muted: #96a2a5; --faint: #7c898c;
  --line: #333b3e; --line-soft: #262d30;
  --accent: #5ad0b0; --accent-soft: #86e0c8; --accent-wash: #10322b;
  --w-wide: 1240px; --radius: 4px; --code-bg: #0f1214;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 10px 28px rgba(0, 0, 0, .5);
}
:root[data-theme="gauge"] .btn-primary { color: #171b1d; }
/* 反色 CTA 通栏（ink 底）上的荧光青绿只有 1.62 —— 眉标/按钮改用底色系亮字 */
:root[data-theme="gauge"] .f-cta .f-eyebrow { color: color-mix(in srgb, var(--bg) 88%, var(--accent)); }
:root[data-theme="gauge"] .gau-certs .f-cert { border-color: color-mix(in srgb, var(--ink) 55%, transparent); }

/* ============================================================
   白盘 · Dialface —— factory-gauge 反差皮：浅灰白盘面 + 深青指针
   实算：正文 15.52（surface 17.64）/ 次要 8.91（10.13）/ muted 5.09（5.79）/
   深青字 6.65（surface 7.56，hover soft 9.31 只升）/ 白字压深青 7.56 /
   深青压 wash 6.14 / 深青压 line-soft 6.04
   ============================================================ */
:root[data-theme="dialface"] {
  --bg: #eef1f0; --surface: #ffffff;
  --ink: #131a1a; --ink-soft: #39443f; --muted: #5c6866; --faint: #8a9693;
  --line: #ced5d3; --line-soft: #e2e7e5;
  --accent: #0f5f52; --accent-soft: #0a473e; --accent-wash: #dcebe6;
  --w-wide: 1240px; --radius: 4px;
  --shadow: 0 1px 2px rgba(19, 26, 26, .05), 0 8px 22px rgba(19, 26, 26, .07);
}
:root[data-theme="dialface"] .btn-primary { color: #fff; }

/* ============================================================
   仪表 · 纯白 —— factory-gauge 纯白皮：中性灰基底照抄「纯白系」段，
   青绿保留本族色相并压深到 #0f6355（白底 7.15，hover soft 10.03 只升）；
   正文 18.72（surface 17.91）/ 次要 9.79（9.37）/ muted 白底 4.57——
   落 surface 只有 4.38，所以带 muted 文字的卡面（模块卡/分类卡/行业卡/
   流程卡/盘面/规格表）基底覆写回纯白 --bg
   ============================================================ */
:root[data-theme="gauge-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #707680; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #0f6355; --accent-soft: #0b4b40; --accent-wash: #e4f0ec;
  --w-wide: 1240px; --radius: 4px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .05), 0 8px 20px rgba(16, 18, 24, .06);
}
:root[data-theme="gauge-white"] .btn-primary { color: #fff; }
:root[data-theme="gauge-white"] .gau-board,
:root[data-theme="gauge-white"] .gau-dial dt,
:root[data-theme="gauge-white"] .gau-mod,
:root[data-theme="gauge-white"] .gau-pipeline .f-step,
:root[data-theme="gauge-white"] .gau-pipeline .f-step-num,
:root[data-theme="gauge-white"] .f-cat-card,
:root[data-theme="gauge-white"] .f-industry,
:root[data-theme="gauge-white"] .pd-specs-tablewrap { background-color: var(--bg); }
:root[data-theme="gauge-white"] .gau-dial dt::after { box-shadow: 0 0 0 2px var(--bg); }

/* =========================================================================
   LAYOUT: factory-gantry — 龙门（工厂族新骨架；partial home_factory_gantry）
   每条选择器限定 [data-theme-layout="factory-gantry"]，自有类名前缀 gnt-（全仓仅本骨架占用）。
   形态：整页读成一座龙门吊。
     页头 = 龙门横梁（header_factory_gantry 专属 DOM）：粗黄横梁整条通栏包住导航
            （上下 3px 钢缘压边，导航字用 --gnt-beam-ink 实算达标），站点标题从横梁
            用两根细钢缆（.gnt-cable 双线）吊下铭牌 .gnt-nameplate（铆钉牌）；
            页头不吸顶——架子是站在地上的结构。≤620px 横梁收成细条、钢缆收起、
            铭牌与汉堡同排，导航回落基础抽屉（menu-toggle + .nav-open，绝不 :target）。
     立柱 = .gnt-hoist 与首屏 .gnt-stage 共用同宽容器的 border-inline 粗黄立柱，
            视觉连成门架；架底 .gnt-stage 收一条粗黄地轨（border-bottom）。
     hero = 居中：钢缆吊眉标铭牌 → 大标题 → 按钮；factory.stats 渲染成「横梁铭板」
            （单条铆钉牌，格间分缝；未配置回落 factory_about）；hero 槽图走
            .gnt-stage-img + bg 92% 遮罩（veil），文字全程压 bg 系底实算达标。
     商品 = 吊装件卡：顶部 6px 粗黄梁边 + 顶缘居中吊环（::before 圆环，专属车道=
            卡自身上缘，720px 收小），悬停「起吊」上浮 + accent 描边。
     流程 = 共享 f-process 重塑成行车轨道：轨枕纹横轨 + 挂轨小车号牌（黄底深字）。
   内页重塑（不改公共模板，只重塑既有类）：
     列表 .page-head → 小龙门门架（居中标题 + 两侧立柱 + 底轨）；.cat-nav → 跨度牌
     （直角挂牌）；.link-grid/.link-card → 吊装件卡（顶部黄梁 + 吊环 + 悬停起吊）。
     详情 .pd-bc → 挂签（顶缘黄边等宽字）；.pd-meta / .pd-specs-tablewrap → 吊重参数牌
     （2px 钢框 + 6px 黄梁顶缘 + 等宽大写表头）；.pd-rel-card 同吊装件卡。
   容器规约：width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto。
   ========================================================================= */
[data-theme-layout="factory-gantry"] {
  --gnt-beam: var(--accent);                                       /* 横梁/立柱/黄梁边（皮肤覆写） */
  --gnt-beam-ink: var(--surface);                                  /* 横梁上的导航字（皮肤覆写） */
  --gnt-cable-c: color-mix(in srgb, var(--ink) 45%, transparent);  /* 钢缆双线 */
  --gnt-rail: color-mix(in srgb, var(--ink) 30%, transparent);     /* 行车轨道轨枕纹 */
}
[data-theme-layout="factory-gantry"] body { background: var(--bg); }
[data-theme-layout="factory-gantry"] .gnt-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-bottom: clamp(3rem, 6vw, 4.4rem);
}

/* ---- 页头：龙门横梁 + 吊下来的铭牌（专属 DOM，header_factory_gantry）------ */
/* 不吸顶：门架站在地上跟页面走；保留 relative 给 ≤620px 抽屉 .nav 定位 */
[data-theme-layout="factory-gantry"] .gnt-header {
  position: relative; top: auto; background: transparent;
  -webkit-backdrop-filter: none; backdrop-filter: none; border-bottom: 0;
}
[data-theme-layout="factory-gantry"] .gnt-beam {
  background: var(--gnt-beam);
  border-block: 3px solid var(--ink);
}
[data-theme-layout="factory-gantry"] .gnt-hoist {
  position: relative; display: flex; flex-direction: column; align-items: center;
  width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto;
  border-inline: 10px solid var(--gnt-beam); padding-bottom: 1rem;
}
[data-theme-layout="factory-gantry"] .gnt-cable {
  display: block; width: clamp(120px, 16vw, 170px); height: 26px;
  border-inline: 2px solid var(--gnt-cable-c);
}
[data-theme-layout="factory-gantry"] .gnt-nameplate {
  position: relative; max-width: min(92%, 560px); padding: .55rem 1.6rem .6rem;
  border: 2px solid var(--ink); background: var(--surface);
  box-shadow: var(--shadow); text-align: center;
}
/* 铭牌铆钉：专属车道=铭牌自身左右缘，绝不外溢 */
[data-theme-layout="factory-gantry"] .gnt-nameplate::before,
[data-theme-layout="factory-gantry"] .gnt-nameplate::after {
  content: ""; position: absolute; top: 50%; width: 7px; height: 7px; margin-top: -3.5px;
  border: 2px solid var(--gnt-cable-c); border-radius: 50%; pointer-events: none;
}
[data-theme-layout="factory-gantry"] .gnt-nameplate::before { left: 6px; }
[data-theme-layout="factory-gantry"] .gnt-nameplate::after { right: 6px; }
[data-theme-layout="factory-gantry"] .gnt-nameplate .brand {
  justify-content: center; font-family: var(--sans); font-weight: 800; letter-spacing: -.01em;
}
@media (min-width: 621px) {
  [data-theme-layout="factory-gantry"] .gnt-nav {
    display: flex; align-items: stretch; justify-content: center; gap: 0;
    width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto; min-height: 50px;
  }
  [data-theme-layout="factory-gantry"] .gnt-nav > a {
    display: inline-flex; align-items: center; padding-inline: clamp(.6rem, 1.4vw, 1.1rem);
    color: var(--gnt-beam-ink); font-size: .92rem; font-weight: 700; overflow-wrap: anywhere;
  }
  /* 悬停不换色（黄底上换 accent 会掉对比），加下划线只升不降 */
  [data-theme-layout="factory-gantry"] .gnt-nav > a:hover {
    color: var(--gnt-beam-ink); text-decoration: underline;
    text-decoration-thickness: 2px; text-underline-offset: 6px;
  }
  [data-theme-layout="factory-gantry"] .gnt-nav a[aria-current="page"] { color: var(--gnt-beam-ink); }
  /* 当前项：基础规则是 bottom:-22px 细线，这里压回横梁底缘加粗 */
  [data-theme-layout="factory-gantry"] .gnt-nav a[aria-current="page"]::after {
    top: auto; bottom: 0; height: 4px; background: var(--gnt-beam-ink);
  }
  [data-theme-layout="factory-gantry"] .gnt-nav .search-ico { opacity: 1; color: var(--gnt-beam-ink); }
  [data-theme-layout="factory-gantry"] .gnt-nav .lang-switch,
  [data-theme-layout="factory-gantry"] .gnt-nav .lang-switch summary { color: var(--gnt-beam-ink); }
  [data-theme-layout="factory-gantry"] .gnt-nameplate .brand-tagline {
    display: block; margin: .15rem 0 0; color: var(--muted);
    font-size: .72rem; letter-spacing: .08em;
  }
}

/* ---- hero：龙门架内的居中首屏（立柱 + 地轨 + 钢缆吊铭牌）------------------ */
[data-theme-layout="factory-gantry"] .gnt-stage {
  position: relative; width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto;
  border-inline: 10px solid var(--gnt-beam); border-bottom: 8px solid var(--gnt-beam);
  background: var(--surface); text-align: center; overflow: hidden;
}
/* 槽图 + 遮罩：绝对定位专属车道=stage 自身（overflow hidden 兜住） */
[data-theme-layout="factory-gantry"] .gnt-stage-img {
  position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover;
}
[data-theme-layout="factory-gantry"] .gnt-stage-veil {
  position: absolute; inset: 0; background: color-mix(in srgb, var(--bg) 92%, transparent);
}
[data-theme-layout="factory-gantry"] .gnt-stage-in {
  position: relative; z-index: 1; display: flex; flex-direction: column; align-items: center;
  padding: 0 clamp(1.2rem, 4vw, 3rem) clamp(2rem, 4.5vw, 3rem);
}
[data-theme-layout="factory-gantry"] .gnt-stage .gnt-cable { height: clamp(34px, 6vw, 60px); }
[data-theme-layout="factory-gantry"] .gnt-eyebrow {
  max-width: 100%; margin: 0 0 1.2rem; padding: .34rem .85rem;
  border: 2px solid var(--ink); background: var(--surface); color: var(--ink);
  font-family: var(--mono); font-size: .7rem; font-weight: 800;
  letter-spacing: .18em; text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="factory-gantry"] .gnt-h1 {
  margin: 0; max-width: 22ch; font-size: clamp(2.1rem, 5vw, 3.6rem);
  font-weight: 800; line-height: 1.08; letter-spacing: -.015em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-gantry"] .gnt-lede {
  max-width: 60ch; margin: 1rem auto 0; color: var(--ink-soft); font-size: 1.03rem; line-height: 1.75;
}
[data-theme-layout="factory-gantry"] .gnt-cta {
  display: flex; flex-wrap: wrap; justify-content: center; gap: .7rem; margin-top: 1.7rem;
}
[data-theme-layout="factory-gantry"] .gnt-btn-ghost { border: 2px solid var(--ink); color: var(--ink); }
[data-theme-layout="factory-gantry"] .gnt-btn-ghost:hover { border-color: var(--accent); color: var(--accent); }
[data-theme-layout="factory-gantry"] div.gnt-anim { width: min(100%, 460px); margin-top: 1.8rem; }

/* 横梁铭板：f-stats 收成一条铆钉金属牌（格间分缝，去网格纹理） */
[data-theme-layout="factory-gantry"] .gnt-plate {
  width: 100%; margin-top: 2.2rem; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0; border: 2px solid var(--ink); background: var(--surface); box-shadow: var(--shadow);
}
[data-theme-layout="factory-gantry"] .gnt-plate .f-stat {
  border: 0; border-right: 1px solid var(--line); border-radius: 0;
  background-image: none; background-color: var(--surface); padding: 1.1rem 1rem .9rem;
}
[data-theme-layout="factory-gantry"] .gnt-plate .f-stat:last-child { border-right: 0; }
/* 角标改铆钉：全量重置基础角括号（含边框四向），专属车道=格子内角 */
[data-theme-layout="factory-gantry"] .gnt-plate .f-stat::before,
[data-theme-layout="factory-gantry"] .gnt-plate .f-stat::after {
  width: 7px; height: 7px; border: 2px solid var(--gnt-cable-c); border-radius: 50%;
}
[data-theme-layout="factory-gantry"] .gnt-plate .f-stat::before { top: 5px; left: 5px; }
[data-theme-layout="factory-gantry"] .gnt-plate .f-stat::after { right: 5px; bottom: 5px; }
[data-theme-layout="factory-gantry"] .gnt-plate .f-stat dt { font-size: clamp(1.4rem, 2.4vw, 2rem); }
[data-theme-layout="factory-gantry"] .gnt-certs { justify-content: center; margin-top: 1.5rem; }
/* 认证章骑在 hero 槽图遮罩上：muted 小字统一升 ink-soft（白皮 veil 上 muted 只有 4.19） */
[data-theme-layout="factory-gantry"] .gnt-stage .f-certs-label,
[data-theme-layout="factory-gantry"] .gnt-stage .f-cert i { color: var(--ink-soft); }
[data-theme-layout="factory-gantry"] .gnt-stage .f-cert { border-radius: 0; }
/* stats 未配置：factory_about 拆分块回落（居中容器里摆正回左对齐） */
[data-theme-layout="factory-gantry"] .gnt-stage .f-about {
  width: 100%; margin-top: 2.2rem; border-radius: 0; text-align: left;
}

/* ---- 区块头 ------------------------------------------------------------- */
[data-theme-layout="factory-gantry"] .gnt-sec { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-gantry"] .gnt-shead {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
  margin-bottom: 1.4rem; padding-bottom: .7rem; border-bottom: 2px solid var(--ink);
}
[data-theme-layout="factory-gantry"] .gnt-shead h2 {
  margin: 0; font-size: clamp(1.35rem, 2.4vw, 1.7rem); font-weight: 780; overflow-wrap: anywhere;
}
[data-theme-layout="factory-gantry"] .gnt-shead > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-gantry"] .gnt-shead > a:hover { color: var(--accent); }

/* ---- 流程：共享 f-process 重塑成行车轨道（轨枕纹 + 挂轨小车号牌）--------- */
[data-theme-layout="factory-gantry"] .gnt-rail-sec .f-step::before {
  top: 1.05rem; height: 8px; border-top: 2px solid var(--gnt-rail);
  background: repeating-linear-gradient(90deg, var(--gnt-rail) 0 2px, transparent 2px 10px);
}
[data-theme-layout="factory-gantry"] .gnt-rail-sec .f-step:last-child::before {
  -webkit-mask-image: linear-gradient(90deg, #000 30%, transparent);
  mask-image: linear-gradient(90deg, #000 30%, transparent);
}
[data-theme-layout="factory-gantry"] .gnt-rail-sec .f-step-num {
  padding: .12rem .6rem .1rem; border: 2px solid var(--ink);
  background: var(--gnt-beam); color: var(--gnt-beam-ink); font-size: 1.1rem;
}
[data-theme-layout="factory-gantry"] .gnt-rail-sec .f-step-title { margin-top: .8rem; }

/* ---- 商品：吊装件卡（顶部粗黄梁边 + 顶缘吊环 + 悬停起吊）----------------- */
[data-theme-layout="factory-gantry"] .gnt-grid {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.7rem .8rem;
}
[data-theme-layout="factory-gantry"] .gnt-card {
  position: relative; display: flex; min-width: 0; flex-direction: column;
  border: 1px solid var(--line); border-top: 6px solid var(--gnt-beam); border-radius: 0;
  background: var(--surface); color: var(--ink);
  transition: border-color var(--speed), transform var(--speed);
}
/* 吊环：专属车道=卡顶缘正中（行距 1.7rem 预留），绝不压别的卡 */
[data-theme-layout="factory-gantry"] .gnt-card::before {
  content: ""; position: absolute; top: -14px; left: 50%; width: 12px; height: 12px;
  margin-left: -8px; border: 2px solid var(--gnt-cable-c); border-radius: 50%;
  background: var(--bg); pointer-events: none;
}
[data-theme-layout="factory-gantry"] .gnt-card:hover {
  border-color: var(--accent); border-top-color: var(--gnt-beam);
  transform: translateY(-4px); color: var(--ink);
}
[data-theme-layout="factory-gantry"] .gnt-card-media {
  display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden;
}
[data-theme-layout="factory-gantry"] .gnt-card-media img {
  width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease;
}
[data-theme-layout="factory-gantry"] .gnt-card:hover .gnt-card-media img { transform: scale(1.03); }
[data-theme-layout="factory-gantry"] .gnt-card-gen b { font-family: var(--sans); font-size: 2.9rem; color: var(--accent); }
[data-theme-layout="factory-gantry"] .gnt-card-body {
  display: flex; flex: 1; flex-direction: column; gap: .3rem; padding: .8rem .9rem 1rem; text-align: left;
}
[data-theme-layout="factory-gantry"] .gnt-card-cat {
  width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
  color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 750;
  letter-spacing: .07em; text-transform: uppercase;
}
[data-theme-layout="factory-gantry"] .gnt-card-title { font-size: .97rem; font-weight: 720; line-height: 1.4; overflow-wrap: anywhere; }
[data-theme-layout="factory-gantry"] .gnt-card-ex {
  display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .8rem; line-height: 1.55;
  -webkit-box-orient: vertical; -webkit-line-clamp: 2;
}
[data-theme-layout="factory-gantry"] .gnt-empty { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center; }

/* ---- 分类 / 行业 / 图集 / FAQ：跟随直角钢构气质 -------------------------- */
[data-theme-layout="factory-gantry"] .gnt-wrap .f-cat-card,
[data-theme-layout="factory-gantry"] .gnt-wrap .f-cat-media,
[data-theme-layout="factory-gantry"] .gnt-wrap .f-industry,
[data-theme-layout="factory-gantry"] .gnt-wrap .f-gallery-item { border-radius: 0; }
[data-theme-layout="factory-gantry"] .gnt-wrap .f-cat-card:hover { border-top-color: var(--gnt-beam); }

/* ---- 动态：吊牌小卡（顶部细黄边）---------------------------------------- */
[data-theme-layout="factory-gantry"] .gnt-news-row {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem;
}
[data-theme-layout="factory-gantry"] .gnt-news-card {
  display: flex; min-width: 0; flex-direction: column; gap: .4rem;
  padding: .95rem 1.1rem 1.1rem; border: 1px solid var(--line);
  border-top: 4px solid var(--gnt-beam); background: var(--surface); color: var(--ink);
  transition: border-color var(--speed);
}
[data-theme-layout="factory-gantry"] .gnt-news-card:hover { border-color: var(--accent); border-top-color: var(--gnt-beam); color: var(--ink); }
[data-theme-layout="factory-gantry"] .gnt-news-card time { color: var(--muted); font-family: var(--mono); font-size: .72rem; }
[data-theme-layout="factory-gantry"] .gnt-news-title { font-weight: 700; line-height: 1.45; overflow-wrap: anywhere; }
[data-theme-layout="factory-gantry"] .gnt-news-card:hover .gnt-news-title { color: var(--accent); }
[data-theme-layout="factory-gantry"] .gnt-news-ex {
  display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .84rem; line-height: 1.6;
  -webkit-box-orient: vertical; -webkit-line-clamp: 2;
}

/* CTA 通栏（背景=ink 反色带）：共享 eyebrow 混色在三皮上不稳，统一压成 bg75%+ink
   （实算 8.96 / 7.31 / 10.72，三皮全过） */
[data-theme-layout="factory-gantry"] .f-cta .f-eyebrow { color: color-mix(in srgb, var(--bg) 75%, var(--ink)); }
[data-theme-layout="factory-gantry"] .f-cta .f-eyebrow::after { background: color-mix(in srgb, var(--bg) 45%, transparent); }

/* =========================================================================
   内页重塑（不改公共模板，只重塑既有类）
   ① 列表：.page-head → 小龙门门架；.cat-nav → 跨度牌；.link-card → 吊装件卡
   ② 详情：.pd-bc → 挂签；.pd-meta/.pd-specs-tablewrap → 吊重参数牌；
      .pd-rel-card → 吊装件卡（与 home 商品卡同语言）
   ========================================================================= */
[data-theme-layout="factory-gantry"] .page-head {
  border-inline: 8px solid var(--gnt-beam); border-bottom: 6px solid var(--gnt-beam);
  padding: 2.2rem clamp(1rem, 3vw, 2rem) 1.6rem; margin-bottom: 1.6rem;
  background: var(--surface); text-align: center;
}
[data-theme-layout="factory-gantry"] .cat-nav a { border-radius: 0; }
[data-theme-layout="factory-gantry"] .link-grid { gap: 1.7rem .8rem; }
[data-theme-layout="factory-gantry"] .link-card {
  position: relative; border-radius: 0; border-top: 5px solid var(--gnt-beam);
}
[data-theme-layout="factory-gantry"] .link-card::before {
  content: ""; position: absolute; top: -13px; left: 50%; width: 11px; height: 11px;
  margin-left: -7.5px; border: 2px solid var(--gnt-cable-c); border-radius: 50%;
  background: var(--bg); pointer-events: none;
}
[data-theme-layout="factory-gantry"] .link-card:hover {
  border-color: var(--accent); border-top-color: var(--gnt-beam);
  transform: translateY(-4px); box-shadow: none;
}
[data-theme-layout="factory-gantry"] .lc-cover { border-radius: 0; }
[data-theme-layout="factory-gantry"] .pd-bc {
  display: flex; flex-wrap: wrap; align-items: center; gap: .2rem .5rem;
  width: fit-content; max-width: 100%; margin-top: 1.1rem; padding: .5rem .85rem;
  border: 1px solid var(--line); border-top: 4px solid var(--gnt-beam);
  background: var(--surface); font-family: var(--mono); font-size: .74rem;
}
[data-theme-layout="factory-gantry"] .pd-media { border: 2px solid var(--ink); border-radius: 0; }
[data-theme-layout="factory-gantry"] .pd-thumb,
[data-theme-layout="factory-gantry"] .pd-rel-media { border-radius: 0; }
[data-theme-layout="factory-gantry"] .pd-meta {
  border: 2px solid var(--ink); border-top: 6px solid var(--gnt-beam);
  background: var(--surface); padding: .2rem 1rem;
}
[data-theme-layout="factory-gantry"] .pd-meta-row dt {
  font-family: var(--mono); font-size: .78rem; letter-spacing: .06em; text-transform: uppercase;
}
[data-theme-layout="factory-gantry"] .pd-specs-tablewrap {
  border: 2px solid var(--ink); border-top: 6px solid var(--gnt-beam); border-radius: 0;
}
[data-theme-layout="factory-gantry"] .pd-specs-table th {
  font-family: var(--mono); font-size: .8rem; letter-spacing: .05em; text-transform: uppercase;
  color: var(--ink-soft); background: var(--surface); font-weight: 700;
}
[data-theme-layout="factory-gantry"] .pd-rel-card {
  position: relative; border-radius: 0; border-top: 5px solid var(--gnt-beam);
}
[data-theme-layout="factory-gantry"] .pd-rel-grid { gap: 1.6rem .8rem; }
[data-theme-layout="factory-gantry"] .pd-rel-card::before {
  content: ""; position: absolute; top: -13px; left: 50%; width: 11px; height: 11px;
  margin-left: -7.5px; border: 2px solid var(--gnt-cable-c); border-radius: 50%;
  background: var(--bg); pointer-events: none;
}
[data-theme-layout="factory-gantry"] .pd-rel-card:hover { border-top-color: var(--gnt-beam); transform: translateY(-3px); }

/* ---- 响应式 ------------------------------------------------------------- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-gantry"] .gnt-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-gantry"] .gnt-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-gantry"] .gnt-plate { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-gantry"] .gnt-plate .f-stat { border-bottom: 1px solid var(--line); }
  [data-theme-layout="factory-gantry"] .gnt-plate .f-stat:nth-child(even) { border-right: 0; }
  [data-theme-layout="factory-gantry"] .gnt-plate .f-stat:nth-last-child(-n+2) { border-bottom: 0; }
  [data-theme-layout="factory-gantry"] .gnt-news-row { grid-template-columns: minmax(0, 1fr); }
  /* 机械动画收起（div 前缀对齐基础 div.f-heroanim 特异度）：大字陈述优先 */
  [data-theme-layout="factory-gantry"] div.gnt-anim { display: none; }
}
@media (max-width: 720px) {
  /* 立柱收细、地轨收薄；吊环缩小归位（绝对定位件全在自家车道内） */
  [data-theme-layout="factory-gantry"] .gnt-hoist { border-inline-width: 6px; }
  [data-theme-layout="factory-gantry"] .gnt-stage { border-inline-width: 6px; border-bottom-width: 6px; }
  [data-theme-layout="factory-gantry"] .page-head { border-inline-width: 5px; border-bottom-width: 4px; }
  [data-theme-layout="factory-gantry"] .gnt-grid { gap: 1.3rem .5rem; }
  [data-theme-layout="factory-gantry"] .gnt-card { border-top-width: 4px; }
  [data-theme-layout="factory-gantry"] .gnt-card::before,
  [data-theme-layout="factory-gantry"] .link-card::before,
  [data-theme-layout="factory-gantry"] .pd-rel-card::before { top: -10px; width: 9px; height: 9px; margin-left: -6.5px; }
  [data-theme-layout="factory-gantry"] .gnt-card-ex,
  [data-theme-layout="factory-gantry"] .gnt-card .f-chips { display: none; }
  [data-theme-layout="factory-gantry"] .pd-specs-table th { font-size: .74rem; }
}
@media (max-width: 620px) {
  /* 横梁收成细条（导航交还基础抽屉，.nav 绝对定位于 .gnt-header 底缘）；
     钢缆收起，铭牌与汉堡同排 */
  [data-theme-layout="factory-gantry"] .gnt-beam { min-height: 10px; border-block-width: 2px; }
  [data-theme-layout="factory-gantry"] .gnt-hoist {
    flex-direction: row; align-items: center; justify-content: space-between;
    gap: .6rem; border-inline-width: 4px; padding: .55rem .6rem;
  }
  [data-theme-layout="factory-gantry"] .gnt-hoist .gnt-cable { display: none; }
  [data-theme-layout="factory-gantry"] .gnt-nameplate { padding: .35rem .8rem .4rem; box-shadow: none; }
  [data-theme-layout="factory-gantry"] .gnt-nameplate .brand { font-size: 1.1rem; }
  [data-theme-layout="factory-gantry"] .gnt-stage { border-inline-width: 4px; }
  [data-theme-layout="factory-gantry"] .gnt-stage .gnt-cable { height: 26px; }
  [data-theme-layout="factory-gantry"] .gnt-plate { margin-top: 1.6rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-gantry"] .gnt-card,
  [data-theme-layout="factory-gantry"] .gnt-card-media img,
  [data-theme-layout="factory-gantry"] .gnt-news-card,
  [data-theme-layout="factory-gantry"] .link-card,
  [data-theme-layout="factory-gantry"] .pd-rel-card { transition: none; }
  [data-theme-layout="factory-gantry"] .gnt-card:hover,
  [data-theme-layout="factory-gantry"] .link-card:hover,
  [data-theme-layout="factory-gantry"] .pd-rel-card:hover { transform: none; }
  [data-theme-layout="factory-gantry"] .gnt-card:hover .gnt-card-media img { transform: none; }
}

/* =========================================================================
   factory-gantry 三皮（原生 gantry / 反差 beamline / 纯白 gantry-white）
   实算对比度见每皮注释；--gnt-beam 作底时字永远用 --gnt-beam-ink（实算达标），
   作块时是结构装饰件，绝不作字底以外的文字用途。
   ========================================================================= */
/* 龙门 · Gantry：浅灰工业白 + 工程黄横梁（原生皮）
   ink/bg 15.10、ink/surface 17.09、ink-soft/surface 10.65、ink-soft/veil(槽图遮罩) 8.67、
   muted/bg 5.22、muted/surface 5.91，accent 作字 4.66(bg) / 5.27(surface)，
   hover→accent-soft 6.63 / 7.50（只升不降），白字压 accent 底（btn-primary/WhatsApp）5.27，
   横梁字 #17140a 压 #d9a20b 8.00（导航/轨道小车号牌），铭板格线角铆钉为装饰件。
   CTA 反色带：bg 字压 ink 15.10、eyebrow 覆写 8.96、note 8.33。
   工程黄横梁对 bg 2.03 —— 纯结构装饰块（非文字、非控件边界），字全走 beam-ink。 */
:root[data-theme="gantry"] {
  --bg: #f1f1ee; --surface: #ffffff; --ink: #1a1c1e; --ink-soft: #3a3f43;
  --muted: #5f6569; --faint: #8f979b; --line: #d5d7d3; --line-soft: #e8e9e6;
  --accent: #8a6608; --accent-soft: #6d5006; --accent-wash: #f7edd2;
  --gnt-beam: #d9a20b; --gnt-beam-ink: #17140a;
  --w-wide: 1280px; --radius: 0px; --shadow: 0 8px 24px rgba(26,28,30,.08);
}
:root[data-theme="gantry"] .btn-primary { color: #fff; }

/* 夜吊 · Beamline：炭黑夜场 + 高亮黄横梁（反差皮）
   ink/bg 15.58、ink/surface 14.16、ink-soft/surface 10.72、ink-soft/veil 10.84、
   muted/bg 6.70、muted/surface 6.09，accent 作字 10.86(bg) / 9.87(surface)，
   hover→accent-soft 12.79 / 11.62（只升不降），深字 #14120a 压 accent/横梁底 11.44
   （btn-primary/WhatsApp/导航/号牌），横梁块对 bg 10.86（夜里亮梁）。
   CTA 反色带（暗皮翻浅底）：bg 字压 ink 15.58、eyebrow 覆写 7.31、note 6.66。 */
:root[data-theme="beamline"] {
  --bg: #16181a; --surface: #1e2124; --ink: #eef0f2; --ink-soft: #ced3d7;
  --muted: #97a0a7; --faint: #6f787f; --line: #31363b; --line-soft: #23272b;
  --accent: #f0c62a; --accent-soft: #f8d961; --accent-wash: #33290a; --code-bg: #0e1012;
  --gnt-beam: #f0c62a; --gnt-beam-ink: #14120a;
  --w-wide: 1280px; --radius: 0px; --shadow: 0 14px 40px rgba(0,0,0,.5);
}
:root[data-theme="beamline"] .btn-primary { color: #14120a; }
:root[data-theme="beamline"] .inquiry-btn.inquiry-wa { color: #14120a; }
:root[data-theme="beamline"] .f-stat dt { text-shadow: 0 0 16px rgba(240,198,42,.26); }

/* 白龙门 · Gantry-white：纯白基底（中性灰对齐纯白系）+ 压深的工程金横梁
   ink/bg 18.72、ink/surface 17.91、ink-soft/bg 9.79、ink-soft/veil 8.98，
   accent 作字 6.25(bg) / 5.98(surface)，hover→accent-soft 8.96 / 8.57（只升不降），
   白字压横梁/accent 底 6.25（导航/号牌/btn-primary），横梁块对 bg 6.25。
   CTA 反色带：bg 字压 ink 18.72、eyebrow 覆写 10.72、note 9.95。
   已知坑：muted #707680 在 surface #fafaf8 上只有 4.38 —— 凡承载 muted 文字的
   卡面/牌面全部覆写回 --bg 纯白（4.57 达标），chip 键名改 ink-soft（9.79）。 */
:root[data-theme="gantry-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #7a5c07; --accent-soft: #5d4605; --accent-wash: #f6efdc;
  --gnt-beam: #7a5c07; --gnt-beam-ink: #ffffff;
  --w-wide: 1200px; --radius: 0px; --shadow: 0 8px 24px rgba(16,18,24,.07);
}
:root[data-theme="gantry-white"] .btn-primary { color: #fff; }
:root[data-theme="gantry-white"] .gnt-card,
:root[data-theme="gantry-white"] .gnt-news-card,
:root[data-theme="gantry-white"] .gnt-nameplate,
:root[data-theme="gantry-white"] .f-stat,
:root[data-theme="gantry-white"] .f-cat-card,
:root[data-theme="gantry-white"] .f-industry,
:root[data-theme="gantry-white"] .pd-bc,
:root[data-theme="gantry-white"] .pd-meta,
:root[data-theme="gantry-white"] .pd-specs-tablewrap { background-color: var(--bg); }
:root[data-theme="gantry-white"] .gnt-plate .f-stat { background-color: var(--bg); }
:root[data-theme="gantry-white"] .f-chip { background: var(--bg); }
:root[data-theme="gantry-white"] .f-chip b { color: var(--ink-soft); }

/* =========================================================================
   LAYOUT: factory-hazardtape — 警示带（工厂族第 10 骨架）
   气质=车间安全告示：粗黑边、直角、黄黑斜纹警示带贯穿全站作为分隔语言。
   每条选择器限定 [data-theme-layout="factory-hazardtape"]，类名前缀 hzt-（全仓未占用）。
   容器规约与工厂族前辈一致：width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto。

   结构：
   - 页头：标准 .site-header 纯 CSS 重塑成「安全帽色块导航」（每项 2px 实边色块，
     当前项黄底黑字实心、悬停黑底反色）+ 页头底沿一条固定高度（10px）黄黑斜纹警示带；
     ≤620px 全部回落基础汉堡抽屉（.menu-toggle + .nav-open，绝不 :target）。
   - 首屏：.hzt-board「安全生产大牌」——左文案 / 右大数字牌（factory.stats 首项当主数字，
     其余小牌），牌内嵌合作流程作业条（factory.process），牌脚认证图章，
     牌底车间图带（factory.gallery）。stats 未配置时回落 factory_about。
   - 区块之间：.hzt-sec::before 细警示带（8px 斜纹 + 上下 2px 黑边），无额外 DOM。
   - 内页：列表=警示带分组（.cat-nav 分组条 + .link-card 顶部警示带帽），
     详情=作业规程式参数表（.pd-specs-table 工序号 counter + 等宽项目列）。

   骨架局部令牌（三张皮在文末覆写）：
     --hzt-hi     高可视填充（警示黄）；只当底色用，配 --hzt-on-hi 深字
     --hzt-dark   警示带里的暗色条
     --hzt-edge   粗边框/实心块颜色（浅皮=近黑，夜班皮=荧光黄）
     --hzt-on-hi  压在 --hzt-hi 上的文字色
     --hzt-cta-eye  CTA 反色通栏上的 eyebrow 色（通栏底是 --ink，随皮反转）
   ========================================================================= */

[data-theme-layout="factory-hazardtape"] {
  --hzt-hi: #f5c518;
  --hzt-dark: #14150f;
  --hzt-edge: #14150f;
  --hzt-on-hi: #14150f;
  --hzt-cta-eye: var(--hzt-hi);
  --hzt-bw: 3px;
  --hzt-tape: repeating-linear-gradient(-45deg, var(--hzt-hi) 0 12px, var(--hzt-dark) 12px 24px);
}
[data-theme-layout="factory-hazardtape"] body { background: var(--bg); }

/* ---------- 页头：安全帽色块导航 + 固定高度斜纹警示带 ---------- */
[data-theme-layout="factory-hazardtape"] .site-header { background: var(--surface); border-bottom: 0; -webkit-backdrop-filter: none; backdrop-filter: none; }
/* 警示带：固定 10px 斜纹 + 上沿粗边，随 sticky 页头一起吸顶 */
[data-theme-layout="factory-hazardtape"] .site-header::after { content: ""; display: block; height: 10px; border-top: var(--hzt-bw) solid var(--hzt-edge); background-image: var(--hzt-tape); }
[data-theme-layout="factory-hazardtape"] .site-header .wrap { flex-wrap: wrap; height: auto; min-height: 62px; gap: .5rem 1rem; padding-block: .5rem; }
[data-theme-layout="factory-hazardtape"] .site-header .brand { padding-bottom: .18rem; border-bottom: 3px solid var(--hzt-hi); font-family: var(--sans); font-weight: 800; letter-spacing: .05em; text-transform: uppercase; }
[data-theme-layout="factory-hazardtape"] .site-header .brand-name { font-family: var(--sans); font-weight: 800; }
[data-theme-layout="factory-hazardtape"] .nav { gap: .3rem; }
[data-theme-layout="factory-hazardtape"] .nav > a { padding: .46rem .76rem; border: 2px solid var(--hzt-edge); background: var(--surface); color: var(--ink-soft); font-family: var(--sans); font-size: .78rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; transition: background var(--speed), color var(--speed); }
[data-theme-layout="factory-hazardtape"] .nav > a[aria-current="page"]::after { content: none; }
/* 悬停=黑块反色（18.36 / 17.91 / 14.69，全部高于静息），当前项=黄底黑字实心（规格要求） */
[data-theme-layout="factory-hazardtape"] .nav > a:hover { background: var(--hzt-edge); border-color: var(--hzt-edge); color: var(--surface); }
[data-theme-layout="factory-hazardtape"] .nav > a[aria-current="page"] { background: var(--hzt-hi); border-color: var(--hzt-edge); color: var(--hzt-on-hi); }
[data-theme-layout="factory-hazardtape"] .nav .search-ico { opacity: 1; }
[data-theme-layout="factory-hazardtape"] .nav .lang-switch { margin-left: .2rem; padding-left: .6rem; border-left: 2px solid var(--line); }
[data-theme-layout="factory-hazardtape"] .nav .lang-switch > summary { color: var(--ink-soft); font-weight: 700; letter-spacing: .06em; text-transform: uppercase; }
[data-theme-layout="factory-hazardtape"] .nav .lang-switch > summary:hover,
[data-theme-layout="factory-hazardtape"] .nav .lang-switch[open] > summary { color: var(--ink); }
[data-theme-layout="factory-hazardtape"] .menu-toggle { border: 2px solid var(--hzt-edge); border-radius: 0; }
[data-theme-layout="factory-hazardtape"] .menu-toggle:hover { background: var(--hzt-hi); color: var(--hzt-on-hi); }

/* ---------- 首屏「安全生产大牌」 ---------- */
[data-theme-layout="factory-hazardtape"] .hzt-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto; padding: clamp(1.6rem, 3.4vw, 2.6rem) 0 clamp(3rem, 6vw, 4.4rem); }
[data-theme-layout="factory-hazardtape"] .hzt-board { border: var(--hzt-bw) solid var(--hzt-edge); background: var(--surface); }
[data-theme-layout="factory-hazardtape"] .hzt-board-top { display: grid; grid-template-columns: minmax(0, 1.16fr) minmax(288px, .84fr); }
[data-theme-layout="factory-hazardtape"] .hzt-copy { min-width: 0; padding: clamp(1.6rem, 3.6vw, 3rem); border-right: var(--hzt-bw) solid var(--hzt-edge); }
[data-theme-layout="factory-hazardtape"] .hzt-eyebrow { width: fit-content; margin: 0 0 1rem; padding: .26rem .6rem; background: var(--hzt-hi); color: var(--hzt-on-hi); font-family: var(--mono); font-size: .7rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; }
[data-theme-layout="factory-hazardtape"] .hzt-h1 { margin: 0; max-width: 15em; font-family: var(--sans); font-size: clamp(1.9rem, 4.4vw, 3.2rem); font-weight: 820; line-height: 1.08; letter-spacing: -.02em; text-transform: uppercase; }
/* 装饰性长文钳高：hero 描述最多 4 行，绝不把大牌撑成长条 */
[data-theme-layout="factory-hazardtape"] .hzt-lede { display: -webkit-box; overflow: hidden; max-width: 56ch; margin: .95rem 0 0; color: var(--ink-soft); font-size: 1rem; line-height: 1.7; -webkit-box-orient: vertical; -webkit-line-clamp: 4; }
[data-theme-layout="factory-hazardtape"] .hzt-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.6rem; }
[data-theme-layout="factory-hazardtape"] .hzt-cta .btn { border-width: 2px; border-color: var(--hzt-edge); border-radius: 0; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
[data-theme-layout="factory-hazardtape"] .hzt-cta .btn:hover { background: var(--hzt-edge); border-color: var(--hzt-edge); color: var(--surface); }
[data-theme-layout="factory-hazardtape"] .hzt-cta .btn-primary:hover { background: var(--hzt-hi); border-color: var(--hzt-edge); color: var(--hzt-on-hi); }

/* 大数字牌：flex 车道（绝不留空格子露底），格间 2px 缝隙由容器底色当分隔线 */
[data-theme-layout="factory-hazardtape"] .hzt-plate { display: grid; min-width: 0; }
[data-theme-layout="factory-hazardtape"] .hzt-nums { display: flex; flex-direction: column; gap: 2px; margin: 0; background: var(--hzt-edge); }
[data-theme-layout="factory-hazardtape"] .hzt-num { flex: 1 1 auto; min-width: 0; padding: 1rem 1.15rem .95rem; background: var(--surface); }
[data-theme-layout="factory-hazardtape"] .hzt-num.is-main { padding: clamp(1.3rem, 2.8vw, 2rem) 1.15rem clamp(1.1rem, 2.2vw, 1.5rem); }
[data-theme-layout="factory-hazardtape"] .hzt-num dt { margin: 0; font-family: var(--mono); font-size: clamp(1.4rem, 2.4vw, 1.9rem); font-weight: 800; line-height: 1; letter-spacing: -.02em; color: var(--ink); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
[data-theme-layout="factory-hazardtape"] .hzt-num.is-main dt { font-size: clamp(2.7rem, 6vw, 4.4rem); }
[data-theme-layout="factory-hazardtape"] .hzt-num dd { display: -webkit-box; overflow: hidden; margin: .42rem 0 0; color: var(--muted); font-size: .7rem; font-weight: 700; line-height: 1.5; letter-spacing: .14em; text-transform: uppercase; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
