[data-theme-layout="factory-hazardtape"] .pd-media, [data-theme-layout="factory-hazardtape"] .pd-thumb,
[data-theme-layout="factory-hazardtape"] .pd-rel-card { border: 2px solid var(--hzt-edge); border-radius: 0; }
