/* 小节标题拖一条警示带尾巴（自带专属车道，flex 项，绝不绝对定位散布） */
[data-theme-layout="factory-hazardtape"] .pd-sec-title { display: flex; align-items: center; gap: .8rem; font-family: var(--sans); font-weight: 800; letter-spacing: -.01em; text-transform: uppercase; }
[data-theme-layout="factory-hazardtape"] .pd-sec-title::after { content: ""; flex: 1; min-width: 24px; height: 8px; border-top: 2px solid var(--hzt-edge); border-bottom: 2px solid var(--hzt-edge); background-image: var(--hzt-tape); }
