[data-theme-layout="factory-floorplan"] .fpl-plan::before { top: 4px; left: 4px; border-top: 2px solid var(--accent); border-left: 2px solid var(--accent); }
[data-theme-layout="factory-floorplan"] .fpl-plan::after { right: 4px; bottom: 4px; border-bottom: 2px solid var(--accent); border-right: 2px solid var(--accent); }
[data-theme-layout="factory-floorplan"] .fpl-zone {
  position: relative; display: flex; min-width: 0; flex-direction: column; justify-content: flex-end;
