  background: color-mix(in srgb, var(--z, var(--accent)) 16%, var(--surface));
  border: 1px solid color-mix(in srgb, var(--z, var(--accent)) 55%, transparent);
}
[data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(5n+1) { --z: var(--fpl-z1); }
[data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(5n+2) { --z: var(--fpl-z2); }
[data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(5n+3) { --z: var(--fpl-z3); }
[data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(5n+4) { --z: var(--fpl-z4); }
[data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(5n+5) { --z: var(--fpl-z5); }
[data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(1) { grid-column: 1 / 4; grid-row: 1 / 3; }
[data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(2) { grid-column: 4 / 7; grid-row: 1 / 2; }
[data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(3) { grid-column: 4 / 6; grid-row: 2 / 3; }
[data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(4) { grid-column: 6 / 7; grid-row: 2 / 3; }
[data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(5) { grid-column: 1 / 7; grid-row: 3 / 4; }
/* 区号牌：CSS 计数器 ZONE A…（左筋吃分区色；牌面 surface 上 ink-soft 作字） */
[data-theme-layout="factory-floorplan"] .fpl-zone::before {
  counter-increment: fpl-zone; content: counter(fpl-zone, upper-alpha);
