  background: var(--surface); border-left: 3px solid var(--z, var(--accent));
  border-right: 1px solid color-mix(in srgb, var(--z, var(--accent)) 55%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--z, var(--accent)) 55%, transparent);
