  letter-spacing: .14em; line-height: 1.6; white-space: nowrap;
}
[data-theme-layout="factory-floorplan"] .fpl-zone-name {
  display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2;
