/* ---- 商品：设备位卡（顶部分区色标 + U-01 设备位号牌）--------------------- */
[data-theme-layout="factory-floorplan"] .fpl-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.2rem .8rem; counter-reset: fpl-unit; }
