[data-theme-layout="factory-floorplan"] .link-card:nth-child(5n+3) { --z: var(--fpl-z3); }
[data-theme-layout="factory-floorplan"] .link-card:nth-child(5n+4) { --z: var(--fpl-z4); }
[data-theme-layout="factory-floorplan"] .link-card:nth-child(5n+5) { --z: var(--fpl-z5); }
