}
/* 标注框：虚线框 + 左上 accent 十字钉（surface 字压 accent 底，三皮实算 ≥7.5） */
[data-theme-layout="factory-floorplan"] .pd-info { position: relative; padding: 1.15rem 1.2rem 1.3rem; border: 1px dashed var(--fpl-mark); background: var(--surface); }
[data-theme-layout="factory-floorplan"] .pd-info::before {
  content: "+"; position: absolute; top: -1px; left: -1px; display: grid; place-items: center;
  width: 22px; height: 22px; background: var(--accent); color: var(--surface);
  font-family: var(--mono); font-size: .9rem; font-weight: 800; line-height: 1;
}
[data-theme-layout="factory-floorplan"] .pd-kicker a { display: inline-flex; align-items: center; gap: .45rem; }
[data-theme-layout="factory-floorplan"] .pd-kicker a::before { content: ""; flex: none; width: 9px; height: 9px; background: var(--accent); }
[data-theme-layout="factory-floorplan"] .pd-inquiry { border-radius: 0; border-left: 4px solid var(--accent); }
[data-theme-layout="factory-floorplan"] .pd-specs-tablewrap { border-radius: 0; border-top: 2px solid var(--ink); }
[data-theme-layout="factory-floorplan"] .pd-specs-table tbody { counter-reset: fpl-spec; }
[data-theme-layout="factory-floorplan"] .pd-specs-table th { position: relative; padding-left: 3.2rem; background: var(--surface); color: var(--ink-soft); font-weight: 650; }
[data-theme-layout="factory-floorplan"] .pd-specs-table th::before {
  counter-increment: fpl-spec; content: "№ " counter(fpl-spec, decimal-leading-zero);
  position: absolute; left: .9rem; top: .68rem; color: var(--accent);
  font-family: var(--mono); font-size: .68rem; font-weight: 800;
}
[data-theme-layout="factory-floorplan"] .pd-rel-card { position: relative; border-radius: 0; padding-top: 4px; }
[data-theme-layout="factory-floorplan"] .pd-rel-card::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 4px; background: var(--z, var(--accent)); }
[data-theme-layout="factory-floorplan"] .pd-rel-card:nth-child(5n+1) { --z: var(--fpl-z1); }
[data-theme-layout="factory-floorplan"] .pd-rel-card:nth-child(5n+2) { --z: var(--fpl-z2); }
[data-theme-layout="factory-floorplan"] .pd-rel-card:nth-child(5n+3) { --z: var(--fpl-z3); }
[data-theme-layout="factory-floorplan"] .pd-rel-card:nth-child(5n+4) { --z: var(--fpl-z4); }
[data-theme-layout="factory-floorplan"] .pd-rel-card:nth-child(5n+5) { --z: var(--fpl-z5); }
[data-theme-layout="factory-floorplan"] .pd-rel-card:hover { border-color: var(--z, var(--accent)); }
[data-theme-layout="factory-floorplan"] .pd-rel-media { border-radius: 0; }

/* ---- 响应式 ------------------------------------------------------------- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-floorplan"] .fpl-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-floorplan"] .fpl-hero { grid-template-columns: minmax(0, 1fr); align-items: start; gap: 1.6rem; }
  [data-theme-layout="factory-floorplan"] .fpl-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-floorplan"] .fpl-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .6rem; }
  [data-theme-layout="factory-floorplan"] .fpl-process-sec .f-process { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 1.6rem; }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-floorplan"] .fpl-plan { grid-auto-rows: minmax(54px, auto); gap: 5px; padding: 12px; }
  /* 窄屏分区重排：横带化铺满，绝对定位牌/角标随容器归位不出框 */
  [data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(1) { grid-column: 1 / 7; grid-row: 1 / 2; }
  [data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(2) { grid-column: 1 / 4; grid-row: 2 / 3; }
  [data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(3) { grid-column: 4 / 7; grid-row: 2 / 3; }
  [data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(4) { grid-column: 1 / 3; grid-row: 3 / 4; }
  [data-theme-layout="factory-floorplan"] .fpl-zone:nth-child(5) { grid-column: 3 / 7; grid-row: 3 / 4; }
  [data-theme-layout="factory-floorplan"] .fpl-zone { padding: 1.5rem .5rem .45rem; }
  [data-theme-layout="factory-floorplan"] .fpl-zone-note { display: none; }
  [data-theme-layout="factory-floorplan"] .fpl-grid { gap: 1rem .5rem; }
  [data-theme-layout="factory-floorplan"] .fpl-card-ex,
  [data-theme-layout="factory-floorplan"] .fpl-card .f-chips { display: none; }
  [data-theme-layout="factory-floorplan"] .fpl-news-item { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="factory-floorplan"] .fpl-news-item .arrow { display: none; }
  [data-theme-layout="factory-floorplan"] .fpl-news-title { white-space: normal; }
  [data-theme-layout="factory-floorplan"] .pd-specs-table th { padding-left: 2.6rem; }
  [data-theme-layout="factory-floorplan"] .pd-specs-table th::before { left: .7rem; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-floorplan"] .fpl-process-sec .f-process { grid-template-columns: minmax(0, 1fr); gap: 1.1rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-floorplan"] .fpl-card,
  [data-theme-layout="factory-floorplan"] .fpl-card-media img,
  [data-theme-layout="factory-floorplan"] a.fpl-zone,
  [data-theme-layout="factory-floorplan"] .link-card { transition: none; }
  [data-theme-layout="factory-floorplan"] .fpl-card:hover { transform: none; }
}

/* =========================================================================
   factory-floorplan 三皮（原生 floorplan / 反差 zoning / 纯白 floorplan-white）
   实算对比度见每皮注释；--fpl-z1..z5 恒为图形件（图例块/分区染/色标条），永不作字。
   ========================================================================= */
/* 图纸 · Floorplan：浅绿灰图纸 + 制图绿 + 五色分区（原生皮）
   ink/bg 14.87、ink/surface 16.42、ink-soft/surface 9.96、muted/surface 5.87、muted/bg 5.32、
   accent 作字 7.58(surface) / 6.86(bg)，hover→accent-soft 10.19 / 9.22（只升不降），
   btn-primary 白字压 accent 底 7.87、pd-info 十字钉 surface 字压 accent 底 7.58。
   分区 16% 淡染上 ink 最低 13.53、ink-soft 8.21；规格 chip muted 压 chip 底 5.22、
   specs th ink-soft 8.94。五分区色对 surface 最低 3.37（琥珀 z3，图形件 ≥3 达标）。 */
:root[data-theme="floorplan"] {
  --bg: #eef0eb; --surface: #fafbf7; --ink: #191d18; --ink-soft: #3b423b;
  --muted: #5d645c; --faint: #8b928a; --line: #d1d6cd; --line-soft: #e3e6df;
  --accent: #1e5c43; --accent-soft: #174732; --accent-wash: #e0ece5;
  --fpl-z1: #3e8563; --fpl-z2: #4a7fae; --fpl-z3: #b1802a; --fpl-z4: #bf6b4a; --fpl-z5: #8674ad;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 8px 24px rgba(25,29,24,.08);
}
:root[data-theme="floorplan"] .btn-primary { color: #fff; }

/* 夜巡 · Zoning：深蓝灰夜车间 + 荧光薄荷 + 荧光分区（反差皮）
   ink/bg 15.83、ink/surface 14.71、ink-soft/surface 10.79、muted/surface 6.68、muted/bg 7.19、
   accent 作字 9.59(surface) / 10.32(bg)，hover→accent-soft 11.42 / 12.28（只升不降），
   深字压 accent 底 10.28（btn-primary #0a1410）、pd-info 十字钉 surface 字压 accent 底 9.59。
   荧光分区 16% 淡染上 ink 最低 10.38、ink-soft 7.62；specs th ink-soft 10.35。
   五荧光分区色对 surface 最低 6.67。CTA 通栏翻浅底（背景=ink）：共用眉标
   mix(accent 60%, bg) 只有 3.61，本皮改 #186049（6.30）。 */
:root[data-theme="zoning"] {
  --bg: #0e1216; --surface: #151a21; --ink: #e7ecf2; --ink-soft: #c4ccd7;
  --muted: #97a1ae; --faint: #6b7583; --line: #2a323e; --line-soft: #1b212a;
  --accent: #52d6a5; --accent-soft: #7ee4bd; --accent-wash: #12352a; --code-bg: #0a0d11;
  --fpl-z1: #45d6a2; --fpl-z2: #5db6f0; --fpl-z3: #e8c14b; --fpl-z4: #ef8f6a; --fpl-z5: #b48df0;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 14px 40px rgba(0,0,0,.5);
}
:root[data-theme="zoning"] .btn-primary { color: #0a1410; }
:root[data-theme="zoning"] .f-cta .f-eyebrow { color: #186049; }
:root[data-theme="zoning"] .f-stat dt { text-shadow: 0 0 16px rgba(82,214,165,.28); }

/* 白图 · Floorplan-white：纯白基底（中性灰对齐纯白系）+ 压深制图绿 + 压深五分区
   ink/bg 18.72、ink/surface 17.91、ink-soft/surface 9.37、accent 作字 8.21(bg) / 7.86(surface)，
   hover→accent-soft 10.88 / 10.41（只升不降），白字压 accent 底 8.21。
   已知坑：muted #707680 在 surface #fafaf8 上只有 4.38 —— 把所有承载 muted 文字的卡面
   （设备位卡/数字卡/行业卡/分类卡/位置卡/chip）覆写回 --bg 纯白（4.57 达标），
   chip 键名改 ink-soft（9.79）。分区 16% 淡染上 ink 14.53 / ink-soft 7.60；
   五分区色对 surface 最低 4.39（图形件）。 */
:root[data-theme="floorplan-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #1d5941; --accent-soft: #164531; --accent-wash: #e5f0ea;
  --fpl-z1: #2f7a57; --fpl-z2: #3a6f9e; --fpl-z3: #9a6d1c; --fpl-z4: #b05a38; --fpl-z5: #75619e;
  --w-wide: 1200px; --radius: 2px;
}
:root[data-theme="floorplan-white"] .btn-primary { color: #fff; }
:root[data-theme="floorplan-white"] .site-header { background: var(--bg); }
:root[data-theme="floorplan-white"] .fpl-card,
:root[data-theme="floorplan-white"] .f-stat,
:root[data-theme="floorplan-white"] .f-industry,
:root[data-theme="floorplan-white"] .f-cat-card,
:root[data-theme="floorplan-white"] .link-card { background-color: var(--bg); }
:root[data-theme="floorplan-white"] .f-chip { background: var(--bg); }
:root[data-theme="floorplan-white"] .f-chip b { color: var(--ink-soft); }

/* =========================================================================
   LAYOUT: factory-quotation — 报价单（工厂族新骨架；partial home_factory_quotation）
   每条选择器限定 [data-theme-layout="factory-quotation"]，自有类名前缀 fqt-（全仓未占用）。
   形态：整页读成一张 RFQ 报价单。
     页头 = 单据步骤导航：CSS 重塑标准 .site-header——导航项前圈号①②③
            （CSS 计数器画圆圈号，不改 DOM），当前项圈号填色（基础底部游标线隐藏，
            当前态由填色圈号承担）；整头双线压底（4px double）。
            重塑段包在 min-width:621px 内，≤620px 交还基础汉堡抽屉。
     hero  = 单头：左=标题区（眉标做成单据字段框），右=factory.stats 重塑成条款行
            （等宽小字标签 + 点线引导 + 值；未配置回落 factory_about），单头双线压底。
     商品  = 报价表：首行表头深底（ink 底 bg 字），行=编号/缩略图/品名/规格 chips/询价钮
            五列 grid；行悬停淡绿衬 + 询价钮填色；≤720px 转卡片（编号变角标）。
     流程  = 复用共享 f-process 标记，重塑成圈号条款步骤（呼应页头圈号）。
     内页  = 商品/归档列表重塑为报价表行（点线分隔 + 序号列）；
            商品详情重塑为完整报价参数表（双线压顶 + 条款序号 + 点线行）。
   ========================================================================= */
[data-theme-layout="factory-quotation"] {
  --fqt-hot: var(--accent);                                      /* 装饰绿：双线压顶/角签，恒不作字 */
  --fqt-dot: color-mix(in srgb, var(--ink) 32%, transparent);    /* 点线引导 */
}
[data-theme-layout="factory-quotation"] body { background: var(--bg); }
[data-theme-layout="factory-quotation"] .fqt-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-bottom: clamp(3rem, 6vw, 4.4rem);
}

/* ---- 页头：单据步骤导航（标准 .site-header 的 CSS 重塑，无新增 DOM）------ */
[data-theme-layout="factory-quotation"] .site-header {
  background: var(--surface); -webkit-backdrop-filter: none; backdrop-filter: none;
  border-bottom: 4px double var(--ink);
}
[data-theme-layout="factory-quotation"] .brand { font-family: var(--sans); font-weight: 760; letter-spacing: -.01em; }
@media (min-width: 621px) {
  [data-theme-layout="factory-quotation"] .site-header .wrap { height: 68px; }
  [data-theme-layout="factory-quotation"] .nav { counter-reset: fqt-step; gap: clamp(.9rem, 1.8vw, 1.5rem); }
  [data-theme-layout="factory-quotation"] .nav > a { display: inline-flex; align-items: center; gap: .45rem; font-size: .9rem; font-weight: 600; }
  /* 圈号①②③：CSS 计数器生成，搜索入口不占号 */
  [data-theme-layout="factory-quotation"] .nav > a:not(.search-ico)::before {
    counter-increment: fqt-step; content: counter(fqt-step);
    display: grid; place-items: center; width: 21px; height: 21px; flex: none;
    border: 1.5px solid var(--muted); border-radius: 50%;
    font-family: var(--mono); font-size: .64rem; font-weight: 750; line-height: 1;
    color: var(--muted); font-variant-numeric: tabular-nums;
    transition: color var(--speed), border-color var(--speed), background var(--speed);
  }
  [data-theme-layout="factory-quotation"] .nav > a:hover::before { border-color: var(--accent); color: var(--accent); }
  /* 当前项=填色圈号；基础底部游标线（bottom:-22px）隐藏，避免压双线 */
  [data-theme-layout="factory-quotation"] .nav a[aria-current="page"]::before {
    background: var(--accent); border-color: var(--accent); color: var(--surface);
  }
  [data-theme-layout="factory-quotation"] .nav a[aria-current="page"]::after { display: none; }
}

/* ---- hero：单头（标题 + 条款行）------------------------------------------ */
[data-theme-layout="factory-quotation"] .fqt-hero {
  display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(300px, .85fr);
  margin-top: clamp(1.6rem, 3.5vw, 2.6rem);
  border: 1px solid var(--line); border-bottom: 4px double var(--ink);
  background: var(--surface);
}
[data-theme-layout="factory-quotation"] .fqt-hero-copy { min-width: 0; padding: clamp(1.8rem, 4vw, 3.2rem); border-right: 1px solid var(--line); }
/* 眉标=单据字段框：描边小牌，等宽大写字距 */
[data-theme-layout="factory-quotation"] .fqt-eyebrow {
  width: fit-content; max-width: 100%; margin: 0 0 1.1rem; padding: .3rem .6rem;
  border: 1px solid var(--accent); color: var(--accent);
  font-family: var(--mono); font-size: .66rem; font-weight: 800;
  letter-spacing: .16em; text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="factory-quotation"] .fqt-h1 {
  margin: 0; max-width: 15em; font-size: clamp(1.95rem, 4.4vw, 3.1rem);
  font-weight: 790; line-height: 1.1; letter-spacing: -.015em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-quotation"] .fqt-lede { max-width: 56ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75; }
[data-theme-layout="factory-quotation"] .fqt-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="factory-quotation"] .fqt-hero-side { display: grid; align-content: center; min-width: 0; padding: clamp(1.2rem, 2.6vw, 2rem); }
/* 条款行：覆写共用数字卡→标签 + 点线引导 + 值（角标/图纸纹全量重置） */
[data-theme-layout="factory-quotation"] .fqt-terms { grid-template-columns: minmax(0, 1fr); gap: 0; }
[data-theme-layout="factory-quotation"] .fqt-terms .f-stat {
  display: flex; align-items: baseline; gap: .7rem; min-width: 0;
  padding: .72rem .1rem; border: 0; border-radius: 0; border-bottom: 1px dotted var(--fqt-dot);
  background: none;
}
[data-theme-layout="factory-quotation"] .fqt-terms .f-stat::before,
[data-theme-layout="factory-quotation"] .fqt-terms .f-stat::after { content: none; }
[data-theme-layout="factory-quotation"] .fqt-terms .f-stat:last-child { border-bottom: 0; }
[data-theme-layout="factory-quotation"] .fqt-terms .f-stat dd {
  order: 1; display: flex; flex: 1; align-items: baseline; gap: .7rem; min-width: 0;
  margin: 0; color: var(--muted); font-family: var(--mono); font-size: .66rem;
  font-weight: 700; letter-spacing: .14em; text-transform: uppercase;
}
[data-theme-layout="factory-quotation"] .fqt-terms .f-stat dd::after { content: ""; flex: 1; min-width: 1.2rem; border-bottom: 1px dotted var(--fqt-dot); }
[data-theme-layout="factory-quotation"] .fqt-terms .f-stat dt {
  order: 2; font-size: 1.05rem; letter-spacing: 0; overflow-wrap: anywhere; text-align: right;
}
[data-theme-layout="factory-quotation"] .fqt-hero-side .f-about { border: 0; border-radius: 0; padding: .4rem .2rem; background: none; }

/* ---- 区块头：双线压底延续单据语法 --------------------------------------- */
[data-theme-layout="factory-quotation"] .fqt-section { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-quotation"] .fqt-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
  margin-bottom: 1.3rem; padding-bottom: .7rem; border-bottom: 4px double var(--ink);
}
[data-theme-layout="factory-quotation"] .fqt-head h2 { margin: 0; font-size: clamp(1.35rem, 2.4vw, 1.7rem); font-weight: 780; overflow-wrap: anywhere; }
[data-theme-layout="factory-quotation"] .fqt-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-quotation"] .fqt-head > a:hover { color: var(--accent); }

/* ---- 商品：报价表（表头深底 + 五列行）----------------------------------- */
[data-theme-layout="factory-quotation"] .fqt-table { border: 1px solid var(--line); background: var(--surface); }
[data-theme-layout="factory-quotation"] .fqt-thead,
[data-theme-layout="factory-quotation"] .fqt-row {
  display: grid; grid-template-columns: 56px 88px minmax(0, 1.3fr) minmax(0, 1fr) auto;
  align-items: center; gap: 1rem;
}
[data-theme-layout="factory-quotation"] .fqt-thead {
  padding: .5rem 1rem .5rem 0; background: var(--ink); color: var(--bg);
  font-family: var(--mono); font-size: .62rem; font-weight: 750; letter-spacing: .16em; text-transform: uppercase;
}
[data-theme-layout="factory-quotation"] .fqt-thead > span:first-child { text-align: center; }
[data-theme-layout="factory-quotation"] .fqt-th-item { grid-column: 2 / 4; }
[data-theme-layout="factory-quotation"] .fqt-row {
  position: relative; padding: .7rem 1rem .7rem 0; border-bottom: 1px solid var(--line-soft);
  color: var(--ink); transition: background var(--speed);
}
[data-theme-layout="factory-quotation"] .fqt-row:last-child { border-bottom: 0; }
[data-theme-layout="factory-quotation"] .fqt-row:hover { background: color-mix(in srgb, var(--accent) 6%, transparent); color: var(--ink); }
[data-theme-layout="factory-quotation"] .fqt-no {
  align-self: stretch; display: grid; place-items: center;
  border-right: 1px dotted var(--fqt-dot); color: var(--muted);
  font-family: var(--mono); font-size: .76rem; font-weight: 700; letter-spacing: .06em; font-variant-numeric: tabular-nums;
}
[data-theme-layout="factory-quotation"] .fqt-row:hover .fqt-no { color: var(--accent); }
[data-theme-layout="factory-quotation"] .fqt-thumb {
  display: grid; place-items: center; width: 88px; aspect-ratio: 4 / 3;
  border: 1px solid var(--line); background: var(--line-soft); overflow: hidden;
}
[data-theme-layout="factory-quotation"] .fqt-thumb img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="factory-quotation"] .fqt-gen b { font-family: var(--sans); font-size: 1.7rem; color: var(--accent); }
[data-theme-layout="factory-quotation"] .fqt-item { display: flex; flex-direction: column; gap: .2rem; min-width: 0; }
[data-theme-layout="factory-quotation"] .fqt-item-cat { width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 750; letter-spacing: .07em; text-transform: uppercase; }
[data-theme-layout="factory-quotation"] .fqt-item-title { font-size: .98rem; font-weight: 720; line-height: 1.4; overflow-wrap: anywhere; }
[data-theme-layout="factory-quotation"] .fqt-item-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .8rem; line-height: 1.55; -webkit-box-orient: vertical; -webkit-line-clamp: 1; }
[data-theme-layout="factory-quotation"] .fqt-specs { min-width: 0; }
[data-theme-layout="factory-quotation"] .fqt-specs .f-chips { margin-top: 0; }
/* 询价钮：描边小牌，行悬停整钮填色（accent 底压 surface 字，对比≥表内正文） */
[data-theme-layout="factory-quotation"] .fqt-rfq {
  display: inline-flex; align-items: center; gap: .4rem; padding: .42rem .7rem;
  border: 1.5px solid var(--accent); color: var(--accent);
  font-family: var(--mono); font-size: .66rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase;
  white-space: nowrap; transition: background var(--speed), color var(--speed);
}
[data-theme-layout="factory-quotation"] .fqt-row:hover .fqt-rfq { background: var(--accent); color: var(--surface); }
[data-theme-layout="factory-quotation"] .fqt-empty { margin: 0; padding: 1.6rem; border-top: 1px dashed var(--line); text-align: center; }

/* ---- 流程：共享 f-process 重塑成圈号条款步骤（呼应页头圈号）-------------- */
[data-theme-layout="factory-quotation"] .fqt-process-sec .f-process { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.3rem; }
[data-theme-layout="factory-quotation"] .fqt-process-sec .f-step::before {
  top: 16px; height: 0; border-top: 1px dotted var(--fqt-dot); background: none;
}
[data-theme-layout="factory-quotation"] .fqt-process-sec .f-step-num {
  display: grid; place-items: center; width: 34px; height: 34px; padding: 0;
  border: 2px solid var(--accent); border-radius: 50%; background: var(--bg);
  font-size: .88rem; line-height: 1; color: var(--accent);
}
[data-theme-layout="factory-quotation"] .fqt-process-sec .f-step-title { margin-top: .75rem; }

/* ---- 分类 / 行业 / 图集：直角单据气质 ----------------------------------- */
[data-theme-layout="factory-quotation"] .fqt-wrap .f-cat-card,
[data-theme-layout="factory-quotation"] .fqt-wrap .f-industry,
[data-theme-layout="factory-quotation"] .fqt-wrap .f-gallery-item { border-radius: 0; }
[data-theme-layout="factory-quotation"] .fqt-wrap .f-cat-card:hover { transform: none; border-color: var(--accent); }
[data-theme-layout="factory-quotation"] .fqt-wrap .f-faq { border-top: 4px double var(--ink); }

/* ---- 动态：细行清单 ----------------------------------------------------- */
[data-theme-layout="factory-quotation"] .fqt-news-head { border-bottom: 1px solid var(--line); }
[data-theme-layout="factory-quotation"] .fqt-news-head h2 { font-size: 1.15rem; color: var(--ink-soft); }
[data-theme-layout="factory-quotation"] .fqt-news-item {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px dotted var(--fqt-dot); color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-quotation"] .fqt-news-item:hover { color: var(--accent); }
[data-theme-layout="factory-quotation"] .fqt-news-item time { color: var(--muted); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-quotation"] .fqt-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* =========================================================================
   内页重塑（不改公共模板，只重塑既有类）
   ① 商品/归档列表 .link-grid → 报价表行：序号列（CSS 计数器）+ 点线分隔 + 双线压顶
   ② 商品详情 .pd-* → 完整报价参数表：面包屑=单据引用条、规格表=双线压顶 + 条款序号
     + 点线行、参数标签等宽大写、询盘盒双线压顶、相关商品顶部双线签
   ========================================================================= */
[data-theme-layout="factory-quotation"] .link-grid {
  grid-template-columns: minmax(0, 1fr); gap: 0; counter-reset: fqt-lrow;
  border: 1px solid var(--line); border-top: 4px double var(--ink); background: var(--surface);
}
[data-theme-layout="factory-quotation"] .link-card {
  display: grid; grid-template-columns: 60px 108px minmax(0, 1fr); align-items: center; gap: 0 1rem;
  padding: .7rem 1rem .7rem 0; border: 0; border-bottom: 1px dotted var(--fqt-dot);
  border-radius: 0; background: transparent;
}
[data-theme-layout="factory-quotation"] .link-card:last-child { border-bottom: 0; }
[data-theme-layout="factory-quotation"] .link-card::before {
  counter-increment: fqt-lrow; content: counter(fqt-lrow, decimal-leading-zero);
  align-self: stretch; display: grid; place-items: center;
  border-right: 1px dotted var(--fqt-dot); color: var(--muted);
  font-family: var(--mono); font-size: .74rem; font-weight: 700; letter-spacing: .06em; font-variant-numeric: tabular-nums;
}
[data-theme-layout="factory-quotation"] .link-card:hover { transform: none; box-shadow: none; background: color-mix(in srgb, var(--accent) 6%, transparent); }
[data-theme-layout="factory-quotation"] .link-card:hover::before { color: var(--accent); }
[data-theme-layout="factory-quotation"] .lc-cover { border: 1px solid var(--line); border-radius: 0; }
[data-theme-layout="factory-quotation"] .lc-body { padding: 0; gap: .25rem; }
[data-theme-layout="factory-quotation"] .lc-title { font-size: 1rem; }
[data-theme-layout="factory-quotation"] .lc-intro { -webkit-line-clamp: 1; }
[data-theme-layout="factory-quotation"] .pd-bc {
  display: flex; flex-wrap: wrap; align-items: center; gap: .2rem .5rem;
  margin-top: 1.1rem; padding: .5rem .85rem; border: 1px solid var(--line);
  background: var(--surface); font-family: var(--mono); font-size: .74rem;
}
[data-theme-layout="factory-quotation"] .pd-media,
[data-theme-layout="factory-quotation"] .pd-thumb,
[data-theme-layout="factory-quotation"] .pd-inquiry,
[data-theme-layout="factory-quotation"] .pd-specs-tablewrap,
[data-theme-layout="factory-quotation"] .pd-rel-card,
[data-theme-layout="factory-quotation"] .pd-rel-media { border-radius: 0; }
[data-theme-layout="factory-quotation"] .pd-meta-row { border-bottom: 1px dotted var(--fqt-dot); }
[data-theme-layout="factory-quotation"] .pd-meta-row dt { font-family: var(--mono); font-size: .72rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; align-self: baseline; }
[data-theme-layout="factory-quotation"] .pd-inquiry { border-top: 4px double var(--fqt-hot); }
[data-theme-layout="factory-quotation"] .pd-specs-tablewrap { border-top: 4px double var(--ink); }
[data-theme-layout="factory-quotation"] .pd-specs-table tbody { counter-reset: fqt-spec; }
[data-theme-layout="factory-quotation"] .pd-specs-table th,
[data-theme-layout="factory-quotation"] .pd-specs-table td { border-bottom: 1px dotted var(--fqt-dot); }
[data-theme-layout="factory-quotation"] .pd-specs-table th {
  position: relative; padding-left: 3.2rem; background: var(--surface);
  color: var(--ink-soft); font-family: var(--mono); font-size: .78rem; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase;
}
[data-theme-layout="factory-quotation"] .pd-specs-table th::before {
  counter-increment: fqt-spec; content: counter(fqt-spec, decimal-leading-zero);
  position: absolute; left: 1rem; top: .72rem; color: var(--accent);
  font-size: .7rem; font-weight: 800;
}
[data-theme-layout="factory-quotation"] .pd-rel-card { border-top: 4px double var(--fqt-hot); }

/* ---- 响应式 ------------------------------------------------------------- */
@media (max-width: 920px) {
  [data-theme-layout="factory-quotation"] .fqt-hero { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="factory-quotation"] .fqt-hero-copy { border-right: 0; border-bottom: 1px solid var(--line); }
  [data-theme-layout="factory-quotation"] .fqt-thead,
  [data-theme-layout="factory-quotation"] .fqt-row { grid-template-columns: 48px 72px minmax(0, 1.4fr) minmax(0, 1fr) auto; gap: .8rem; }
  [data-theme-layout="factory-quotation"] .fqt-thumb { width: 72px; }
  [data-theme-layout="factory-quotation"] .fqt-process-sec .f-process { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 1.6rem; }
  [data-theme-layout="factory-quotation"] .link-card { grid-template-columns: 52px 96px minmax(0, 1fr); gap: 0 .9rem; }
}
@media (max-width: 720px) {
  /* 报价表转卡片：表头隐藏，编号变左上角标，缩略图纵贯左列 */
  [data-theme-layout="factory-quotation"] .fqt-table { display: grid; gap: .7rem; border: 0; background: none; }
  [data-theme-layout="factory-quotation"] .fqt-thead { display: none; }
  [data-theme-layout="factory-quotation"] .fqt-row {
    grid-template-columns: 96px minmax(0, 1fr); grid-auto-rows: min-content;
    align-items: start; gap: .45rem .9rem; padding: 1rem .9rem .95rem;
    border: 1px solid var(--line); background: var(--surface);
  }
  [data-theme-layout="factory-quotation"] .fqt-row:last-child { border-bottom: 1px solid var(--line); }
  [data-theme-layout="factory-quotation"] .fqt-no {
    position: absolute; top: 0; left: 0; align-self: auto; padding: .16rem .5rem;
    border-right: 0; background: var(--ink); color: var(--bg);
    font-size: .6rem; line-height: 1.6; letter-spacing: .12em;
  }
  [data-theme-layout="factory-quotation"] .fqt-thumb { grid-row: 1 / 4; width: 96px; margin-top: .5rem; }
  [data-theme-layout="factory-quotation"] .fqt-item,
  [data-theme-layout="factory-quotation"] .fqt-specs,
  [data-theme-layout="factory-quotation"] .fqt-rfq { grid-column: 2; }
  [data-theme-layout="factory-quotation"] .fqt-rfq { justify-self: start; }
  [data-theme-layout="factory-quotation"] .fqt-item-ex { display: none; }
  [data-theme-layout="factory-quotation"] .fqt-news-item { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="factory-quotation"] .fqt-news-item .arrow { display: none; }
  [data-theme-layout="factory-quotation"] .fqt-news-title { white-space: normal; }
  [data-theme-layout="factory-quotation"] .link-card { grid-template-columns: 44px 84px minmax(0, 1fr); gap: 0 .75rem; }
  [data-theme-layout="factory-quotation"] .link-card::before { font-size: .64rem; letter-spacing: .02em; }
  [data-theme-layout="factory-quotation"] .pd-specs-table th { padding-left: 2.6rem; }
  [data-theme-layout="factory-quotation"] .pd-specs-table th::before { left: .7rem; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-quotation"] .fqt-process-sec .f-process { grid-template-columns: minmax(0, 1fr); gap: 1.1rem; }
  [data-theme-layout="factory-quotation"] .fqt-row { grid-template-columns: 80px minmax(0, 1fr); }
  [data-theme-layout="factory-quotation"] .fqt-thumb { width: 80px; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-quotation"] .fqt-row,
  [data-theme-layout="factory-quotation"] .fqt-rfq,
  [data-theme-layout="factory-quotation"] .link-card,
  [data-theme-layout="factory-quotation"] .nav > a:not(.search-ico)::before { transition: none; }
}

/* =========================================================================
   factory-quotation 三皮（原生 quotation / 反差 proforma / 纯白 quotation-white）
   实算对比度见每皮注释；--fqt-hot 恒为装饰色（双线压顶/角签），永不作字。
   ========================================================================= */
/* 单据白绿 · Quotation：纸感绿白 + 单据绿（原生皮）
   ink/bg 14.75、ink/surface 16.35、ink-soft/surface 9.95、muted/surface 5.69、muted/bg 5.13、
   accent 作字 6.33(surface) / 5.72(bg)，hover→accent-soft 9.35 / 8.43（只升不降），
   表头/CTA 通栏 bg 字压 ink 底 14.75，btn-primary 白字压 accent 底 6.46，
   询价钮悬停 surface 字压 accent 底 6.33，圈号当前态 surface 字压 accent 底 6.33，
   行悬停底 #eff4f0 上 ink 14.99 / muted 5.21 / accent 5.81（全不降）。
   装饰绿 #2f9463 对 surface 3.72 / bg 3.35（非文字图形件，≥3 达标）。 */
:root[data-theme="quotation"] {
  --bg: #eef2ee; --surface: #fcfdfb; --ink: #17201b; --ink-soft: #39443d;
  --muted: #5d6861; --faint: #8c968e; --line: #cfd8d0; --line-soft: #e2e8e2;
  --accent: #1e6b47; --accent-soft: #164f34; --accent-wash: #e0efe6;
  --fqt-hot: #2f9463;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 8px 24px rgba(23,32,27,.08);
}
:root[data-theme="quotation"] .btn-primary { color: #fff; }

/* 夜单 · Proforma：深灰黑夜单 + 薄荷绿（反差皮）
   ink/bg 16.38、ink/surface 15.24、ink-soft/surface 11.22、muted/surface 6.70、muted/bg 7.20、
   accent 作字 10.35(surface) / 11.12(bg)，hover→accent-soft 12.31 / 13.23（只升不降），
   表头 bg 字压 ink 底 16.38，btn-primary 深字压薄荷底 10.59（#0b1710），
   询价钮悬停 surface 字压 accent 底 10.35，行悬停底 #19241e 上 ink 13.60 / muted 5.98。
   CTA 通栏在暗皮里翻成浅底（背景=ink），共用眉标的 mix(accent 60%, bg) 只有 3.58，
   本皮改用 #1c5c40（6.72）。 */
:root[data-theme="proforma"] {
  --bg: #0c0f0d; --surface: #141815; --ink: #e8eeea; --ink-soft: #c5cfc9;
  --muted: #95a19a; --faint: #67726b; --line: #262e29; --line-soft: #1a201c;
  --accent: #6cd9a7; --accent-soft: #97e6c2; --accent-wash: #12301f; --code-bg: #070908;
  --fqt-hot: #4ecb95;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 14px 40px rgba(0,0,0,.5);
}
:root[data-theme="proforma"] .btn-primary { color: #0b1710; }
:root[data-theme="proforma"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #0b1710; }
:root[data-theme="proforma"] .f-cta .f-eyebrow { color: #1c5c40; }

/* 白单 · Quotation-white：纯白基底（中性灰对齐纯白系）+ 压深的单据绿
   ink/bg 18.72、ink/surface 17.91、ink-soft/surface 9.37、accent 作字 7.45(bg) / 7.13(surface)，
   hover→accent-soft 11.79 / 11.28（只升不降），白字压 accent 底 7.45，
   表头 bg 字压 ink 底 18.72，装饰绿 #23815c 对 bg 4.81（≥3 达标）。
   已知坑：muted #707680 在 surface #fafaf8 上只有 4.38 —— 本皮把所有承载 muted 文字的
   单面/行面/卡面覆写回 --bg 纯白（4.57 达标），行悬停淡绿衬会把 muted 压到 4.01，
   故悬停底也覆写回 --bg、改用左缘 3px 绿签做悬停提示；规格 chip 键名改 ink-soft（9.79）。 */
:root[data-theme="quotation-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #1e6047; --accent-soft: #143f2f; --accent-wash: #e7f2ec;
  --fqt-hot: #23815c;
  --w-wide: 1200px; --radius: 2px;
}
:root[data-theme="quotation-white"] .btn-primary { color: #fff; }
:root[data-theme="quotation-white"] .site-header { background: var(--bg); }
:root[data-theme="quotation-white"] .fqt-hero,
:root[data-theme="quotation-white"] .fqt-table,
:root[data-theme="quotation-white"] .fqt-row,
:root[data-theme="quotation-white"] .link-grid,
:root[data-theme="quotation-white"] .f-stat,
:root[data-theme="quotation-white"] .f-industry,
:root[data-theme="quotation-white"] .f-cat-card { background-color: var(--bg); }
:root[data-theme="quotation-white"] .fqt-row:hover,
:root[data-theme="quotation-white"] .link-card:hover { background: var(--bg); box-shadow: inset 3px 0 0 var(--accent); }
:root[data-theme="quotation-white"] .f-chip { background: var(--bg); }
:root[data-theme="quotation-white"] .f-chip b { color: var(--ink-soft); }

/* =========================================================================
   LAYOUT: factory-tonnage — 吨位（工厂族新骨架；partial home_factory_tonnage）
   每条选择器限定 [data-theme-layout="factory-tonnage"]，自有类名前缀 ftn-（全仓未占用）。
   形态：数据融合极致——整页把「数字」当第一视觉，粗野主义钢厂气质。
     页头 = 大写宽字距粗野条：CSS 重塑标准 .site-header——4px 粗底线、品牌与导航全大写
            宽字距，当前项底部 4px 强调条；整段包在 min-width:621px 内，
            ≤620px 交还基础汉堡抽屉（不新增 header define）。
     hero  = 眉标 + 900 字重大标题 + factory.stats 数据板：首项由 :first-child 放大成
            超大数字（clamp 4.25rem→7rem、900 字重、4px 粗底线），dd 顶对齐排在数字右侧
            读成「单位小字上标」；其余项列成 2 列小吨位牌（2px 钢框、去共用图纸底纹）。
            未配置 stats 回落 factory_about。
     商品  = 牌号大卡：深底钢牌（--ftn-plate）+ 大写代号色字（标题，mono 900，--ftn-code）
            + 品名/参数 chips 反色重排；底缘 4px 熔橙条；无封面时代号大字本身即卡面。
     流程  = 复用共享 f-process 标记，编号放大成 900 字重大数字 + 3px 钢线。
     内页  = 商品/归档列表 .link-grid 重塑为「牌号网格」：深底钢牌卡，标题即大写代号色字，
            lc-mono 首字兜底转代号色；商品详情 .pd-* 重塑为「大字参数块」：
            规格表 display 网格化，每对参数一格（值=mono 900 大数字、键=小写距大写标签、
            2px 钢框 + 4px 粗底缘），主图 2px 钢框、询盘条 4px 熔橙左筋、相关商品同深底钢牌。
   ========================================================================= */
[data-theme-layout="factory-tonnage"] {
  --ftn-hot: var(--accent);                                          /* 熔橙装饰：粗条/底缘/左筋，恒不作字 */
  --ftn-plate: var(--ink);                                           /* 钢牌深底 */
  --ftn-plate-ink: var(--bg);                                        /* 钢牌主字 */
  --ftn-plate-mute: color-mix(in srgb, var(--bg) 74%, var(--ink));   /* 钢牌次要字 */
  --ftn-code: color-mix(in srgb, var(--accent) 46%, var(--bg));      /* 钢牌代号色字 */
}
[data-theme-layout="factory-tonnage"] body { background: var(--bg); }
[data-theme-layout="factory-tonnage"] .ftn-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-bottom: clamp(3rem, 6vw, 4.4rem);
}

/* ---- 页头：大写宽字距粗野条（标准 .site-header 的 CSS 重塑，无新增 DOM）------ */
[data-theme-layout="factory-tonnage"] .site-header {
  background: var(--surface); -webkit-backdrop-filter: none; backdrop-filter: none;
  border-bottom: 4px solid var(--ink);
}
[data-theme-layout="factory-tonnage"] .brand {
  font-family: var(--sans); font-size: 1.02rem; font-weight: 900;
  letter-spacing: .16em; text-transform: uppercase;
}
@media (min-width: 621px) {
  [data-theme-layout="factory-tonnage"] .site-header .wrap { height: 70px; align-items: stretch; }
  [data-theme-layout="factory-tonnage"] .brand { align-self: center; margin-right: auto; padding-right: 1rem; }
  [data-theme-layout="factory-tonnage"] .nav { align-items: stretch; gap: 0; }
  [data-theme-layout="factory-tonnage"] .nav > a {
    display: inline-flex; align-items: center; padding: 0 clamp(.55rem, 1.4vw, 1.05rem);
    font-size: .78rem; font-weight: 750; letter-spacing: .14em; text-transform: uppercase;
  }
  [data-theme-layout="factory-tonnage"] .nav > a:hover { color: var(--accent); background: color-mix(in srgb, var(--ink) 5%, transparent); }
  /* 当前项：底部 4px 强调条（基础规则是 bottom:-22px 的 2px 细线，压到条底加粗） */
  [data-theme-layout="factory-tonnage"] .nav a[aria-current="page"]::after { top: auto; bottom: 0; height: 4px; background: var(--accent); }
  [data-theme-layout="factory-tonnage"] .nav .search-ico { padding-inline: .6rem; opacity: 1; color: var(--muted); }
  [data-theme-layout="factory-tonnage"] .nav .search-ico:hover { color: var(--accent); }
}

/* ---- hero：眉标 + 900 大标题 + 数据板（首项超大数字）----------------------- */
[data-theme-layout="factory-tonnage"] .ftn-hero {
  display: grid; grid-template-columns: minmax(0, .96fr) minmax(320px, 1.04fr);
  align-items: center; gap: clamp(1.6rem, 3.4vw, 3.2rem);
  padding: clamp(2.2rem, 5vw, 3.8rem) 0 clamp(1.6rem, 3vw, 2.4rem);
}
[data-theme-layout="factory-tonnage"] .ftn-eyebrow {
  width: fit-content; max-width: 100%; margin: 0 0 1.15rem; padding: .3rem .65rem;
  background: var(--accent); color: var(--bg); font-family: var(--mono);
  font-size: .68rem; font-weight: 800; letter-spacing: .2em; text-transform: uppercase;
  overflow-wrap: anywhere;
}
[data-theme-layout="factory-tonnage"] .ftn-h1 {
  margin: 0; max-width: 14em; font-size: clamp(2rem, 4.6vw, 3.4rem);
  font-weight: 900; line-height: 1.04; letter-spacing: -.02em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-tonnage"] .ftn-lede { max-width: 54ch; margin: 1.05rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75; }
[data-theme-layout="factory-tonnage"] .ftn-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="factory-tonnage"] .ftn-hero-side { min-width: 0; }
/* 数据板：去共用图纸底纹与角标，2 列小吨位牌 */
[data-theme-layout="factory-tonnage"] .ftn-board { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .7rem; }
[data-theme-layout="factory-tonnage"] .ftn-board .f-stat { padding: .95rem 1rem .9rem; border: 2px solid var(--ink); border-radius: 0; background: var(--surface); }
[data-theme-layout="factory-tonnage"] .ftn-board .f-stat::before,
[data-theme-layout="factory-tonnage"] .ftn-board .f-stat::after { display: none; }
[data-theme-layout="factory-tonnage"] .ftn-board .f-stat dt { font-size: clamp(1.5rem, 2.2vw, 2rem); font-weight: 900; }
/* 首项=超大数字：clamp 64px+ / 900 字重，dd 顶对齐读成「单位小字上标」 */
[data-theme-layout="factory-tonnage"] .ftn-board .f-stat:first-child {
  grid-column: 1 / -1; display: flex; align-items: flex-start; gap: .65rem;
  padding: 0 0 1.05rem; border: 0; border-bottom: 4px solid var(--ink); background: transparent;
}
[data-theme-layout="factory-tonnage"] .ftn-board .f-stat:first-child dt {
  min-width: 0; font-size: clamp(4.25rem, 8.8vw, 7rem); font-weight: 900;
  line-height: .92; letter-spacing: -.035em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-tonnage"] .ftn-board .f-stat:first-child dd {
  min-width: 0; margin: .6rem 0 0; font-size: .7rem; letter-spacing: .16em;
}
[data-theme-layout="factory-tonnage"] .ftn-hero-side .f-about { border-radius: 0; }

/* ---- 区块头：4px 粗底线 + 大写重标题 ------------------------------------- */
[data-theme-layout="factory-tonnage"] .ftn-section { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-tonnage"] .ftn-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
  margin-bottom: 1.35rem; padding-bottom: .7rem; border-bottom: 4px solid var(--ink);
}
[data-theme-layout="factory-tonnage"] .ftn-head h2 {
  margin: 0; font-size: clamp(1.3rem, 2.3vw, 1.6rem); font-weight: 900;
  letter-spacing: .04em; text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="factory-tonnage"] .ftn-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-tonnage"] .ftn-head > a:hover { color: var(--accent); }

/* ---- 商品：牌号大卡（深底钢牌 + 大写代号色字 + 品名 + 参数）--------------- */
[data-theme-layout="factory-tonnage"] .ftn-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.1rem; }
[data-theme-layout="factory-tonnage"] .ftn-card {
  display: flex; min-width: 0; flex-direction: column;
  border-radius: 0; border-bottom: 4px solid var(--ftn-hot);
  background: var(--ftn-plate); color: var(--ftn-plate-ink); overflow: hidden;
  transition: transform var(--speed), box-shadow var(--speed);
}
[data-theme-layout="factory-tonnage"] .ftn-card:hover { transform: translateY(-3px); box-shadow: 0 0 0 2px var(--accent), var(--shadow); color: var(--ftn-plate-ink); }
[data-theme-layout="factory-tonnage"] .ftn-card-media {
  display: block; aspect-ratio: 16 / 7; overflow: hidden;
  background: color-mix(in srgb, var(--ftn-plate-ink) 8%, var(--ftn-plate));
}
[data-theme-layout="factory-tonnage"] .ftn-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
[data-theme-layout="factory-tonnage"] .ftn-card:hover .ftn-card-media img { transform: scale(1.03); }
[data-theme-layout="factory-tonnage"] .ftn-card-body { display: flex; flex: 1; flex-direction: column; gap: .45rem; padding: 1.05rem 1.1rem 1.15rem; }
[data-theme-layout="factory-tonnage"] .ftn-card-cat {
  width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
  color: var(--ftn-plate-mute); font-family: var(--mono); font-size: .62rem; font-weight: 750;
  letter-spacing: .18em; text-transform: uppercase;
}
[data-theme-layout="factory-tonnage"] .ftn-card-code {
  font-family: var(--mono); font-size: clamp(1.45rem, 2.4vw, 1.9rem); font-weight: 900;
  line-height: 1.05; letter-spacing: -.01em; text-transform: uppercase;
  color: var(--ftn-code); overflow-wrap: anywhere;
}
[data-theme-layout="factory-tonnage"] .ftn-card-ex { display: -webkit-box; overflow: hidden; color: var(--ftn-plate-mute); font-size: .82rem; line-height: 1.6; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="factory-tonnage"] .ftn-card .f-chips { margin-top: auto; padding-top: .55rem; }
[data-theme-layout="factory-tonnage"] .ftn-card .f-chip {
  border-color: color-mix(in srgb, var(--ftn-plate-ink) 24%, transparent);
  background: color-mix(in srgb, var(--ftn-plate-ink) 7%, transparent);
  color: var(--ftn-plate-ink);
}
[data-theme-layout="factory-tonnage"] .ftn-card .f-chip b { color: var(--ftn-plate-mute); }
[data-theme-layout="factory-tonnage"] .ftn-empty { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 2px dashed var(--line); text-align: center; }

/* ---- 流程：编号放大成 900 大数字 + 3px 钢线 ------------------------------ */
[data-theme-layout="factory-tonnage"] .ftn-process-sec .f-step::before { top: 1.15rem; height: 3px; background: var(--ink); }
[data-theme-layout="factory-tonnage"] .ftn-process-sec .f-step:last-child::before { background: linear-gradient(90deg, var(--ink) 55%, transparent); }
[data-theme-layout="factory-tonnage"] .ftn-process-sec .f-step-num { font-size: 2.6rem; font-weight: 900; letter-spacing: -.03em; }

/* ---- 分类 / 行业 / 图集：跟随直角粗野气质 -------------------------------- */
[data-theme-layout="factory-tonnage"] .ftn-wrap .f-cat-card,
[data-theme-layout="factory-tonnage"] .ftn-wrap .f-cat-media,
[data-theme-layout="factory-tonnage"] .ftn-wrap .f-industry,
[data-theme-layout="factory-tonnage"] .ftn-wrap .f-gallery-item { border-radius: 0; }
[data-theme-layout="factory-tonnage"] .ftn-wrap .f-cat-card:hover { transform: none; border-color: var(--accent); box-shadow: inset 0 -3px 0 var(--ftn-hot); }
[data-theme-layout="factory-tonnage"] .ftn-wrap .f-cat-name { font-weight: 800; }

/* ---- 动态：细行清单（mono 日期 + 单行标题）------------------------------- */
[data-theme-layout="factory-tonnage"] .ftn-news-head { border-bottom-width: 1px; border-bottom-color: var(--line); }
[data-theme-layout="factory-tonnage"] .ftn-news-head h2 { font-size: 1.1rem; color: var(--ink-soft); }
[data-theme-layout="factory-tonnage"] .ftn-news-item {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-tonnage"] .ftn-news-item:hover { color: var(--accent); }
[data-theme-layout="factory-tonnage"] .ftn-news-item time { color: var(--muted); font-family: var(--mono); font-size: .74rem; font-variant-numeric: tabular-nums; }
[data-theme-layout="factory-tonnage"] .ftn-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* =========================================================================
   内页重塑（不改公共模板，只重塑既有类）
   ① 商品/归档列表 .link-grid → 牌号网格：深底钢牌卡、标题=大写代号色字、
      lc-mono 首字兜底转代号色、tag 反色钢框、底缘 4px 熔橙条
   ② 商品详情 .pd-* → 大字参数块：规格表网格化——每对参数一格
     （值=mono 900 大数字、键=大写小标签、2px 钢框 + 4px 粗底缘），
      主图 2px 钢框、询盘 4px 熔橙左筋、相关商品同深底钢牌
   ========================================================================= */
[data-theme-layout="factory-tonnage"] .link-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }
[data-theme-layout="factory-tonnage"] .link-card {
  border: 0; border-bottom: 4px solid var(--ftn-hot); border-radius: 0;
  background: var(--ftn-plate); color: var(--ftn-plate-ink);
}
[data-theme-layout="factory-tonnage"] .link-card:hover { transform: translateY(-3px); box-shadow: 0 0 0 2px var(--accent), var(--shadow); color: var(--ftn-plate-ink); }
[data-theme-layout="factory-tonnage"] .lc-cover { background: color-mix(in srgb, var(--ftn-plate-ink) 8%, var(--ftn-plate)); }
[data-theme-layout="factory-tonnage"] .lc-mono { background: none; color: var(--ftn-code); font-family: var(--mono); font-weight: 900; }
[data-theme-layout="factory-tonnage"] .lc-title {
  font-family: var(--mono); font-size: 1.1rem; font-weight: 900; letter-spacing: -.005em;
  text-transform: uppercase; color: var(--ftn-code); overflow-wrap: anywhere;
}
[data-theme-layout="factory-tonnage"] .lc-arrow { color: var(--ftn-plate-ink); }
[data-theme-layout="factory-tonnage"] .lc-intro { color: var(--ftn-plate-mute); }
[data-theme-layout="factory-tonnage"] .link-card .tag,
[data-theme-layout="factory-tonnage"] .link-card .tag:hover {
  border-radius: 0; background: color-mix(in srgb, var(--ftn-plate-ink) 7%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ftn-plate-ink) 24%, transparent);
  color: var(--ftn-plate-mute);
}
[data-theme-layout="factory-tonnage"] .pd-bc { font-family: var(--mono); font-size: .74rem; letter-spacing: .06em; text-transform: uppercase; }
[data-theme-layout="factory-tonnage"] .pd-title { font-weight: 900; letter-spacing: -.01em; text-transform: uppercase; }
[data-theme-layout="factory-tonnage"] .pd-media { border: 2px solid var(--ink); border-radius: 0; }
[data-theme-layout="factory-tonnage"] .pd-thumb,
[data-theme-layout="factory-tonnage"] .pd-inquiry,
[data-theme-layout="factory-tonnage"] .pd-rel-media { border-radius: 0; }
[data-theme-layout="factory-tonnage"] .pd-inquiry { border-left: 4px solid var(--ftn-hot); }
[data-theme-layout="factory-tonnage"] .pd-meta { border-top: 2px solid var(--ink); }
[data-theme-layout="factory-tonnage"] .pd-meta-row dd { font-weight: 700; font-variant-numeric: tabular-nums; }
[data-theme-layout="factory-tonnage"] .pd-sec-title { font-size: 1.15rem; font-weight: 900; letter-spacing: .03em; text-transform: uppercase; }
/* 大字参数块：表格 display 网格化，一对参数一格（键值上下倒置=值大键小） */
[data-theme-layout="factory-tonnage"] .pd-specs-tablewrap { overflow: visible; border: 0; border-radius: 0; background: transparent; }
[data-theme-layout="factory-tonnage"] .pd-specs-table { display: block; }
[data-theme-layout="factory-tonnage"] .pd-specs-table tbody { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .7rem; }
[data-theme-layout="factory-tonnage"] .pd-specs-table tr {
  display: flex; flex-direction: column-reverse; gap: .3rem;
  padding: .95rem 1.05rem 1.05rem; border: 2px solid var(--ink); border-bottom-width: 4px;
  background: var(--surface);
}
[data-theme-layout="factory-tonnage"] .pd-specs-table th,
[data-theme-layout="factory-tonnage"] .pd-specs-table td { width: auto; min-width: 0; padding: 0; border: 0; background: transparent; }
[data-theme-layout="factory-tonnage"] .pd-specs-table td {
  color: var(--ink); font-family: var(--mono); font-size: clamp(1.3rem, 2.4vw, 1.85rem);
  font-weight: 900; line-height: 1.15; letter-spacing: -.02em;
  font-variant-numeric: tabular-nums; overflow-wrap: anywhere;
}
[data-theme-layout="factory-tonnage"] .pd-specs-table th {
  color: var(--ink-soft); font-size: .66rem; font-weight: 750;
  letter-spacing: .16em; text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="factory-tonnage"] .pd-rel-card {
  border: 0; border-bottom: 4px solid var(--ftn-hot); border-radius: 0;
  background: var(--ftn-plate); color: var(--ftn-plate-ink);
}
[data-theme-layout="factory-tonnage"] .pd-rel-card:hover { box-shadow: 0 0 0 2px var(--accent); color: var(--ftn-plate-ink); }
[data-theme-layout="factory-tonnage"] .pd-rel-media { background: color-mix(in srgb, var(--ftn-plate-ink) 8%, var(--ftn-plate)); }
[data-theme-layout="factory-tonnage"] .pd-rel-gen b { color: var(--ftn-code); }
[data-theme-layout="factory-tonnage"] .pd-rel-title { font-family: var(--mono); font-weight: 900; text-transform: uppercase; color: var(--ftn-code); }

/* ---- 响应式 ------------------------------------------------------------- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-tonnage"] .ftn-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-tonnage"] .ftn-hero { grid-template-columns: minmax(0, 1fr); align-items: start; gap: 1.7rem; }
  [data-theme-layout="factory-tonnage"] .link-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-tonnage"] .pd-specs-table tbody { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-tonnage"] .ftn-grid { grid-template-columns: minmax(0, 1fr); gap: .9rem; }
  [data-theme-layout="factory-tonnage"] .ftn-card-ex { display: none; }
  [data-theme-layout="factory-tonnage"] .ftn-board .f-stat:first-child dt { font-size: clamp(3.4rem, 15vw, 4.25rem); }
  [data-theme-layout="factory-tonnage"] .ftn-news-item { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="factory-tonnage"] .ftn-news-item .arrow { display: none; }
  [data-theme-layout="factory-tonnage"] .ftn-news-title { white-space: normal; }
  [data-theme-layout="factory-tonnage"] .link-grid { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="factory-tonnage"] .pd-specs-table td { font-size: clamp(1.15rem, 4vw, 1.5rem); }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-tonnage"] .ftn-board { gap: .55rem; }
  [data-theme-layout="factory-tonnage"] .pd-specs-table tbody { grid-template-columns: minmax(0, 1fr); }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-tonnage"] .ftn-card,
  [data-theme-layout="factory-tonnage"] .ftn-card-media img,
  [data-theme-layout="factory-tonnage"] .link-card { transition: none; }
  [data-theme-layout="factory-tonnage"] .ftn-card:hover,
  [data-theme-layout="factory-tonnage"] .link-card:hover { transform: none; }
  [data-theme-layout="factory-tonnage"] .ftn-card:hover .ftn-card-media img { transform: none; }
}

/* =========================================================================
   factory-tonnage 三皮（原生 tonnage / 反差 millscale / 纯白 tonnage-white）
   实算对比度见每皮注释；--ftn-hot 恒为装饰色（4px 粗条/底缘/左筋，≥3 即可），
   --ftn-code 是钢牌上的「代号色字」＝正经文字，逐皮实算 ≥4.5。
   ========================================================================= */
/* 吨位 · Tonnage：钢厂浅灰 + 熔橙（原生皮）
   ink/bg 15.57、ink/surface 17.32、ink-soft/surface 10.55、muted/surface 6.02、muted/bg 5.41、
   accent 作字 5.53(bg) / 6.15(surface)，hover→accent-soft 7.32 / 8.14（只升不降），
   眉标 bg 字压 accent 底 5.53、btn-primary #fff 压 accent 6.33；
   钢牌 plate #1b1e20 上 plate-ink 15.18 / plate-mute 7.63 / 代号字 #ff8a52 7.19。
   装饰熔橙 #c1461c 对 surface 4.91 / bg 4.42（非文字件，≥3 达标）。 */
:root[data-theme="tonnage"] {
  --bg: #eef0f1; --surface: #fbfcfc; --ink: #16181a; --ink-soft: #383e42;
  --muted: #5c6266; --faint: #8d9298; --line: #ced3d5; --line-soft: #e2e5e6;
  --accent: #a83c12; --accent-soft: #8a300d; --accent-wash: #f5e3da;
  --ftn-hot: #c1461c; --ftn-plate: #1b1e20; --ftn-plate-ink: #f2f4f4;
  --ftn-plate-mute: #a9b0b4; --ftn-code: #ff8a52;
  --w-wide: 1280px; --radius: 0px; --shadow: 0 10px 26px rgba(22,24,26,.12);
}
:root[data-theme="tonnage"] .btn-primary { color: #fff; }

/* 轧线夜 · Millscale：黑 + 橙红拣灯（反差皮）
   ink/bg 16.18、ink/surface 15.07、ink-soft/surface 10.64、muted/surface 6.16、muted/bg 6.61、
   accent 作字 6.93(bg) / 6.45(surface)，hover→accent-soft 9.44 / 8.79（只升不降），
   眉标 bg 字压 accent 底 6.93、btn-primary 深字 #1c0f08 压 accent 6.64；
   钢牌 plate #211d1a 上 plate-ink 14.75 / plate-mute 6.43 / 代号字 #ff8a55 7.18。
   CTA 通栏在暗皮里翻成浅底（背景=ink #ede9e5）：note 7.30、共用眉标
   mix(accent 60%, bg)=#984a31 得 5.18，均达标无需覆写。装饰橙 #e35a2b 对 surface 5.00。 */
:root[data-theme="millscale"] {
  --bg: #0d0c0b; --surface: #171514; --ink: #ede9e5; --ink-soft: #cbc5bf;
  --muted: #9c958e; --faint: #6e6862; --line: #2f2a26; --line-soft: #1e1b18;
  --accent: #f4744a; --accent-soft: #ff9a78; --accent-wash: #33190e; --code-bg: #080706;
  --ftn-hot: #e35a2b; --ftn-plate: #211d1a; --ftn-plate-ink: #f4f0ec;
  --ftn-plate-mute: #a89f97; --ftn-code: #ff8a55;
  --w-wide: 1280px; --radius: 0px; --shadow: 0 14px 40px rgba(0,0,0,.55);
}
:root[data-theme="millscale"] .btn-primary { color: #1c0f08; }
:root[data-theme="millscale"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #1c0f08; }
:root[data-theme="millscale"] .ftn-board .f-stat:first-child dt { text-shadow: 0 0 22px rgba(244,116,74,.30); }

/* 白吨位 · Tonnage-white：纯白基底（中性灰对齐纯白系）+ 压深熔橙
   ink/bg 18.72、ink/surface 17.91、ink-soft/surface 9.37、accent 作字 6.71(bg) / 6.42(surface)，
   hover→accent-soft 9.02 / 8.63（只升不降），眉标/btn-primary #fff 压 accent 6.71；
   钢牌 plate #14161c 上 plate-ink 18.08 / plate-mute 7.93 / 代号字 #ff8b57 7.82。
   已知坑：muted #707680 在 surface #fafaf8 上只有 4.38 —— 承载 muted 文字的卡面
  （数据板小牌 dd / 行业卡 note / 分类卡计数）覆写回 --bg 纯白（4.57 达标）；
   规格参数格的键名本骨架用 ink-soft（9.37），不踩坑。装饰熔橙 #c1461c 对 bg 5.05。 */
:root[data-theme="tonnage-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #a13a11; --accent-soft: #822d0b; --accent-wash: #f8e8e0;
  --ftn-hot: #c1461c; --ftn-plate: #14161c; --ftn-plate-ink: #ffffff;
  --ftn-plate-mute: #a7acb5; --ftn-code: #ff8b57;
  --w-wide: 1200px; --radius: 0px;
}
:root[data-theme="tonnage-white"] .btn-primary { color: #fff; }
:root[data-theme="tonnage-white"] .site-header { background: var(--bg); }
:root[data-theme="tonnage-white"] .ftn-board .f-stat,
:root[data-theme="tonnage-white"] .f-industry,
:root[data-theme="tonnage-white"] .f-cat-card { background-color: var(--bg); }

/* =========================================================================
   LAYOUT: factory-crate — 木箱（工厂族新骨架；partial home_factory_crate）
   每条选择器限定 [data-theme-layout="factory-crate"]，自有类名前缀 fcr-（全仓未占用）。
   形态：整页读成一只出口木箱。
     页头 = 唛头行导航：CSS 重塑标准 .site-header——导航项等宽大写 + ↗ 角标
            （::before + flex order 生成，不改 DOM；::after 留给当前项双细线），
            整条页头双线压底（6px double）；≤620px 交还基础汉堡抽屉。
     hero  = 大木箱面：木纹板条渐变（竖板缝 + 细横纹）+ 4px 粗木框 + 外圈 2px 复线
            + ::before 对角箱撑（5% ink，低扰动）+ ::after 右上 FRAGILE 旋转印
            （装饰专属车道：桌面由 hero-side 顶部留空 4.4rem，≤920 转由 copy 顶部
            留空 3.4rem，≤720 直接隐藏归位）；站名蚀刻（双层 text-shadow 凿刻感）；
            factory.stats 重塑成唛头数据行「标签 …… 数值」（杀掉共用数字卡的
            图纸底与角标，未配置回落 factory_about）。
     印章行 = 共享 f-certs 直接读成箱面盖章（基础样式已是斜盖双框章）。
     商品  = 箱面卡：2px 木框 + 内缩 1px 内框缝 + 左上 CTN 编号红章（模板 printf 生成）。
     流程  = 共享 f-process 重塑成盖章步骤（编号斜盖小红章 + 实线连线）。
     内页  = 商品/归档列表重塑为箱面网格（木框卡 + CSS 计数器 CTN 红章）；
            商品详情重塑为装箱单（面包屑=唛头行、主图厚木框、规格表=PACKING LIST
            表头条 + 等宽大写参数名 + 虚线行，天然承接净重/毛重/尺寸/箱规类参数）。
   无 keyframes 动画（全静态盖章/框线），reduced-motion 只需关过渡。
   ========================================================================= */
[data-theme-layout="factory-crate"] {
  --fcr-stamp: var(--accent);                                       /* 印章红：FRAGILE/CTN 章（皮肤实测覆写） */
  --fcr-face: color-mix(in srgb, var(--accent) 7%, var(--surface)); /* 箱面木色（皮肤覆写为实测值） */
  --fcr-frame: color-mix(in srgb, var(--ink) 70%, transparent);     /* 木框 */
  --fcr-seam: color-mix(in srgb, var(--ink) 13%, transparent);      /* 板缝 */
}
[data-theme-layout="factory-crate"] body { background: var(--bg); }
[data-theme-layout="factory-crate"] .fcr-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-bottom: clamp(3rem, 6vw, 4.4rem);
}

/* ---- 页头：唛头行导航（标准 .site-header 的 CSS 重塑，无新增 DOM）---------- */
[data-theme-layout="factory-crate"] .site-header {
  background: var(--surface); -webkit-backdrop-filter: none; backdrop-filter: none;
  border-bottom: 6px double var(--ink);
}
@media (min-width: 621px) {
  [data-theme-layout="factory-crate"] .site-header .wrap { height: 70px; }
  [data-theme-layout="factory-crate"] .brand {
    font-family: var(--sans); font-weight: 800; letter-spacing: .03em;
  }
  [data-theme-layout="factory-crate"] .nav { gap: clamp(.9rem, 2vw, 1.7rem); }
  [data-theme-layout="factory-crate"] .nav > a:not(.search-ico) {
    display: inline-flex; align-items: baseline; gap: .3rem;
    font-family: var(--mono); font-size: .78rem; font-weight: 700;
    letter-spacing: .14em; text-transform: uppercase;
  }
  /* 唛头角标 ↗：::before + order 排到文字后（::after 留给当前项下划双线） */
  [data-theme-layout="factory-crate"] .nav > a:not(.search-ico)::before {
    content: "↗" / ""; order: 2; font-size: .72em; color: var(--fcr-stamp);
  }
  [data-theme-layout="factory-crate"] .nav > a:not(.search-ico):hover::before { color: var(--accent-soft); }
  [data-theme-layout="factory-crate"] .nav a[aria-current="page"] { color: var(--accent); }
  /* 当前项：底部双细线（基础规则是 bottom:-22px 的 2px 实线，这里改双线贴字） */
  [data-theme-layout="factory-crate"] .nav a[aria-current="page"]::after {
    bottom: -8px; height: 6px; background: none;
    border-top: 2px solid var(--accent); border-bottom: 2px solid var(--accent);
  }
  [data-theme-layout="factory-crate"] .nav .search-ico { opacity: 1; color: var(--muted); }
  [data-theme-layout="factory-crate"] .nav .search-ico:hover { color: var(--accent); }
}

/* ---- hero：大木箱面 ------------------------------------------------------ */
[data-theme-layout="factory-crate"] .fcr-hero {
  position: relative; display: grid;
  grid-template-columns: minmax(0, 1.16fr) minmax(300px, .84fr);
  gap: clamp(1.6rem, 3.5vw, 3rem);
  margin-top: clamp(1.5rem, 3vw, 2.4rem);
  padding: clamp(1.6rem, 4vw, 3rem);
  border: 4px solid var(--fcr-frame);
  outline: 2px solid var(--fcr-frame); outline-offset: 4px;
  background-color: var(--fcr-face);
  background-image:
    repeating-linear-gradient(90deg, transparent 0 122px, var(--fcr-seam) 122px 124px),
    repeating-linear-gradient(0deg, color-mix(in srgb, var(--ink) 3%, transparent) 0 1px, transparent 1px 9px);
}
/* 对角箱撑（X 撑条，5% ink 低扰动，正文对比只降 ~0.5，见皮肤注释实测） */
[data-theme-layout="factory-crate"] .fcr-hero::before {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background:
    linear-gradient(to top right, transparent calc(50% - 20px), color-mix(in srgb, var(--ink) 5%, transparent) calc(50% - 20px) calc(50% + 20px), transparent 0),
    linear-gradient(to bottom right, transparent calc(50% - 20px), color-mix(in srgb, var(--ink) 5%, transparent) calc(50% - 20px) calc(50% + 20px), transparent 0);
}
/* FRAGILE 旋转印：纯装饰（alt 空串防读屏），右上专属车道，≤720 隐藏归位 */
[data-theme-layout="factory-crate"] .fcr-hero::after {
  content: "↑ ↑" / ""; position: absolute; top: 1.2rem; right: 1.3rem;
  padding: .34rem .8rem .3rem; border: 4px double var(--fcr-stamp);
  color: var(--fcr-stamp); transform: rotate(7deg);
  font-family: var(--mono); font-size: .82rem; font-weight: 800; letter-spacing: .3em;
  pointer-events: none; user-select: none; opacity: .92;
}
[data-theme-layout="factory-crate"] .fcr-eyebrow {
  width: fit-content; max-width: 100%; margin: 0 0 1.1rem; padding: .26rem .6rem;
  border: 2px solid var(--ink); color: var(--ink); font-family: var(--mono);
  font-size: .66rem; font-weight: 800; letter-spacing: .2em; text-transform: uppercase;
  overflow-wrap: anywhere;
}
/* 蚀刻站名：双层影（亮下缘 + 暗错位）拟凿刻，影不压字对比 */
[data-theme-layout="factory-crate"] .fcr-h1 {
  margin: 0; max-width: 14em; font-size: clamp(2rem, 4.6vw, 3.2rem);
  font-weight: 830; line-height: 1.08; letter-spacing: .015em; text-transform: uppercase;
  overflow-wrap: anywhere;
  text-shadow: 1px 1px 0 color-mix(in srgb, var(--surface) 65%, transparent),
               2px 2px 0 color-mix(in srgb, var(--ink) 20%, transparent);
}
[data-theme-layout="factory-crate"] .fcr-lede { max-width: 54ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75; }
[data-theme-layout="factory-crate"] .fcr-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="factory-crate"] .fcr-hero-side { min-width: 0; padding-top: 4.4rem; }
[data-theme-layout="factory-crate"] .fcr-hero-side .f-about { border-radius: 0; }

/* ---- 唛头数据行：共用数字卡重塑成「标签 …… 数值」行 ---------------------- */
[data-theme-layout="factory-crate"] .fcr-marks { display: block; margin: 0; border-top: 2px solid var(--fcr-frame); }
[data-theme-layout="factory-crate"] .fcr-marks > .f-stats { display: block; margin: 0; }
[data-theme-layout="factory-crate"] .fcr-marks-label {
  display: block; margin: 0; padding: .5rem .1rem .45rem;
  border-bottom: 2px solid var(--fcr-frame); color: var(--ink-soft);
  font-family: var(--mono); font-size: .62rem; font-weight: 800; letter-spacing: .3em;
}
[data-theme-layout="factory-crate"] .fcr-marks .f-stat {
  display: flex; flex-direction: row-reverse; justify-content: space-between;
  align-items: baseline; gap: 1rem; min-width: 0; padding: .6rem .1rem .55rem;
  border: 0; border-bottom: 1px solid color-mix(in srgb, var(--ink) 30%, transparent);
  border-radius: 0; background: none;
}
[data-theme-layout="factory-crate"] .fcr-marks .f-stat:last-child { border-bottom: 2px solid var(--fcr-frame); }
[data-theme-layout="factory-crate"] .fcr-marks .f-stat::before,
[data-theme-layout="factory-crate"] .fcr-marks .f-stat::after { content: none; }
[data-theme-layout="factory-crate"] .fcr-marks .f-stat dt { font-size: clamp(1.15rem, 1.9vw, 1.5rem); }
[data-theme-layout="factory-crate"] .fcr-marks .f-stat dd {
  margin: 0; min-width: 0; color: var(--ink-soft); font-family: var(--mono);
  font-size: .68rem; font-weight: 700; letter-spacing: .18em; overflow-wrap: anywhere;
}

/* ---- 印章行：认证章居中盖在箱面下 ---------------------------------------- */
[data-theme-layout="factory-crate"] .fcr-stamprow { display: flex; justify-content: center; padding: 1.2rem .2rem .2rem; }
[data-theme-layout="factory-crate"] .fcr-certs { justify-content: center; }

/* ---- 区块头：双线压底（唛头同款） ---------------------------------------- */
[data-theme-layout="factory-crate"] .fcr-section { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-crate"] .fcr-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
  margin-bottom: 1.3rem; padding-bottom: .65rem; border-bottom: 6px double var(--ink);
}
[data-theme-layout="factory-crate"] .fcr-head h2 {
  margin: 0; font-size: clamp(1.3rem, 2.4vw, 1.65rem); font-weight: 800;
  letter-spacing: .05em; text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="factory-crate"] .fcr-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-crate"] .fcr-head > a:hover { color: var(--accent); }

/* ---- 商品：箱面卡（木框 + 内框缝 + CTN 编号红章） ------------------------ */
[data-theme-layout="factory-crate"] .fcr-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.4rem 1rem; }
[data-theme-layout="factory-crate"] .fcr-card {
  position: relative; display: flex; min-width: 0; flex-direction: column;
  border: 2px solid var(--fcr-frame); border-radius: 0; background: var(--surface);
  color: var(--ink); overflow: hidden;
  transition: border-color var(--speed), transform var(--speed), box-shadow var(--speed);
}
/* 内框缝：1px 半透明内圈 = 木框双缘（盖在封面边缘上，读成箱板压条） */
[data-theme-layout="factory-crate"] .fcr-card::after {
  content: ""; position: absolute; inset: 4px; pointer-events: none;
  border: 1px solid color-mix(in srgb, var(--fcr-frame) 45%, transparent);
}
[data-theme-layout="factory-crate"] .fcr-card:hover { border-color: var(--accent); transform: translateY(-3px); box-shadow: var(--shadow); color: var(--ink); }
[data-theme-layout="factory-crate"] .fcr-card-media { position: relative; display: grid; place-items: center; aspect-ratio: 4 / 3; border-bottom: 2px solid var(--fcr-frame); background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-crate"] .fcr-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
[data-theme-layout="factory-crate"] .fcr-card:hover .fcr-card-media img { transform: scale(1.03); }
[data-theme-layout="factory-crate"] .fcr-card-gen b { font-family: var(--sans); font-size: 2.9rem; color: var(--accent); }
[data-theme-layout="factory-crate"] .fcr-card-ctn {
  position: absolute; top: 8px; left: 8px; z-index: 1; padding: .14rem .42rem;
  border: 1.5px solid var(--fcr-stamp); background: var(--surface); color: var(--fcr-stamp);
  font-family: var(--mono); font-size: .6rem; font-weight: 800; letter-spacing: .14em;
  line-height: 1.6; transform: rotate(-3deg);
}
[data-theme-layout="factory-crate"] .fcr-card-body { display: flex; flex: 1; flex-direction: column; gap: .3rem; padding: .85rem .95rem 1rem; }
[data-theme-layout="factory-crate"] .fcr-card-cat { width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 750; letter-spacing: .07em; text-transform: uppercase; }
[data-theme-layout="factory-crate"] .fcr-card-title { font-size: .97rem; font-weight: 720; line-height: 1.4; overflow-wrap: anywhere; }
[data-theme-layout="factory-crate"] .fcr-card-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .8rem; line-height: 1.55; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="factory-crate"] .fcr-empty { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center; }

/* ---- 流程：共享 f-process 重塑成盖章步骤（编号斜盖小红章） --------------- */
[data-theme-layout="factory-crate"] .fcr-process-sec .f-step::before { top: 14px; background: color-mix(in srgb, var(--ink) 26%, transparent); }
[data-theme-layout="factory-crate"] .fcr-process-sec .f-step-num {
  width: fit-content; padding: .18rem .5rem .14rem; border: 2px solid var(--fcr-stamp);
  background: var(--bg); color: var(--accent); font-size: 1rem; transform: rotate(-2.5deg);
}
[data-theme-layout="factory-crate"] .fcr-process-sec .f-step-title { margin-top: .7rem; }

/* ---- 分类 / 行业 / 图集：直角木器化 -------------------------------------- */
[data-theme-layout="factory-crate"] .fcr-wrap .f-cat-card,
[data-theme-layout="factory-crate"] .fcr-wrap .f-cat-media,
[data-theme-layout="factory-crate"] .fcr-wrap .f-industry,
[data-theme-layout="factory-crate"] .fcr-wrap .f-gallery-item { border-radius: 0; }
[data-theme-layout="factory-crate"] .fcr-wrap .f-cat-card:hover { transform: none; }

/* ---- 动态：细行清单 ------------------------------------------------------ */
[data-theme-layout="factory-crate"] .fcr-news-head { border-bottom: 1px solid var(--line); }
[data-theme-layout="factory-crate"] .fcr-news-head h2 { font-size: 1.12rem; color: var(--ink-soft); }
[data-theme-layout="factory-crate"] .fcr-news-item {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-crate"] .fcr-news-item:hover { color: var(--accent); }
[data-theme-layout="factory-crate"] .fcr-news-item time { color: var(--muted); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-crate"] .fcr-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* =========================================================================
   内页重塑（不改公共模板，只重塑既有类）
   ① 商品/归档列表 .link-grid → 箱面网格：木框卡 + 左上 CTN 红章（CSS 计数器）
   ② 商品详情 .pd-* → 装箱单：面包屑=唛头行、主图厚木框、规格表=PACKING LIST
      表头条 + 等宽大写参数名 + 虚线行（净重/毛重/尺寸/箱规类参数天然成装箱单）
   ========================================================================= */
[data-theme-layout="factory-crate"] .link-grid { counter-reset: fcr-ctn; gap: 1.2rem; }
[data-theme-layout="factory-crate"] .link-card {
  position: relative; counter-increment: fcr-ctn;
  border: 2px solid var(--fcr-frame); border-radius: 0; background: var(--surface);
}
[data-theme-layout="factory-crate"] .link-card::after {
  content: "№ " counter(fcr-ctn, decimal-leading-zero);
  position: absolute; top: 8px; left: 8px; z-index: 1; padding: .14rem .42rem;
  border: 1.5px solid var(--fcr-stamp); background: var(--surface); color: var(--fcr-stamp);
  font-family: var(--mono); font-size: .6rem; font-weight: 800; letter-spacing: .14em;
  line-height: 1.6; transform: rotate(-3deg); pointer-events: none;
}
[data-theme-layout="factory-crate"] .link-card:hover { border-color: var(--accent); }
[data-theme-layout="factory-crate"] .lc-cover { border-bottom: 2px solid var(--fcr-frame); border-radius: 0; }
[data-theme-layout="factory-crate"] .pd-bc {
  margin-top: 1.1rem; padding: .5rem .1rem; border-bottom: 6px double var(--fcr-frame);
  font-family: var(--mono); font-size: .74rem; letter-spacing: .06em; text-transform: uppercase;
}
[data-theme-layout="factory-crate"] .pd-media,
[data-theme-layout="factory-crate"] .pd-thumb,
[data-theme-layout="factory-crate"] .pd-inquiry,
[data-theme-layout="factory-crate"] .pd-specs-tablewrap,
[data-theme-layout="factory-crate"] .pd-rel-card,
[data-theme-layout="factory-crate"] .pd-rel-media { border-radius: 0; }
[data-theme-layout="factory-crate"] .pd-media { border: 3px solid var(--fcr-frame); }
[data-theme-layout="factory-crate"] .pd-thumb { border-color: var(--fcr-frame); }
[data-theme-layout="factory-crate"] .pd-meta { border-top: 2px solid var(--fcr-frame); }
[data-theme-layout="factory-crate"] .pd-meta-row { border-bottom: 1px dashed var(--line); }
[data-theme-layout="factory-crate"] .pd-meta-row dt { font-family: var(--mono); font-size: .78rem; letter-spacing: .1em; text-transform: uppercase; }
[data-theme-layout="factory-crate"] .pd-inquiry { border: 2px solid var(--fcr-frame); }
[data-theme-layout="factory-crate"] .pd-specs-tablewrap { border: 2px solid var(--fcr-frame); }
[data-theme-layout="factory-crate"] .pd-specs-table th {
  background: var(--surface); color: var(--ink-soft);
  font-family: var(--mono); font-size: .76rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
}
[data-theme-layout="factory-crate"] .pd-specs-table th,
[data-theme-layout="factory-crate"] .pd-specs-table td { border-bottom: 1px dashed var(--line); }
[data-theme-layout="factory-crate"] .pd-specs-table td { font-variant-numeric: tabular-nums; }
[data-theme-layout="factory-crate"] .pd-rel-card { border: 2px solid var(--fcr-frame); }

/* ---- 响应式 -------------------------------------------------------------- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-crate"] .fcr-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-crate"] .fcr-hero { grid-template-columns: minmax(0, 1fr); gap: 1.6rem; }
  /* 车道换手：印章改压 copy 顶部空档，side 不再留空 */
  [data-theme-layout="factory-crate"] .fcr-hero-copy { padding-top: 3.4rem; }
  [data-theme-layout="factory-crate"] .fcr-hero-side { padding-top: 0; }
  [data-theme-layout="factory-crate"] .fcr-hero::after { top: 1rem; right: 1rem; font-size: .72rem; }
  [data-theme-layout="factory-crate"] .fcr-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-crate"] .fcr-process-sec .f-process { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 1.6rem; }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-crate"] .fcr-hero { padding: 1.2rem; outline-offset: 3px; }
  [data-theme-layout="factory-crate"] .fcr-hero::after { display: none; }
  [data-theme-layout="factory-crate"] .fcr-hero-copy { padding-top: 0; }
  [data-theme-layout="factory-crate"] .fcr-grid { gap: 1rem .6rem; }
  [data-theme-layout="factory-crate"] .fcr-card-ex,
  [data-theme-layout="factory-crate"] .fcr-card .f-chips { display: none; }
  [data-theme-layout="factory-crate"] .fcr-news-item { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="factory-crate"] .fcr-news-item .arrow { display: none; }
  [data-theme-layout="factory-crate"] .fcr-news-title { white-space: normal; }
  [data-theme-layout="factory-crate"] .pd-bc { border-bottom-width: 4px; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-crate"] .fcr-process-sec .f-process { grid-template-columns: minmax(0, 1fr); gap: 1.1rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-crate"] .fcr-card,
  [data-theme-layout="factory-crate"] .fcr-card-media img,
  [data-theme-layout="factory-crate"] .link-card { transition: none; }
  [data-theme-layout="factory-crate"] .fcr-card:hover { transform: none; }
  [data-theme-layout="factory-crate"] .fcr-card:hover .fcr-card-media img { transform: none; }
}

/* =========================================================================
   factory-crate 三皮（原生 crate / 反差 stencil / 纯白 crate-white）
   实算对比度见每皮注释；--fcr-stamp 作字（CTN 章/FRAGILE 印）全皮 ≥4.5。
   ========================================================================= */
/* 出口木黄 · Crate：胶合板暖黄 + 烙印红（原生皮）
   ink/bg 14.07、ink/surface 15.60、ink/箱面 12.76、ink-soft/surface 9.21、
   ink-soft/箱面 7.53（hero lede/唛头标签）、muted/surface 5.82、muted/bg 5.24、
   accent 作字 6.69(surface) / 6.03(bg) / 5.47(箱面)，hover→accent-soft 8.82 / 7.95（只升），
   印章红 #a63c12 作字 5.94(surface=CTN 章底) / 4.86(箱面=FRAGILE)，
   白字压 accent 底 7.22（btn-primary），CTA 眉标 mix(accent60,bg)=#bb8060 压 ink 底 5.11，
   注文 mix(bg72,ink)=#b8b0a0 压 ink 7.82，规格 chip 面 #efe8d7 上 muted 5.14 / ink-soft 8.14。
   对角箱撑/木纹 3~5% ink 低扰动：箱面正文最坏仍 >12。 */
:root[data-theme="crate"] {
  --bg: #f2ead9; --surface: #faf6ec; --ink: #241c0e; --ink-soft: #4a4230;
  --muted: #6a5f49; --faint: #988c72; --line: #d8cdb4; --line-soft: #e8dfc9;
  --accent: #97390f; --accent-soft: #7a2d0a; --accent-wash: #f3e0d2;
  --fcr-stamp: #a63c12; --fcr-face: #ecdfc4;
  --w-wide: 1280px; --radius: 0px; --shadow: 0 10px 26px rgba(36,28,14,.14);
}
:root[data-theme="crate"] .btn-primary { color: #fff; }

/* 夜运 · Stencil：深棕黑车皮 + 米黄喷印（反差皮）
   ink/bg 14.72、ink/surface 13.70、ink/箱面 12.95、ink-soft/surface 10.08、ink-soft/箱面 9.52、
   muted/surface 6.03、muted/bg 6.48、accent(米黄) 作字 9.61(surface) / 10.32(bg) / 9.08(箱面)，
   hover→accent-soft 11.91 / 12.79（只升），喷印章 #e2b45c 9.17(surface) / 8.67(箱面)，
   深字压 accent 底 10.12（btn-primary #191204），CTA 通栏翻浅底（背景=ink 米黄）：
   深字压底 14.72、注文 mix(bg72,ink)=#514b3f 6.72；共用眉标 mix(accent60,bg) 只 3.38 →
   本皮改 #6a582f（5.35）。规格 chip 面 #211c12 上 muted 5.79 / ink-soft 9.68。
   基础 .lc-mono 渐变尾 #7a6b4b 压深字只 3.57 → 本皮改 accent→#b3924e 渐变（深字最坏 6.32）。 */
:root[data-theme="stencil"] {
  --bg: #14100a; --surface: #1d1810; --ink: #ede2c8; --ink-soft: #cfc3a4;
  --muted: #a2967a; --faint: #6f6650; --line: #3a3222; --line-soft: #241f14;
  --accent: #d9bc7c; --accent-soft: #e9d29e; --accent-wash: #33290f; --code-bg: #0b0906;
  --fcr-stamp: #e2b45c; --fcr-face: #241d12;
  --w-wide: 1280px; --radius: 0px; --shadow: 0 14px 40px rgba(0,0,0,.55);
}
:root[data-theme="stencil"] .btn-primary { color: #191204; }
:root[data-theme="stencil"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #191204; }
:root[data-theme="stencil"] .f-cta .f-eyebrow { color: #6a582f; }
:root[data-theme="stencil"] .lc-mono { background: linear-gradient(135deg, var(--accent), #b3924e); color: #191204; }
:root[data-theme="stencil"] .f-stat dt { text-shadow: 0 0 16px rgba(217,188,124,.24); }

/* 白箱 · Crate-white：纯白基底（中性灰对齐纯白系）+ 压深木章红
   ink/bg 18.72、ink/surface 17.91、ink-soft/surface 9.37 / 9.79(bg)、
   accent 作字 6.66(bg) / 6.38(surface)，hover→accent-soft 8.83 / 8.45（只升），
   章红 #b0421a 5.77(bg) / 5.52(surface)，白字压 accent 底 6.66，
   CTA 眉标 mix=#c68a72 压 ink 6.49、注文 mix(bg72,ink)=#bcbdbe 9.95。
   已知坑：muted #707680 在 surface #fafaf8 仅 4.38 —— 承载 muted 文字的卡面
   （箱面卡/行业卡/link-card）覆写回 --bg 纯白（4.57 达标）；规格 chip 面 mix 后
   只 4.23 → chip 底改纯白 + 键名改 ink-soft（9.79）。本皮箱面=纯白 #ffffff（muted 4.57）。 */
:root[data-theme="crate-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #a03c14; --accent-soft: #82300d; --accent-wash: #f7e7dd;
  --fcr-stamp: #b0421a; --fcr-face: #ffffff;
  --w-wide: 1200px; --radius: 0px;
}
:root[data-theme="crate-white"] .btn-primary { color: #fff; }
:root[data-theme="crate-white"] .site-header { background: var(--bg); }
:root[data-theme="crate-white"] .fcr-card,
:root[data-theme="crate-white"] .f-industry,
:root[data-theme="crate-white"] .f-cat-card,
:root[data-theme="crate-white"] .link-card { background-color: var(--bg); }
:root[data-theme="crate-white"] .fcr-card-ctn,
:root[data-theme="crate-white"] .link-card::after { background: var(--bg); }
:root[data-theme="crate-white"] .f-chip { background: var(--bg); }
:root[data-theme="crate-white"] .f-chip b { color: var(--ink-soft); }

/* =========================================================================
   LAYOUT: factory-certwall — 认证墙（工厂族新骨架；partial home_factory_certwall）
   每条选择器限定 [data-theme-layout="factory-certwall"]，自有类名前缀 fcw-（全仓未占用）。
   形态：整页读成一面挂满资质的墙。
     页头 = 资质页签导航：CSS 重塑标准 .site-header——导航项做成坐在 2px 底线上的
            档案页签（顶圆角 + 铆钉小环 ::before），当前项顶缘 accent 粗线（把基础
            aria-current 的 bottom:-22px 下划线改挂到页签顶缘）；
            整段包在 min-width:621px 内，≤620px 交还基础汉堡抽屉。
     hero  = 认证徽章环绕：共享 f-stats 重塑成居中一排双线圆徽（外圈 2px accent +
            内圈 1px --fcw-ring，dt 大数字居中、dd 标签钳两行防撑破圆），
            首尾两枚下沉微转成环拱（装饰位移，720px 归位 2×2）；
            下接居中大标题 + 一句话；未配置 stats 回落 factory_about（居中限宽）。
     商品  = 资料卡：双线框（border + outline，格距已为 outline 让出车道）+
            封面角落纯装饰圆环（挂在 overflow:hidden 的 media 专属车道里）
            + productChips 重塑中性规格小标签行（双线小框 + accent 键名）。
     流程  = 共享 f-process 的编号重塑成双线圆徽节点。
     内页  = ① 列表 .cat-nav → 按认证筛选条（accent 左筋单据条 + 铆钉环页签，
              active 翻 accent 底；count 的 .68 透明度在 accent 底上不达标，覆写 .9）；
            ② 商品/归档列表 .link-card → 资料卡同款双线框 + 封面装饰圆环；
            ③ 商品详情 .pd-specs 表 → 逐项规格块（tbody 转栅格，每行规格=一张
              双线参数卡：环形记号 + 大写键名 + 值），面包屑/询盘条加 accent 左筋。
   ========================================================================= */
[data-theme-layout="factory-certwall"] {
  --fcw-ring: color-mix(in srgb, var(--accent) 55%, transparent);      /* 双线内圈：纯装饰不作字 */
  --fcw-ring-soft: color-mix(in srgb, var(--accent) 28%, transparent); /* 外光圈/描边淡档 */
}
[data-theme-layout="factory-certwall"] body { background: var(--bg); }
[data-theme-layout="factory-certwall"] .fcw-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-bottom: clamp(3rem, 6vw, 4.4rem);
}

/* ---- 页头：资质页签导航（标准 .site-header 的 CSS 重塑，无新增 DOM）-------- */
[data-theme-layout="factory-certwall"] .site-header {
  background: var(--surface); -webkit-backdrop-filter: none; backdrop-filter: none;
  border-bottom: 2px solid var(--ink);
}
@media (min-width: 621px) {
  [data-theme-layout="factory-certwall"] .site-header .wrap { height: 72px; align-items: stretch; }
  [data-theme-layout="factory-certwall"] .brand { align-self: center; }
  [data-theme-layout="factory-certwall"] .nav { align-items: flex-end; gap: .4rem; }
  /* 档案页签：顶圆角小卡坐在底线上，铆钉小环开头 */
  [data-theme-layout="factory-certwall"] .nav > a:not(.search-ico):not(.btn) {
    display: inline-flex; align-items: center; gap: .45rem;
    padding: .58rem .8rem .66rem; border: 1px solid var(--line); border-bottom: 0;
    border-radius: 5px 5px 0 0; background: var(--bg);
    font-size: .86rem; font-weight: 650; overflow-wrap: anywhere;
  }
  [data-theme-layout="factory-certwall"] .nav > a:not(.search-ico):not(.btn)::before {
    content: ""; flex: none; width: 9px; height: 9px;
    border: 2px solid var(--faint); border-radius: 50%;
  }
  [data-theme-layout="factory-certwall"] .nav > a:not(.search-ico):not(.btn):hover { background: var(--accent-wash); color: var(--accent); }
  [data-theme-layout="factory-certwall"] .nav > a:not(.search-ico):not(.btn):hover::before { border-color: var(--accent); }
  [data-theme-layout="factory-certwall"] .nav a[aria-current="page"] { border-color: var(--ink); background: var(--surface); color: var(--ink); }
  [data-theme-layout="factory-certwall"] .nav a[aria-current="page"]::before { border-color: var(--accent); }
  /* 当前项强调线：基础规则挂在 bottom:-22px，这里改挂页签顶缘 */
  [data-theme-layout="factory-certwall"] .nav a[aria-current="page"]::after { top: -1px; bottom: auto; left: -1px; right: -1px; height: 3px; background: var(--accent); }
  [data-theme-layout="factory-certwall"] .nav .search-ico,
  [data-theme-layout="factory-certwall"] .nav .lang-switch { align-self: center; }
  [data-theme-layout="factory-certwall"] .nav .search-ico { margin-left: .35rem; opacity: 1; color: var(--muted); }
  [data-theme-layout="factory-certwall"] .nav .search-ico:hover { color: var(--accent); }
}

/* ---- hero：真实认证槽徽章环绕 + 中性工厂指标 + 居中大标题 ---------------- */
[data-theme-layout="factory-certwall"] .fcw-hero {
  padding: clamp(2.2rem, 5vw, 3.4rem) 0 clamp(1.2rem, 2.6vw, 1.8rem);
  text-align: center;
}
/* 双线圆徽排：只消费 factory.certifications；空槽不生成任何资质。 */
[data-theme-layout="factory-certwall"] .fcw-seals {
  display: flex; flex-wrap: wrap; justify-content: center;
  gap: clamp(.9rem, 2.4vw, 1.7rem); padding-bottom: 10px; /* 首尾下沉 16px 的落位车道 */
}
[data-theme-layout="factory-certwall"] .fcw-seals .f-stat {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  width: clamp(120px, 13vw, 150px); aspect-ratio: 1; padding: 1rem; text-align: center;
  border: 2px solid var(--accent); border-radius: 50%;
  background-color: var(--surface); background-image: none;
}
/* 内圈：基础角标 ::before 全量重置成第二道细圈（双线徽） */
[data-theme-layout="factory-certwall"] .fcw-seals .f-stat::before {
  top: 5px; left: 5px; right: 5px; bottom: 5px; width: auto; height: auto;
  border: 1px solid var(--fcw-ring); border-radius: 50%;
}
[data-theme-layout="factory-certwall"] .fcw-seals .f-stat::after { content: none; }
[data-theme-layout="factory-certwall"] .fcw-seals .f-stat dt {
  display: -webkit-box; overflow: hidden; max-width: 92%;
  font-size: clamp(.82rem, 1.45vw, 1.12rem); line-height: 1.25;
  overflow-wrap: anywhere; -webkit-box-orient: vertical; -webkit-line-clamp: 3;
}
/* 装饰长文钳高：长标签截两行，绝不撑破圆徽 */
[data-theme-layout="factory-certwall"] .fcw-seals .f-stat dd {
  display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2;
  margin-top: .25rem; max-width: 92%; font-size: .56rem; letter-spacing: .09em; line-height: 1.45;
}
/* 环拱：首尾两枚下沉微转（纯装饰位移，720px 归位） */
[data-theme-layout="factory-certwall"] .fcw-seals .f-stat:first-child { transform: translateY(16px) rotate(-4deg); }
[data-theme-layout="factory-certwall"] .fcw-seals .f-stat:last-child { transform: translateY(16px) rotate(4deg); }
[data-theme-layout="factory-certwall"] .fcw-hero-copy { max-width: 60rem; margin: clamp(1.5rem, 3vw, 2.1rem) auto 0; }
/* 眉标：双线小牌（accent 作字，实算达标；外圈纯装饰） */
[data-theme-layout="factory-certwall"] .fcw-eyebrow {
  width: fit-content; max-width: 100%; margin: 0 auto .95rem; padding: .28rem .66rem;
  border: 1px solid var(--accent); outline: 1px solid var(--fcw-ring-soft); outline-offset: 2px;
  border-radius: 3px; color: var(--accent); font-family: var(--mono);
  font-size: .68rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase;
  overflow-wrap: anywhere;
}
[data-theme-layout="factory-certwall"] .fcw-h1 {
  margin: 0 auto; max-width: 17em; font-size: clamp(2rem, 4.6vw, 3.2rem);
  font-weight: 790; line-height: 1.1; letter-spacing: -.015em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-certwall"] .fcw-lede { max-width: 58ch; margin: 1rem auto 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75; }
[data-theme-layout="factory-certwall"] .fcw-cta { display: flex; flex-wrap: wrap; justify-content: center; gap: .7rem; margin-top: 1.6rem; }
[data-theme-layout="factory-certwall"] .fcw-metrics {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: .75rem; max-width: 62rem; margin: 1.9rem auto 0;
  text-align: left;
}
[data-theme-layout="factory-certwall"] .fcw-hero-about { max-width: 56rem; margin: 1.9rem auto 0; text-align: left; }

/* ---- 区块头：双线横规（档案柜隔断） ------------------------------------- */
[data-theme-layout="factory-certwall"] .fcw-section { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-certwall"] .fcw-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
  margin-bottom: 1.35rem; padding-bottom: .65rem; border-bottom: 4px double var(--ink);
}
[data-theme-layout="factory-certwall"] .fcw-head h2 { margin: 0; font-size: clamp(1.35rem, 2.4vw, 1.7rem); font-weight: 780; overflow-wrap: anywhere; }
[data-theme-layout="factory-certwall"] .fcw-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-certwall"] .fcw-head > a:hover { color: var(--accent); }

/* ---- 商品：资料卡（双线框 + 封面装饰圆环 + 中性规格标签）---------------- */
[data-theme-layout="factory-certwall"] .fcw-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.5rem 1.1rem; } /* 格距为 outline 车道让出 8px+ */
[data-theme-layout="factory-certwall"] .fcw-card {
  display: flex; min-width: 0; flex-direction: column;
  border: 1px solid var(--line); outline: 1px solid var(--line); outline-offset: 3px;
  border-radius: 3px; background: var(--surface); color: var(--ink); overflow: hidden;
  transition: border-color var(--speed), outline-color var(--speed), transform var(--speed);
}
[data-theme-layout="factory-certwall"] .fcw-card:hover { border-color: var(--accent); outline-color: var(--fcw-ring); transform: translateY(-3px); color: var(--ink); }
[data-theme-layout="factory-certwall"] .fcw-card-media { position: relative; display: grid; place-items: center; aspect-ratio: 4 / 3; border-bottom: 1px solid var(--line); background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-certwall"] .fcw-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
[data-theme-layout="factory-certwall"] .fcw-card:hover .fcw-card-media img { transform: scale(1.03); }
[data-theme-layout="factory-certwall"] .fcw-card-gen b { font-family: var(--sans); font-size: 2.9rem; color: var(--accent); }
/* 无语义装饰圆环：不暗示商品通过认证，挂在 media 车道右上角，720px 照常在位 */
[data-theme-layout="factory-certwall"] .fcw-card-media::after {
  content: ""; position: absolute; top: .5rem; right: .5rem; display: block;
  width: 26px; height: 26px; border: 2px solid var(--accent); border-radius: 50%;
  background: color-mix(in srgb, var(--surface) 84%, transparent);
  box-shadow: 0 0 0 1px var(--surface), 0 0 0 3px var(--fcw-ring);
}
[data-theme-layout="factory-certwall"] .fcw-card-body { display: flex; flex: 1; flex-direction: column; gap: .3rem; padding: .85rem .95rem 1rem; }
[data-theme-layout="factory-certwall"] .fcw-card-cat { width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 750; letter-spacing: .07em; text-transform: uppercase; }
[data-theme-layout="factory-certwall"] .fcw-card-title { font-size: .97rem; font-weight: 720; line-height: 1.4; overflow-wrap: anywhere; }
[data-theme-layout="factory-certwall"] .fcw-card-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .8rem; line-height: 1.55; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
/* 中性规格标签行：chips 双线小框化，键名 accent 大写（实算达标） */
[data-theme-layout="factory-certwall"] .fcw-card .f-chips { gap: .5rem; padding-top: .15rem; }
[data-theme-layout="factory-certwall"] .fcw-card .f-chip {
  margin: 2px; border: 1px solid color-mix(in srgb, var(--ink) 40%, transparent);
  outline: 1px solid color-mix(in srgb, var(--ink) 22%, transparent); outline-offset: 2px;
  border-radius: 2px; background: var(--surface);
}
[data-theme-layout="factory-certwall"] .fcw-card .f-chip b { color: var(--accent); text-transform: uppercase; }
[data-theme-layout="factory-certwall"] .fcw-empty { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center; }

/* ---- 流程：编号重塑成双线圆徽节点 --------------------------------------- */
[data-theme-layout="factory-certwall"] .fcw-process-sec .f-step::before { top: 19px; }
[data-theme-layout="factory-certwall"] .fcw-process-sec .f-step-num {
  display: grid; place-items: center; width: 38px; height: 38px; padding: 0;
  border: 2px solid var(--accent); border-radius: 50%; background: var(--bg);
  outline: 1px solid var(--fcw-ring); outline-offset: 2px;
  font-size: .92rem; line-height: 1; color: var(--accent);
}
[data-theme-layout="factory-certwall"] .fcw-process-sec .f-step-title { margin-top: .75rem; }

/* ---- 动态：细行清单 ----------------------------------------------------- */
[data-theme-layout="factory-certwall"] .fcw-news-head { border-bottom: 1px solid var(--line); }
[data-theme-layout="factory-certwall"] .fcw-news-head h2 { font-size: 1.15rem; color: var(--ink-soft); }
[data-theme-layout="factory-certwall"] .fcw-news-item {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-certwall"] .fcw-news-item:hover { color: var(--accent); }
[data-theme-layout="factory-certwall"] .fcw-news-item time { color: var(--muted); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-certwall"] .fcw-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* =========================================================================
   内页重塑（不改公共模板，只重塑既有类）
   ① 列表 .cat-nav → 按认证筛选条：accent 左筋单据条 + 铆钉环页签，active 翻 accent 底
   ② 商品/归档列表 .link-card → 资料卡：双线框 + 封面装饰圆环
   ③ 商品详情 .pd-* → 面包屑/询盘条 accent 左筋；规格表 → 逐项参数块（每规格一卡）
   ========================================================================= */
[data-theme-layout="factory-certwall"] .cat-nav {
  display: flex; flex-wrap: wrap; gap: .5rem .65rem; margin: 1.4rem 0; padding: .8rem .85rem;
  border: 1px solid var(--line); border-left: 4px solid var(--accent); border-radius: 3px; background: var(--surface);
}
[data-theme-layout="factory-certwall"] .cat-nav a {
  display: inline-flex; align-items: center; gap: .45rem; padding: .4rem .8rem;
  border: 1px solid var(--line); border-radius: 3px; background: var(--bg); color: var(--ink-soft);
  font-family: var(--mono); font-size: .8rem; font-weight: 650; letter-spacing: .03em; text-transform: uppercase;
}
[data-theme-layout="factory-certwall"] .cat-nav a::before { content: ""; flex: none; width: 8px; height: 8px; border: 2px solid var(--faint); border-radius: 50%; }
[data-theme-layout="factory-certwall"] .cat-nav a:hover { border-color: var(--accent); color: var(--accent); }
[data-theme-layout="factory-certwall"] .cat-nav a:hover::before { border-color: var(--accent); }
[data-theme-layout="factory-certwall"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: var(--bg); }
[data-theme-layout="factory-certwall"] .cat-nav a.active::before { border-color: currentColor; }
/* 基础 .68 透明度的计数在 accent 底上只剩 3.7~4.3，抬到 .9（实算 5.1/8.5/6.1） */
[data-theme-layout="factory-certwall"] .cat-nav a.active .muted { opacity: .9; }
[data-theme-layout="factory-certwall"] .link-grid { gap: 1.2rem; } /* 双线框 outline 车道 */
[data-theme-layout="factory-certwall"] .link-card {
  border: 1px solid var(--line); outline: 1px solid var(--line); outline-offset: 3px;
  border-radius: 3px; background: var(--surface);
}
[data-theme-layout="factory-certwall"] .link-card:hover { border-color: var(--accent); outline-color: var(--fcw-ring); transform: translateY(-3px); box-shadow: none; }
[data-theme-layout="factory-certwall"] .lc-cover { position: relative; }
[data-theme-layout="factory-certwall"] .lc-cover::after {
  content: ""; position: absolute; top: .5rem; right: .5rem; display: block;
  width: 24px; height: 24px; border: 2px solid var(--accent); border-radius: 50%;
  background: color-mix(in srgb, var(--surface) 84%, transparent);
  box-shadow: 0 0 0 1px var(--surface), 0 0 0 3px var(--fcw-ring);
}
[data-theme-layout="factory-certwall"] .pd-bc {
  display: flex; flex-wrap: wrap; align-items: center; gap: .2rem .5rem;
  margin-top: 1.1rem; padding: .5rem .85rem; border: 1px solid var(--line);
  border-left: 4px solid var(--accent); border-radius: 3px; background: var(--surface);
  font-family: var(--mono); font-size: .74rem;
}
[data-theme-layout="factory-certwall"] .pd-media,
[data-theme-layout="factory-certwall"] .pd-thumb,
[data-theme-layout="factory-certwall"] .pd-rel-media { border-radius: 3px; }
[data-theme-layout="factory-certwall"] .pd-thumb.is-active { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent), 0 0 0 4px var(--fcw-ring-soft); }
[data-theme-layout="factory-certwall"] .pd-inquiry { border-left: 4px solid var(--accent); }
/* 规格表 → 逐项参数块：tbody 转两列栅格，每行规格=一张双线参数卡 */
[data-theme-layout="factory-certwall"] .pd-specs-tablewrap { overflow: visible; border: 0; border-radius: 0; background: none; }
[data-theme-layout="factory-certwall"] .pd-specs-table { display: block; }
[data-theme-layout="factory-certwall"] .pd-specs-table tbody { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .95rem; }
[data-theme-layout="factory-certwall"] .pd-specs-table tr {
  display: flex; flex-direction: column; gap: .35rem; padding: .95rem 1.05rem .9rem;
  border: 1px solid var(--line); outline: 1px solid var(--line-soft); outline-offset: 3px;
  border-radius: 3px; background: var(--surface);
}
[data-theme-layout="factory-certwall"] .pd-specs-table th,
[data-theme-layout="factory-certwall"] .pd-specs-table td { display: block; width: auto; min-width: 0; padding: 0; border: 0; background: none; }
[data-theme-layout="factory-certwall"] .pd-specs-table th {
  display: flex; align-items: center; gap: .5rem; color: var(--ink-soft);
  font-family: var(--mono); font-size: .72rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
}
[data-theme-layout="factory-certwall"] .pd-specs-table th::before { content: ""; flex: none; width: 9px; height: 9px; border: 2px solid var(--accent); border-radius: 50%; }
[data-theme-layout="factory-certwall"] .pd-specs-table td { color: var(--ink); font-size: .95rem; font-weight: 620; overflow-wrap: anywhere; }
[data-theme-layout="factory-certwall"] .pd-rel-card { border: 1px solid var(--line); outline: 1px solid var(--line-soft); outline-offset: 3px; border-radius: 3px; }
[data-theme-layout="factory-certwall"] .pd-rel-grid { gap: 1.2rem; }
[data-theme-layout="factory-certwall"] .pd-rel-card:hover { border-color: var(--accent); outline-color: var(--fcw-ring); }

/* ---- 响应式 ------------------------------------------------------------- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-certwall"] .fcw-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-certwall"] .fcw-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-certwall"] .fcw-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-certwall"] .fcw-seals { gap: .9rem; }
  [data-theme-layout="factory-certwall"] .fcw-seals .f-stat { width: clamp(112px, 15vw, 132px); }
}
@media (max-width: 720px) {
  /* 环拱归位：位移/旋转清零，圆徽收 2×2 栅格 */
  [data-theme-layout="factory-certwall"] .fcw-seals { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); justify-items: center; gap: .8rem; padding-bottom: 0; }
  [data-theme-layout="factory-certwall"] .fcw-seals .f-stat:first-child,
  [data-theme-layout="factory-certwall"] .fcw-seals .f-stat:last-child { transform: none; }
  [data-theme-layout="factory-certwall"] .fcw-seals .f-stat { width: min(100%, 138px); }
  [data-theme-layout="factory-certwall"] .fcw-grid { gap: 1.1rem .8rem; }
  [data-theme-layout="factory-certwall"] .fcw-card-ex,
  [data-theme-layout="factory-certwall"] .fcw-card .f-chips { display: none; }
  [data-theme-layout="factory-certwall"] .fcw-news-item { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="factory-certwall"] .fcw-news-item .arrow { display: none; }
  [data-theme-layout="factory-certwall"] .fcw-news-title { white-space: normal; }
  [data-theme-layout="factory-certwall"] .pd-specs-table tbody { grid-template-columns: minmax(0, 1fr); }
  [data-theme-layout="factory-certwall"] .cat-nav { padding: .65rem .7rem; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-certwall"] .fcw-hero { padding-top: 1.6rem; }
  [data-theme-layout="factory-certwall"] .fcw-hero-copy { margin-top: 1.3rem; }
  [data-theme-layout="factory-certwall"] .fcw-metrics { grid-template-columns: minmax(0, 1fr); }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-certwall"] .fcw-card,
  [data-theme-layout="factory-certwall"] .fcw-card-media img,
  [data-theme-layout="factory-certwall"] .link-card { transition: none; }
  [data-theme-layout="factory-certwall"] .fcw-card:hover,
  [data-theme-layout="factory-certwall"] .link-card:hover { transform: none; }
}

/* =========================================================================
   factory-certwall 三皮（原生 certwall / 反差 attest / 纯白 certwall-white）
   实算对比度见每皮注释；--fcw-ring / --fcw-ring-soft 恒为装饰圈，永不作字。
   ========================================================================= */
/* 医械蓝白 · Certwall：诊室蓝白 + 械字号钴蓝（原生皮）
   ink/bg 14.36、ink/surface 15.72、ink-soft/surface 9.02、muted/surface 5.55、muted/bg 5.07、
   accent 作字 6.54(surface) / 5.97(bg)，hover→accent-soft 8.97 / 8.20（只升不降），
   白字压 accent 底 6.67（btn-primary）、装饰圆环 accent 边线清晰可见、
   筛选条 active bg 字压 accent 底 5.97（count .9 透明度实算 5.1）、
   页签悬停 accent 字压 wash 底 5.60、CTA 带 bg 字压 ink 底 14.36 / note 8.07 / 眉标 5.34。 */
:root[data-theme="certwall"] {
  --bg: #eef3f7; --surface: #fbfdfe; --ink: #13232f; --ink-soft: #354a5b;
  --muted: #57697a; --faint: #8b9aa8; --line: #ccd8e2; --line-soft: #dfe8ef;
  --accent: #0e5f9e; --accent-soft: #0a4a7e; --accent-wash: #e0edf7;
  --w-wide: 1280px; --radius: 4px; --shadow: 0 8px 24px rgba(19,35,47,.08);
}
:root[data-theme="certwall"] .btn-primary { color: #fff; }

/* 夜审 · Attest：深蓝黑档案室 + 冰蓝徽（反差皮）
   ink/bg 16.20、ink/surface 14.85、ink-soft/surface 11.37、muted/surface 7.08、muted/bg 7.72、
   accent 作字 9.14(surface) / 9.97(bg)，hover→accent-soft 11.39 / 12.42（只升不降），
   深字压冰蓝底 9.54（btn-primary #0a1721）、装饰圆环 accent 边线清晰可见、
   筛选条 active bg 字压 accent 底 9.97（count .9 实算 8.5）、页签悬停 accent/wash 7.53。
   CTA 通栏在暗皮里翻成浅底（背景=ink #e7eef5）：共用眉标 mix(accent 60%, bg) 只有 3.81，
   本皮改用 #2e5a85（6.15）；note 实算 7.09。 */
:root[data-theme="attest"] {
  --bg: #0a111a; --surface: #101b27; --ink: #e7eef5; --ink-soft: #c4d3e0;
  --muted: #93a8bb; --faint: #647a8c; --line: #24384b; --line-soft: #182636;
  --accent: #8ac2ef; --accent-soft: #aed6f7; --accent-wash: #132c42; --code-bg: #070c12;
  --w-wide: 1280px; --radius: 4px; --shadow: 0 14px 40px rgba(0,0,0,.5);
}
:root[data-theme="attest"] .btn-primary { color: #0a1721; }
:root[data-theme="attest"] .f-cta .f-eyebrow { color: #2e5a85; }
:root[data-theme="attest"] .f-stat dt { text-shadow: 0 0 16px rgba(138,194,239,.3); }

/* 白档案 · Certwall-white：纯白基底（中性灰对齐纯白系）+ 压深的械字号蓝
   ink/bg 18.72、ink/surface 17.91、ink-soft/surface 9.37、accent 作字 7.16(bg) / 6.85(surface)，
   hover→accent-soft 9.96 / 9.53（只升不降），白字压 accent 底 7.16、装饰圆环边线清晰可见、
   筛选条 active bg 字压 accent 底 7.16（count .9 实算 6.1）、页签悬停 accent/wash 6.17、
   CTA 带 18.72 / note 9.95 / 眉标 6.46。
   已知坑：muted #707680 在 surface #fafaf8 上只有 4.38 —— 本皮把所有承载 muted 文字的
   卡面（圆徽/合规卡/行业卡/分类卡/规格卡/关于块）覆写回 --bg 纯白（4.57 达标），
   chips 键名走 accent（7.16）不受累。 */
:root[data-theme="certwall-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #175a95; --accent-soft: #114570; --accent-wash: #e7eff7;
  --w-wide: 1200px; --radius: 4px;
}
:root[data-theme="certwall-white"] .btn-primary { color: #fff; }
:root[data-theme="certwall-white"] .site-header { background: var(--bg); }
:root[data-theme="certwall-white"] .fcw-card,
:root[data-theme="certwall-white"] .f-stat,
:root[data-theme="certwall-white"] .f-industry,
:root[data-theme="certwall-white"] .f-cat-card,
:root[data-theme="certwall-white"] .f-about,
:root[data-theme="certwall-white"] .pd-specs-table tr { background-color: var(--bg); }
:root[data-theme="certwall-white"] .f-chip { background: var(--bg); }

/* =========================================================================
   LAYOUT: factory-pipeworks — 管廊（工厂族新骨架；partial home_factory_pipeworks）
   每条选择器限定 [data-theme-layout="factory-pipeworks"]，自有类名前缀 ppw-（全仓未占用）。
   形态：整页读成一套厂区管路系统。
     页头 = 阀门圆点导航：CSS 重塑标准 .site-header——导航项前加空心阀轮 ◎（纯 CSS 圆环，
            当前项填实成 ◉），页头底缘接一条「总管」横条：金属渐变（ink/surface 三段混色）
            + 两个 accent 阀门方块，全部用 ::after 的多层 background 画成，零新增 DOM、
            零绝对定位；≤620px 圆点收起，交还基础汉堡抽屉。
     hero  = 大标题 + factory.stats 表压读数胶囊（999px 圆角描边 + 内圈阴影拟表盘；
            未配置回落 factory_about）。
     商品  = 管段卡：大圆角（18px 管口）+ 媒体区 DN 序号牌 + 底部「口径行」
            （productChips 重塑：虚线上边 + 胶囊 chip）。
     流程  = 复用共享 f-process 标记，重塑成管线流程：连线加粗成金属管段（8px 纵向渐变），
            步骤号变法兰接头（实线圆 + 外圈虚线螺栓圈）。
     内页  = 商品/归档列表重塑为口径分组行：单列管段行卡 + 左侧 DN 序号胶囊（CSS 计数器）；
            商品详情重塑为管路参数 + 介质表：面包屑=管路路径胶囊条、缩略图=圆形表盘、
            规格表=介质表（表头行前阀轮圈 + surface 表头底）、参数行 dt 等宽大写。
   动画：全骨架零 keyframes（管路是静止结构件），reduced-motion 下再关掉 transition。
   ========================================================================= */
[data-theme-layout="factory-pipeworks"] {
  --ppw-hot: var(--accent);                                          /* 装饰青：阀门方块/法兰圈描边，恒不作字 */
  --ppw-steel-hi: color-mix(in srgb, var(--ink) 8%, var(--surface)); /* 金属管高光 */
  --ppw-steel-mid: color-mix(in srgb, var(--ink) 26%, var(--surface));/* 金属管中调 */
  --ppw-steel-lo: color-mix(in srgb, var(--ink) 12%, var(--surface)); /* 金属管反光 */
  --ppw-ring: color-mix(in srgb, var(--ink) 34%, transparent);       /* 法兰/胶囊描边 */
}
[data-theme-layout="factory-pipeworks"] body { background: var(--bg); }
[data-theme-layout="factory-pipeworks"] .ppw-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-bottom: clamp(3rem, 6vw, 4.4rem);
}

/* ---- 页头：阀门圆点导航 + 总管横条（标准 .site-header 的 CSS 重塑，无新增 DOM）---- */
[data-theme-layout="factory-pipeworks"] .site-header {
  background: var(--surface); -webkit-backdrop-filter: none; backdrop-filter: none;
  border-bottom: 0;
}
/* 总管：::after 常规流铺满一条（自带车道，不绝对定位）；
   三层 background = 两个阀门方块（accent）+ 纵向金属渐变管身 */
[data-theme-layout="factory-pipeworks"] .site-header::after {
  content: ""; display: block; height: 16px;
  border-block: 1px solid var(--ppw-ring);
  background-image:
    linear-gradient(var(--ppw-hot) 0 0),
    linear-gradient(var(--ppw-hot) 0 0),
    linear-gradient(180deg, var(--ppw-steel-hi), var(--ppw-steel-mid) 55%, var(--ppw-steel-lo));
  background-repeat: no-repeat;
  background-size: 30px 100%, 30px 100%, 100% 100%;
  background-position: 16% 0, 84% 0, 0 0;
}
@media (min-width: 621px) {
  [data-theme-layout="factory-pipeworks"] .site-header .wrap { height: 68px; }
  [data-theme-layout="factory-pipeworks"] .brand { font-family: var(--sans); font-weight: 760; letter-spacing: -.01em; }
  [data-theme-layout="factory-pipeworks"] .nav { gap: 1.35rem; }
  [data-theme-layout="factory-pipeworks"] .nav > a:not(.search-ico) {
    display: inline-flex; align-items: center; gap: .42rem;
    font-size: .92rem; font-weight: 620;
  }
  /* 阀轮 ◎：空心圆环，hover 描边转 accent，当前项填实成 ◉ */
  [data-theme-layout="factory-pipeworks"] .nav > a:not(.search-ico)::before {
    content: ""; flex: none; width: 9px; height: 9px;
    border: 2px solid var(--muted); border-radius: 50%; background: transparent;
    transition: border-color var(--speed), background var(--speed);
  }
  [data-theme-layout="factory-pipeworks"] .nav > a:not(.search-ico):hover::before { border-color: var(--accent); }
  [data-theme-layout="factory-pipeworks"] .nav a[aria-current="page"] { color: var(--ink); }
  [data-theme-layout="factory-pipeworks"] .nav a[aria-current="page"]::before { border-color: var(--accent); background: var(--accent); }
  /* 基础规则的 bottom:-22px 细下划线取消——当前态由实心阀轮承担 */
  [data-theme-layout="factory-pipeworks"] .nav a[aria-current="page"]::after { display: none; }
  [data-theme-layout="factory-pipeworks"] .nav .search-ico { opacity: 1; color: var(--muted); }
  [data-theme-layout="factory-pipeworks"] .nav .search-ico:hover { color: var(--accent); }
}

/* ---- hero：大标题 + 表压读数胶囊 ---------------------------------------- */
[data-theme-layout="factory-pipeworks"] .ppw-hero {
  display: grid; grid-template-columns: minmax(0, 1.12fr) minmax(280px, .88fr);
  align-items: center; gap: clamp(1.4rem, 3vw, 2.8rem);
  padding: clamp(2rem, 4.5vw, 3.4rem) 0 clamp(1.6rem, 3vw, 2.2rem);
}
[data-theme-layout="factory-pipeworks"] .ppw-eyebrow {
  display: inline-flex; align-items: center; gap: .45rem; width: fit-content; max-width: 100%;
  margin: 0 0 1.1rem; padding: .3rem .8rem;
  border: 2px solid var(--accent); border-radius: 999px; color: var(--accent);
  font-family: var(--mono); font-size: .68rem; font-weight: 800; letter-spacing: .14em;
  text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="factory-pipeworks"] .ppw-eyebrow::before {
  content: ""; flex: none; width: 8px; height: 8px;
  border: 2px solid var(--accent); border-radius: 50%;
}
[data-theme-layout="factory-pipeworks"] .ppw-h1 {
  margin: 0; max-width: 15em; font-size: clamp(2rem, 4.6vw, 3.3rem);
  font-weight: 790; line-height: 1.08; letter-spacing: -.015em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-pipeworks"] .ppw-lede { max-width: 56ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75; }
[data-theme-layout="factory-pipeworks"] .ppw-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="factory-pipeworks"] .ppw-hero-side { min-width: 0; }
/* 表压读数胶囊：999px 描边 + 内圈阴影拟表盘玻璃；共用数字卡的图纸网格底与
   角标 ::before/::after（corner 括角）全量关掉 */
[data-theme-layout="factory-pipeworks"] .ppw-gauges { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .75rem; }
[data-theme-layout="factory-pipeworks"] .ppw-gauges .f-stat {
  padding: 1.05rem 1.3rem 1rem; border: 2px solid var(--ppw-ring); border-radius: 999px;
  background-image: none; text-align: center;
  box-shadow: inset 0 0 0 4px color-mix(in srgb, var(--ink) 5%, transparent);
}
[data-theme-layout="factory-pipeworks"] .ppw-gauges .f-stat::before,
[data-theme-layout="factory-pipeworks"] .ppw-gauges .f-stat::after { content: none; }
[data-theme-layout="factory-pipeworks"] .ppw-gauges .f-stat dt { font-size: clamp(1.35rem, 2.2vw, 1.85rem); }
[data-theme-layout="factory-pipeworks"] .ppw-gauges .f-stat dd { letter-spacing: .1em; }
[data-theme-layout="factory-pipeworks"] .ppw-hero-side .f-about { border-radius: 18px; }

/* ---- 区块头：底缘「支管」横条（accent 阀段 + 金属渐变，元素内自有车道）---- */
[data-theme-layout="factory-pipeworks"] .ppw-section { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-pipeworks"] .ppw-head {
  position: relative; display: flex; align-items: flex-end; justify-content: space-between;
  gap: 1rem; margin-bottom: 1.3rem; padding-bottom: 1rem;
}
[data-theme-layout="factory-pipeworks"] .ppw-head::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 6px;
  border-radius: 3px;
  background-image:
    linear-gradient(var(--ppw-hot) 0 0),
    linear-gradient(180deg, var(--ppw-steel-hi), var(--ppw-steel-mid) 60%, var(--ppw-steel-lo));
  background-repeat: no-repeat;
  background-size: 74px 100%, 100% 100%;
}
[data-theme-layout="factory-pipeworks"] .ppw-head h2 { margin: 0; font-size: clamp(1.35rem, 2.4vw, 1.7rem); font-weight: 780; overflow-wrap: anywhere; }
[data-theme-layout="factory-pipeworks"] .ppw-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-pipeworks"] .ppw-head > a:hover { color: var(--accent); }

/* ---- 商品：管段卡（大圆角管口 + DN 序号牌 + 口径行）--------------------- */
[data-theme-layout="factory-pipeworks"] .ppw-pipes { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.2rem .9rem; }
[data-theme-layout="factory-pipeworks"] .ppw-pipe {
  display: flex; min-width: 0; flex-direction: column;
  border: 1.5px solid var(--line); border-radius: 18px; background: var(--surface); color: var(--ink);
  overflow: hidden; transition: border-color var(--speed), transform var(--speed);
}
[data-theme-layout="factory-pipeworks"] .ppw-pipe:hover { border-color: var(--accent); transform: translateY(-3px); color: var(--ink); }
[data-theme-layout="factory-pipeworks"] .ppw-pipe-media { position: relative; display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-pipeworks"] .ppw-pipe-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .25s ease; }
[data-theme-layout="factory-pipeworks"] .ppw-pipe:hover .ppw-pipe-media img { transform: scale(1.03); }
[data-theme-layout="factory-pipeworks"] .ppw-pipe-gen b { font-family: var(--sans); font-size: 2.9rem; color: var(--accent); }
/* DN 牌：绝对定位钉在媒体框（自有车道），720px 不外溢 */
[data-theme-layout="factory-pipeworks"] .ppw-pipe-tag {
  position: absolute; top: 10px; left: 10px; padding: .16rem .55rem;
  border-radius: 999px; background: var(--ink); color: var(--bg);
  font-family: var(--mono); font-size: .58rem; font-weight: 700; letter-spacing: .12em; line-height: 1.6;
}
[data-theme-layout="factory-pipeworks"] .ppw-pipe-body { display: flex; flex: 1; flex-direction: column; gap: .3rem; padding: .85rem 1rem .95rem; }
[data-theme-layout="factory-pipeworks"] .ppw-pipe-cat { width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 750; letter-spacing: .07em; text-transform: uppercase; }
[data-theme-layout="factory-pipeworks"] .ppw-pipe-title { font-size: .97rem; font-weight: 720; line-height: 1.4; overflow-wrap: anywhere; }
[data-theme-layout="factory-pipeworks"] .ppw-pipe-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .8rem; line-height: 1.55; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
/* 口径行：chips 压到卡底，虚线上边 + 胶囊 chip */
[data-theme-layout="factory-pipeworks"] .ppw-pipe .f-chips { margin-top: auto; padding-top: .55rem; border-top: 1px dashed var(--line); }
[data-theme-layout="factory-pipeworks"] .ppw-pipe .f-chip { border-radius: 999px; }
[data-theme-layout="factory-pipeworks"] .ppw-empty { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); border-radius: 18px; text-align: center; }

/* ---- 流程：共享 f-process 重塑成管线（金属管段连线 + 法兰接头圈）-------- */
[data-theme-layout="factory-pipeworks"] .ppw-process-sec .f-process { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.3rem; }
[data-theme-layout="factory-pipeworks"] .ppw-process-sec .f-step::before {
  top: 15px; height: 8px; border-radius: 4px;
  background: linear-gradient(180deg, var(--ppw-steel-hi), var(--ppw-steel-mid) 55%, var(--ppw-steel-lo));
}
[data-theme-layout="factory-pipeworks"] .ppw-process-sec .f-step:last-child::before {
  background: linear-gradient(90deg, var(--ppw-steel-mid) 30%, transparent);
}
/* 法兰接头：实线圆 + 外圈虚线螺栓圈（outline 不占布局车道） */
[data-theme-layout="factory-pipeworks"] .ppw-process-sec .f-step-num {
  display: grid; place-items: center; width: 38px; height: 38px; padding: 0;
  border: 2px solid var(--accent); border-radius: 50%; background: var(--bg);
  outline: 2px dashed var(--ppw-ring); outline-offset: 3px;
  font-size: .9rem; line-height: 1; color: var(--accent);
}
[data-theme-layout="factory-pipeworks"] .ppw-process-sec .f-step-title { margin-top: .85rem; }

/* ---- 分类 / 行业 / FAQ / 图集：跟随圆管气质（大圆角）-------------------- */
[data-theme-layout="factory-pipeworks"] .ppw-wrap .f-cat-card,
[data-theme-layout="factory-pipeworks"] .ppw-wrap .f-industry,
[data-theme-layout="factory-pipeworks"] .ppw-wrap .f-faq-item,
[data-theme-layout="factory-pipeworks"] .ppw-wrap .f-gallery-item { border-radius: 14px; }
[data-theme-layout="factory-pipeworks"] .ppw-wrap .f-cat-media { border-radius: 10px; }

/* ---- 动态：细行清单 ----------------------------------------------------- */
[data-theme-layout="factory-pipeworks"] .ppw-news-head::after { height: 3px; background-image: linear-gradient(180deg, var(--ppw-steel-mid), var(--ppw-steel-lo)); background-size: 100% 100%; }
[data-theme-layout="factory-pipeworks"] .ppw-news-head h2 { font-size: 1.15rem; color: var(--ink-soft); }
[data-theme-layout="factory-pipeworks"] .ppw-news-item {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-pipeworks"] .ppw-news-item:hover { color: var(--accent); }
[data-theme-layout="factory-pipeworks"] .ppw-news-item time { color: var(--muted); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-pipeworks"] .ppw-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* =========================================================================
   内页重塑（不改公共模板，只重塑既有类）
   ① 商品/归档列表 .link-grid → 口径分组行：单列管段行卡（18px 圆角）+
      左侧 DN 序号胶囊列（CSS 计数器 + 虚线右分隔=支管接口）
   ② 商品详情 .pd-* → 管路参数 + 介质表：面包屑=管路路径胶囊条、主图 18px 管口圆角、
      缩略图=圆形表盘、询盘卡圆角、规格表=介质表（表头 surface 底 + 行前阀轮圈）、
      参数行 dt 等宽大写、相关商品跟管段卡圆角
   ========================================================================= */
[data-theme-layout="factory-pipeworks"] .link-grid { grid-template-columns: minmax(0, 1fr); gap: .65rem; counter-reset: ppw-dn; }
[data-theme-layout="factory-pipeworks"] .link-card {
  display: grid; grid-template-columns: 86px 112px minmax(0, 1fr); align-items: center; gap: 0 1rem;
  padding: .6rem .95rem .6rem .6rem; border: 1.5px solid var(--line); border-radius: 18px;
  background: var(--surface);
}
[data-theme-layout="factory-pipeworks"] .link-card::before {
  counter-increment: ppw-dn; content: "№ " counter(ppw-dn, decimal-leading-zero);
  align-self: stretch; display: grid; place-items: center;
  border-right: 1px dashed var(--ppw-ring); color: var(--ink-soft);
  font-family: var(--mono); font-size: .72rem; font-weight: 700; letter-spacing: .08em;
}
[data-theme-layout="factory-pipeworks"] .link-card:hover { transform: none; box-shadow: none; border-color: var(--accent); }
[data-theme-layout="factory-pipeworks"] .link-card:hover::before { color: var(--accent); }
[data-theme-layout="factory-pipeworks"] .lc-cover { border-radius: 12px; border: 1px solid var(--line); }
[data-theme-layout="factory-pipeworks"] .lc-body { padding: 0; gap: .25rem; }
[data-theme-layout="factory-pipeworks"] .lc-title { font-size: 1rem; }
[data-theme-layout="factory-pipeworks"] .lc-intro { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 1; }
/* 详情：管路路径胶囊条 */
[data-theme-layout="factory-pipeworks"] .pd-bc {
  display: flex; flex-wrap: wrap; align-items: center; gap: .2rem .5rem;
  margin-top: 1.1rem; padding: .5rem 1rem; border: 1.5px solid var(--line);
  border-radius: 999px; background: var(--surface);
  font-family: var(--mono); font-size: .74rem;
}
[data-theme-layout="factory-pipeworks"] .pd-media { border-radius: 18px; }
[data-theme-layout="factory-pipeworks"] .pd-thumb { border-radius: 50%; }
[data-theme-layout="factory-pipeworks"] .pd-inquiry { border: 2px solid var(--ppw-ring); border-radius: 18px; }
[data-theme-layout="factory-pipeworks"] .pd-meta { border-top: 2px solid var(--ink); }
[data-theme-layout="factory-pipeworks"] .pd-meta-row dt { font-family: var(--mono); font-size: .8rem; letter-spacing: .05em; text-transform: uppercase; }
/* 介质表：表头 surface 底（ink-soft 作字，三皮实算 ≥9）+ 行前阀轮圈 */
[data-theme-layout="factory-pipeworks"] .pd-specs-tablewrap { border-width: 1.5px; border-radius: 16px; }
[data-theme-layout="factory-pipeworks"] .pd-specs-table th {
  position: relative; padding-left: 2.4rem; background: var(--surface);
  color: var(--ink-soft); font-weight: 650;
}
[data-theme-layout="factory-pipeworks"] .pd-specs-table th::before {
  content: ""; position: absolute; left: 1rem; top: .95rem; width: 9px; height: 9px;
  border: 2px solid var(--accent); border-radius: 50%;
}
[data-theme-layout="factory-pipeworks"] .pd-rel-card,
[data-theme-layout="factory-pipeworks"] .pd-rel-media { border-radius: 16px; }

/* ---- 响应式 ------------------------------------------------------------- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-pipeworks"] .ppw-pipes { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-pipeworks"] .ppw-hero { grid-template-columns: minmax(0, 1fr); align-items: start; gap: 1.6rem; }
  [data-theme-layout="factory-pipeworks"] .ppw-pipes { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-pipeworks"] .ppw-process-sec .f-process { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 1.6rem; }
  [data-theme-layout="factory-pipeworks"] .link-card { grid-template-columns: 70px 96px minmax(0, 1fr); gap: 0 .9rem; }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-pipeworks"] .site-header::after { height: 12px; background-size: 22px 100%, 22px 100%, 100% 100%; }
  [data-theme-layout="factory-pipeworks"] .ppw-pipes { gap: 1rem .6rem; }
  [data-theme-layout="factory-pipeworks"] .ppw-pipe-ex { display: none; }
  [data-theme-layout="factory-pipeworks"] .ppw-pipe-tag { top: 7px; left: 7px; }
  [data-theme-layout="factory-pipeworks"] .ppw-news-item { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="factory-pipeworks"] .ppw-news-item .arrow { display: none; }
  [data-theme-layout="factory-pipeworks"] .ppw-news-title { white-space: normal; }
  [data-theme-layout="factory-pipeworks"] .link-card { grid-template-columns: 56px 84px minmax(0, 1fr); gap: 0 .75rem; border-radius: 14px; }
  [data-theme-layout="factory-pipeworks"] .link-card::before { font-size: .62rem; letter-spacing: .03em; }
  [data-theme-layout="factory-pipeworks"] .pd-specs-table th { padding-left: 2rem; }
  [data-theme-layout="factory-pipeworks"] .pd-specs-table th::before { left: .7rem; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-pipeworks"] .ppw-process-sec .f-process { grid-template-columns: minmax(0, 1fr); gap: 1.2rem; }
  [data-theme-layout="factory-pipeworks"] .ppw-gauges { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .55rem; }
  [data-theme-layout="factory-pipeworks"] .ppw-gauges .f-stat { padding: .9rem 1rem .85rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-pipeworks"] .ppw-pipe,
  [data-theme-layout="factory-pipeworks"] .ppw-pipe-media img,
  [data-theme-layout="factory-pipeworks"] .nav > a:not(.search-ico)::before,
  [data-theme-layout="factory-pipeworks"] .link-card { transition: none; }
  [data-theme-layout="factory-pipeworks"] .ppw-pipe:hover { transform: none; }
}

/* =========================================================================
   factory-pipeworks 三皮（原生 pipeworks / 反差 flowline / 纯白 pipeworks-white）
   实算对比度见每皮注释；--ppw-hot 恒为装饰色（阀门方块/支管 accent 段），永不作字；
   金属渐变（steel-hi/mid/lo）是纯装饰肌理，上面不落任何文字。
   ========================================================================= */
/* 不锈钢青 · Pipeworks：冷调钢白 + 不锈钢青（原生皮）
   ink/bg 15.30、ink/surface 16.80、ink-soft/surface 10.15、ink-soft/bg 9.24、
   muted/surface 5.80、muted/bg 5.28，accent 作字 6.20(surface) / 5.65(bg)，
   hover→accent-soft 9.18(surface) / 8.36(bg)（只升不降），
   btn-primary 白字压 accent 底 6.38，DN 牌 bg 字压 ink 底 15.30，
   CTA 通栏（ink 底）：眉标 mix(accent 60%, bg)=#66a19b 5.87、note 8.43、h2 15.30。
   装饰青 --ppw-hot #0f8d81 对 surface 3.97 / bg 3.61（非文字图形件，≥3 达标）。 */
:root[data-theme="pipeworks"] {
  --bg: #eef2f1; --surface: #fbfcfc; --ink: #161c1b; --ink-soft: #37423f;
  --muted: #5b6663; --faint: #8c9793; --line: #ccd6d3; --line-soft: #dfe7e4;
  --accent: #0b6b62; --accent-soft: #084f49; --accent-wash: #dcecea;
  --ppw-hot: #0f8d81;
  --w-wide: 1280px; --radius: 10px; --shadow: 0 8px 24px rgba(22,28,27,.08);
}
:root[data-theme="pipeworks"] .btn-primary { color: #fff; }

/* 夜巡管 · Flowline：深灰蓝夜厂 + 荧光青示流（反差皮）
   ink/bg 16.19、ink/surface 15.01、ink-soft/surface 10.87、ink-soft/bg 11.72、
   muted/surface 6.45、muted/bg 6.96，accent 作字 10.24(surface) / 11.04(bg)，
   hover→accent-soft 12.15(surface) / 13.11(bg)（只升不降），
   深字 #062a2e 压荧光青底 8.80（btn-primary / cat-nav active），
   DN 牌 bg 字压 ink 底 16.19。CTA 通栏在暗皮里翻成浅底（背景=ink #e7edf1），
   共用眉标 mix(accent 60%, bg)=#328790 只有 3.55——本皮改用 #0c5a62（6.70）。
   荧光青 --ppw-hot #22c9d6 对 surface 8.77（装饰件，示流灯气质）。 */
:root[data-theme="flowline"] {
  --bg: #0b1014; --surface: #12191f; --ink: #e7edf1; --ink-soft: #c2ccd3;
  --muted: #909ea8; --faint: #64717b; --line: #25313a; --line-soft: #19232b;
  --accent: #4cd7e2; --accent-soft: #83e5ed; --accent-wash: #0e3237; --code-bg: #070b0e;
  --ppw-hot: #22c9d6;
  --w-wide: 1280px; --radius: 10px; --shadow: 0 14px 40px rgba(0,0,0,.5);
}
:root[data-theme="flowline"] .btn-primary { color: #062a2e; }
:root[data-theme="flowline"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #062a2e; }
:root[data-theme="flowline"] .f-cta .f-eyebrow { color: #0c5a62; }
:root[data-theme="flowline"] .f-stat dt { text-shadow: 0 0 16px rgba(76,215,226,.3); }

/* 白管廊 · Pipeworks-white：纯白基底（中性灰对齐纯白系）+ 压深的钢青
   ink/bg 18.72、ink/surface 17.91、ink-soft/surface 9.37、ink-soft/bg 9.79，
   accent 作字 7.02(surface) / 7.33(bg)，hover→accent-soft 9.71 / 10.15（只升不降），
   白字压 accent 底 7.33，DN 牌 bg 字压 ink 底 18.72，
   CTA 通栏（ink 底）：眉标 6.37、note 9.95。装饰青 --ppw-hot #0d8377 对 surface 4.44。
   已知坑：muted #707680 在 surface #fafaf8 上只有 4.38 —— 本皮把所有承载 muted 文字的
   卡面（管段卡/表压胶囊/行业卡/分类卡/chip）覆写回 --bg 纯白（4.57 达标），
   chip 键名改 ink-soft（9.79）。 */
:root[data-theme="pipeworks-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #0c6157; --accent-soft: #094a42; --accent-wash: #e2f0ee;
  --ppw-hot: #0d8377;
  --w-wide: 1200px; --radius: 10px;
}
:root[data-theme="pipeworks-white"] .btn-primary { color: #fff; }
:root[data-theme="pipeworks-white"] .site-header { background: var(--bg); }
:root[data-theme="pipeworks-white"] .ppw-pipe,
:root[data-theme="pipeworks-white"] .f-stat,
:root[data-theme="pipeworks-white"] .f-industry,
:root[data-theme="pipeworks-white"] .f-cat-card,
:root[data-theme="pipeworks-white"] .link-card { background-color: var(--bg); }
:root[data-theme="pipeworks-white"] .f-chip { background: var(--bg); }
:root[data-theme="pipeworks-white"] .f-chip b { color: var(--ink-soft); }

/* =========================================================================
   LAYOUT: factory-shutter — 卷帘（工厂族；partial home_factory_shutter）
   每条选择器限定 [data-theme-layout="factory-shutter"]，自有类名前缀 sht-（全仓未占用）。
   形态：整页读成一条卷帘门市街。
     页头 = 门牌号导航：CSS 重塑标准 .site-header——导航项配等宽 No.01… 门牌号
            （CSS 计数器 decimal-leading-zero 生成，不改 DOM），当前项深底黄字灯牌
            （--sht-plate 底 + --sht-lamp 字）；≤620px 交还基础汉堡抽屉。
     hero  = 大标题（眉标=灯箱牌：plate 底 lamp 字 + hot 压条）+ factory.stats 档口小牌
            （顶条 No. 门牌；未配置回落 factory_about）。
     商品  = 卷帘门格：卡顶卷轴盒横条（plate 底 + hot 压条纹），媒体上段被帘板横纹渐变
            覆盖、底部白色信息条露出=半卷起，悬停帘子再卷高一段（reduced-motion 静止）；
            首张精选卡整门卷起=纯白底完整内容（无帘板覆盖，恒跨两列，卷轴盒加厚=帘卷收拢）。
     图集  = 档口实拍格：共享 f-gallery 从横向滚动带重塑为 No. 编号格网。
     流程  = 共享 f-process 记号，编号重塑成方形门牌（plate 底 + lamp 字）。
     内页  = 商品/归档列表 .link-grid 重塑为门市街（卡顶卷轴盒 + No. 门牌 + 帘板半卷覆盖）；
            商品详情 .pd-* 重塑为整门卷起大页（大图顶部帘卷收拢盒 + 面包屑门牌路条 +
            缩略图编号小牌 + 询价牌/规格表 plate 收边）。
   ========================================================================= */
[data-theme-layout="factory-shutter"] {
  --sht-hot: var(--accent);   /* 帘板压条黄：只贴 plate 底与照片上，恒不作字、不裸贴浅面 */
  --sht-plate: var(--ink);    /* 门牌/卷轴盒深底 */
  --sht-lamp: var(--bg);      /* 门牌灯字：兜底用 bg 反白，三皮各自覆写成实算过的灯黄 */
  --sht-slat: color-mix(in srgb, var(--ink) 22%, transparent); /* 帘板横纹 */
}
[data-theme-layout="factory-shutter"] body { background: var(--bg); }
[data-theme-layout="factory-shutter"] .sht-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px);
  margin-inline: auto;
  padding-bottom: clamp(3rem, 6vw, 4.4rem);
}

/* ---- 页头：门牌号导航（标准 .site-header 的 CSS 重塑，无新增 DOM）---------- */
[data-theme-layout="factory-shutter"] .site-header {
  background: var(--surface); -webkit-backdrop-filter: none; backdrop-filter: none;
  border-bottom: 2px solid var(--sht-plate);
}
@media (min-width: 621px) {
  [data-theme-layout="factory-shutter"] .site-header .wrap { height: 72px; align-items: stretch; gap: 0; }
  [data-theme-layout="factory-shutter"] .brand {
    align-self: center; margin-right: auto; padding-right: 1.1rem;
    font-family: var(--sans); font-weight: 780; letter-spacing: -.01em;
  }
  [data-theme-layout="factory-shutter"] .nav {
    counter-reset: sht-nav; align-self: stretch; align-items: stretch;
    gap: 0; border-left: 1px solid var(--line);
  }
  [data-theme-layout="factory-shutter"] .nav > a {
    display: flex; flex-direction: column; justify-content: center; gap: .16rem;
    padding: 0 clamp(.55rem, 1.3vw, 1rem); border-right: 1px solid var(--line);
    font-size: .88rem; font-weight: 650; overflow-wrap: anywhere;
  }
  /* 门牌号：CSS 计数器生成 No.01…，搜索入口不占号 */
  [data-theme-layout="factory-shutter"] .nav > a:not(.search-ico)::before {
    counter-increment: sht-nav; content: "№ " counter(sht-nav, decimal-leading-zero);
    font-family: var(--mono); font-size: .56rem; font-weight: 700;
    letter-spacing: .16em; color: var(--muted);
  }
  [data-theme-layout="factory-shutter"] .nav > a:hover { background: color-mix(in srgb, var(--ink) 4%, transparent); }
  /* 当前项＝亮灯的档口：深底黄字（lamp/plate 实算 10.42/12.23/11.95），基础下划线撤掉 */
  [data-theme-layout="factory-shutter"] .nav a[aria-current="page"] { background: var(--sht-plate); color: var(--sht-lamp); }
  [data-theme-layout="factory-shutter"] .nav a[aria-current="page"]:not(.search-ico)::before { color: var(--sht-lamp); }
  [data-theme-layout="factory-shutter"] .nav a[aria-current="page"]::after { content: none; }
  [data-theme-layout="factory-shutter"] .nav .search-ico { padding-inline: clamp(.55rem, 1.3vw, 1rem); opacity: 1; color: var(--muted); }
  [data-theme-layout="factory-shutter"] .nav .search-ico:hover { color: var(--accent); }
  [data-theme-layout="factory-shutter"] .nav .lang-switch { padding-left: .75rem; border-left: 0; }
}

/* ---- hero：大标题 + 档口小牌 -------------------------------------------- */
[data-theme-layout="factory-shutter"] .sht-hero {
  display: grid; grid-template-columns: minmax(0, 1.12fr) minmax(280px, .88fr);
  align-items: end; gap: clamp(1.4rem, 3vw, 2.8rem);
  padding: clamp(2rem, 4.5vw, 3.4rem) 0 clamp(1.4rem, 3vw, 2rem);
}
[data-theme-layout="factory-shutter"] .sht-eyebrow {
  width: fit-content; max-width: 100%; margin: 0 0 1.1rem; padding: .3rem .65rem;
  background: var(--sht-plate); color: var(--sht-lamp); border-bottom: 3px solid var(--sht-hot);
  font-family: var(--mono); font-size: .68rem; font-weight: 800; letter-spacing: .16em;
  text-transform: uppercase; overflow-wrap: anywhere;
}
[data-theme-layout="factory-shutter"] .sht-h1 {
  margin: 0; max-width: 15em; font-size: clamp(2rem, 4.6vw, 3.3rem);
  font-weight: 790; line-height: 1.08; letter-spacing: -.015em; overflow-wrap: anywhere;
}
[data-theme-layout="factory-shutter"] .sht-lede { max-width: 56ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.75; }
[data-theme-layout="factory-shutter"] .sht-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="factory-shutter"] .sht-hero-side { min-width: 0; }
[data-theme-layout="factory-shutter"] .sht-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .7rem; counter-reset: sht-plateno; }
[data-theme-layout="factory-shutter"] .sht-stats .f-stat { padding: 1.9rem 1rem .95rem; border-radius: 0; }
/* 档口小牌顶条：覆写共用数字卡的左上角标（含 content/尺寸/边框全量重置） */
[data-theme-layout="factory-shutter"] .sht-stats .f-stat::before {
  counter-increment: sht-plateno; content: "№ " counter(sht-plateno, decimal-leading-zero);
  top: 0; left: 0; right: 0; width: auto; height: auto; padding: .2rem .55rem;
  border: 0; background: var(--sht-plate); color: var(--sht-lamp); text-align: left;
  font-family: var(--mono); font-size: .56rem; font-weight: 700; letter-spacing: .16em; line-height: 1.6;
}
[data-theme-layout="factory-shutter"] .sht-stats .f-stat::after { border-color: var(--sht-hot); }
[data-theme-layout="factory-shutter"] .sht-stats .f-stat dt { font-size: clamp(1.35rem, 2.2vw, 1.9rem); }
[data-theme-layout="factory-shutter"] .sht-hero-side .f-about { border-radius: 0; }

/* ---- 区块头：门楣线 ------------------------------------------------------ */
[data-theme-layout="factory-shutter"] .sht-section { padding-top: clamp(2.6rem, 5vw, 3.6rem); }
[data-theme-layout="factory-shutter"] .sht-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem;
  margin-bottom: 1.3rem; padding-bottom: .7rem; border-bottom: 2px solid var(--sht-plate);
}
[data-theme-layout="factory-shutter"] .sht-head h2 { margin: 0; font-size: clamp(1.35rem, 2.4vw, 1.7rem); font-weight: 780; overflow-wrap: anywhere; }
[data-theme-layout="factory-shutter"] .sht-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="factory-shutter"] .sht-head > a:hover { color: var(--accent); }

/* ---- 商品：卷帘门格（卷轴盒 + 帘板半卷覆盖 + 白色信息条）----------------- */
[data-theme-layout="factory-shutter"] .sht-doors { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.4rem .7rem; counter-reset: sht-door; }
[data-theme-layout="factory-shutter"] .sht-door {
  display: flex; min-width: 0; flex-direction: column;
  border: 1px solid var(--line); border-radius: 0; background: var(--surface); color: var(--ink);
  overflow: hidden; transition: border-color var(--speed), transform var(--speed);
}
/* 卷轴盒：门顶横条（plate 底 + hot 压条纹）——块级流内，不占绝对定位车道 */
[data-theme-layout="factory-shutter"] .sht-door::before {
  content: ""; display: block; flex: none; height: 9px;
  background-color: var(--sht-plate);
  background-image: repeating-linear-gradient(90deg, color-mix(in srgb, var(--sht-hot) 85%, transparent) 0 12px, transparent 12px 26px);
}
[data-theme-layout="factory-shutter"] .sht-door:hover { border-color: var(--accent); transform: translateY(-3px); color: var(--ink); }
[data-theme-layout="factory-shutter"] .sht-door-media { position: relative; display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="factory-shutter"] .sht-door-media img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="factory-shutter"] .sht-door-gen b { font-family: var(--sans); font-size: 2.9rem; color: var(--accent); }
/* No. 门牌：绝对定位钉死在媒体左上（媒体 relative+overflow hidden 即专属车道，720px 不游走） */
[data-theme-layout="factory-shutter"] .sht-door-media::before {
  counter-increment: sht-door; content: "№ " counter(sht-door, decimal-leading-zero);
  position: absolute; top: 0; left: 0; z-index: 2; padding: .18rem .5rem;
  background: var(--sht-plate); color: var(--sht-lamp);
  font-family: var(--mono); font-size: .58rem; font-weight: 700; letter-spacing: .14em; line-height: 1.6;
}
/* 帘板：横纹渐变盖住媒体上段=半卷起；底缘 plate 收边条；悬停再卷高一段 */
[data-theme-layout="factory-shutter"] .sht-door-media::after {
  content: ""; position: absolute; inset: 0 0 auto; z-index: 1; height: 58%;
  background-color: color-mix(in srgb, var(--surface) 42%, transparent);
  background-image: repeating-linear-gradient(180deg, var(--sht-slat) 0 2px, color-mix(in srgb, var(--ink) 5%, transparent) 2px 9px);
  border-bottom: 3px solid var(--sht-plate);
  transition: height .3s ease;
}
[data-theme-layout="factory-shutter"] .sht-door:hover .sht-door-media::after { height: 26%; }
[data-theme-layout="factory-shutter"] .sht-door-body { display: flex; flex: 1; flex-direction: column; gap: .3rem; padding: .8rem .9rem 1rem; background: var(--surface); }
[data-theme-layout="factory-shutter"] .sht-door-cat { width: fit-content; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--accent); font-family: var(--mono); font-size: .64rem; font-weight: 750; letter-spacing: .07em; text-transform: uppercase; }
[data-theme-layout="factory-shutter"] .sht-door-title { font-size: .97rem; font-weight: 720; line-height: 1.4; overflow-wrap: anywhere; }
[data-theme-layout="factory-shutter"] .sht-door-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .8rem; line-height: 1.55; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="factory-shutter"] .sht-empty { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--line); text-align: center; }
/* 精选＝整门卷起：恒跨两列（4/3/2 列栅格下都成立），无帘板覆盖，卷轴盒加厚=帘卷收拢 */
[data-theme-layout="factory-shutter"] .sht-door-open { grid-column: span 2; }
[data-theme-layout="factory-shutter"] .sht-door-open::before {
  height: 16px;
  background-image: repeating-linear-gradient(0deg, color-mix(in srgb, var(--sht-hot) 70%, transparent) 0 2px, transparent 2px 5px);
}
[data-theme-layout="factory-shutter"] .sht-door-open .sht-door-media { aspect-ratio: 2 / 1; }
[data-theme-layout="factory-shutter"] .sht-door-open .sht-door-media::after { content: none; }
[data-theme-layout="factory-shutter"] .sht-door-open .sht-door-title { font-size: 1.15rem; }
[data-theme-layout="factory-shutter"] .sht-door-open .sht-door-ex { -webkit-line-clamp: 3; }

/* ---- 图集：档口实拍格（共享 f-gallery 从滚动带重塑为编号格网）------------ */
[data-theme-layout="factory-shutter"] .sht-wrap .f-gallery { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .8rem; padding-bottom: 0; overflow: visible; counter-reset: sht-g; }
[data-theme-layout="factory-shutter"] .sht-wrap .f-gallery-item { position: relative; border-radius: 0; }
[data-theme-layout="factory-shutter"] .sht-wrap .f-gallery-item img { width: 100%; height: 100%; max-width: none; aspect-ratio: 4 / 3; object-fit: cover; }
[data-theme-layout="factory-shutter"] .sht-wrap .f-gallery-item::after {
  counter-increment: sht-g; content: "№ " counter(sht-g, decimal-leading-zero);
  position: absolute; top: 0; left: 0; padding: .16rem .45rem;
  background: var(--sht-plate); color: var(--sht-lamp);
  font-family: var(--mono); font-size: .55rem; font-weight: 700; letter-spacing: .14em; line-height: 1.6;
}

/* ---- 流程：编号重塑成方形门牌 -------------------------------------------- */
[data-theme-layout="factory-shutter"] .sht-process-sec .f-step::before { top: 16px; }
[data-theme-layout="factory-shutter"] .sht-process-sec .f-step-num {
  display: grid; place-items: center; width: 34px; height: 34px; padding: 0;
  background: var(--sht-plate); color: var(--sht-lamp); font-size: .9rem; line-height: 1;
}
[data-theme-layout="factory-shutter"] .sht-process-sec .f-step-title { margin-top: .7rem; }

/* ---- 分类 / 行业 / hero 兜底：跟随直角门市气质 --------------------------- */
[data-theme-layout="factory-shutter"] .sht-wrap .f-cat-card,
[data-theme-layout="factory-shutter"] .sht-wrap .f-cat-media,
[data-theme-layout="factory-shutter"] .sht-wrap .f-industry { border-radius: 0; }
[data-theme-layout="factory-shutter"] .sht-wrap .f-cat-card:hover { transform: none; border-color: var(--accent); }

/* ---- 动态：细行清单 ------------------------------------------------------ */
[data-theme-layout="factory-shutter"] .sht-news-head { border-bottom-width: 1px; border-bottom-color: var(--line); }
[data-theme-layout="factory-shutter"] .sht-news-head h2 { font-size: 1.15rem; color: var(--ink-soft); }
[data-theme-layout="factory-shutter"] .sht-news-item {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: baseline; gap: 1rem;
  padding: .7rem .2rem; border-bottom: 1px solid var(--line-soft); color: var(--ink-soft); font-size: .92rem;
}
[data-theme-layout="factory-shutter"] .sht-news-item:hover { color: var(--accent); }
[data-theme-layout="factory-shutter"] .sht-news-item time { color: var(--muted); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="factory-shutter"] .sht-news-title { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* =========================================================================
   内页重塑（不改公共模板，只重塑既有类）
   ① 商品/归档列表 .link-grid → 门市街：卡顶卷轴盒 + No. 门牌 + 帘板半卷覆盖封面
   ② 商品详情 .pd-* → 整门卷起大页：大图顶帘卷收拢盒、面包屑门牌路条、缩略图编号小牌
   ========================================================================= */
[data-theme-layout="factory-shutter"] .link-grid { counter-reset: sht-shop; gap: 1.4rem .7rem; }
[data-theme-layout="factory-shutter"] .link-card { border-radius: 0; }
[data-theme-layout="factory-shutter"] .link-card::before {
  content: ""; display: block; flex: none; height: 8px;
  background-color: var(--sht-plate);
  background-image: repeating-linear-gradient(90deg, color-mix(in srgb, var(--sht-hot) 85%, transparent) 0 12px, transparent 12px 26px);
}
[data-theme-layout="factory-shutter"] .link-card:hover { border-color: var(--accent); box-shadow: none; transform: translateY(-3px); }
[data-theme-layout="factory-shutter"] .lc-cover { position: relative; }
[data-theme-layout="factory-shutter"] .lc-cover::before {
  counter-increment: sht-shop; content: "№ " counter(sht-shop, decimal-leading-zero);
  position: absolute; top: 0; left: 0; z-index: 2; padding: .16rem .45rem;
  background: var(--sht-plate); color: var(--sht-lamp);
  font-family: var(--mono); font-size: .55rem; font-weight: 700; letter-spacing: .14em; line-height: 1.6;
}
[data-theme-layout="factory-shutter"] .lc-cover::after {
  content: ""; position: absolute; inset: 0 0 auto; z-index: 1; height: 46%;
  background-color: color-mix(in srgb, var(--surface) 38%, transparent);
  background-image: repeating-linear-gradient(180deg, var(--sht-slat) 0 2px, color-mix(in srgb, var(--ink) 5%, transparent) 2px 9px);
  border-bottom: 2px solid var(--sht-plate);
  transition: height .3s ease;
}
[data-theme-layout="factory-shutter"] .link-card:hover .lc-cover::after { height: 16%; }
[data-theme-layout="factory-shutter"] .pd-bc {
  display: flex; flex-wrap: wrap; align-items: center; gap: .2rem .5rem;
  margin-top: 1.1rem; padding: .5rem .85rem; border: 1px solid var(--line);
  border-left: 4px solid var(--sht-plate); background: var(--surface);
  font-family: var(--mono); font-size: .74rem;
}
/* 大图顶部帘卷收拢盒：整门卷起（块级流内，横纹=收拢的帘卷） */
[data-theme-layout="factory-shutter"] .pd-gallery::before {
  content: ""; display: block; height: 14px; border: 1px solid var(--line); border-bottom: 0;
  background-color: var(--sht-plate);
  background-image: repeating-linear-gradient(0deg, color-mix(in srgb, var(--sht-hot) 70%, transparent) 0 2px, transparent 2px 5px);
}
[data-theme-layout="factory-shutter"] .pd-media,
[data-theme-layout="factory-shutter"] .pd-thumb,
[data-theme-layout="factory-shutter"] .pd-inquiry,
[data-theme-layout="factory-shutter"] .pd-specs-tablewrap,
[data-theme-layout="factory-shutter"] .pd-rel-card,
[data-theme-layout="factory-shutter"] .pd-rel-media { border-radius: 0; }
[data-theme-layout="factory-shutter"] .pd-thumbs { counter-reset: sht-th; }
[data-theme-layout="factory-shutter"] .pd-thumb { position: relative; }
[data-theme-layout="factory-shutter"] .pd-thumb::after {
  counter-increment: sht-th; content: counter(sht-th, decimal-leading-zero);
  position: absolute; left: 0; bottom: 0; padding: .05rem .28rem;
  background: var(--sht-plate); color: var(--sht-lamp); font-family: var(--mono); font-size: .55rem; font-weight: 700; line-height: 1.7;
}
[data-theme-layout="factory-shutter"] .pd-inquiry { border-left: 4px solid var(--sht-plate); }
[data-theme-layout="factory-shutter"] .pd-specs-tablewrap { border-top: 4px solid var(--sht-plate); }
[data-theme-layout="factory-shutter"] .pd-rel-card::before {
  content: ""; display: block; flex: none; height: 7px;
  background-color: var(--sht-plate);
  background-image: repeating-linear-gradient(90deg, color-mix(in srgb, var(--sht-hot) 85%, transparent) 0 10px, transparent 10px 22px);
}

/* ---- 响应式 -------------------------------------------------------------- */
@media (max-width: 1020px) {
  [data-theme-layout="factory-shutter"] .sht-doors { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 920px) {
  [data-theme-layout="factory-shutter"] .sht-hero { grid-template-columns: minmax(0, 1fr); align-items: start; gap: 1.6rem; }
  [data-theme-layout="factory-shutter"] .sht-doors { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="factory-shutter"] .sht-wrap .f-gallery { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  [data-theme-layout="factory-shutter"] .sht-doors { gap: 1rem .5rem; }
  [data-theme-layout="factory-shutter"] .sht-door:not(.sht-door-open) .sht-door-ex,
  [data-theme-layout="factory-shutter"] .sht-door:not(.sht-door-open) .f-chips { display: none; }
  [data-theme-layout="factory-shutter"] .sht-door-open .sht-door-media { aspect-ratio: 16 / 9; }
  [data-theme-layout="factory-shutter"] .sht-wrap .f-gallery { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .6rem; }
  [data-theme-layout="factory-shutter"] .sht-news-item { grid-template-columns: minmax(0, 1fr); gap: .15rem; }
  [data-theme-layout="factory-shutter"] .sht-news-item .arrow { display: none; }
  [data-theme-layout="factory-shutter"] .sht-news-title { white-space: normal; }
}
@media (max-width: 620px) {
  [data-theme-layout="factory-shutter"] .sht-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .5rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="factory-shutter"] .sht-door,
  [data-theme-layout="factory-shutter"] .sht-door-media::after,
  [data-theme-layout="factory-shutter"] .link-card,
  [data-theme-layout="factory-shutter"] .lc-cover::after { transition: none; }
  [data-theme-layout="factory-shutter"] .sht-door:hover { transform: none; }
  [data-theme-layout="factory-shutter"] .sht-door:hover .sht-door-media::after { height: 58%; }
  [data-theme-layout="factory-shutter"] .link-card:hover { transform: none; }
  [data-theme-layout="factory-shutter"] .link-card:hover .lc-cover::after { height: 46%; }
}

/* =========================================================================
   factory-shutter 三皮（原生 shutter / 反差 stallfront / 纯白 shutter-white）
   实算对比度见每皮注释；--sht-hot 恒为装饰色（帘板压条/卷轴盒纹），永不作字、
   不裸贴浅面（只贴 plate 底与照片上）；--sht-lamp 只在 --sht-plate 深底上作字。
   ========================================================================= */
/* 五金城 · Shutter：暖灰水泥 + 卷帘黄（原生皮）
   ink/bg 14.98、ink/surface 16.51、ink-soft/surface 9.78、muted/surface 6.23、muted/bg 5.65、
   accent 作字 5.62(surface) / 5.10(bg)，hover→accent-soft 7.76 / 7.04（只升不降），
   门牌灯字 lamp #f7c14b 压 plate 底 10.42（导航当前项/No. 门牌/hero 眉标/流程号牌通用），
   btn-primary 白字压 accent 5.87，CTA 眉标（共用 mix(accent 60%, bg)≈#b3965e）压 ink 6.11。
   帘板压条黄 #f0b400 压 plate 9.22（对 surface 仅 1.79，故绝不裸贴浅面）。 */
:root[data-theme="shutter"] {
  --bg: #f0efea; --surface: #fbfaf6; --ink: #1c1b16; --ink-soft: #43413a;
  --muted: #605e55; --faint: #8b897f; --line: #d5d3c9; --line-soft: #e6e4da;
  --accent: #8a5b00; --accent-soft: #6e4800; --accent-wash: #f4ead0;
  --sht-hot: #f0b400; --sht-lamp: #f7c14b;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 8px 24px rgba(28,27,22,.08);
}
:root[data-theme="shutter"] .btn-primary { color: #fff; }

/* 夜市 · Stallfront：深灰黑市街 + 暖黄灯（反差皮）
   ink/bg 15.29、ink/surface 14.21、ink-soft/surface 9.97、muted/surface 5.67、muted/bg 6.10、
   accent 作字 9.63(surface) / 10.36(bg)，hover→accent-soft 11.36 / 12.23（只升不降），
   深字 #1a1408 压 accent 黄底 10.05（btn-primary / cat-nav 激活），
   门牌 plate 压深到 #060505、灯字 #f5c14b 压 plate 12.23（深底黄字＝夜市灯牌）。
   CTA 通栏在暗皮里翻成浅底（背景=ink），共用眉标 mix(accent 60%, bg) 只有 3.50，
   本皮改用 #6d4d10（6.26）；cta-note（bg 72% mix）实算 6.83。
   深底门牌沉进深卡面，描一圈灯晕内边免得看不见。 */
:root[data-theme="stallfront"] {
  --bg: #121110; --surface: #1b1917; --ink: #ece7db; --ink-soft: #c9c3b4;
  --muted: #999283; --faint: #6e6759; --line: #34302a; --line-soft: #221f1b;
  --accent: #f2b63c; --accent-soft: #f7ca6b; --accent-wash: #3a2e10; --code-bg: #0a0908;
  --sht-hot: #f2b63c; --sht-plate: #060505; --sht-lamp: #f5c14b;
  --w-wide: 1280px; --radius: 2px; --shadow: 0 14px 40px rgba(0,0,0,.5);
}
:root[data-theme="stallfront"] .btn-primary { color: #1a1408; }
:root[data-theme="stallfront"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: #1a1408; }
:root[data-theme="stallfront"] .f-cta .f-eyebrow { color: #6d4d10; }
:root[data-theme="stallfront"] .f-stat dt { text-shadow: 0 0 16px rgba(242,182,60,.28); }
:root[data-theme="stallfront"] .sht-eyebrow,
:root[data-theme="stallfront"] .sht-door::before,
:root[data-theme="stallfront"] .sht-door-media::before,
:root[data-theme="stallfront"] .sht-stats .f-stat::before,
:root[data-theme="stallfront"] .f-gallery-item::after,
:root[data-theme="stallfront"] .sht-process-sec .f-step-num,
:root[data-theme="stallfront"] .link-card::before,
:root[data-theme="stallfront"] .lc-cover::before,
:root[data-theme="stallfront"] .pd-gallery::before,
:root[data-theme="stallfront"] .pd-thumb::after,
:root[data-theme="stallfront"] .pd-rel-card::before { box-shadow: inset 0 0 0 1px rgba(242,182,60,.25); }

/* 白档口 · Shutter-white：纯白基底（中性灰对齐纯白系）+ 压深的卷帘金
   ink/bg 18.72、ink/surface 17.91、ink-soft/surface 9.37、accent 作字 6.21(bg) / 5.94(surface)，
   hover→accent-soft 8.99 / 8.61（只升不降），白字压 accent 6.21，
   灯字 #f7c948 压 plate 11.95，CTA 眉标（共用 mix）压 ink 7.05，压条金 #a87b00 对 bg 3.82。
   已知坑：muted #707680 在 surface #fafaf8 上只有 4.38——本皮把所有承载 muted 文字的
   卡面（卷帘门卡/档口小牌/行业卡/分类卡/门市街卡/规格 chip）覆写回 --bg 纯白（4.57 达标），
   规格表 th 底同覆写、th 与 chip 键名改 ink-soft（9.37/9.79）。 */
:root[data-theme="shutter-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #7e5b00; --accent-soft: #614400; --accent-wash: #f8f0da;
  --sht-hot: #a87b00; --sht-lamp: #f7c948;
  --w-wide: 1200px; --radius: 2px;
}
:root[data-theme="shutter-white"] .btn-primary { color: #fff; }
:root[data-theme="shutter-white"] .site-header { background: var(--bg); }
:root[data-theme="shutter-white"] .sht-door,
:root[data-theme="shutter-white"] .sht-door-body,
:root[data-theme="shutter-white"] .f-stat,
:root[data-theme="shutter-white"] .f-industry,
:root[data-theme="shutter-white"] .f-cat-card,
:root[data-theme="shutter-white"] .link-card { background-color: var(--bg); }
:root[data-theme="shutter-white"] .f-chip { background: var(--bg); }
:root[data-theme="shutter-white"] .f-chip b { color: var(--ink-soft); }
:root[data-theme="shutter-white"] .pd-specs-table th { background: var(--bg); color: var(--ink-soft); }

/* ==========================================================================
   外贸独立站(dtc)骨架第二批 ×20：橱窗 / 刊物店 / 型录 / 集市 / 直列 / 严选格 / 秀场 /
   工坊 / 月盒 / 展位 / 药柜 / 食铺 / 酒窖 / 营地 / 玩具盒 / 手账铺 / 黑白铺 / 平铺 /
   传单 / 灯箱。每款＝布局段 + 商品列表页与详情页定制段 + 三张皮令牌块（原生 / 反差 / 纯白）。
   选择器一律限定 [data-theme-layout="dtc-<slug>"] 或 :root[data-theme="<skin>"]。
   ========================================================================== */

/* =========================================================================
   LAYOUT: dtc-vitrine — 「橱窗」精品店（vtr-*）：三联橱窗首屏（中窗大、文案压
   中窗下沿）+ 白底细框 4/5 竖卡商品格 + 分类细字排。细顶条页头（品牌左、链接中、
   右上纯 CSS 购物袋挂 /products）。全部选择器限定 [data-theme-layout="dtc-vitrine"]；
   本段必须排在 DTC 共用段（dt-*）之后——按钮直角/内页覆写靠源顺序压过族规则。
   ========================================================================= */
[data-theme-layout="dtc-vitrine"] .vtr-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-vitrine"] .btn, [data-theme-layout="dtc-vitrine"] .inquiry-btn { border-radius: 0; }

/* ---- 页头重塑：细顶条（≤620px 交还基础汉堡抽屉，重塑段整体包 min-width:621px） ---- */
@media (min-width: 621px) {
  [data-theme-layout="dtc-vitrine"] .site-header { background: var(--bg); border-bottom: 1px solid var(--line); -webkit-backdrop-filter: none; backdrop-filter: none; }
  [data-theme-layout="dtc-vitrine"] .site-header .wrap { height: 54px; }
  [data-theme-layout="dtc-vitrine"] .site-header .brand { font-size: 1.04rem; font-weight: 650; letter-spacing: .14em; text-transform: uppercase; }
  /* 链接居中：首链接与 search-ico 各吃一个 auto margin，剩余空间对半分 */
  [data-theme-layout="dtc-vitrine"] .nav { flex: 1; min-width: 0; gap: 1.35rem; }
  [data-theme-layout="dtc-vitrine"] .nav > a:first-child:not([href$="/products"]) { margin-left: auto; }
  [data-theme-layout="dtc-vitrine"] .nav > a[href$="/products"]:first-child + a { margin-left: auto; }
  [data-theme-layout="dtc-vitrine"] .nav .search-ico { margin-left: auto; }
  [data-theme-layout="dtc-vitrine"] .nav a { font-size: .8rem; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; }
  [data-theme-layout="dtc-vitrine"] .nav a[aria-current="page"]::after { bottom: -17px; }
  /* 纯 CSS 购物袋（袋身 ::before + 提手 ::after，currentColor）：命中任意语种前缀的
     /products 菜单项并排到最右；菜单没有该项时整组规则空转，页头照常 */
  [data-theme-layout="dtc-vitrine"] .nav a[href$="/products"] { order: 99; position: relative; padding-left: 21px; font-weight: 700; color: var(--accent); }
  [data-theme-layout="dtc-vitrine"] .nav a[href$="/products"]:hover { color: var(--accent-soft); }
  [data-theme-layout="dtc-vitrine"] .nav a[href$="/products"]::before { content: ""; position: absolute; left: 0; bottom: .1em; width: 13px; height: 11px; border: 1.6px solid currentColor; border-radius: 2px 2px 5px 5px; }
  [data-theme-layout="dtc-vitrine"] .nav a[href$="/products"]::after { content: ""; position: absolute; left: 3px; bottom: calc(.1em + 8px); width: 7px; height: 7px; border: 1.6px solid currentColor; border-bottom: 0; border-radius: 6px 6px 0 0; }
}

/* ---- 三联橱窗首屏：中窗大；两侧窗为前三件商品的陈列位（绝对定位内容的车道=各自窗格） ---- */
[data-theme-layout="dtc-vitrine"] .vtr-hero { margin-top: 1.5rem; }
[data-theme-layout="dtc-vitrine"] .vtr-windows { display: grid; grid-template-areas: "l c r"; grid-template-columns: minmax(0, 1fr) minmax(0, 1.9fr) minmax(0, 1fr); gap: 14px; }
[data-theme-layout="dtc-vitrine"] .vtr-win { position: relative; min-width: 0; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); overflow: hidden; }
[data-theme-layout="dtc-vitrine"] .vtr-win-l { grid-area: l; }
[data-theme-layout="dtc-vitrine"] .vtr-win-r { grid-area: r; }
[data-theme-layout="dtc-vitrine"] .vtr-win-main { grid-area: c; display: flex; flex-direction: column; justify-content: flex-end; aspect-ratio: 10 / 9; }
[data-theme-layout="dtc-vitrine"] .vtr-win-item, [data-theme-layout="dtc-vitrine"] .vtr-win-pane { position: absolute; inset: 0; display: grid; place-items: center; }
[data-theme-layout="dtc-vitrine"] .vtr-win-pane { background: linear-gradient(165deg, var(--accent-wash), var(--surface) 72%); }
[data-theme-layout="dtc-vitrine"] .vtr-win-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; transition: transform .35s ease; }
[data-theme-layout="dtc-vitrine"] .vtr-win-item:hover .vtr-win-img { transform: scale(1.03); }
[data-theme-layout="dtc-vitrine"] .vtr-win-layer { position: absolute; inset: 0; display: grid; place-items: start center; padding: clamp(.8rem, 2vw, 1.6rem); }
[data-theme-layout="dtc-vitrine"] .vtr-win-main:not(.has-photo) { background: linear-gradient(180deg, var(--accent-wash), var(--surface) 62%); }
/* scrim：文案落位区（下沿）alpha ≥ .44→.82；白字对纯白图最坏底 ≥7.4（.7 处）～11.7（底部） */
[data-theme-layout="dtc-vitrine"] .vtr-win-main.has-photo::before { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(15,12,7,0) 30%, rgba(15,12,7,.44) 58%, rgba(15,12,7,.82) 100%); }
[data-theme-layout="dtc-vitrine"] .vtr-hero-copy { position: relative; z-index: 1; padding: clamp(1.1rem, 2.6vw, 1.9rem); }
[data-theme-layout="dtc-vitrine"] .vtr-h1 { margin: 0; max-width: 17em; font-family: var(--dt-display, var(--serif)); font-size: clamp(1.7rem, 3.4vw, 2.6rem); font-weight: 650; line-height: 1.14; letter-spacing: -.012em; }
[data-theme-layout="dtc-vitrine"] .vtr-lede { display: -webkit-box; overflow: hidden; margin: .7rem 0 0; max-width: 52ch; color: var(--muted); font-size: .98rem; line-height: 1.75; -webkit-box-orient: vertical; -webkit-line-clamp: 3; } /* 长描述钳高，护住橱窗比例 */
[data-theme-layout="dtc-vitrine"] .vtr-cta { display: flex; flex-wrap: wrap; gap: .65rem; margin-top: 1.15rem; }
[data-theme-layout="dtc-vitrine"] .vtr-win-main.has-photo .dt-eyebrow { color: #fff; opacity: .85; }
[data-theme-layout="dtc-vitrine"] .vtr-win-main.has-photo .vtr-h1 { color: #fff; } /* 全局 h1 色规则会盖过继承，压图必须显式白字 */
[data-theme-layout="dtc-vitrine"] .vtr-win-main.has-photo .vtr-lede { color: rgba(255,255,255,.88); }
[data-theme-layout="dtc-vitrine"] .vtr-win-main.has-photo .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-vitrine"] .vtr-win-main.has-photo .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-vitrine"] .vtr-win-main.has-photo .btn-primary { background: #fff; border-color: #fff; color: #16120c; }

/* ---- 商品橱窗格：分类细字排 + 白底细框 4/5 竖卡（规格签当价签） ---- */
[data-theme-layout="dtc-vitrine"] .vtr-section { padding-top: clamp(2.8rem, 6vw, 4.2rem); }
[data-theme-layout="dtc-vitrine"] .vtr-cats { display: flex; flex-wrap: wrap; gap: .4rem 1.5rem; margin: 0 0 1.2rem; padding-bottom: .8rem; border-bottom: 1px solid var(--line); }
[data-theme-layout="dtc-vitrine"] .vtr-cats a { color: var(--ink-soft); font-size: .8rem; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; }
[data-theme-layout="dtc-vitrine"] .vtr-cats a:hover { color: var(--accent-soft); }
[data-theme-layout="dtc-vitrine"] .vtr-cats i { font-style: normal; color: var(--muted); font-size: .7rem; letter-spacing: 0; }
[data-theme-layout="dtc-vitrine"] .vtr-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(215px, 100%), 1fr)); gap: 1.1rem; }
[data-theme-layout="dtc-vitrine"] .vtr-card { display: flex; flex-direction: column; min-width: 0; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); overflow: hidden; transition: border-color var(--speed), box-shadow var(--speed); }
[data-theme-layout="dtc-vitrine"] .vtr-card:hover { border-color: var(--accent); box-shadow: var(--shadow); color: var(--ink); }
[data-theme-layout="dtc-vitrine"] .vtr-card-media { display: grid; place-items: center; aspect-ratio: 4 / 5; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-vitrine"] .vtr-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-vitrine"] .vtr-card:hover .vtr-card-media img { transform: scale(1.04); }
[data-theme-layout="dtc-vitrine"] .vtr-card-body { display: flex; flex: 1; flex-direction: column; gap: .5rem; padding: .85rem .95rem 1rem; }
[data-theme-layout="dtc-vitrine"] .vtr-card-title { font-family: var(--dt-display, var(--serif)); font-size: 1.02rem; font-weight: 650; line-height: 1.4; }
[data-theme-layout="dtc-vitrine"] .vtr-card .f-chips { margin-top: auto; }

/* ---- 内页 · 商品列表（generic_list DOM）：列表跟随橱窗母题——细字分类排 + 4/5 竖卡 ---- */
[data-theme-layout="dtc-vitrine"] .page-head { padding: 2.6rem 0 1.6rem; }
[data-theme-layout="dtc-vitrine"] .page-head h1 { font-family: var(--dt-display, var(--serif)); font-weight: 650; letter-spacing: -.01em; }
[data-theme-layout="dtc-vitrine"] .page-head .eyebrow { letter-spacing: .2em; }
[data-theme-layout="dtc-vitrine"] .cat-nav { gap: .4rem 1.5rem; margin: 1.8rem 0 .2rem; padding-bottom: .9rem; border-bottom: 1px solid var(--line); }
[data-theme-layout="dtc-vitrine"] .cat-nav a { padding: 0; border: 0; border-radius: 0; background: none; color: var(--ink-soft); font-size: .8rem; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; }
[data-theme-layout="dtc-vitrine"] .cat-nav a:hover { color: var(--accent-soft); background: none; }
[data-theme-layout="dtc-vitrine"] .cat-nav a.active { background: none; border: 0; color: var(--accent); text-decoration: underline; text-underline-offset: .5em; }
[data-theme-layout="dtc-vitrine"] .cat-nav a .muted { color: var(--muted); font-size: .7rem; }
[data-theme-layout="dtc-vitrine"] .cat-nav a.active .muted { color: var(--accent); opacity: 1; }
[data-theme-layout="dtc-vitrine"] .link-grid { grid-template-columns: repeat(auto-fill, minmax(min(215px, 100%), 1fr)); gap: 1.1rem; }
[data-theme-layout="dtc-vitrine"] .link-card { border-radius: var(--radius); }
[data-theme-layout="dtc-vitrine"] .link-card:hover { transform: none; border-color: var(--accent); box-shadow: var(--shadow); }
[data-theme-layout="dtc-vitrine"] .lc-cover { aspect-ratio: 4 / 5; }
[data-theme-layout="dtc-vitrine"] .lc-cover img { transition: transform .3s ease; }
[data-theme-layout="dtc-vitrine"] .link-card:hover .lc-cover img { transform: scale(1.04); }
[data-theme-layout="dtc-vitrine"] .lc-mono { background: var(--accent-wash); color: var(--accent); font-family: var(--dt-display, var(--serif)); font-weight: 650; } /* 弃白字渐变底，wash+accent 实算 ≥4.7 */
[data-theme-layout="dtc-vitrine"] .lc-title { font-family: var(--dt-display, var(--serif)); font-size: 1.02rem; font-weight: 650; }
[data-theme-layout="dtc-vitrine"] .lc-intro { font-size: .86rem; }
[data-theme-layout="dtc-vitrine"] .lc-foot .tag { padding: 0; border: 0; border-radius: 0; background: none; color: var(--accent); font-size: .7rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
[data-theme-layout="dtc-vitrine"] .pagination a, [data-theme-layout="dtc-vitrine"] .pagination span { border-radius: 0; }

/* ---- 内页 · 商品详情（product_detail DOM）：左大图（4/5 橱窗比）+ 右粘性购买栏 ---- */
[data-theme-layout="dtc-vitrine"] .pd-main { padding-top: 1.4rem; }
[data-theme-layout="dtc-vitrine"] .pd-top { grid-template-columns: minmax(0, 1.12fr) minmax(0, .88fr); }
@media (min-width: 901px) { /* 基础层 ≤900 已折单列；粘性只在双栏时开 */
  [data-theme-layout="dtc-vitrine"] .pd-info { position: sticky; top: 72px; }
}
[data-theme-layout="dtc-vitrine"] .pd-media { aspect-ratio: 4 / 5; }
[data-theme-layout="dtc-vitrine"] .pd-thumb { border-radius: 0; }
[data-theme-layout="dtc-vitrine"] .pd-kicker { font-family: var(--sans); letter-spacing: .16em; }
[data-theme-layout="dtc-vitrine"] .pd-title { font-family: var(--dt-display, var(--serif)); font-weight: 650; letter-spacing: -.01em; }
[data-theme-layout="dtc-vitrine"] .pd-meta { border-top-color: var(--ink); }
[data-theme-layout="dtc-vitrine"] .pd-inquiry { padding: 1.15rem 1.2rem 1.3rem; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
[data-theme-layout="dtc-vitrine"] .pd-inquiry .inquiry-title { font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-vitrine"] .pd-inquiry .inquiry-actions { display: grid; grid-template-columns: 1fr; gap: .55rem; }
[data-theme-layout="dtc-vitrine"] .pd-inquiry .inquiry-btn { justify-content: center; }
[data-theme-layout="dtc-vitrine"] .pd-sec-title { font-family: var(--dt-display, var(--serif)); font-weight: 650; }
[data-theme-layout="dtc-vitrine"] .pd-specs-tablewrap { border-radius: 0; }
[data-theme-layout="dtc-vitrine"] .pd-specs-table th { color: var(--ink-soft); } /* 混色表头底上 muted 掉到 4.26（白皮），统一压回 ink-soft ≥8.7 */
[data-theme-layout="dtc-vitrine"] .pd-rel-card { border-radius: var(--radius); }
[data-theme-layout="dtc-vitrine"] .pd-rel-card:hover { transform: none; box-shadow: var(--shadow); }
[data-theme-layout="dtc-vitrine"] .pd-rel-media { aspect-ratio: 4 / 5; }
[data-theme-layout="dtc-vitrine"] .pd-rel-title { font-family: var(--dt-display, var(--serif)); font-weight: 650; }

/* ---- 响应式：920 收窄三联；720 中窗整行、两侧窗降为下排双窗，栅格双列不横溢 ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-vitrine"] .vtr-windows { grid-template-columns: minmax(0, .9fr) minmax(0, 2fr) minmax(0, .9fr); gap: 10px; }
  [data-theme-layout="dtc-vitrine"] .vtr-win-main { aspect-ratio: 1 / 1; }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-vitrine"] .vtr-windows { grid-template-areas: "c c" "l r"; grid-template-columns: 1fr 1fr; }
  [data-theme-layout="dtc-vitrine"] .vtr-win-main { aspect-ratio: auto; min-height: min(72vw, 430px); }
  [data-theme-layout="dtc-vitrine"] .vtr-win-side { aspect-ratio: 4 / 5; }
  [data-theme-layout="dtc-vitrine"] .vtr-grid { grid-template-columns: 1fr 1fr; gap: .75rem; }
  [data-theme-layout="dtc-vitrine"] .vtr-card .f-chips { display: none; } /* 窄卡收规格签，同 fc-card 先例 */
  [data-theme-layout="dtc-vitrine"] .link-grid { grid-template-columns: 1fr 1fr; gap: .75rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-vitrine"] .vtr-win-img, [data-theme-layout="dtc-vitrine"] .vtr-card-media img,
  [data-theme-layout="dtc-vitrine"] .lc-cover img, [data-theme-layout="dtc-vitrine"] .vtr-card,
  [data-theme-layout="dtc-vitrine"] .link-card, [data-theme-layout="dtc-vitrine"] .pd-rel-card { transition: none; }
}

/* ============================================================
   dtc-vitrine 皮肤 ×3：原生 vitrine / 深反差 vitrine-noir / 纯白 vitrine-white。
   全变量成套覆写；对比实算见各块注释（正文≥7、次要/accent≥4.5、hover 只升不降）。
   ============================================================ */

/* ---- 橱窗 · Vitrine（原生）：暖白纸底 + 墨黑 + 古铜金，细框精品店。
   实算：ink/bg 16.06、ink-soft/bg 8.79、muted/bg 5.40、muted/wash 4.82、
   accent/bg 5.29、accent/surface 5.82、accent/wash 4.73、hover accent-soft/bg 7.63↑ ---- */
:root[data-theme="vitrine"] {
  --bg: #f6f4ef; --surface: #ffffff; --ink: #1c1813; --ink-soft: #4a4437;
  --muted: #6b6355; --faint: #9a9183; --line: #e2dccd; --line-soft: #eeeadf;
  --accent: #7e6034; --accent-soft: #63491f; --accent-wash: #f0e7d3;
  --radius: 2px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(28,24,19,.05), 0 12px 28px rgba(28,24,19,.07);
}

/* ---- 橱窗夜幕 · Vitrine Noir（深反差）：夜幕黑 + 暖金橱窗灯。
   实算：ink/bg 15.66、ink-soft/bg 11.05、muted/bg 7.15、muted/surface 6.63、
   accent/bg 9.17、accent/surface 8.51、hover accent-soft/bg 11.08↑（暗皮 hover 提亮） ---- */
:root[data-theme="vitrine-noir"] {
  --bg: #151009; --surface: #1f1810; --ink: #f0e9db; --ink-soft: #cfc5b0;
  --muted: #a99e88; --faint: #7d735f; --line: #3a3222; --line-soft: #2a2318;
  --accent: #d9ae62; --accent-soft: #e6c17e; --accent-wash: #2a2113;
  --radius: 2px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(0,0,0,.5), 0 14px 34px rgba(0,0,0,.45);
}
/* 压图态主按钮走暖金（白按钮在夜幕大图上过艳）；金底近黑字 9.1 */
:root[data-theme="vitrine-noir"] .vtr-win-main.has-photo .btn-primary { background: var(--accent); border-color: var(--accent); color: #16120c; }

/* ---- 橱窗纯白 · Vitrine White：共享中性灰纯白基底；surface 收纯白避开
   「muted #707680 在 #fafaf8 上 4.38」的坑（细框本就是母题，白面靠发丝线分卡）。
   实算：ink/bg 18.72、ink-soft/bg 9.79、muted/白面 4.57、accent/bg 6.88、
   accent/wash 5.94、hover accent-soft/bg 9.53↑ ---- */
:root[data-theme="vitrine-white"] {
  --bg: #ffffff; --surface: #ffffff; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #755425; --accent-soft: #5c401a; --accent-wash: #f4eede;
  --radius: 0px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(16,18,24,.04), 0 10px 24px rgba(16,18,24,.06);
}
/* CTA 注释行 muted 落在 wash 上只有 3.95，压回 ink-soft（8.45） */
:root[data-theme="vitrine-white"] .dt-cta-note { color: var(--ink-soft); }

/* ==========================================================================
   dtc-journal 「刊物店」（jnl-*）：把独立站排成一本杂志。
   居中刊头双行（衬线大字距站名 + 细字链接行，双线压底）→ 封面故事跨页
   （HeroEyebrow 眉题 + 大衬线标题 + 第一件商品「封面物」图文卡）→ 栏目行
   →「本期选物」三栏条（上细线）→ 刊末数据栏 / 画页 / 读者来信引文 / FAQ / CTA。
   内页：列表=图文编辑流（大图行左右交替）；详情=杂志专题页（标题通栏、
   正文窄栏、右浮规格卡）。每条选择器限定 [data-theme-layout="dtc-journal"]；
   共享 dt-*（按钮/评价/FAQ/CTA/hero 动画）按刊物语言重排。
   hover 红线：全部走「颜色只升不降 + accent 下划线」——绝不悬停降对比。
   ========================================================================== */
[data-theme-layout="dtc-journal"] .jnl-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-journal"] .btn, [data-theme-layout="dtc-journal"] .inquiry-btn { border-radius: 0; } /* 刊物直角，压过族内胶囊语言 */

/* ---- 页头重塑：居中刊头双行，双线压底（只动 CSS；重塑段包 min-width:621px，
   ≤620px 交还基础汉堡抽屉） ---- */
[data-theme-layout="dtc-journal"] .site-header { border-bottom: 4px double var(--ink); }
[data-theme-layout="dtc-journal"] .nav a:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 5px; text-decoration-color: var(--accent); }
@media (min-width: 621px) {
  [data-theme-layout="dtc-journal"] .site-header { position: static; background: var(--bg); -webkit-backdrop-filter: none; backdrop-filter: none; }
  [data-theme-layout="dtc-journal"] .site-header .wrap { flex-direction: column; justify-content: center; height: auto; gap: .4rem; padding-top: 1.35rem; padding-bottom: 0; }
  [data-theme-layout="dtc-journal"] .site-header .brand { justify-content: center; text-align: center; font-size: clamp(1.5rem, 3vw, 2rem); font-weight: 700; letter-spacing: .26em; text-indent: .26em; text-transform: uppercase; }
  [data-theme-layout="dtc-journal"] .site-header .brand-tagline { margin: 0; text-align: center; font-family: var(--serif); font-style: italic; font-size: .85rem; color: var(--muted); }
  [data-theme-layout="dtc-journal"] .nav { align-self: stretch; justify-content: center; flex-wrap: wrap; gap: .1rem 1.5rem; margin-top: .5rem; border-top: 1px solid var(--line); padding: .5rem 0 .6rem; }
  [data-theme-layout="dtc-journal"] .nav a { min-width: 0; overflow-wrap: anywhere; font-size: .8rem; font-weight: 400; letter-spacing: .16em; text-transform: uppercase; }
  [data-theme-layout="dtc-journal"] .nav a[aria-current="page"]::after { bottom: -.66rem; height: 2px; }
}

/* ---- 封面故事跨页：左＝眉题/大题/引言/CTA，右＝封面物（第一件商品）/svg/轻动画 ---- */
[data-theme-layout="dtc-journal"] .jnl-cover { position: relative; margin-top: 1.7rem; border-bottom: 1px solid var(--line); overflow: hidden; }
[data-theme-layout="dtc-journal"] .jnl-cover-inner { display: grid; grid-template-columns: minmax(0, 1.02fr) minmax(300px, .98fr); align-items: center; gap: clamp(1.6rem, 4vw, 3.4rem); padding: clamp(2rem, 5vw, 3.6rem) 0 clamp(2.2rem, 5vw, 3.8rem); }
[data-theme-layout="dtc-journal"] .jnl-rubric { display: flex; align-items: center; gap: .8rem; margin: 0 0 1rem; color: var(--accent); font-size: .74rem; font-weight: 750; letter-spacing: .28em; text-transform: uppercase; }
[data-theme-layout="dtc-journal"] .jnl-rubric span { min-width: 0; overflow-wrap: anywhere; }
[data-theme-layout="dtc-journal"] .jnl-rubric::before { content: ""; flex: none; width: 34px; height: 1px; background: var(--accent); }
[data-theme-layout="dtc-journal"] .jnl-h1 { margin: 0; max-width: 14em; font-family: var(--dt-display, var(--serif)); font-size: clamp(2.2rem, 5vw, 3.6rem); font-weight: 700; line-height: 1.08; letter-spacing: -.012em; }
[data-theme-layout="dtc-journal"] .jnl-lede { max-width: 54ch; margin: 1.1rem 0 0; color: var(--ink-soft); font-family: var(--serif); font-style: italic; font-size: 1.04rem; line-height: 1.85; }
[data-theme-layout="dtc-journal"] .jnl-cover-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.9rem; }
[data-theme-layout="dtc-journal"] .jnl-cover-side { min-width: 0; }
/* hero=image：全幅封面照，scrim 压字，单列（绝对定位图和 scrim 各占专属图层车道） */
[data-theme-layout="dtc-journal"] .jnl-cover-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-journal"] .jnl-cover.has-img { min-height: min(70vh, 540px); display: flex; align-items: flex-end; border-bottom: 0; }
[data-theme-layout="dtc-journal"] .jnl-cover.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(102deg, rgba(12,10,8,.68) 0%, rgba(12,10,8,.42) 46%, rgba(12,10,8,.06) 74%), linear-gradient(200deg, rgba(12,10,8,0) 42%, rgba(12,10,8,.52) 96%); }
[data-theme-layout="dtc-journal"] .jnl-cover.has-img .jnl-cover-inner { position: relative; z-index: 1; grid-template-columns: minmax(0, 1fr); padding-inline: clamp(1.2rem, 3vw, 2.4rem); }
[data-theme-layout="dtc-journal"] .jnl-cover.has-img .jnl-h1 { color: #fff; } /* 全局 h1 色规则会盖过继承，压图必须显式白字 */
[data-theme-layout="dtc-journal"] .jnl-cover.has-img .jnl-rubric { color: #fff; opacity: .86; }
[data-theme-layout="dtc-journal"] .jnl-cover.has-img .jnl-rubric::before { background: #fff; }
[data-theme-layout="dtc-journal"] .jnl-cover.has-img .jnl-lede { color: rgba(255,255,255,.88); }
[data-theme-layout="dtc-journal"] .jnl-cover.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-journal"] .jnl-cover.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-journal"] .jnl-cover.has-img .btn-primary { background: #fff; border-color: #fff; color: #181410; }
/* 封面物：第一件商品图文并排，像杂志开篇的「本期封面物」板 */
[data-theme-layout="dtc-journal"] .jnl-cover-obj { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, .9fr); min-width: 0; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); box-shadow: var(--shadow); overflow: hidden; transition: border-color var(--speed); }
[data-theme-layout="dtc-journal"] .jnl-cover-obj:hover { border-color: var(--accent); color: var(--ink); }
[data-theme-layout="dtc-journal"] .jnl-obj-media { display: grid; place-items: center; aspect-ratio: 4 / 5; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-journal"] .jnl-obj-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .35s ease; }
[data-theme-layout="dtc-journal"] .jnl-cover-obj:hover .jnl-obj-media img { transform: scale(1.04); }
[data-theme-layout="dtc-journal"] .jnl-obj-body { display: flex; flex-direction: column; gap: .45rem; min-width: 0; padding: 1.1rem 1.15rem 1.05rem; border-left: 1px solid var(--line); }
[data-theme-layout="dtc-journal"] .jnl-obj-no { color: var(--accent); font-size: .7rem; font-weight: 800; letter-spacing: .22em; }
[data-theme-layout="dtc-journal"] .jnl-obj-title { font-family: var(--dt-display, var(--serif)); font-size: 1.18rem; font-weight: 650; line-height: 1.35; overflow-wrap: anywhere; }
[data-theme-layout="dtc-journal"] .jnl-obj-ex { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .85rem; line-height: 1.7; -webkit-box-orient: vertical; -webkit-line-clamp: 3; }
[data-theme-layout="dtc-journal"] .jnl-obj-go { margin-top: auto; padding-top: .6rem; color: var(--accent); font-size: .8rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-journal"] .jnl-cover-obj:hover .jnl-obj-go { color: var(--accent-soft); text-decoration: underline; text-underline-offset: 4px; }

/* ---- 栏目行（Categories）＋「本期选物」三栏条（上细线） ---- */
[data-theme-layout="dtc-journal"] .jnl-depts { display: flex; flex-wrap: wrap; justify-content: center; gap: .35rem 1.5rem; padding: .85rem 0 0; }
[data-theme-layout="dtc-journal"] .jnl-dept { display: inline-flex; align-items: baseline; gap: .4rem; min-width: 0; color: var(--ink-soft); font-size: .8rem; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; }
[data-theme-layout="dtc-journal"] .jnl-dept:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--accent); }
[data-theme-layout="dtc-journal"] .jnl-dept-name { overflow-wrap: anywhere; }
[data-theme-layout="dtc-journal"] .jnl-dept-n { color: var(--muted); font-size: .68rem; font-variant-numeric: tabular-nums; letter-spacing: 0; }
[data-theme-layout="dtc-journal"] .jnl-section, [data-theme-layout="dtc-journal"] .jnl-issue { padding-top: clamp(2.6rem, 5.5vw, 4rem); }
[data-theme-layout="dtc-journal"] .jnl-issue { margin-top: clamp(1.3rem, 3vw, 1.9rem); border-top: 1px solid var(--line); }
[data-theme-layout="dtc-journal"] .jnl-head h2 { font-weight: 700; }
[data-theme-layout="dtc-journal"] .dt-head > a:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--accent); }
[data-theme-layout="dtc-journal"] .jnl-issue-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: clamp(1.2rem, 2.6vw, 2rem); }
[data-theme-layout="dtc-journal"] .jnl-item { display: flex; flex-direction: column; gap: .35rem; min-width: 0; color: var(--ink); }
[data-theme-layout="dtc-journal"] .jnl-item:hover { color: var(--ink); }
[data-theme-layout="dtc-journal"] .jnl-item-media { display: grid; place-items: center; aspect-ratio: 4 / 5; border-radius: var(--radius); background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-journal"] .jnl-item-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-journal"] .jnl-item:hover .jnl-item-media img { transform: scale(1.05); }
[data-theme-layout="dtc-journal"] .jnl-item-cat { margin-top: .35rem; color: var(--accent); font-size: .7rem; font-weight: 750; letter-spacing: .16em; text-transform: uppercase; }
[data-theme-layout="dtc-journal"] .jnl-item-title { font-family: var(--dt-display, var(--serif)); font-size: 1.05rem; font-weight: 650; line-height: 1.4; overflow-wrap: anywhere; }
[data-theme-layout="dtc-journal"] .jnl-item:hover .jnl-item-title { text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--accent); }

/* ---- 刊末数据栏 / 读者来信引文 / FAQ / CTA：共享 dt-* 按刊物语言重排 ---- */
[data-theme-layout="dtc-journal"] .dt-stats { gap: 0; border-block: 1px solid var(--line); }
[data-theme-layout="dtc-journal"] .dt-stat { border: 0; border-left: 1px solid var(--line); border-radius: 0; background: transparent; padding: 1.3rem 1rem 1.15rem; }
[data-theme-layout="dtc-journal"] .dt-stat:first-child { border-left: 0; }
[data-theme-layout="dtc-journal"] .dt-testis { gap: clamp(1.4rem, 3vw, 2.4rem); }
[data-theme-layout="dtc-journal"] .dt-testi { border: 0; border-top: 2px solid var(--ink); border-radius: 0; background: transparent; padding: 1.1rem .1rem 0; }
[data-theme-layout="dtc-journal"] .dt-testi-quote { font-family: var(--serif); font-style: italic; font-size: 1.06rem; line-height: 1.9; }
[data-theme-layout="dtc-journal"] .dt-testi-mark { font-size: 2.6rem; }
[data-theme-layout="dtc-journal"] .dt-testi-ini { border-radius: 0; }
[data-theme-layout="dtc-journal"] .f-faq { border-top: 2px solid var(--ink); }
[data-theme-layout="dtc-journal"] .f-faq-q { font-family: var(--serif); font-size: 1.04rem; }
[data-theme-layout="dtc-journal"] .f-faq-q:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--accent); }
[data-theme-layout="dtc-journal"] .dt-cta-inner { border-radius: 0; border: 4px double var(--ink); }
[data-theme-layout="dtc-journal"] .pagination a:hover { border-color: var(--accent); color: var(--ink); }

/* ---- 内页 · 商品/内容列表（generic_list DOM）：图文编辑流，大图行左右交替 ---- */
[data-theme-layout="dtc-journal"] .page-head { padding: 2.4rem 0 0; border-bottom: 0; text-align: center; }
[data-theme-layout="dtc-journal"] .page-head .breadcrumb { justify-content: center; }
[data-theme-layout="dtc-journal"] .page-head .eyebrow { color: var(--accent); letter-spacing: .3em; }
[data-theme-layout="dtc-journal"] .page-head h1 { font-family: var(--serif); font-size: clamp(2.1rem, 4.6vw, 3.1rem); font-weight: 700; }
[data-theme-layout="dtc-journal"] .page-head p { margin-inline: auto; font-family: var(--serif); font-style: italic; }
[data-theme-layout="dtc-journal"] .page-head::after { content: ""; display: block; margin-top: 1.7rem; border-bottom: 4px double var(--ink); } /* 双线呼应刊头 */
[data-theme-layout="dtc-journal"] .cat-nav { justify-content: center; gap: .3rem 1.5rem; margin: 1.4rem 0 0; padding-bottom: .95rem; border-bottom: 1px solid var(--line); }
[data-theme-layout="dtc-journal"] .cat-nav a { padding: 0; border: 0; border-radius: 0; color: var(--ink-soft); font-size: .8rem; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; }
[data-theme-layout="dtc-journal"] .cat-nav a:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--accent); }
[data-theme-layout="dtc-journal"] .cat-nav a.active { background: transparent; color: var(--accent); box-shadow: 0 2px 0 var(--accent); }
[data-theme-layout="dtc-journal"] .link-grid { display: block; margin: 0 0 2.5rem; }
[data-theme-layout="dtc-journal"] .link-card { display: grid; grid-template-columns: minmax(0, 1.06fr) minmax(0, .94fr); gap: clamp(1.2rem, 3.5vw, 2.6rem); align-items: center; padding: clamp(1.4rem, 3.5vw, 2.2rem) 0; border: 0; border-top: 1px solid var(--line); border-radius: 0; background: transparent; overflow: visible; }
[data-theme-layout="dtc-journal"] .link-grid > .link-card:first-of-type { border-top: 0; }
[data-theme-layout="dtc-journal"] .link-card:hover { border-color: var(--line); box-shadow: none; transform: none; }
[data-theme-layout="dtc-journal"] .link-card:nth-of-type(even) .lc-cover { order: 2; } /* 大图行左右交替 */
[data-theme-layout="dtc-journal"] .lc-cover { aspect-ratio: 4 / 3; border-radius: var(--radius); }
[data-theme-layout="dtc-journal"] .lc-cover img { transition: transform .3s ease; }
[data-theme-layout="dtc-journal"] .link-card:hover .lc-cover img { transform: scale(1.03); }
[data-theme-layout="dtc-journal"] .lc-body { padding: 0; gap: .6rem; }
[data-theme-layout="dtc-journal"] .lc-title { justify-content: flex-start; font-family: var(--serif); font-size: clamp(1.3rem, 2.4vw, 1.7rem); font-weight: 650; }
[data-theme-layout="dtc-journal"] .link-card:hover .lc-title { text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--accent); }
[data-theme-layout="dtc-journal"] .lc-intro { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 3; flex: none; font-size: .95rem; line-height: 1.85; }
[data-theme-layout="dtc-journal"] .lc-title .lc-arrow { color: var(--accent); }
/* 条目编号：编辑流的「目录感」（计数器挂 lc-body 首位，不占 link-card 的网格轨道） */
[data-theme-layout="dtc-journal"] .link-grid { counter-reset: jnl-entry; }
[data-theme-layout="dtc-journal"] .link-card { counter-increment: jnl-entry; }
[data-theme-layout="dtc-journal"] .lc-body::before { content: "№ " counter(jnl-entry, decimal-leading-zero); order: -1; color: var(--accent); font-size: .7rem; font-weight: 800; letter-spacing: .22em; }
[data-theme-layout="dtc-journal"] .lc-foot { margin-top: .1rem; }
[data-theme-layout="dtc-journal"] .lc-foot .tag { padding: 0; border: 0; background: transparent; color: var(--accent); font-size: .72rem; font-weight: 750; letter-spacing: .16em; text-transform: uppercase; }
[data-theme-layout="dtc-journal"] .link-grid > .muted { margin: 2rem 0; text-align: center; font-family: var(--serif); font-style: italic; }
[data-theme-layout="dtc-journal"] .breadcrumb a:hover { color: var(--ink); } /* muted→ink 只升（noir 上 accent 会降） */
[data-theme-layout="dtc-journal"] .pagination a, [data-theme-layout="dtc-journal"] .pagination span { border-radius: 0; }

/* ---- 内页 · 商品详情（product_detail DOM）：杂志专题页——标题通栏居中、
   图集下移、正文窄栏、规格表右浮成卡（float 专属车道，720px 归位普通流） ---- */
[data-theme-layout="dtc-journal"] .pd-bc { text-align: center; }
[data-theme-layout="dtc-journal"] .pd-top { display: flex; flex-direction: column-reverse; gap: 1.9rem; }
[data-theme-layout="dtc-journal"] .pd-info { display: flex; flex-direction: column; align-items: center; text-align: center; }
[data-theme-layout="dtc-journal"] .pd-kicker { display: flex; align-items: center; gap: .7rem; font-family: var(--sans); font-size: .74rem; letter-spacing: .26em; }
[data-theme-layout="dtc-journal"] .pd-kicker::before, [data-theme-layout="dtc-journal"] .pd-kicker::after { content: ""; flex: none; width: 30px; height: 1px; background: var(--accent); }
[data-theme-layout="dtc-journal"] .pd-kicker a:hover { color: var(--accent-soft); text-decoration: underline; text-underline-offset: 4px; }
[data-theme-layout="dtc-journal"] .pd-title { max-width: 18em; font-family: var(--serif); font-size: clamp(1.9rem, 4.4vw, 3rem); font-weight: 700; line-height: 1.12; }
[data-theme-layout="dtc-journal"] .pd-lead { max-width: 58ch; color: var(--ink-soft); font-family: var(--serif); font-style: italic; line-height: 1.85; }
[data-theme-layout="dtc-journal"] .pd-meta { width: min(100%, 560px); border-top: 2px solid var(--ink); text-align: left; }
[data-theme-layout="dtc-journal"] .pd-inquiry { width: min(100%, 560px); border-radius: 0; }
[data-theme-layout="dtc-journal"] .pd-gallery { width: min(100%, 860px); margin: 0 auto; }
[data-theme-layout="dtc-journal"] .pd-media { aspect-ratio: 16 / 10; border-radius: var(--radius); }
[data-theme-layout="dtc-journal"] .pd-sec-title { font-family: var(--serif); }
[data-theme-layout="dtc-journal"] .pd-meta-row dt { font-size: .74rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }
[data-theme-layout="dtc-journal"] .pd-thumb { border-radius: 0; }
[data-theme-layout="dtc-journal"] .pd-thumb.is-active { border-color: var(--accent); }
[data-theme-layout="dtc-journal"] .pd-inquiry { text-align: center; }
[data-theme-layout="dtc-journal"] .pd-inquiry .inquiry-title { font-family: var(--serif); }
[data-theme-layout="dtc-journal"] .pd-specs { float: right; width: min(360px, 44%); margin: .4rem 0 1.4rem clamp(1.4rem, 3vw, 2.4rem); padding: 1.2rem 1.2rem 1rem; border: 1px solid var(--line); background: var(--surface); box-shadow: var(--shadow); }
[data-theme-layout="dtc-journal"] .pd-specs .pd-sec-title { margin-top: 0; font-size: 1.1rem; }
[data-theme-layout="dtc-journal"] .pd-specs-table th { font-size: .78rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--muted); }
[data-theme-layout="dtc-journal"] .pd-desc .prose { max-width: 68ch; } /* 正文窄栏；右侧留给规格卡的车道 */
/* 专题页首段首字下沉（杂志签名式；float 只吃自家段落，reduced-motion 无涉） */
[data-theme-layout="dtc-journal"] .pd-desc .prose > p:first-of-type::first-letter { float: left; padding: .12em .14em 0 0; font-family: var(--serif); font-size: 3.1em; font-weight: 700; line-height: .82; color: var(--accent); }
[data-theme-layout="dtc-journal"] .pd-related { clear: both; margin-top: 2.4rem; padding-top: 2.4rem; border-top: 1px solid var(--line); }
[data-theme-layout="dtc-journal"] .pd-related-head a:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--accent); }
[data-theme-layout="dtc-journal"] .pd-rel-media { aspect-ratio: 4 / 5; border-radius: var(--radius); }
[data-theme-layout="dtc-journal"] .pd-rel-title { font-family: var(--serif); font-weight: 650; }
[data-theme-layout="dtc-journal"] .pd-rel-card:hover .pd-rel-title { text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--accent); }

/* ---- 响应式：920 折两栏 / 720 单列归位，无横向溢出 ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-journal"] .jnl-cover-inner { grid-template-columns: 1fr; align-items: start; }
  [data-theme-layout="dtc-journal"] .jnl-cover-obj { max-width: 560px; }
  [data-theme-layout="dtc-journal"] .jnl-issue-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-journal"] .jnl-issue-grid { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-journal"] .jnl-cover-obj { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-journal"] .jnl-obj-body { border-left: 0; border-top: 1px solid var(--line); }
  [data-theme-layout="dtc-journal"] .jnl-cover.has-img { min-height: 60vh; }
  [data-theme-layout="dtc-journal"] .link-card { grid-template-columns: 1fr; gap: .9rem; }
  [data-theme-layout="dtc-journal"] .link-card:nth-of-type(even) .lc-cover { order: 0; } /* 交替归位 */
  [data-theme-layout="dtc-journal"] .pd-specs { float: none; width: 100%; margin: 0 0 1.4rem; } /* 右浮规格卡归位普通流 */
  [data-theme-layout="dtc-journal"] .pd-desc .prose { max-width: none; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-journal"] .jnl-obj-media img, [data-theme-layout="dtc-journal"] .jnl-item-media img,
  [data-theme-layout="dtc-journal"] .lc-cover img { transition: none; }
  [data-theme-layout="dtc-journal"] .jnl-cover-obj:hover .jnl-obj-media img,
  [data-theme-layout="dtc-journal"] .jnl-item:hover .jnl-item-media img,
  [data-theme-layout="dtc-journal"] .link-card:hover .lc-cover img { transform: none; }
}

/* ============================================================
   dtc-journal 皮肤 ×3（Category 一律 dtc；accent 均实算过 4.5:1）
   ============================================================ */
/* ---- 刊物店 · Journalshop（原生）：米白纸底 #fbfaf6 + 墨字 + 砖红 #a8352c ---- */
:root[data-theme="journalshop"] {
  --bg: #fbfaf6; --surface: #ffffff; --ink: #1c1a16; --ink-soft: #46423a;
  --muted: #6e6a5f; --faint: #a09a8c; --line: #e6e1d4; --line-soft: #f2eee3;
  --accent: #a8352c; --accent-soft: #872a23; --accent-wash: #f7ece7;
  --radius: 2px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(28,26,22,.05), 0 10px 26px rgba(28,26,22,.07);
}
/* ---- 刊物店 · Journalshop Noir（反差，暗）：墨黑底 + 米白字 + 提亮砖红 ---- */
:root[data-theme="journalshop-noir"] {
  --bg: #161411; --surface: #1e1b17; --ink: #f2ede1; --ink-soft: #cfc8b8;
  --muted: #a49d8d; --faint: #766f61; --line: #35312a; --line-soft: #26221d;
  --accent: #d4705d; --accent-soft: #e08a76; --accent-wash: #2c211c;
  --radius: 2px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(0,0,0,.4), 0 12px 30px rgba(0,0,0,.45);
}
/* 分页当前页：提亮砖红上白字只有 3.35——压成墨黑字（5.49） */
:root[data-theme="journalshop-noir"] .pagination .cur { color: #161411; }
/* ---- 刊物店 · Journalshop White（纯白）：中性灰基底对齐纯白系写法；
   muted 压深到 #666c76（#fafaf8 卡面 5.06，绕开 #707680 的 4.38 坑） ---- */
:root[data-theme="journalshop-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #666c76; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #a8352c; --accent-soft: #8c2b23; --accent-wash: #f9edea;
  --radius: 2px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(16,18,24,.04), 0 8px 22px rgba(16,18,24,.06);
}

/* =========================================================================
   LAYOUT: dtc-catalogue — 型录：印刷型录气质的外贸独立站。
   左侧常驻「品牌 + 主导航」竖栏（标准 .site-header 纯 CSS 重塑，≥921px；
   621~920px 收顶部横排；≤620px 交还基础汉堡抽屉——重塑段全包 min-width）。
   home：题签 + 分类索引竖栏（ctg-side）+ 编号行主区（No.NNN CSS counter +
   缩略图 + 规格签 + 右端箭头，行间细线）；FactoryStats=「产能行」横条。
   每条选择器限定 [data-theme-layout="dtc-catalogue"]，类名前缀 ctg-。
   ========================================================================= */

/* ---- 型录按钮语言：直角（压过族内胶囊倾向；印刷目录没有圆角） ---- */
[data-theme-layout="dtc-catalogue"] .btn,
[data-theme-layout="dtc-catalogue"] .inquiry-btn { border-radius: 0; }
[data-theme-layout="dtc-catalogue"] .f-chip { border-radius: 0; }

/* ---- 页头重塑：621~920px 顶部横排（印刷细则线 + 大写字距导航） ---- */
@media (min-width: 621px) {
  [data-theme-layout="dtc-catalogue"] .site-header {
    background: var(--bg);
    -webkit-backdrop-filter: none; backdrop-filter: none;
    border-bottom: 2px solid var(--ink);
  }
  [data-theme-layout="dtc-catalogue"] .nav a { font-size: .85rem; letter-spacing: .07em; text-transform: uppercase; }
  [data-theme-layout="dtc-catalogue"] .nav a[aria-current="page"]::after { bottom: -21px; height: 2px; background: var(--accent); }
}

/* ---- 页头重塑：≥921px 左侧常驻竖栏（body 让出车道，绝不横溢） ---- */
@media (min-width: 921px) {
  [data-theme-layout="dtc-catalogue"] { --ctg-rail: 232px; }
  [data-theme-layout="dtc-catalogue"] body { padding-left: var(--ctg-rail); }
  [data-theme-layout="dtc-catalogue"] .site-header {
    position: fixed; inset: 0 auto 0 0; width: var(--ctg-rail); height: 100vh;
    border-right: 1px solid var(--ink); border-bottom: 0;
    background: var(--surface); overflow-y: auto; z-index: 50;
  }
  [data-theme-layout="dtc-catalogue"] .site-header .wrap {
    flex-direction: column; align-items: stretch; justify-content: flex-start;
    width: auto; max-width: none; height: auto; min-height: 100%;
    margin: 0; padding: 30px 20px 22px; gap: 0;
  }
  [data-theme-layout="dtc-catalogue"] .site-header .brand {
    margin: 0; padding: 0 0 .9rem; border-bottom: 3px double var(--ink);
    font-size: 1.32rem; line-height: 1.25; letter-spacing: .01em;
  }
  [data-theme-layout="dtc-catalogue"] .site-header .brand-logo { height: 30px; width: auto; }
  [data-theme-layout="dtc-catalogue"] .brand-tagline { display: block; margin: .7rem 0 0; font-size: .78rem; line-height: 1.55; color: var(--muted); }
  /* 竖向主导航：编号目录条目（counter），行间细线 */
  [data-theme-layout="dtc-catalogue"] .nav {
    counter-reset: ctgnav;
    flex-direction: column; align-items: stretch; gap: 0; width: 100%; margin-top: 1.2rem;
  }
  [data-theme-layout="dtc-catalogue"] .nav > a {
    display: flex; align-items: baseline; gap: .55rem;
    padding: .58rem .1rem; border-bottom: 1px solid var(--line-soft); font-size: .86rem;
  }
  [data-theme-layout="dtc-catalogue"] .nav > a:not(.search-ico) { counter-increment: ctgnav; }
  [data-theme-layout="dtc-catalogue"] .nav > a:not(.search-ico)::before {
    content: counter(ctgnav, decimal-leading-zero);
    flex: none; color: var(--faint); font-family: var(--mono, monospace);
    font-size: .7rem; font-variant-numeric: tabular-nums;
  }
  [data-theme-layout="dtc-catalogue"] .nav a[aria-current="page"] { color: var(--accent); }
  [data-theme-layout="dtc-catalogue"] .nav a[aria-current="page"]::after { display: none; }
  [data-theme-layout="dtc-catalogue"] .nav a[aria-current="page"]:not(.search-ico)::before { color: var(--accent); }
  [data-theme-layout="dtc-catalogue"] .nav .search-ico { opacity: 1; color: var(--ink-soft); margin-top: .9rem; padding: .3rem 0; }
  [data-theme-layout="dtc-catalogue"] .search-label { display: inline; font-size: .84rem; }
  [data-theme-layout="dtc-catalogue"] .nav .lang-switch { align-self: stretch; width: 100%; margin: .5rem 0 0; padding: 0; border-left: 0; }
  [data-theme-layout="dtc-catalogue"] .nav .lang-switch summary { justify-content: flex-start; padding: .35rem 0; }
  [data-theme-layout="dtc-catalogue"] .nav .lang-menu { left: 0; right: auto; }
}

/* ---- home 骨架：竖栏 + 主区两栏（容器规约宽度，绝不自造） ---- */
[data-theme-layout="dtc-catalogue"] .ctg-wrap {
  width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 2rem 0 1rem;
  display: grid; grid-template-columns: minmax(216px, 258px) minmax(0, 1fr);
  gap: clamp(1.6rem, 4vw, 3.2rem); align-items: start;
}
[data-theme-layout="dtc-catalogue"] .ctg-side { position: sticky; top: 88px; min-width: 0; }
@media (min-width: 921px) { /* 左栏页头不占顶部高度，吸附位上移 */
  [data-theme-layout="dtc-catalogue"] .ctg-side { top: 24px; }
}

/* 题签：双框印刷牌（HeroTitle + 版次小字 = HeroEyebrow） */
[data-theme-layout="dtc-catalogue"] .ctg-plate {
  padding: 1.4rem 1.25rem 1.35rem; border: 1px solid var(--ink);
  outline: 1px solid var(--line); outline-offset: 3px; background: var(--surface);
}
[data-theme-layout="dtc-catalogue"] .ctg-h1 {
  margin: 0; font-family: var(--dt-display, var(--serif));
  font-size: clamp(1.45rem, 2.4vw, 1.9rem); font-weight: 650; line-height: 1.22; letter-spacing: .01em;
}
[data-theme-layout="dtc-catalogue"] .ctg-edition {
  margin: .75rem 0 0; padding-top: .65rem; border-top: 1px solid var(--line);
  color: var(--accent); font-family: var(--sans); font-size: .7rem; font-weight: 750;
  letter-spacing: .18em; text-transform: uppercase;
}
[data-theme-layout="dtc-catalogue"] .ctg-note {
  display: -webkit-box; overflow: hidden; margin: .6rem 0 0; color: var(--muted);
  font-size: .85rem; line-height: 1.75; -webkit-box-orient: vertical; -webkit-line-clamp: 4;
}
[data-theme-layout="dtc-catalogue"] .ctg-plate-cta { display: flex; flex-wrap: wrap; gap: .55rem; margin-top: 1.15rem; }
[data-theme-layout="dtc-catalogue"] .ctg-plate-cta .btn { padding: .55rem 1.05rem; font-size: .88rem; }

/* 卷首图版（hero image/svg 态）：细框衬纸小图，绝不全幅 */
[data-theme-layout="dtc-catalogue"] .ctg-figure { margin: 1rem 0 0; padding: 6px; border: 1px solid var(--line); background: var(--surface); }
[data-theme-layout="dtc-catalogue"] .ctg-figure img { display: block; width: 100%; height: auto; max-height: 240px; object-fit: cover; }

/* 分类索引：墨色顶线 + 行间细线 + 右端数目 */
[data-theme-layout="dtc-catalogue"] .ctg-index { margin-top: 1.3rem; border-top: 2px solid var(--ink); }
[data-theme-layout="dtc-catalogue"] .ctg-index-head {
  margin: 0; padding: .55rem .1rem .45rem; border-bottom: 1px solid var(--line);
  color: var(--muted); font-family: var(--sans); font-size: .68rem; font-weight: 750;
  letter-spacing: .2em; text-transform: uppercase;
}
[data-theme-layout="dtc-catalogue"] .ctg-index-item {
  display: flex; align-items: baseline; justify-content: space-between; gap: .6rem;
  padding: .55rem .1rem; border-bottom: 1px solid var(--line-soft);
  color: var(--ink-soft); font-size: .9rem; transition: color var(--speed);
}
[data-theme-layout="dtc-catalogue"] .ctg-index-item span { min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
[data-theme-layout="dtc-catalogue"] .ctg-index-item small { flex: none; color: var(--faint); font-family: var(--mono, monospace); font-size: .74rem; font-variant-numeric: tabular-nums; }
[data-theme-layout="dtc-catalogue"] .ctg-index-item:hover { color: var(--accent); }

/* ---- 主区：编号行（印刷型录的行式陈列） ---- */
[data-theme-layout="dtc-catalogue"] .ctg-main { min-width: 0; }
[data-theme-layout="dtc-catalogue"] .ctg-sec { padding-top: clamp(2.8rem, 5vw, 4rem); }
[data-theme-layout="dtc-catalogue"] .ctg-rows { counter-reset: ctgrow; border-top: 2px solid var(--ink); }
[data-theme-layout="dtc-catalogue"] .ctg-row {
  counter-increment: ctgrow;
  display: grid; grid-template-columns: auto 72px minmax(0, 1fr) auto; align-items: center;
  gap: clamp(.8rem, 2vw, 1.2rem); padding: .95rem .25rem;
  border-bottom: 1px solid var(--line); color: var(--ink); transition: background var(--speed);
}
/* No.NNN：首页最多 12 行，前导 0 拼出三位编号 */
[data-theme-layout="dtc-catalogue"] .ctg-row::before {
  content: "№ " counter(ctgrow, decimal-leading-zero);
  min-width: 3.6em; color: var(--accent); font-family: var(--mono, monospace);
  font-size: .74rem; font-weight: 700; letter-spacing: .04em; font-variant-numeric: tabular-nums;
}
[data-theme-layout="dtc-catalogue"] .ctg-thumb { display: grid; place-items: center; width: 72px; height: 72px; border: 1px solid var(--line); background: var(--surface); overflow: hidden; }
[data-theme-layout="dtc-catalogue"] .ctg-thumb img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-catalogue"] .ctg-thumb.dt-gen b { font-size: 1.4rem; }
[data-theme-layout="dtc-catalogue"] .ctg-row-body { min-width: 0; }
[data-theme-layout="dtc-catalogue"] .ctg-row-title { display: block; font-size: 1rem; font-weight: 650; line-height: 1.45; }
[data-theme-layout="dtc-catalogue"] .ctg-row .f-chips { margin-top: .4rem; }
[data-theme-layout="dtc-catalogue"] .ctg-row-arrow { color: var(--faint); transition: color var(--speed), transform var(--speed); }
[data-theme-layout="dtc-catalogue"] .ctg-row:hover { background: color-mix(in srgb, var(--accent-wash) 55%, transparent); }
[data-theme-layout="dtc-catalogue"] .ctg-row:hover .ctg-row-title { color: var(--accent); }
[data-theme-layout="dtc-catalogue"] .ctg-row:hover .ctg-row-arrow { color: var(--accent); transform: translateX(3px); }

/* 产能行（FactoryStats）：上下双细线横条，数字排一行 */
[data-theme-layout="dtc-catalogue"] .ctg-cap { margin-top: clamp(2.6rem, 5vw, 3.6rem); padding: 1.05rem 0; border-top: 2px solid var(--ink); border-bottom: 1px solid var(--ink); }
[data-theme-layout="dtc-catalogue"] .dt-stats { display: flex; flex-wrap: wrap; gap: .8rem 0; }
[data-theme-layout="dtc-catalogue"] .dt-stat { flex: 1 1 130px; min-width: 0; padding: .15rem 1.1rem; border: 0; border-left: 1px solid var(--line); border-radius: 0; background: transparent; text-align: left; }
[data-theme-layout="dtc-catalogue"] .dt-stat:first-child { border-left: 0; padding-left: .25rem; }
[data-theme-layout="dtc-catalogue"] .dt-stat dt { font-size: clamp(1.35rem, 2.2vw, 1.8rem); }
[data-theme-layout="dtc-catalogue"] .dt-stat dd { font-size: .8rem; }

/* 评价/CTA 收进印刷语言：直角 + 细框（文字色对儿已实算过审） */
[data-theme-layout="dtc-catalogue"] .dt-testi { border-radius: 0; }
[data-theme-layout="dtc-catalogue"] .dt-testi-ini { border-radius: 0; }
[data-theme-layout="dtc-catalogue"] .dt-cta-inner { border-radius: 0; border: 1px solid var(--ink); outline: 1px solid var(--line); outline-offset: 3px; }

/* ---- 内页 · 商品/内容列表（generic_list DOM）：同编号行母题 ---- */
[data-theme-layout="dtc-catalogue"] .page-head { padding: 2.6rem 0 1.5rem; border-bottom: 2px solid var(--ink); }
[data-theme-layout="dtc-catalogue"] .page-head h1 { font-family: var(--dt-display, var(--serif)); font-size: clamp(1.7rem, 3vw, 2.3rem); }
[data-theme-layout="dtc-catalogue"] .cat-nav { gap: 0 .2rem; margin: 1.5rem 0 0; border-bottom: 1px solid var(--line); }
[data-theme-layout="dtc-catalogue"] .cat-nav a {
  margin-bottom: -1px; padding: .5rem .85rem; border: 0; border-bottom: 2px solid transparent; border-radius: 0;
  color: var(--muted); font-size: .84rem; letter-spacing: .06em; text-transform: uppercase;
}
[data-theme-layout="dtc-catalogue"] .cat-nav a:hover { color: var(--accent); }
[data-theme-layout="dtc-catalogue"] .cat-nav a.active { background: transparent; color: var(--accent); border-bottom-color: currentColor; }
[data-theme-layout="dtc-catalogue"] .link-grid { display: block; margin: 0 0 2.4rem; counter-reset: ctglist; }
[data-theme-layout="dtc-catalogue"] .link-card {
  counter-increment: ctglist;
  display: grid; grid-template-columns: auto 84px minmax(0, 1fr); align-items: center;
  gap: clamp(.8rem, 2vw, 1.2rem); padding: 1rem .25rem;
  border: 0; border-bottom: 1px solid var(--line); border-radius: 0; background: transparent;
  overflow: visible; transition: background var(--speed);
}
[data-theme-layout="dtc-catalogue"] .link-card::before {
  content: "№ " counter(ctglist, decimal-leading-zero);
  min-width: 3.6em; color: var(--accent); font-family: var(--mono, monospace);
  font-size: .74rem; font-weight: 700; letter-spacing: .04em; font-variant-numeric: tabular-nums;
}
[data-theme-layout="dtc-catalogue"] .link-card:hover { transform: none; box-shadow: none; border-color: var(--line); background: color-mix(in srgb, var(--accent-wash) 55%, transparent); }
[data-theme-layout="dtc-catalogue"] .lc-cover { width: 84px; aspect-ratio: 1; border: 1px solid var(--line); background: var(--surface); }
[data-theme-layout="dtc-catalogue"] .lc-mono { background: var(--accent-wash); color: var(--accent); font-size: 1.6rem; }
[data-theme-layout="dtc-catalogue"] .lc-body { padding: 0; gap: .3rem; }
[data-theme-layout="dtc-catalogue"] .lc-title { font-size: 1.02rem; justify-content: flex-start; }
[data-theme-layout="dtc-catalogue"] .lc-arrow { margin-left: auto; opacity: 1; transform: none; color: var(--faint); }
[data-theme-layout="dtc-catalogue"] .link-card:hover .lc-title { color: var(--accent); }
[data-theme-layout="dtc-catalogue"] .link-card:hover .lc-arrow { color: var(--accent); }
[data-theme-layout="dtc-catalogue"] .lc-intro { display: -webkit-box; overflow: hidden; flex: none; color: var(--muted); font-size: .86rem; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="dtc-catalogue"] .lc-foot .tag { border-radius: 0; }
[data-theme-layout="dtc-catalogue"] .pagination :is(a, .cur) { border-radius: 0; }

/* ---- 内页 · 商品详情（product_detail DOM）：规格表=型录主角，双线表头 + 询单加重 ---- */
[data-theme-layout="dtc-catalogue"] .pd-main { padding-top: 1.4rem; }
[data-theme-layout="dtc-catalogue"] .pd-bc { padding-bottom: .8rem; border-bottom: 1px solid var(--line); font-size: .8rem; letter-spacing: .03em; }
[data-theme-layout="dtc-catalogue"] .pd-top { margin-top: 1.6rem; }
[data-theme-layout="dtc-catalogue"] .pd-media,
[data-theme-layout="dtc-catalogue"] .pd-thumb,
[data-theme-layout="dtc-catalogue"] .pd-rel-card,
[data-theme-layout="dtc-catalogue"] .pd-lightbox-figure img { border-radius: 0; }
[data-theme-layout="dtc-catalogue"] .pd-thumb.is-active { box-shadow: none; border: 2px solid var(--accent); }
[data-theme-layout="dtc-catalogue"] .pd-kicker { letter-spacing: .14em; }
[data-theme-layout="dtc-catalogue"] .pd-lead { font-size: .98rem; line-height: 1.75; }
[data-theme-layout="dtc-catalogue"] .pd-meta-row dd { font-variant-numeric: tabular-nums; }
[data-theme-layout="dtc-catalogue"] .pd-title { padding-bottom: .75rem; border-bottom: 2px solid var(--ink); font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-catalogue"] .pd-meta { border-top: 0; }
[data-theme-layout="dtc-catalogue"] .pd-meta-row dt { font-size: .78rem; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-catalogue"] .pd-sec-title { padding-bottom: .55rem; border-bottom: 3px double var(--ink); font-size: 1.15rem; letter-spacing: .04em; }
[data-theme-layout="dtc-catalogue"] .pd-specs-tablewrap { border: 0; border-radius: 0; background: transparent; border-bottom: 1px solid var(--ink); }
[data-theme-layout="dtc-catalogue"] .pd-specs-table th {
  width: 30%; background: transparent; color: var(--muted);
  font-family: var(--sans); font-size: .78rem; font-weight: 750; letter-spacing: .08em; text-transform: uppercase;
}
[data-theme-layout="dtc-catalogue"] .pd-specs-table td { font-variant-numeric: tabular-nums; }
[data-theme-layout="dtc-catalogue"] .pd-specs-table tr:last-child :is(th, td) { border-bottom: 0; }
/* 询单区：双框加重 + 按钮放大加粗（inquiry-wa 走族规 ink 底 surface 字，对比最高对儿） */
[data-theme-layout="dtc-catalogue"] .pd-inquiry { padding: 1.15rem 1.15rem 1.3rem; border: 1px solid var(--ink); outline: 1px solid var(--line); outline-offset: 3px; background: var(--surface); }
[data-theme-layout="dtc-catalogue"] .pd-inquiry .inquiry-btn { padding: .74rem 1.25rem; border-width: 2px; border-color: var(--ink); font-size: .95rem; font-weight: 700; }
/* 长文与相关商品：正文钳宽、相关卡收进印刷框（悬停不浮起，描边压深） */
[data-theme-layout="dtc-catalogue"] .pd-desc .prose { max-width: 78ch; }
[data-theme-layout="dtc-catalogue"] .pd-related-head { border-bottom: 3px double var(--ink); padding-bottom: .55rem; margin-bottom: 1.1rem; }
[data-theme-layout="dtc-catalogue"] .pd-related-head .pd-sec-title { border-bottom: 0; padding-bottom: 0; }
[data-theme-layout="dtc-catalogue"] .pd-rel-card:hover { transform: none; border-color: var(--accent); }
[data-theme-layout="dtc-catalogue"] .pd-rel-media { background: var(--line-soft); }
[data-theme-layout="dtc-catalogue"] .pd-rel-title { font-weight: 650; }

/* ---- 响应式：920 收单列（索引横排）、720 行收窄，绝不横向溢出 ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-catalogue"] .ctg-wrap { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-catalogue"] .ctg-side { position: static; }
  [data-theme-layout="dtc-catalogue"] .ctg-figure img { max-height: 300px; }
  [data-theme-layout="dtc-catalogue"] .ctg-index { display: flex; flex-wrap: wrap; gap: .45rem; padding-top: .8rem; }
  [data-theme-layout="dtc-catalogue"] .ctg-index-head { flex: 1 1 100%; border-bottom: 0; padding: 0 0 .1rem; }
  [data-theme-layout="dtc-catalogue"] .ctg-index-item { gap: .45rem; padding: .4rem .75rem; border: 1px solid var(--line); background: var(--surface); font-size: .86rem; }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-catalogue"] .ctg-row { grid-template-columns: auto 56px minmax(0, 1fr); }
  [data-theme-layout="dtc-catalogue"] .ctg-row-arrow { display: none; }
  [data-theme-layout="dtc-catalogue"] .ctg-thumb { width: 56px; height: 56px; }
  [data-theme-layout="dtc-catalogue"] .dt-stat { flex-basis: 40%; border-left: 0; padding-left: .25rem; }
  [data-theme-layout="dtc-catalogue"] .link-card { grid-template-columns: auto 64px minmax(0, 1fr); }
  [data-theme-layout="dtc-catalogue"] .lc-cover { width: 64px; }
  [data-theme-layout="dtc-catalogue"] .lc-arrow { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-catalogue"] :is(.ctg-row, .ctg-row-arrow, .ctg-index-item, .link-card, .lc-arrow) { transition: none; }
  [data-theme-layout="dtc-catalogue"] .ctg-row:hover .ctg-row-arrow { transform: none; }
}

/* =========================================================================
   dtc-catalogue 皮肤 ×3。全变量成套覆写（:root[data-theme=…] 锁定调色板，
   不随 OS 亮暗漂移）；全部关键对儿逐一实算 WCAG（见各皮注释数字）。
   ========================================================================= */

/* ---- 型录 · Catalogue（原生）：象牙纸 + 墨 + 暗金。
   实算：ink/bg 14.64、ink/surface 15.57、ink-soft/bg 8.63、muted/bg 5.26、
   muted/surface 5.60、muted/wash 4.78、accent/bg 5.52、accent/surface 5.87、
   accent/wash 5.01、hover accent-soft/bg 7.54（只升）、按钮 ink底/surface字 15.57。
   任务书示意的 #8a6a1f 在象牙底不足 4.5，压深为 #7c5c10 保住暗金色相。 ---- */
:root[data-theme="catalogue"] {
  --bg: #f4f2ec; --surface: #fbf9f3; --ink: #241f14; --ink-soft: #4b4433;
  --muted: #6b6450; --faint: #98917c; --line: #dbd5c3; --line-soft: #eae5d6;
  --accent: #7c5c10; --accent-soft: #63490c; --accent-wash: #efe7d1;
  --radius: 2px; --w-wide: 1200px;
  --shadow: 0 1px 2px rgba(36, 31, 20, .05), 0 10px 26px rgba(36, 31, 20, .07);
}

/* ---- 型录 · 夜览 Catalogue Noir（深反差）：深炭 + 暗金。
   实算：ink/bg 14.74、ink/surface 13.79、ink-soft/bg 10.43、muted/bg 6.61、
   muted/surface 6.19、muted/wash 5.72、accent/bg 7.86、accent/surface 7.35、
   accent/wash 6.80、hover accent-soft/bg 9.80（只升）、按钮对儿 13.79。 ---- */
:root[data-theme="catalogue-noir"] {
  --bg: #15130e; --surface: #1d1a13; --ink: #ebe5d3; --ink-soft: #c9c2ac;
  --muted: #a29a82; --faint: #6e6753; --line: #39331f; --line-soft: #262114;
  --accent: #c9a44a; --accent-soft: #d9b968; --accent-wash: #262112;
  --radius: 2px; --w-wide: 1200px;
  --shadow: 0 1px 2px rgba(0, 0, 0, .5), 0 12px 30px rgba(0, 0, 0, .45);
}

/* ---- 型录 · 纯白 Catalogue White：中性灰基底 + 暗金压深。
   实算：ink/bg 18.72、ink/surface 17.91、ink-soft/bg 9.79、muted/bg 5.45、
   muted/surface(#fafaf8) 5.21（--muted 全局压深到 #646a74，卡面坑已除）、
   muted/wash 4.82、accent/bg 6.25、accent/surface 5.98、accent/wash 5.53、
   hover accent-soft/bg 8.52（只升）、按钮对儿 17.91。 ---- */
:root[data-theme="catalogue-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #646a74; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #7a5c08; --accent-soft: #61490a; --accent-wash: #f7f1dd;
  --radius: 2px; --w-wide: 1200px;
  --shadow: 0 1px 2px rgba(16, 18, 24, .04), 0 8px 22px rgba(16, 18, 24, .05);
}

/* ============================================================================
   dtc-bazaar 骨架（bzr-*）：「集市」——红布条横幅页头 + 开市词居中 hero +
   木牌胶囊分类排 + 摊位卡三列（条纹摊棚 + 斜放手写价签）。
   每条选择器限定 [data-theme-layout="dtc-bazaar"]；容器规约同族。
   皮肤 ×3：bazaar（麻布米+摊红+木棕）/ bazaar-noir（夜市深棕+灯串暖黄）/ bazaar-white。
   ========================================================================== */
[data-theme-layout="dtc-bazaar"] { --bzr-hand: "Segoe Print", "Bradley Hand", "Chalkboard SE", "Comic Sans MS", "PingFang SC", "Hiragino Sans GB", cursive; }
[data-theme-layout="dtc-bazaar"] .bzr-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }

/* ---- 页头=红布条横幅（只准 CSS 重塑标准 .site-header；≤620px 交还基础汉堡抽屉） ----
   布条画在 .wrap::before（裁角 clip-path 燕尾两端）——不能直接 clip .wrap，
   否则语言切换的下拉弹层会被裁掉；站名+链接白字居中，noir 皮加灯串圆点层。 */
@media (min-width: 621px) {
  [data-theme-layout="dtc-bazaar"] .site-header { position: static; background: transparent; border-bottom: 0; -webkit-backdrop-filter: none; backdrop-filter: none; padding: 1rem 0 .9rem; }
  [data-theme-layout="dtc-bazaar"] .site-header .wrap { position: relative; z-index: 0; height: auto; flex-direction: column; justify-content: center; gap: .55rem; padding: 1.05rem 3.4rem 1.2rem; }
  [data-theme-layout="dtc-bazaar"] .site-header .wrap::before {
    content: ""; position: absolute; inset: 0; z-index: -1;
    background:
      radial-gradient(3.5px at 22px 9px, var(--bzr-lamp, transparent) 55%, transparent 62%) 0 0 / 44px 20px repeat-x,
      linear-gradient(180deg, rgba(255,255,255,.15), rgba(255,255,255,0) 38%),
      var(--bzr-cloth);
    clip-path: polygon(0 0, 100% 0, calc(100% - 26px) 50%, 100% 100%, 0 100%, 26px 50%);
    box-shadow: var(--shadow);
  }
  [data-theme-layout="dtc-bazaar"] .site-header .brand,
  [data-theme-layout="dtc-bazaar"] .site-header .brand-name { color: var(--bzr-cloth-ink); }
  [data-theme-layout="dtc-bazaar"] .site-header .nav { gap: 1.35rem; flex-wrap: wrap; justify-content: center; }
  [data-theme-layout="dtc-bazaar"] .site-header .nav a { color: color-mix(in srgb, var(--bzr-cloth-ink) 88%, var(--bzr-cloth)); }
  [data-theme-layout="dtc-bazaar"] .site-header .nav a:hover { color: var(--bzr-cloth-ink); }
  [data-theme-layout="dtc-bazaar"] .site-header .nav a[aria-current="page"] { color: var(--bzr-cloth-ink); }
  [data-theme-layout="dtc-bazaar"] .site-header .nav a[aria-current="page"]::after { bottom: -7px; height: 2px; background: var(--bzr-cloth-ink); }
  [data-theme-layout="dtc-bazaar"] .site-header .nav .search-ico { color: var(--bzr-cloth-ink); opacity: .85; }
  [data-theme-layout="dtc-bazaar"] .site-header .nav .search-ico:hover { opacity: 1; }
  [data-theme-layout="dtc-bazaar"] .site-header .lang-switch summary,
  [data-theme-layout="dtc-bazaar"] .site-header .lang-cur { color: var(--bzr-cloth-ink); }
}

/* ---- hero：布幅下一行开市词（全部居中；三态照 flagship） ---- */
[data-theme-layout="dtc-bazaar"] .bzr-hero { position: relative; margin-top: .6rem; border-radius: calc(var(--radius) * 1.4); background: linear-gradient(180deg, var(--accent-wash), var(--surface)); overflow: hidden; text-align: center; }
[data-theme-layout="dtc-bazaar"] .bzr-hero-inner { position: relative; z-index: 1; max-width: 62rem; margin: 0 auto; padding: clamp(2.2rem, 5vw, 3.8rem) clamp(1.2rem, 4vw, 3rem); }
[data-theme-layout="dtc-bazaar"] .bzr-h1 { margin: 0 auto; max-width: 18em; font-family: var(--dt-display, var(--serif)); font-size: clamp(2rem, 4.4vw, 3.2rem); font-weight: 650; line-height: 1.14; letter-spacing: -.01em; }
[data-theme-layout="dtc-bazaar"] .bzr-lede { max-width: 52ch; margin: .95rem auto 0; color: var(--muted); font-size: 1.02rem; line-height: 1.8; }
[data-theme-layout="dtc-bazaar"] .bzr-cta { display: flex; flex-wrap: wrap; justify-content: center; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="dtc-bazaar"] .bzr-hero-side { width: min(100%, 460px); margin: 1.9rem auto 0; }
[data-theme-layout="dtc-bazaar"] .bzr-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
/* 压图 scrim：居中白字，最劣（纯白底图）取 α.56 段仍 4.58:1，边缘 .66 更高 */
[data-theme-layout="dtc-bazaar"] .bzr-hero.has-img { min-height: min(66vh, 540px); display: grid; align-items: center; }
[data-theme-layout="dtc-bazaar"] .bzr-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(12,9,7,.66), rgba(12,9,7,.56) 55%, rgba(12,9,7,.66)); }
[data-theme-layout="dtc-bazaar"] .bzr-hero.has-img .bzr-hero-inner { z-index: 1; }
[data-theme-layout="dtc-bazaar"] .bzr-hero.has-img .dt-eyebrow { color: #fff; opacity: .85; }
[data-theme-layout="dtc-bazaar"] .bzr-hero.has-img .bzr-h1 { color: #fff; } /* 全局 h1 色规则会盖过继承 */
[data-theme-layout="dtc-bazaar"] .bzr-hero.has-img .bzr-lede { color: rgba(255,255,255,.88); }
[data-theme-layout="dtc-bazaar"] .bzr-hero.has-img .btn-primary { background: #fff; border-color: #fff; color: #241408; }
[data-theme-layout="dtc-bazaar"] .bzr-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-bazaar"] .bzr-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }

/* ---- 分类=木牌胶囊排（木纹渐变 + 交替微倾 + 钉点） ---- */
[data-theme-layout="dtc-bazaar"] .bzr-planks { display: flex; flex-wrap: wrap; justify-content: center; gap: .75rem .85rem; margin-top: clamp(1.8rem, 4vw, 2.6rem); }
[data-theme-layout="dtc-bazaar"] .bzr-plank { position: relative; display: inline-flex; align-items: center; gap: .5rem; min-width: 0; max-width: 100%; padding: .55rem 1.5rem; border: 1px solid color-mix(in srgb, var(--bzr-wood) 70%, #000); border-radius: 9px; background: linear-gradient(180deg, color-mix(in srgb, var(--bzr-wood) 86%, #fff), var(--bzr-wood) 46%, color-mix(in srgb, var(--bzr-wood) 84%, #000)); color: var(--bzr-wood-ink); font-weight: 650; font-size: .93rem; line-height: 1.4; box-shadow: 0 2px 0 color-mix(in srgb, var(--bzr-wood) 58%, #000), var(--shadow); transition: transform var(--speed), box-shadow var(--speed); }
[data-theme-layout="dtc-bazaar"] .bzr-plank::before,
[data-theme-layout="dtc-bazaar"] .bzr-plank::after { content: ""; position: absolute; top: 50%; width: 5px; height: 5px; margin-top: -2.5px; border-radius: 50%; background: color-mix(in srgb, var(--bzr-wood-ink) 55%, var(--bzr-wood)); }
[data-theme-layout="dtc-bazaar"] .bzr-plank::before { left: 8px; }
[data-theme-layout="dtc-bazaar"] .bzr-plank::after { right: 8px; }
[data-theme-layout="dtc-bazaar"] .bzr-plank:nth-child(odd) { transform: rotate(-1.3deg); }
[data-theme-layout="dtc-bazaar"] .bzr-plank:nth-child(even) { transform: rotate(1.2deg); }
[data-theme-layout="dtc-bazaar"] .bzr-plank:hover { transform: rotate(0) translateY(-2px); color: var(--bzr-wood-ink); }
[data-theme-layout="dtc-bazaar"] .bzr-plank small { font-size: .74em; font-weight: 750; color: inherit; }

/* ---- 商品=摊位卡三列（顶部条纹摊棚 + 荷叶边 + 斜放手写价签） ---- */
[data-theme-layout="dtc-bazaar"] .bzr-section { padding-top: clamp(2.8rem, 6vw, 4.2rem); }
[data-theme-layout="dtc-bazaar"] .bzr-stalls { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.2rem; }
[data-theme-layout="dtc-bazaar"] .bzr-stall { position: relative; display: flex; flex-direction: column; min-width: 0; border: 1px solid var(--line); border-radius: calc(var(--radius) * 1.1); background: var(--surface); color: var(--ink); transition: transform var(--speed), box-shadow var(--speed), border-color var(--speed); }
[data-theme-layout="dtc-bazaar"] .bzr-stall:hover { transform: translateY(-3px); border-color: var(--accent); box-shadow: var(--shadow); color: var(--ink); }
[data-theme-layout="dtc-bazaar"] .bzr-awning { position: relative; flex: none; height: 16px; border-radius: calc(var(--radius) * 1.1) calc(var(--radius) * 1.1) 0 0; background: repeating-linear-gradient(90deg, var(--bzr-awning-a) 0 18px, var(--bzr-awning-b) 18px 36px); }
[data-theme-layout="dtc-bazaar"] .bzr-awning::after { content: ""; position: absolute; top: 100%; left: 0; right: 0; height: 7px; z-index: 1; background: repeating-linear-gradient(90deg, var(--bzr-awning-a) 0 18px, var(--bzr-awning-b) 18px 36px); -webkit-mask: radial-gradient(7px at 9px 0, #000 97%, transparent) 0 0 / 18px 7px repeat-x; mask: radial-gradient(7px at 9px 0, #000 97%, transparent) 0 0 / 18px 7px repeat-x; }
[data-theme-layout="dtc-bazaar"] .bzr-stall-media { display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-bazaar"] .bzr-stall-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-bazaar"] .bzr-stall:hover .bzr-stall-media img { transform: scale(1.04); }
/* 价签：绝对定位压图面右上（专属车道=图区，无文字冲突）；手写体 + 斜放 + 麻绳孔 */
[data-theme-layout="dtc-bazaar"] .bzr-tag { position: absolute; top: 30px; right: 10px; z-index: 2; display: inline-flex; align-items: baseline; gap: .35rem; max-width: 74%; padding: .3rem .8rem .3rem 1.15rem; border: 1px dashed var(--accent); border-radius: 4px 12px 12px 4px; background: var(--bzr-tag-bg); color: var(--bzr-tag-ink); font-family: var(--bzr-hand); font-size: .8rem; line-height: 1.5; transform: rotate(6deg); box-shadow: var(--shadow); }
[data-theme-layout="dtc-bazaar"] .bzr-tag::before { content: ""; position: absolute; left: .38rem; top: 50%; width: 6px; height: 6px; margin-top: -3px; border: 1.5px solid var(--accent); border-radius: 50%; }
[data-theme-layout="dtc-bazaar"] .bzr-tag b { flex: none; font-weight: 700; color: var(--accent); }
[data-theme-layout="dtc-bazaar"] .bzr-tag i { font-style: normal; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
[data-theme-layout="dtc-bazaar"] .bzr-stall-body { display: flex; flex-direction: column; gap: .3rem; padding: .95rem 1.05rem 1.1rem; }
[data-theme-layout="dtc-bazaar"] .bzr-stall-title { font-size: 1rem; font-weight: 700; line-height: 1.45; }
[data-theme-layout="dtc-bazaar"] .bzr-stall:hover .bzr-stall-title { color: var(--accent); }
[data-theme-layout="dtc-bazaar"] .bzr-stall-ex { display: -webkit-box; overflow: hidden; color: var(--ink-soft); font-size: .85rem; line-height: 1.6; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }

/* ---- 摊主故事（stats 空回落站点简介，说书体居中） ---- */
[data-theme-layout="dtc-bazaar"] .bzr-about { max-width: 62ch; margin: 0 auto; text-align: center; font-family: var(--dt-display, var(--serif)); font-size: clamp(1.02rem, 1.8vw, 1.26rem); line-height: 2; color: var(--ink-soft); }

/* ---- 内页 · 商品列表（generic_list 的 DOM）：列表形态跟随母题=摊位卡 ---- */
[data-theme-layout="dtc-bazaar"] .page-head { border-bottom: 0; padding: 2.6rem 0 1.1rem; text-align: center; }
[data-theme-layout="dtc-bazaar"] .page-head p { margin: 0 auto; }
[data-theme-layout="dtc-bazaar"] .page-head .breadcrumb { justify-content: center; }
[data-theme-layout="dtc-bazaar"] .page-head h1 { font-family: var(--dt-display, var(--serif)); letter-spacing: -.01em; }
[data-theme-layout="dtc-bazaar"] .page-head h1::after { content: ""; display: block; width: min(220px, 60%); height: 6px; margin: .9rem auto 0; border-radius: 3px; background: repeating-linear-gradient(90deg, var(--bzr-awning-a) 0 14px, var(--bzr-awning-b) 14px 28px); }
[data-theme-layout="dtc-bazaar"] .page-head .hero-sub { max-width: 56ch; }
[data-theme-layout="dtc-bazaar"] .cat-nav { justify-content: center; gap: .7rem .8rem; }
[data-theme-layout="dtc-bazaar"] .cat-nav a { border: 1px solid color-mix(in srgb, var(--bzr-wood) 70%, #000); border-radius: 9px; background: linear-gradient(180deg, color-mix(in srgb, var(--bzr-wood) 86%, #fff), var(--bzr-wood) 46%, color-mix(in srgb, var(--bzr-wood) 84%, #000)); color: var(--bzr-wood-ink); font-weight: 650; box-shadow: 0 2px 0 color-mix(in srgb, var(--bzr-wood) 58%, #000); }
[data-theme-layout="dtc-bazaar"] .cat-nav a:nth-child(odd) { transform: rotate(-1.2deg); }
[data-theme-layout="dtc-bazaar"] .cat-nav a:nth-child(even) { transform: rotate(1.1deg); }
[data-theme-layout="dtc-bazaar"] .cat-nav a:hover { transform: rotate(0); border-color: color-mix(in srgb, var(--bzr-wood) 70%, #000); color: var(--bzr-wood-ink); }
[data-theme-layout="dtc-bazaar"] .cat-nav a .muted { color: inherit; }
[data-theme-layout="dtc-bazaar"] .cat-nav a.active { background: var(--bzr-cloth); border-color: color-mix(in srgb, var(--bzr-cloth) 72%, #000); color: var(--bzr-cloth-ink); }
[data-theme-layout="dtc-bazaar"] .cat-nav a.active .muted { color: inherit; opacity: 1; }
[data-theme-layout="dtc-bazaar"] .link-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.2rem; }
[data-theme-layout="dtc-bazaar"] .link-card { position: relative; overflow: visible; border-radius: calc(var(--radius) * 1.1); }
[data-theme-layout="dtc-bazaar"] .link-card::before { content: ""; flex: none; height: 14px; border-radius: calc(var(--radius) * 1.1) calc(var(--radius) * 1.1) 0 0; background: repeating-linear-gradient(90deg, var(--bzr-awning-a) 0 18px, var(--bzr-awning-b) 18px 36px); }
[data-theme-layout="dtc-bazaar"] .link-card::after { content: ""; position: absolute; top: 14px; left: 0; right: 0; height: 7px; z-index: 1; background: repeating-linear-gradient(90deg, var(--bzr-awning-a) 0 18px, var(--bzr-awning-b) 18px 36px); -webkit-mask: radial-gradient(7px at 9px 0, #000 97%, transparent) 0 0 / 18px 7px repeat-x; mask: radial-gradient(7px at 9px 0, #000 97%, transparent) 0 0 / 18px 7px repeat-x; }
[data-theme-layout="dtc-bazaar"] .link-card:hover { border-color: var(--accent); }
[data-theme-layout="dtc-bazaar"] .lc-cover { border-radius: 0; }
[data-theme-layout="dtc-bazaar"] .lc-body { border-radius: 0 0 calc(var(--radius) * 1.1) calc(var(--radius) * 1.1); }
[data-theme-layout="dtc-bazaar"] .lc-title { font-size: 1rem; font-weight: 700; }
[data-theme-layout="dtc-bazaar"] .lc-arrow { color: var(--accent); }
[data-theme-layout="dtc-bazaar"] .lc-intro { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 3; }
[data-theme-layout="dtc-bazaar"] .lc-foot .tag { display: inline-block; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; padding: .26rem .75rem; border: 1px dashed var(--accent); border-radius: 4px 12px 12px 4px; background: var(--bzr-tag-bg); color: var(--bzr-tag-ink); font-family: var(--bzr-hand); font-size: .78rem; transform: rotate(-2deg); }
[data-theme-layout="dtc-bazaar"] .lc-mono { color: var(--bzr-on-accent, #fff); }
[data-theme-layout="dtc-bazaar"] .pagination a, [data-theme-layout="dtc-bazaar"] .pagination span { border-radius: 9px; }
[data-theme-layout="dtc-bazaar"] .pagination .cur { background: var(--accent); border-color: var(--accent); color: var(--bzr-on-accent, #fff); }

/* ---- 内页 · 商品详情（product_detail 的 DOM）：摊主故事块 + 大按钮询价 CTA ---- */
[data-theme-layout="dtc-bazaar"] .pd-bc { padding-bottom: 1.1rem; }
[data-theme-layout="dtc-bazaar"] .pd-gallery::before { content: ""; display: block; height: 14px; margin-bottom: .7rem; border-radius: 7px; background: repeating-linear-gradient(90deg, var(--bzr-awning-a) 0 18px, var(--bzr-awning-b) 18px 36px); }
[data-theme-layout="dtc-bazaar"] .pd-media { border-radius: calc(var(--radius) * 1.1); }
[data-theme-layout="dtc-bazaar"] .pd-thumb { border-radius: 8px; }
[data-theme-layout="dtc-bazaar"] .pd-kicker { font-family: var(--bzr-hand); font-size: .95rem; letter-spacing: .02em; text-transform: none; }
[data-theme-layout="dtc-bazaar"] .pd-title { font-family: var(--dt-display, var(--serif)); letter-spacing: -.01em; }
[data-theme-layout="dtc-bazaar"] .pd-lead { color: var(--ink-soft); }
[data-theme-layout="dtc-bazaar"] .pd-meta { border-top: 2px dashed var(--line); }
[data-theme-layout="dtc-bazaar"] .pd-meta-row { border-bottom: 1px dashed var(--line-soft); }
[data-theme-layout="dtc-bazaar"] .pd-sec-title { font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-bazaar"] .pd-specs .pd-sec-title::after, [data-theme-layout="dtc-bazaar"] .pd-related .pd-sec-title::after { content: ""; display: block; width: 64px; height: 5px; margin-top: .45rem; border-radius: 3px; background: repeating-linear-gradient(90deg, var(--bzr-awning-a) 0 12px, var(--bzr-awning-b) 12px 24px); }
/* 询价 CTA：整卡提亮 + 摊棚条 + 大按钮（转化主动作放大） */
[data-theme-layout="dtc-bazaar"] .pd-inquiry { position: relative; overflow: hidden; padding: 1.9rem 1.5rem 1.5rem; border: 1px solid var(--line); border-radius: calc(var(--radius) * 1.1); background: var(--accent-wash); }
[data-theme-layout="dtc-bazaar"] .pd-inquiry::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 10px; background: repeating-linear-gradient(90deg, var(--bzr-awning-a) 0 18px, var(--bzr-awning-b) 18px 36px); }
[data-theme-layout="dtc-bazaar"] .pd-inquiry .inquiry-title { font-family: var(--dt-display, var(--serif)); font-size: 1.32rem; }
[data-theme-layout="dtc-bazaar"] .pd-inquiry .inquiry-note { color: var(--ink-soft); }
[data-theme-layout="dtc-bazaar"] .pd-inquiry .inquiry-actions { gap: .8rem; }
[data-theme-layout="dtc-bazaar"] .pd-inquiry .inquiry-btn { padding: .85rem 1.5rem; font-size: 1.02rem; font-weight: 700; }
[data-theme-layout="dtc-bazaar"] .pd-specs-tablewrap { border-radius: calc(var(--radius) * 1.1); }
[data-theme-layout="dtc-bazaar"] .pd-specs-table th { color: var(--ink-soft); background: color-mix(in srgb, var(--bzr-wood) 10%, var(--surface)); }
/* 摊主故事块：正文卡装裱 + 首字下沉（说书开笔） */
[data-theme-layout="dtc-bazaar"] .pd-desc { position: relative; overflow: hidden; padding: clamp(1.5rem, 3vw, 2.2rem) clamp(1.2rem, 3vw, 2rem) 1.6rem; border: 1px solid var(--line); border-radius: calc(var(--radius) * 1.1); background: var(--surface); }
[data-theme-layout="dtc-bazaar"] .pd-desc::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 10px; background: repeating-linear-gradient(90deg, var(--bzr-awning-a) 0 18px, var(--bzr-awning-b) 18px 36px); }
[data-theme-layout="dtc-bazaar"] .pd-desc .prose > p:first-child::first-letter { float: left; margin: .06em .14em 0 0; font-family: var(--dt-display, var(--serif)); font-size: 2.9em; line-height: .9; color: var(--accent); }
[data-theme-layout="dtc-bazaar"] .pd-related-head > a:hover { color: var(--accent); }
[data-theme-layout="dtc-bazaar"] .pd-rel-card { border-radius: calc(var(--radius) * 1.1); }
[data-theme-layout="dtc-bazaar"] .pd-rel-card:hover { border-color: var(--accent); }
[data-theme-layout="dtc-bazaar"] .pd-rel-card::before { content: ""; flex: none; height: 10px; background: repeating-linear-gradient(90deg, var(--bzr-awning-a) 0 18px, var(--bzr-awning-b) 18px 36px); }
[data-theme-layout="dtc-bazaar"] .pd-rel-title { font-weight: 700; }

/* ---- 响应式：920 两列 / 720 单列，价签归位普通流，绝无横向溢出 ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-bazaar"] .bzr-stalls { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="dtc-bazaar"] .link-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-bazaar"] .bzr-stalls { grid-template-columns: 1fr; gap: 1rem; }
  [data-theme-layout="dtc-bazaar"] .link-grid { grid-template-columns: 1fr; }
  /* 价签归位普通流：摊棚→图→价签→卡身（order 定序），不再压图斜放 */
  [data-theme-layout="dtc-bazaar"] .bzr-tag { position: static; align-self: flex-start; margin: .7rem 1.05rem 0; transform: rotate(-1.5deg); max-width: calc(100% - 2.1rem); order: 1; }
  [data-theme-layout="dtc-bazaar"] .bzr-awning { order: -1; }
  [data-theme-layout="dtc-bazaar"] .bzr-stall-media { order: 0; }
  [data-theme-layout="dtc-bazaar"] .bzr-stall-body { order: 2; }
  [data-theme-layout="dtc-bazaar"] .bzr-hero.has-img { min-height: 58vh; }
  [data-theme-layout="dtc-bazaar"] .bzr-hero-inner { padding: clamp(1.6rem, 5vw, 2.4rem) 1.1rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-bazaar"] .bzr-stall, [data-theme-layout="dtc-bazaar"] .bzr-plank,
  [data-theme-layout="dtc-bazaar"] .bzr-stall-media img { transition: none; }
  [data-theme-layout="dtc-bazaar"] .bzr-stall:hover { transform: none; }
  [data-theme-layout="dtc-bazaar"] .bzr-stall:hover .bzr-stall-media img { transform: none; }
  [data-theme-layout="dtc-bazaar"] .bzr-plank:hover { transform: none; }
}

/* ============================================================
   皮肤 ×3（变量成套覆写；正文≥7、次要/accent≥4.5，hover 只升不降，实算见提交说明）
   ============================================================ */
/* ---- 集市 · Bazaar（原生）：麻布米 #f1e8d8 + 摊红 #a8352c + 木棕 #7a5230 ----
   ink/bg 12.95, muted/bg 5.43, accent/bg 5.38(hover soft 7.00↑), 白字/红布 6.54,
   木牌字/木棕 5.99, 价签字/签面 14.61 */
:root[data-theme="bazaar"] {
  --bg: #f1e8d8; --surface: #faf5ea; --ink: #2b2118; --ink-soft: #4f4234;
  --muted: #6b5a47; --faint: #93836f; --line: #ddcfb6; --line-soft: #eadfc9;
  --accent: #a8352c; --accent-soft: #8c2a22; --accent-wash: #f3ded1;
  --radius: 12px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(43,33,24,.06), 0 10px 26px rgba(43,33,24,.09);
  --bzr-cloth: #a8352c; --bzr-cloth-ink: #ffffff;
  --bzr-awning-a: #a8352c; --bzr-awning-b: #f6ead6;
  --bzr-wood: #7a5230; --bzr-wood-ink: #f9efdf;
  --bzr-tag-bg: #fdf6e4; --bzr-tag-ink: #2b2118; --bzr-on-accent: #ffffff;
}

/* ---- 集市 · Bazaar Noir（反差暗皮）：夜市深棕 + 灯串暖黄 ----
   ink/bg 14.45, muted/bg 7.36, accent/bg 9.29(hover soft 11.15↑),
   布条字/深酱布 10.62, 木牌字/木棕 6.60, 深字/暖黄 8.90 */
:root[data-theme="bazaar-noir"] {
  --bg: #221712; --surface: #2d2018; --ink: #f4e8d3; --ink-soft: #d8c8ab;
  --muted: #b7a689; --faint: #8a7960; --line: #483626; --line-soft: #3a2b1e;
  --accent: #e9b45b; --accent-soft: #f3c87e; --accent-wash: #3b2a17;
  --radius: 12px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(0,0,0,.45), 0 12px 30px rgba(0,0,0,.5);
  --bzr-cloth: #54241a; --bzr-cloth-ink: #f7e9c9; --bzr-lamp: #ffd67e;
  --bzr-awning-a: #54241a; --bzr-awning-b: #e9b45b;
  --bzr-wood: #6f4c2b; --bzr-wood-ink: #f9edd6;
  --bzr-tag-bg: #f7ecd4; --bzr-tag-ink: #33241a; --bzr-on-accent: #2a1a0c;
}
/* 夜市压图 hero：主按钮换灯串暖黄（深字 8.90），白底按钮在夜图上太刺 */
:root[data-theme="bazaar-noir"] .bzr-hero.has-img .btn-primary { background: var(--accent); border-color: var(--accent); color: #2a1a0c; }

/* ---- 集市 · Bazaar White（纯白皮）：中性灰基底对齐纯白系，摊红压深到 #a03328 ----
   ink/bg 18.72, accent/bg 7.00(hover soft 9.44↑), 白字/红布 7.00, 白字/木棕 7.65;
   muted 压深为 #6a707a——#707680 在 #fafaf8 上只有 4.38，压深后 4.77/4.99 过审 */
:root[data-theme="bazaar-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #6a707a; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #a03328; --accent-soft: #7f281f; --accent-wash: #f8ece9;
  --radius: 10px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(16,18,24,.05), 0 10px 26px rgba(16,18,24,.07);
  --bzr-cloth: #a03328; --bzr-cloth-ink: #ffffff;
  --bzr-awning-a: #a03328; --bzr-awning-b: #f4f4f2;
  --bzr-wood: #6f4c2b; --bzr-wood-ink: #ffffff;
  --bzr-tag-bg: #ffffff; --bzr-tag-ink: #101218; --bzr-on-accent: #ffffff;
}
/* 纯白皮 CTA 通栏：note 的 muted 落在 accent-wash 上只有 4.31——换 ink-soft（8.6+） */
:root[data-theme="bazaar-white"] .dt-cta-note { color: var(--ink-soft); }

/* ==========================================================================
   dtc-column 直列（clm-*）：导航无横栏——左上小站名 + 右缘悬浮圆点节（纯 CSS 锚点）；
   整页一屏一款：hero 第一屏（HeroTitle 大字压屏），每件商品独占一整屏区
   （大图居中 + 左下标题与规格签 + SHOT NN 编号，CSS counter 生成）；
   末屏 CTA。共享 dt-/f- 语言经 [data-theme-layout^="dtc-"] 自动生效。
   每屏高度一律 min-height（内容多不裁）；容器规约 min(100% - 48px, var(--w-wide) - 48px)。
   皮肤三款：column（近黑+暖金+月白）/ column-day（亮白+墨+金）/ column-white（纯白）。
   ========================================================================== */
@media (prefers-reduced-motion: no-preference) {
  html[data-theme-layout="dtc-column"] { scroll-behavior: smooth; }
}

/* ---- 页头 CSS 重塑：无横栏——去 sticky/底线/毛玻璃，小站名 + 小字导航；
       ≤620px 交还基础汉堡抽屉（重塑段全部包在 min-width:621px 里） ---- */
@media (min-width: 621px) {
  [data-theme-layout="dtc-column"] .site-header { position: static; background: transparent; border-bottom: 0; -webkit-backdrop-filter: none; backdrop-filter: none; }
  [data-theme-layout="dtc-column"] .site-header .wrap { height: 64px; }
  [data-theme-layout="dtc-column"] .brand,
  [data-theme-layout="dtc-column"] .brand-name { font-family: var(--sans); font-size: .92rem; font-weight: 750; letter-spacing: .2em; text-transform: uppercase; }
  [data-theme-layout="dtc-column"] .nav { gap: 1.25rem; }
  [data-theme-layout="dtc-column"] .nav a { color: var(--muted); font-size: .78rem; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; }
  [data-theme-layout="dtc-column"] .nav a:hover { color: var(--accent); }
  [data-theme-layout="dtc-column"] .nav a[aria-current="page"] { color: var(--ink); }
  [data-theme-layout="dtc-column"] .nav a[aria-current="page"]::after { bottom: -6px; height: 1px; background: var(--ink); }
}

/* ---- 右缘圆点节栏：fixed 专属车道 = 容器 24px 侧沟（栏含点宽 ≤18px，不压内容）；
       ≤720px 整栏隐藏（辅助锚点导航，内容本身顺序可滚达） ---- */
[data-theme-layout="dtc-column"] .clm-rail { position: fixed; top: 50%; right: clamp(6px, 1vw, 14px); z-index: 40; display: flex; flex-direction: column; align-items: center; gap: 13px; padding: 8px 0; transform: translateY(-50%); }
[data-theme-layout="dtc-column"] .clm-rail::before { content: ""; position: absolute; top: 0; bottom: 0; left: 50%; width: 1px; transform: translateX(-50%); background: color-mix(in srgb, var(--ink) 22%, transparent); }
[data-theme-layout="dtc-column"] .clm-dot { position: relative; z-index: 1; width: 9px; height: 9px; border-radius: 50%; background: var(--bg); border: 2px solid color-mix(in srgb, var(--ink) 55%, transparent); transition: border-color var(--speed), background var(--speed), transform var(--speed); }
[data-theme-layout="dtc-column"] .clm-dot:hover,
[data-theme-layout="dtc-column"] .clm-dot:focus-visible { border-color: var(--accent); background: var(--accent); transform: scale(1.3); }

/* ---- 屏区骨架：min-height 撑屏（不固定高，内容多不裁） ---- */
[data-theme-layout="dtc-column"] .clm-wrap { counter-reset: clmshot; }
[data-theme-layout="dtc-column"] .clm-screen { display: flex; flex-direction: column; justify-content: center; min-height: calc(100vh - 64px); min-height: calc(100svh - 64px); padding: clamp(1.6rem, 4vh, 3rem) 0; }

/* hero 第一屏：大字压屏；三态 image scrim / svg 内嵌 / 轻动画（视觉右下融合，普通流） */
[data-theme-layout="dtc-column"] .clm-hero { position: relative; overflow: hidden; }
[data-theme-layout="dtc-column"] .clm-hero-inner { position: relative; z-index: 1; width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto; }
[data-theme-layout="dtc-column"] .clm-h1 { margin: 0; max-width: 13em; font-family: var(--dt-display, var(--serif)); font-size: clamp(2.5rem, 7vw, 4.8rem); font-weight: 650; line-height: 1.06; letter-spacing: -.02em; }
[data-theme-layout="dtc-column"] .clm-lede { max-width: 54ch; margin: 1.2rem 0 0; color: var(--muted); font-size: 1.04rem; line-height: 1.85; }
[data-theme-layout="dtc-column"] .clm-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 2rem; }
[data-theme-layout="dtc-column"] .clm-hero-side { width: min(100% - 48px, var(--w-wide) - 48px); margin: 1.4rem auto 0; display: flex; justify-content: flex-end; }
[data-theme-layout="dtc-column"] .clm-hero-side .dt-animsvg,
[data-theme-layout="dtc-column"] .clm-hero-side svg { width: min(100%, 400px); height: auto; }
[data-theme-layout="dtc-column"] .clm-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-column"] .clm-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(108deg, rgba(10,10,12,.68) 0%, rgba(10,10,12,.42) 48%, rgba(10,10,12,.08) 78%), linear-gradient(200deg, rgba(10,10,12,0) 46%, rgba(10,10,12,.5) 98%); }
[data-theme-layout="dtc-column"] .clm-hero.has-img .clm-hero-inner { z-index: 1; }
[data-theme-layout="dtc-column"] .clm-hero.has-img .clm-h1 { color: #fff; } /* 全局 h1 色规则盖容器继承，压图必须显式白字 */
[data-theme-layout="dtc-column"] .clm-hero.has-img .dt-eyebrow { color: #fff; opacity: .82; }
[data-theme-layout="dtc-column"] .clm-hero.has-img .clm-lede { color: rgba(255,255,255,.86); }
[data-theme-layout="dtc-column"] .clm-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-column"] .clm-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-column"] .clm-hero.has-img .btn-primary { background: #fff; border-color: #fff; color: #14151a; }

/* 商品屏：一屏一款——大图居中吃掉主高度，左下编号+标题+规格签；偶数屏换 surface 底 */
[data-theme-layout="dtc-column"] .clm-shot { border-top: 1px solid var(--line-soft); scroll-margin-top: 12px; counter-increment: clmshot; }
[data-theme-layout="dtc-column"] .clm-shot:nth-of-type(2n) { background: var(--surface); }
[data-theme-layout="dtc-column"] .clm-shot-link { display: flex; flex: 1; min-height: 0; flex-direction: column; justify-content: flex-end; gap: clamp(1rem, 3vh, 1.8rem); width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto; color: var(--ink); }
[data-theme-layout="dtc-column"] .clm-shot-link:hover { color: var(--ink); }
[data-theme-layout="dtc-column"] .clm-shot-media { display: grid; flex: 1; min-height: 0; place-items: center; }
[data-theme-layout="dtc-column"] .clm-shot-media img { display: block; width: auto; max-width: 100%; max-height: min(56vh, 600px); object-fit: contain; border-radius: calc(var(--radius) * 1.2); transition: transform .35s ease; }
[data-theme-layout="dtc-column"] .clm-shot-link:hover .clm-shot-media img { transform: scale(1.02); }
[data-theme-layout="dtc-column"] .clm-shot-media.dt-gen { flex: none; width: min(100%, 560px); min-height: clamp(240px, 42vh, 440px); margin: auto; border-radius: calc(var(--radius) * 1.2); }
[data-theme-layout="dtc-column"] .clm-shot-media.dt-gen b { font-size: clamp(3rem, 8vw, 5rem); }
[data-theme-layout="dtc-column"] .clm-shot-panel { display: block; max-width: 640px; padding-bottom: clamp(1rem, 3.5vh, 2rem); }
[data-theme-layout="dtc-column"] .clm-num { display: block; margin-bottom: .55rem; color: var(--accent); font-family: var(--sans); font-style: normal; font-size: .72rem; font-weight: 800; letter-spacing: .3em; }
[data-theme-layout="dtc-column"] .clm-num::before { content: "№ " counter(clmshot, decimal-leading-zero); }
[data-theme-layout="dtc-column"] .clm-shot-cat { display: block; margin-bottom: .25rem; color: var(--muted); font-size: .78rem; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-column"] .clm-shot-title { display: block; font-family: var(--dt-display, var(--serif)); font-size: clamp(1.5rem, 3vw, 2.3rem); font-weight: 650; line-height: 1.15; letter-spacing: -.01em; transition: color var(--speed); }
[data-theme-layout="dtc-column"] .clm-shot-link:hover .clm-shot-title { color: var(--accent); }
[data-theme-layout="dtc-column"] .clm-chips { margin-top: .8rem; }
[data-theme-layout="dtc-column"] .clm-shot-go { display: inline-flex; align-items: center; gap: .35rem; margin-top: 1rem; color: var(--ink-soft); font-size: .86rem; font-weight: 650; }
[data-theme-layout="dtc-column"] .clm-shot-go .arrow { transition: transform var(--speed); }
[data-theme-layout="dtc-column"] .clm-shot-link:hover .clm-shot-go { color: var(--accent); }
[data-theme-layout="dtc-column"] .clm-shot-link:hover .clm-shot-go .arrow { transform: translateX(3px); }

/* 可选条带（数字/评价/FAQ）：紧凑，不占整屏；未配置整段不渲染 */
[data-theme-layout="dtc-column"] .clm-band { padding: clamp(2.6rem, 6vw, 4rem) 0; border-top: 1px solid var(--line-soft); }
[data-theme-layout="dtc-column"] .clm-band-in { width: min(100% - 48px, var(--w-wide) - 48px); margin-inline: auto; }
[data-theme-layout="dtc-column"] .dt-testi-region { color: var(--muted); } /* 家族默认 faint 在小字号上不达 4.5，本骨架三皮统一升到 muted */

/* ---- 内页 · 商品列表（generic_list DOM）：同构屏节紧凑版——
       横带卡（偶数左右互换）+ SHOT 编号 + 分类导航化作圆点节 ---- */
[data-theme-layout="dtc-column"] .page-head { padding: clamp(2.4rem, 6vw, 3.6rem) 0 1.2rem; border-bottom: 0; }
[data-theme-layout="dtc-column"] .page-head h1 { font-family: var(--dt-display, var(--serif)); font-size: clamp(2.2rem, 5vw, 3.4rem); font-weight: 650; letter-spacing: -.015em; }
[data-theme-layout="dtc-column"] .page-head .eyebrow { letter-spacing: .3em; }
[data-theme-layout="dtc-column"] .cat-nav { gap: .3rem 1.5rem; margin: .8rem 0 0; }
[data-theme-layout="dtc-column"] .cat-nav a { position: relative; padding: .3rem 0 .3rem 16px; border: 0; border-radius: 0; color: var(--muted); font-size: .8rem; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; }
[data-theme-layout="dtc-column"] .cat-nav a::before { content: ""; position: absolute; left: 0; top: 50%; width: 8px; height: 8px; border: 2px solid color-mix(in srgb, var(--ink) 45%, transparent); border-radius: 50%; transform: translateY(-50%); }
[data-theme-layout="dtc-column"] .cat-nav a:hover { color: var(--accent); }
[data-theme-layout="dtc-column"] .cat-nav a:hover::before { border-color: var(--accent); }
[data-theme-layout="dtc-column"] .cat-nav a.active { background: none; color: var(--ink); }
[data-theme-layout="dtc-column"] .cat-nav a.active::before { background: var(--accent); border-color: var(--accent); }
[data-theme-layout="dtc-column"] .cat-nav a.active .muted { color: var(--muted); opacity: 1; }
[data-theme-layout="dtc-column"] .link-grid { display: block; margin: .6rem 0 2.6rem; counter-reset: clmls; }
[data-theme-layout="dtc-column"] .link-card { display: grid; grid-template-columns: minmax(0, .95fr) minmax(0, 1.05fr); gap: clamp(1.2rem, 3vw, 2.6rem); align-items: center; min-height: clamp(260px, 42vh, 400px); padding: clamp(1.4rem, 3vw, 2.4rem) 0; border: 0; border-top: 1px solid var(--line); border-radius: 0; background: transparent; overflow: visible; counter-increment: clmls; }
[data-theme-layout="dtc-column"] .link-card:first-child { border-top: 0; }
[data-theme-layout="dtc-column"] .link-card:hover { border-color: var(--line); box-shadow: none; transform: none; }
[data-theme-layout="dtc-column"] .link-card:nth-child(even) .lc-cover { order: 2; }
[data-theme-layout="dtc-column"] .lc-cover { aspect-ratio: auto; background: transparent; display: grid; place-items: center; }
[data-theme-layout="dtc-column"] .lc-cover img { width: auto; max-width: 100%; height: auto; max-height: clamp(220px, 34vh, 340px); object-fit: contain; border-radius: calc(var(--radius) * 1.2); transition: transform .3s ease; }
[data-theme-layout="dtc-column"] .link-card:hover .lc-cover img { transform: scale(1.02); }
[data-theme-layout="dtc-column"] .lc-mono { min-height: clamp(180px, 28vh, 280px); border-radius: calc(var(--radius) * 1.2); background: var(--accent-wash); color: var(--accent); font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-column"] .lc-body { padding: 0; gap: .45rem; }
[data-theme-layout="dtc-column"] .lc-body::before { content: "№ " counter(clmls, decimal-leading-zero); color: var(--accent); font-size: .72rem; font-weight: 800; letter-spacing: .3em; }
[data-theme-layout="dtc-column"] .lc-title { font-family: var(--dt-display, var(--serif)); font-size: clamp(1.4rem, 2.6vw, 2rem); font-weight: 650; line-height: 1.18; justify-content: flex-start; }
[data-theme-layout="dtc-column"] .lc-intro { flex: none; display: -webkit-box; max-width: 52ch; margin: 0; overflow: hidden; color: var(--muted); font-size: .92rem; line-height: 1.75; -webkit-box-orient: vertical; -webkit-line-clamp: 3; }
[data-theme-layout="dtc-column"] .lc-foot .tag { border: 1px solid var(--line); border-radius: 999px; background: transparent; color: var(--ink-soft); }

/* ---- 内页 · 商品详情（product_detail DOM）：同构大图 + 底部固定购买条 ---- */
[data-theme-layout="dtc-column"] .pd-top { grid-template-columns: minmax(0, 1.12fr) minmax(0, .88fr); }
[data-theme-layout="dtc-column"] .pd-media { border: 0; background: transparent; aspect-ratio: auto; min-height: clamp(300px, 50vh, 540px); border-radius: calc(var(--radius) * 1.2); }
[data-theme-layout="dtc-column"] .pd-media img { max-height: min(60vh, 620px); }
[data-theme-layout="dtc-column"] .pd-media-gen { background: var(--accent-wash); }
[data-theme-layout="dtc-column"] .pd-thumbs { display: flex; flex-wrap: wrap; justify-content: center; gap: .55rem; }
[data-theme-layout="dtc-column"] .pd-thumb { flex: none; width: 52px; height: 52px; aspect-ratio: auto; border-radius: 50%; } /* 圆形缩略图：呼应圆点节母题 */
[data-theme-layout="dtc-column"] .pd-kicker { font-family: var(--sans); letter-spacing: .28em; }
[data-theme-layout="dtc-column"] .pd-title { font-family: var(--dt-display, var(--serif)); font-size: clamp(1.8rem, 3.6vw, 2.7rem); font-weight: 650; letter-spacing: -.015em; }
[data-theme-layout="dtc-column"] .pd-sec-title { font-family: var(--dt-display, var(--serif)); font-size: 1.35rem; }
[data-theme-layout="dtc-column"] .pd-sec-title::before { content: ""; display: block; width: 34px; height: 2px; margin-bottom: .6rem; background: var(--accent); }
[data-theme-layout="dtc-column"] .pd-specs-tablewrap { border: 0; border-top: 1px solid var(--line); border-radius: 0; background: transparent; }
[data-theme-layout="dtc-column"] .pd-specs-table th { background: transparent; }
[data-theme-layout="dtc-column"] .pd-rel-card { border: 0; background: transparent; border-radius: 0; overflow: visible; }
[data-theme-layout="dtc-column"] .pd-rel-card:hover { transform: none; }
[data-theme-layout="dtc-column"] .pd-rel-media { border-radius: calc(var(--radius) * 1.2); overflow: hidden; }
[data-theme-layout="dtc-column"] .pd-rel-title { padding: .7rem .1rem 0; font-weight: 650; }
/* 底部固定购买条：≥721px 悬浮（surface 毛玻璃 + 发丝顶线），标题居左、按钮靠右；
   主内容 padding-bottom 留 120px 专属车道，to-top 上移让位；≤720px 归位普通流 */
@media (min-width: 721px) {
  [data-theme-layout="dtc-column"] .pd-inquiry { position: fixed; right: 0; bottom: 0; left: 0; z-index: 45; display: flex; align-items: center; gap: 1rem; margin: 0; padding: .7rem clamp(16px, 3vw, 32px); border: 0; border-top: 1px solid var(--line); border-radius: 0; background: color-mix(in srgb, var(--surface) 92%, transparent); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); }
  [data-theme-layout="dtc-column"] .pd-inquiry .inquiry-title { margin: 0; font-size: .95rem; }
  [data-theme-layout="dtc-column"] .pd-inquiry .inquiry-note { display: none; }
  [data-theme-layout="dtc-column"] .pd-inquiry .inquiry-actions { flex-wrap: nowrap; margin-left: auto; }
  [data-theme-layout="dtc-column"] .pd-main:has(.pd-inquiry) { padding-bottom: 120px; }
  [data-theme-layout="dtc-column"] .pd-main:has(.pd-inquiry) ~ .to-top { bottom: 84px; } /* to-top 是 main 的后随兄弟节点，上移让位购买条 */
}

/* ---- 响应式：920 收紧、720 归位单列（本骨架天生单列，无横向溢出面） ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-column"] .clm-shot-media img { max-height: 46vh; }
  [data-theme-layout="dtc-column"] .clm-shot-panel { max-width: 100%; }
  [data-theme-layout="dtc-column"] .pd-top { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-column"] .clm-rail { display: none; }
  [data-theme-layout="dtc-column"] .clm-screen { min-height: 0; padding: 2.2rem 0; }
  [data-theme-layout="dtc-column"] .clm-hero { min-height: min(calc(100vh - 64px), 40rem); min-height: min(calc(100svh - 64px), 40rem); }
  [data-theme-layout="dtc-column"] .clm-hero-side { justify-content: center; }
  [data-theme-layout="dtc-column"] .clm-shot-media img { max-height: 52vh; }
  [data-theme-layout="dtc-column"] .link-card { grid-template-columns: 1fr; min-height: 0; align-items: start; }
  [data-theme-layout="dtc-column"] .link-card:nth-child(even) .lc-cover { order: 0; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-column"] .clm-shot-media img,
  [data-theme-layout="dtc-column"] .lc-cover img,
  [data-theme-layout="dtc-column"] .clm-dot,
  [data-theme-layout="dtc-column"] .clm-shot-go .arrow { transition: none; }
  [data-theme-layout="dtc-column"] .clm-shot-link:hover .clm-shot-media img,
  [data-theme-layout="dtc-column"] .link-card:hover .lc-cover img,
  [data-theme-layout="dtc-column"] .clm-dot:hover { transform: none; }
}

/* ============================================================================
   dtc-column 皮肤 ×3。变量成套覆写锁调色板；关键对比实算见各块注释。
   ========================================================================== */

/* ---- 直列 · Column（原生，暗）：近黑 #101113 + 暖金 + 月白衬线大字 ----
   实算：ink/bg 16.42、ink/surface 14.82、muted/bg 8.21、muted/surface 7.41、
   accent/bg 7.92、accent/surface 7.15、accent/wash 6.86、hover accent-soft/bg 10.16（只升）、
   主按钮 月白底×surface字 14.82。 */
:root[data-theme="column"] {
  --bg: #101113; --surface: #1a1c21; --ink: #f2efe5; --ink-soft: #cbc8bb;
  --muted: #a9aca4; --faint: #7d8189; --line: #2c2f36; --line-soft: #1e2127;
  --accent: #c9a25c; --accent-soft: #ddb97a; --accent-wash: #251f13;
  --radius: 10px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(0,0,0,.45), 0 14px 34px rgba(0,0,0,.5);
}

/* ---- 直列 · Column Day（浅反差）：亮白纸底 + 墨 + 压深金 ----
   实算：ink/bg 16.85、ink/surface 17.75、muted/bg 5.75、muted/surface 6.06、muted/wash 5.11、
   accent/bg 5.10、accent/surface 5.37、hover accent-soft/bg 7.26（只升）、主按钮 墨底×白字 17.75。 */
:root[data-theme="column-day"] {
  --bg: #faf9f5; --surface: #ffffff; --ink: #17181b; --ink-soft: #3f434b;
  --muted: #5d636c; --faint: #6c727b; --line: #e3e1d9; --line-soft: #f2f0ea;
  --accent: #8a6410; --accent-soft: #6d4e0a; --accent-wash: #f4ebd6;
  --radius: 10px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(23,24,27,.05), 0 10px 28px rgba(23,24,27,.07);
}

/* ---- 直列 · Column White（纯白）：中性灰基底（对齐 answer-desk-white）+ 金压深；
   muted 压到 #656b74 补 #fafaf8 卡面 4.38 坑 → 实算 muted/surface 5.14、muted/bg 5.37、
   ink/bg 18.72、accent/bg 5.37、accent/surface 5.14、hover accent-soft/bg 7.05（只升）。 */
:root[data-theme="column-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #656b74; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #8a6408; --accent-soft: #6f5506; --accent-wash: #f8f2df;
  --radius: 10px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(16,18,24,.05), 0 10px 28px rgba(16,18,24,.06);
}
:root[data-theme="column-white"] .clm-shot:nth-of-type(2n) { border-top-color: var(--line); } /* 纯白：surface 带与 bg 近同色，发丝线压深一档保持屏区分节 */

/* ==========================================================================
   dtc-swissgrid 骨架（swg-*）「严选格」：瑞士网格排版的品牌店——
   双层页头（顶部黑色公告细条 = HeroEyebrow 文案位 + 下层主导航左品牌右链接）、
   hero 大字行（瑞士粗黑体）、商品 1px 网格线陈列（格间 1px 底色缝、卡编号
   SG-NN 由 CSS counter 生成、规格签代替价格）。
   公告细条实现：.site-header::before 预留 38px 车道（≥721px），首页分片的
   .swg-notice 绝对定位入位；内页无眉标时车道呈纯色品牌横带（刻意保留）。
   ≤720px 公告条归位普通流；≤620px 页头整段交还基础汉堡抽屉（重塑包 621px+）。
   三皮：swissgrid（纯白+黑 #141414+信号红，米白网格缝）/ swissgrid-noir（黑底
   白线红点）/ swissgrid-white（纯白+灰缝）。radius 全皮 0（瑞士直角）。
   ========================================================================== */

/* ---- 双层页头：CSS 重塑标准 .site-header（只动 CSS，不动 DOM） ---- */
@media (min-width: 721px) {
  [data-theme-layout="dtc-swissgrid"] .site-header::before { content: ""; display: block; height: 38px; background: var(--swg-bar-bg, var(--ink)); }
  [data-theme-layout="dtc-swissgrid"] .swg-notice { position: absolute; top: 0; left: 0; right: 0; z-index: 60; height: 38px; }
}
@media (min-width: 621px) {
  [data-theme-layout="dtc-swissgrid"] .site-header { position: static; background: var(--bg); -webkit-backdrop-filter: none; backdrop-filter: none; border-bottom: 2px solid var(--swg-rule, var(--ink)); }
  [data-theme-layout="dtc-swissgrid"] .site-header .wrap { height: 62px; }
  [data-theme-layout="dtc-swissgrid"] .brand { font-family: var(--swg-sans, var(--sans)); font-size: 1.16rem; font-weight: 800; letter-spacing: .02em; text-transform: uppercase; }
  [data-theme-layout="dtc-swissgrid"] .nav { gap: 1.35rem; }
  [data-theme-layout="dtc-swissgrid"] .nav a { font-size: .8rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
  [data-theme-layout="dtc-swissgrid"] .nav a[aria-current="page"]::after { bottom: -6px; height: 2px; }
}
/* 公告条基础态（≤720px 普通流：贴在页头下方的通栏细条；装饰长文单行钳断） */
[data-theme-layout="dtc-swissgrid"] .swg-notice { display: flex; align-items: center; justify-content: center; min-height: 34px; margin: 0; padding: .3rem 24px; background: var(--swg-bar-bg, var(--ink)); color: var(--swg-bar-ink, var(--bg)); font-size: .76rem; font-weight: 650; letter-spacing: .14em; text-transform: uppercase; text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* ---- 骨架容器 / hero 大字行 ---- */
[data-theme-layout="dtc-swissgrid"] .swg-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-swissgrid"] .btn, [data-theme-layout="dtc-swissgrid"] .inquiry-btn { border-radius: 0; }
[data-theme-layout="dtc-swissgrid"] .swg-hero { position: relative; border-bottom: 3px solid var(--swg-rule, var(--ink)); overflow: hidden; }
[data-theme-layout="dtc-swissgrid"] .swg-hero-inner { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(240px, .8fr); align-items: center; gap: clamp(1rem, 3vw, 2.4rem); padding: clamp(2rem, 5vw, 3.4rem) 0 clamp(1.5rem, 4vw, 2.5rem); }
[data-theme-layout="dtc-swissgrid"] .swg-h1 { margin: 0; font-family: var(--swg-sans, var(--sans)); font-size: clamp(2.4rem, 6.4vw, 4.8rem); font-weight: 800; line-height: 1.04; letter-spacing: -.02em; text-transform: uppercase; overflow-wrap: anywhere; }
[data-theme-layout="dtc-swissgrid"] .swg-lede { max-width: 54ch; margin: 1.1rem 0 0; color: var(--muted); font-size: 1rem; line-height: 1.75; }
[data-theme-layout="dtc-swissgrid"] .swg-cta { display: flex; flex-wrap: wrap; gap: .6rem; margin-top: 1.6rem; }
[data-theme-layout="dtc-swissgrid"] .swg-hero-side { min-width: 0; }
/* hero image 态：全幅底图 + scrim 压字（同 flagship 规约——白字要压得住任意用户图） */
[data-theme-layout="dtc-swissgrid"] .swg-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-swissgrid"] .swg-hero.has-img { min-height: min(64vh, 520px); display: flex; align-items: flex-end; }
[data-theme-layout="dtc-swissgrid"] .swg-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(102deg, rgba(10,10,12,.68) 0%, rgba(10,10,12,.42) 46%, rgba(10,10,12,.06) 74%), linear-gradient(200deg, rgba(10,10,12,0) 42%, rgba(10,10,12,.52) 96%); }
[data-theme-layout="dtc-swissgrid"] .swg-hero.has-img .swg-hero-inner { position: relative; z-index: 1; grid-template-columns: minmax(0, 1fr); padding: clamp(1.8rem, 4vw, 2.8rem) clamp(1.2rem, 3vw, 2rem); }
[data-theme-layout="dtc-swissgrid"] .swg-hero.has-img .swg-h1 { color: #fff; }
[data-theme-layout="dtc-swissgrid"] .swg-hero.has-img .swg-lede { color: rgba(255,255,255,.88); }
[data-theme-layout="dtc-swissgrid"] .swg-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.66); color: #fff; }
[data-theme-layout="dtc-swissgrid"] .swg-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-swissgrid"] .swg-hero.has-img .btn-primary { background: #fff; border-color: #fff; color: #141414; }

/* ---- 分类导航行（.Categories）：细缝分段条 ---- */
[data-theme-layout="dtc-swissgrid"] .swg-cats { display: flex; flex-wrap: wrap; margin-top: 1.8rem; border: 1px solid var(--swg-gap, var(--line)); background: var(--surface); }
[data-theme-layout="dtc-swissgrid"] .swg-cats a { display: inline-flex; align-items: center; gap: .45rem; padding: .55rem 1rem; border-right: 1px solid var(--swg-gap, var(--line)); color: var(--ink-soft); font-size: .78rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-swissgrid"] .swg-cats a:hover { color: var(--accent); }
[data-theme-layout="dtc-swissgrid"] .swg-cats a small { color: var(--accent); font-size: .72rem; font-weight: 800; }
[data-theme-layout="dtc-swissgrid"] .swg-cats-all { margin-left: auto; border-right: 0 !important; border-left: 1px solid var(--swg-gap, var(--line)); }

/* ---- 区块头：粗顶规线 + 红点 + 全大写标题 ---- */
[data-theme-layout="dtc-swissgrid"] .swg-section { padding-top: clamp(2.4rem, 5vw, 3.8rem); }
[data-theme-layout="dtc-swissgrid"] .swg-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; border-top: 3px solid var(--swg-rule, var(--ink)); padding-top: .65rem; margin-bottom: 1.1rem; }
[data-theme-layout="dtc-swissgrid"] .swg-head h2 { margin: 0; font-family: var(--swg-sans, var(--sans)); font-size: clamp(1.1rem, 2vw, 1.45rem); font-weight: 800; letter-spacing: .04em; text-transform: uppercase; }
[data-theme-layout="dtc-swissgrid"] .swg-head h2::before { content: ""; display: inline-block; width: .5em; height: .5em; margin-right: .5rem; border-radius: 50%; background: var(--swg-signal, var(--accent)); }
[data-theme-layout="dtc-swissgrid"] .swg-head > a { flex: none; color: var(--ink-soft); font-size: .76rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
[data-theme-layout="dtc-swissgrid"] .swg-head > a:hover { color: var(--accent); }

/* ---- 商品网格：1px 底色缝 + SG-NN 编号（CSS counter） ---- */
[data-theme-layout="dtc-swissgrid"] .swg-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(220px, 100%), 1fr)); gap: 1px; background: var(--swg-gap, var(--line)); border: 1px solid var(--swg-gap, var(--line)); counter-reset: swg; }
[data-theme-layout="dtc-swissgrid"] .swg-card { display: flex; flex-direction: column; min-width: 0; background: var(--surface); color: var(--ink); counter-increment: swg; }
[data-theme-layout="dtc-swissgrid"] .swg-card::before { content: "№ " counter(swg, decimal-leading-zero); padding: .5rem .75rem; border-bottom: 1px solid var(--swg-gap, var(--line)); font-family: var(--mono); font-size: .7rem; font-weight: 700; letter-spacing: .12em; color: var(--muted); }
[data-theme-layout="dtc-swissgrid"] .swg-card-media { display: grid; place-items: center; aspect-ratio: 1 / 1; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-swissgrid"] .swg-card-media img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-swissgrid"] .swg-card-body { display: flex; flex-direction: column; gap: .45rem; padding: .8rem .75rem .95rem; border-top: 1px solid var(--swg-gap, var(--line)); }
[data-theme-layout="dtc-swissgrid"] .swg-card-title { font-family: var(--swg-sans, var(--sans)); font-size: .95rem; font-weight: 700; line-height: 1.4; }
[data-theme-layout="dtc-swissgrid"] .swg-card:hover { color: var(--ink); }
[data-theme-layout="dtc-swissgrid"] .swg-card:hover .swg-card-title,
[data-theme-layout="dtc-swissgrid"] .swg-card:hover::before { color: var(--accent); }
[data-theme-layout="dtc-swissgrid"] .swg-card .f-chips { margin-top: 0; }
[data-theme-layout="dtc-swissgrid"] .f-chip { border-radius: 0; }

/* ---- 品牌数字 / 分页：跟随网格语言 ---- */
[data-theme-layout="dtc-swissgrid"] .dt-stats { gap: 1px; background: var(--swg-gap, var(--line)); border: 1px solid var(--swg-gap, var(--line)); }
[data-theme-layout="dtc-swissgrid"] .dt-stat { border: 0; border-radius: 0; background: var(--surface); text-align: left; }
[data-theme-layout="dtc-swissgrid"] .dt-stat dt { font-family: var(--swg-sans, var(--sans)); font-weight: 800; letter-spacing: -.01em; }
[data-theme-layout="dtc-swissgrid"] .pagination a, [data-theme-layout="dtc-swissgrid"] .pagination span { border-radius: 0; }
[data-theme-layout="dtc-swissgrid"] .pagination .cur { background: var(--ink); border-color: var(--ink); color: var(--bg); }

/* ---- 内页 · 商品列表（generic_list 的 .page-head/.cat-nav/.link-grid）：同格陈列 ---- */
[data-theme-layout="dtc-swissgrid"] .breadcrumb { font-family: var(--mono); font-size: .74rem; letter-spacing: .06em; text-transform: uppercase; }
[data-theme-layout="dtc-swissgrid"] .page-head { padding: 2.4rem 0 1.6rem; border-bottom: 3px solid var(--swg-rule, var(--ink)); }
[data-theme-layout="dtc-swissgrid"] .page-head .eyebrow { font-family: var(--mono); letter-spacing: .18em; }
[data-theme-layout="dtc-swissgrid"] .page-head h1 { font-family: var(--swg-sans, var(--sans)); font-size: clamp(2.1rem, 5vw, 3.4rem); font-weight: 800; letter-spacing: -.02em; text-transform: uppercase; overflow-wrap: anywhere; }
[data-theme-layout="dtc-swissgrid"] .cat-nav { display: inline-flex; flex-wrap: wrap; gap: 1px; margin: 1.8rem 0; padding: 1px; background: var(--swg-gap, var(--line)); }
[data-theme-layout="dtc-swissgrid"] .cat-nav a { border: 0; border-radius: 0; background: var(--surface); font-size: .8rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-swissgrid"] .cat-nav a.active { background: var(--ink); color: var(--bg); }
[data-theme-layout="dtc-swissgrid"] .link-grid { grid-template-columns: repeat(auto-fill, minmax(min(230px, 100%), 1fr)); gap: 1px; margin: 1.8rem 0; background: var(--swg-gap, var(--line)); border: 1px solid var(--swg-gap, var(--line)); counter-reset: swg; }
[data-theme-layout="dtc-swissgrid"] .link-card { border: 0; border-radius: 0; counter-increment: swg; }
[data-theme-layout="dtc-swissgrid"] .link-card::before { content: "№ " counter(swg, decimal-leading-zero); padding: .5rem .8rem; border-bottom: 1px solid var(--swg-gap, var(--line)); font-family: var(--mono); font-size: .7rem; font-weight: 700; letter-spacing: .12em; color: var(--muted); }
[data-theme-layout="dtc-swissgrid"] .link-card:hover { transform: none; box-shadow: none; }
[data-theme-layout="dtc-swissgrid"] .link-card:hover::before { color: var(--accent); }
[data-theme-layout="dtc-swissgrid"] .lc-cover { aspect-ratio: 1 / 1; }
[data-theme-layout="dtc-swissgrid"] .lc-mono { background: var(--accent-wash); color: var(--accent); font-family: var(--swg-sans, var(--sans)); }
[data-theme-layout="dtc-swissgrid"] .lc-title { font-family: var(--swg-sans, var(--sans)); font-size: .98rem; }
[data-theme-layout="dtc-swissgrid"] .lc-intro { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="dtc-swissgrid"] .lc-foot .tag { border-radius: 0; }
[data-theme-layout="dtc-swissgrid"] .link-grid > .muted { grid-column: 1 / -1; margin: 0; padding: 1.6rem; background: var(--surface); }

/* ---- 内页 · 商品详情（product_detail）：图|参数|购买 三格拼版、细线分隔 ---- */
[data-theme-layout="dtc-swissgrid"] .pd-top { grid-template-columns: minmax(0, 1.08fr) minmax(0, .92fr); gap: 1px; background: var(--swg-gap, var(--line)); border: 1px solid var(--swg-gap, var(--line)); }
[data-theme-layout="dtc-swissgrid"] .pd-gallery { background: var(--surface); padding: clamp(.9rem, 2vw, 1.4rem); }
[data-theme-layout="dtc-swissgrid"] .pd-media { border: 0; border-radius: 0; }
[data-theme-layout="dtc-swissgrid"] .pd-thumb { border-radius: 0; border-color: var(--swg-gap, var(--line)); }
[data-theme-layout="dtc-swissgrid"] .pd-thumb.is-active { border-color: var(--accent); box-shadow: none; }
[data-theme-layout="dtc-swissgrid"] .pd-info { --swg-pdpad: clamp(1.1rem, 2.5vw, 1.6rem); display: flex; flex-direction: column; background: var(--surface); padding: var(--swg-pdpad); }
[data-theme-layout="dtc-swissgrid"] .pd-title { font-family: var(--swg-sans, var(--sans)); font-weight: 800; letter-spacing: -.015em; text-transform: uppercase; overflow-wrap: anywhere; }
[data-theme-layout="dtc-swissgrid"] .pd-meta { border-top: 2px solid var(--swg-rule, var(--ink)); }
[data-theme-layout="dtc-swissgrid"] .pd-meta-row { border-bottom: 1px solid var(--swg-gap, var(--line)); }
[data-theme-layout="dtc-swissgrid"] .pd-meta-row dt { font-family: var(--mono); font-size: .78rem; letter-spacing: .06em; text-transform: uppercase; padding-top: .12rem; }
/* 购买格：细线切出的第三格（accent-wash 底、贴齐 info 格边缘、压到格底） */
[data-theme-layout="dtc-swissgrid"] .pd-inquiry { margin: 1.2rem calc(var(--swg-pdpad) * -1) calc(var(--swg-pdpad) * -1); margin-top: auto; padding: 1.15rem var(--swg-pdpad) 1.3rem; border-top: 1px solid var(--swg-gap, var(--line)); background: var(--accent-wash); }
[data-theme-layout="dtc-swissgrid"] .inquiry-title { font-family: var(--swg-sans, var(--sans)); font-size: .95rem; font-weight: 800; letter-spacing: .05em; text-transform: uppercase; }
[data-theme-layout="dtc-swissgrid"] .pd-sec-title { font-family: var(--swg-sans, var(--sans)); font-size: 1.1rem; font-weight: 800; letter-spacing: .03em; text-transform: uppercase; border-top: 3px solid var(--swg-rule, var(--ink)); padding-top: .6rem; }
[data-theme-layout="dtc-swissgrid"] .pd-specs-tablewrap { border-radius: 0; border-color: var(--swg-gap, var(--line)); }
[data-theme-layout="dtc-swissgrid"] .pd-specs-table th { font-family: var(--mono); font-size: .8rem; letter-spacing: .05em; text-transform: uppercase; }
[data-theme-layout="dtc-swissgrid"] .pd-rel-grid { gap: 1px; background: var(--swg-gap, var(--line)); border: 1px solid var(--swg-gap, var(--line)); counter-reset: swg; }
[data-theme-layout="dtc-swissgrid"] .pd-rel-card { border: 0; border-radius: 0; counter-increment: swg; }
[data-theme-layout="dtc-swissgrid"] .pd-rel-card::before { content: "№ " counter(swg, decimal-leading-zero); padding: .45rem .8rem; border-bottom: 1px solid var(--swg-gap, var(--line)); font-family: var(--mono); font-size: .68rem; font-weight: 700; letter-spacing: .12em; color: var(--muted); }
[data-theme-layout="dtc-swissgrid"] .pd-rel-card:hover { transform: none; }
[data-theme-layout="dtc-swissgrid"] .pd-rel-card:hover::before { color: var(--accent); }

/* ---- 响应式：920/720 逐级收单列，375 无横溢；缝网格自身不横滚 ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-swissgrid"] .swg-hero-inner { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-swissgrid"] .swg-hero-side { max-width: 380px; }
  [data-theme-layout="dtc-swissgrid"] .pd-top { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-swissgrid"] .swg-grid, [data-theme-layout="dtc-swissgrid"] .link-grid,
  [data-theme-layout="dtc-swissgrid"] .pd-rel-grid { grid-template-columns: 1fr 1fr; }
  [data-theme-layout="dtc-swissgrid"] .swg-head { flex-direction: column; align-items: flex-start; gap: .3rem; }
  [data-theme-layout="dtc-swissgrid"] .swg-cats-all { margin-left: 0; border-left: 0; }
}
@media (max-width: 560px) {
  [data-theme-layout="dtc-swissgrid"] .swg-card .f-chips { display: none; }
  [data-theme-layout="dtc-swissgrid"] .dt-stats { grid-template-columns: 1fr 1fr; }
}
/* 骨架自身零动画（hero 轻动画的 reduced-motion 静止由 dtc 族共用段兜底） */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-swissgrid"] * { transition-duration: .01ms !important; }
}

/* ---- 严选格 · Swissgrid（dtc-swissgrid，原生）：暖纸底 + 黑 #141414 + 信号红，
   米白网格缝；纯白留给独立 White 色卡。信号红只做非文字装饰点，
   文字 accent 使用更深的 #c2311f 保证正文对比度。 ---- */
:root[data-theme="swissgrid"] {
  --bg: #f3f0e7; --surface: #faf8f2; --ink: #141414; --ink-soft: #3c3c3c;
  --muted: #5f5f5f; --faint: #757575; --line: #d8d3c6; --line-soft: #ece8de;
  --accent: #c2311f; --accent-soft: #9c2716; --accent-wash: #faeae7;
  --radius: 0px; --w-wide: 1240px; --shadow: 0 1px 2px rgba(20,20,20,.05), 0 8px 22px rgba(20,20,20,.06);
  --serif: "Helvetica Neue", "Neue Haas Grotesk Display", Helvetica, Arial, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
  --dt-display: var(--serif);
  --swg-sans: var(--serif);
  --swg-rule: #141414; --swg-gap: #ddd7c8;
  --swg-bar-bg: #141414; --swg-bar-ink: #ffffff; --swg-signal: #e03e2d;
}

/* ---- 严选格 · Noir（dtc-swissgrid，暗反差）：黑底白线红点——
   信号红 #e03e2d 黑底仅 4.50:1 零余量、wash 上 4.26 不过——文字 accent 提亮到
   #e6503f（黑底 5.13 / wash 4.86），红点装饰仍用原色 --swg-signal。 ---- */
:root[data-theme="swissgrid-noir"] {
  --bg: #0e0e0e; --surface: #0e0e0e; --ink: #f5f4f0; --ink-soft: #cfceca;
  --muted: #a8a7a2; --faint: #8b8a86; --line: #2e2d2a; --line-soft: #1b1a18;
  --accent: #e6503f; --accent-soft: #ef6a55; --accent-wash: #1e1210;
  --radius: 0px; --w-wide: 1240px; --shadow: 0 1px 2px rgba(0,0,0,.5), 0 10px 26px rgba(0,0,0,.5);
  --serif: "Helvetica Neue", "Neue Haas Grotesk Display", Helvetica, Arial, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
  --dt-display: var(--serif);
  --swg-sans: var(--serif);
  --swg-rule: #f5f4f0; --swg-gap: #e9e7df;
  --swg-bar-bg: #f5f4f0; --swg-bar-ink: #0e0e0e; --swg-signal: #e03e2d;
}

/* ---- 严选格 · White（dtc-swissgrid，纯白皮）：纯白 + 灰缝（与原生的米白缝区分）、
   中性灰基底 + 深压信号红；muted 压到 #616670（纯白面 5.77:1，绕开 4.38 坑）。 ---- */
:root[data-theme="swissgrid-white"] {
  --bg: #ffffff; --surface: #ffffff; --ink: #101218; --ink-soft: #3f444d;
  --muted: #616670; --faint: #71747a; --line: #d7d9dd; --line-soft: #f1f2f4;
  --accent: #b02c1c; --accent-soft: #8f2114; --accent-wash: #f7ece9;
  --radius: 0px; --w-wide: 1240px; --shadow: 0 1px 2px rgba(16,18,24,.04), 0 8px 22px rgba(16,18,24,.05);
  --serif: "Helvetica Neue", "Neue Haas Grotesk Display", Helvetica, Arial, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
  --dt-display: var(--serif);
  --swg-sans: var(--serif);
  --swg-rule: #101218; --swg-gap: #d0d3d8;
  --swg-bar-bg: #101218; --swg-bar-ink: #ffffff; --swg-signal: #b02c1c;
}

/* =========================================================================
   LAYOUT: dtc-runway — 秀场：透明页头压全屏开场 Look + LOOK 编号横排卡（3/4 竖构图）
   every selector scoped under [data-theme-layout="dtc-runway"], classes rwy-*
   hero 恒为「暗场亮台」（固定深色渐变/图片压固定 scrim），三皮下白字页头都可读；
   页头重塑整段包 min-width:621px，≤620px 交还基础汉堡抽屉（实底可用）。
   内页：列表=Look 流（大竖卡两列 + CSS counter 续 LOOK 母题）；
   详情=Look 页（左全身大图 3/4 + 右单品清单卡，specs 行=清单行）。
   ========================================================================= */

/* ---- 标准页头 CSS 重塑（只准 CSS）：内页=实底细字距条；首页(:has(.rwy-stage))=
   透明悬浮压 hero，白字，静态零滚动语义 ---- */
@media (min-width: 621px) {
  [data-theme-layout="dtc-runway"] .site-header { background: var(--bg); border-bottom: 1px solid var(--line); -webkit-backdrop-filter: none; backdrop-filter: none; }
  [data-theme-layout="dtc-runway"] .site-header .wrap { height: 72px; }
  [data-theme-layout="dtc-runway"] .brand { font-size: 1.1rem; font-weight: 650; letter-spacing: .22em; text-transform: uppercase; }
  [data-theme-layout="dtc-runway"] .nav { gap: 1.9rem; }
  [data-theme-layout="dtc-runway"] .nav a { font-size: .78rem; font-weight: 600; letter-spacing: .17em; text-transform: uppercase; }
  [data-theme-layout="dtc-runway"] .nav a[aria-current="page"]::after { bottom: -10px; height: 1px; }
  [data-theme-layout="dtc-runway"]:has(.rwy-stage) .site-header { position: absolute; top: 0; right: 0; left: 0; background: transparent; border-bottom: 1px solid rgba(255,255,255,.18); }
  [data-theme-layout="dtc-runway"]:has(.rwy-stage) :is(.brand, .brand-name, .nav a, .lang-switch summary) { color: rgba(255,255,255,.88); }
  [data-theme-layout="dtc-runway"]:has(.rwy-stage) :is(.brand:hover, .nav a:hover, .lang-switch summary:hover) { color: #fff; }
  [data-theme-layout="dtc-runway"]:has(.rwy-stage) .nav a[aria-current="page"] { color: #fff; }
  [data-theme-layout="dtc-runway"]:has(.rwy-stage) .nav a[aria-current="page"]::after { background: #d8b877; }
}

/* ---- 全屏开场 Look（恒暗舞台：固定深色渐变 + 香槟追光；文案锚左下） ---- */
[data-theme-layout="dtc-runway"] .rwy-stage { position: relative; display: flex; align-items: flex-end; min-height: 560px; min-height: max(560px, 94svh); overflow: hidden; background: radial-gradient(56% 44% at 74% 16%, rgba(201,162,92,.16), transparent 70%), linear-gradient(168deg, #17131a 0%, #0d0c0e 52%, #16110d 100%); }
[data-theme-layout="dtc-runway"] .rwy-stage-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
/* 压图 scrim（固定色，不吃皮肤）：左下文案区 + 底部双向压暗，任意亮度用户图白字可读 */
[data-theme-layout="dtc-runway"] .rwy-stage.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(102deg, rgba(10,10,12,.68) 0%, rgba(10,10,12,.38) 48%, rgba(10,10,12,.08) 78%), linear-gradient(200deg, rgba(10,10,12,0) 40%, rgba(10,10,12,.62) 96%); }
[data-theme-layout="dtc-runway"] .rwy-stage-inner { position: relative; z-index: 1; display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(260px, .9fr); align-items: end; gap: clamp(1.4rem, 4vw, 3rem); width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 108px 0 clamp(2.2rem, 6vh, 4.5rem); }
[data-theme-layout="dtc-runway"] .rwy-stage.has-img .rwy-stage-inner { grid-template-columns: minmax(0, 1fr); }
[data-theme-layout="dtc-runway"] .rwy-eyebrow { margin: 0 0 1rem; color: #d8b877; font-family: var(--sans); font-size: .74rem; font-weight: 700; letter-spacing: .38em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .rwy-h1 { margin: 0; max-width: 13em; color: #fff; font-family: var(--dt-display, var(--serif)); font-size: clamp(2.5rem, 6.4vw, 4.6rem); font-weight: 600; line-height: 1.04; letter-spacing: .01em; text-transform: uppercase; }
/* 装饰位长文钳高：描述最多 4 行 */
[data-theme-layout="dtc-runway"] .rwy-lede { display: -webkit-box; overflow: hidden; max-width: 46ch; margin: 1.1rem 0 0; color: rgba(255,255,255,.84); font-size: 1rem; line-height: 1.8; -webkit-box-orient: vertical; -webkit-line-clamp: 4; }
[data-theme-layout="dtc-runway"] .rwy-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="dtc-runway"] .rwy-stage .btn-primary,
[data-theme-layout="dtc-runway"] .rwy-stage .btn-primary:hover { background: #fff; border-color: #fff; color: #14151a; }
[data-theme-layout="dtc-runway"] .rwy-stage .btn-primary:hover { box-shadow: 0 0 0 3px rgba(216,184,119,.4); }
[data-theme-layout="dtc-runway"] .rwy-stage .dt-btn-ghost { border-color: rgba(255,255,255,.6); color: #fff; }
[data-theme-layout="dtc-runway"] .rwy-stage .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-runway"] .rwy-stage-side { min-width: 0; max-width: 440px; justify-self: end; }

/* ---- 首页正文（容器规约 + 系列场次条 + LOOK 横排卡 + 秀评） ---- */
[data-theme-layout="dtc-runway"] .rwy-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-runway"] .rwy-section { padding-top: clamp(3rem, 6vw, 4.5rem); }
[data-theme-layout="dtc-runway"] .rwy-series { display: flex; flex-wrap: wrap; gap: .4rem 2rem; padding: 1.05rem 0; border-bottom: 1px solid var(--line); }
[data-theme-layout="dtc-runway"] .rwy-series a { display: inline-flex; align-items: baseline; gap: .3rem; color: var(--ink-soft); font-size: .8rem; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .rwy-series a:hover { color: var(--ink); }
[data-theme-layout="dtc-runway"] .rwy-series sup { color: var(--muted); font-size: .68em; letter-spacing: .05em; }
[data-theme-layout="dtc-runway"] .rwy-looks { display: flex; gap: clamp(1rem, 2.4vw, 1.8rem); padding-bottom: .9rem; overflow-x: auto; scroll-snap-type: x proximity; scrollbar-width: thin; }
[data-theme-layout="dtc-runway"] .rwy-look { flex: none; display: flex; flex-direction: column; width: clamp(230px, 24vw, 300px); min-width: 0; color: var(--ink); scroll-snap-align: start; }
[data-theme-layout="dtc-runway"] .rwy-look:hover { color: var(--ink); }
[data-theme-layout="dtc-runway"] .rwy-look-num { display: flex; align-items: center; gap: .6rem; margin-bottom: .55rem; color: var(--accent); font-family: var(--sans); font-size: .72rem; font-weight: 750; letter-spacing: .26em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .rwy-look-num::after { content: ""; flex: 1; height: 1px; background: var(--line); }
[data-theme-layout="dtc-runway"] .rwy-look-media { display: grid; place-items: center; aspect-ratio: 3 / 4; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-runway"] .rwy-look-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .35s ease; }
[data-theme-layout="dtc-runway"] .rwy-look:hover .rwy-look-media img { transform: scale(1.045); }
[data-theme-layout="dtc-runway"] .rwy-look-title { margin-top: .75rem; font-family: var(--dt-display, var(--serif)); font-size: 1.02rem; font-weight: 650; line-height: 1.45; }
[data-theme-layout="dtc-runway"] .rwy-look:hover .rwy-look-title { text-decoration: underline; text-decoration-color: var(--accent); text-underline-offset: .25em; }
[data-theme-layout="dtc-runway"] .rwy-look-chips { margin-top: .5rem; }
[data-theme-layout="dtc-runway"] .rwy-look .f-chip { border-radius: 0; background: transparent; }
[data-theme-layout="dtc-runway"] .rwy-quotes { max-width: 74ch; }
[data-theme-layout="dtc-runway"] .rwy-quote { margin: 0; padding: 1.35rem 0 1.35rem 1.6rem; border-left: 1px solid var(--accent); }
[data-theme-layout="dtc-runway"] .rwy-quote + .rwy-quote { border-top: 1px solid var(--line-soft); }
[data-theme-layout="dtc-runway"] .rwy-quote blockquote { margin: 0; color: var(--ink-soft); font-family: var(--dt-display, var(--serif)); font-size: clamp(1.08rem, 1.9vw, 1.42rem); font-style: italic; line-height: 1.7; }
[data-theme-layout="dtc-runway"] .rwy-quote figcaption { margin-top: .65rem; color: var(--muted); font-size: .78rem; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .inquiry-btn { border-radius: 0; }

/* ---- 内页·商品列表（generic_list DOM）：Look 流——大竖卡两列，CSS counter 续
   LOOK 编号母题（纯装饰），分类导航化为居中细字距条 ---- */
[data-theme-layout="dtc-runway"] .page-head { padding: 3.2rem 0 2rem; border-bottom: 0; text-align: center; }
[data-theme-layout="dtc-runway"] .page-head .breadcrumb { padding-top: 1.6rem; font-size: .78rem; letter-spacing: .08em; }
[data-theme-layout="dtc-runway"] .page-head .eyebrow { letter-spacing: .34em; }
[data-theme-layout="dtc-runway"] .page-head h1 { font-family: var(--dt-display, var(--serif)); font-size: clamp(2.1rem, 4.6vw, 3.2rem); letter-spacing: .05em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .page-head p { margin-inline: auto; }
[data-theme-layout="dtc-runway"] .cat-nav { justify-content: center; gap: .5rem 1.9rem; margin: 0 0 2.4rem; padding: .95rem 0; border-block: 1px solid var(--line); }
[data-theme-layout="dtc-runway"] .cat-nav a { padding: 0; border: 0; border-radius: 0; color: var(--ink-soft); font-size: .8rem; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .cat-nav a:hover { border-color: transparent; color: var(--ink); }
[data-theme-layout="dtc-runway"] .cat-nav a.active { background: transparent; border: 0; color: var(--accent); box-shadow: 0 1px 0 0 var(--accent); }
[data-theme-layout="dtc-runway"] .cat-nav a.active .muted { color: currentColor; }
[data-theme-layout="dtc-runway"] .link-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: clamp(1.6rem, 3.5vw, 2.8rem); margin: 0 0 2.6rem; counter-reset: rwylook; }
[data-theme-layout="dtc-runway"] .link-card { position: relative; border: 0; border-radius: 0; background: transparent; overflow: visible; counter-increment: rwylook; transition: none; }
[data-theme-layout="dtc-runway"] .link-card:hover { transform: none; box-shadow: none; border-color: transparent; }
[data-theme-layout="dtc-runway"] .link-card::before { content: "№ " counter(rwylook, decimal-leading-zero); display: block; margin-bottom: .55rem; color: var(--accent); font-size: .72rem; font-weight: 750; letter-spacing: .26em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .lc-cover { aspect-ratio: 3 / 4; border-radius: 0; }
[data-theme-layout="dtc-runway"] .lc-cover img { transition: transform .35s ease; }
[data-theme-layout="dtc-runway"] .link-card:hover .lc-cover img { transform: scale(1.04); }
[data-theme-layout="dtc-runway"] .lc-body { padding: .95rem 0 0; }
[data-theme-layout="dtc-runway"] .lc-title { font-family: var(--dt-display, var(--serif)); font-size: 1.25rem; font-weight: 650; }
[data-theme-layout="dtc-runway"] .link-card:hover .lc-title { text-decoration: underline; text-decoration-color: var(--accent); text-underline-offset: .25em; }
[data-theme-layout="dtc-runway"] .lc-arrow { opacity: 1; transform: none; }
[data-theme-layout="dtc-runway"] .lc-intro { color: var(--muted); }
[data-theme-layout="dtc-runway"] .lc-foot .tag { padding: .22rem .6rem; border: 1px solid var(--line); border-radius: 0; background: transparent; color: var(--muted); font-size: .7rem; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .lc-foot .tag:hover { background: var(--ink); border-color: var(--ink); color: var(--bg); }
/* 生成封面/翻页去基础的「白字压 accent」（香槟金上白字在暗皮只有 2.31）：
   生成块走 wash+accent（6.99/4.50/4.91），当前页码走 ink 底 bg 字（≥16.4） */
[data-theme-layout="dtc-runway"] .lc-mono { background: var(--accent-wash); color: var(--accent); font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-runway"] .pagination a, [data-theme-layout="dtc-runway"] .pagination span { border-radius: 0; }
[data-theme-layout="dtc-runway"] .pagination a:hover { border-color: var(--ink); color: var(--ink); }
[data-theme-layout="dtc-runway"] .pagination .cur { background: var(--ink); border-color: var(--ink); color: var(--bg); }

/* ---- 内页·商品详情（product_detail DOM）：Look 页——左全身大图 3/4 竖裁，
   右单品清单卡（surface 卡 + sticky；pd-meta/specs 化为清单行） ---- */
[data-theme-layout="dtc-runway"] .pd-bc { padding-top: 1.6rem; font-size: .78rem; letter-spacing: .08em; }
[data-theme-layout="dtc-runway"] .pd-top { grid-template-columns: minmax(0, 1.08fr) minmax(300px, .92fr); }
[data-theme-layout="dtc-runway"] .pd-media { aspect-ratio: 3 / 4; border: 0; border-radius: 0; background: var(--line-soft); }
[data-theme-layout="dtc-runway"] .pd-media img { object-fit: cover; }
[data-theme-layout="dtc-runway"] .pd-media-gen b { font-family: var(--dt-display, var(--serif)); color: var(--accent); }
[data-theme-layout="dtc-runway"] .pd-thumbs { grid-template-columns: repeat(auto-fill, minmax(64px, 1fr)); }
[data-theme-layout="dtc-runway"] .pd-thumb { border-radius: 0; }
[data-theme-layout="dtc-runway"] .pd-info { position: sticky; top: 92px; border: 1px solid var(--line); background: var(--surface); padding: clamp(1.3rem, 2.6vw, 2rem); }
[data-theme-layout="dtc-runway"] .pd-kicker { font-family: var(--sans); letter-spacing: .24em; }
[data-theme-layout="dtc-runway"] .pd-title { font-family: var(--dt-display, var(--serif)); font-size: clamp(1.4rem, 2.6vw, 1.9rem); letter-spacing: .02em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .pd-title::after { content: ""; display: block; width: 44px; height: 2px; margin-top: .7rem; background: var(--accent); }
[data-theme-layout="dtc-runway"] .pd-lead { font-family: var(--dt-display, var(--serif)); font-style: italic; }
[data-theme-layout="dtc-runway"] .pd-meta-row { grid-template-columns: minmax(5.5rem, auto) minmax(0, 1fr); }
[data-theme-layout="dtc-runway"] .inquiry-title { font-family: var(--dt-display, var(--serif)); font-size: 1rem; letter-spacing: .12em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .pd-desc .prose { max-width: 74ch; }
[data-theme-layout="dtc-runway"] .pd-meta-row dt { align-self: baseline; font-size: .72rem; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .pd-sec-title { display: flex; align-items: center; gap: .8rem; font-family: var(--dt-display, var(--serif)); font-size: 1.1rem; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .pd-sec-title::after { content: ""; flex: 1; height: 1px; background: var(--line); }
[data-theme-layout="dtc-runway"] .pd-related-head a { flex: none; }
[data-theme-layout="dtc-runway"] .pd-specs-tablewrap { border-radius: 0; }
[data-theme-layout="dtc-runway"] .pd-specs-table th { background: transparent; font-size: .8rem; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; }
[data-theme-layout="dtc-runway"] .pd-rel-card { border: 0; border-radius: 0; background: transparent; overflow: visible; }
[data-theme-layout="dtc-runway"] .pd-rel-card:hover { transform: none; }
[data-theme-layout="dtc-runway"] .pd-rel-media { aspect-ratio: 3 / 4; }
[data-theme-layout="dtc-runway"] .pd-rel-gen b { font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-runway"] .pd-rel-title { padding: .7rem 0 0; }
[data-theme-layout="dtc-runway"] .pd-rel-card:hover .pd-rel-title { text-decoration: underline; text-decoration-color: var(--accent); text-underline-offset: .25em; }

/* ---- 响应式：920 折单列、720 归位普通流单列，375 无横向溢出（横排卡自滚） ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-runway"] .rwy-stage-inner { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-runway"] .rwy-stage-side { max-width: 340px; justify-self: start; }
  [data-theme-layout="dtc-runway"] .pd-top { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-runway"] .pd-info { position: static; }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-runway"] .rwy-stage { min-height: 520px; min-height: max(520px, 86svh); }
  [data-theme-layout="dtc-runway"] .rwy-series { gap: .4rem 1.3rem; }
  [data-theme-layout="dtc-runway"] .rwy-look { width: min(74vw, 320px); }
  [data-theme-layout="dtc-runway"] .rwy-quote { padding-left: 1rem; }
  [data-theme-layout="dtc-runway"] .link-grid { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-runway"] .pd-rel-grid { grid-template-columns: 1fr 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-runway"] .rwy-look-media img, [data-theme-layout="dtc-runway"] .lc-cover img { transition: none; }
  [data-theme-layout="dtc-runway"] .rwy-look:hover .rwy-look-media img, [data-theme-layout="dtc-runway"] .link-card:hover .lc-cover img { transform: none; }
}

/* ============================================================
   dtc-runway 皮肤 ×3：catwalk 近黑+香槟金 / catwalk-day 日场亮白+墨+金 /
   catwalk-white 纯白（中性灰基底对齐 answer-desk-white）。
   实算 WCAG：正文 ink/bg 16.43 / 16.86 / 18.72，muted ≥4.5（白皮见下方坑修），
   accent/bg 8.18 / 5.13 / 5.53，hover 走 accent-soft 11.03 / 7.25 / 7.75 只升不降。
   ============================================================ */
:root[data-theme="catwalk"] {
  --bg: #0d0c0e; --surface: #17151a; --ink: #f0ebe1; --ink-soft: #cec7b9;
  --muted: #a29a8c; --faint: #6f695e; --line: #2b2830; --line-soft: #1c1a20;
  --accent: #c9a25c; --accent-soft: #ddbf85; --accent-wash: #241d12;
  --radius: 0px; --w-wide: 1240px; --shadow: 0 1px 2px rgba(0,0,0,.4), 0 14px 34px rgba(0,0,0,.5);
}
:root[data-theme="catwalk-day"] {
  --bg: #faf9f6; --surface: #ffffff; --ink: #1a171c; --ink-soft: #46414b;
  --muted: #6a6358; --faint: #a49c90; --line: #e6e1d6; --line-soft: #f2efe8;
  --accent: #86651a; --accent-soft: #6b4f10; --accent-wash: #f2ead6;
  --radius: 0px; --w-wide: 1240px; --shadow: 0 1px 2px rgba(26,23,28,.05), 0 12px 30px rgba(26,23,28,.08);
}
:root[data-theme="catwalk-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #856318; --accent-soft: #6a4e0e; --accent-wash: #f7f1e2;
  --radius: 0px; --w-wide: 1240px; --shadow: 0 1px 2px rgba(16,18,24,.04), 0 12px 30px rgba(16,18,24,.07);
}
/* 纯白坑修：muted #707680 踩 #fafaf8 只有 4.38——凡带 muted 文字的卡面覆写回纯白
   （#fff 上 4.57）；CTA note 踩 wash 4.06 → 提为 ink-soft（8.69）。 */
:root[data-theme="catwalk-white"] :is(.pd-info, .pd-specs-tablewrap, .dt-stat, .f-chip) { background: #fff; }
:root[data-theme="catwalk-white"] .dt-cta-note { color: var(--ink-soft); }

/* =========================================================================
   LAYOUT: dtc-atelier — 工坊（DTC 外贸独立站 · 手作工作室）
   每条选择器限定 [data-theme-layout="dtc-atelier"]，类名前缀 atl-。
   导航=左竖签工牌：深木底竖排站名 + 链接竖排其下（≥921px）；621~920px 转顶部木条；
   ≤620px 交还基础汉堡抽屉（重塑段整体包在 min-width:621px 内）。
   hero=工作台叙事（衬线宽行距口述）；商品=器物卡 + 工艺行；内页=器物卡列表 +
   制作过程纵向时间线详情。皮肤 3 款：handcraft / handcraft-noir / handcraft-white。
   ========================================================================= */
[data-theme-layout="dtc-atelier"] {
  --atl-rail: 96px;
  --atl-wood: #423525; --atl-wood-ink: #f2e9d8;
  --atl-wood-act: #e3bf7d; --atl-wood-hov: #ffffff;
}

/* ---- 页头重塑（≥621px；620 以下基础汉堡抽屉原样接管） ---- */
@media (min-width: 621px) {
  /* 621~920px：顶部木条工牌 */
  [data-theme-layout="dtc-atelier"] .site-header { background: var(--atl-wood); border-bottom: 1px solid color-mix(in srgb, var(--atl-wood-ink) 18%, var(--atl-wood)); -webkit-backdrop-filter: none; backdrop-filter: none; }
  [data-theme-layout="dtc-atelier"] .site-header .brand,
  [data-theme-layout="dtc-atelier"] .site-header .brand-name { color: var(--atl-wood-ink); font-family: var(--serif); letter-spacing: .14em; }
  [data-theme-layout="dtc-atelier"] .nav a { color: var(--atl-wood-ink); }
  [data-theme-layout="dtc-atelier"] .nav a:hover { color: var(--atl-wood-hov); }
  [data-theme-layout="dtc-atelier"] .nav a[aria-current="page"] { color: var(--atl-wood-act); }
  [data-theme-layout="dtc-atelier"] .nav a[aria-current="page"]::after { background: var(--atl-wood-act); }
  [data-theme-layout="dtc-atelier"] .nav .search-ico { color: var(--atl-wood-ink); opacity: 1; }
  [data-theme-layout="dtc-atelier"] .nav .lang-switch summary,
  [data-theme-layout="dtc-atelier"] .nav .lang-cur { color: var(--atl-wood-ink); }
}
@media (min-width: 921px) {
  /* ≥921px：左竖签工牌——固定窄竖栏，站名/链接全竖排（工牌吊签） */
  [data-theme-layout="dtc-atelier"] body { padding-left: var(--atl-rail); }
  [data-theme-layout="dtc-atelier"] .site-header { position: fixed; inset: 0 auto 0 0; width: var(--atl-rail); height: 100vh; border-bottom: 0; border-right: 1px solid color-mix(in srgb, var(--atl-wood-ink) 18%, var(--atl-wood)); overflow-y: auto; z-index: 50; }
  [data-theme-layout="dtc-atelier"] .site-header .wrap { flex-direction: column; align-items: center; justify-content: flex-start; height: auto; min-height: 100%; max-width: none; padding: 1.3rem 8px 1rem; gap: 1.15rem; }
  [data-theme-layout="dtc-atelier"] .site-header .brand { writing-mode: vertical-rl; text-orientation: mixed; margin: 0; font-size: 1.22rem; letter-spacing: .3em; max-height: 42vh; overflow: hidden; }
  [data-theme-layout="dtc-atelier"] .site-header .brand-logo { height: 28px; width: auto; }
  [data-theme-layout="dtc-atelier"] .nav { flex: 1; flex-direction: column; align-items: center; gap: .8rem; width: 100%; }
  [data-theme-layout="dtc-atelier"] .nav > a { writing-mode: vertical-rl; text-orientation: mixed; padding: .78rem .32rem; border: 1px solid color-mix(in srgb, var(--atl-wood-ink) 30%, transparent); border-radius: 3px; background: color-mix(in srgb, var(--atl-wood-ink) 7%, transparent); font-size: .86rem; letter-spacing: .24em; max-height: 11em; overflow: hidden; }
  [data-theme-layout="dtc-atelier"] .nav > a:hover { border-color: var(--atl-wood-hov); }
  [data-theme-layout="dtc-atelier"] .nav a[aria-current="page"] { border-color: var(--atl-wood-act); }
  [data-theme-layout="dtc-atelier"] .nav a[aria-current="page"]::after { display: none; }
  [data-theme-layout="dtc-atelier"] .nav .search-ico { margin-top: auto; }
  [data-theme-layout="dtc-atelier"] .nav .lang-switch { border-left: 0; margin: 0; padding: 0; }
  [data-theme-layout="dtc-atelier"] .nav .lang-menu { left: .3rem; right: auto; }
}

/* ---- 首页（atl-*）：工作台叙事 hero + 分类木签 + 器物卡 ---- */
[data-theme-layout="dtc-atelier"] .atl-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-atelier"] .atl-hero { position: relative; margin-top: 1.6rem; border: 1px solid var(--line); border-top: 6px solid var(--atl-wood); border-radius: var(--radius); background: var(--surface); overflow: hidden; }
[data-theme-layout="dtc-atelier"] .atl-hero-inner { display: grid; grid-template-columns: minmax(0, 1.08fr) minmax(280px, .92fr); align-items: center; gap: clamp(1.2rem, 3vw, 2.6rem); padding: clamp(2rem, 5vw, 3.6rem); }
[data-theme-layout="dtc-atelier"] .atl-hero-copy { position: relative; padding-left: 3rem; } /* 左缘=竖排眉标的专属车道 */
[data-theme-layout="dtc-atelier"] .atl-hero-mark { position: absolute; left: 0; top: .25rem; margin: 0; writing-mode: vertical-rl; text-orientation: mixed; color: var(--accent); font-family: var(--sans); font-size: .72rem; font-weight: 750; letter-spacing: .3em; text-transform: uppercase; max-height: 15em; overflow: hidden; } /* 装饰长文钳高 */
[data-theme-layout="dtc-atelier"] .atl-h1 { margin: 0; max-width: 14em; font-family: var(--dt-display, var(--serif)); font-size: clamp(2rem, 4.2vw, 3.1rem); font-weight: 640; line-height: 1.16; letter-spacing: -.01em; }
[data-theme-layout="dtc-atelier"] .atl-tale { max-width: 54ch; margin: 1.15rem 0 0; font-family: var(--serif); font-size: 1.05rem; line-height: 2.05; color: var(--ink-soft); } /* 主理人口述：衬线 + 宽行距 */
[data-theme-layout="dtc-atelier"] .atl-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="dtc-atelier"] .atl-hero-side { min-width: 0; }
[data-theme-layout="dtc-atelier"] .atl-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-atelier"] .atl-hero.has-img { min-height: min(70vh, 540px); display: flex; align-items: flex-end; border-color: transparent; }
[data-theme-layout="dtc-atelier"] .atl-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(100deg, rgba(14,11,7,.68) 0%, rgba(14,11,7,.42) 46%, rgba(14,11,7,.06) 76%), linear-gradient(198deg, rgba(14,11,7,0) 40%, rgba(14,11,7,.52) 96%); }
[data-theme-layout="dtc-atelier"] .atl-hero.has-img .atl-hero-inner { position: relative; z-index: 1; grid-template-columns: minmax(0, 1fr); }
[data-theme-layout="dtc-atelier"] .atl-hero.has-img .atl-hero-copy { color: #fff; }
[data-theme-layout="dtc-atelier"] .atl-hero.has-img .atl-hero-mark { color: #fff; opacity: .85; }
[data-theme-layout="dtc-atelier"] .atl-hero.has-img .atl-h1 { color: #fff; } /* 全局 h1 色规则会盖过容器继承，压图必须显式白字 */
[data-theme-layout="dtc-atelier"] .atl-hero.has-img .atl-tale { color: rgba(255,255,255,.88); }
[data-theme-layout="dtc-atelier"] .atl-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-atelier"] .atl-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-atelier"] .atl-hero.has-img .btn-primary { background: #fff; border-color: #fff; color: #181310; }
/* 分类=货架木签（左侧厚签舌） */
[data-theme-layout="dtc-atelier"] .atl-shelf { display: flex; flex-wrap: wrap; gap: .6rem; margin-top: 2.1rem; }
[data-theme-layout="dtc-atelier"] .atl-shelf-tag { display: inline-flex; align-items: baseline; gap: .5rem; padding: .48rem .9rem .48rem 1rem; border: 1px solid var(--line); border-left: 4px solid var(--accent); border-radius: 2px; background: var(--surface); color: var(--ink-soft); font-size: .9rem; }
[data-theme-layout="dtc-atelier"] .atl-shelf-tag:hover { background: var(--accent-wash); color: var(--ink); border-left-color: var(--accent-soft); }
[data-theme-layout="dtc-atelier"] .atl-shelf-tag small { color: var(--muted); font-family: var(--mono); font-size: .7rem; }
[data-theme-layout="dtc-atelier"] .atl-section { padding-top: clamp(2.8rem, 6vw, 4.2rem); }
/* 器物卡：方图 + 衬线名 + 工艺行（productChips 点线对账行） */
[data-theme-layout="dtc-atelier"] .atl-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(235px, 100%), 1fr)); gap: 1.15rem; }
[data-theme-layout="dtc-atelier"] .atl-card { display: flex; min-width: 0; flex-direction: column; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); overflow: hidden; transition: transform var(--speed), border-color var(--speed), box-shadow var(--speed); }
[data-theme-layout="dtc-atelier"] .atl-card:hover { transform: translateY(-3px); border-color: var(--accent); box-shadow: var(--shadow); color: var(--ink); }
[data-theme-layout="dtc-atelier"] .atl-card-media { display: grid; place-items: center; aspect-ratio: 1 / 1; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-atelier"] .atl-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-atelier"] .atl-card:hover .atl-card-media img { transform: scale(1.04); }
[data-theme-layout="dtc-atelier"] .atl-card-body { display: flex; flex-direction: column; gap: .3rem; padding: .95rem 1rem 1.05rem; }
[data-theme-layout="dtc-atelier"] .atl-card-cat { color: var(--accent); font-size: .7rem; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; }
[data-theme-layout="dtc-atelier"] .atl-card-title { font-family: var(--serif); font-size: 1.06rem; font-weight: 650; line-height: 1.4; }
[data-theme-layout="dtc-atelier"] .atl-card:hover .atl-card-title { color: var(--accent); }
[data-theme-layout="dtc-atelier"] .atl-craft { display: block; margin-top: .5rem; }
[data-theme-layout="dtc-atelier"] .atl-craft-row { display: flex; justify-content: space-between; gap: 1rem; padding: .34rem 0; border-top: 1px dotted var(--line); font-size: .8rem; }
[data-theme-layout="dtc-atelier"] .atl-craft-row b { flex: none; color: var(--muted); font-weight: 600; }
[data-theme-layout="dtc-atelier"] .atl-craft-row i { min-width: 0; overflow: hidden; color: var(--ink-soft); font-style: normal; text-align: right; text-overflow: ellipsis; white-space: nowrap; }
[data-theme-layout="dtc-atelier"] .atl-about { max-width: 62ch; margin: 0; font-family: var(--serif); font-size: clamp(1.02rem, 1.7vw, 1.24rem); line-height: 2.1; color: var(--ink-soft); }
[data-theme-layout="dtc-atelier"] .atl-bench .f-gallery-item { border-radius: 2px; }

/* ---- 内页 · 商品列表（generic_list DOM）：器物卡母题跟随——
   page-head=工作台沿（accent 顶签细横带）、分类导航=货架木签（同首页 atl-shelf 语言）、
   link-card=器物卡（方图 + 点线分隔 + 衬线名 + 工艺签脚注） ---- */
[data-theme-layout="dtc-atelier"] .page-head { position: relative; padding-top: 3.4rem; border-bottom: 1px solid var(--line); }
[data-theme-layout="dtc-atelier"] .page-head::before { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 6px; background: var(--atl-wood); } /* 台沿：与首页 hero 顶边同语言 */
[data-theme-layout="dtc-atelier"] .page-head h1 { font-family: var(--serif); font-weight: 650; letter-spacing: -.01em; }
[data-theme-layout="dtc-atelier"] .page-head .eyebrow { letter-spacing: .3em; }
[data-theme-layout="dtc-atelier"] .page-head .hero-sub { font-family: var(--serif); line-height: 1.9; }
[data-theme-layout="dtc-atelier"] .breadcrumb a { color: var(--muted); }
[data-theme-layout="dtc-atelier"] .breadcrumb a:hover { color: var(--accent); }
[data-theme-layout="dtc-atelier"] .cat-nav { gap: .6rem; }
[data-theme-layout="dtc-atelier"] .cat-nav a { border-radius: 2px; border: 1px solid var(--line); border-left: 4px solid var(--accent); background: var(--surface); }
[data-theme-layout="dtc-atelier"] .cat-nav a:hover { background: var(--accent-wash); border-color: var(--line); border-left-color: var(--accent-soft); color: var(--ink); }
[data-theme-layout="dtc-atelier"] .cat-nav a.active { border-left-color: var(--ink); }
[data-theme-layout="dtc-atelier"] .cat-nav a .muted { font-family: var(--mono); }
[data-theme-layout="dtc-atelier"] .link-grid { grid-template-columns: repeat(auto-fill, minmax(min(235px, 100%), 1fr)); gap: 1.15rem; }
[data-theme-layout="dtc-atelier"] .link-card { border-radius: var(--radius); }
[data-theme-layout="dtc-atelier"] .link-card:hover { box-shadow: var(--shadow); }
[data-theme-layout="dtc-atelier"] .lc-cover { aspect-ratio: 1 / 1; }
[data-theme-layout="dtc-atelier"] .lc-cover img { transition: transform .3s ease; }
[data-theme-layout="dtc-atelier"] .link-card:hover .lc-cover img { transform: scale(1.04); }
[data-theme-layout="dtc-atelier"] .lc-mono { background: var(--accent-wash); color: var(--accent); font-family: var(--serif); } /* 生成字避开基础白字压 accent 渐变（noir 金底白字不达标） */
[data-theme-layout="dtc-atelier"] .lc-body { border-top: 1px dotted var(--line); padding: .95rem 1rem 1.05rem; }
[data-theme-layout="dtc-atelier"] .lc-title { font-family: var(--serif); font-size: 1.06rem; font-weight: 650; }
[data-theme-layout="dtc-atelier"] .lc-arrow { color: var(--accent); }
[data-theme-layout="dtc-atelier"] .lc-intro { display: -webkit-box; overflow: hidden; color: var(--muted); font-size: .86rem; line-height: 1.7; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="dtc-atelier"] .link-grid > .muted { grid-column: 1 / -1; margin: 0; padding: 1.8rem; border: 1px dashed var(--line); border-radius: var(--radius); text-align: center; } /* 空态（factory.no_products）优雅缺省 */
[data-theme-layout="dtc-atelier"] .lc-foot { padding-top: .5rem; border-top: 1px dotted var(--line); }
[data-theme-layout="dtc-atelier"] .lc-foot .tag { border-radius: 2px; }
[data-theme-layout="dtc-atelier"] .pagination a, [data-theme-layout="dtc-atelier"] .pagination span { border-radius: 2px; }
[data-theme-layout="dtc-atelier"] .pagination a:hover { background: var(--accent-wash); }
[data-theme-layout="dtc-atelier"] .pagination .cur { background: var(--ink); border-color: var(--ink); color: var(--surface); } /* 基础白字压 accent 在 noir 金底不达标，换 ink 底 surface 字 */

/* ---- 内页 · 商品详情（product_detail DOM）：器物档案——图为素坯板（方角）、
   规格 specs 表格化 DOM 重塑为「制作过程」纵向时间线（tr=工序行）、询盘区=订购面板 ---- */
[data-theme-layout="dtc-atelier"] .pd-bc a { color: var(--muted); }
[data-theme-layout="dtc-atelier"] .pd-bc a:hover { color: var(--accent); }
[data-theme-layout="dtc-atelier"] .pd-title { font-family: var(--serif); font-weight: 650; letter-spacing: -.01em; }
[data-theme-layout="dtc-atelier"] .pd-kicker { font-family: var(--sans); letter-spacing: .18em; }
[data-theme-layout="dtc-atelier"] .pd-lead { font-family: var(--serif); line-height: 1.9; }
[data-theme-layout="dtc-atelier"] .pd-media, [data-theme-layout="dtc-atelier"] .pd-thumb { border-radius: 2px; }
[data-theme-layout="dtc-atelier"] .pd-media-gen b { font-family: var(--serif); }
[data-theme-layout="dtc-atelier"] .pd-meta-row { border-bottom: 1px dotted var(--line); }
[data-theme-layout="dtc-atelier"] .pd-meta { border-top: 1px dotted var(--line); }
[data-theme-layout="dtc-atelier"] .pd-meta-row dt { font-size: .78rem; letter-spacing: .1em; text-transform: uppercase; }
/* 订购区：工作台面板（accent 顶签），询盘按钮即订购按钮 */
[data-theme-layout="dtc-atelier"] .pd-inquiry { margin-top: 1.35rem; padding: 1.15rem 1.2rem 1.25rem; border: 1px solid var(--line); border-top: 4px solid var(--accent); border-radius: 3px; background: var(--surface); }
[data-theme-layout="dtc-atelier"] .pd-inquiry .inquiry-title { font-family: var(--serif); }
[data-theme-layout="dtc-atelier"] .pd-inquiry .inquiry-btn { border-radius: 999px; }
[data-theme-layout="dtc-atelier"] .pd-sec-title { font-family: var(--serif); }
/* specs 表格化 DOM → 工序时间线：tr=一道工序（左侧线 + 圆号节点），th=工序名，td=说明 */
[data-theme-layout="dtc-atelier"] .pd-specs-tablewrap { border: 0; border-radius: 0; background: transparent; overflow: visible; }
[data-theme-layout="dtc-atelier"] .pd-specs-table, [data-theme-layout="dtc-atelier"] .pd-specs-table tbody { display: block; width: 100%; }
[data-theme-layout="dtc-atelier"] .pd-specs-table tbody { counter-reset: atlstep; }
[data-theme-layout="dtc-atelier"] .pd-specs-table tr { display: block; position: relative; padding: .1rem 0 1.15rem 2.7rem; counter-increment: atlstep; } /* 左 2.7rem=节点专属车道 */
[data-theme-layout="dtc-atelier"] .pd-specs-table tr::before { content: ""; position: absolute; left: 12px; top: 4px; bottom: -4px; width: 2px; background: var(--line); }
[data-theme-layout="dtc-atelier"] .pd-specs-table tr:last-child::before { bottom: auto; height: 1.5rem; }
[data-theme-layout="dtc-atelier"] .pd-specs-table tr::after { content: counter(atlstep, decimal-leading-zero); position: absolute; left: 0; top: 0; display: grid; place-items: center; width: 26px; height: 26px; border: 2px solid var(--accent); border-radius: 50%; background: var(--surface); color: var(--accent); font-family: var(--mono); font-size: .6rem; font-weight: 800; }
[data-theme-layout="dtc-atelier"] .pd-specs-table th, [data-theme-layout="dtc-atelier"] .pd-specs-table td { display: block; width: auto; min-width: 0; padding: 0; border: 0; background: transparent; text-align: left; }
[data-theme-layout="dtc-atelier"] .pd-specs-table th { margin-bottom: .18rem; color: var(--muted); font-size: .74rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
[data-theme-layout="dtc-atelier"] .pd-specs-table td { color: var(--ink); font-size: .96rem; line-height: 1.75; }
[data-theme-layout="dtc-atelier"] .pd-specs, [data-theme-layout="dtc-atelier"] .pd-desc { border-top: 1px dotted var(--line); padding-top: 1.9rem; }
[data-theme-layout="dtc-atelier"] .pd-inquiry .inquiry-note { color: var(--muted); font-size: .88rem; }
[data-theme-layout="dtc-atelier"] .pd-desc .prose { font-family: var(--serif); line-height: 2; }
[data-theme-layout="dtc-atelier"] .pd-rel-title { font-family: var(--serif); }
[data-theme-layout="dtc-atelier"] .pd-rel-card:hover .pd-rel-title { color: var(--accent); }
[data-theme-layout="dtc-atelier"] .pd-rel-media { border-radius: 2px; }

/* ---- 断点：920 单列 hero、720 全线单列；装饰竖标回归普通流 ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-atelier"] .atl-hero-inner { grid-template-columns: 1fr; padding: clamp(1.6rem, 5vw, 2.4rem); }
  [data-theme-layout="dtc-atelier"] .atl-hero-side { max-width: 420px; }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-atelier"] .atl-grid, [data-theme-layout="dtc-atelier"] .link-grid { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-atelier"] .atl-hero-copy { padding-left: 0; }
  [data-theme-layout="dtc-atelier"] .atl-hero-mark { position: static; writing-mode: horizontal-tb; max-height: none; margin: 0 0 .7rem; letter-spacing: .2em; }
  [data-theme-layout="dtc-atelier"] .atl-hero.has-img { min-height: 60vh; }
  [data-theme-layout="dtc-atelier"] .atl-craft-row i { white-space: normal; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-atelier"] .atl-card, [data-theme-layout="dtc-atelier"] .atl-card-media img { transition: none; }
  [data-theme-layout="dtc-atelier"] .atl-card:hover { transform: none; }
  [data-theme-layout="dtc-atelier"] .atl-card:hover .atl-card-media img { transform: none; }
}

/* ============================================================
   手作 · Handcraft（dtc-atelier）：麻米纸底 + 深木 + 近黑——原生亚麻工坊
   实算对比度：ink/bg 14.27、ink/surface 15.45、ink-soft/bg 9.08、
   muted/bg 5.42、muted/surface 5.87、muted/wash 4.77、accent/bg 6.97、
   accent/surface 7.55、accent/wash 6.14、hover soft/bg 9.88（只升）、
   btn(ink底surface字) 15.45、工牌 wood-ink/wood 9.86、wood-act/wood 6.80
   ============================================================ */
:root[data-theme="handcraft"] {
  --bg: #efe9dd; --surface: #f7f2e7;
  --ink: #201a11; --ink-soft: #453b2b; --muted: #675c49; --faint: #8a7d66;
  --line: #d9cdb4; --line-soft: #e6dcc7;
  --accent: #5d4a33; --accent-soft: #443421; --accent-wash: #e6dbc4;
  --atl-wood: #423525; --atl-wood-ink: #f2e9d8; --atl-wood-act: #e3bf7d; --atl-wood-hov: #ffffff;
  --w-wide: 1200px; --radius: 4px;
  --shadow: 0 1px 2px rgba(32,26,17,.06), 0 10px 24px rgba(32,26,17,.08);
}

/* ============================================================
   手作暗夜 · Handcraft Noir（dtc-atelier，暗）：深木夜底 + 烛金点睛
   实算对比度：ink/bg 15.33、ink/surface 14.14、ink-soft/bg 11.31、
   muted/bg 7.21、muted/surface 6.65、muted/wash 5.81、accent/bg 8.53、
   accent/surface 7.87、accent/wash 6.88、hover soft/bg 10.90（只升）、
   btn(ink底surface字) 14.14、工牌 wood-ink/wood 16.18、wood-act/wood 10.31
   ============================================================ */
:root[data-theme="handcraft-noir"] {
  --bg: #18130e; --surface: #221b13;
  --ink: #f3e9d7; --ink-soft: #d8c9ad; --muted: #b0a084; --faint: #857863;
  --line: #3b3223; --line-soft: #2c2517;
  --accent: #dda74f; --accent-soft: #eec06f; --accent-wash: #302614;
  --atl-wood: #100c08; --atl-wood-ink: #f3e9d7; --atl-wood-act: #e5b562; --atl-wood-hov: #ffffff;
  --w-wide: 1200px; --radius: 4px; --code-bg: #0d0a06;
  --shadow: 0 1px 2px rgba(0,0,0,.5), 0 12px 30px rgba(0,0,0,.55);
}

/* ============================================================
   手作纯白 · Handcraft White（dtc-atelier）：纯白基底 + 木褐点缀；
   工牌竖栏转白底细线（深字），muted 压深到 #656b75 避开 #fafaf8 上 4.38 坑。
   实算对比度：ink/bg 18.72、ink/surface 17.91、ink-soft/bg 9.79、
   muted/bg 5.37、muted/surface 5.13、muted/wash 4.65、accent/bg 7.21、
   accent/surface 6.90、accent/wash 6.24、hover soft/bg 9.84（只升）、
   btn(ink底surface字) 17.91、工牌 wood-ink/wood 18.72、wood-act/wood 7.21
   ============================================================ */
:root[data-theme="handcraft-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #656b75; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #6b5335; --accent-soft: #53402a; --accent-wash: #f4eee3;
  --atl-wood: #ffffff; --atl-wood-ink: #101218; --atl-wood-act: #6b5335; --atl-wood-hov: #53402a;
  --w-wide: 1200px; --radius: 6px;
}
:root[data-theme="handcraft-white"] .atl-hero { border-top-color: var(--accent); } /* 白皮工牌无深木底，台沿改木褐 */
:root[data-theme="handcraft-white"] .pd-specs-table tr::after { background: var(--bg); }

/* =========================================================================
   LAYOUT: dtc-monthbox — 月盒：订阅盒气质的外贸独立站（every selector scoped
   under [data-theme-layout="dtc-monthbox"]，classes mbx-*）。
   页头 CSS 重塑为居中三段页签：品牌居中在上，主导航压成等宽页签带（边框相接，
   margin-left:-1px 合线），当前页签 accent-wash 亮面 + 顶缘 accent 粗线；
   home：「本月盒」大卡 hero（期号券标 + 右侧盒盖立体感=纯 CSS 叠板阴影）
   →「往期盒」小卡横排（自带横滚车道）→ 数字/评价 →「订阅须知」勾选折叠条列。
   共用 dt-*（前缀 ^dtc- 规则自动命中）；三皮 monthbox / monthbox-noir / monthbox-white。
   ========================================================================= */
/* ---- 页头 · 居中三段页签（≤620px 交还基础汉堡抽屉，重塑段全包 min-width:621px） ---- */
@media (min-width: 621px) {
  [data-theme-layout="dtc-monthbox"] .site-header .wrap { flex-direction: column; justify-content: center; gap: .6rem; height: auto; padding-top: .85rem; padding-bottom: .85rem; }
  [data-theme-layout="dtc-monthbox"] .brand { justify-content: center; }
  [data-theme-layout="dtc-monthbox"] .brand-tagline { margin: -.25rem 0 0; color: var(--muted); font-size: .76rem; text-align: center; }
  [data-theme-layout="dtc-monthbox"] .nav { justify-content: center; flex-wrap: wrap; gap: 0; }
  [data-theme-layout="dtc-monthbox"] .nav > a:not(.search-ico) {
    flex: 1 1 0; min-width: 0; max-width: 180px; margin-left: -1px; padding: .58rem 1.1rem;
    border: 1px solid var(--line); background: var(--surface); color: var(--ink-soft);
    font-size: .9rem; font-weight: 600; text-align: center;
    overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
    transition: color var(--speed), background var(--speed);
  }
  [data-theme-layout="dtc-monthbox"] .nav > a:not(.search-ico):first-child { margin-left: 0; border-radius: 9px 0 0 9px; }
  [data-theme-layout="dtc-monthbox"] .nav > a:not(.search-ico):has(+ .search-ico) { border-radius: 0 9px 9px 0; }
  [data-theme-layout="dtc-monthbox"] .nav > a:not(.search-ico):hover { color: var(--accent); }
  [data-theme-layout="dtc-monthbox"] .nav > a[aria-current="page"] { background: var(--accent-wash); color: var(--ink); box-shadow: inset 0 2px 0 var(--accent); }
  [data-theme-layout="dtc-monthbox"] .nav > a[aria-current="page"]::after { display: none; } /* 底线指示让位页签亮面；≤620px 抽屉保留基础指示 */
  [data-theme-layout="dtc-monthbox"] .nav .search-ico { margin-left: .9rem; }
}

/* ---- home 容器 + 「本月盒」大卡 hero（三态：image 全幅 scrim / svg / 盒盖·轻动画） ---- */
[data-theme-layout="dtc-monthbox"] .mbx-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-monthbox"] .mbx-hero { position: relative; margin-top: 1.6rem; border: 1px solid var(--line); border-radius: calc(var(--radius) * 1.5); background: linear-gradient(160deg, var(--accent-wash), var(--surface) 62%); overflow: hidden; }
[data-theme-layout="dtc-monthbox"] .mbx-hero-inner { position: relative; z-index: 1; display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(280px, .9fr); align-items: center; gap: clamp(1.4rem, 3.4vw, 3rem); padding: clamp(2.2rem, 5vw, 3.8rem); }
[data-theme-layout="dtc-monthbox"] .mbx-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img { min-height: min(70vh, 540px); display: flex; align-items: flex-end; border: 0; }
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(102deg, rgba(10,10,12,.66) 0%, rgba(10,10,12,.4) 46%, rgba(10,10,12,.05) 74%), linear-gradient(200deg, rgba(10,10,12,0) 42%, rgba(10,10,12,.5) 96%); }
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img .mbx-hero-inner { grid-template-columns: minmax(0, 1fr); }
/* 期号券标（HeroEyebrow）：mono 大写 + 虚线券边——订阅期刊的「本期」戳 */
[data-theme-layout="dtc-monthbox"] .mbx-issue { display: inline-flex; align-items: center; gap: .5rem; margin: 0 0 1.1rem; padding: .34rem .8rem; border: 1px dashed var(--accent); border-radius: 8px; color: var(--accent); font-family: var(--mono); font-size: .74rem; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; overflow-wrap: anywhere; }
[data-theme-layout="dtc-monthbox"] .mbx-h1 { margin: 0; max-width: 15em; font-family: var(--dt-display, var(--serif)); font-size: clamp(2.1rem, 4.6vw, 3.3rem); font-weight: 650; line-height: 1.12; letter-spacing: -.015em; }
/* 描述钳高 4 行——装饰位不许把大卡撑成长文 */
[data-theme-layout="dtc-monthbox"] .mbx-lede { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 4; max-width: 56ch; margin: 1rem 0 0; color: var(--muted); font-size: 1.02rem; line-height: 1.8; }
/* 本月盒主打条（第一件商品：标题 + 规格签）——盒面上贴的内容签 */
[data-theme-layout="dtc-monthbox"] .mbx-pick { display: flex; flex-direction: column; gap: .1rem; max-width: 460px; margin-top: 1.4rem; padding: .9rem 1.05rem 1rem; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); transition: border-color var(--speed), box-shadow var(--speed); }
[data-theme-layout="dtc-monthbox"] .mbx-pick:hover { border-color: var(--accent); box-shadow: var(--shadow); color: var(--ink); }
[data-theme-layout="dtc-monthbox"] .mbx-pick-title { font-size: .98rem; font-weight: 650; line-height: 1.5; }
[data-theme-layout="dtc-monthbox"] .mbx-pick:hover .mbx-pick-title { color: var(--accent); }
[data-theme-layout="dtc-monthbox"] .mbx-pick .arrow { color: var(--faint); transition: color var(--speed); }
[data-theme-layout="dtc-monthbox"] .mbx-pick:hover .arrow { color: var(--accent); }
[data-theme-layout="dtc-monthbox"] .mbx-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.6rem; }
/* 压图态白字（同 flagship scrim 口径）；主打条落成实白面板，字色定死深墨 */
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img .mbx-hero-copy { color: #fff; }
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img .mbx-issue { border-color: rgba(255,255,255,.75); color: #fff; }
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img .mbx-h1 { color: #fff; } /* 全局 h1 色规则会盖过容器继承，压图必须显式白字 */
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img .mbx-lede { color: rgba(255,255,255,.85); }
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img .mbx-pick { border-color: transparent; background: rgba(255,255,255,.95); }
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img .mbx-pick-title,
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img .mbx-pick:hover .mbx-pick-title { color: #14151a; }
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-monthbox"] .mbx-hero.has-img .btn-primary { background: #fff; border-color: #fff; color: #14151a; }
/* 盒盖（第一件商品图）：纯 CSS 阴影立体感——盖面 + 内缘线 + 两层叠板 + 落影 */
[data-theme-layout="dtc-monthbox"] .mbx-hero-side { min-width: 0; }
[data-theme-layout="dtc-monthbox"] .mbx-lid { position: relative; display: block; aspect-ratio: 4 / 3; border-radius: calc(var(--radius) * 1.2); background: var(--line-soft); overflow: hidden; box-shadow: 0 10px 0 -4px var(--line-soft), 0 19px 0 -8px var(--line), 0 36px 44px -18px rgba(12,10,6,.4); }
[data-theme-layout="dtc-monthbox"] .mbx-lid::after { content: ""; position: absolute; inset: 0; border: 1px solid color-mix(in srgb, var(--ink) 16%, transparent); border-radius: inherit; pointer-events: none; }
[data-theme-layout="dtc-monthbox"] .mbx-lid img { width: 100%; height: 100%; object-fit: cover; }

/* ---- 「往期盒」小卡横排：自带横滚车道（overflow-x），NO. 计数签 + 方图 + 规格签 ---- */
[data-theme-layout="dtc-monthbox"] .mbx-section { padding-top: clamp(3rem, 6vw, 4.5rem); }
[data-theme-layout="dtc-monthbox"] .mbx-row { display: grid; grid-auto-flow: column; grid-auto-columns: min(232px, 72vw); gap: 1rem; padding-bottom: .6rem; overflow-x: auto; scroll-snap-type: x proximity; scrollbar-width: thin; counter-reset: mbxp; }
[data-theme-layout="dtc-monthbox"] .mbx-box { display: flex; flex-direction: column; min-width: 0; scroll-snap-align: start; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); overflow: hidden; transition: transform var(--speed), border-color var(--speed), box-shadow var(--speed); }
[data-theme-layout="dtc-monthbox"] .mbx-box:hover { transform: translateY(-3px); border-color: var(--accent); box-shadow: var(--shadow); color: var(--ink); }
[data-theme-layout="dtc-monthbox"] .mbx-box-media { display: grid; place-items: center; aspect-ratio: 1 / 1; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-monthbox"] .mbx-box-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-monthbox"] .mbx-box:hover .mbx-box-media img { transform: scale(1.04); }
[data-theme-layout="dtc-monthbox"] .mbx-box-body { display: flex; flex-direction: column; gap: .3rem; padding: .8rem .95rem 1rem; }
[data-theme-layout="dtc-monthbox"] .mbx-box-no { color: var(--accent); font-family: var(--mono); font-size: .74rem; font-weight: 750; letter-spacing: .12em; }
[data-theme-layout="dtc-monthbox"] .mbx-box-no::before { content: "№"; }
[data-theme-layout="dtc-monthbox"] .mbx-box-title { font-size: .96rem; font-weight: 650; line-height: 1.45; }
[data-theme-layout="dtc-monthbox"] .mbx-box:hover .mbx-box-title { color: var(--accent); }

/* ---- 「订阅须知」折叠条列：虚线分隔 + 勾选框标（Q 字替换为 ✓，纯装饰） ---- */
[data-theme-layout="dtc-monthbox"] .mbx-notes .f-faq, [data-theme-layout="dtc-monthbox"] .mbx-notes .f-faq-item { border-style: dashed; }
[data-theme-layout="dtc-monthbox"] .mbx-notes .f-faq-marker { font-size: 0; }
[data-theme-layout="dtc-monthbox"] .mbx-notes .f-faq-marker::before { content: "✓"; display: grid; place-items: center; width: 1.1rem; height: 1.1rem; border: 1px solid var(--accent); border-radius: 5px; color: var(--accent); font-size: .68rem; font-weight: 800; line-height: 1; }
[data-theme-layout="dtc-monthbox"] .mbx-notes .f-faq-a { padding-left: 1.85rem; }
[data-theme-layout="dtc-monthbox"] .dt-cta-inner { border-radius: calc(var(--radius) * 1.5); }

/* ---- 内页 · 商品/内容列表（generic_list DOM）：盒卡格 ---- */
[data-theme-layout="dtc-monthbox"] .page-head { padding: 2.6rem 0 2rem; border-bottom: 1px dashed var(--line); background: linear-gradient(180deg, var(--accent-wash), var(--bg)); }
[data-theme-layout="dtc-monthbox"] .page-head .eyebrow { color: var(--accent); font-family: var(--mono); letter-spacing: .18em; }
[data-theme-layout="dtc-monthbox"] .page-head h1 { font-family: var(--dt-display, var(--serif)); letter-spacing: -.01em; }
/* 分类条＝同页头语言的等宽页签段（active=accent-wash 亮面 + 顶缘 accent 线） */
[data-theme-layout="dtc-monthbox"] .cat-nav { gap: 0; margin: 1.8rem 0; }
[data-theme-layout="dtc-monthbox"] .cat-nav a { margin-left: -1px; border-radius: 0; border-color: var(--line); background: var(--surface); color: var(--ink-soft); font-weight: 600; transition: color var(--speed), background var(--speed); }
[data-theme-layout="dtc-monthbox"] .cat-nav a:first-child { margin-left: 0; border-radius: 9px 0 0 9px; }
[data-theme-layout="dtc-monthbox"] .cat-nav a:last-child { border-radius: 0 9px 9px 0; }
[data-theme-layout="dtc-monthbox"] .cat-nav a:hover { border-color: var(--line); color: var(--accent); }
[data-theme-layout="dtc-monthbox"] .cat-nav a.active { background: var(--accent-wash); border-color: var(--line); color: var(--ink); box-shadow: inset 0 2px 0 var(--accent); }
[data-theme-layout="dtc-monthbox"] .cat-nav a.active .muted { color: var(--muted); opacity: 1; }
/* 列表卡＝盒卡：NO. 计数签行（虚线分隔）+ 方图 + 叠板落影，跟随 home 往期盒母题 */
[data-theme-layout="dtc-monthbox"] .link-grid { grid-template-columns: repeat(auto-fill, minmax(min(230px, 100%), 1fr)); margin: 1.8rem 0 2.4rem; counter-reset: mbxl; }
[data-theme-layout="dtc-monthbox"] .link-card { counter-increment: mbxl; box-shadow: 0 7px 0 -3px var(--line-soft); }
[data-theme-layout="dtc-monthbox"] .link-card:hover { box-shadow: 0 7px 0 -3px var(--line), var(--shadow); }
[data-theme-layout="dtc-monthbox"] .link-card::before { content: "№ " counter(mbxl, decimal-leading-zero); display: flex; align-items: center; padding: .48rem .95rem; border-bottom: 1px dashed var(--line); color: var(--accent); font-family: var(--mono); font-size: .74rem; font-weight: 750; letter-spacing: .12em; }
[data-theme-layout="dtc-monthbox"] .lc-cover { aspect-ratio: 1 / 1; }
[data-theme-layout="dtc-monthbox"] .lc-mono { background: var(--accent-wash); color: var(--accent); font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-monthbox"] .lc-title { font-size: 1rem; font-weight: 650; }
[data-theme-layout="dtc-monthbox"] .lc-intro { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; color: var(--muted); }
[data-theme-layout="dtc-monthbox"] .lc-foot .tag { border: 1px solid var(--line); border-radius: 999px; background: var(--surface); color: var(--accent); font-family: var(--mono); font-size: .7rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-monthbox"] .link-grid > .muted { grid-column: 1 / -1; margin: 0; padding: 1.8rem; border: 1px dashed var(--line); border-radius: var(--radius); text-align: center; }
[data-theme-layout="dtc-monthbox"] .pagination .cur { background: var(--ink); border-color: var(--ink); color: var(--surface); }
[data-theme-layout="dtc-monthbox"] .pagination a:hover { border-color: var(--accent); color: var(--accent); }

/* ---- 内页 · 商品详情（product_detail DOM）：「盒内清单」 ---- */
[data-theme-layout="dtc-monthbox"] .pd-kicker a { display: inline-block; padding: .2rem .65rem; border: 1px dashed var(--accent); border-radius: 8px; color: var(--accent); letter-spacing: .14em; }
[data-theme-layout="dtc-monthbox"] .pd-title { font-family: var(--dt-display, var(--serif)); font-weight: 650; letter-spacing: -.01em; }
[data-theme-layout="dtc-monthbox"] .pd-media { background: var(--surface); box-shadow: 0 9px 0 -4px var(--line-soft); }
[data-theme-layout="dtc-monthbox"] .pd-media-gen { background: var(--accent-wash); }
[data-theme-layout="dtc-monthbox"] .pd-media-gen b { font-family: var(--dt-display, var(--serif)); color: var(--accent); }
[data-theme-layout="dtc-monthbox"] .pd-meta-row dt { font-family: var(--mono); font-size: .8rem; letter-spacing: .04em; text-transform: uppercase; }
/* 询盘区＝订阅卡：accent-wash 软卡（首屏可见），按钮走族规胶囊 */
[data-theme-layout="dtc-monthbox"] .pd-inquiry { padding: 1.5rem 1.4rem 1.4rem; border-radius: calc(var(--radius) * 1.2); background: var(--accent-wash); }
[data-theme-layout="dtc-monthbox"] .pd-inquiry .inquiry-note { color: var(--muted); }
/* 规格表＝「盒内清单」：去表头底色、行改虚线、行首生成勾选框（✓ 纯装饰） */
[data-theme-layout="dtc-monthbox"] .pd-specs .pd-sec-title { display: flex; align-items: center; gap: .6rem; font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-monthbox"] .pd-specs-tablewrap { border-style: dashed; }
[data-theme-layout="dtc-monthbox"] .pd-specs-table th, [data-theme-layout="dtc-monthbox"] .pd-specs-table td { border-bottom: 1px dashed var(--line); }
[data-theme-layout="dtc-monthbox"] .pd-specs-table tr:last-child th, [data-theme-layout="dtc-monthbox"] .pd-specs-table tr:last-child td { border-bottom: 0; }
[data-theme-layout="dtc-monthbox"] .pd-specs-table th { position: relative; padding-left: 2.3rem; background: transparent; color: var(--ink); font-weight: 650; }
[data-theme-layout="dtc-monthbox"] .pd-specs-table th::before { content: "✓"; position: absolute; left: .95rem; top: .72rem; display: grid; place-items: center; width: 1.05rem; height: 1.05rem; border: 1px solid var(--accent); border-radius: 5px; color: var(--accent); font-size: .64rem; font-weight: 800; line-height: 1; }
[data-theme-layout="dtc-monthbox"] .pd-specs-table td { color: var(--ink-soft); }
/* 相关商品＝迷你盒卡：标题前生成 NO. 号 */
[data-theme-layout="dtc-monthbox"] .pd-rel-grid { counter-reset: mbxr; }
[data-theme-layout="dtc-monthbox"] .pd-rel-card { counter-increment: mbxr; box-shadow: 0 6px 0 -3px var(--line-soft); }
[data-theme-layout="dtc-monthbox"] .pd-rel-media { aspect-ratio: 1 / 1; }
[data-theme-layout="dtc-monthbox"] .pd-rel-gen { background: var(--accent-wash); }
[data-theme-layout="dtc-monthbox"] .pd-rel-title::before { content: "№ " counter(mbxr, decimal-leading-zero) "  "; color: var(--accent); font-family: var(--mono); font-size: .74rem; letter-spacing: .1em; }

/* ---- 响应式（920/720 单列、绝不横溢；横排车道自滚）+ reduced-motion ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-monthbox"] .mbx-hero-inner { grid-template-columns: 1fr; padding: clamp(1.6rem, 5vw, 2.6rem); }
  [data-theme-layout="dtc-monthbox"] .mbx-hero-side { max-width: 420px; }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-monthbox"] .mbx-hero.has-img { min-height: 60vh; }
  [data-theme-layout="dtc-monthbox"] .mbx-lid { box-shadow: 0 8px 0 -4px var(--line-soft), 0 15px 0 -8px var(--line), 0 26px 32px -16px rgba(12,10,6,.35); }
  [data-theme-layout="dtc-monthbox"] .mbx-row { grid-auto-columns: min(210px, 78vw); }
  [data-theme-layout="dtc-monthbox"] .link-grid { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-monthbox"] .mbx-box, [data-theme-layout="dtc-monthbox"] .mbx-box-media img,
  [data-theme-layout="dtc-monthbox"] .mbx-pick, [data-theme-layout="dtc-monthbox"] .nav > a,
  [data-theme-layout="dtc-monthbox"] .cat-nav a { transition: none; }
  [data-theme-layout="dtc-monthbox"] .mbx-box:hover { transform: none; }
  [data-theme-layout="dtc-monthbox"] .mbx-box:hover .mbx-box-media img { transform: none; }
}

/* ============================================================
   dtc-monthbox 皮肤 ×3：monthbox 暖米原生 / monthbox-noir 夜蓝蜜金反差 /
   monthbox-white 纯白。全部变量成套覆写；实算 WCAG 见各皮注释
   （正文≥7、次要/accent≥4.5、hover 只升不降）。
   ============================================================ */
/* ---- 月盒 · Monthbox（原生）：暖米 #f7f3ec + 墨 #241f16 + 蜜棕（正文 accent 压深到
   #8a5a12 白米可读，设计稿蜜棕 #b0762a 留作 accent-soft 装饰位）。
   实算：ink/bg 14.80、ink/surface 16.11、ink/wash(CTA h2) 13.13、ink-soft/bg 8.85、
   muted/bg 5.26、muted/surface 5.73、muted/wash(cta note) 4.67、
   accent/bg 5.35、accent/surface 5.82、accent/wash 4.74、accent-soft/bg 3.47（装饰）、
   按钮 surface-on-ink 16.11、压图白字最劣 6.58（scrim .66 上叠纯白图）。 ---- */
:root[data-theme="monthbox"] {
  --bg: #f7f3ec; --surface: #fffdf8; --ink: #241f16; --ink-soft: #4a4335;
  --muted: #6e6452; --faint: #998c72; --line: #e6ddcc; --line-soft: #f0e9db;
  --accent: #8a5a12; --accent-soft: #b0762a; --accent-wash: #f2e5cb;
  --radius: 14px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(36,31,22,.05), 0 10px 28px rgba(36,31,22,.08);
}
/* ---- 夜盒 · Monthbox Noir（暗反差）：夜蓝 #0f1524 + 蜜金 #d7b26c，深夜开箱。
   实算：ink/bg 14.62、ink/surface 12.98、ink/wash 12.03、ink-soft/bg 10.55、
   muted/bg 7.19、muted/surface 6.38、muted/wash 5.92、accent/bg 9.08、
   accent/surface 8.07、accent/wash 7.48、accent-soft/bg 11.35（hover 只升）、
   按钮 surface-on-ink 12.98。 ---- */
:root[data-theme="monthbox-noir"] {
  --bg: #0f1524; --surface: #182036; --ink: #ebe6d9; --ink-soft: #cbc5b2;
  --muted: #a6a394; --faint: #6e7488; --line: #2a3450; --line-soft: #1d2740;
  --accent: #d7b26c; --accent-soft: #e5c98f; --accent-wash: #2a2717;
  --radius: 12px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(0,0,0,.42), 0 12px 32px rgba(0,0,0,.46);
}
/* 夜盒：盒盖落影换纯黑加深（暖灰影在深底上发灰），期号券边压亮一档 */
:root[data-theme="monthbox-noir"] .mbx-lid { box-shadow: 0 10px 0 -4px var(--line-soft), 0 19px 0 -8px var(--line), 0 36px 44px -18px rgba(0,0,0,.6); }
:root[data-theme="monthbox-noir"] .mbx-lid::after { border-color: color-mix(in srgb, var(--ink) 24%, transparent); }
/* ---- 纯白 · Monthbox White：纯白基底（对齐纯白系写法），蜜棕压深到 #8a5a10；
   --muted 压深到 #656b75，绕开 #707680 在 #fafaf8 上 4.38 的坑。
   实算：ink/bg 18.72、ink/surface 17.91、ink/wash 16.22、ink-soft/bg 9.79、
   muted/bg 5.37、muted/surface(#fafaf8) 5.13、muted/wash 4.65、accent/bg 5.91、
   accent/surface 5.66、accent/wash 5.12、accent-soft/bg 8.21（hover 只升）、
   按钮白字 on ink 18.72。 ---- */
:root[data-theme="monthbox-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #656b75; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #8a5a10; --accent-soft: #6d470c; --accent-wash: #f6eedd;
  --radius: 10px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(16,18,24,.05), 0 8px 22px rgba(16,18,24,.06);
}
:root[data-theme="monthbox-white"] .btn-primary { color: #fff; }
:root[data-theme="monthbox-white"] .mbx-lid { box-shadow: 0 10px 0 -4px var(--line-soft), 0 19px 0 -8px var(--line), 0 36px 44px -18px rgba(16,18,24,.22); }

/* =========================================================================
   LAYOUT: dtc-booth — 展位：展馆气质的外贸独立站（every selector scoped under
   [data-theme-layout="dtc-booth"]，classes bth-*）。
   页头 CSS 重塑为展馆指示牌（白底细框、右缘箭头裁角胶囊排；两层 clip-path：
   元素底色当细框、::before 内缩 1px 当白底——border 会被 clip-path 裁掉，
   只能这样做发丝框）；home：品牌墙深色横幅 hero（--bth-wall* 令牌，三皮各配）
   + 展区箭头签（Categories）+ 展位编号卡（A-NN CSS counter）+ 展会数字行。
   共用 dt-*（前缀 ^dtc- 规则自动命中）；三皮 booth / booth-noir / booth-white。
   ========================================================================= */
/* ---- 页头 · 展馆指示牌（≤620px 交还基础汉堡抽屉，重塑段全包 min-width:621px） ---- */
[data-theme-layout="dtc-booth"] .site-header { background: var(--bg); }
@media (min-width: 621px) {
  [data-theme-layout="dtc-booth"] .nav a[aria-current="page"]::after { display: none; } /* 底线指示让位签面高亮；≤620px 抽屉保留基础指示 */
  [data-theme-layout="dtc-booth"] .site-header .wrap { height: 70px; gap: 1rem; }
  [data-theme-layout="dtc-booth"] .nav { gap: .45rem; flex-wrap: wrap; }
  [data-theme-layout="dtc-booth"] .nav > a:not(.search-ico) {
    position: relative; z-index: 0; min-width: 0; padding: .42rem 1.55rem .42rem 1rem;
    background: var(--line); color: var(--ink-soft); font-size: .88rem; font-weight: 600;
    clip-path: polygon(0 0, calc(100% - 13px) 0, 100% 50%, calc(100% - 13px) 100%, 0 100%);
    transition: color var(--speed), background var(--speed);
  }
  [data-theme-layout="dtc-booth"] .nav > a:not(.search-ico)::before {
    content: ""; position: absolute; inset: 1px; z-index: -1; background: var(--surface);
    clip-path: polygon(0 0, calc(100% - 12.4px) 0, 100% 50%, calc(100% - 12.4px) 100%, 0 100%);
  }
  [data-theme-layout="dtc-booth"] .nav > a:not(.search-ico):hover,
  [data-theme-layout="dtc-booth"] .nav > a:not(.search-ico):focus-visible { color: var(--accent); background: var(--accent); outline: none; }
  [data-theme-layout="dtc-booth"] .nav > a[aria-current="page"] { color: var(--accent); background: var(--accent); }
}

/* ---- home 容器 + 品牌墙深色横幅 hero（三态：image 全幅 scrim / svg / 轻动画） ---- */
[data-theme-layout="dtc-booth"] .bth-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-booth"] .bth-hero { position: relative; margin-top: 1.6rem; border-radius: var(--radius); background: var(--bth-wall); overflow: hidden; }
/* 品牌墙拼板缝（仅无图态；缝线是装饰，专属车道=hero 盒内、不与文案抢位） */
[data-theme-layout="dtc-booth"] .bth-hero:not(.has-img)::before { content: ""; position: absolute; inset: 0; pointer-events: none; background: repeating-linear-gradient(90deg, transparent 0 168px, var(--bth-wall-line) 168px 169px); }
[data-theme-layout="dtc-booth"] .bth-hero-inner { position: relative; z-index: 1; display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(280px, .95fr); align-items: center; gap: clamp(1.2rem, 3vw, 2.6rem); padding: clamp(2.2rem, 5vw, 4rem); }
[data-theme-layout="dtc-booth"] .bth-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-booth"] .bth-hero.has-img { min-height: min(70vh, 540px); display: flex; align-items: flex-end; }
[data-theme-layout="dtc-booth"] .bth-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(102deg, rgba(10,12,14,.72) 0%, rgba(10,12,14,.44) 48%, rgba(10,12,14,.08) 76%), linear-gradient(200deg, rgba(10,12,14,0) 40%, rgba(10,12,14,.55) 96%); }
[data-theme-layout="dtc-booth"] .bth-hero.has-img .bth-hero-inner { grid-template-columns: minmax(0, 1fr); }
/* HALL/BOOTH 小字牌：HeroEyebrow 装进细框指示牌 + 指示灯小方块 */
[data-theme-layout="dtc-booth"] .bth-hall { display: inline-flex; align-items: center; gap: .55rem; margin: 0 0 1.1rem; padding: .34rem .8rem; border: 1px solid var(--bth-wall-line); border-radius: 4px; color: var(--bth-wall-accent); font-family: var(--mono); font-size: .74rem; font-weight: 700; letter-spacing: .22em; text-transform: uppercase; overflow-wrap: anywhere; }
[data-theme-layout="dtc-booth"] .bth-hall::before { content: ""; flex: none; width: 7px; height: 7px; background: var(--bth-wall-accent); }
[data-theme-layout="dtc-booth"] .bth-h1 { margin: 0; max-width: 15em; color: var(--bth-wall-ink); font-family: var(--dt-display, var(--sans)); font-size: clamp(2.1rem, 4.6vw, 3.3rem); font-weight: 750; line-height: 1.1; letter-spacing: -.015em; }
/* 描述钳高 4 行——装饰位不许把横幅撑成长文 */
[data-theme-layout="dtc-booth"] .bth-lede { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 4; max-width: 56ch; margin: 1rem 0 0; color: var(--bth-wall-muted); font-size: 1.02rem; line-height: 1.8; }
[data-theme-layout="dtc-booth"] .bth-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.8rem; }
[data-theme-layout="dtc-booth"] .btn { border-radius: 8px; }
[data-theme-layout="dtc-booth"] .inquiry-btn { border-radius: 8px; }
[data-theme-layout="dtc-booth"] .bth-hero .btn-primary { background: #fff; border-color: #fff; color: #14161a; }
[data-theme-layout="dtc-booth"] .bth-hero .btn-primary:hover { background: #fff; border-color: #fff; color: #14161a; box-shadow: 0 0 0 3px color-mix(in srgb, var(--bth-wall-accent) 40%, transparent); }
[data-theme-layout="dtc-booth"] .bth-hero .dt-btn-ghost { border-color: color-mix(in srgb, var(--bth-wall-ink) 62%, transparent); color: var(--bth-wall-ink); }
[data-theme-layout="dtc-booth"] .bth-hero .dt-btn-ghost:hover { border-color: var(--bth-wall-ink); color: var(--bth-wall-ink); }
[data-theme-layout="dtc-booth"] .bth-hero-side { min-width: 0; }

/* ---- 展区指示牌（Categories）：A/B/C 区号牌 + 箭头裁角胶囊 ---- */
[data-theme-layout="dtc-booth"] .bth-zones { display: flex; flex-wrap: wrap; gap: .55rem; margin-top: 1.1rem; counter-reset: bthz; }
[data-theme-layout="dtc-booth"] .bth-sign { position: relative; z-index: 0; display: inline-flex; align-items: center; gap: .55rem; min-width: 0; padding: .5rem 1.7rem .5rem .55rem; background: var(--line); color: var(--ink-soft); font-size: .88rem; font-weight: 600; clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 50%, calc(100% - 14px) 100%, 0 100%); transition: color var(--speed), background var(--speed); }
[data-theme-layout="dtc-booth"] .bth-sign::before { content: ""; position: absolute; inset: 1px; z-index: -1; background: var(--surface); clip-path: polygon(0 0, calc(100% - 13.3px) 0, 100% 50%, calc(100% - 13.3px) 100%, 0 100%); }
[data-theme-layout="dtc-booth"] .bth-zone::after { counter-increment: bthz; content: counter(bthz, upper-alpha); order: -1; display: grid; place-items: center; flex: none; width: 1.55rem; height: 1.55rem; background: var(--ink); color: var(--surface); font-family: var(--mono); font-size: .74rem; font-weight: 700; }
[data-theme-layout="dtc-booth"] .bth-zone-name { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; max-width: 18ch; }
[data-theme-layout="dtc-booth"] .bth-zone-n { color: var(--muted); font-family: var(--mono); font-size: .74rem; }
[data-theme-layout="dtc-booth"] .bth-sign:hover, [data-theme-layout="dtc-booth"] .bth-sign:focus-visible { color: var(--accent); background: var(--accent); outline: none; }

/* ---- 展位编号卡（A-NN CSS counter + 图 + 标题 + 规格签） ---- */
[data-theme-layout="dtc-booth"] .bth-section { padding-top: clamp(3rem, 6vw, 4.5rem); }
[data-theme-layout="dtc-booth"] .bth-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(230px, 100%), 1fr)); gap: 1.1rem; counter-reset: bthn; }
[data-theme-layout="dtc-booth"] .bth-card { display: flex; flex-direction: column; min-width: 0; counter-increment: bthn; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); color: var(--ink); overflow: hidden; transition: transform var(--speed), border-color var(--speed), box-shadow var(--speed); }
[data-theme-layout="dtc-booth"] .bth-card:hover { transform: translateY(-3px); border-color: var(--accent); box-shadow: var(--shadow); color: var(--ink); }
[data-theme-layout="dtc-booth"] .bth-card-top { display: flex; align-items: center; justify-content: space-between; gap: .5rem; padding: .5rem .85rem; border-bottom: 1px dashed var(--line); }
[data-theme-layout="dtc-booth"] .bth-no::before { content: "№ " counter(bthn, decimal-leading-zero); color: var(--accent); font-family: var(--mono); font-size: .8rem; font-weight: 750; letter-spacing: .08em; }
[data-theme-layout="dtc-booth"] .bth-card-word { color: var(--muted); font-style: normal; font-size: .64rem; font-weight: 700; letter-spacing: .3em; text-transform: uppercase; }
[data-theme-layout="dtc-booth"] .bth-card-media { display: grid; place-items: center; aspect-ratio: 4 / 3; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-booth"] .bth-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-booth"] .bth-card:hover .bth-card-media img { transform: scale(1.04); }
[data-theme-layout="dtc-booth"] .bth-card-body { display: flex; flex-direction: column; gap: .3rem; padding: .85rem .9rem 1rem; }
[data-theme-layout="dtc-booth"] .bth-card-title { font-size: .98rem; font-weight: 650; line-height: 1.45; }
[data-theme-layout="dtc-booth"] .bth-card:hover .bth-card-title { color: var(--accent); }

/* ---- 展会数字行（FactoryStats）：整条计数板，左缘 accent 竖标 ---- */
[data-theme-layout="dtc-booth"] .bth-figures .dt-stats { grid-template-columns: repeat(auto-fit, minmax(min(180px, 100%), 1fr)); gap: 0; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); overflow: hidden; }
[data-theme-layout="dtc-booth"] .bth-figures .dt-stat { border: 0; border-left: 1px solid var(--line); border-radius: 0; text-align: left; }
[data-theme-layout="dtc-booth"] .bth-figures .dt-stat:first-child { border-left: 0; }
[data-theme-layout="dtc-booth"] .bth-figures .dt-stat dt { color: var(--accent); font-family: var(--mono); letter-spacing: -.02em; }

/* ---- 预约洽谈 CTA（dtc_cta 复用）：品牌墙色大板 + 白色大按钮 ---- */
[data-theme-layout="dtc-booth"] .dt-cta-inner { background: var(--bth-wall); border-radius: var(--radius); }
[data-theme-layout="dtc-booth"] .dt-cta h2 { color: var(--bth-wall-ink); }
[data-theme-layout="dtc-booth"] .dt-cta-note { color: var(--bth-wall-muted); }
[data-theme-layout="dtc-booth"] .dt-cta .inquiry-btn,
[data-theme-layout="dtc-booth"] .dt-cta .inquiry-btn.inquiry-wa { background: #fff; border-color: #fff; color: #14161a; }
[data-theme-layout="dtc-booth"] .dt-cta .inquiry-btn:hover,
[data-theme-layout="dtc-booth"] .dt-cta .inquiry-btn.inquiry-wa:hover { background: #fff; border-color: #fff; color: #14161a; box-shadow: 0 0 0 3px color-mix(in srgb, var(--bth-wall-accent) 40%, transparent); }

/* ---- 内页 · 商品/内容列表（generic_list DOM）：页头墙板 + 展区签 + 展位卡 ---- */
[data-theme-layout="dtc-booth"] .page-head { position: relative; overflow: hidden; padding: 2.8rem 0 2.3rem; border-bottom: 3px solid var(--accent); background: var(--bth-wall); }
/* 页头墙板拼缝（同 hero 品牌墙母题；装饰专属车道=盒内 + pointer-events:none） */
[data-theme-layout="dtc-booth"] .page-head::before { content: ""; position: absolute; inset: 0; pointer-events: none; background: repeating-linear-gradient(90deg, transparent 0 168px, var(--bth-wall-line) 168px 169px); }
[data-theme-layout="dtc-booth"] .page-head .wrap { position: relative; }
[data-theme-layout="dtc-booth"] .page-head h1 { color: var(--bth-wall-ink); }
[data-theme-layout="dtc-booth"] .page-head .eyebrow { color: var(--bth-wall-accent); }
[data-theme-layout="dtc-booth"] .page-head p { color: var(--bth-wall-muted); }
[data-theme-layout="dtc-booth"] .page-head .breadcrumb, [data-theme-layout="dtc-booth"] .page-head .breadcrumb a,
[data-theme-layout="dtc-booth"] .page-head .breadcrumb .sep { color: var(--bth-wall-muted); }
[data-theme-layout="dtc-booth"] .page-head .breadcrumb a:hover,
[data-theme-layout="dtc-booth"] .page-head .breadcrumb span[aria-current] { color: var(--bth-wall-ink); }
/* 分类条＝展区指示牌（同 home 箭头签语言；active＝整签压成 ink 实底） */
[data-theme-layout="dtc-booth"] .cat-nav { gap: .55rem; margin: 1.6rem 0; }
[data-theme-layout="dtc-booth"] .cat-nav a { position: relative; z-index: 0; border: 0; border-radius: 0; padding: .5rem 1.7rem .5rem .95rem; background: var(--line); color: var(--ink-soft); font-weight: 600; clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 50%, calc(100% - 14px) 100%, 0 100%); transition: color var(--speed), background var(--speed); }
[data-theme-layout="dtc-booth"] .cat-nav a::before { content: ""; position: absolute; inset: 1px; z-index: -1; background: var(--surface); clip-path: polygon(0 0, calc(100% - 13.3px) 0, 100% 50%, calc(100% - 13.3px) 100%, 0 100%); }
[data-theme-layout="dtc-booth"] .cat-nav a:hover { color: var(--accent); background: var(--accent); }
[data-theme-layout="dtc-booth"] .cat-nav a.active { color: var(--surface); background: var(--ink); }
[data-theme-layout="dtc-booth"] .cat-nav a.active::before { background: var(--ink); }
[data-theme-layout="dtc-booth"] .cat-nav a.active .muted { color: currentColor; opacity: .72; }
/* 列表卡＝展位卡：::before 生成 A-NN 门楣行（虚线分隔），封面 4:3 跟母题 */
[data-theme-layout="dtc-booth"] .link-grid { counter-reset: bthl; margin: 1.8rem 0 2.2rem; }
[data-theme-layout="dtc-booth"] .link-card { counter-increment: bthl; }
[data-theme-layout="dtc-booth"] .link-card::before { content: "№ " counter(bthl, decimal-leading-zero); display: flex; align-items: center; padding: .5rem .9rem; border-bottom: 1px dashed var(--line); color: var(--accent); font-family: var(--mono); font-size: .8rem; font-weight: 750; letter-spacing: .08em; }
[data-theme-layout="dtc-booth"] .lc-cover { aspect-ratio: 4 / 3; }
[data-theme-layout="dtc-booth"] .lc-mono { background: var(--bth-wall); color: var(--bth-wall-accent); font-family: var(--sans); }
[data-theme-layout="dtc-booth"] .lc-title { font-size: 1rem; font-weight: 650; }
[data-theme-layout="dtc-booth"] .lc-arrow { color: var(--accent); }
[data-theme-layout="dtc-booth"] .lc-intro { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; color: var(--muted); }
/* 卡脚分类标＝迷你展区签（mono 小写间距 + 细框） */
[data-theme-layout="dtc-booth"] .lc-foot .tag { border: 1px solid var(--line); border-radius: 4px; background: var(--surface); color: var(--accent); font-family: var(--mono); font-size: .7rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-booth"] .link-grid > .muted { grid-column: 1 / -1; margin: 0; padding: 1.8rem; border: 1px dashed var(--line); border-radius: var(--radius); text-align: center; }
[data-theme-layout="dtc-booth"] .pagination .cur { background: var(--ink); border-color: var(--ink); color: var(--surface); }
[data-theme-layout="dtc-booth"] .pagination a:hover { border-color: var(--accent); color: var(--accent); }

/* ---- 内页 · 商品详情（product_detail DOM）：参数册 + 预约洽谈大 CTA ---- */
[data-theme-layout="dtc-booth"] .pd-kicker a { display: inline-block; padding: .18rem .6rem; border: 1px solid var(--line); background: var(--surface); color: var(--accent); }
[data-theme-layout="dtc-booth"] .pd-kicker a:hover { border-color: var(--accent); }
[data-theme-layout="dtc-booth"] .pd-title { font-weight: 750; letter-spacing: -.015em; }
[data-theme-layout="dtc-booth"] .pd-media { background: var(--surface); }
[data-theme-layout="dtc-booth"] .pd-media-gen { background: var(--bth-wall); }
[data-theme-layout="dtc-booth"] .pd-media-gen b { color: var(--bth-wall-accent); }
[data-theme-layout="dtc-booth"] .pd-thumb:hover { border-color: var(--accent-soft); }
[data-theme-layout="dtc-booth"] .pd-thumb.is-active { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
[data-theme-layout="dtc-booth"] .pd-sec-title { font-weight: 700; }
[data-theme-layout="dtc-booth"] .pd-meta { border-top: 2px solid var(--ink); }
[data-theme-layout="dtc-booth"] .pd-meta-row dt { font-family: var(--mono); font-size: .8rem; letter-spacing: .04em; text-transform: uppercase; }
/* 参数册：SPEC 页签 + 表头列走 mono 大写、accent-wash 底 */
[data-theme-layout="dtc-booth"] .pd-specs .pd-sec-title { display: flex; align-items: center; gap: .6rem; }
[data-theme-layout="dtc-booth"] .pd-specs .pd-sec-title::before { content: "◆"; flex: none; padding: .16rem .5rem; background: var(--ink); color: var(--surface); font-family: var(--mono); font-size: .66rem; font-weight: 700; letter-spacing: .24em; }
[data-theme-layout="dtc-booth"] .pd-specs-table th { background: var(--accent-wash); color: var(--ink-soft); font-family: var(--mono); font-size: .8rem; letter-spacing: .05em; text-transform: uppercase; }
[data-theme-layout="dtc-booth"] .pd-specs-table td { color: var(--ink); }
/* 预约洽谈大 CTA：Inquiry 区升格为品牌墙大板 + 白色大按钮（首屏可见） */
[data-theme-layout="dtc-booth"] .pd-inquiry { padding: 1.7rem 1.6rem 1.6rem; border: 0; border-top: 3px solid var(--accent); background: var(--bth-wall); }
[data-theme-layout="dtc-booth"] .pd-inquiry .inquiry-title { color: var(--bth-wall-ink); font-size: 1.3rem; }
[data-theme-layout="dtc-booth"] .pd-inquiry .inquiry-note { color: var(--bth-wall-muted); }
[data-theme-layout="dtc-booth"] .pd-inquiry .inquiry-btn,
[data-theme-layout="dtc-booth"] .pd-inquiry .inquiry-btn.inquiry-wa { padding: .68rem 1.3rem; background: #fff; border-color: #fff; color: #14161a; font-weight: 650; }
[data-theme-layout="dtc-booth"] .pd-inquiry .inquiry-btn:hover,
[data-theme-layout="dtc-booth"] .pd-inquiry .inquiry-btn.inquiry-wa:hover { background: #fff; border-color: #fff; color: #14161a; box-shadow: 0 0 0 3px color-mix(in srgb, var(--bth-wall-accent) 40%, transparent); }
/* 相关商品＝迷你展位卡：标题前生成 A-NN 号 */
[data-theme-layout="dtc-booth"] .pd-rel-grid { counter-reset: bthr; }
[data-theme-layout="dtc-booth"] .pd-rel-card { counter-increment: bthr; }
[data-theme-layout="dtc-booth"] .pd-rel-title::before { content: "№ " counter(bthr, decimal-leading-zero) "  "; color: var(--accent); font-family: var(--mono); font-size: .78rem; letter-spacing: .08em; }
[data-theme-layout="dtc-booth"] .pd-rel-gen { background: var(--bth-wall); }
[data-theme-layout="dtc-booth"] .pd-rel-gen b { color: var(--bth-wall-accent); }
[data-theme-layout="dtc-booth"] .pd-rel-card:hover .pd-rel-title { color: var(--accent); }

/* ---- 响应式（920/720 单列、绝不横溢）+ reduced-motion ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-booth"] .bth-hero-inner { grid-template-columns: 1fr; padding: clamp(1.6rem, 5vw, 2.6rem); }
  [data-theme-layout="dtc-booth"] .bth-hero-side { max-width: 420px; }
  [data-theme-layout="dtc-booth"] .bth-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-booth"] .bth-grid { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-booth"] .bth-figures .dt-stats { grid-template-columns: 1fr 1fr; }
  [data-theme-layout="dtc-booth"] .bth-figures .dt-stat { border-left: 0; }
  [data-theme-layout="dtc-booth"] .bth-hero.has-img { min-height: 60vh; }
  [data-theme-layout="dtc-booth"] .bth-zone-name { max-width: 12ch; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-booth"] .bth-card, [data-theme-layout="dtc-booth"] .bth-card-media img,
  [data-theme-layout="dtc-booth"] .bth-sign, [data-theme-layout="dtc-booth"] .cat-nav a,
  [data-theme-layout="dtc-booth"] .nav > a { transition: none; }
  [data-theme-layout="dtc-booth"] .bth-card:hover { transform: none; }
  [data-theme-layout="dtc-booth"] .bth-card:hover .bth-card-media img { transform: none; }
}

/* ============================================================
   dtc-booth 皮肤 ×3：booth 展馆灰原生 / booth-noir 夜馆深底反差 /
   booth-white 纯白。全部变量成套覆写；--bth-wall* 品牌墙令牌各配。
   实算 WCAG：见各皮注释（正文≥7、次要/accent≥4.5、hover 只升不降）。
   ============================================================ */
/* ---- 展位 · Booth（原生）：展馆灰 #eef0f2 + 深灰蓝 #1d2126 + 指示蓝 #3d6b8a。
   实算：ink/bg 14.16、ink/surface 16.18、muted/bg 5.42、muted/surface 6.20、
   accent/bg 5.01、accent/surface 5.72（hover soft 8.03 只升）、
   wall-ink/wall 14.94、wall-muted/wall 8.68、wall-accent/wall 8.40、
   ink-soft/wash(参数册表头) 7.88、hero 白钮字 18.11。 ---- */
:root[data-theme="booth"] {
  --bg: #eef0f2; --surface: #ffffff; --ink: #1d2126; --ink-soft: #3f4650;
  --muted: #59626c; --faint: #8a929b; --line: #d2d7dc; --line-soft: #e4e8ec;
  --accent: #3d6b8a; --accent-soft: #2d5470; --accent-wash: #e1ebf2;
  --radius: 10px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(29,33,38,.06), 0 10px 28px rgba(29,33,38,.09);
  --dt-display: var(--sans);
  --bth-wall: #1d2126; --bth-wall-ink: #f4f6f8; --bth-wall-muted: #b6bfc7;
  --bth-wall-accent: #8fc1e3; --bth-wall-line: rgba(244,246,248,.16);
}
/* ---- 夜馆 · Booth Noir（暗反差）：夜馆深底 + 荧蓝指示。
   实算：ink/bg 16.11、ink/surface 14.69、muted/bg 7.41、muted/surface 6.75、
   accent(荧蓝)/bg 8.52、/surface 7.77（hover soft 9.77 只升）、
   wall-ink/wall 15.79、wall-muted/wall 7.49、wall-accent/wall 7.93、
   ink-soft/wash 10.08、按钮 surface/ink 14.69。 ---- */
:root[data-theme="booth-noir"] {
  --bg: #0d1218; --surface: #151c25; --ink: #e9eef3; --ink-soft: #c2ccd6;
  --muted: #98a4b0; --faint: #6a7480; --line: #28323e; --line-soft: #1b232d;
  --accent: #57b9e8; --accent-soft: #82cdf2; --accent-wash: #12212c;
  --radius: 10px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(0,0,0,.42), 0 12px 32px rgba(0,0,0,.46);
  --dt-display: var(--sans);
  --bth-wall: #131a23; --bth-wall-ink: #eef4f9; --bth-wall-muted: #9fabb8;
  --bth-wall-accent: #57b9e8; --bth-wall-line: rgba(238,244,249,.14);
}
/* 夜馆：墙板与页底同为深色，描边圈出横幅/CTA 的板界 */
:root[data-theme="booth-noir"] .bth-hero,
:root[data-theme="booth-noir"] .dt-cta-inner,
:root[data-theme="booth-noir"] .pd-inquiry { border: 1px solid var(--line); }
:root[data-theme="booth-noir"] .page-head { border-top: 1px solid var(--line); }
/* ---- 纯白 · Booth White：纯白基底（对齐纯白系写法），指示蓝压深到白底可读；
   品牌墙深横幅母题保留（墙色同原生）。实算：ink/bg 18.72、ink/surface 17.91、
   muted/bg 4.77、muted/surface(#fafaf8) 4.57（--muted 压深到 #6d737d，
   绕开 #707680 在 #fafaf8 上 4.38 的坑）、accent/bg 6.74、/surface 6.45
   （hover soft 8.20 只升）、wall 组同原生（14.94 / 8.68 / 8.40）、ink-soft/wash 8.50。 ---- */
:root[data-theme="booth-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #6d737d; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #33607e; --accent-soft: #28506b; --accent-wash: #e8f0f6;
  --radius: 8px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(16,18,24,.05), 0 8px 22px rgba(16,18,24,.06);
  --dt-display: var(--sans);
  --bth-wall: #1d2126; --bth-wall-ink: #f4f6f8; --bth-wall-muted: #b6bfc7;
  --bth-wall-accent: #8fc1e3; --bth-wall-line: rgba(244,246,248,.16);
}
:root[data-theme="booth-white"] .btn-primary { color: #fff; }

/* =========================================================================
   LAYOUT: dtc-apothecary — 「药柜」草本铺（apo-*）：居中瓷标签导航 + 药柜题签
   hero（双框题签卡）+ 瓶签卡四列（卡顶凸出墨绿瓶盖 + mono 编号 CSS counter）+
   瓷标签分类排。全部选择器限定 [data-theme-layout="dtc-apothecary"]；
   本段必须排在 DTC 共用段（dt-*）之后——按钮/内页覆写靠源顺序压过族规则。
   ========================================================================= */
[data-theme-layout="dtc-apothecary"] .apo-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-apothecary"] .btn, [data-theme-layout="dtc-apothecary"] .inquiry-btn { border-radius: 3px; }

/* ---- 页头重塑：品牌居中 + 瓷标签横排（白底 1px 墨绿细框衬线小签，圆角 3px，间距均匀）。
   ≤620px 交还基础汉堡抽屉，重塑段整体包 min-width:621px ---- */
@media (min-width: 621px) {
  [data-theme-layout="dtc-apothecary"] .site-header { background: var(--bg); -webkit-backdrop-filter: none; backdrop-filter: none; }
  [data-theme-layout="dtc-apothecary"] .site-header .wrap { flex-direction: column; justify-content: center; gap: .7rem; height: auto; padding-top: 1rem; padding-bottom: 1.05rem; }
  [data-theme-layout="dtc-apothecary"] .site-header .brand { font-size: 1.22rem; letter-spacing: .1em; }
  [data-theme-layout="dtc-apothecary"] .nav { flex-wrap: wrap; justify-content: center; gap: .55rem; }
  [data-theme-layout="dtc-apothecary"] .nav > a:not(.search-ico) { padding: .32rem .95rem; border: 1px solid var(--accent); border-radius: 3px; background: var(--surface); color: var(--accent); font-family: var(--dt-display, var(--serif)); font-size: .84rem; font-weight: 550; }
  [data-theme-layout="dtc-apothecary"] .nav > a:not(.search-ico):hover { border-color: var(--accent-soft); color: var(--accent-soft); background: var(--accent-wash); }
  [data-theme-layout="dtc-apothecary"] .nav a[aria-current="page"] { background: var(--accent); border-color: var(--accent); color: var(--bg); }
  [data-theme-layout="dtc-apothecary"] .nav a[aria-current="page"]::after { display: none; } /* 瓷签自带高亮，收掉基础下划线（-22px 会飘出新页头） */
}

/* ---- 药柜题签 hero：双框题签卡居中（外框墨绿 + 内框发丝线）；image=全幅底图压 scrim ---- */
[data-theme-layout="dtc-apothecary"] .apo-hero { position: relative; margin-top: 1.6rem; border: 1px solid var(--accent); border-radius: 6px; background: var(--surface); overflow: hidden; }
[data-theme-layout="dtc-apothecary"] .apo-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-apothecary"] .apo-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(14,18,13,.72) 0%, rgba(14,18,13,.76) 55%, rgba(14,18,13,.84) 100%); } /* 居中文案铺满整卡→近平墨绿深纱；白字对最坏底（纯白图）7.67→8.85→11.89，.88 白 lede 在中段 7.29 */
[data-theme-layout="dtc-apothecary"] .apo-hero-inner { position: relative; z-index: 1; display: flex; flex-direction: column; align-items: center; margin: 7px; padding: clamp(2rem, 5vw, 3.6rem) clamp(1.2rem, 4vw, 2.6rem); border: 1px solid var(--line); border-radius: 4px; text-align: center; }
[data-theme-layout="dtc-apothecary"] .apo-eyebrow { margin-bottom: 1rem; letter-spacing: .38em; text-indent: .38em; } /* 拉丁小字大字距（title 侧配平居中） */
[data-theme-layout="dtc-apothecary"] .apo-h1 { margin: 0; max-width: 16em; font-family: var(--dt-display, var(--serif)); font-size: clamp(2rem, 4.2vw, 3.1rem); font-weight: 650; line-height: 1.16; letter-spacing: -.01em; }
[data-theme-layout="dtc-apothecary"] .apo-lede { display: -webkit-box; overflow: hidden; margin: .9rem auto 0; max-width: 56ch; color: var(--muted); font-size: 1rem; line-height: 1.8; -webkit-box-orient: vertical; -webkit-line-clamp: 4; } /* 描述钳高，护住题签比例 */
[data-theme-layout="dtc-apothecary"] .apo-cta { display: flex; flex-wrap: wrap; justify-content: center; gap: .65rem; margin-top: 1.4rem; }
[data-theme-layout="dtc-apothecary"] .apo-hero-side { width: min(100%, 420px); margin: 1.7rem auto 0; }
[data-theme-layout="dtc-apothecary"] .apo-hero.has-img .apo-hero-inner { border-color: rgba(255,255,255,.4); }
[data-theme-layout="dtc-apothecary"] .apo-hero.has-img .dt-eyebrow { color: #fff; opacity: .85; }
[data-theme-layout="dtc-apothecary"] .apo-hero.has-img .apo-h1 { color: #fff; } /* 全局 h1 色规则会盖过继承，压图必须显式白字 */
[data-theme-layout="dtc-apothecary"] .apo-hero.has-img .apo-lede { color: rgba(255,255,255,.88); }
[data-theme-layout="dtc-apothecary"] .apo-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-apothecary"] .apo-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-apothecary"] .apo-hero.has-img .btn-primary { background: #fff; border-color: #fff; color: #16211a; }

/* ---- 瓷标签排（首页分类；页头同款视觉在上面的重塑段） ---- */
[data-theme-layout="dtc-apothecary"] .apo-tags { display: flex; flex-wrap: wrap; justify-content: center; gap: .55rem; margin-top: 2.1rem; }
[data-theme-layout="dtc-apothecary"] .apo-tag { display: inline-flex; align-items: baseline; gap: .35rem; padding: .34rem 1rem; border: 1px solid var(--accent); border-radius: 3px; background: var(--surface); color: var(--accent); font-family: var(--dt-display, var(--serif)); font-size: .86rem; font-weight: 550; }
[data-theme-layout="dtc-apothecary"] .apo-tag:hover { border-color: var(--accent-soft); color: var(--accent-soft); background: var(--accent-wash); }
[data-theme-layout="dtc-apothecary"] .apo-tag sup { font-family: var(--mono); font-size: .64rem; color: var(--muted); }

/* ---- 瓶签卡四列：白底浅绿框 6/6/3/3，卡顶中央 ::before 凸出墨绿瓶盖，mono 编号 counter ---- */
[data-theme-layout="dtc-apothecary"] .apo-section { padding-top: clamp(2.8rem, 6vw, 4.2rem); }
[data-theme-layout="dtc-apothecary"] .apo-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.15rem; padding-top: 8px; counter-reset: apo; } /* padding-top=瓶盖凸出车道 */
[data-theme-layout="dtc-apothecary"] .apo-card { position: relative; display: flex; flex-direction: column; min-width: 0; counter-increment: apo; border: 1px solid var(--line); border-radius: 6px 6px 3px 3px; background: var(--surface); color: var(--ink); transition: border-color var(--speed), box-shadow var(--speed); }
[data-theme-layout="dtc-apothecary"] .apo-card::before { content: ""; position: absolute; top: -8px; left: 50%; z-index: 1; width: 40px; height: 14px; transform: translateX(-50%); border-radius: 4px 4px 2px 2px; background: var(--accent); } /* 瓶盖：车道=grid padding-top 8px + 卡自身，720px 不出格 */
[data-theme-layout="dtc-apothecary"] .apo-card:hover { border-color: var(--accent); box-shadow: var(--shadow); color: var(--ink); }
[data-theme-layout="dtc-apothecary"] .apo-card-media { display: grid; place-items: center; aspect-ratio: 1 / 1; border-bottom: 1px solid var(--line-soft); border-radius: 5px 5px 0 0; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-apothecary"] .apo-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-apothecary"] .apo-card-media b { font-family: var(--dt-display, var(--serif)); font-size: 2.4rem; color: var(--accent); }
[data-theme-layout="dtc-apothecary"] .apo-card:hover .apo-card-media img { transform: scale(1.04); }
[data-theme-layout="dtc-apothecary"] .apo-card-body { display: flex; flex: 1; flex-direction: column; gap: .3rem; padding: .8rem .9rem 1rem; text-align: center; }
[data-theme-layout="dtc-apothecary"] .apo-card-no::before { content: "№ " counter(apo, decimal-leading-zero); font-family: var(--mono); font-size: .66rem; letter-spacing: .14em; color: var(--muted); }
[data-theme-layout="dtc-apothecary"] .apo-card-title { font-family: var(--dt-display, var(--serif)); font-size: 1rem; font-weight: 650; line-height: 1.4; }
[data-theme-layout="dtc-apothecary"] .apo-card .f-chips { justify-content: center; margin-top: auto; padding-top: .5rem; }
[data-theme-layout="dtc-apothecary"] .dt-cta-inner { border: 1px solid var(--accent); border-radius: 6px; } /* CTA 也上题签框 */

/* ---- 内页 · 商品列表（generic_list DOM）：成分卡格＝同瓶签卡形；cat-nav 瓷标签化 ---- */
[data-theme-layout="dtc-apothecary"] .page-head { position: relative; padding: 2.8rem 0 1.7rem; border-bottom: 0; text-align: center; }
[data-theme-layout="dtc-apothecary"] .page-head::after { content: ""; position: absolute; bottom: 0; left: 50%; width: min(120px, 40%); height: 3px; transform: translateX(-50%); border-radius: 2px; background: var(--accent); } /* 题签短墨绿界线代替通栏细线 */
[data-theme-layout="dtc-apothecary"] .page-head h1 { font-family: var(--dt-display, var(--serif)); font-weight: 650; }
[data-theme-layout="dtc-apothecary"] .page-head .eyebrow { letter-spacing: .34em; text-indent: .34em; }
[data-theme-layout="dtc-apothecary"] .page-head p { margin-inline: auto; }
[data-theme-layout="dtc-apothecary"] .page-head .breadcrumb { justify-content: center; display: flex; flex-wrap: wrap; }
[data-theme-layout="dtc-apothecary"] .page-head .breadcrumb a:hover { color: var(--accent-soft); }
[data-theme-layout="dtc-apothecary"] .cat-nav { justify-content: center; gap: .55rem; margin: 1.9rem 0 .4rem; }
[data-theme-layout="dtc-apothecary"] .cat-nav a { padding: .34rem 1rem; border: 1px solid var(--accent); border-radius: 3px; background: var(--surface); color: var(--accent); font-family: var(--dt-display, var(--serif)); font-size: .86rem; font-weight: 550; }
[data-theme-layout="dtc-apothecary"] .cat-nav a:hover { border-color: var(--accent-soft); color: var(--accent-soft); background: var(--accent-wash); }
[data-theme-layout="dtc-apothecary"] .cat-nav a.active { background: var(--accent); border-color: var(--accent); color: var(--bg); }
[data-theme-layout="dtc-apothecary"] .cat-nav a .muted { color: var(--muted); font-family: var(--mono); font-size: .68em; }
[data-theme-layout="dtc-apothecary"] .cat-nav a.active .muted { color: currentColor; opacity: 1; } /* 基础 .68 透明度会把计数压穿 4.5 */
[data-theme-layout="dtc-apothecary"] .link-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.15rem; padding-top: 8px; }
[data-theme-layout="dtc-apothecary"] .link-card { position: relative; overflow: visible; border-radius: 6px 6px 3px 3px; }
[data-theme-layout="dtc-apothecary"] .link-card::before { content: ""; position: absolute; top: -8px; left: 50%; z-index: 1; width: 40px; height: 14px; transform: translateX(-50%); border-radius: 4px 4px 2px 2px; background: var(--accent); }
[data-theme-layout="dtc-apothecary"] .link-card:hover { transform: none; box-shadow: var(--shadow); }
[data-theme-layout="dtc-apothecary"] .lc-cover { aspect-ratio: 1 / 1; border-bottom: 1px solid var(--line-soft); border-radius: 5px 5px 0 0; overflow: hidden; }
[data-theme-layout="dtc-apothecary"] .lc-mono { background: var(--accent-wash); color: var(--accent); font-family: var(--dt-display, var(--serif)); font-weight: 650; } /* 弃白字渐变底，wash+accent 实算 ≥6.7 */
[data-theme-layout="dtc-apothecary"] .lc-body { text-align: center; }
[data-theme-layout="dtc-apothecary"] .lc-title { justify-content: center; font-family: var(--dt-display, var(--serif)); font-size: 1rem; font-weight: 650; }
[data-theme-layout="dtc-apothecary"] .link-card:hover .lc-title { color: var(--accent); }
[data-theme-layout="dtc-apothecary"] .lc-arrow { display: none; } /* 瓶签居中版式没有右飘箭头位 */
[data-theme-layout="dtc-apothecary"] .lc-intro { display: -webkit-box; overflow: hidden; font-size: .86rem; -webkit-box-orient: vertical; -webkit-line-clamp: 3; } /* 长简介钳高，护住瓶签整齐 */
[data-theme-layout="dtc-apothecary"] .lc-foot { display: flex; justify-content: center; }
[data-theme-layout="dtc-apothecary"] .lc-foot .tag { padding: .12rem .6rem; border: 1px solid var(--accent); border-radius: 3px; background: none; color: var(--accent); font-family: var(--dt-display, var(--serif)); font-size: .72rem; }
[data-theme-layout="dtc-apothecary"] .pagination a, [data-theme-layout="dtc-apothecary"] .pagination span { border-radius: 3px; }
[data-theme-layout="dtc-apothecary"] .link-grid > .muted { grid-column: 1 / -1; padding: 1.6rem 0; text-align: center; } /* 空态占满整行居中 */

/* ---- 内页 · 商品详情（product_detail DOM）：题签框图位 + 成分/用法双列行卡
  （specs 表 CSS 多列拆两摞并排「成分行卡」，920px 落单列） ---- */
[data-theme-layout="dtc-apothecary"] .pd-main { padding-top: 1.4rem; }
[data-theme-layout="dtc-apothecary"] .pd-bc a:hover { color: var(--accent-soft); }
[data-theme-layout="dtc-apothecary"] .pd-media { border: 1px solid var(--accent); border-radius: 6px 6px 3px 3px; }
[data-theme-layout="dtc-apothecary"] .pd-media-gen b { font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-apothecary"] .pd-thumb { border-radius: 3px; }
[data-theme-layout="dtc-apothecary"] .pd-thumb.is-active { border-color: var(--accent); }
[data-theme-layout="dtc-apothecary"] .pd-kicker { letter-spacing: .22em; text-transform: uppercase; font-size: .74rem; }
[data-theme-layout="dtc-apothecary"] .pd-title { font-family: var(--dt-display, var(--serif)); font-weight: 650; }
[data-theme-layout="dtc-apothecary"] .pd-lead { font-size: 1.02rem; line-height: 1.8; }
[data-theme-layout="dtc-apothecary"] .pd-meta { border-top: 1px solid var(--accent); }
[data-theme-layout="dtc-apothecary"] .pd-meta-row dt { font-family: var(--mono); font-size: .8rem; letter-spacing: .06em; }
[data-theme-layout="dtc-apothecary"] .pd-inquiry { padding: 1.1rem 1.15rem 1.25rem; border: 1px solid var(--accent); border-radius: 6px 6px 3px 3px; background: var(--surface); }
[data-theme-layout="dtc-apothecary"] .pd-inquiry .inquiry-title { font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-apothecary"] .pd-inquiry .inquiry-actions { display: grid; grid-template-columns: 1fr; gap: .55rem; }
[data-theme-layout="dtc-apothecary"] .pd-inquiry .inquiry-btn { justify-content: center; }
[data-theme-layout="dtc-apothecary"] .pd-sec-title { position: relative; padding-left: .85rem; font-family: var(--dt-display, var(--serif)); font-weight: 650; }
[data-theme-layout="dtc-apothecary"] .pd-sec-title::before { content: ""; position: absolute; top: .18em; left: 0; width: 5px; height: .95em; border-radius: 2px; background: var(--accent); } /* 小瓶盖记号 */
[data-theme-layout="dtc-apothecary"] .pd-specs-tablewrap { overflow: visible; border: 0; border-radius: 0; background: none; }
[data-theme-layout="dtc-apothecary"] .pd-specs-table { display: block; width: auto; }
[data-theme-layout="dtc-apothecary"] .pd-specs-table tbody { display: block; column-count: 2; column-gap: 1.1rem; }
[data-theme-layout="dtc-apothecary"] .pd-specs-table tr { display: grid; grid-template-columns: minmax(7.5rem, 32%) minmax(0, 1fr); overflow: hidden; margin-bottom: .6rem; border: 1px solid var(--line); border-radius: 6px 6px 3px 3px; background: var(--surface); break-inside: avoid; }
[data-theme-layout="dtc-apothecary"] .pd-specs-table th, [data-theme-layout="dtc-apothecary"] .pd-specs-table td { border-bottom: 0; }
[data-theme-layout="dtc-apothecary"] .pd-specs-table th { width: auto; min-width: 0; border-right: 1px solid var(--line-soft); background: var(--accent-wash); color: var(--ink-soft); font-family: var(--dt-display, var(--serif)); } /* muted 在混色底会掉穿 4.5，压回 ink-soft */
[data-theme-layout="dtc-apothecary"] .pd-rel-card { position: relative; overflow: visible; border: 1px solid var(--line); border-radius: 6px 6px 3px 3px; background: var(--surface); }
[data-theme-layout="dtc-apothecary"] .pd-rel-card::before { content: ""; position: absolute; top: -8px; left: 50%; z-index: 1; width: 34px; height: 12px; transform: translateX(-50%); border-radius: 4px 4px 2px 2px; background: var(--accent); }
[data-theme-layout="dtc-apothecary"] .pd-rel-grid { padding-top: 8px; }
[data-theme-layout="dtc-apothecary"] .pd-rel-card:hover { transform: none; box-shadow: var(--shadow); border-color: var(--accent); }
[data-theme-layout="dtc-apothecary"] .pd-rel-media { aspect-ratio: 1 / 1; border-radius: 5px 5px 0 0; overflow: hidden; }
[data-theme-layout="dtc-apothecary"] .pd-rel-title { text-align: center; font-family: var(--dt-display, var(--serif)); font-weight: 650; }

/* ---- 响应式：920 三→双列 + 双表落单列；720 双列窄卡收规格签，单列不横溢 ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-apothecary"] .apo-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="dtc-apothecary"] .link-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  [data-theme-layout="dtc-apothecary"] .pd-specs-table tbody { column-count: 1; }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-apothecary"] .apo-grid { gap: .8rem; }
  [data-theme-layout="dtc-apothecary"] .apo-card .f-chips { display: none; } /* 窄卡收规格签，同 fc-card 先例 */
  [data-theme-layout="dtc-apothecary"] .link-grid { gap: .8rem; }
  [data-theme-layout="dtc-apothecary"] .apo-hero-inner { margin: 5px; padding: 1.6rem 1rem 1.8rem; }
  [data-theme-layout="dtc-apothecary"] .apo-tags, [data-theme-layout="dtc-apothecary"] .cat-nav { gap: .45rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-apothecary"] .apo-card, [data-theme-layout="dtc-apothecary"] .apo-card-media img,
  [data-theme-layout="dtc-apothecary"] .link-card, [data-theme-layout="dtc-apothecary"] .lc-cover img,
  [data-theme-layout="dtc-apothecary"] .pd-rel-card { transition: none; }
}

/* ============================================================
   dtc-apothecary 皮肤 ×3：原生 herbary / 深反差 herbary-noir / 纯白 herbary-white。
   全变量成套覆写；对比实算见各块注释（正文≥7、次要/accent≥4.5、hover 只升不降）。
   ============================================================ */

/* ---- 药草铺 · Herbary（原生）：药草白纸底 + 墨绿瓷签 + 深墨字。
   实算：ink/bg 13.60、ink/surface 15.06、ink-soft/bg 8.05、muted/bg 5.57、
   muted/surface(编号) 6.17、muted/wash 5.01、accent/bg 7.47、accent/surface(瓷签) 8.27、
   accent/wash 6.71、hover accent-soft/surface 10.94↑、白字/accent(主按钮+瓶盖) 8.27 ---- */
:root[data-theme="herbary"] {
  --bg: #f2f4ef; --surface: #ffffff; --ink: #23281f; --ink-soft: #454c3e;
  --muted: #5c6454; --faint: #8b9282; --line: #d7ddcc; --line-soft: #e6eadd;
  --accent: #38553f; --accent-soft: #2a4230; --accent-wash: #e2eadd;
  --radius: 6px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(35,40,31,.05), 0 10px 26px rgba(35,40,31,.08);
}

/* ---- 药草夜柜 · Herbary Noir（深反差）：深墨绿夜底 + 瓷白字 + 浅药绿签。
   实算：ink/bg 15.32、ink/surface 13.35、ink-soft/bg 10.98、muted/bg 6.63、
   muted/surface(编号) 5.78、muted/wash 4.96、accent/bg 9.69、accent/surface(瓷签) 8.44、
   accent/wash 7.24、hover accent-soft/bg 11.65↑（暗皮 hover 提亮）、
   深墨字/accent(主按钮) 9.69、hover 深墨字/accent-soft 11.65↑ ---- */
:root[data-theme="herbary-noir"] {
  --bg: #131c15; --surface: #1b291e; --ink: #edf2e7; --ink-soft: #c5d1bd;
  --muted: #96a48c; --faint: #6d7a65; --line: #32432f; --line-soft: #233225;
  --accent: #a3cc9b; --accent-soft: #bcdcb4; --accent-wash: #22352a;
  --radius: 6px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(0,0,0,.5), 0 14px 34px rgba(0,0,0,.45);
}
/* 浅药绿当按钮底时白字只有 1.58——反转成深墨字（9.69，hover 11.65 只升） */
:root[data-theme="herbary-noir"] .btn-primary, :root[data-theme="herbary-noir"] .btn-primary:hover { color: #131c15; }

/* ---- 药草纯白 · Herbary White：共享中性灰纯白基底；surface 收纯白避开
   「muted #707680 在 #fafaf8 上 4.38」的坑（瓶签卡本就白底靠浅绿发丝框分卡）。
   实算：ink/bg 18.72、ink-soft/bg 9.79、muted/白面(编号) 4.57、accent/bg(瓷签) 8.52、
   accent/wash 7.40、hover accent-soft/bg 11.38↑、白字/accent(主按钮+瓶盖) 8.52 ---- */
:root[data-theme="herbary-white"] {
  --bg: #ffffff; --surface: #ffffff; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d3dccf; --line-soft: #e9eee6;
  --accent: #31543c; --accent-soft: #24402c; --accent-wash: #eaf1e7;
  --radius: 3px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(16,18,24,.04), 0 10px 24px rgba(16,18,24,.06);
}
/* CTA 注释行 muted 落在 wash 上只有 3.97，压回 ink-soft（wash 上 8.50） */
:root[data-theme="herbary-white"] .dt-cta-note { color: var(--ink-soft); }

/* ============================================================================
   dtc-grocer 骨架（gcr-*）：「食铺」——悬挂木牌导航（木棕胶囊自页头下沿悬挂）+
   黑板价目栏 hero（墨绿板 #23372c + 6px 木框 + 价目行点线）+ 纸袋货架商品
   （梯形 clip-path 纸袋卡 + 木搁板）。每条选择器限定 [data-theme-layout="dtc-grocer"]。
   皮肤 ×3：grocer（麦米+黑板绿+木棕）/ grocer-noir（黑板绿夜底+粉笔白）/ grocer-white。
   ========================================================================== */
[data-theme-layout="dtc-grocer"] .gcr-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }

/* ---- 页头=悬挂木牌（只 CSS 重塑标准 .site-header；≤620px 交还基础汉堡抽屉） ----
   页头底缘 4px 木梁；每个导航项=木棕胶囊吊牌：下圆角 0 0 8px 8px + 底部 3px 深影，
   translateY 跨过木梁悬挂到页头下沿之外（页头改 static + 去毛玻璃，绝不裁剪吊牌）；
   顶部小钉点 ::before。当前页=黑板绿吊牌粉笔字；hover 木色压深（字对比只升不降）。 */
@media (min-width: 621px) {
  [data-theme-layout="dtc-grocer"] .site-header { position: static; background: var(--bg); border-bottom: 4px solid var(--gcr-wood); -webkit-backdrop-filter: none; backdrop-filter: none; }
  [data-theme-layout="dtc-grocer"] .site-header .wrap { height: 76px; }
  [data-theme-layout="dtc-grocer"] .site-header .brand { font-family: var(--dt-display, var(--serif)); font-size: 1.22rem; letter-spacing: .04em; }
  [data-theme-layout="dtc-grocer"] .site-header .nav { gap: .55rem; }
  [data-theme-layout="dtc-grocer"] .site-header .nav > a { padding: .46rem .95rem .5rem; border-radius: 0 0 8px 8px; background: linear-gradient(180deg, color-mix(in srgb, var(--gcr-wood) 87%, #fff), var(--gcr-wood) 52%, color-mix(in srgb, var(--gcr-wood) 88%, #000)); color: var(--gcr-wood-ink); font-size: .88rem; font-weight: 650; box-shadow: 0 3px 0 color-mix(in srgb, var(--gcr-wood) 55%, #000); transform: translateY(23px); transition: filter var(--speed); }
  [data-theme-layout="dtc-grocer"] .site-header .nav > a::before { content: ""; position: absolute; top: 4px; left: 50%; width: 5px; height: 5px; margin-left: -2.5px; border-radius: 50%; background: color-mix(in srgb, var(--gcr-wood-ink) 45%, var(--gcr-wood)); }
  [data-theme-layout="dtc-grocer"] .site-header .nav > a:hover { color: var(--gcr-wood-ink); filter: brightness(.9); } /* 底色压深，字对比 6.57→更高 */
  [data-theme-layout="dtc-grocer"] .site-header .nav > a[aria-current="page"] { background: var(--gcr-board); color: var(--gcr-chalk); box-shadow: 0 3px 0 color-mix(in srgb, var(--gcr-board) 55%, #000); }
  [data-theme-layout="dtc-grocer"] .site-header .nav > a[aria-current="page"]::after { content: none; }
  [data-theme-layout="dtc-grocer"] .site-header .lang-switch summary, [data-theme-layout="dtc-grocer"] .site-header .lang-cur { color: var(--ink); }
}

/* ---- hero=黑板价目栏（墨绿板+6px 木框；三态照 flagship） ---- */
[data-theme-layout="dtc-grocer"] .gcr-hero { position: relative; margin-top: 2.6rem; border: 6px solid var(--gcr-wood); border-radius: 12px; background: var(--gcr-board); box-shadow: var(--shadow); overflow: hidden; }
[data-theme-layout="dtc-grocer"] .gcr-hero-inner { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(260px, .9fr); align-items: center; gap: clamp(1.2rem, 3vw, 2.4rem); padding: clamp(1.8rem, 4.5vw, 3.2rem); }
[data-theme-layout="dtc-grocer"] .gcr-hero .dt-eyebrow { color: var(--gcr-chalk-accent); }
[data-theme-layout="dtc-grocer"] .gcr-h1 { margin: 0; max-width: 14em; color: var(--gcr-chalk); font-family: var(--dt-display, var(--serif)); font-size: clamp(2rem, 4.2vw, 3.1rem); font-weight: 650; line-height: 1.18; letter-spacing: .08em; } /* 店名粉笔字：衬线大字距 */
[data-theme-layout="dtc-grocer"] .gcr-lede { max-width: 52ch; margin: .95rem 0 0; color: var(--gcr-chalk-soft); font-size: 1.01rem; line-height: 1.8; }
/* 价目行：名字·点线（dotted 半透明粉笔）·第一枚规格签右对齐；行 hover 提白只升不降 */
[data-theme-layout="dtc-grocer"] .gcr-menu { list-style: none; margin: 1.5rem 0 0; padding: 1rem .2rem 0; border-top: 2px dotted color-mix(in srgb, var(--gcr-chalk) 38%, transparent); }
[data-theme-layout="dtc-grocer"] .gcr-menu-row { display: flex; align-items: baseline; gap: .6rem; padding: .4rem 0; color: var(--gcr-chalk); }
[data-theme-layout="dtc-grocer"] .gcr-menu-row:hover { color: #fff; }
[data-theme-layout="dtc-grocer"] .gcr-menu-name { flex: 0 1 auto; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-weight: 600; font-size: .97rem; }
[data-theme-layout="dtc-grocer"] .gcr-menu-dots { flex: 1 1 24px; min-width: 24px; border-bottom: 2px dotted color-mix(in srgb, var(--gcr-chalk) 45%, transparent); transform: translateY(-.3em); }
[data-theme-layout="dtc-grocer"] .gcr-menu-chip { flex: none; display: inline-flex; align-items: baseline; gap: .35rem; max-width: 42%; font-size: .84rem; }
[data-theme-layout="dtc-grocer"] .gcr-menu-chip b { flex: none; color: var(--gcr-chalk-accent); font-weight: 750; }
[data-theme-layout="dtc-grocer"] .gcr-menu-chip i { font-style: normal; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
[data-theme-layout="dtc-grocer"] .gcr-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.6rem; }
/* 板上按钮：主按钮=粉笔黄粉盒（板字 7.70），ghost=粉笔描边 */
[data-theme-layout="dtc-grocer"] .gcr-hero .btn-primary { background: var(--gcr-chalk-accent); border-color: var(--gcr-chalk-accent); color: var(--gcr-board); }
[data-theme-layout="dtc-grocer"] .gcr-hero .btn-primary:hover { background: color-mix(in srgb, var(--gcr-chalk-accent) 86%, #fff); border-color: color-mix(in srgb, var(--gcr-chalk-accent) 86%, #fff); color: var(--gcr-board); }
[data-theme-layout="dtc-grocer"] .gcr-hero .dt-btn-ghost { border-color: color-mix(in srgb, var(--gcr-chalk) 55%, transparent); color: var(--gcr-chalk); }
[data-theme-layout="dtc-grocer"] .gcr-hero .dt-btn-ghost:hover { border-color: var(--gcr-chalk); color: #fff; }
[data-theme-layout="dtc-grocer"] .gcr-hero-side { min-width: 0; }
/* 压图态：全幅底图 + 深 scrim（中段 α.62 纯白底图最劣仍 5.40，见皮肤注），文字统一提白 */
[data-theme-layout="dtc-grocer"] .gcr-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-grocer"] .gcr-hero.has-img { min-height: min(68vh, 540px); display: flex; align-items: flex-end; }
[data-theme-layout="dtc-grocer"] .gcr-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(12,16,12,.72), rgba(12,16,12,.62) 55%, rgba(12,16,12,.72)); }
[data-theme-layout="dtc-grocer"] .gcr-hero.has-img .gcr-hero-inner { position: relative; z-index: 1; grid-template-columns: minmax(0, 1fr); }
[data-theme-layout="dtc-grocer"] .gcr-hero.has-img :is(.gcr-h1, .dt-eyebrow, .gcr-menu-row, .gcr-menu-chip b) { color: #fff; }
[data-theme-layout="dtc-grocer"] .gcr-hero.has-img .gcr-lede { color: #fff; opacity: .96; }
[data-theme-layout="dtc-grocer"] .gcr-hero.has-img .btn-primary { background: #fff; border-color: #fff; color: #1d2a22; }
[data-theme-layout="dtc-grocer"] .gcr-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-grocer"] .gcr-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }

/* ---- 分类=货架签排（纸签+左侧木沿，仿货架边条价签） ---- */
[data-theme-layout="dtc-grocer"] .gcr-aisles { display: flex; flex-wrap: wrap; gap: .6rem .7rem; margin-top: clamp(1.7rem, 4vw, 2.4rem); }
[data-theme-layout="dtc-grocer"] .gcr-aisle { display: inline-flex; align-items: baseline; gap: .45rem; max-width: 100%; padding: .42rem .9rem .42rem .75rem; border-left: 5px solid var(--gcr-wood); border-radius: 3px 8px 8px 3px; background: var(--gcr-bag); color: var(--gcr-bag-ink); font-size: .9rem; font-weight: 650; box-shadow: var(--shadow); transition: transform var(--speed); }
[data-theme-layout="dtc-grocer"] .gcr-aisle:hover { transform: translateY(-2px); color: var(--gcr-bag-ink); }
[data-theme-layout="dtc-grocer"] .gcr-aisle small { flex: none; font-size: .74em; font-weight: 750; color: var(--gcr-bag-muted); }

/* ---- 商品=纸袋货架（梯形 clip-path 纸袋卡：袋口折线 ::before + 底部木搁板） ---- */
[data-theme-layout="dtc-grocer"] .gcr-section { padding-top: clamp(2.8rem, 6vw, 4.2rem); }
[data-theme-layout="dtc-grocer"] .gcr-shelf { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.5rem 1.2rem; }
[data-theme-layout="dtc-grocer"] .gcr-bag { position: relative; display: flex; flex-direction: column; min-width: 0; padding: 1.1rem .95rem .9rem; background: linear-gradient(180deg, color-mix(in srgb, var(--gcr-bag) 96%, #fff), var(--gcr-bag) 42%, color-mix(in srgb, var(--gcr-bag) 93%, #000)); border-bottom: 7px solid var(--gcr-wood); color: var(--gcr-bag-ink); clip-path: polygon(4.5% 0, 95.5% 0, 100% 100%, 0 100%); transition: transform var(--speed); }
[data-theme-layout="dtc-grocer"] .gcr-bag::before { content: ""; position: absolute; top: .52rem; left: 7%; right: 7%; border-top: 2px dashed color-mix(in srgb, var(--gcr-bag-ink) 30%, var(--gcr-bag)); } /* 袋口折线（纯装饰，720px 无占位不必归位） */
[data-theme-layout="dtc-grocer"] .gcr-bag:hover { transform: translateY(-3px); color: var(--gcr-bag-ink); }
[data-theme-layout="dtc-grocer"] .gcr-bag-media { display: grid; place-items: center; aspect-ratio: 4 / 3; margin-top: .5rem; border-radius: 6px; background: color-mix(in srgb, var(--gcr-bag) 82%, #fff); overflow: hidden; }
[data-theme-layout="dtc-grocer"] .gcr-bag-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-grocer"] .gcr-bag:hover .gcr-bag-media img { transform: scale(1.04); }
[data-theme-layout="dtc-grocer"] .gcr-bag-media.dt-gen b { color: var(--gcr-bag-accent); } /* noir 皮 accent 是浅黄，纸面字改袋内深绿 */
[data-theme-layout="dtc-grocer"] .gcr-bag-body { display: flex; flex-direction: column; gap: .45rem; padding: .75rem .35rem .1rem; }
[data-theme-layout="dtc-grocer"] .gcr-bag-title { font-size: .99rem; font-weight: 700; line-height: 1.45; }
[data-theme-layout="dtc-grocer"] .gcr-chips { display: flex; flex-wrap: wrap; gap: .35rem .45rem; }
[data-theme-layout="dtc-grocer"] .gcr-chip { display: inline-flex; align-items: baseline; gap: .3rem; max-width: 100%; padding: .16rem .55rem; border: 1px dashed color-mix(in srgb, var(--gcr-bag-accent) 55%, var(--gcr-bag)); border-radius: 4px; font-size: .78rem; line-height: 1.5; }
[data-theme-layout="dtc-grocer"] .gcr-chip b { flex: none; color: var(--gcr-bag-accent); font-weight: 750; }
[data-theme-layout="dtc-grocer"] .gcr-chip i { font-style: normal; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }

/* ---- 店主故事（stats 空回落站点简介） ---- */
[data-theme-layout="dtc-grocer"] .gcr-about { max-width: 62ch; margin: 0; font-family: var(--dt-display, var(--serif)); font-size: clamp(1.02rem, 1.8vw, 1.26rem); line-height: 2; color: var(--ink-soft); }

/* ---- 内页 · 商品列表（generic_list 的 DOM）：黑板页眉 + 货架签分类 + 纸袋格 ---- */
[data-theme-layout="dtc-grocer"] .page-head { border-bottom: 5px solid var(--gcr-wood); background: var(--gcr-board); padding: 2.3rem 0 1.6rem; }
[data-theme-layout="dtc-grocer"] .page-head h1 { color: var(--gcr-chalk); font-family: var(--dt-display, var(--serif)); letter-spacing: .06em; }
[data-theme-layout="dtc-grocer"] .page-head .eyebrow { color: var(--gcr-chalk-accent); }
[data-theme-layout="dtc-grocer"] .page-head .hero-sub { max-width: 56ch; color: var(--gcr-chalk-soft); }
[data-theme-layout="dtc-grocer"] .page-head .breadcrumb a { color: var(--gcr-chalk-soft); }
[data-theme-layout="dtc-grocer"] .page-head .breadcrumb a:hover { color: var(--gcr-chalk); }
[data-theme-layout="dtc-grocer"] .page-head .breadcrumb .sep { color: color-mix(in srgb, var(--gcr-chalk) 55%, transparent); }
[data-theme-layout="dtc-grocer"] .page-head .breadcrumb [aria-current="page"] { color: var(--gcr-chalk); }
[data-theme-layout="dtc-grocer"] .cat-nav a { border: 0; border-left: 5px solid var(--gcr-wood); border-radius: 3px 8px 8px 3px; background: var(--gcr-bag); color: var(--gcr-bag-ink); font-weight: 650; box-shadow: var(--shadow); }
[data-theme-layout="dtc-grocer"] .cat-nav a:hover { color: var(--gcr-bag-ink); }
[data-theme-layout="dtc-grocer"] .cat-nav a .muted { color: var(--gcr-bag-muted); }
[data-theme-layout="dtc-grocer"] .cat-nav a.active { background: var(--gcr-board); border-left-color: color-mix(in srgb, var(--gcr-board) 55%, #000); color: var(--gcr-chalk); }
[data-theme-layout="dtc-grocer"] .cat-nav a.active .muted { color: var(--gcr-chalk-soft); }
[data-theme-layout="dtc-grocer"] .link-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.5rem 1.2rem; }
[data-theme-layout="dtc-grocer"] .link-card { position: relative; border: 0; border-radius: 0; border-bottom: 7px solid var(--gcr-wood); background: linear-gradient(180deg, color-mix(in srgb, var(--gcr-bag) 96%, #fff), var(--gcr-bag) 42%, color-mix(in srgb, var(--gcr-bag) 93%, #000)); box-shadow: none; clip-path: polygon(4.5% 0, 95.5% 0, 100% 100%, 0 100%); padding-top: 1.05rem; }
[data-theme-layout="dtc-grocer"] .link-card::before { content: ""; position: absolute; top: .5rem; left: 7%; right: 7%; border-top: 2px dashed color-mix(in srgb, var(--gcr-bag-ink) 30%, var(--gcr-bag)); }
[data-theme-layout="dtc-grocer"] .link-card:hover { transform: translateY(-3px); box-shadow: none; }
[data-theme-layout="dtc-grocer"] .lc-cover { margin: 0 .9rem; border-radius: 6px; background: color-mix(in srgb, var(--gcr-bag) 82%, #fff); }
[data-theme-layout="dtc-grocer"] .lc-mono { color: var(--gcr-bag-accent); }
[data-theme-layout="dtc-grocer"] .lc-body { padding: .85rem 1.15rem 1.05rem; background: transparent; }
[data-theme-layout="dtc-grocer"] .lc-title { color: var(--gcr-bag-ink); font-weight: 700; }
[data-theme-layout="dtc-grocer"] .link-card:hover .lc-title { color: var(--gcr-bag-ink); } /* hover 靠抬升，不降字色对比 */
[data-theme-layout="dtc-grocer"] .lc-arrow { color: var(--gcr-bag-accent); }
[data-theme-layout="dtc-grocer"] .lc-intro { display: -webkit-box; overflow: hidden; color: var(--gcr-bag-muted); -webkit-box-orient: vertical; -webkit-line-clamp: 3; }
[data-theme-layout="dtc-grocer"] .lc-foot .tag { border: 1px dashed color-mix(in srgb, var(--gcr-bag-accent) 55%, var(--gcr-bag)); border-radius: 4px; background: transparent; color: var(--gcr-bag-accent); font-weight: 650; }
[data-theme-layout="dtc-grocer"] .pagination .cur { background: var(--gcr-board); border-color: var(--gcr-board); color: var(--gcr-chalk); }

/* ---- 内页 · 商品详情（product_detail 的 DOM）：产地/储存双纸卡 + 黑板营养行 ---- */
[data-theme-layout="dtc-grocer"] .pd-media { border: 1px solid var(--line); border-radius: 8px; }
[data-theme-layout="dtc-grocer"] .pd-title { font-family: var(--dt-display, var(--serif)); letter-spacing: .03em; }
/* 文本字段行（产地/储存/保质期…）升格为双列纸袋卡 */
[data-theme-layout="dtc-grocer"] .pd-meta { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .8rem; margin: 1.3rem 0 0; padding: 0; border: 0; }
[data-theme-layout="dtc-grocer"] .pd-meta-row { display: flex; flex-direction: column; gap: .3rem; padding: .85rem 1rem .95rem; border: 0; border-bottom: 5px solid var(--gcr-wood); background: linear-gradient(180deg, color-mix(in srgb, var(--gcr-bag) 96%, #fff), var(--gcr-bag) 42%, color-mix(in srgb, var(--gcr-bag) 93%, #000)); clip-path: polygon(3% 0, 97% 0, 100% 100%, 0 100%); }
[data-theme-layout="dtc-grocer"] .pd-meta-row dt { color: var(--gcr-bag-muted); font-size: .74rem; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-grocer"] .pd-meta-row dd { margin: 0; color: var(--gcr-bag-ink); font-weight: 650; }
[data-theme-layout="dtc-grocer"] .pd-meta-row dd a { color: var(--gcr-bag-accent); }
/* specs 表=黑板营养行：墨绿板+木框，规格名粉笔白、值粉笔灰右对齐，行间点线 */
[data-theme-layout="dtc-grocer"] .pd-sec-title { font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-grocer"] .pd-specs-tablewrap { border: 6px solid var(--gcr-wood); border-radius: 10px; background: var(--gcr-board); padding: .5rem 1.1rem; box-shadow: var(--shadow); }
[data-theme-layout="dtc-grocer"] .pd-specs-table th, [data-theme-layout="dtc-grocer"] .pd-specs-table td { background: transparent; border: 0; border-bottom: 2px dotted color-mix(in srgb, var(--gcr-chalk) 32%, transparent); }
[data-theme-layout="dtc-grocer"] .pd-specs-table tr:last-child th, [data-theme-layout="dtc-grocer"] .pd-specs-table tr:last-child td { border-bottom: 0; }
[data-theme-layout="dtc-grocer"] .pd-specs-table th { color: var(--gcr-chalk); font-weight: 650; }
[data-theme-layout="dtc-grocer"] .pd-specs-table td { color: var(--gcr-chalk-soft); text-align: right; }
/* 首屏询盘=大纸袋卡；按钮统一黑板绿粉笔字（noir 皮浅 ink 落在纸面会翻车，一律板色） */
[data-theme-layout="dtc-grocer"] .pd-inquiry { position: relative; padding: 1.7rem 1.3rem 1.4rem; border: 0; border-bottom: 6px solid var(--gcr-wood); background: linear-gradient(180deg, color-mix(in srgb, var(--gcr-bag) 96%, #fff), var(--gcr-bag) 42%, color-mix(in srgb, var(--gcr-bag) 93%, #000)); clip-path: polygon(2.5% 0, 97.5% 0, 100% 100%, 0 100%); }
[data-theme-layout="dtc-grocer"] .pd-inquiry::before { content: ""; position: absolute; top: .55rem; left: 5%; right: 5%; border-top: 2px dashed color-mix(in srgb, var(--gcr-bag-ink) 30%, var(--gcr-bag)); }
[data-theme-layout="dtc-grocer"] .pd-inquiry .inquiry-title { color: var(--gcr-bag-ink); font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-grocer"] .pd-inquiry .inquiry-note { color: var(--gcr-bag-muted); }
[data-theme-layout="dtc-grocer"] .pd-inquiry .inquiry-btn { background: var(--gcr-board); border-color: var(--gcr-board); color: var(--gcr-chalk); }
[data-theme-layout="dtc-grocer"] .pd-inquiry .inquiry-btn:hover { background: color-mix(in srgb, var(--gcr-board) 78%, #000); border-color: color-mix(in srgb, var(--gcr-board) 78%, #000); color: var(--gcr-chalk); }
[data-theme-layout="dtc-grocer"] .pd-rel-card { border: 0; border-radius: 0; border-bottom: 6px solid var(--gcr-wood); background: linear-gradient(180deg, color-mix(in srgb, var(--gcr-bag) 96%, #fff), var(--gcr-bag) 42%, color-mix(in srgb, var(--gcr-bag) 93%, #000)); clip-path: polygon(4.5% 0, 95.5% 0, 100% 100%, 0 100%); padding: .9rem .8rem .8rem; color: var(--gcr-bag-ink); }
[data-theme-layout="dtc-grocer"] .pd-rel-media { margin-top: .35rem; border-radius: 6px; background: color-mix(in srgb, var(--gcr-bag) 82%, #fff); }
[data-theme-layout="dtc-grocer"] .pd-rel-gen b { color: var(--gcr-bag-accent); }
[data-theme-layout="dtc-grocer"] .pd-rel-title { padding-inline: .3rem; color: var(--gcr-bag-ink); font-weight: 700; }

/* ---- 响应式：920 两列 / 720 单列绝无横溢；梯形收敛防夹挤 ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-grocer"] .gcr-hero-inner { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-grocer"] .gcr-hero-side { max-width: 420px; }
  [data-theme-layout="dtc-grocer"] .gcr-shelf, [data-theme-layout="dtc-grocer"] .link-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-grocer"] .gcr-shelf, [data-theme-layout="dtc-grocer"] .link-grid { grid-template-columns: 1fr; gap: 1.1rem; }
  [data-theme-layout="dtc-grocer"] .pd-meta { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-grocer"] .gcr-hero.has-img { min-height: 56vh; }
  [data-theme-layout="dtc-grocer"] .gcr-hero-inner { padding: 1.4rem 1.1rem 1.6rem; }
  [data-theme-layout="dtc-grocer"] .gcr-menu-name { max-width: 55%; }
  [data-theme-layout="dtc-grocer"] :is(.gcr-bag, .link-card, .pd-meta-row, .pd-inquiry, .pd-rel-card) { clip-path: polygon(2.5% 0, 97.5% 0, 100% 100%, 0 100%); }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-grocer"] :is(.gcr-bag, .link-card, .gcr-aisle, .site-header .nav > a, .gcr-bag-media img) { transition: none; }
  [data-theme-layout="dtc-grocer"] :is(.gcr-bag, .link-card, .gcr-aisle):hover { transform: translateY(0); }
  [data-theme-layout="dtc-grocer"] :is(.gcr-bag, .link-card):hover img { transform: none; }
}

/* ============================================================
   皮肤 ×3（变量成套覆写；正文≥7、次要/accent≥4.5，hover 只升不降，实算见提交说明）
   ============================================================ */
/* ---- 食铺 · Grocer（原生）：麦米 #f5efe2 + 黑板绿 #23372c + 木棕 #6d4c33 ----
   ink/bg 13.58, ink-soft/bg 8.23, muted/bg 5.66(卡面 surface 6.06), accent/bg 6.80
   (hover soft 9.23↑), 白字/accent 钮 7.80, 粉笔/板 10.94, 粉笔灰/板 8.34,
   粉笔黄/板 7.78, 板字/粉笔黄钮 7.70, 木牌字/木棕 6.57, 袋字/纸袋 11.75,
   袋次字/纸袋 5.61, 袋绿签/纸袋 5.98, muted/wash(CTA note) 5.25 */
:root[data-theme="grocer"] {
  --bg: #f5efe2; --surface: #fbf7ed;
  --ink: #29231a; --ink-soft: #4d453a; --muted: #665d4d; --faint: #93876f;
  --line: #ded3ba; --line-soft: #ebe3d0;
  --accent: #2e5b43; --accent-soft: #22462f; --accent-wash: #e5e9d9;
  --radius: 10px; --w-wide: 1200px;
  --shadow: 0 1px 2px rgba(41,35,26,.06), 0 10px 26px rgba(41,35,26,.09);
  --gcr-board: #23372c; --gcr-chalk: #f2eee2; --gcr-chalk-soft: #ccd4c5; --gcr-chalk-accent: #e9c684;
  --gcr-wood: #6d4c33; --gcr-wood-ink: #f7ecd9;
  --gcr-bag: #eee0c4; --gcr-bag-ink: #2b241a; --gcr-bag-muted: #5f5544; --gcr-bag-accent: #2e5b43;
}
:root[data-theme="grocer"] .btn-primary { color: #fff; }

/* ---- 食铺 · Grocer Noir（反差暗皮）：黑板绿夜底 + 粉笔白 + 木棕，accent=黄油粉笔 ----
   ink/bg 14.22(surface 12.22), ink-soft/bg 11.19, muted/bg 7.23(surface 6.21),
   accent/bg 9.23(hover soft 10.77↑), accent/wash 6.25, 深字/accent 钮 8.37,
   粉笔/板 10.90, 粉笔灰/板 8.13, 粉笔黄/板 7.78, 木牌字/木棕 6.57,
   袋字/牛皮纸 10.36, 袋次字/牛皮纸 5.19, 袋绿签/牛皮纸 5.77, muted/wash 4.90 */
:root[data-theme="grocer-noir"] {
  --bg: #16221b; --surface: #1e2f25;
  --ink: #edf0e4; --ink-soft: #cfd8c8; --muted: #a3b09c; --faint: #76836e;
  --line: #34483b; --line-soft: #283a2f;
  --accent: #e3bd76; --accent-soft: #eecd90; --accent-wash: #2c4033;
  --radius: 10px; --w-wide: 1200px;
  --shadow: 0 1px 2px rgba(0,0,0,.5), 0 12px 30px rgba(0,0,0,.5);
  --gcr-board: #23372c; --gcr-chalk: #f0eee2; --gcr-chalk-soft: #c8d2c2; --gcr-chalk-accent: #e9c684;
  --gcr-wood: #6d4c33; --gcr-wood-ink: #f7ecd9;
  --gcr-bag: #e3d3ae; --gcr-bag-ink: #2b241a; --gcr-bag-muted: #5c5240; --gcr-bag-accent: #2f5440;
}
:root[data-theme="grocer-noir"] .btn-primary { color: #1f2a20; } /* accent 是浅黄油粉笔，钮字用夜绿 8.37 */

/* ---- 食铺 · Grocer White（纯白皮）：中性灰基底对齐纯白系；黑板/木牌保留当签名色，
   纸袋卡去梯形 clip-path 改细描边+纯白面（避免大面积米色）----
   ink/bg 18.72(surface 17.91), ink-soft/bg 9.79, muted/bg 4.99(surface 4.77——
   #707680 在 #fafaf8 上只有 4.38 的坑，压深为 #6a707a 过审), accent/bg 8.23
   (hover soft 11.22↑), 白字/accent 钮 8.23, 粉笔/板 11.33, 粉笔黄/板 7.78,
   白牌字/木棕 7.69, 袋次字/白袋 4.99, 袋绿签/白袋 8.23 */
:root[data-theme="grocer-white"] {
  --bg: #ffffff; --surface: #fafaf8;
  --ink: #101218; --ink-soft: #3f444d; --muted: #6a707a; --faint: #a9aeb6;
  --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #265840; --accent-soft: #1c4230; --accent-wash: #e9f1ec;
  --radius: 10px; --w-wide: 1200px;
  --shadow: 0 1px 2px rgba(16,18,24,.05), 0 10px 26px rgba(16,18,24,.07);
  --gcr-board: #23372c; --gcr-chalk: #f4f2ea; --gcr-chalk-soft: #ccd4c5; --gcr-chalk-accent: #e9c684;
  --gcr-wood: #6d4c33; --gcr-wood-ink: #ffffff;
  --gcr-bag: #ffffff; --gcr-bag-ink: #101218; --gcr-bag-muted: #6a707a; --gcr-bag-accent: #265840;
}
:root[data-theme="grocer-white"] .btn-primary { color: #fff; }
:root[data-theme="grocer-white"] :is(.gcr-bag, .link-card, .pd-meta-row, .pd-inquiry, .pd-rel-card) { clip-path: none; border: 1px solid var(--line); border-bottom: 5px solid var(--gcr-wood); border-radius: 8px 8px 4px 4px; background: #fff; }
:root[data-theme="grocer-white"] :is(.gcr-aisle, .cat-nav a) { border: 1px solid var(--line); border-left: 5px solid var(--gcr-wood); background: #fff; }
:root[data-theme="grocer-white"] .cat-nav a.active { border-color: var(--gcr-board); border-left-color: color-mix(in srgb, var(--gcr-board) 55%, #000); background: var(--gcr-board); }
:root[data-theme="grocer-white"] :is(.gcr-bag-media, .lc-cover, .pd-rel-media) { background: var(--surface); }
:root[data-theme="grocer-white"] .dt-cta-note { color: var(--ink-soft); } /* muted 落 accent-wash 只有 4.34，换 ink-soft 8.51 */

/* =========================================================================
   LAYOUT: dtc-cellar — 「酒窖」（clr-*）：暗底鎏金细线页头（品牌+导航两行居中，
   金字 .2em 字距、底 1px 金线 33% 透明——三皮共用深木黑门楣）+ 窖藏题词 hero
   （居中金眉标/衬线大题/羊皮米描述，双细线匾框）+ 横向酒架行（4 瓶一层，
   层底 3px 木棕粗线=架板，由每张瓶卡 ::after 拼成整条；瓶卡=深底细木框，
   年份签=productChips 第一签 mono 金字）。全部选择器限定 [data-theme-layout="dtc-cellar"]；
   本段必须排在 DTC 共用段（dt-*）之后。木色走 --clr-wood/--clr-shelf 令牌，皮肤覆写。
   ========================================================================= */
[data-theme-layout="dtc-cellar"] { --clr-wood: #5d472a; --clr-shelf: #7a5a34; }
[data-theme-layout="dtc-cellar"] .clr-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-cellar"] .btn, [data-theme-layout="dtc-cellar"] .inquiry-btn { border-radius: 2px; }

/* ---- 页头重塑：暗底鎏金（≤620px 交还基础汉堡抽屉，重塑段整体包 min-width:621px）。
   门楣三皮共用深木黑literal：金 #d9a848/#1d1710 实算 8.16、hover #ecc887 11.15↑、
   品牌羊皮米 #e8ddc2 13.15。 ---- */
@media (min-width: 621px) {
  [data-theme-layout="dtc-cellar"] .site-header { background: #1d1710; border-bottom: 1px solid rgba(217,168,72,.33); -webkit-backdrop-filter: none; backdrop-filter: none; }
  [data-theme-layout="dtc-cellar"] .site-header .wrap { flex-direction: column; justify-content: center; gap: .5rem; height: auto; padding-top: .95rem; padding-bottom: .8rem; }
  [data-theme-layout="dtc-cellar"] .site-header .brand, [data-theme-layout="dtc-cellar"] .site-header .brand-name { color: #e8ddc2; letter-spacing: .12em; }
  [data-theme-layout="dtc-cellar"] .nav { justify-content: center; flex-wrap: wrap; gap: .4rem 1.9rem; }
  [data-theme-layout="dtc-cellar"] .nav a { color: #d9a848; font-size: .78rem; font-weight: 600; letter-spacing: .2em; text-transform: uppercase; }
  [data-theme-layout="dtc-cellar"] .nav a:hover, [data-theme-layout="dtc-cellar"] .nav a[aria-current="page"] { color: #ecc887; }
  [data-theme-layout="dtc-cellar"] .nav a[aria-current="page"]::after { bottom: -5px; height: 1px; background: #d9a848; }
  [data-theme-layout="dtc-cellar"] .nav .search-ico { opacity: .85; }
  [data-theme-layout="dtc-cellar"] .site-header .lang-switch summary { color: #e8ddc2; }
}

/* ---- 窖藏题词 hero：居中匾额（细线框+内缩 33% 金内框）；三态照 flagship——
   image=全幅底图 scrim 压字 / svg / 默认轻动画（后两者落在题词下方）。 ---- */
[data-theme-layout="dtc-cellar"] .clr-hero { position: relative; margin-top: 1.6rem; padding: clamp(2.6rem, 6vw, 4.6rem) clamp(1.2rem, 4vw, 3rem); border: 1px solid var(--line); border-radius: var(--radius); outline: 1px solid color-mix(in srgb, var(--accent) 33%, transparent); outline-offset: -8px; background: var(--surface); text-align: center; overflow: hidden; }
[data-theme-layout="dtc-cellar"] .clr-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
/* scrim 全幅压暗（文案居中，全域都要可读）：白字对纯白图最坏底 ≥7.50（.7 顶）～12.72（.84 底），
   金眉标 #f2e6c8 ≥6.05、lede(.92 白) ≥6.66 */
[data-theme-layout="dtc-cellar"] .clr-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(16,11,5,.7), rgba(16,11,5,.84)); }
[data-theme-layout="dtc-cellar"] .clr-hero-inner { position: relative; z-index: 1; max-width: 46rem; margin: 0 auto; }
[data-theme-layout="dtc-cellar"] .clr-eyebrow { margin-bottom: 1rem; font-size: .78rem; letter-spacing: .34em; }
[data-theme-layout="dtc-cellar"] .clr-h1 { margin: 0; font-family: var(--dt-display, var(--serif)); font-size: clamp(2rem, 4.4vw, 3.2rem); font-weight: 600; line-height: 1.16; letter-spacing: .01em; }
[data-theme-layout="dtc-cellar"] .clr-lede { display: -webkit-box; overflow: hidden; max-width: 58ch; margin: 1rem auto 0; color: var(--ink-soft); font-size: 1rem; line-height: 1.9; -webkit-box-orient: vertical; -webkit-line-clamp: 4; } /* 羊皮米字宽行距；长文钳 4 行护匾框比例 */
[data-theme-layout="dtc-cellar"] .clr-cta { display: flex; flex-wrap: wrap; justify-content: center; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="dtc-cellar"] .clr-hero-side { max-width: 440px; margin: 2.2rem auto 0; }
[data-theme-layout="dtc-cellar"] .clr-hero.has-img .dt-eyebrow { color: #f2e6c8; }
[data-theme-layout="dtc-cellar"] .clr-hero.has-img .clr-h1 { color: #fff; } /* 全局 h1 色规则会盖过继承，压图必须显式白字 */
[data-theme-layout="dtc-cellar"] .clr-hero.has-img .clr-lede { color: rgba(255,255,255,.92); }
[data-theme-layout="dtc-cellar"] .clr-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-cellar"] .clr-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-cellar"] .clr-hero.has-img .btn-primary { background: #e8ddc2; border-color: #e8ddc2; color: #1c150b; } /* 羊皮米按钮 13.39 */

/* ---- 横向酒架：4 瓶一层；层底架板=瓶卡 ::after 各伸半个列距拼成通条（专属车道=卡自身，
   容器 overflow:clip 收边，padding-bottom 给末层架板留位）；分类=酒区细字排。 ---- */
[data-theme-layout="dtc-cellar"] .clr-section { padding-top: clamp(3rem, 6vw, 4.4rem); }
[data-theme-layout="dtc-cellar"] .clr-cats { display: flex; flex-wrap: wrap; gap: .4rem 1.6rem; margin: 0 0 1.4rem; padding-bottom: .85rem; border-bottom: 1px solid color-mix(in srgb, var(--accent) 33%, transparent); }
[data-theme-layout="dtc-cellar"] .clr-cats a { color: var(--accent); font-size: .78rem; font-weight: 650; letter-spacing: .18em; text-transform: uppercase; }
[data-theme-layout="dtc-cellar"] .clr-cats a:hover { color: var(--accent-soft); }
[data-theme-layout="dtc-cellar"] .clr-cats i { font-style: normal; color: var(--muted); font-size: .72rem; letter-spacing: 0; }
[data-theme-layout="dtc-cellar"] .clr-rack { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 2.4rem 1.3rem; overflow: clip; padding-bottom: .8rem; }
[data-theme-layout="dtc-cellar"] .clr-card { position: relative; display: flex; flex-direction: column; min-width: 0; border: 1px solid var(--clr-wood); border-radius: var(--radius) var(--radius) 0 0; background: var(--surface); color: var(--ink); transition: border-color var(--speed); } /* 底缘收直角：瓶箱坐实架板 */
[data-theme-layout="dtc-cellar"] .clr-card::after { content: ""; position: absolute; left: -.65rem; right: -.65rem; bottom: -.55rem; height: 3px; background: var(--clr-shelf); } /* 架板 */
[data-theme-layout="dtc-cellar"] .clr-card:hover { border-color: var(--accent); color: var(--ink); }
[data-theme-layout="dtc-cellar"] .clr-card-media { display: grid; place-items: center; aspect-ratio: 4 / 5; border-radius: var(--radius) var(--radius) 0 0; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-cellar"] .clr-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-cellar"] .clr-card:hover .clr-card-media img { transform: scale(1.04); }
[data-theme-layout="dtc-cellar"] .clr-card-body { display: flex; flex: 1; flex-direction: column; gap: .35rem; padding: .75rem .85rem .9rem; }
[data-theme-layout="dtc-cellar"] .clr-vintage { display: flex; align-items: baseline; gap: .5rem; min-width: 0; font-family: var(--mono); font-size: .72rem; letter-spacing: .06em; color: var(--accent); } /* 年份签：mono 金字 */
[data-theme-layout="dtc-cellar"] .clr-vintage b { flex: none; font-weight: 700; text-transform: uppercase; }
[data-theme-layout="dtc-cellar"] .clr-vintage i { font-style: normal; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
[data-theme-layout="dtc-cellar"] .clr-card-title { font-family: var(--dt-display, var(--serif)); font-size: 1rem; font-weight: 620; line-height: 1.4; }
/* 窖藏数字：金字行——去卡面，上缘 33% 金细线 */
[data-theme-layout="dtc-cellar"] .clr-stats .dt-stat { padding: 1.1rem .5rem 0; border: 0; border-top: 1px solid color-mix(in srgb, var(--accent) 33%, transparent); border-radius: 0; background: none; }
[data-theme-layout="dtc-cellar"] .clr-stats .dt-stat dt { color: var(--accent); font-weight: 600; }

/* ---- 内页 · 商品列表（generic_list DOM）：酒架分层同构——瓶卡细木框 + 架板通条 ---- */
[data-theme-layout="dtc-cellar"] .page-head { padding: 2.4rem 0 1.2rem; }
[data-theme-layout="dtc-cellar"] .page-head h1 { font-family: var(--dt-display, var(--serif)); font-weight: 600; letter-spacing: .01em; }
[data-theme-layout="dtc-cellar"] .page-head .eyebrow { color: var(--accent); letter-spacing: .3em; }
[data-theme-layout="dtc-cellar"] .cat-nav { gap: .4rem 1.6rem; margin: 1.6rem 0 .4rem; padding-bottom: .85rem; border-bottom: 1px solid color-mix(in srgb, var(--accent) 33%, transparent); }
[data-theme-layout="dtc-cellar"] .cat-nav a { padding: 0; border: 0; border-radius: 0; background: none; color: var(--accent); font-size: .78rem; font-weight: 650; letter-spacing: .18em; text-transform: uppercase; }
[data-theme-layout="dtc-cellar"] .cat-nav a:hover { color: var(--accent-soft); background: none; }
[data-theme-layout="dtc-cellar"] .cat-nav a.active { border: 0; background: none; color: var(--ink); text-decoration: underline; text-underline-offset: .55em; text-decoration-color: var(--accent); }
[data-theme-layout="dtc-cellar"] .cat-nav a .muted { color: var(--muted); font-size: .7rem; }
[data-theme-layout="dtc-cellar"] .link-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 2.4rem 1.3rem; overflow: clip; padding-bottom: .8rem; }
[data-theme-layout="dtc-cellar"] .link-grid > .muted { grid-column: 1 / -1; margin: 0; padding: 1.8rem; border: 1px dashed var(--clr-wood); border-radius: var(--radius); text-align: center; } /* 空态占整层，别缩在第一格 */
[data-theme-layout="dtc-cellar"] .link-card { position: relative; border-color: var(--clr-wood); border-radius: var(--radius) var(--radius) 0 0; overflow: visible; } /* 放开裁剪给架板；圆角交给 lc-cover 自守 */
[data-theme-layout="dtc-cellar"] .link-card::after { content: ""; position: absolute; left: -.65rem; right: -.65rem; bottom: -.55rem; height: 3px; background: var(--clr-shelf); }
[data-theme-layout="dtc-cellar"] .link-card:hover { transform: none; border-color: var(--accent); box-shadow: none; }
[data-theme-layout="dtc-cellar"] .lc-cover { aspect-ratio: 4 / 5; border-radius: var(--radius) var(--radius) 0 0; overflow: hidden; }
[data-theme-layout="dtc-cellar"] .lc-foot { margin-top: auto; } /* 分类签沉底=年份签位 */
[data-theme-layout="dtc-cellar"] .lc-mono { background: var(--accent-wash); color: var(--accent); font-family: var(--dt-display, var(--serif)); } /* 弃白字渐变底，wash+accent 三皮实算 ≥5.36 */
[data-theme-layout="dtc-cellar"] .lc-title { font-family: var(--dt-display, var(--serif)); font-size: 1.02rem; font-weight: 620; }
[data-theme-layout="dtc-cellar"] .lc-intro { font-size: .86rem; line-height: 1.7; }
[data-theme-layout="dtc-cellar"] .lc-foot .tag { padding: 0; border: 0; background: none; color: var(--accent); font-family: var(--mono); font-size: .7rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-cellar"] .pagination a, [data-theme-layout="dtc-cellar"] .pagination span { border-radius: 2px; }

/* ---- 内页 · 商品详情（product_detail DOM）：品鉴笔记——正文衬线宽行距 1.9；
   规格表化作年份轴：左缘 33% 金细线，每行金点 + mono 金字签名位。 ---- */
[data-theme-layout="dtc-cellar"] .pd-title { font-family: var(--dt-display, var(--serif)); font-weight: 600; letter-spacing: .005em; }
[data-theme-layout="dtc-cellar"] .pd-kicker a { letter-spacing: .18em; }
[data-theme-layout="dtc-cellar"] .pd-media { border-color: var(--clr-wood); }
[data-theme-layout="dtc-cellar"] .pd-media-gen b { font-family: var(--dt-display, var(--serif)); }
[data-theme-layout="dtc-cellar"] .pd-thumb { border-radius: 2px; }
[data-theme-layout="dtc-cellar"] .pd-lead { font-family: var(--dt-display, var(--serif)); font-size: 1.05rem; line-height: 1.9; }
[data-theme-layout="dtc-cellar"] .pd-desc .prose { max-width: 70ch; font-family: var(--dt-display, var(--serif)); font-size: 1.02rem; line-height: 1.9; }
[data-theme-layout="dtc-cellar"] .pd-desc .prose blockquote { border-left: 2px solid var(--accent); color: var(--ink-soft); } /* 品鉴引文=金侧线 */
[data-theme-layout="dtc-cellar"] .pd-sec-title { font-family: var(--dt-display, var(--serif)); font-weight: 620; }
[data-theme-layout="dtc-cellar"] .pd-meta { border-top-color: var(--clr-wood); }
[data-theme-layout="dtc-cellar"] .pd-inquiry { padding: 1.1rem 1.2rem 1.25rem; border: 1px solid var(--clr-wood); border-radius: var(--radius); background: var(--surface); }
[data-theme-layout="dtc-cellar"] .pd-inquiry .inquiry-actions { display: grid; grid-template-columns: 1fr; gap: .55rem; }
[data-theme-layout="dtc-cellar"] .pd-inquiry .inquiry-btn { justify-content: center; }
[data-theme-layout="dtc-cellar"] .pd-specs-tablewrap { border: 0; border-radius: 0; background: none; overflow: visible; }
[data-theme-layout="dtc-cellar"] .pd-specs-table, [data-theme-layout="dtc-cellar"] .pd-specs-table tbody { display: block; width: 100%; }
[data-theme-layout="dtc-cellar"] .pd-specs-table tr { position: relative; display: flex; align-items: baseline; gap: 1rem; padding: .6rem 0 .6rem 1.5rem; border-left: 1px solid color-mix(in srgb, var(--accent) 33%, transparent); }
[data-theme-layout="dtc-cellar"] .pd-specs-table tr::before { content: ""; position: absolute; left: -4px; top: 1.05rem; width: 7px; height: 7px; border-radius: 50%; background: var(--accent); } /* 轴上金点 */
[data-theme-layout="dtc-cellar"] .pd-specs-table th { flex: none; width: auto; min-width: 8.5rem; padding: 0; border: 0; background: none; color: var(--accent); font-family: var(--mono); font-size: .78rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
[data-theme-layout="dtc-cellar"] .pd-specs-table td { flex: 1; min-width: 0; padding: 0; border: 0; overflow-wrap: anywhere; color: var(--ink); }
[data-theme-layout="dtc-cellar"] .pd-rel-card { border-color: var(--clr-wood); }
[data-theme-layout="dtc-cellar"] .pd-rel-card:hover { transform: none; border-color: var(--accent); box-shadow: none; }
[data-theme-layout="dtc-cellar"] .pd-rel-media { aspect-ratio: 4 / 5; }
[data-theme-layout="dtc-cellar"] .pd-rel-title { font-family: var(--dt-display, var(--serif)); font-weight: 620; }

/* ---- 响应式：920 三瓶一层、720 双瓶（酒架/列表同构收窄，无横溢）；reduced-motion 关动画 ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-cellar"] .clr-rack, [data-theme-layout="dtc-cellar"] .link-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-cellar"] .clr-rack, [data-theme-layout="dtc-cellar"] .link-grid { grid-template-columns: 1fr 1fr; gap: 2rem .8rem; }
  [data-theme-layout="dtc-cellar"] .clr-hero { padding: 2rem 1.1rem 2.2rem; }
  [data-theme-layout="dtc-cellar"] .clr-hero-side { max-width: 340px; }
  [data-theme-layout="dtc-cellar"] .clr-vintage { font-size: .68rem; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-cellar"] .clr-card, [data-theme-layout="dtc-cellar"] .clr-card-media img,
  [data-theme-layout="dtc-cellar"] .link-card, [data-theme-layout="dtc-cellar"] .lc-cover img { transition: none; }
}

/* ============================================================
   dtc-cellar 皮肤 ×3：原生 cellar（暗）/ 浅反差 cellar-day / 纯白 cellar-white。
   全变量成套覆写；对比实算见各块注释（正文≥7、次要/accent≥4.5、hover 只升不降）。
   ============================================================ */

/* ---- 酒窖 · Cellar（原生，暗）：窖黑 #17130e + 鎏金 #d9a848 + 羊皮米 #e8ddc2。
   实算：ink/bg 13.69、ink-soft/bg 10.46、muted/bg 6.80、muted/wash 5.83、
   accent/bg 8.49、accent/surface 7.92、accent/wash 7.29、hover accent-soft/bg 10.44↑
  （暗皮 hover 提亮）、btn 主按钮 surface-on-ink 12.77 ---- */
:root[data-theme="cellar"] {
  --bg: #17130e; --surface: #201a12; --ink: #e8ddc2; --ink-soft: #cfc2a0;
  --muted: #a89c7e; --faint: #7d7259; --line: #37301f; --line-soft: #262013;
  --accent: #d9a848; --accent-soft: #e6bd6c; --accent-wash: #2a2110;
  --radius: 3px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(0,0,0,.5), 0 14px 34px rgba(0,0,0,.45);
  --clr-wood: #5d472a; --clr-shelf: #7a5a34;
}

/* ---- 日窖 · Cellar Day（浅反差）：日窖亮米 + 深木褐 + 暗金（金作文字压深）。
   实算：ink/bg 14.18、ink-soft/bg 8.23、muted/bg 5.51、muted/wash 5.17、
   accent #75550c /bg 6.09、/surface 6.69、/wash 5.71（全部 ≥4.5）、
   hover accent-soft/bg 8.49↑、btn 主按钮 15.58 ---- */
:root[data-theme="cellar-day"] {
  --bg: #f7f1e2; --surface: #fffcf3; --ink: #2a2012; --ink-soft: #54452c;
  --muted: #6e5f43; --faint: #9a8d70; --line: #e2d7ba; --line-soft: #eee6cf;
  --accent: #75550c; --accent-soft: #5a4109; --accent-wash: #f3ead0;
  --radius: 3px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(42,32,18,.05), 0 12px 28px rgba(42,32,18,.08);
  --clr-wood: #b3966a; --clr-shelf: #5f4526;
}

/* ---- 窖白 · Cellar White：共享中性灰纯白基底；surface 收纯白避开
   「muted #707680 在 #fafaf8 上 4.38」的坑（瓶卡靠细木框分面，不靠面色）。
   实算：ink/bg 18.72、ink-soft/bg 9.79、muted/bg 4.57、accent #7d5c10 /bg 6.16、
   /wash 5.36、hover accent-soft/bg 8.87↑、btn 主按钮 18.72 ---- */
:root[data-theme="cellar-white"] {
  --bg: #ffffff; --surface: #ffffff; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #7d5c10; --accent-soft: #5f460c; --accent-wash: #f5efdc;
  --radius: 2px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(16,18,24,.04), 0 10px 24px rgba(16,18,24,.06);
  --clr-wood: #c9bda9; --clr-shelf: #6b4f30;
}
/* CTA 注释行 muted 落在 wash 上只有 3.98，压回 ink-soft（8.51） */
:root[data-theme="cellar-white"] .dt-cta-note { color: var(--ink-soft); }

/* ============================================================================
   dtc-basecamp 骨架（bcp-*）：「营地」——路标木牌箭头导航 + 等高线底纹 +
   开拔词 hero + 装备清单行（60px 缩略图 + 名称 + 规格签 + 右端 mono 军绿重量列）。
   每条选择器限定 [data-theme-layout="dtc-basecamp"]；容器规约同族。
   皮肤 ×3：basecamp（苔白+军绿+深林墨）/ basecamp-noir（夜营深绿+月白）/ basecamp-white。
   ========================================================================== */
[data-theme-layout="dtc-basecamp"] { --dt-display: var(--sans); }
[data-theme-layout="dtc-basecamp"] .bcp-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
/* 等高线底纹：两组错位细环线（1px），透明度走皮肤变量 --bcp-contour（白皮 transparent 即隐去） */
[data-theme-layout="dtc-basecamp"] body {
  background:
    repeating-radial-gradient(circle at 14% -8%, transparent 0 44px, var(--bcp-contour) 44px 45px),
    repeating-radial-gradient(circle at 88% 110%, transparent 0 56px, var(--bcp-contour) 56px 57px),
    var(--bg);
}

/* ---- 页头=路标木牌（只准 CSS 重塑标准 .site-header；≤620px 交还基础汉堡抽屉） ----
   每个导航项一块军绿木牌，右端箭头 clip-path polygon(0 0,86% 0,100% 50%,86% 100%,0 100%)。 */
@media (min-width: 621px) {
  [data-theme-layout="dtc-basecamp"] .site-header { position: static; background: transparent; border-bottom: 0; -webkit-backdrop-filter: none; backdrop-filter: none; }
  [data-theme-layout="dtc-basecamp"] .site-header .wrap { height: auto; padding-top: 1.1rem; padding-bottom: 1rem; gap: 1.2rem; }
  [data-theme-layout="dtc-basecamp"] .site-header .nav { gap: .5rem; flex-wrap: wrap; justify-content: flex-end; }
  [data-theme-layout="dtc-basecamp"] .site-header .nav > a:not(.search-ico) {
    display: inline-flex; align-items: center; padding: .5rem 1.55rem .5rem 1rem;
    border-radius: 3px 0 0 3px; background: var(--bcp-sign); color: var(--bcp-sign-ink);
    clip-path: polygon(0 0, 86% 0, 100% 50%, 86% 100%, 0 100%);
    font-size: .87rem; font-weight: 650; letter-spacing: .02em; transition: background var(--speed);
  }
  [data-theme-layout="dtc-basecamp"] .site-header .nav > a:not(.search-ico):hover { background: var(--bcp-sign-hover); color: var(--bcp-sign-ink); }
  [data-theme-layout="dtc-basecamp"] .site-header .nav > a[aria-current="page"] { background: var(--bcp-sign-hover); color: var(--bcp-sign-ink); }
  [data-theme-layout="dtc-basecamp"] .site-header .nav > a[aria-current="page"]::after { content: none; }
}

/* ---- hero：开拔词（HeroTitle+HeroDescription；三态照 flagship） ---- */
[data-theme-layout="dtc-basecamp"] .bcp-hero { position: relative; margin-top: 1.3rem; border: 1px solid var(--line); border-radius: calc(var(--radius) * 1.4); background: linear-gradient(150deg, var(--accent-wash), var(--surface) 62%); overflow: hidden; }
[data-theme-layout="dtc-basecamp"] .bcp-hero-inner { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(280px, .95fr); align-items: center; gap: clamp(1.2rem, 3vw, 2.4rem); padding: clamp(2rem, 5vw, 3.6rem); }
[data-theme-layout="dtc-basecamp"] .bcp-h1 { margin: 0; max-width: 16em; font-family: var(--dt-display, var(--sans)); font-size: clamp(2rem, 4.4vw, 3.2rem); font-weight: 750; line-height: 1.1; letter-spacing: -.015em; }
[data-theme-layout="dtc-basecamp"] .bcp-lede { max-width: 56ch; margin: 1rem 0 0; color: var(--muted); font-size: 1.02rem; line-height: 1.8; }
[data-theme-layout="dtc-basecamp"] .bcp-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="dtc-basecamp"] .bcp-hero-side { min-width: 0; }
[data-theme-layout="dtc-basecamp"] .bcp-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
/* 压图 scrim：文案列压在左 46% 内（α≥.62），最劣纯白底图实算 5.18:1；右缘只作过渡 */
[data-theme-layout="dtc-basecamp"] .bcp-hero.has-img { min-height: min(70vh, 560px); display: flex; align-items: flex-end; }
[data-theme-layout="dtc-basecamp"] .bcp-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(102deg, rgba(16,21,12,.72) 0%, rgba(16,21,12,.62) 46%, rgba(16,21,12,.18) 78%), linear-gradient(200deg, rgba(16,21,12,0) 42%, rgba(16,21,12,.5) 96%); }
[data-theme-layout="dtc-basecamp"] .bcp-hero.has-img .bcp-hero-inner { position: relative; z-index: 1; grid-template-columns: minmax(0, 1fr); }
[data-theme-layout="dtc-basecamp"] .bcp-hero.has-img .dt-eyebrow { color: #fff; opacity: .85; }
[data-theme-layout="dtc-basecamp"] .bcp-hero.has-img .bcp-h1 { color: #fff; } /* 全局 h1 色规则会盖过容器继承，压图必须显式白字 */
[data-theme-layout="dtc-basecamp"] .bcp-hero.has-img .bcp-lede { color: rgba(255,255,255,.88); }
[data-theme-layout="dtc-basecamp"] .bcp-hero.has-img .btn-primary { background: #fff; border-color: #fff; color: #25301f; }
[data-theme-layout="dtc-basecamp"] .bcp-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-basecamp"] .bcp-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }

/* ---- 分类=路线小牌（同款箭头 clip；无边框走 wash 底，箭头斜边不吃 1px 框） ---- */
[data-theme-layout="dtc-basecamp"] .bcp-routes { display: flex; flex-wrap: wrap; gap: .6rem; margin-top: clamp(1.6rem, 4vw, 2.4rem); }
[data-theme-layout="dtc-basecamp"] .bcp-route { display: inline-flex; align-items: baseline; gap: .45rem; min-width: 0; max-width: 100%; padding: .45rem 1.5rem .45rem 1rem; border-radius: 3px 0 0 3px; background: var(--accent-wash); color: var(--ink-soft); clip-path: polygon(0 0, 90% 0, 100% 50%, 90% 100%, 0 100%); font-size: .88rem; font-weight: 650; line-height: 1.4; transition: background var(--speed), color var(--speed); }
[data-theme-layout="dtc-basecamp"] .bcp-route small { font-family: var(--mono); font-size: .74em; font-weight: 750; color: var(--accent); }
[data-theme-layout="dtc-basecamp"] .bcp-route:hover { background: var(--accent); color: var(--bcp-on-accent); }
[data-theme-layout="dtc-basecamp"] .bcp-route:hover small { color: inherit; }

/* ---- 商品=装备清单行：白卡容器 1px 框，行间细线，右端 mono 军绿重量列 ---- */
[data-theme-layout="dtc-basecamp"] .bcp-section { padding-top: clamp(2.8rem, 6vw, 4.2rem); }
[data-theme-layout="dtc-basecamp"] .bcp-manifest { counter-reset: bcprow; border: 1px solid var(--line); border-radius: calc(var(--radius) * 1.2); background: var(--surface); overflow: hidden; }
[data-theme-layout="dtc-basecamp"] .bcp-row { display: grid; grid-template-columns: 2rem 60px minmax(0, 1fr) auto; gap: 1rem; align-items: center; padding: .8rem 1.15rem; color: var(--ink); transition: background var(--speed); }
[data-theme-layout="dtc-basecamp"] .bcp-row + .bcp-row { border-top: 1px solid var(--line-soft); }
[data-theme-layout="dtc-basecamp"] .bcp-row::before { counter-increment: bcprow; content: counter(bcprow, decimal-leading-zero); font-family: var(--mono); font-size: .74rem; color: var(--faint); }
[data-theme-layout="dtc-basecamp"] .bcp-row:hover { background: color-mix(in srgb, var(--accent) 7%, var(--surface)); color: var(--ink); }
[data-theme-layout="dtc-basecamp"] .bcp-row-thumb { display: grid; place-items: center; width: 60px; height: 60px; border-radius: calc(var(--radius) * .7); background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-basecamp"] .bcp-row-thumb img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-basecamp"] .bcp-row-thumb.dt-gen b { font-size: 1.4rem; }
[data-theme-layout="dtc-basecamp"] .bcp-row-main { display: flex; flex-direction: column; gap: .3rem; min-width: 0; }
[data-theme-layout="dtc-basecamp"] .bcp-row-name { font-size: .98rem; font-weight: 650; line-height: 1.4; }
[data-theme-layout="dtc-basecamp"] .bcp-row:hover .bcp-row-name { color: var(--accent); }
[data-theme-layout="dtc-basecamp"] .bcp-row-chips { margin-top: 0; }
[data-theme-layout="dtc-basecamp"] .bcp-row-load { justify-self: end; display: flex; flex-direction: column; align-items: flex-end; gap: .15rem; max-width: 11rem; text-align: right; }
[data-theme-layout="dtc-basecamp"] .bcp-row-load b { font-size: .62rem; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }
[data-theme-layout="dtc-basecamp"] .bcp-row-load i { max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-style: normal; font-family: var(--mono); font-size: .88rem; font-weight: 600; color: var(--accent); }

/* ---- 营地数字行（dt-stats 重排：去卡面，左缘军绿刻线，mono 数字） ---- */
[data-theme-layout="dtc-basecamp"] .bcp-stats .dt-stat { padding: .4rem 0 .4rem 1.05rem; border: 0; border-left: 3px solid var(--accent); border-radius: 0; background: transparent; text-align: left; }
[data-theme-layout="dtc-basecamp"] .bcp-stats .dt-stat dt { font-family: var(--mono); letter-spacing: -.02em; }
/* 营地实拍横带（factory_gallery 复用）：加发丝框收整 */
[data-theme-layout="dtc-basecamp"] .f-gallery-item { border: 1px solid var(--line); }

/* ---- 内页 · 商品列表（generic_list 的 DOM）：清单行同构 ---- */
[data-theme-layout="dtc-basecamp"] .page-head { border-bottom: 0; padding: 2.4rem 0 .9rem; }
[data-theme-layout="dtc-basecamp"] .page-head h1 { font-family: var(--dt-display, var(--sans)); font-weight: 750; letter-spacing: -.015em; }
[data-theme-layout="dtc-basecamp"] .page-head h1::after { content: ""; display: block; width: 96px; height: 4px; margin-top: .7rem; background: repeating-linear-gradient(90deg, var(--accent) 0 12px, transparent 12px 20px); }
[data-theme-layout="dtc-basecamp"] .cat-nav { gap: .6rem; }
[data-theme-layout="dtc-basecamp"] .cat-nav a { border: 0; border-radius: 3px 0 0 3px; padding: .45rem 1.5rem .45rem 1rem; background: var(--accent-wash); color: var(--ink-soft); font-weight: 650; clip-path: polygon(0 0, 90% 0, 100% 50%, 90% 100%, 0 100%); }
[data-theme-layout="dtc-basecamp"] .cat-nav a:hover { background: var(--accent); color: var(--bcp-on-accent); }
[data-theme-layout="dtc-basecamp"] .cat-nav a:hover .muted { color: inherit; }
[data-theme-layout="dtc-basecamp"] .cat-nav a .muted { color: var(--accent); font-family: var(--mono); }
[data-theme-layout="dtc-basecamp"] .cat-nav a.active { background: var(--accent); color: var(--bcp-on-accent); }
[data-theme-layout="dtc-basecamp"] .cat-nav a.active .muted { color: inherit; opacity: 1; }
[data-theme-layout="dtc-basecamp"] .link-grid { display: block; counter-reset: bcplist; margin: 1.6rem 0; border: 1px solid var(--line); border-radius: calc(var(--radius) * 1.2); background: var(--surface); overflow: hidden; }
[data-theme-layout="dtc-basecamp"] .link-card { display: grid; grid-template-columns: 2rem 64px minmax(0, 1fr); gap: 1rem; align-items: center; padding: .85rem 1.15rem; border: 0; border-radius: 0; background: transparent; transition: background var(--speed); }
[data-theme-layout="dtc-basecamp"] .link-card::before { counter-increment: bcplist; content: counter(bcplist, decimal-leading-zero); font-family: var(--mono); font-size: .74rem; color: var(--faint); }
[data-theme-layout="dtc-basecamp"] .link-card + .link-card { border-top: 1px solid var(--line-soft); }
[data-theme-layout="dtc-basecamp"] .link-card:hover { border-color: transparent; box-shadow: none; transform: none; background: color-mix(in srgb, var(--accent) 7%, var(--surface)); }
[data-theme-layout="dtc-basecamp"] .lc-cover { width: 64px; height: 64px; aspect-ratio: auto; border-radius: calc(var(--radius) * .7); }
[data-theme-layout="dtc-basecamp"] .lc-mono { font-size: 1.4rem; }
[data-theme-layout="dtc-basecamp"] .lc-body { padding: 0; gap: .28rem; }
[data-theme-layout="dtc-basecamp"] .lc-title { font-size: .98rem; font-weight: 650; }
[data-theme-layout="dtc-basecamp"] .lc-arrow { opacity: 1; transform: none; color: var(--faint); font-family: var(--mono); }
[data-theme-layout="dtc-basecamp"] .link-card:hover .lc-arrow { color: var(--accent); }
[data-theme-layout="dtc-basecamp"] .lc-intro { flex: none; display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 1; font-size: .85rem; color: var(--muted); }
[data-theme-layout="dtc-basecamp"] .lc-foot .tag { display: inline-block; max-width: 100%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; padding: .18rem .68rem; border: 1px solid var(--line); border-radius: 999px; background: var(--bg); font-size: .72rem; color: var(--ink-soft); }
[data-theme-layout="dtc-basecamp"] .pagination a, [data-theme-layout="dtc-basecamp"] .pagination span { border-radius: 6px; }

/* ---- 内页 · 商品详情（product_detail 的 DOM）：参数表 + 场景实拍横带 ---- */
[data-theme-layout="dtc-basecamp"] .pd-bc { padding-bottom: 1.1rem; }
[data-theme-layout="dtc-basecamp"] .pd-media { border-radius: calc(var(--radius) * 1.2); background: var(--surface); }
/* 场景实拍横带：缩略图收成 64px 方格一横排，溢出横滚（图集未配置整排不出现） */
[data-theme-layout="dtc-basecamp"] .pd-thumbs { display: flex; flex-wrap: nowrap; gap: .55rem; overflow-x: auto; padding-bottom: .3rem; scrollbar-width: thin; }
[data-theme-layout="dtc-basecamp"] .pd-thumb { flex: none; width: 64px; border-radius: calc(var(--radius) * .7); }
[data-theme-layout="dtc-basecamp"] .pd-kicker a { color: var(--accent); }
[data-theme-layout="dtc-basecamp"] .pd-title { font-family: var(--dt-display, var(--sans)); font-weight: 750; letter-spacing: -.015em; }
[data-theme-layout="dtc-basecamp"] .pd-lead { color: var(--ink-soft); }
/* 快速参数（pd-meta）：装备铭牌化——顶头军绿粗线，dt 走 mono 大写 */
[data-theme-layout="dtc-basecamp"] .pd-meta { border-top: 2px solid var(--accent); }
[data-theme-layout="dtc-basecamp"] .pd-meta-row dt { font-family: var(--mono); font-size: .78rem; letter-spacing: .08em; text-transform: uppercase; }
/* 询盘=营地告示牌：白卡 1px 框 + 顶部军绿箭头短横（路标母题回声） */
[data-theme-layout="dtc-basecamp"] .pd-inquiry { padding: 1.5rem 1.4rem 1.4rem; border: 1px solid var(--line); border-radius: calc(var(--radius) * 1.2); background: var(--surface); }
[data-theme-layout="dtc-basecamp"] .pd-inquiry::before { content: ""; display: block; width: min(160px, 46%); height: 10px; margin-bottom: 1rem; background: var(--accent); clip-path: polygon(0 0, 93% 0, 100% 50%, 93% 100%, 0 100%); }
[data-theme-layout="dtc-basecamp"] .pd-sec-title { font-family: var(--dt-display, var(--sans)); font-weight: 750; }
[data-theme-layout="dtc-basecamp"] .pd-specs .pd-sec-title::after, [data-theme-layout="dtc-basecamp"] .pd-related .pd-sec-title::after { content: ""; display: block; width: 64px; height: 4px; margin-top: .5rem; background: repeating-linear-gradient(90deg, var(--accent) 0 10px, transparent 10px 18px); }
/* 参数表：th 走 mono 大写 + 军绿微染底 */
[data-theme-layout="dtc-basecamp"] .pd-specs-tablewrap { border-radius: calc(var(--radius) * 1.2); }
[data-theme-layout="dtc-basecamp"] .pd-specs-table th { font-family: var(--mono); font-size: .78rem; letter-spacing: .06em; text-transform: uppercase; color: var(--ink-soft); background: color-mix(in srgb, var(--accent) 8%, var(--surface)); }
[data-theme-layout="dtc-basecamp"] .pd-rel-card { border-radius: calc(var(--radius) * 1.2); }
[data-theme-layout="dtc-basecamp"] .pd-rel-title { font-weight: 650; }

/* ---- 响应式：920 hero 单列 / 720 清单行收两列，重量列归位名称下方普通流 ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-basecamp"] .bcp-hero-inner { grid-template-columns: 1fr; padding: clamp(1.6rem, 5vw, 2.6rem); }
  [data-theme-layout="dtc-basecamp"] .bcp-hero-side { max-width: 420px; }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-basecamp"] .bcp-row { grid-template-columns: 48px minmax(0, 1fr); padding: .75rem .9rem; }
  [data-theme-layout="dtc-basecamp"] .bcp-row::before { display: none; }
  [data-theme-layout="dtc-basecamp"] .bcp-row-thumb { width: 48px; height: 48px; }
  [data-theme-layout="dtc-basecamp"] .bcp-row-load { grid-column: 2; justify-self: start; flex-direction: row; align-items: baseline; gap: .45rem; max-width: 100%; text-align: left; }
  [data-theme-layout="dtc-basecamp"] .link-card { grid-template-columns: 48px minmax(0, 1fr); padding: .75rem .9rem; }
  [data-theme-layout="dtc-basecamp"] .link-card::before { display: none; }
  [data-theme-layout="dtc-basecamp"] .lc-cover { width: 48px; height: 48px; }
  [data-theme-layout="dtc-basecamp"] .bcp-hero.has-img { min-height: 58vh; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-basecamp"] .bcp-row, [data-theme-layout="dtc-basecamp"] .bcp-route,
  [data-theme-layout="dtc-basecamp"] .link-card,
  [data-theme-layout="dtc-basecamp"] .site-header .nav > a:not(.search-ico) { transition: none; }
}

/* ============================================================
   皮肤 ×3（变量成套覆写；正文≥7、次要/accent≥4.5，hover 只升不降，实算见提交说明）
   ============================================================ */
/* ---- 营地 · Basecamp（原生）：苔白 #eef0e8 + 军绿 #4a5c38 + 深林墨 #25301f ----
   ink/bg 12.01, ink-soft/bg 8.10, muted/bg 5.28(/wash 4.73), accent/bg 6.34
   (hover soft 8.69↑), 白字/军绿木牌 7.29(hover 深牌 9.82↑), 按钮 surface/ink 13.05 */
:root[data-theme="basecamp"] {
  --bg: #eef0e8; --surface: #f8f9f4; --ink: #25301f; --ink-soft: #3e4b31;
  --muted: #5b6650; --faint: #7b8470; --line: #ccd3bf; --line-soft: #dfe4d4;
  --accent: #4a5c38; --accent-soft: #38472a; --accent-wash: #dfe6d0;
  --radius: 10px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(37,48,31,.06), 0 10px 26px rgba(37,48,31,.09);
  --bcp-sign: #4a5c38; --bcp-sign-ink: #ffffff; --bcp-sign-hover: #3a4829;
  --bcp-on-accent: #ffffff; --bcp-contour: rgba(37,48,31,.08);
}

/* ---- 营地 · Basecamp Noir（反差暗皮）：夜营深绿底 + 月白 + 浅军绿 ----
   ink/bg 15.26, ink-soft/bg 11.69, muted/bg 7.68(/wash 5.83), accent/bg 8.91
   (hover soft 10.82↑), 月白字/木牌 8.44(hover 深牌 11.00↑), 按钮 surface/ink 13.56;
   浅军绿 accent 当底时字换夜绿 #151c10（8.91），绝不放白字 */
:root[data-theme="basecamp-noir"] {
  --bg: #151c10; --surface: #1e2716; --ink: #edf2e2; --ink-soft: #ccd8b9;
  --muted: #a4b18e; --faint: #79856a; --line: #35402a; --line-soft: #2a3320;
  --accent: #a9c284; --accent-soft: #bdd49a; --accent-wash: #2a331c;
  --radius: 10px; --w-wide: 1200px; --code-bg: #0d130a; --shadow: 0 1px 2px rgba(0,0,0,.45), 0 12px 30px rgba(0,0,0,.5);
  --bcp-sign: #3c4c26; --bcp-sign-ink: #f2f5e9; --bcp-sign-hover: #2c3a1b;
  --bcp-on-accent: #151c10; --bcp-contour: rgba(237,242,226,.05);
}
/* 浅军绿当底的两处基础样式：分页当前页、无图首字块——白字换夜绿深字 */
:root[data-theme="basecamp-noir"] .pagination .cur { color: #151c10; }
:root[data-theme="basecamp-noir"] .lc-mono { color: #151c10; }

/* ---- 营地 · Basecamp White（纯白皮）：中性灰基底对齐纯白系，军绿压深到 #42552f ----
   ink/bg 18.72, accent/bg 8.16(hover soft 10.83↑), 白字/军绿木牌 8.16(hover 10.83↑);
   muted 压深为 #6a707a——#707680 在 #fafaf8 上只有 4.38，压深后 4.77/4.99，
   wash 提亮到 #f2f5ee 保 muted/wash 4.53；等高线底纹整层隐去（--bcp-contour: transparent） */
:root[data-theme="basecamp-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #6a707a; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #42552f; --accent-soft: #33421f; --accent-wash: #f2f5ee;
  --radius: 10px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(16,18,24,.05), 0 10px 26px rgba(16,18,24,.07);
  --bcp-sign: #42552f; --bcp-sign-ink: #ffffff; --bcp-sign-hover: #33421f;
  --bcp-on-accent: #ffffff; --bcp-contour: transparent;
}

/* =========================================================================
   LAYOUT: dtc-toybox — 玩具盒：玩具/母婴品牌独立站（every selector scoped under
   [data-theme-layout="dtc-toybox"]，classes tbx-*）。
   页头 CSS 重塑为彩色积木块导航（圆角 12px 粗体白字块，nth-child 四色轮换；
   四色全部从设计稿原色压深到白字 ≥4.5，见皮肤注释），页头底缘四色积木条；
   home：开盖 hero（盒盖=四色积木条 ::before，绝对定位有专属车道、720px 归位
   普通流）+ 分类积木条 + 玩具格三列（白卡 3px 墨描边 + 右上 -8px 悬出 8deg
   贴纸徽章，红底白字白描边；网格 padding 预留车道防裁切、720px 收回卡内）。
   共用 dt-*（前缀 ^dtc- 规则自动命中）；三皮 toybox / toybox-noir / toybox-white。
   ========================================================================= */
/* ---- 页头 · 积木块导航（≤620px 交还基础汉堡抽屉，重塑段全包 min-width:621px） ---- */
[data-theme-layout="dtc-toybox"] .site-header { background: var(--bg); }
[data-theme-layout="dtc-toybox"] .site-header::after { content: ""; display: block; height: 4px; background: repeating-linear-gradient(90deg, var(--tbx-blk1) 0 44px, var(--tbx-blk2) 44px 88px, var(--tbx-blk3) 88px 132px, var(--tbx-blk4) 132px 176px); }
@media (min-width: 621px) {
  [data-theme-layout="dtc-toybox"] .nav a[aria-current="page"]::after { display: none; } /* 底线指示让位积木块内圈；≤620px 抽屉保留基础指示 */
  [data-theme-layout="dtc-toybox"] .site-header .wrap { height: 72px; gap: 1rem; }
  [data-theme-layout="dtc-toybox"] .nav { gap: .5rem; flex-wrap: wrap; }
  [data-theme-layout="dtc-toybox"] .nav > a:not(.search-ico) { min-width: 0; padding: .46rem 1.05rem; border-radius: 12px; background: var(--tbx-blk1); color: var(--tbx-blk-ink); font-size: .9rem; font-weight: 750; transition: box-shadow var(--speed), transform var(--speed); }
  [data-theme-layout="dtc-toybox"] .nav > a:not(.search-ico):nth-child(4n+2) { background: var(--tbx-blk2); }
  [data-theme-layout="dtc-toybox"] .nav > a:not(.search-ico):nth-child(4n+3) { background: var(--tbx-blk3); }
  [data-theme-layout="dtc-toybox"] .nav > a:not(.search-ico):nth-child(4n) { background: var(--tbx-blk4); }
  [data-theme-layout="dtc-toybox"] .nav > a:not(.search-ico):hover,
  [data-theme-layout="dtc-toybox"] .nav > a:not(.search-ico):focus-visible { color: var(--tbx-blk-ink); transform: translateY(-2px); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ink) 30%, transparent); outline: none; }
  [data-theme-layout="dtc-toybox"] .nav > a[aria-current="page"] { color: var(--tbx-blk-ink); box-shadow: inset 0 0 0 2px var(--tbx-blk-ink); }
}

/* ---- home 容器 + 开盖 hero（三态：image 全幅 scrim / svg / 轻动画） ---- */
[data-theme-layout="dtc-toybox"] .tbx-wrap { width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: 0 0 1rem; }
[data-theme-layout="dtc-toybox"] .tbx-hero { position: relative; margin-top: 2.1rem; border: 3px solid var(--tbx-edge); border-radius: 20px; background: linear-gradient(150deg, var(--accent-wash), var(--surface)); }
/* 盒盖：微倾四色积木条（装饰专属车道=hero 上方 margin 2.1rem > 盖高+悬出；720px 归位普通流） */
[data-theme-layout="dtc-toybox"] .tbx-hero::before { content: ""; position: absolute; top: -14px; left: 22px; width: min(42%, 280px); height: 20px; border: 3px solid var(--tbx-edge); border-radius: 9px; background: repeating-linear-gradient(90deg, var(--tbx-blk1) 0 44px, var(--tbx-blk2) 44px 88px, var(--tbx-blk3) 88px 132px, var(--tbx-blk4) 132px 176px); transform: rotate(-2deg); }
[data-theme-layout="dtc-toybox"] .tbx-hero-inner { position: relative; z-index: 1; display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(280px, .95fr); align-items: center; gap: clamp(1.2rem, 3vw, 2.6rem); padding: clamp(2.2rem, 5vw, 4rem); }
[data-theme-layout="dtc-toybox"] .tbx-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-toybox"] .tbx-hero.has-img { min-height: min(70vh, 540px); display: flex; align-items: flex-end; overflow: hidden; }
[data-theme-layout="dtc-toybox"] .tbx-hero.has-img::before { display: none; }
[data-theme-layout="dtc-toybox"] .tbx-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(102deg, rgba(12,10,8,.68) 0%, rgba(12,10,8,.42) 48%, rgba(12,10,8,.06) 76%), linear-gradient(200deg, rgba(12,10,8,0) 40%, rgba(12,10,8,.52) 96%); }
[data-theme-layout="dtc-toybox"] .tbx-hero.has-img .tbx-hero-inner { grid-template-columns: minmax(0, 1fr); }
[data-theme-layout="dtc-toybox"] .tbx-hero.has-img .tbx-hero-copy, [data-theme-layout="dtc-toybox"] .tbx-hero.has-img .tbx-h1 { color: #fff; }
[data-theme-layout="dtc-toybox"] .tbx-hero.has-img .dt-eyebrow { color: #fff; opacity: .85; }
[data-theme-layout="dtc-toybox"] .tbx-hero.has-img .tbx-lede { color: rgba(255,255,255,.88); }
[data-theme-layout="dtc-toybox"] .tbx-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-toybox"] .tbx-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-toybox"] .tbx-hero.has-img .btn-primary { background: #fff; border-color: #fff; color: #191410; }
/* 开盖词：粗黑圆体感——重磅 sans + 微负字距 */
[data-theme-layout="dtc-toybox"] .tbx-h1 { margin: 0; max-width: 14em; color: var(--ink); font-family: var(--sans); font-size: clamp(2.1rem, 4.6vw, 3.4rem); font-weight: 800; line-height: 1.1; letter-spacing: -.02em; }
/* 描述钳高 4 行——装饰位不许把开盖首屏撑成长文；hero 渐变起点是 wash，用 ink-soft 保 ≥4.5 */
[data-theme-layout="dtc-toybox"] .tbx-lede { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 4; max-width: 56ch; margin: 1rem 0 0; color: var(--ink-soft); font-size: 1.02rem; line-height: 1.8; }
[data-theme-layout="dtc-toybox"] .tbx-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.8rem; }
[data-theme-layout="dtc-toybox"] .btn, [data-theme-layout="dtc-toybox"] .inquiry-btn { border-radius: 12px; font-weight: 700; }
[data-theme-layout="dtc-toybox"] .tbx-hero-side { min-width: 0; }
[data-theme-layout="dtc-toybox"] .dt-head h2 { font-weight: 800; letter-spacing: -.02em; }

/* ---- 分类积木条（Categories）：四色轮换收纳格 ---- */
[data-theme-layout="dtc-toybox"] .tbx-bins { display: flex; flex-wrap: wrap; gap: .6rem; margin-top: 1.2rem; }
[data-theme-layout="dtc-toybox"] .tbx-bin { display: inline-flex; align-items: baseline; gap: .5rem; min-width: 0; padding: .52rem 1.05rem; border-radius: 12px; background: var(--tbx-blk1); color: var(--tbx-blk-ink); font-size: .9rem; font-weight: 750; transition: box-shadow var(--speed), transform var(--speed); }
[data-theme-layout="dtc-toybox"] .tbx-bin:nth-child(4n+2) { background: var(--tbx-blk2); }
[data-theme-layout="dtc-toybox"] .tbx-bin:nth-child(4n+3) { background: var(--tbx-blk3); }
[data-theme-layout="dtc-toybox"] .tbx-bin:nth-child(4n) { background: var(--tbx-blk4); }
[data-theme-layout="dtc-toybox"] .tbx-bin:hover, [data-theme-layout="dtc-toybox"] .tbx-bin:focus-visible { color: var(--tbx-blk-ink); transform: translateY(-2px); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ink) 30%, transparent); outline: none; }
[data-theme-layout="dtc-toybox"] .tbx-bin-name { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; max-width: 16ch; }
[data-theme-layout="dtc-toybox"] .tbx-bin-n { font-size: .74rem; font-weight: 700; }

/* ---- 玩具格三列：白卡 3px 墨描边 + 右上悬出贴纸徽章（车道=网格 padding） ---- */
[data-theme-layout="dtc-toybox"] .tbx-section { padding-top: clamp(3rem, 6vw, 4.5rem); }
[data-theme-layout="dtc-toybox"] .tbx-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.2rem; padding-top: 14px; } /* 14px 车道：首行贴纸 -8px 悬出不撞区块头 */
[data-theme-layout="dtc-toybox"] .tbx-card { position: relative; display: flex; flex-direction: column; min-width: 0; border: 3px solid var(--tbx-edge); border-radius: 16px; background: var(--surface); color: var(--ink); overflow: visible; transition: transform var(--speed), box-shadow var(--speed); }
[data-theme-layout="dtc-toybox"] .tbx-card:hover { transform: translateY(-3px); box-shadow: var(--shadow); color: var(--ink); }
[data-theme-layout="dtc-toybox"] .tbx-sticker { position: absolute; top: -8px; right: -8px; z-index: 1; display: grid; place-items: center; width: 74px; height: 74px; padding: 9px; border: 2px solid #fff; border-radius: 50%; background: var(--tbx-badge); color: var(--tbx-badge-ink); font-size: .68rem; font-weight: 750; line-height: 1.3; text-align: center; transform: rotate(8deg); box-shadow: 0 3px 10px color-mix(in srgb, var(--ink) 22%, transparent); }
[data-theme-layout="dtc-toybox"] .tbx-sticker { overflow: hidden; } /* 贴纸长文钳形：圆面内两行截断 */
[data-theme-layout="dtc-toybox"] .tbx-card-media { display: grid; place-items: center; aspect-ratio: 1 / 1; border-radius: 13px 13px 0 0; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-toybox"] .tbx-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s ease; }
[data-theme-layout="dtc-toybox"] .tbx-card:hover .tbx-card-media img { transform: scale(1.04); }
[data-theme-layout="dtc-toybox"] .tbx-card-body { display: flex; flex-direction: column; gap: .3rem; padding: .85rem .95rem 1rem; border-top: 3px solid var(--tbx-edge); }
[data-theme-layout="dtc-toybox"] .tbx-card-title { font-size: 1rem; font-weight: 750; line-height: 1.45; }
[data-theme-layout="dtc-toybox"] .tbx-card:hover .tbx-card-title { color: var(--accent); }

/* ---- 品牌数字（FactoryStats）：积木顶边色卡（四色轮换 8px 顶梁） ---- */
[data-theme-layout="dtc-toybox"] .tbx-figures .dt-stat { border: 3px solid var(--tbx-edge); border-top: 8px solid var(--tbx-blk1); border-radius: 16px; }
[data-theme-layout="dtc-toybox"] .tbx-figures .dt-stat:nth-child(4n+2) { border-top-color: var(--tbx-blk2); }
[data-theme-layout="dtc-toybox"] .tbx-figures .dt-stat:nth-child(4n+3) { border-top-color: var(--tbx-blk3); }
[data-theme-layout="dtc-toybox"] .tbx-figures .dt-stat:nth-child(4n) { border-top-color: var(--tbx-blk4); }
[data-theme-layout="dtc-toybox"] .tbx-figures .dt-stat dt { font-family: var(--sans); font-weight: 800; letter-spacing: -.02em; }

/* ---- 联系 CTA（dtc_cta 复用）：墨描边大盒 + 居中四色积木条（普通流装饰） ---- */
[data-theme-layout="dtc-toybox"] .dt-cta-inner { position: relative; border: 3px solid var(--tbx-edge); border-radius: 20px; background: var(--surface); }
[data-theme-layout="dtc-toybox"] .dt-cta-inner::before { content: ""; display: block; width: 132px; height: 10px; margin: 0 auto 1.2rem; border-radius: 6px; background: repeating-linear-gradient(90deg, var(--tbx-blk1) 0 33px, var(--tbx-blk2) 33px 66px, var(--tbx-blk3) 66px 99px, var(--tbx-blk4) 99px 132px); }
[data-theme-layout="dtc-toybox"] .dt-cta h2 { font-family: var(--sans); font-weight: 800; letter-spacing: -.02em; }

/* ---- 内页 · 商品/内容列表（generic_list DOM）：玩具格跟随母题 ---- */
[data-theme-layout="dtc-toybox"] .page-head { padding: 2.6rem 0 2.1rem; }
[data-theme-layout="dtc-toybox"] .page-head h1 { font-family: var(--sans); font-weight: 800; letter-spacing: -.02em; }
[data-theme-layout="dtc-toybox"] .page-head h1::after { content: ""; display: block; width: 96px; height: 10px; margin-top: .75rem; border-radius: 6px; background: repeating-linear-gradient(90deg, var(--tbx-blk1) 0 24px, var(--tbx-blk2) 24px 48px, var(--tbx-blk3) 48px 72px, var(--tbx-blk4) 72px 96px); }
/* 分类条＝积木块（同 home 收纳格语言；active＝块内白圈） */
[data-theme-layout="dtc-toybox"] .cat-nav { gap: .6rem; margin: 1.6rem 0; }
[data-theme-layout="dtc-toybox"] .cat-nav a { border: 0; border-radius: 12px; padding: .5rem 1.05rem; background: var(--tbx-blk1); color: var(--tbx-blk-ink); font-weight: 750; transition: box-shadow var(--speed), transform var(--speed); }
[data-theme-layout="dtc-toybox"] .cat-nav a:nth-child(4n+2) { background: var(--tbx-blk2); }
[data-theme-layout="dtc-toybox"] .cat-nav a:nth-child(4n+3) { background: var(--tbx-blk3); }
[data-theme-layout="dtc-toybox"] .cat-nav a:nth-child(4n) { background: var(--tbx-blk4); }
[data-theme-layout="dtc-toybox"] .cat-nav a:hover { color: var(--tbx-blk-ink); transform: translateY(-2px); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ink) 30%, transparent); }
[data-theme-layout="dtc-toybox"] .cat-nav a.active { color: var(--tbx-blk-ink); box-shadow: inset 0 0 0 2px var(--tbx-blk-ink); }
[data-theme-layout="dtc-toybox"] .cat-nav a .muted { color: currentColor; opacity: .82; }
/* 列表卡＝玩具格：3px 墨描边圆角白卡；卡脚分类标=迷你贴纸 */
[data-theme-layout="dtc-toybox"] .link-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.2rem; margin: 1.8rem 0 2.2rem; }
[data-theme-layout="dtc-toybox"] .link-card { border: 3px solid var(--tbx-edge); border-radius: 16px; background: var(--surface); overflow: hidden; transition: transform var(--speed), box-shadow var(--speed); }
[data-theme-layout="dtc-toybox"] .link-card:hover { transform: translateY(-3px); box-shadow: var(--shadow); border-color: var(--tbx-edge); }
[data-theme-layout="dtc-toybox"] .lc-cover { aspect-ratio: 4 / 3; border-bottom: 3px solid var(--tbx-edge); background: var(--line-soft); }
[data-theme-layout="dtc-toybox"] .lc-mono { background: var(--accent-wash); color: var(--accent); font-family: var(--sans); font-weight: 800; }
[data-theme-layout="dtc-toybox"] .lc-title { font-size: 1.02rem; font-weight: 750; }
[data-theme-layout="dtc-toybox"] .lc-arrow { color: var(--accent); }
[data-theme-layout="dtc-toybox"] .lc-intro { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; color: var(--muted); }
[data-theme-layout="dtc-toybox"] .lc-foot .tag { border: 2px solid #fff; border-radius: 999px; background: var(--tbx-badge); color: var(--tbx-badge-ink); font-weight: 750; box-shadow: 0 1px 4px color-mix(in srgb, var(--ink) 20%, transparent); }
[data-theme-layout="dtc-toybox"] .link-grid > .muted { grid-column: 1 / -1; margin: 0; padding: 1.8rem; border: 3px dashed var(--line); border-radius: 16px; text-align: center; }
[data-theme-layout="dtc-toybox"] .pagination a, [data-theme-layout="dtc-toybox"] .pagination .cur { border-radius: 10px; }
[data-theme-layout="dtc-toybox"] .pagination .cur { background: var(--ink); border-color: var(--ink); color: var(--surface); }
[data-theme-layout="dtc-toybox"] .pagination a:hover { border-color: var(--accent); color: var(--accent); }

/* ---- 内页 · 商品详情（product_detail DOM）：年龄段/玩法卡——specs 拆彩边小卡 ---- */
[data-theme-layout="dtc-toybox"] .pd-title { font-family: var(--sans); font-weight: 800; letter-spacing: -.02em; }
[data-theme-layout="dtc-toybox"] .pd-kicker a { display: inline-block; padding: .22rem .8rem; border-radius: 10px; background: var(--tbx-blk2); color: var(--tbx-blk-ink); font-weight: 750; }
[data-theme-layout="dtc-toybox"] .pd-kicker a:hover { color: var(--tbx-blk-ink); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ink) 30%, transparent); }
[data-theme-layout="dtc-toybox"] .pd-media { border: 3px solid var(--tbx-edge); border-radius: 16px; background: var(--surface); overflow: hidden; }
[data-theme-layout="dtc-toybox"] .pd-media-gen { background: var(--accent-wash); }
[data-theme-layout="dtc-toybox"] .pd-media-gen b { color: var(--accent); font-family: var(--sans); font-weight: 800; }
[data-theme-layout="dtc-toybox"] .pd-thumb { border-radius: 10px; }
[data-theme-layout="dtc-toybox"] .pd-thumb:hover { border-color: var(--accent-soft); }
[data-theme-layout="dtc-toybox"] .pd-thumb.is-active { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
/* 单值字段（pd-meta）＝彩边小卡：竖排键值 + 四色左梁轮换 */
[data-theme-layout="dtc-toybox"] .pd-meta { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(180px, 100%), 1fr)); gap: .7rem; border: 0; }
[data-theme-layout="dtc-toybox"] .pd-meta-row { display: flex; flex-direction: column; gap: .18rem; margin: 0; padding: .72rem .9rem; border: 2px solid var(--line); border-left: 6px solid var(--tbx-blk1); border-radius: 12px; background: var(--surface); }
[data-theme-layout="dtc-toybox"] .pd-meta-row:nth-child(4n+2) { border-left-color: var(--tbx-blk2); }
[data-theme-layout="dtc-toybox"] .pd-meta-row:nth-child(4n+3) { border-left-color: var(--tbx-blk3); }
[data-theme-layout="dtc-toybox"] .pd-meta-row:nth-child(4n) { border-left-color: var(--tbx-blk4); }
[data-theme-layout="dtc-toybox"] .pd-meta-row dt { margin: 0; color: var(--muted); font-size: .74rem; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; }
[data-theme-layout="dtc-toybox"] .pd-meta-row dd { margin: 0; color: var(--ink); font-weight: 700; }
/* 规格表（pd-specs）＝年龄段/玩法卡墙：表行拆成四色顶梁小卡 */
[data-theme-layout="dtc-toybox"] .pd-sec-title { font-family: var(--sans); font-weight: 800; letter-spacing: -.02em; }
[data-theme-layout="dtc-toybox"] .pd-specs-table { display: block; border: 0; }
[data-theme-layout="dtc-toybox"] .pd-specs-table tbody { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(200px, 100%), 1fr)); gap: .8rem; }
[data-theme-layout="dtc-toybox"] .pd-specs-table tr { display: flex; flex-direction: column; gap: .2rem; padding: .85rem 1rem; border: 2px solid var(--line); border-top: 6px solid var(--tbx-blk1); border-radius: 12px; background: var(--surface); }
[data-theme-layout="dtc-toybox"] .pd-specs-table tr:nth-child(4n+2) { border-top-color: var(--tbx-blk2); }
[data-theme-layout="dtc-toybox"] .pd-specs-table tr:nth-child(4n+3) { border-top-color: var(--tbx-blk3); }
[data-theme-layout="dtc-toybox"] .pd-specs-table tr:nth-child(4n) { border-top-color: var(--tbx-blk4); }
[data-theme-layout="dtc-toybox"] .pd-specs-table th, [data-theme-layout="dtc-toybox"] .pd-specs-table td { display: block; padding: 0; border: 0; background: transparent; text-align: left; }
[data-theme-layout="dtc-toybox"] .pd-specs-table th { color: var(--muted); font-size: .74rem; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; }
[data-theme-layout="dtc-toybox"] .pd-specs-table td { color: var(--ink); font-weight: 700; }
/* 询盘卡：墨描边盒（surface 底，muted 文案不压 wash——纯白皮 muted/wash 只有 4.06） */
[data-theme-layout="dtc-toybox"] .pd-inquiry { border: 3px solid var(--tbx-edge); border-radius: 16px; background: var(--surface); }
[data-theme-layout="dtc-toybox"] .pd-inquiry .inquiry-title { font-family: var(--sans); font-weight: 800; }
/* 相关商品＝迷你玩具格 */
[data-theme-layout="dtc-toybox"] .pd-rel-card { border: 3px solid var(--tbx-edge); border-radius: 14px; background: var(--surface); overflow: hidden; }
[data-theme-layout="dtc-toybox"] .pd-rel-media { border-bottom: 3px solid var(--tbx-edge); }
[data-theme-layout="dtc-toybox"] .pd-rel-gen { background: var(--accent-wash); }
[data-theme-layout="dtc-toybox"] .pd-rel-gen b { color: var(--accent); }
[data-theme-layout="dtc-toybox"] .pd-rel-title { padding: .6rem .8rem .8rem; font-weight: 750; }
[data-theme-layout="dtc-toybox"] .pd-rel-card:hover .pd-rel-title { color: var(--accent); }

/* ---- 响应式（920/720 单列、绝不横溢）+ reduced-motion ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-toybox"] .tbx-hero-inner { grid-template-columns: 1fr; padding: clamp(1.6rem, 5vw, 2.6rem); }
  [data-theme-layout="dtc-toybox"] .tbx-hero-side { max-width: 420px; }
  [data-theme-layout="dtc-toybox"] .tbx-grid, [data-theme-layout="dtc-toybox"] .link-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-toybox"] .tbx-grid, [data-theme-layout="dtc-toybox"] .link-grid { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-toybox"] .tbx-grid { padding-top: 0; } /* 贴纸收回卡内，车道退场 */
  [data-theme-layout="dtc-toybox"] .tbx-sticker { top: 8px; right: 8px; }
  [data-theme-layout="dtc-toybox"] .tbx-hero { margin-top: 1.4rem; }
  [data-theme-layout="dtc-toybox"] .tbx-hero::before { position: static; display: block; width: 120px; margin: 1.1rem 0 -1rem 1.2rem; transform: none; } /* 盒盖归位普通流 */
  [data-theme-layout="dtc-toybox"] .tbx-hero.has-img { min-height: 60vh; }
  [data-theme-layout="dtc-toybox"] .tbx-bin-name { max-width: 12ch; }
}
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-toybox"] .nav > a, [data-theme-layout="dtc-toybox"] .tbx-bin,
  [data-theme-layout="dtc-toybox"] .cat-nav a, [data-theme-layout="dtc-toybox"] .tbx-card,
  [data-theme-layout="dtc-toybox"] .link-card, [data-theme-layout="dtc-toybox"] .tbx-card-media img { transition: none; }
  [data-theme-layout="dtc-toybox"] .nav > a:not(.search-ico):hover, [data-theme-layout="dtc-toybox"] .tbx-bin:hover,
  [data-theme-layout="dtc-toybox"] .cat-nav a:hover, [data-theme-layout="dtc-toybox"] .tbx-card:hover,
  [data-theme-layout="dtc-toybox"] .link-card:hover { transform: none; }
  [data-theme-layout="dtc-toybox"] .tbx-card:hover .tbx-card-media img { transform: none; }
}

/* ============================================================
   dtc-toybox 皮肤 ×3：toybox 奶油原生 / toybox-noir 夜游深底反差 /
   toybox-white 纯白。全部变量成套覆写；--tbx-blk1..4 积木四色 +
   --tbx-blk-ink 块上字 + --tbx-badge 贴纸 + --tbx-edge 墨描边各配。
   实算 WCAG 见各皮注释（正文≥7、次要/accent≥4.5、hover 只升不降）。
   ============================================================ */
/* ---- 玩具盒 · Toybox（原生）：奶油 #fdf7ec + 墨棕 #33271c + 压深积木四色。
   设计稿四色与白字全部不足 4.5（红 #e05252=3.82 / 蓝 #3d8bd4=3.60 /
   绿 #3fa66a=3.05 / 琥珀 #e8a13d=2.19），逐个压深为红 #cf4444=4.60 /
   蓝 #2f74b3=4.92 / 绿 #2e7d4f=5.05 / 琥珀 #a06a10=4.60。
   实算：ink/bg 13.60、ink/surface 14.51、ink-soft/bg 8.76、/wash 8.11、
   muted/bg 5.25、/surface 5.60、accent/bg 4.97、/surface 5.30、/wash 4.60、
   hover accent-soft/bg 6.50 只升、贴纸白字/红底 4.60、主按钮 14.51。 ---- */
:root[data-theme="toybox"] {
  --bg: #fdf7ec; --surface: #ffffff; --ink: #33271c; --ink-soft: #52443a;
  --muted: #74655a; --faint: #a3937f; --line: #e6dac4; --line-soft: #f4ecdc;
  --accent: #c23a3a; --accent-soft: #a52e2e; --accent-wash: #fbece4;
  --radius: 14px; --w-wide: 1200px; --shadow: 0 2px 4px rgba(51,39,28,.08), 0 12px 28px rgba(51,39,28,.12);
  --dt-display: var(--sans);
  --tbx-blk1: #cf4444; --tbx-blk2: #2f74b3; --tbx-blk3: #2e7d4f; --tbx-blk4: #a06a10;
  --tbx-blk-ink: #ffffff; --tbx-badge: #cf4444; --tbx-badge-ink: #ffffff;
  --tbx-edge: #33271c;
}
/* ---- 夜游 · Toybox Noir（暗反差）：夜游深紫底 + 亮积木四色（块上换深字）。
   暗底上四色同样实算：块字 #191322 于红 #ef6d6d=6.11 / 蓝 #62a8e8=7.16 /
   绿 #58bc82=7.71 / 琥珀 #f0aa4a=9.12；块面/bg 6.37~9.49。
   实算：ink/bg 16.37、ink/surface 15.15、ink-soft/bg 11.65、muted/bg 7.13、
   /surface 6.60、accent/bg 6.37、/surface 5.89、/wash 5.56、
   hover accent-soft/bg 8.41 只升、贴纸白字/红底 4.60（红取原生压深红）、
   主按钮 surface/ink 15.15。 ---- */
:root[data-theme="toybox-noir"] {
  --bg: #120f1d; --surface: #1b1729; --ink: #f1edf7; --ink-soft: #cfc8dc;
  --muted: #a49bb4; --faint: #6f6683; --line: #322b45; --line-soft: #241e35;
  --accent: #ef6d6d; --accent-soft: #f79090; --accent-wash: #2a1a26;
  --radius: 14px; --w-wide: 1200px; --shadow: 0 2px 4px rgba(0,0,0,.4), 0 14px 32px rgba(0,0,0,.46);
  --dt-display: var(--sans);
  --tbx-blk1: #ef6d6d; --tbx-blk2: #62a8e8; --tbx-blk3: #58bc82; --tbx-blk4: #f0aa4a;
  --tbx-blk-ink: #191322; --tbx-badge: #cf4444; --tbx-badge-ink: #ffffff;
  --tbx-edge: #4a4062;
}
/* 夜游：hover 光圈的 ink 是浅紫白，混色圈在暗底同样可见；描边卡与页底同暗，
   浅紫 edge 圈出盒界（非文本 3.4:1）。 */
:root[data-theme="toybox-noir"] .page-head { border-bottom: 1px solid var(--line); }
/* ---- 纯白 · Toybox White：纯白基底（对齐纯白系写法；muted 压深到 #6d737d，
   绕开 #707680 在 #fafaf8 上 4.38 的坑=4.57）；积木四色同原生压深值
   （白字 4.60/4.92/5.05/4.60），accent 红 #c23a3a。
   实算：ink/bg 18.72、ink/surface 17.91、ink-soft/bg 9.79、muted/bg 4.77、
   /surface 4.57、accent/bg 5.30、/surface 5.07、/wash 4.51、
   hover accent-soft/bg 6.93 只升、贴纸白字/红底 4.60、主按钮白字/ink 18.7。 ---- */
:root[data-theme="toybox-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #6d737d; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #c23a3a; --accent-soft: #a52e2e; --accent-wash: #fbe9e2;
  --radius: 12px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(16,18,24,.05), 0 8px 22px rgba(16,18,24,.07);
  --dt-display: var(--sans);
  --tbx-blk1: #cf4444; --tbx-blk2: #2f74b3; --tbx-blk3: #2e7d4f; --tbx-blk4: #a06a10;
  --tbx-blk-ink: #ffffff; --tbx-badge: #cf4444; --tbx-badge-ink: #ffffff;
  --tbx-edge: #101218;
}
:root[data-theme="toybox-white"] .btn-primary { color: #fff; }

/* ==========================================================================
   dtc-paperie 骨架（ppr-*）「手账铺」：文具/手账品牌店——
   背景=低透明网格纸（1px × 22px 方格），主区=白纸容器（1px 细框 + 内衬 18px
   印刷框：框走 ::before 的 padding 车道、容器 padding ≥ 34px 恒大于内衬位，
   绝不压内容；≤720px 内衬框收起）。页头导航 CSS 重塑成索引贴纸页签：
   上圆角 8px 8px 0 0，nth-child 多色轮换（和纸黄/雾蓝/藕紫/豆绿，签字深色同族，
   逐对实算 ≥6.1:1），页签底边坐在页头底缘规线上与主纸区相接不留缝；
   ≤620px 交还基础汉堡抽屉（重塑段全部包在 min-width:621px 里）。
   hero=手账扉页（行距宽），商品=胶带贴角卡（卡顶 ::before 半透明和纸胶带条
   rotate(-2deg) 压顶边——胶带只做装饰绝不承字，承字的页签/眉标全用不透明原色）。
   三皮：paperie（纸白+墨+和纸黄）/ paperie-noir（深夜手账蓝黑底+暖纸色签）/
   paperie-white（纯白，网格纹几乎隐去）。
   ========================================================================== */

/* ---- 页头重塑：索引贴纸页签（只动 CSS；≤620px 基础汉堡抽屉原样接管） ---- */
@media (min-width: 621px) {
  [data-theme-layout="dtc-paperie"] .site-header { position: static; background: transparent; -webkit-backdrop-filter: none; backdrop-filter: none; border-bottom: 1px solid var(--line); }
  [data-theme-layout="dtc-paperie"] .site-header .wrap { height: 64px; align-items: stretch; }
  [data-theme-layout="dtc-paperie"] .brand { align-self: center; font-family: var(--dt-display, var(--serif)); font-size: 1.16rem; font-weight: 700; letter-spacing: .01em; }
  [data-theme-layout="dtc-paperie"] .nav { gap: .35rem; align-items: flex-end; }
  [data-theme-layout="dtc-paperie"] .nav .search-ico, [data-theme-layout="dtc-paperie"] .nav .lang-switch { align-self: center; margin-left: .5rem; }
  /* 页签本体：上圆角、底边贴住页头规线（border-bottom:0，不留缝） */
  [data-theme-layout="dtc-paperie"] .nav > a:not(.search-ico) { padding: .5rem .95rem .58rem; border-radius: 8px 8px 0 0; border: 1px solid color-mix(in srgb, var(--ink) 22%, transparent); border-bottom: 0; background: var(--ppr-tabbg, var(--line-soft)); color: var(--ppr-tabink, var(--ink-soft)); font-size: .84rem; font-weight: 650; line-height: 1.2; }
  [data-theme-layout="dtc-paperie"] .nav > a:not(.search-ico):nth-child(4n+1) { --ppr-tabbg: var(--ppr-tab1); --ppr-tabink: var(--ppr-tab1-ink); }
  [data-theme-layout="dtc-paperie"] .nav > a:not(.search-ico):nth-child(4n+2) { --ppr-tabbg: var(--ppr-tab2); --ppr-tabink: var(--ppr-tab2-ink); }
  [data-theme-layout="dtc-paperie"] .nav > a:not(.search-ico):nth-child(4n+3) { --ppr-tabbg: var(--ppr-tab3); --ppr-tabink: var(--ppr-tab3-ink); }
  [data-theme-layout="dtc-paperie"] .nav > a:not(.search-ico):nth-child(4n+4) { --ppr-tabbg: var(--ppr-tab4); --ppr-tabink: var(--ppr-tab4-ink); }
  /* 悬停/当前态：色不变只加线/加高（绝不悬停降对比） */
  [data-theme-layout="dtc-paperie"] .nav > a:not(.search-ico):hover { color: var(--ppr-tabink, var(--ink-soft)); text-decoration: underline; text-underline-offset: 3px; }
  [data-theme-layout="dtc-paperie"] .nav > a:not(.search-ico)[aria-current="page"] { padding-top: .82rem; font-weight: 800; color: var(--ppr-tabink, var(--ink-soft)); }
  [data-theme-layout="dtc-paperie"] .nav a[aria-current="page"]::after { display: none; }
}

/* ---- 网格纸背景 + 白纸容器（1px 细框 + 内衬 18px 印刷框） ---- */
[data-theme-layout="dtc-paperie"] body { background: var(--bg); background-image: linear-gradient(var(--ppr-grid) 1px, transparent 1px), linear-gradient(90deg, var(--ppr-grid) 1px, transparent 1px); background-size: 22px 22px; }
[data-theme-layout="dtc-paperie"] .ppr-wrap { position: relative; width: min(100% - 48px, var(--w-wide) - 48px); margin: 0 auto; padding: clamp(2.2rem, 4vw, 2.8rem) clamp(2.2rem, 4vw, 3rem) 2.4rem; background: var(--surface); border: 1px solid var(--line); border-radius: 0 0 var(--radius) var(--radius); box-shadow: var(--shadow); }
[data-theme-layout="dtc-paperie"] .ppr-wrap::before { content: ""; position: absolute; inset: 18px; border: 1px solid color-mix(in srgb, var(--line) 72%, transparent); border-radius: 2px; pointer-events: none; }

/* ---- hero 扉页：行距宽的题词页 ---- */
[data-theme-layout="dtc-paperie"] .ppr-hero { position: relative; overflow: hidden; border-radius: 4px; }
[data-theme-layout="dtc-paperie"] .ppr-hero-inner { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(260px, .95fr); align-items: center; gap: clamp(1.2rem, 3vw, 2.4rem); padding: clamp(1.2rem, 3vw, 2.2rem) 0; }
[data-theme-layout="dtc-paperie"] .ppr-eyebrow { display: inline-block; max-width: 100%; overflow: hidden; margin: 0 0 1rem; padding: .32rem .8rem; background: var(--ppr-tab1); color: var(--ppr-tab1-ink); border-radius: 3px; transform: rotate(-1.2deg); font-size: .74rem; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; white-space: nowrap; text-overflow: ellipsis; }
[data-theme-layout="dtc-paperie"] .ppr-h1 { margin: 0; max-width: 16em; font-family: var(--dt-display, var(--serif)); font-size: clamp(2rem, 4.2vw, 3.1rem); font-weight: 650; line-height: 1.32; letter-spacing: .01em; }
[data-theme-layout="dtc-paperie"] .ppr-lede { max-width: 54ch; margin: 1.1rem 0 0; color: var(--muted); font-size: 1rem; line-height: 2.05; }
[data-theme-layout="dtc-paperie"] .ppr-cta { display: flex; flex-wrap: wrap; gap: .7rem; margin-top: 1.7rem; }
[data-theme-layout="dtc-paperie"] .ppr-hero-side { min-width: 0; }
/* hero image 态：全幅底图 + scrim 压字（同 flagship 规约，白字压得住任意用户图） */
[data-theme-layout="dtc-paperie"] .ppr-hero-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-paperie"] .ppr-hero.has-img { min-height: min(58vh, 480px); display: flex; align-items: flex-end; }
[data-theme-layout="dtc-paperie"] .ppr-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(102deg, rgba(10,10,12,.64) 0%, rgba(10,10,12,.38) 46%, rgba(10,10,12,.05) 74%), linear-gradient(200deg, rgba(10,10,12,0) 42%, rgba(10,10,12,.5) 96%); }
[data-theme-layout="dtc-paperie"] .ppr-hero.has-img .ppr-hero-inner { position: relative; z-index: 1; grid-template-columns: minmax(0, 1fr); padding: clamp(1.6rem, 4vw, 2.6rem) clamp(1.2rem, 3vw, 2rem); }
[data-theme-layout="dtc-paperie"] .ppr-hero.has-img .ppr-h1 { color: #fff; } /* 全局 h1 色规则会盖过容器继承，压图必须显式白字 */
[data-theme-layout="dtc-paperie"] .ppr-hero.has-img .ppr-lede { color: rgba(255,255,255,.88); }
[data-theme-layout="dtc-paperie"] .ppr-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.64); color: #fff; }
[data-theme-layout="dtc-paperie"] .ppr-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-paperie"] .ppr-hero.has-img .btn-primary { background: #fff; border-color: #fff; color: #2a271f; }

/* ---- 分类＝索引贴纸行（坐在规线上，和页头页签同语言） ---- */
[data-theme-layout="dtc-paperie"] .ppr-cats { display: flex; flex-wrap: wrap; gap: .4rem; align-items: flex-end; margin-top: 1.9rem; border-bottom: 1px solid var(--line); }
[data-theme-layout="dtc-paperie"] .ppr-cats a { display: inline-flex; align-items: baseline; gap: .35rem; margin-bottom: -1px; padding: .4rem .85rem .5rem; border: 1px solid color-mix(in srgb, var(--ink) 22%, transparent); border-bottom: 0; border-radius: 8px 8px 0 0; background: var(--ppr-tabbg, var(--line-soft)); color: var(--ppr-tabink, var(--ink-soft)); font-size: .82rem; font-weight: 650; }
[data-theme-layout="dtc-paperie"] .ppr-cats a:nth-child(4n+1) { --ppr-tabbg: var(--ppr-tab1); --ppr-tabink: var(--ppr-tab1-ink); }
[data-theme-layout="dtc-paperie"] .ppr-cats a:nth-child(4n+2) { --ppr-tabbg: var(--ppr-tab2); --ppr-tabink: var(--ppr-tab2-ink); }
[data-theme-layout="dtc-paperie"] .ppr-cats a:nth-child(4n+3) { --ppr-tabbg: var(--ppr-tab3); --ppr-tabink: var(--ppr-tab3-ink); }
[data-theme-layout="dtc-paperie"] .ppr-cats a:nth-child(4n+4) { --ppr-tabbg: var(--ppr-tab4); --ppr-tabink: var(--ppr-tab4-ink); }
