/* ---- 商品＝胶带贴角卡（卡顶半透明和纸胶带 rotate(-2deg)；胶带只装饰不承字） ---- */
[data-theme-layout="dtc-paperie"] .ppr-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(220px, 100%), 1fr)); gap: 2rem 1.3rem; padding-top: 14px; }
[data-theme-layout="dtc-paperie"] .ppr-card { position: relative; display: flex; flex-direction: column; min-width: 0; padding: .75rem .75rem .95rem; background: var(--surface); border: 1px solid var(--line); border-radius: 6px; color: var(--ink); transition: transform var(--speed), box-shadow var(--speed); }
[data-theme-layout="dtc-paperie"] .ppr-card::before { content: ""; position: absolute; top: -11px; left: 50%; width: 96px; max-width: 70%; height: 24px; transform: translateX(-50%) rotate(-2deg); background: color-mix(in srgb, var(--ppr-tape, var(--ppr-tab1)) 56%, transparent); border-left: 1px dashed rgba(255,255,255,.5); border-right: 1px dashed rgba(255,255,255,.5); pointer-events: none; }
[data-theme-layout="dtc-paperie"] .ppr-card:nth-child(4n+2) { --ppr-tape: var(--ppr-tab2); }
[data-theme-layout="dtc-paperie"] .ppr-card:nth-child(4n+3) { --ppr-tape: var(--ppr-tab3); }
[data-theme-layout="dtc-paperie"] .ppr-card:nth-child(4n+4) { --ppr-tape: var(--ppr-tab4); }
[data-theme-layout="dtc-paperie"] .ppr-card:hover { transform: translateY(-3px); box-shadow: var(--shadow); color: var(--ink); }
[data-theme-layout="dtc-paperie"] .ppr-card-media { display: grid; place-items: center; aspect-ratio: 1 / 1; border-radius: 4px; background: var(--line-soft); overflow: hidden; }
[data-theme-layout="dtc-paperie"] .ppr-card-media img { width: 100%; height: 100%; object-fit: cover; }
[data-theme-layout="dtc-paperie"] .ppr-card-title { margin-top: .7rem; font-family: var(--dt-display, var(--serif)); font-size: .98rem; font-weight: 650; line-height: 1.5; }
[data-theme-layout="dtc-paperie"] .ppr-card:hover .ppr-card-title { color: var(--accent); }
[data-theme-layout="dtc-paperie"] .ppr-card .f-chips { margin-top: .5rem; }

/* ---- 数字便签 / 相册 / 评价 / FAQ / CTA：手账语言 ---- */
[data-theme-layout="dtc-paperie"] .ppr-facts .dt-stat { border-style: dashed; border-radius: 6px; text-align: left; }
[data-theme-layout="dtc-paperie"] .ppr-facts .dt-stat:nth-child(odd) { transform: rotate(-.5deg); }
[data-theme-layout="dtc-paperie"] .ppr-facts .dt-stat:nth-child(even) { transform: rotate(.4deg); }
[data-theme-layout="dtc-paperie"] .f-gallery-item { padding: 8px 8px 24px; background: var(--surface); border: 1px solid var(--line); border-radius: 2px; }
[data-theme-layout="dtc-paperie"] .dt-testi { position: relative; border-style: dashed; border-radius: 6px; }
[data-theme-layout="dtc-paperie"] .dt-testi::before { content: ""; position: absolute; top: -10px; left: 50%; width: 78px; height: 20px; transform: translateX(-50%) rotate(-2deg); background: color-mix(in srgb, var(--ppr-tape, var(--ppr-tab2)) 52%, transparent); pointer-events: none; }
[data-theme-layout="dtc-paperie"] .dt-testis { padding-top: 12px; }
[data-theme-layout="dtc-paperie"] .dt-testi:nth-child(3n+2) { --ppr-tape: var(--ppr-tab3); }
[data-theme-layout="dtc-paperie"] .dt-testi:nth-child(3n) { --ppr-tape: var(--ppr-tab4); }
[data-theme-layout="dtc-paperie"] .f-faq { border-top-style: dashed; }
[data-theme-layout="dtc-paperie"] .f-faq-item { border-bottom-style: dashed; }
[data-theme-layout="dtc-paperie"] .dt-cta { margin-top: 3rem; }
[data-theme-layout="dtc-paperie"] .dt-cta-inner { position: relative; border: 1px solid var(--line); border-radius: var(--radius); }
[data-theme-layout="dtc-paperie"] .dt-cta-inner::before { content: ""; position: absolute; top: -11px; left: 50%; width: 110px; height: 24px; transform: translateX(-50%) rotate(-2deg); background: color-mix(in srgb, var(--ppr-tab1) 56%, transparent); pointer-events: none; }

/* ---- 内页 · 商品列表（generic_list）：贴纸墙——纸容器 + 索引页签分类 + 胶带卡 ---- */
[data-theme-layout="dtc-paperie"] main > .wrap { background: var(--surface); border: 1px solid var(--line); border-radius: 6px; padding: clamp(1.3rem, 3vw, 2.2rem) clamp(1.3rem, 3vw, 2.4rem) 2.2rem; margin-bottom: 2.6rem; box-shadow: var(--shadow); }
