[data-theme-layout="dtc-paperie"] .cat-nav a { margin-bottom: -1px; padding: .4rem .85rem .5rem; border: 1px solid color-mix(in srgb, var(--ink) 22%, transparent); border-bottom: 0; border-radius: 8px 8px 0 0; background: var(--ppr-tabbg, var(--line-soft)); color: var(--ppr-tabink, var(--ink-soft)); font-size: .84rem; font-weight: 650; }
[data-theme-layout="dtc-paperie"] .cat-nav a:nth-child(4n+1) { --ppr-tabbg: var(--ppr-tab1); --ppr-tabink: var(--ppr-tab1-ink); }
[data-theme-layout="dtc-paperie"] .cat-nav a:nth-child(4n+2) { --ppr-tabbg: var(--ppr-tab2); --ppr-tabink: var(--ppr-tab2-ink); }
[data-theme-layout="dtc-paperie"] .cat-nav a:nth-child(4n+3) { --ppr-tabbg: var(--ppr-tab3); --ppr-tabink: var(--ppr-tab3-ink); }
[data-theme-layout="dtc-paperie"] .cat-nav a:nth-child(4n+4) { --ppr-tabbg: var(--ppr-tab4); --ppr-tabink: var(--ppr-tab4-ink); }
[data-theme-layout="dtc-paperie"] .cat-nav a:hover { border-color: color-mix(in srgb, var(--ink) 22%, transparent); color: var(--ppr-tabink, var(--ink-soft)); text-decoration: underline; text-underline-offset: 3px; }
