[data-theme-layout="dtc-paperie"] .link-grid { grid-template-columns: repeat(auto-fill, minmax(min(220px, 100%), 1fr)); gap: 2rem 1.3rem; padding-top: 14px; }
[data-theme-layout="dtc-paperie"] .link-card { position: relative; overflow: visible; padding: .75rem; border-radius: 6px; }
[data-theme-layout="dtc-paperie"] .link-card::before { content: ""; position: absolute; top: -11px; left: 50%; width: 96px; max-width: 70%; height: 24px; transform: translateX(-50%) rotate(-2deg); background: color-mix(in srgb, var(--ppr-tape, var(--ppr-tab1)) 56%, transparent); border-left: 1px dashed rgba(255,255,255,.5); border-right: 1px dashed rgba(255,255,255,.5); pointer-events: none; z-index: 1; }
[data-theme-layout="dtc-paperie"] .link-card:nth-child(4n+2) { --ppr-tape: var(--ppr-tab2); }
[data-theme-layout="dtc-paperie"] .link-card:nth-child(4n+3) { --ppr-tape: var(--ppr-tab3); }
[data-theme-layout="dtc-paperie"] .link-card:nth-child(4n+4) { --ppr-tape: var(--ppr-tab4); }
[data-theme-layout="dtc-paperie"] .link-card:hover { border-color: var(--line); box-shadow: var(--shadow); }
[data-theme-layout="dtc-paperie"] .lc-cover { aspect-ratio: 1 / 1; border-radius: 4px; }
[data-theme-layout="dtc-paperie"] .lc-body { padding: .75rem .15rem 0; }
