/* ---- 内页 · 商品详情（product_detail）：贴角照片 + 用纸规格表 + 搭配示范区 ---- */
[data-theme-layout="dtc-paperie"] .pd-main { background: var(--surface); border: 1px solid var(--line); border-radius: 6px; padding: clamp(1.3rem, 3vw, 2.4rem) clamp(1.3rem, 3vw, 2.6rem) 2.6rem; margin-top: 1.6rem; margin-bottom: 2.6rem; box-shadow: var(--shadow); }
