[data-theme-layout="dtc-paperie"] .pd-gallery::after { content: ""; position: absolute; top: -7px; right: 8%; width: 72px; height: 20px; transform: rotate(2.5deg); background: color-mix(in srgb, var(--ppr-tab2) 52%, transparent); z-index: 2; pointer-events: none; }
[data-theme-layout="dtc-paperie"] .pd-media { border-radius: 4px; background: var(--line-soft); }
