[data-theme-layout="dtc-lightbox"] .lbx-hero.has-img::after { content: ""; position: absolute; inset: 0; background: linear-gradient(102deg, rgba(8,10,14,.68) 0%, rgba(8,10,14,.42) 46%, rgba(8,10,14,.06) 74%), linear-gradient(200deg, rgba(8,10,14,0) 42%, rgba(8,10,14,.52) 96%); }
[data-theme-layout="dtc-lightbox"] .lbx-hero.has-img .lbx-hero-inner { position: relative; z-index: 1; grid-template-columns: minmax(0, 1fr); }
[data-theme-layout="dtc-lightbox"] .lbx-hero.has-img .lbx-eyebrow { color: #7ad7ff; text-shadow: 0 0 14px rgba(122,215,255,.4); }
[data-theme-layout="dtc-lightbox"] .lbx-hero.has-img .lbx-h1 { color: #fff; text-shadow: 0 0 24px rgba(122,215,255,.45); }
[data-theme-layout="dtc-lightbox"] .lbx-hero.has-img .lbx-lede { color: rgba(255,255,255,.86); }
[data-theme-layout="dtc-lightbox"] .lbx-hero.has-img .dt-btn-ghost { border-color: rgba(255,255,255,.62); color: #fff; }
[data-theme-layout="dtc-lightbox"] .lbx-hero.has-img .dt-btn-ghost:hover { border-color: #fff; color: #fff; }
[data-theme-layout="dtc-lightbox"] .lbx-hero.has-img .btn-primary, [data-theme-layout="dtc-lightbox"] .lbx-hero.has-img .btn-primary:hover { background: #fff; border-color: #fff; color: #14151a; }

/* ---- 分类光带（.Categories）：霓虹胶囊，同导航语汇 ---- */
[data-theme-layout="dtc-lightbox"] .lbx-cats { display: flex; flex-wrap: wrap; gap: .55rem; margin-top: 1.9rem; }
[data-theme-layout="dtc-lightbox"] .lbx-cats a { display: inline-flex; align-items: center; gap: .4rem; padding: .38rem 1rem; border: 1px solid color-mix(in srgb, var(--accent) 40%, transparent); border-radius: 999px; color: var(--accent); font-size: .82rem; font-weight: 600; box-shadow: 0 0 12px color-mix(in srgb, var(--lbx-glow, var(--accent)) 12%, transparent); }
[data-theme-layout="dtc-lightbox"] .lbx-cats a:hover { color: var(--accent-soft); border-color: color-mix(in srgb, var(--accent) 72%, transparent); box-shadow: 0 0 18px color-mix(in srgb, var(--lbx-glow, var(--accent)) 24%, transparent); }
[data-theme-layout="dtc-lightbox"] .lbx-cats a small { font-size: .74rem; font-weight: 750; color: var(--accent-soft); }

/* ---- 区块头：发光圆点 + 白标题 ---- */
[data-theme-layout="dtc-lightbox"] .lbx-section { padding-top: clamp(2.8rem, 6vw, 4.2rem); }
[data-theme-layout="dtc-lightbox"] .lbx-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; margin-bottom: 1.3rem; }
[data-theme-layout="dtc-lightbox"] .lbx-head h2 { margin: 0; display: flex; align-items: center; gap: .6rem; font-family: var(--dt-display, var(--sans)); font-size: clamp(1.3rem, 2.4vw, 1.7rem); font-weight: 700; letter-spacing: .01em; }
[data-theme-layout="dtc-lightbox"] .lbx-head h2::before { content: ""; flex: none; width: .5em; height: .5em; border-radius: 50%; background: var(--accent); box-shadow: 0 0 12px color-mix(in srgb, var(--lbx-glow, var(--accent)) 55%, transparent); }
[data-theme-layout="dtc-lightbox"] .lbx-head > a { flex: none; color: var(--ink-soft); font-size: .86rem; }
[data-theme-layout="dtc-lightbox"] .lbx-head > a:hover { color: var(--accent); }

/* ---- 商品灯箱格三列：深卡灰框圆角 8 + 图区发光内芯（hover 只加光，无位移） ---- */
[data-theme-layout="dtc-lightbox"] .lbx-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.1rem; }
[data-theme-layout="dtc-lightbox"] .lbx-card { display: flex; flex-direction: column; min-width: 0; border: 1px solid var(--lbx-frame, var(--line)); border-radius: 8px; background: var(--lbx-card, var(--surface)); color: var(--ink); overflow: hidden; transition: border-color var(--speed), box-shadow var(--speed); }
[data-theme-layout="dtc-lightbox"] .lbx-card:hover { color: var(--ink); border-color: color-mix(in srgb, var(--accent) 60%, var(--lbx-frame, var(--line))); box-shadow: 0 0 22px color-mix(in srgb, var(--lbx-glow, var(--accent)) 16%, transparent); }
[data-theme-layout="dtc-lightbox"] .lbx-card-media { display: grid; place-items: center; aspect-ratio: 4 / 3; margin: 10px 10px 0; border: 1px solid color-mix(in srgb, var(--accent) 38%, transparent); border-radius: 6px; background: radial-gradient(72% 64% at 50% 42%, color-mix(in srgb, var(--lbx-glow, var(--accent)) 22%, var(--lbx-card, var(--surface))), var(--lbx-card, var(--surface)) 84%); box-shadow: inset 0 0 26px color-mix(in srgb, var(--lbx-glow, var(--accent)) 14%, transparent); overflow: hidden; }
[data-theme-layout="dtc-lightbox"] .lbx-card-media img { width: 100%; height: 100%; object-fit: cover; }
