[data-theme-layout="dtc-lightbox"] .lbx-card-body { display: flex; flex-direction: column; gap: .5rem; padding: .8rem .95rem 1rem; }
[data-theme-layout="dtc-lightbox"] .lbx-card-title { display: -webkit-box; overflow: hidden; font-size: .98rem; font-weight: 650; line-height: 1.45; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="dtc-lightbox"] .lbx-card .f-chips { margin-top: 0; }
/* 青字规格签（全站）：透明底 + 青描边（b=K 走 accent-soft，hover 无——纯静态签） */
[data-theme-layout="dtc-lightbox"] .f-chip { border-color: color-mix(in srgb, var(--accent) 40%, transparent); background: transparent; color: var(--accent); }
[data-theme-layout="dtc-lightbox"] .f-chip b { color: var(--accent-soft); }

/* ---- 数字带 / 评价卡 / 图集 / CTA：灯箱化（卡面走 --lbx-card，白皮借道避 4.38 坑） ---- */
[data-theme-layout="dtc-lightbox"] .dt-stat { border-color: var(--lbx-frame, var(--line)); border-radius: 8px; background: var(--lbx-card, var(--surface)); }
[data-theme-layout="dtc-lightbox"] .dt-stat dt { color: var(--accent); text-shadow: 0 0 18px color-mix(in srgb, var(--lbx-glow, var(--accent)) 35%, transparent); }
[data-theme-layout="dtc-lightbox"] .dt-testi { border-color: var(--lbx-frame, var(--line)); border-radius: 8px; background: var(--lbx-card, var(--surface)); }
[data-theme-layout="dtc-lightbox"] .f-gallery-item { border: 1px solid var(--lbx-frame, var(--line)); border-radius: 8px; }
[data-theme-layout="dtc-lightbox"] .dt-cta-inner { border: 1px solid color-mix(in srgb, var(--accent) 40%, transparent); border-radius: 12px; box-shadow: 0 0 30px color-mix(in srgb, var(--lbx-glow, var(--accent)) 12%, transparent), inset 0 0 34px color-mix(in srgb, var(--lbx-glow, var(--accent)) 6%, transparent); }
[data-theme-layout="dtc-lightbox"] .dt-cta h2 { text-shadow: 0 0 20px color-mix(in srgb, var(--lbx-glow, var(--accent)) 30%, transparent); }

/* ---- 内页·商品列表（generic_list DOM）：灯箱墙 ---- */
[data-theme-layout="dtc-lightbox"] .breadcrumb { font-size: .8rem; letter-spacing: .04em; }
[data-theme-layout="dtc-lightbox"] .breadcrumb a:hover { color: var(--accent); }
[data-theme-layout="dtc-lightbox"] .page-head { padding: 2.8rem 0 1.9rem; border-bottom: 1px solid var(--line); }
[data-theme-layout="dtc-lightbox"] .page-head .hero-sub { max-width: 60ch; }
[data-theme-layout="dtc-lightbox"] .page-head .eyebrow { letter-spacing: .32em; text-shadow: 0 0 14px color-mix(in srgb, var(--lbx-glow, var(--accent)) 30%, transparent); }
[data-theme-layout="dtc-lightbox"] .page-head h1 { font-family: var(--dt-display, var(--sans)); font-weight: 700; text-shadow: 0 0 24px color-mix(in srgb, var(--lbx-glow, var(--accent)) 34%, transparent); }
[data-theme-layout="dtc-lightbox"] .cat-nav { gap: .55rem; }
[data-theme-layout="dtc-lightbox"] .cat-nav a { border-color: color-mix(in srgb, var(--accent) 40%, transparent); color: var(--accent); font-size: .84rem; font-weight: 600; box-shadow: 0 0 12px color-mix(in srgb, var(--lbx-glow, var(--accent)) 12%, transparent); }
[data-theme-layout="dtc-lightbox"] .cat-nav a:hover { color: var(--accent-soft); border-color: color-mix(in srgb, var(--accent) 72%, transparent); box-shadow: 0 0 18px color-mix(in srgb, var(--lbx-glow, var(--accent)) 24%, transparent); }
[data-theme-layout="dtc-lightbox"] .cat-nav a.active { background: var(--ink); border-color: var(--ink); color: var(--bg); box-shadow: 0 0 16px color-mix(in srgb, var(--lbx-glow, var(--accent)) 20%, transparent); }
[data-theme-layout="dtc-lightbox"] .link-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.1rem; margin: 2rem 0 2.6rem; }
[data-theme-layout="dtc-lightbox"] .link-card { border-color: var(--lbx-frame, var(--line)); border-radius: 8px; background: var(--lbx-card, var(--surface)); }
/* hover 只加光不位移；标题保持白字（ink→accent 是降对比，只在卡框上做反馈） */
[data-theme-layout="dtc-lightbox"] .link-card:hover { transform: none; border-color: color-mix(in srgb, var(--accent) 60%, var(--lbx-frame, var(--line))); box-shadow: 0 0 22px color-mix(in srgb, var(--lbx-glow, var(--accent)) 16%, transparent); }
[data-theme-layout="dtc-lightbox"] .lc-cover { aspect-ratio: 4 / 3; margin: 10px 10px 0; border: 1px solid color-mix(in srgb, var(--accent) 38%, transparent); border-radius: 6px; background: radial-gradient(72% 64% at 50% 42%, color-mix(in srgb, var(--lbx-glow, var(--accent)) 22%, var(--lbx-card, var(--surface))), var(--lbx-card, var(--surface)) 84%); box-shadow: inset 0 0 26px color-mix(in srgb, var(--lbx-glow, var(--accent)) 14%, transparent); }
[data-theme-layout="dtc-lightbox"] .lc-mono { background: transparent; color: var(--accent); font-family: var(--dt-display, var(--sans)); text-shadow: 0 0 16px color-mix(in srgb, var(--lbx-glow, var(--accent)) 45%, transparent); }
[data-theme-layout="dtc-lightbox"] .lc-body { padding: .85rem 1rem 1.05rem; }
[data-theme-layout="dtc-lightbox"] .lc-title { font-size: 1rem; }
[data-theme-layout="dtc-lightbox"] .lc-arrow { color: var(--accent); }
[data-theme-layout="dtc-lightbox"] .lc-intro { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
[data-theme-layout="dtc-lightbox"] .lc-foot .tag { padding: .22rem .7rem; border: 1px solid color-mix(in srgb, var(--accent) 40%, transparent); border-radius: 999px; background: transparent; color: var(--accent); font-size: .74rem; font-weight: 600; }
[data-theme-layout="dtc-lightbox"] .link-grid > .muted { grid-column: 1 / -1; margin: 0; padding: 1.6rem; border: 1px dashed var(--lbx-frame, var(--line)); border-radius: 8px; text-align: center; }
[data-theme-layout="dtc-lightbox"] .pagination a, [data-theme-layout="dtc-lightbox"] .pagination span { border-radius: 999px; }
/* 基础 .cur=accent 底白字（青底白字对比不够）→ 反转为 ink 底 bg 字 */
[data-theme-layout="dtc-lightbox"] .pagination .cur { background: var(--ink); border-color: var(--ink); color: var(--bg); }

/* ---- 内页·商品详情（product_detail DOM）：大灯箱图 + 光晕参数卡 ---- */
[data-theme-layout="dtc-lightbox"] .pd-bc { font-size: .8rem; letter-spacing: .04em; }
[data-theme-layout="dtc-lightbox"] .pd-top { grid-template-columns: minmax(0, 1.06fr) minmax(300px, .94fr); }
[data-theme-layout="dtc-lightbox"] .pd-media { border: 1px solid color-mix(in srgb, var(--accent) 38%, transparent); border-radius: 10px; background: radial-gradient(74% 64% at 50% 42%, color-mix(in srgb, var(--lbx-glow, var(--accent)) 18%, var(--lbx-card, var(--surface))), var(--lbx-card, var(--surface)) 84%); box-shadow: inset 0 0 34px color-mix(in srgb, var(--lbx-glow, var(--accent)) 14%, transparent), 0 0 26px color-mix(in srgb, var(--lbx-glow, var(--accent)) 10%, transparent); }
[data-theme-layout="dtc-lightbox"] .pd-media-gen b { color: var(--accent); text-shadow: 0 0 18px color-mix(in srgb, var(--lbx-glow, var(--accent)) 45%, transparent); }
[data-theme-layout="dtc-lightbox"] .pd-thumb { border-radius: 8px; background: var(--lbx-card, var(--surface)); }
[data-theme-layout="dtc-lightbox"] .pd-thumb.is-active { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent), 0 0 12px color-mix(in srgb, var(--lbx-glow, var(--accent)) 30%, transparent); }
/* 光晕参数卡：整卡框线 + 低透明外晕；询盘/规格都住在卡里 */
[data-theme-layout="dtc-lightbox"] .pd-info { padding: clamp(1.2rem, 2.4vw, 1.7rem); border: 1px solid var(--lbx-frame, var(--line)); border-radius: 10px; background: var(--lbx-card, var(--surface)); box-shadow: 0 0 24px color-mix(in srgb, var(--lbx-glow, var(--accent)) 8%, transparent); }
[data-theme-layout="dtc-lightbox"] .pd-kicker { letter-spacing: .2em; text-transform: uppercase; font-size: .74rem; font-weight: 700; }
[data-theme-layout="dtc-lightbox"] .pd-title { font-family: var(--dt-display, var(--sans)); font-weight: 700; text-shadow: 0 0 20px color-mix(in srgb, var(--lbx-glow, var(--accent)) 30%, transparent); }
[data-theme-layout="dtc-lightbox"] .pd-lead { color: var(--ink-soft); }
[data-theme-layout="dtc-lightbox"] .pd-meta { border-top: 1px solid color-mix(in srgb, var(--accent) 45%, transparent); }
[data-theme-layout="dtc-lightbox"] .pd-meta-row dt { font-size: .8rem; letter-spacing: .06em; text-transform: uppercase; }
[data-theme-layout="dtc-lightbox"] .pd-inquiry { border: 1px solid color-mix(in srgb, var(--accent) 40%, transparent); border-radius: 8px; background: var(--accent-wash); box-shadow: inset 0 0 20px color-mix(in srgb, var(--lbx-glow, var(--accent)) 7%, transparent); }
[data-theme-layout="dtc-lightbox"] .inquiry-title { letter-spacing: .04em; }
[data-theme-layout="dtc-lightbox"] .pd-desc .prose { max-width: 76ch; }
[data-theme-layout="dtc-lightbox"] .pd-related-head a:hover { color: var(--accent); }
[data-theme-layout="dtc-lightbox"] .pd-sec-title { display: flex; align-items: center; gap: .6rem; font-family: var(--dt-display, var(--sans)); font-weight: 700; }
[data-theme-layout="dtc-lightbox"] .pd-sec-title::before { content: ""; flex: none; width: .5em; height: .5em; border-radius: 50%; background: var(--accent); box-shadow: 0 0 12px color-mix(in srgb, var(--lbx-glow, var(--accent)) 55%, transparent); }
/* specs 卡霓虹细框 */
[data-theme-layout="dtc-lightbox"] .pd-specs-tablewrap { border-color: color-mix(in srgb, var(--accent) 45%, transparent); border-radius: 8px; background: var(--lbx-card, var(--surface)); box-shadow: 0 0 18px color-mix(in srgb, var(--lbx-glow, var(--accent)) 10%, transparent), inset 0 0 18px color-mix(in srgb, var(--lbx-glow, var(--accent)) 5%, transparent); }
[data-theme-layout="dtc-lightbox"] .pd-specs-table th { color: var(--accent); background: color-mix(in srgb, var(--accent) 8%, transparent); font-size: .84rem; letter-spacing: .04em; text-transform: uppercase; }
[data-theme-layout="dtc-lightbox"] .pd-rel-card { border-color: var(--lbx-frame, var(--line)); border-radius: 8px; background: var(--lbx-card, var(--surface)); }
[data-theme-layout="dtc-lightbox"] .pd-rel-card:hover { transform: none; border-color: color-mix(in srgb, var(--accent) 60%, var(--lbx-frame, var(--line))); box-shadow: 0 0 22px color-mix(in srgb, var(--lbx-glow, var(--accent)) 16%, transparent); }
[data-theme-layout="dtc-lightbox"] .pd-rel-media { margin: 8px 8px 0; border: 1px solid color-mix(in srgb, var(--accent) 38%, transparent); border-radius: 6px; background: radial-gradient(72% 64% at 50% 42%, color-mix(in srgb, var(--lbx-glow, var(--accent)) 22%, var(--lbx-card, var(--surface))), var(--lbx-card, var(--surface)) 84%); box-shadow: inset 0 0 20px color-mix(in srgb, var(--lbx-glow, var(--accent)) 12%, transparent); }
[data-theme-layout="dtc-lightbox"] .pd-rel-gen b { color: var(--accent); text-shadow: 0 0 14px color-mix(in srgb, var(--lbx-glow, var(--accent)) 45%, transparent); }

/* ---- 响应式：920 折两列/hero 单列、720 全部单列归位普通流，375 无横向溢出 ---- */
@media (max-width: 920px) {
  [data-theme-layout="dtc-lightbox"] .lbx-hero-inner { grid-template-columns: 1fr; padding: clamp(1.6rem, 5vw, 2.6rem); }
  [data-theme-layout="dtc-lightbox"] .lbx-hero-side { max-width: 420px; }
  [data-theme-layout="dtc-lightbox"] .lbx-grid, [data-theme-layout="dtc-lightbox"] .link-grid { grid-template-columns: 1fr 1fr; }
  [data-theme-layout="dtc-lightbox"] .pd-top { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
  [data-theme-layout="dtc-lightbox"] .lbx-grid, [data-theme-layout="dtc-lightbox"] .link-grid { grid-template-columns: 1fr; }
  [data-theme-layout="dtc-lightbox"] .lbx-head { flex-direction: column; align-items: flex-start; gap: .35rem; }
  [data-theme-layout="dtc-lightbox"] .lbx-hero.has-img { min-height: 60vh; }
}
/* 骨架自身零动画；hover 过渡在 reduced-motion 下瞬时完成 */
@media (prefers-reduced-motion: reduce) {
  [data-theme-layout="dtc-lightbox"] * { transition-duration: .01ms !important; }
}

/* ============================================================
   dtc-lightbox 皮肤 ×3：lightbox 夜黑+霓虹青 / lightbox-day 日光灯箱亮底 /
   lightbox-white 纯白（中性灰基底对齐 answer-desk-white）。
   实算 WCAG：正文 ink/bg 15.79 / 16.10 / 18.72（卡面 14.77 / 17.49 / 18.72）、
   muted/bg 7.36 / 5.53 / 4.57、accent/bg 9.79 / 5.98 / 6.16（卡面 9.16 / 6.50 /
   6.16、wash 8.30 / 5.41 / 5.45、发光内芯 5.78 / 5.16 / 4.89），
   hover accent-soft/bg 11.86 / 8.28 / 8.52 只升不降。发光=低透明 shadow，静态。
   ============================================================ */
/* ---- 灯箱 · Lightbox（原生，暗）：夜黑 #0e0f12 + 霓虹青 #3ec6ff + 灰白 #e8e9ec ---- */
:root[data-theme="lightbox"] {
  --bg: #0e0f12; --surface: #15171c; --ink: #e8e9ec; --ink-soft: #c3c7ce;
  --muted: #9aa1ac; --faint: #6e747e; --line: #262a33; --line-soft: #1a1d24;
  --accent: #3ec6ff; --accent-soft: #7ad7ff; --accent-wash: #10222f;
  --radius: 8px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(0,0,0,.45), 0 12px 30px rgba(0,0,0,.5);
  --serif: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
  --dt-display: var(--sans);
  --lbx-card: #15171c; --lbx-frame: #262a33; --lbx-glow: #3ec6ff;
}

/* ---- 灯箱 · Day（浅反差）：日光灯箱亮底 + 深字 + 青点缀（青压深到 #0a648f
   保青相：bg 5.98 / 白卡 6.50 / wash 5.41，hover #084e70 8.28 只升） ---- */
:root[data-theme="lightbox-day"] {
  --bg: #f2f6f9; --surface: #ffffff; --ink: #151a20; --ink-soft: #3e4650;
  --muted: #5b646f; --faint: #8d97a3; --line: #d9e1e9; --line-soft: #e9eef4;
  --accent: #0a648f; --accent-soft: #084e70; --accent-wash: #dcedf7;
  --radius: 8px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(21,26,32,.05), 0 10px 26px rgba(21,26,32,.08);
  --serif: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
  --dt-display: var(--sans);
  --lbx-card: #ffffff; --lbx-frame: #d9e1e9; --lbx-glow: #2a9bd6;
}

/* ---- 灯箱 · White（纯白皮）：中性灰基底 + 深压青 #0b6892（白底 6.16） ---- */
:root[data-theme="lightbox-white"] {
  --bg: #ffffff; --surface: #fafaf8; --ink: #101218; --ink-soft: #3f444d;
  --muted: #707680; --faint: #a9aeb6; --line: #d7d9dd; --line-soft: #eef0f3;
  --accent: #0b6892; --accent-soft: #085273; --accent-wash: #e6f3fb;
  --radius: 8px; --w-wide: 1200px; --shadow: 0 1px 2px rgba(16,18,24,.04), 0 10px 26px rgba(16,18,24,.06);
  --serif: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
  --dt-display: var(--sans);
  --lbx-card: #ffffff; --lbx-frame: #d7d9dd; --lbx-glow: #2a9bd6;
}
/* 纯白坑修：muted #707680 踩 #fafaf8 只有 4.38——带 muted 文字的卡面全走
   --lbx-card=#fff（4.57）；wash 上的 muted 说明文字 4.05 → 提为 ink-soft（8.66）；
   btn-primary/inquiry-wa 文字从 surface #fafaf8 收紧为 #fff。 */
:root[data-theme="lightbox-white"] .dt-cta-note { color: var(--ink-soft); }
:root[data-theme="lightbox-white"] .inquiry-note { color: var(--ink-soft); }
:root[data-theme="lightbox-white"] .btn-primary, :root[data-theme="lightbox-white"] .inquiry-btn.inquiry-wa { color: #fff; }
